


SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "public";


ALTER SCHEMA "public" OWNER TO "pg_database_owner";


COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE TYPE "public"."email_type" AS ENUM (
    'invoice',
    'statement',
    'order_confirmed',
    'delivery_completed',
    'quote',
    'ar_reminder',
    'low_stock_alert',
    'month_end_close',
    'pre_application_notice',
    'post_application_notice'
);


ALTER TYPE "public"."email_type" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_batch_apply_prepayments_impl"("p_allocations" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_alloc            jsonb;
  v_invoice_id       uuid;
  v_invoice_date     date;
  v_result_id        uuid;
  v_result_ids       uuid[] := ARRAY[]::uuid[];
  v_total_applied    bigint := 0;
  v_count            integer := 0;
  v_cached_result    jsonb;
  v_result           jsonb;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    v_cached_result := check_idempotency(p_idempotency_key, 'batch_apply_prepayments');
    IF v_cached_result IS NOT NULL THEN
      RETURN v_cached_result;
    END IF;
  END IF;

  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations)
  LOOP
    v_invoice_id := (v_alloc->>'invoice_id')::uuid;

    SELECT invoice_date INTO v_invoice_date
      FROM invoices
     WHERE id = v_invoice_id;
    IF v_invoice_date IS NULL THEN
      RAISE EXCEPTION 'Invoice not found for prepay allocation: %', v_invoice_id;
    END IF;
    PERFORM check_period_open(v_invoice_date);

    v_result_id := apply_prepay_to_invoice(
      (v_alloc->>'prepay_credit_id')::uuid,
      v_invoice_id,
      (v_alloc->>'amount_cents')::bigint
    );
    v_result_ids := array_append(v_result_ids, v_result_id);
    v_total_applied := v_total_applied + (v_alloc->>'amount_cents')::bigint;
    v_count := v_count + 1;
  END LOOP;

  v_result := jsonb_build_object(
    'success', true,
    'applied_count', v_count,
    'total_applied_cents', v_total_applied,
    'application_ids', to_jsonb(v_result_ids)
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'batch_apply_prepayments', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."_batch_apply_prepayments_impl"("p_allocations" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_batch_apply_prepayments_impl"("p_allocations" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Atomic batch application of prepay credits to invoices. Enforces check_period_open per-invoice before mutating (Wave A.4 / P3-4). Any invoice in a closed period raises and rolls back the entire batch.';



CREATE OR REPLACE FUNCTION "public"."_bind_completed_lifecycle_idempotency"("p_key" "text", "p_operation" "text", "p_contract" "text", "p_request_fingerprint" "text", "p_request" "jsonb", "p_response" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_key IS NULL THEN
    RETURN;
  END IF;
  IF p_response IS NULL OR p_response = 'null'::jsonb THEN
    RAISE EXCEPTION 'IDEMPOTENCY_RESPONSE_REQUIRED: % key %', p_operation, p_key;
  END IF;

  UPDATE public.idempotency_keys k
     SET result = jsonb_build_object(
           '_contract', p_contract,
           'request_fingerprint', p_request_fingerprint,
           'request', p_request,
           'response', p_response
         ),
         expires_at = now() + interval '24 hours'
   WHERE k.idempotency_key = p_key
     AND k.operation = p_operation
     AND k.result->>'_contract' IS NOT DISTINCT FROM p_contract
     AND k.result->>'request_fingerprint' IS NOT DISTINCT FROM p_request_fingerprint
     AND k.result->'response' = 'null'::jsonb;
  IF NOT FOUND THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_CLAIM_LOST: % key % disappeared before request binding',
      p_operation, p_key;
  END IF;
END;
$$;


ALTER FUNCTION "public"."_bind_completed_lifecycle_idempotency"("p_key" "text", "p_operation" "text", "p_contract" "text", "p_request_fingerprint" "text", "p_request" "jsonb", "p_response" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_calculate_product_pricing"("p_mode" "text", "p_current_cost" numeric, "p_tier1_margin" numeric, "p_tier2_margin" numeric, "p_tier3_margin" numeric, "p_tier1_price" numeric, "p_tier2_price" numeric, "p_tier3_price" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t1_margin numeric := p_tier1_margin;
  v_t2_margin numeric := p_tier2_margin;
  v_t3_margin numeric := p_tier3_margin;
  v_t1_price numeric := p_tier1_price;
  v_t2_price numeric := p_tier2_price;
  v_t3_price numeric := p_tier3_price;
  v_t1_gross numeric;
  v_t2_gross numeric;
  v_t3_gross numeric;
BEGIN
  IF p_mode NOT IN ('legacy_margin', 'margin_driven', 'price_driven') THEN
    RAISE EXCEPTION 'PRICING_MODE_INVALID';
  END IF;
  IF (p_mode <> 'legacy_margin' AND p_current_cost IS NULL)
     OR p_current_cost::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_current_cost < 0
     OR round(p_current_cost, 2) IS DISTINCT FROM p_current_cost
     OR (p_mode = 'margin_driven' AND p_current_cost = 0) THEN
    RAISE EXCEPTION 'PRICING_COST_INVALID';
  END IF;

  IF p_mode IN ('legacy_margin', 'margin_driven') THEN
    IF p_mode = 'margin_driven' AND (
      v_t1_margin IS NULL OR v_t2_margin IS NULL OR v_t3_margin IS NULL
      OR v_t1_margin::text IN ('NaN', 'Infinity', '-Infinity')
      OR v_t2_margin::text IN ('NaN', 'Infinity', '-Infinity')
      OR v_t3_margin::text IN ('NaN', 'Infinity', '-Infinity')
      OR v_t1_margin < 0 OR v_t1_margin >= 1
      OR v_t2_margin < 0 OR v_t2_margin >= 1
      OR v_t3_margin < 0 OR v_t3_margin >= 1
    ) THEN
      RAISE EXCEPTION 'PRICING_MARGIN_INVALID';
    END IF;

    IF (p_mode = 'margin_driven' OR p_current_cost > 0)
       AND v_t1_margin IS NOT NULL AND v_t1_margin >= 0 AND v_t1_margin < 1
       AND (p_mode = 'margin_driven' OR v_t1_margin > 0) THEN
      v_t1_price := round(p_current_cost / (1 - v_t1_margin), 2);
      v_t1_gross := CASE WHEN v_t1_margin = 1 THEN NULL
                         ELSE round(v_t1_margin / (1 - v_t1_margin), 4) END;
    ELSE
      v_t1_gross := NULL;
    END IF;
    IF (p_mode = 'margin_driven' OR p_current_cost > 0)
       AND v_t2_margin IS NOT NULL AND v_t2_margin >= 0 AND v_t2_margin < 1
       AND (p_mode = 'margin_driven' OR v_t2_margin > 0) THEN
      v_t2_price := round(p_current_cost / (1 - v_t2_margin), 2);
      v_t2_gross := CASE WHEN v_t2_margin = 1 THEN NULL
                         ELSE round(v_t2_margin / (1 - v_t2_margin), 4) END;
    ELSE
      v_t2_gross := NULL;
    END IF;
    IF (p_mode = 'margin_driven' OR p_current_cost > 0)
       AND v_t3_margin IS NOT NULL AND v_t3_margin >= 0 AND v_t3_margin < 1
       AND (p_mode = 'margin_driven' OR v_t3_margin > 0) THEN
      v_t3_price := round(p_current_cost / (1 - v_t3_margin), 2);
      v_t3_gross := CASE WHEN v_t3_margin = 1 THEN NULL
                         ELSE round(v_t3_margin / (1 - v_t3_margin), 4) END;
    ELSE
      v_t3_gross := NULL;
    END IF;
  ELSE
    IF v_t1_price IS NULL OR v_t2_price IS NULL OR v_t3_price IS NULL
       OR v_t1_price::text IN ('NaN', 'Infinity', '-Infinity')
       OR v_t2_price::text IN ('NaN', 'Infinity', '-Infinity')
       OR v_t3_price::text IN ('NaN', 'Infinity', '-Infinity')
       OR v_t1_price < 0 OR v_t2_price < 0 OR v_t3_price < 0
       OR round(v_t1_price, 2) IS DISTINCT FROM v_t1_price
       OR round(v_t2_price, 2) IS DISTINCT FROM v_t2_price
       OR round(v_t3_price, 2) IS DISTINCT FROM v_t3_price THEN
      RAISE EXCEPTION 'PRICING_PRICE_INVALID';
    END IF;
    IF (v_t1_price = 0 AND p_current_cost > 0)
       OR (v_t2_price = 0 AND p_current_cost > 0)
       OR (v_t3_price = 0 AND p_current_cost > 0) THEN
      RAISE EXCEPTION 'PRICING_ZERO_PRICE_BELOW_COST';
    END IF;

    v_t1_margin := CASE WHEN v_t1_price = 0 THEN 0
                        ELSE round((v_t1_price - p_current_cost) / v_t1_price, 8) END;
    v_t2_margin := CASE WHEN v_t2_price = 0 THEN 0
                        ELSE round((v_t2_price - p_current_cost) / v_t2_price, 8) END;
    v_t3_margin := CASE WHEN v_t3_price = 0 THEN 0
                        ELSE round((v_t3_price - p_current_cost) / v_t3_price, 8) END;
    v_t1_gross := CASE WHEN p_current_cost = 0 THEN NULL
                       ELSE round((v_t1_price - p_current_cost) / p_current_cost, 4) END;
    v_t2_gross := CASE WHEN p_current_cost = 0 THEN NULL
                       ELSE round((v_t2_price - p_current_cost) / p_current_cost, 4) END;
    v_t3_gross := CASE WHEN p_current_cost = 0 THEN NULL
                       ELSE round((v_t3_price - p_current_cost) / p_current_cost, 4) END;
  END IF;

  RETURN jsonb_build_object(
    'current_cost', p_current_cost,
    'tier1_margin', v_t1_margin,
    'tier2_margin', v_t2_margin,
    'tier3_margin', v_t3_margin,
    'tier1_price', v_t1_price,
    'tier2_price', v_t2_price,
    'tier3_price', v_t3_price,
    'tier1_gross_margin', v_t1_gross,
    'tier2_gross_margin', v_t2_gross,
    'tier3_gross_margin', v_t3_gross
  );
END;
$$;


ALTER FUNCTION "public"."_calculate_product_pricing"("p_mode" "text", "p_current_cost" numeric, "p_tier1_margin" numeric, "p_tier2_margin" numeric, "p_tier3_margin" numeric, "p_tier1_price" numeric, "p_tier2_price" numeric, "p_tier3_price" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_cancel_order_impl_20260714"("p_order_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_cached_result jsonb;
  v_order record;
  v_item record;
  v_undelivered numeric;
  v_holds_released integer := 0;
  v_commissions_cancelled integer := 0;
  v_paid_commissions integer := 0;
  v_draft_cancelled integer := 0;
  v_posted_notified integer := 0;
  v_deliveries_cancelled integer := 0;
  v_invoice record;
  v_admin record;
  v_result jsonb;
  -- A3<<<
  v_draw_item record;
  v_draw_quote record;
  v_draw_fully_drawn boolean;
  -- >>>A3
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  IF p_performed_by IS NOT NULL AND v_actor IS DISTINCT FROM p_performed_by THEN
    RAISE EXCEPTION 'actor mismatch';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached_result := check_idempotency(p_idempotency_key, 'cancel_order');
    IF v_cached_result IS NOT NULL THEN
      RETURN v_cached_result;
    END IF;
  END IF;

  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;
  IF v_order.status = 'cancelled' THEN
    RETURN jsonb_build_object('status', 'already_cancelled');
  END IF;
  IF v_order.status = 'fulfilled' THEN
    RAISE EXCEPTION 'Cannot cancel a fulfilled order';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_actor AND role = 'admin' AND is_active = true
  ) THEN
    RAISE EXCEPTION 'Only admins can cancel orders';
  END IF;

  -- Commission batch-freeze guard (overnight bug-hunt HIGH, 20260620): a pending
  -- commission already committed to a non-voided commission_payments batch must not
  -- be silently cancelled here — post_commission_payment would later resurrect it to
  -- 'paid' and pay the retained snapshot. Force the admin to void the payout first.
  IF EXISTS (
    SELECT 1
    FROM commissions cm
    JOIN commission_payment_items cpi ON cpi.commission_id = cm.id
    JOIN commission_payments cp ON cp.id = cpi.commission_payment_id
    WHERE cm.order_id = p_order_id
      AND cm.status = 'pending'
      AND cp.status <> 'voided'
  ) THEN
    RAISE EXCEPTION 'ORDER_HAS_BATCHED_COMMISSIONS: order % has pending commission(s) committed to an active commission payment batch. Void that payment first, then cancel.', v_order.order_number;
  END IF;

  SET LOCAL app.admin_override = 'true';

  UPDATE deliveries SET
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_by = v_actor,
    cancel_reason = 'Parent order ' || v_order.order_number || ' cancelled',
    updated_at = now()
  WHERE order_id = p_order_id
    AND status IN ('scheduled', 'in_progress');
  GET DIAGNOSTICS v_deliveries_cancelled = ROW_COUNT;

  IF v_deliveries_cancelled > 0 THEN
    INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
    SELECT
      d.assigned_driver,
      'Delivery Cancelled',
      'Delivery ' || d.delivery_number || ' cancelled — order ' || v_order.order_number || ' was cancelled.',
      'delivery_update', 'delivery', d.id
    FROM deliveries d
    WHERE d.order_id = p_order_id
      AND d.status = 'cancelled'
      AND d.cancel_reason LIKE 'Parent order%'
      AND d.assigned_driver IS NOT NULL;
  END IF;

  UPDATE orders SET status = 'cancelled', updated_at = now() WHERE id = p_order_id;
  -- A3<<< draw-ledger reversal (finding A3, 20260610190000 — see file header).
  -- cancel = only the UNDELIVERED remainder returns to the booking balance
  -- (mirrors the prebook release below); delivered units stay consumed so the
  -- customer cannot be over-entitled.
  IF COALESCE(v_order.booking_draw, false) AND v_order.quote_id IS NOT NULL THEN
    -- Lock the parent quote first: same quote → inventory order as
    -- draw_down_quote, and serializes against a concurrent draw.
    SELECT * INTO v_draw_quote FROM quotes
    WHERE id = v_order.quote_id FOR UPDATE;

    FOR v_draw_item IN
      SELECT product_id,
             SUM(GREATEST(COALESCE(total_units_needed, 0) - COALESCE(quantity_delivered, 0), 0)) AS qty_undelivered
      FROM order_items
      WHERE order_id = p_order_id AND product_id IS NOT NULL
      GROUP BY product_id
      HAVING SUM(GREATEST(COALESCE(total_units_needed, 0) - COALESCE(quantity_delivered, 0), 0)) > 0
    LOOP
      UPDATE quote_product_draws
        SET quantity_drawn = GREATEST(quantity_drawn - v_draw_item.qty_undelivered, 0),
            updated_at = now()
      WHERE quote_id = v_order.quote_id
        AND product_id = v_draw_item.product_id;
    END LOOP;

    -- If this was the final draw, the quote sits at 'accepted'; with the
    -- balance restored it is no longer fully drawn, so reopen the booking.
    IF v_draw_quote.status = 'accepted' THEN
      SELECT COALESCE(bool_and(COALESCE(d.quantity_drawn, 0) >= b.booked), true) INTO v_draw_fully_drawn
      FROM (
        SELECT product_id, SUM(COALESCE(total_units_needed, 0)) AS booked
        FROM quote_items WHERE quote_id = v_order.quote_id
        GROUP BY product_id
      ) b
      LEFT JOIN quote_product_draws d
        ON d.quote_id = v_order.quote_id AND d.product_id = b.product_id
      WHERE b.booked > 0;

      IF NOT v_draw_fully_drawn THEN
        -- app.admin_override is already 'true' for this whole function body
        -- (SET LOCAL above) and is deliberately NOT reset here — the later
        -- unposted-invoice cancellation depends on it staying set.
        UPDATE quotes SET status = 'sent', updated_at = now()
        WHERE id = v_order.quote_id;

        INSERT INTO activity_feed (event_type, description, performed_by,
          related_entity_type, related_entity_id, customer_id)
        VALUES ('booking_reopened',
          'Booking ' || v_draw_quote.quote_number || ' reopened (accepted → sent): draw order ' ||
            v_order.order_number || ' was cancelled, returning its undelivered quantity to the booking balance',
          v_actor, 'quote', v_order.quote_id, v_draw_quote.customer_id);
      END IF;
    END IF;
  END IF;
  -- >>>A3

  FOR v_item IN
    SELECT product_id, total_units_needed, quantity_delivered
    FROM order_items WHERE order_id = p_order_id
  LOOP
    v_undelivered := GREATEST(v_item.total_units_needed - COALESCE(v_item.quantity_delivered, 0), 0);
    IF v_undelivered <= 0 THEN CONTINUE; END IF;

    UPDATE inventory SET
      quantity_prebooked = GREATEST(quantity_prebooked - v_undelivered, 0),
      updated_at = now()
    WHERE product_id = v_item.product_id AND location = 'Main Warehouse';

    INSERT INTO inventory_transactions (
      product_id, transaction_type, quantity, to_location,
      order_id, performed_by, notes
    ) VALUES (
      v_item.product_id, 'released', v_undelivered, 'Main Warehouse',
      p_order_id, v_actor,
      'Released ' || v_undelivered || ' units — order ' || v_order.order_number || ' cancelled'
    );
  END LOOP;

  -- F7 fix / A3b: a non-draw cancel deactivates the booking's holds; a draw cancel
  -- keeps the booking OPEN but must REBUILD its holds to booked−drawn — the draw
  -- moved hold→prebooked, the prebooked was just released above, and the drawn
  -- ledger was just reduced, so a preserved (decremented) hold leaks the returned
  -- quantity out of the reservation (Net Free over-counts). Codex 2026-06-13 finding 1.
  IF v_order.quote_id IS NOT NULL THEN
    IF COALESCE(v_order.booking_draw, false) THEN
      PERFORM _sync_planned_holds(v_order.quote_id, v_actor);
    ELSE
      UPDATE inventory_holds SET is_active = false, updated_at = now()
      WHERE source_id = v_order.quote_id AND is_active = true;
      GET DIAGNOSTICS v_holds_released = ROW_COUNT;
    END IF;
  END IF;

  UPDATE commissions SET
    status = 'cancelled',
    commission_amount = 0
  WHERE order_id = p_order_id AND status = 'pending';
  GET DIAGNOSTICS v_commissions_cancelled = ROW_COUNT;

  SELECT COUNT(*) INTO v_paid_commissions
  FROM commissions WHERE order_id = p_order_id AND status = 'paid';

  IF v_paid_commissions > 0 THEN
    FOR v_admin IN
      SELECT id FROM profiles WHERE role = 'admin' AND is_active = true
    LOOP
      INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
      VALUES (
        v_admin.id,
        'Cancelled Order Has Paid Commissions',
        'Order ' || v_order.order_number || ' was cancelled but has ' || v_paid_commissions || ' paid commission(s). Manual review required.',
        'cancellation_review', 'order', p_order_id
      );
    END LOOP;
  END IF;

  FOR v_invoice IN
    SELECT * FROM invoices
    WHERE order_id = p_order_id
      AND deleted_at IS NULL
      AND status IN ('draft', 'unposted', 'posted')
  LOOP
    IF v_invoice.status IN ('draft', 'unposted') THEN
      UPDATE invoices SET
        status = 'cancelled',
        total_amount_cents = 0,
        paid_amount_cents = 0,
        prepay_applied_cents = 0,
        write_off_cents = 0,
        updated_at = now()
      WHERE id = v_invoice.id;

      INSERT INTO financial_audit_log (
        operation_type, entity_type, entity_id, actor_role,
        old_values, new_values, total_impact_cents, description
      ) VALUES (
        'invoice_cancelled', 'invoice', v_invoice.id, 'admin',
        jsonb_build_object('status', v_invoice.status, 'total_cents', v_invoice.total_amount_cents),
        jsonb_build_object('status', 'cancelled', 'reason', 'Order ' || v_order.order_number || ' cancelled'),
        -1 * v_invoice.total_amount_cents,
        'Auto-cancelled ' || v_invoice.status || ' invoice ' || v_invoice.invoice_number || ' — order ' || v_order.order_number || ' cancelled'
      );

      v_draft_cancelled := v_draft_cancelled + 1;

    ELSIF v_invoice.status = 'posted' THEN
      FOR v_admin IN
        SELECT id FROM profiles WHERE role = 'admin' AND is_active = true
      LOOP
        INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
        VALUES (
          v_admin.id,
          'Order Cancelled — Posted Invoice Needs Review',
          'Order ' || v_order.order_number || ' cancelled. Invoice ' || v_invoice.invoice_number || ' is posted and needs manual voiding.',
          'cancellation_review', 'invoice', v_invoice.id
        );
      END LOOP;

      v_posted_notified := v_posted_notified + 1;
    END IF;
  END LOOP;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    old_values, new_values, total_impact_cents, description
  ) VALUES (
    'order_cancelled', 'order', p_order_id, 'admin',
    jsonb_build_object('status', v_order.status, 'order_number', v_order.order_number),
    jsonb_build_object(
      'status', 'cancelled',
      'deliveries_cancelled', v_deliveries_cancelled,
      'holds_released', v_holds_released,
      'commissions_cancelled', v_commissions_cancelled,
      'draft_invoices_cancelled', v_draft_cancelled,
      'posted_invoices_flagged', v_posted_notified
    ),
    0,
    'Order ' || v_order.order_number || ' cancelled by admin'
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'order_cancelled',
    'Order ' || v_order.order_number || ' cancelled. ' ||
      v_deliveries_cancelled || ' delivery(s) cancelled, ' ||
      v_holds_released || ' hold(s) released, ' ||
      v_commissions_cancelled || ' commission(s) zeroed, ' ||
      v_draft_cancelled || ' draft/unposted invoice(s) cancelled.' ||
      CASE WHEN v_posted_notified > 0 THEN ' ' || v_posted_notified || ' posted invoice(s) flagged for review.' ELSE '' END ||
      CASE WHEN v_paid_commissions > 0 THEN ' ' || v_paid_commissions || ' paid commission(s) flagged for review.' ELSE '' END,
    v_actor, 'order', p_order_id, v_order.customer_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'status', 'cancelled',
    'order_number', v_order.order_number,
    'deliveries_cancelled', v_deliveries_cancelled,
    'holds_released', v_holds_released,
    'commissions_cancelled', v_commissions_cancelled,
    'paid_commissions_flagged', v_paid_commissions,
    'draft_invoices_cancelled', v_draft_cancelled,
    'posted_invoices_flagged', v_posted_notified
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'cancel_order', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."_cancel_order_impl_20260714"("p_order_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_cancel_order_split_provenance_impl_20260719"("p_order_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'cancel_order');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  PERFORM 1 FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF;

  IF EXISTS (
    SELECT 1
    FROM public.returns r
    WHERE r.order_id = p_order_id
      AND r.deleted_at IS NULL
      AND r.status IN ('received', 'credited')
  ) THEN
    RAISE EXCEPTION 'ORDER_HAS_RECEIVED_RETURN';
  END IF;

  RETURN public._cancel_order_impl_20260714(
    p_order_id, p_performed_by, p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."_cancel_order_split_provenance_impl_20260719"("p_order_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_check_credit_limit"("p_customer_id" "uuid", "p_additional_cents" bigint DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_customer    record;
  v_ar_balance  bigint;
BEGIN
  SELECT credit_limit_cents, farm_name INTO v_customer FROM customers WHERE id = p_customer_id;
  IF COALESCE(v_customer.credit_limit_cents, 0) = 0 THEN RETURN; END IF;

  SELECT COALESCE(SUM(balance_cents), 0) INTO v_ar_balance
  FROM invoices WHERE customer_id = p_customer_id AND status IN ('draft', 'posted', 'overdue');

  v_ar_balance := v_ar_balance + p_additional_cents;

  IF v_ar_balance >= v_customer.credit_limit_cents THEN
    RAISE EXCEPTION 'Credit limit exceeded for customer "%": limit $%, current AR balance $%',
      v_customer.farm_name, (v_customer.credit_limit_cents / 100.0)::numeric(12,2), (v_ar_balance / 100.0)::numeric(12,2);
  END IF;
END;
$_$;


ALTER FUNCTION "public"."_check_credit_limit"("p_customer_id" "uuid", "p_additional_cents" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_claim_bound_lifecycle_idempotency"("p_key" "text", "p_operation" "text", "p_contract" "text", "p_request_fingerprint" "text", "p_request" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing_operation text;
  v_existing jsonb;
BEGIN
  IF p_key IS NULL THEN
    RETURN NULL;
  END IF;
  IF btrim(p_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('crx:idempotency:' || p_operation || ':' || p_key, 0)
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('crx:idempotency:' || p_key, 0)
  );

  DELETE FROM public.idempotency_keys
   WHERE idempotency_key = p_key
     AND expires_at < now();

  SELECT k.operation, k.result
    INTO v_existing_operation, v_existing
    FROM public.idempotency_keys k
   WHERE k.idempotency_key = p_key;

  IF NOT FOUND THEN
    INSERT INTO public.idempotency_keys (
      idempotency_key, operation, result, expires_at
    ) VALUES (
      p_key,
      p_operation,
      jsonb_build_object(
        '_contract', p_contract,
        'request_fingerprint', p_request_fingerprint,
        'request', p_request,
        'response', NULL
      ),
      now() + interval '24 hours'
    );
    RETURN NULL;
  END IF;
  IF v_existing_operation IS DISTINCT FROM p_operation THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_CROSS_OP_KEY_REUSE: idempotency_key % is already in use for operation %; cannot reuse it for operation %',
      p_key, v_existing_operation, p_operation;
  END IF;
  IF v_existing->>'_contract' IS DISTINCT FROM p_contract
     OR NOT (v_existing ? 'request_fingerprint') THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_UNBOUND_REPLAY: key % has no % request binding; use a new key',
      p_key, p_contract;
  END IF;
  IF v_existing->>'request_fingerprint' IS DISTINCT FROM p_request_fingerprint THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_REQUEST_MISMATCH: key % was already used with different % arguments',
      p_key, p_operation;
  END IF;
  IF NOT (v_existing ? 'response') OR v_existing->'response' = 'null'::jsonb THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_INCOMPLETE_REPLAY: key % has no completed % response',
      p_key, p_operation;
  END IF;

  RETURN v_existing->'response';
END;
$$;


ALTER FUNCTION "public"."_claim_bound_lifecycle_idempotency"("p_key" "text", "p_operation" "text", "p_contract" "text", "p_request_fingerprint" "text", "p_request" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_close_job_location_dispatch_on_job_terminal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status IN ('completed', 'cancelled') THEN
    -- Cancel (never hard-delete) — mirrors undispatch_job_locations's audit-
    -- preserving semantics. NEW.status is used directly as the new
    -- dispatch_status: both 'completed' and 'cancelled' are already allowed by
    -- job_location_dispatches_dispatch_status_check, so this maps 1:1 with no
    -- constraint change.
    UPDATE job_location_dispatches
       SET dispatch_status = NEW.status,
           updated_at = now()
     WHERE job_id = NEW.id
       AND dispatch_status = 'dispatched';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_close_job_location_dispatch_on_job_terminal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_complete_cycle_count_impl"("p_cycle_count_id" "uuid", "p_completed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_item     RECORD;
  v_count    record;
  v_new_qty  numeric;
  v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_completed_by IS NOT NULL AND p_completed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_completed_by does not match authenticated user';
  END IF;
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Admin access required to complete a cycle count';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'complete_cycle_count');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;

  SELECT * INTO v_count
    FROM cycle_counts
   WHERE id = p_cycle_count_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cycle count not found';
  END IF;

  IF v_count.status != 'in_progress' THEN
    RAISE EXCEPTION 'Cycle count is not in progress (current status: %)', v_count.status;
  END IF;

  FOR v_item IN
    SELECT cci.*, i.quantity_available, i.location
    FROM cycle_count_items cci
    LEFT JOIN inventory i ON i.id = cci.inventory_id
    WHERE cci.cycle_count_id = p_cycle_count_id
      AND cci.is_counted = true
      AND cci.variance IS NOT NULL
      AND cci.variance <> 0
  LOOP
    IF v_item.inventory_id IS NOT NULL THEN
      IF COALESCE(v_item.quantity_available, 0) + v_item.variance < 0 THEN
        RAISE EXCEPTION 'Cycle count adjustment for product % would set on-hand to % (currently %, variance %). Resolve upstream discrepancy (missing delivery, unlogged return, prior reconciliation gap) before completing this count.',
          v_item.product_id,
          COALESCE(v_item.quantity_available, 0) + v_item.variance,
          COALESCE(v_item.quantity_available, 0),
          v_item.variance;
      END IF;

      v_new_qty := COALESCE(v_item.quantity_available, 0) + v_item.variance;

      UPDATE inventory
      SET quantity_available = v_new_qty,
          last_counted_at    = now(),
          updated_at         = now()
      WHERE id = v_item.inventory_id;

      INSERT INTO inventory_transactions (
        product_id, transaction_type, quantity,
        to_location, performed_by, notes
      ) VALUES (
        v_item.product_id, 'adjusted', v_item.variance,
        v_item.location, v_actor,
        'Cycle count ' || v_count.count_number || ': adjusted from ' ||
        v_item.expected_qty || ' to ' || v_item.counted_qty
      );
    END IF;
  END LOOP;

  UPDATE inventory
  SET last_counted_at = now(), updated_at = now()
  WHERE id IN (
    SELECT cci.inventory_id FROM cycle_count_items cci
    WHERE cci.cycle_count_id = p_cycle_count_id
      AND cci.is_counted = true
      AND cci.inventory_id IS NOT NULL
  );

  UPDATE cycle_counts
  SET status       = 'completed',
      completed_by = v_actor,
      completed_at = now()
  WHERE id = p_cycle_count_id;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'complete_cycle_count', '{}'::jsonb);
  END IF;
END;
$$;


ALTER FUNCTION "public"."_complete_cycle_count_impl"("p_cycle_count_id" "uuid", "p_completed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_complete_delivery_aggregate_impl"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_quantities" "jsonb" DEFAULT NULL::"jsonb", "p_issue_type" "text" DEFAULT NULL::"text", "p_issue_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_completed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_actor_role text;
  v_delivery record;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;

  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT id, assigned_driver
    INTO v_delivery
    FROM public.deliveries
   WHERE id = p_delivery_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Delivery not found: %', p_delivery_id;
  END IF;

  SELECT role
    INTO v_actor_role
    FROM public.profiles
   WHERE id = v_actor
     AND is_active = true;

  IF v_actor_role IS NULL OR NOT (
    v_actor_role IN ('admin', 'sales_rep')
    OR (v_actor_role = 'driver' AND v_actor = v_delivery.assigned_driver)
  ) THEN
    RAISE EXCEPTION 'Not authorized to complete this delivery';
  END IF;

  RETURN public._complete_delivery_authorized_impl(
    p_delivery_id,
    p_signed_by,
    p_performed_by,
    p_quantities,
    p_issue_type,
    p_issue_notes,
    p_idempotency_key,
    p_completed_at
  );
END;
$$;


ALTER FUNCTION "public"."_complete_delivery_aggregate_impl"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid", "p_quantities" "jsonb", "p_issue_type" "text", "p_issue_notes" "text", "p_idempotency_key" "text", "p_completed_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_complete_delivery_aggregate_impl"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid", "p_quantities" "jsonb", "p_issue_type" "text", "p_issue_notes" "text", "p_idempotency_key" "text", "p_completed_at" timestamp with time zone) IS 'Internal delivery completion wrapper. Direct execution is revoked; use public.complete_delivery so aggregate repeated-product stock checks run first.';



CREATE OR REPLACE FUNCTION "public"."_complete_delivery_authorized_impl"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_quantities" "jsonb" DEFAULT NULL::"jsonb", "p_issue_type" "text" DEFAULT NULL::"text", "p_issue_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_completed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_delivery record;
  v_item record;
  v_inv record;
  v_qty_to_deliver numeric;
  v_deduct_from_prebooked numeric;
  v_any_partial boolean := false;
  v_all_delivered boolean;
  v_linked_invoice record;
  v_result jsonb;
  v_existing jsonb;
  v_actor uuid;
  v_actor_role text;
  v_auto_invoice_id uuid;
  v_auto_invoice_number text;
  v_auto_total_cents bigint := 0;
  v_auto_cost_cents bigint := 0;
  v_existing_active_invoice_count int;
  v_closed_period record;
  v_admin record;
  -- U9 stock-policy WARN-NOT-BLOCK
  v_short_count int := 0;
  v_stock_warnings text[] := '{}';
  v_short_product_ids uuid[] := '{}';
  v_effective_completion_date date;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;

  -- U15: optional backdate. Reject future timestamps (small clock-skew allowance);
  -- NULL = legacy behavior (now()/CURRENT_DATE).
  IF p_completed_at IS NOT NULL AND p_completed_at > now() + interval '5 minutes' THEN
    RAISE EXCEPTION 'COMPLETED_AT_IN_FUTURE: completion time cannot be in the future';
  END IF;

  v_effective_completion_date := COALESCE(
    (p_completed_at AT TIME ZONE 'America/Chicago')::date,
    (now() AT TIME ZONE 'America/Chicago')::date
  );

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'complete_delivery');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_delivery FROM deliveries WHERE id = p_delivery_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found: %', p_delivery_id; END IF;

  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR NOT (
    v_actor_role IN ('admin', 'sales_rep')
    OR (v_actor_role = 'driver' AND v_actor = v_delivery.assigned_driver)
  ) THEN
    RAISE EXCEPTION 'Not authorized to complete this delivery';
  END IF;

  IF v_delivery.status != 'in_progress' THEN
    RAISE EXCEPTION 'Delivery must be in_progress to complete (current status: %). Call confirm_delivery() first.', v_delivery.status;
  END IF;

  -- PR-01 fix: column is `scheduled_date`, not `delivery_date`.
  SELECT id, period_start, period_end
    INTO v_closed_period
    FROM accounting_periods
   WHERE status = 'closed'
     AND v_effective_completion_date BETWEEN period_start AND period_end
   LIMIT 1;

  IF FOUND THEN
    INSERT INTO activity_feed (
      event_type, description, performed_by,
      related_entity_type, related_entity_id, customer_id
    ) VALUES (
      'backdated_delivery_in_closed_period',
      'WARNING: Delivery ' || v_delivery.delivery_number ||
        ' completed for ' || v_effective_completion_date::text ||
        ' which falls in CLOSED accounting period ' ||
        v_closed_period.period_start::text || ' to ' ||
        v_closed_period.period_end::text || '. Operation proceeded; verify with finance.',
      v_actor, 'delivery', p_delivery_id, v_delivery.customer_id
    );

    FOR v_admin IN SELECT id FROM profiles WHERE role = 'admin' AND is_active = true
    LOOP
      INSERT INTO notifications (
        user_id, title, message, notification_type,
        related_entity_type, related_entity_id
      ) VALUES (
        v_admin.id,
        'Backdated Delivery Completion',
        'Delivery ' || v_delivery.delivery_number ||
          ' was completed for ' || v_effective_completion_date::text ||
          ' — that date is inside a CLOSED accounting period (' ||
          v_closed_period.period_start::text || ' to ' ||
          v_closed_period.period_end::text || '). Inventory and lifecycle ' ||
          'changes proceeded. Verify the financial impact.',
        'period_warning', 'delivery', p_delivery_id
      );
    END LOOP;
  END IF;

  FOR v_item IN
    SELECT di.*, p.product_name FROM delivery_items di JOIN products p ON p.id = di.product_id
    WHERE di.delivery_id = p_delivery_id
  LOOP
    IF p_quantities IS NOT NULL AND p_quantities ? v_item.id::text THEN
      v_qty_to_deliver := GREATEST(0, LEAST((p_quantities->>v_item.id::text)::numeric, v_item.quantity));
    ELSE
      v_qty_to_deliver := v_item.quantity;
    END IF;
    IF v_qty_to_deliver < v_item.quantity THEN v_any_partial := true; END IF;
    IF v_qty_to_deliver = 0 THEN CONTINUE; END IF;
    SELECT * INTO v_inv FROM inventory WHERE product_id = v_item.product_id AND location = 'Main Warehouse' FOR UPDATE;
    -- U9: WARN-NOT-BLOCK (was: RAISE EXCEPTION 'Insufficient inventory ...').
    -- Same on-hand math; completion proceeds and stock is allowed to go negative.
    IF NOT FOUND OR COALESCE(v_inv.quantity_available, 0) < v_qty_to_deliver THEN
      v_short_count := v_short_count + 1;
      v_short_product_ids := array_append(v_short_product_ids, v_item.product_id);
      v_stock_warnings := array_append(v_stock_warnings,
        v_item.product_name || ': need ' || v_qty_to_deliver || ', only ' ||
        COALESCE(v_inv.quantity_available, 0) || ' on-hand');
      -- U9 (Codex R2 P2): seed a zero row when missing so the deduction UPDATE
      -- below lands and the on-hand aggregate goes visibly negative.
      IF NOT FOUND THEN
        INSERT INTO inventory (product_id, location, quantity_available, quantity_prebooked, manufactured_at_delivery)
        VALUES (v_item.product_id, 'Main Warehouse', 0, 0, true)  -- surfaces on /integrity-cleanup (P4-7 phantom-row flag)
        ON CONFLICT DO NOTHING;
      END IF;
    END IF;
  END LOOP;

  -- P2-D: authorize the post-completion delivery_items + lifecycle writes below.
  -- The enforce_delivery_items_parent_lock trigger blocks writes to a
  -- non-scheduled delivery's items; complete_delivery legitimately records
  -- quantity_delivered after flipping status to 'completed', so it sets the
  -- canonical admin_override escape hatch (transaction-local).
  SET LOCAL app.admin_override = 'true';

  UPDATE deliveries SET
    status = 'completed', completed_at = COALESCE(p_completed_at, now()), signed_by = p_signed_by,
    issue_type = COALESCE(p_issue_type, issue_type),
    issue_notes = CASE WHEN p_issue_notes IS NOT NULL THEN p_issue_notes ELSE issue_notes END
  WHERE id = p_delivery_id;

  FOR v_item IN
    SELECT di.*, p.product_name FROM delivery_items di JOIN products p ON p.id = di.product_id
    WHERE di.delivery_id = p_delivery_id
  LOOP
    IF p_quantities IS NOT NULL AND p_quantities ? v_item.id::text THEN
      v_qty_to_deliver := GREATEST(0, LEAST((p_quantities->>v_item.id::text)::numeric, v_item.quantity));
    ELSE
      v_qty_to_deliver := v_item.quantity;
    END IF;
    UPDATE delivery_items SET quantity_delivered = v_qty_to_deliver WHERE id = v_item.id;
    IF v_qty_to_deliver = 0 THEN CONTINUE; END IF;

    UPDATE order_items SET
      quantity_delivered = quantity_delivered + v_qty_to_deliver,
      quantity_remaining = GREATEST(quantity_remaining - v_qty_to_deliver, 0)
    WHERE id = v_item.order_item_id;

    -- U9: flag the delivered ledger row for review when the product was short.
    INSERT INTO inventory_transactions (
      product_id, transaction_type, quantity, from_location,
      order_id, delivery_id, performed_by, notes, requires_review
    ) VALUES (
      v_item.product_id, 'delivered', v_qty_to_deliver, 'Main Warehouse',
      v_delivery.order_id, p_delivery_id, v_actor,
      'Delivery ' || v_delivery.delivery_number ||
        CASE WHEN v_qty_to_deliver < v_item.quantity
          THEN ' (partial: ' || v_qty_to_deliver || '/' || v_item.quantity || ')'
          ELSE '' END ||
        CASE WHEN v_item.product_id = ANY(v_short_product_ids)
          THEN ' [SHORT STOCK — review required]' ELSE '' END ||
        '. Signed by: ' || p_signed_by,
      v_item.product_id = ANY(v_short_product_ids)
    );

    SELECT * INTO v_inv FROM inventory WHERE product_id = v_item.product_id AND location = 'Main Warehouse';
    v_deduct_from_prebooked := LEAST(v_qty_to_deliver, COALESCE(v_inv.quantity_prebooked, 0));

    UPDATE inventory SET
      quantity_available = quantity_available - v_qty_to_deliver,
      quantity_prebooked = quantity_prebooked - v_deduct_from_prebooked,
      updated_at = now()
    WHERE product_id = v_item.product_id AND location = 'Main Warehouse';
  END LOOP;

  -- U2 (Codex P2): with per-delivery invoices now possible on one order, the
  -- tote copy must NOT stamp a SIBLING delivery's invoice — scope it to this
  -- delivery's own invoice or an order-level one (delivery_id IS NULL), the
  -- same shape as the auto-invoice guard below.
  UPDATE invoice_items ii
  SET tote_number = di.tote_number
  FROM delivery_items di
  JOIN invoices inv ON inv.order_id = v_delivery.order_id AND inv.deleted_at IS NULL
    AND (inv.delivery_id = p_delivery_id OR inv.delivery_id IS NULL)
  WHERE di.delivery_id = p_delivery_id
    AND ii.invoice_id = inv.id
    AND di.order_item_id = ii.order_item_id
    AND di.tote_number IS NOT NULL;

  IF v_any_partial THEN
    FOR v_item IN
      SELECT di.*, p.product_name FROM delivery_items di JOIN products p ON p.id = di.product_id
      WHERE di.delivery_id = p_delivery_id AND di.quantity_delivered < di.quantity
    LOOP
      INSERT INTO delivery_remainders (
        original_delivery_id, order_id, order_item_id,
        customer_id, product_id, quantity_remaining, unit_size
      ) VALUES (
        p_delivery_id, v_delivery.order_id, v_item.order_item_id,
        v_delivery.customer_id, v_item.product_id,
        v_item.quantity - v_item.quantity_delivered, v_item.unit_size
      );
    END LOOP;
  END IF;

  -- U2 #39: close out the remainder rows THIS follow-up delivery was created to satisfy.
  -- create_followup_delivery flips the parent's remainders 'pending'->'scheduled' and stamps
  -- followup_delivery_id = this delivery. Now that this delivery has completed, mark them
  -- 'fulfilled'. Any lines this follow-up ITSELF shorted are already captured as fresh
  -- 'pending' remainder rows by the v_any_partial INSERT above (original_delivery_id = this
  -- delivery), so this flip never loses outstanding quantity — it prevents the same shortfall
  -- being double-counted as both a stale 'scheduled' row and a new 'pending' row. Idempotent
  -- (guarded by status = 'scheduled'); targets rows disjoint from the ones just inserted.
  UPDATE delivery_remainders
     SET status = 'fulfilled', updated_at = now()
   WHERE followup_delivery_id = p_delivery_id
     AND status = 'scheduled';

  -- P2 fix (Codex 2026-07-10): serialize concurrent same-day FINAL deliveries on the SAME
  -- order. Two deliveries completing at once each read v_all_delivered under READ COMMITTED
  -- without seeing the other's uncommitted order_items decrement, so both could compute
  -- false and skip the Feature A auto-split (order falls back to manual split-billing — safe,
  -- but the auto-split silently doesn't fire). Take the orders row lock BEFORE the read: the
  -- second completion blocks here until the first commits, then sees the committed decrement.
  -- Lock ORDER is unchanged (deliveries -> inventory -> orders): the UPDATE orders just below
  -- already acquired this same row lock — this only moves the acquisition ahead of the read,
  -- adding no new lock pair (no new deadlock surface).
  IF v_delivery.order_id IS NOT NULL THEN
    PERFORM 1 FROM orders WHERE id = v_delivery.order_id FOR UPDATE;
  END IF;

  SELECT NOT EXISTS (
    SELECT 1 FROM order_items WHERE order_id = v_delivery.order_id AND quantity_remaining > 0
  ) INTO v_all_delivered;

  UPDATE orders SET
    status = CASE WHEN v_all_delivered THEN 'fulfilled' ELSE 'partially_fulfilled' END,
    updated_at = now()
  WHERE id = v_delivery.order_id;

  IF v_any_partial AND v_delivery.order_id IS NOT NULL THEN
    FOR v_linked_invoice IN
      SELECT * FROM invoices
      WHERE order_id = v_delivery.order_id AND status = 'draft' AND delivery_id = p_delivery_id
    LOOP
      UPDATE invoice_items ii SET
        quantity = di.quantity_delivered,
        extended_cents = ROUND(di.quantity_delivered * ii.unit_price_cents)
      FROM delivery_items di
      WHERE di.delivery_id = p_delivery_id AND ii.invoice_id = v_linked_invoice.id AND ii.order_item_id = di.order_item_id;
      -- Overnight bug-hunt LOW (20260620): also recompute the stored header cost so
      -- a partial completion doesn't leave total_cost_cents sized to the full qty.
      -- cost_cents is PER-UNIT cents; line cost = cost_cents * quantity (no *100).
      UPDATE invoices SET
        total_amount_cents = (SELECT COALESCE(SUM(extended_cents), 0) FROM invoice_items WHERE invoice_id = v_linked_invoice.id),
        total_cost_cents = (SELECT COALESCE(SUM(cost_cents * quantity), 0) FROM invoice_items WHERE invoice_id = v_linked_invoice.id),
        updated_at = now()
      WHERE id = v_linked_invoice.id;
    END LOOP;
  END IF;

  IF v_delivery.order_id IS NOT NULL THEN
    -- U2 #34: per-DELIVERY-aware guard (was per-ORDER). Block only if THIS delivery already
    -- has an active invoice, or an ORDER-LEVEL invoice (delivery_id IS NULL) already covers
    -- the whole order. An active invoice tied to a DIFFERENT delivery must NOT block this
    -- delivery — otherwise a follow-up delivery of shorted product is never billed.
    SELECT COUNT(*) INTO v_existing_active_invoice_count
    FROM invoices
    WHERE order_id = v_delivery.order_id
      AND status NOT IN ('voided', 'cancelled')
      AND (delivery_id = p_delivery_id OR delivery_id IS NULL);

    IF v_existing_active_invoice_count = 0 THEN
      -- U7 SAFE-SCOPE (#43): a field/acre-allocated order must NOT be mono-billed
      -- 100% to the primary customer (that dead-ends the landlord's payment). Skip the
      -- auto-draft, flag the order for a manual per-owner split-billing pass, and notify
      -- the office. Non-allocated orders keep the EXACT auto-draft in the ELSE below.
      IF EXISTS (
        SELECT 1 FROM order_item_field_allocations oifa
        JOIN order_items oi ON oi.id = oifa.order_item_id
        WHERE oi.order_id = v_delivery.order_id
      ) THEN
        -- Codex pre-ship HIGH fix: only auto-split when the delivery's EFFECTIVE date is TODAY.
        -- create_split_invoices_from_order stamps invoice_date = CURRENT_DATE and takes no date arg, so
        -- auto-splitting a BACKDATED completion (p_completed_at in a prior/closed period) would silently
        -- date the drafts today and shift AR aging/terms — while the mono-bill path (below) respects the
        -- backdate. A backdated allocated order falls through to flag+notify (the office creates the split
        -- manually, exactly as before Feature A); same-day completions (the common case) auto-split.
        IF v_all_delivered
           AND v_effective_completion_date = (now() AT TIME ZONE 'America/Chicago')::date THEN
          -- the whole order is now delivered TODAY -> auto-create the per-owner split DRAFTS via the proven engine.
          BEGIN
            PERFORM create_split_invoices_from_order(
              v_delivery.order_id, NULL, 'chemical_sale',
              COALESCE(p_idempotency_key, p_delivery_id::text) || ':autosplit'
            );
            -- create_split_invoices_from_order creates draft invoices per owner, clears
            -- needs_split_billing, and writes its own activity_feed + financial_audit_log rows.
            -- Add ONE activity_feed row noting the auto-creation on this delivery completion.
            INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
            VALUES (
              'split_invoices_auto_created',
              'Delivery ' || v_delivery.delivery_number || ' completed the order — per-owner split DRAFT invoices were auto-created (review + post them).',
              v_actor, 'order', v_delivery.order_id, v_delivery.customer_id
            );
          EXCEPTION WHEN OTHERS THEN
            -- Any reason the split cannot run yet (order not priced -> PRICING_INCOMPLETE, an
            -- edge race, a still-open sibling delivery, etc.): fall back to today's flag+notify.
            -- The subtransaction rolls back any partial split work; the delivery completion is UNAFFECTED.
        UPDATE orders SET needs_split_billing = true, updated_at = now()
          WHERE id = v_delivery.order_id;
        INSERT INTO activity_feed (
          event_type, description, performed_by,
          related_entity_type, related_entity_id, customer_id
        ) VALUES (
          'order_needs_split_billing',
          'Delivery ' || v_delivery.delivery_number || ' completed on a multi-owner (field/acre) order — auto-invoice skipped; create split invoices from the order to bill each owner.',
          v_actor, 'order', v_delivery.order_id, v_delivery.customer_id
        );
        FOR v_admin IN SELECT id FROM profiles WHERE role = 'admin' AND is_active = true
        LOOP
          INSERT INTO notifications (
            user_id, title, message, notification_type,
            related_entity_type, related_entity_id
          ) VALUES (
            v_admin.id,
            'Order needs split billing',
            'Delivery ' || v_delivery.delivery_number || ' completed on a field/acre-allocated order. The mono-bill auto-invoice was skipped — open the order and use "Create Split Invoices" to bill each owner their own payable invoice.',
            'split_billing', 'order', v_delivery.order_id
          );
        END LOOP;
        END;
      ELSE
        -- Partial delivery of an allocated order (product still remains): keep today's
        -- skip-and-queue exactly. (Per-delivery split billing for partial orders is a separate redesign.)
        UPDATE orders SET needs_split_billing = true, updated_at = now()
          WHERE id = v_delivery.order_id;
        INSERT INTO activity_feed (
          event_type, description, performed_by,
          related_entity_type, related_entity_id, customer_id
        ) VALUES (
          'order_needs_split_billing',
          'Delivery ' || v_delivery.delivery_number || ' completed on a multi-owner (field/acre) order — auto-invoice skipped; create split invoices from the order to bill each owner.',
          v_actor, 'order', v_delivery.order_id, v_delivery.customer_id
        );
        FOR v_admin IN SELECT id FROM profiles WHERE role = 'admin' AND is_active = true
        LOOP
          INSERT INTO notifications (
            user_id, title, message, notification_type,
            related_entity_type, related_entity_id
          ) VALUES (
            v_admin.id,
            'Order needs split billing',
            'Delivery ' || v_delivery.delivery_number || ' completed on a field/acre-allocated order. The mono-bill auto-invoice was skipped — open the order and use "Create Split Invoices" to bill each owner their own payable invoice.',
            'split_billing', 'order', v_delivery.order_id
          );
        END LOOP;
      END IF;
      ELSE
      v_auto_invoice_number := next_invoice_number('chemical_sale');
      INSERT INTO invoices (
        invoice_number, invoice_type, order_id, customer_id, delivery_id,
        status, invoice_date, total_amount_cents, total_cost_cents, created_by
      ) VALUES (
        v_auto_invoice_number, 'chemical_sale', v_delivery.order_id, v_delivery.customer_id, p_delivery_id,
        'draft', v_effective_completion_date, 0, 0, v_actor
      ) RETURNING id INTO v_auto_invoice_id;

      v_auto_total_cents := 0;
      v_auto_cost_cents := 0;
      FOR v_item IN
        SELECT di.id AS di_id, di.product_id, di.quantity_delivered, di.unit_size, di.order_item_id, di.tote_number,
               oi.price_per_unit, oi.cost_per_unit, oi.product_name AS oi_product_name,
               p.product_name AS p_name
          FROM delivery_items di
          JOIN order_items oi ON oi.id = di.order_item_id
          JOIN products p ON p.id = di.product_id
         WHERE di.delivery_id = p_delivery_id
           AND COALESCE(di.quantity_delivered, 0) > 0
      LOOP
        v_auto_total_cents := v_auto_total_cents + ROUND(v_item.quantity_delivered * v_item.price_per_unit * 100)::bigint;
        v_auto_cost_cents  := v_auto_cost_cents  + ROUND(v_item.quantity_delivered * COALESCE(v_item.cost_per_unit, 0) * 100)::bigint;
        INSERT INTO invoice_items (
          invoice_id, order_item_id, product_id, description,
          quantity, unit_price_cents, extended_cents, cost_cents,
          unit_size, tote_number
        ) VALUES (
          v_auto_invoice_id, v_item.order_item_id, v_item.product_id,
          COALESCE(v_item.oi_product_name, v_item.p_name),
          v_item.quantity_delivered,
          ROUND(v_item.price_per_unit * 100)::bigint,
          ROUND(v_item.quantity_delivered * v_item.price_per_unit * 100)::bigint,
          ROUND(COALESCE(v_item.cost_per_unit, 0) * 100)::bigint,
          v_item.unit_size,
          v_item.tote_number
        );
      END LOOP;

      UPDATE invoices
         SET total_amount_cents = v_auto_total_cents,
             total_cost_cents   = v_auto_cost_cents
       WHERE id = v_auto_invoice_id;

      -- Overnight bug-hunt MED (20260620): provenance breadcrumb. Write the same
      -- financial_audit_log 'invoice_created' row create_invoice_from_order /
      -- create_invoice_for_unbilled_delivery write, so the append-only ledger
      -- records this auto-creator too (it previously logged only activity_feed).
      -- Draft-stage provenance; post_invoice still writes 'invoice_posted' later.
      INSERT INTO financial_audit_log (
        operation_type, entity_type, entity_id, actor_role,
        new_values, total_impact_cents, description
      ) VALUES (
        'invoice_created', 'invoice', v_auto_invoice_id,
        (SELECT role FROM profiles WHERE id = v_actor),
        jsonb_build_object(
          'invoice_number', v_auto_invoice_number,
          'delivery_id', p_delivery_id,
          'order_id', v_delivery.order_id,
          'customer_id', v_delivery.customer_id,
          'total_cents', v_auto_total_cents
        ),
        v_auto_total_cents,
        'Invoice ' || v_auto_invoice_number || ' auto-created on completion of delivery ' || v_delivery.delivery_number
      );
      END IF;
    END IF;
  END IF;

  -- U9: short-stock WARN emit (mirrors the backdated-period warn+notify pattern above).
  IF v_short_count > 0 THEN
    INSERT INTO activity_feed (
      event_type, description, performed_by,
      related_entity_type, related_entity_id, customer_id
    ) VALUES (
      'delivery_short_stock',
      'WARNING: Delivery ' || v_delivery.delivery_number || ' completed with ' || v_short_count ||
        ' product(s) short on stock: ' || array_to_string(v_stock_warnings, ' | ') ||
        '. Completion proceeded; on-hand inventory went negative — review with the warehouse.',
      v_actor, 'delivery', p_delivery_id, v_delivery.customer_id
    );
    FOR v_admin IN SELECT id FROM profiles WHERE role = 'admin' AND is_active = true
    LOOP
      INSERT INTO notifications (
        user_id, title, message, notification_type,
        related_entity_type, related_entity_id
      ) VALUES (
        v_admin.id,
        'Short Stock — Delivery ' || v_delivery.delivery_number,
        'Delivery ' || v_delivery.delivery_number || ' was completed but ' || v_short_count ||
          ' product(s) did not have enough on-hand stock: ' || array_to_string(v_stock_warnings, ' | ') ||
          '. The completion proceeded and inventory went negative; please review.',
        'stock_warning', 'delivery', p_delivery_id
      );
    END LOOP;
  END IF;

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'delivery_completed',
    'Delivery ' || v_delivery.delivery_number || ' completed. Signed by: ' || p_signed_by ||
      CASE WHEN v_any_partial THEN ' (partial delivery — remainders created)' ELSE '' END ||
      CASE WHEN v_auto_invoice_id IS NOT NULL THEN ' [draft invoice ' || v_auto_invoice_number || ' auto-created]' ELSE '' END,
    v_actor, 'delivery', p_delivery_id, v_delivery.customer_id
  );

  -- U9: additive result fields — warnings[] + short_stock_count.
  v_result := jsonb_build_object(
    'status', CASE WHEN v_any_partial THEN 'partial' ELSE 'completed' END,
    'delivery_id', p_delivery_id,
    'order_fulfilled', v_all_delivered,
    'auto_invoice', CASE
      WHEN v_auto_invoice_id IS NOT NULL THEN
        jsonb_build_object('invoice_id', v_auto_invoice_id, 'invoice_number', v_auto_invoice_number, 'total_cents', v_auto_total_cents)
      ELSE NULL
    END,
    'stock_warning', (v_short_count > 0),
    'short_stock_count', v_short_count,
    'warnings', to_jsonb(v_stock_warnings)
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'complete_delivery', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."_complete_delivery_authorized_impl"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid", "p_quantities" "jsonb", "p_issue_type" "text", "p_issue_notes" "text", "p_idempotency_key" "text", "p_completed_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_complete_delivery_authorized_impl"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid", "p_quantities" "jsonb", "p_issue_type" "text", "p_issue_notes" "text", "p_idempotency_key" "text", "p_completed_at" timestamp with time zone) IS 'Internal delivery completion implementation. Direct execution is revoked; use public.complete_delivery so authorization runs before replay lookup.';



CREATE OR REPLACE FUNCTION "public"."_complete_delivery_period_preflight_impl"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_quantities" "jsonb" DEFAULT NULL::"jsonb", "p_issue_type" "text" DEFAULT NULL::"text", "p_issue_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_completed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_role text;
  v_delivery record;
  v_existing jsonb;
  v_result jsonb;
  v_item record;
  v_admin record;
  v_short_count integer := 0;
  v_short_product_ids uuid[] := '{}';
  v_stock_warnings text[] := '{}';
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;

  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT id, delivery_number, customer_id, assigned_driver
    INTO v_delivery
    FROM public.deliveries
   WHERE id = p_delivery_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Delivery not found: %', p_delivery_id;
  END IF;

  SELECT role
    INTO v_actor_role
    FROM public.profiles
   WHERE id = v_actor
     AND is_active = true;

  IF v_actor_role IS NULL OR NOT (
    v_actor_role IN ('admin', 'sales_rep')
    OR (v_actor_role = 'driver' AND v_actor = v_delivery.assigned_driver)
  ) THEN
    RAISE EXCEPTION 'Not authorized to complete this delivery';
  END IF;

  -- Authorization deliberately precedes replay lookup.
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(
      p_idempotency_key,
      'complete_delivery'
    );
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  -- Lock every existing warehouse row involved before taking the aggregate
  -- snapshot. Missing rows are already handled by the proven inner function.
  PERFORM 1
    FROM public.inventory inv
   WHERE inv.location = 'Main Warehouse'
     AND inv.product_id IN (
       SELECT di.product_id
         FROM public.delivery_items di
        WHERE di.delivery_id = p_delivery_id
     )
   ORDER BY inv.product_id
   FOR UPDATE;

  FOR v_item IN
    WITH effective_lines AS (
      SELECT
        di.product_id,
        p.product_name,
        CASE
          WHEN p_quantities IS NOT NULL AND p_quantities ? di.id::text
            THEN GREATEST(
              0,
              LEAST((p_quantities->>di.id::text)::numeric, di.quantity)
            )
          ELSE di.quantity
        END AS effective_quantity
      FROM public.delivery_items di
      JOIN public.products p ON p.id = di.product_id
      WHERE di.delivery_id = p_delivery_id
    )
    SELECT
      el.product_id,
      el.product_name,
      SUM(el.effective_quantity) AS quantity_needed,
      COALESCE(inv.quantity_available, 0) AS quantity_available
    FROM effective_lines el
    LEFT JOIN public.inventory inv
      ON inv.product_id = el.product_id
     AND inv.location = 'Main Warehouse'
    GROUP BY
      el.product_id,
      el.product_name,
      inv.quantity_available
    HAVING COUNT(*) FILTER (WHERE el.effective_quantity > 0) > 1
       AND SUM(el.effective_quantity) > COALESCE(inv.quantity_available, 0)
       AND MAX(el.effective_quantity) <= COALESCE(inv.quantity_available, 0)
  LOOP
    v_short_count := v_short_count + 1;
    v_short_product_ids := array_append(v_short_product_ids, v_item.product_id);
    v_stock_warnings := array_append(
      v_stock_warnings,
      v_item.product_name || ': need ' || v_item.quantity_needed ||
        ' across repeated lines, only ' || v_item.quantity_available || ' on-hand'
    );
  END LOOP;

  IF v_short_count > 0 THEN
    PERFORM pg_catalog.set_config(
      'app.delivery_aggregate_short_delivery_id',
      p_delivery_id::text,
      true
    );
    PERFORM pg_catalog.set_config(
      'app.delivery_aggregate_short_product_ids',
      array_to_string(v_short_product_ids, ','),
      true
    );
  END IF;

  v_result := public._complete_delivery_aggregate_impl(
    p_delivery_id,
    p_signed_by,
    p_performed_by,
    p_quantities,
    p_issue_type,
    p_issue_notes,
    p_idempotency_key,
    p_completed_at
  );

  IF v_short_count > 0 THEN
    INSERT INTO public.activity_feed (
      event_type,
      description,
      performed_by,
      related_entity_type,
      related_entity_id,
      customer_id
    ) VALUES (
      'delivery_short_stock',
      'WARNING: Delivery ' || v_delivery.delivery_number || ' completed with ' ||
        v_short_count || ' repeated-line product(s) short on stock: ' ||
        array_to_string(v_stock_warnings, ' | ') ||
        '. Completion proceeded; on-hand inventory went negative — review with the warehouse.',
      v_actor,
      'delivery',
      p_delivery_id,
      v_delivery.customer_id
    );

    FOR v_admin IN
      SELECT id
        FROM public.profiles
       WHERE role = 'admin'
         AND is_active = true
    LOOP
      INSERT INTO public.notifications (
        user_id,
        title,
        message,
        notification_type,
        related_entity_type,
        related_entity_id
      ) VALUES (
        v_admin.id,
        'Short Stock — Delivery ' || v_delivery.delivery_number,
        'Delivery ' || v_delivery.delivery_number || ' was completed but ' ||
          v_short_count || ' repeated-line product(s) exceeded aggregate on-hand stock: ' ||
          array_to_string(v_stock_warnings, ' | ') ||
          '. The completion proceeded and inventory went negative; please review.',
        'stock_warning',
        'delivery',
        p_delivery_id
      );
    END LOOP;

    v_result := v_result || jsonb_build_object(
      'stock_warning', true,
      'short_stock_count',
        COALESCE((v_result->>'short_stock_count')::integer, 0) + v_short_count,
      'warnings',
        COALESCE(v_result->'warnings', '[]'::jsonb) || to_jsonb(v_stock_warnings)
    );

    IF p_idempotency_key IS NOT NULL THEN
      UPDATE public.idempotency_keys
         SET result = v_result
       WHERE idempotency_key = p_idempotency_key
         AND operation = 'complete_delivery';
    END IF;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."_complete_delivery_period_preflight_impl"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid", "p_quantities" "jsonb", "p_issue_type" "text", "p_issue_notes" "text", "p_idempotency_key" "text", "p_completed_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_complete_delivery_period_preflight_impl"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid", "p_quantities" "jsonb", "p_issue_type" "text", "p_issue_notes" "text", "p_idempotency_key" "text", "p_completed_at" timestamp with time zone) IS 'Internal delivery completion wrapper. Direct execution is revoked; use public.complete_delivery so period rejection happens before legacy warning work.';



CREATE OR REPLACE FUNCTION "public"."_create_split_invoices_from_order_provenance_impl_20260719"("p_order_id" "uuid", "p_salesman_id" "uuid" DEFAULT NULL::"uuid", "p_invoice_type" "text" DEFAULT 'chemical_sale'::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_existing text;
  v_order record;
  v_has_alloc boolean := false;
  v_existing_count int;
  v_delivery_count int;
  v_group_id uuid;
  v_invoice_id uuid;
  v_invoice_ids uuid[] := '{}';
  v_item record;
  v_alloc record;
  v_cust record;
  v_line_cents bigint;
  v_total_acres numeric;
  v_acre_pcts numeric[];
  v_field_cents bigint[];
  v_field_idx int;
  v_owner_ids uuid[];
  v_owner_pcts numeric[];
  v_owner_cents bigint[];
  v_owner_acres numeric;
  v_sum_pct numeric;
  v_oidx int;
  v_total_cents bigint;
  -- per-(customer, line) contribution accumulator; aggregated in pass 2.
  v_rows jsonb := '[]'::jsonb;
BEGIN
  -- Authorization (mirror create_invoice_from_order): creating invoices is admin/sales_rep only.
  -- The old split path was unreachable (quote_sections.field_id was never persisted), so it had
  -- no gate; making it reachable means it MUST gate here or any authenticated user (driver/applicator)
  -- could mint invoices via this SECURITY DEFINER RPC (Codex P1).
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'Not authorized: admin or sales role required to create invoices from orders';
  END IF;

  -- Lock the order FIRST (mirror create_invoice_from_order's Codex-P1 lock): serializes against a
  -- concurrent delivery/invoice insert AND against a same-key retry, so the idempotency replay below
  -- runs only after any in-flight first call on this order has committed.
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found: %', p_order_id; END IF;

  -- Canonical operation-scoped idempotency replay, AFTER the order lock (draw_down_quote 2026-06-10
  -- pattern): a racing same-key retry blocks on the lock above, then resumes here and returns the
  -- cached invoice ids — instead of missing the still-uncommitted row pre-lock and then falsely
  -- erroring on the active-invoice guard below (Codex round-3 P2). result is a jsonb string; #>>'{}'
  -- extracts the bare "id1,id2" text so string_to_array sees no surrounding quotes.
  IF p_idempotency_key IS NOT NULL THEN
    SELECT result #>> '{}' INTO v_existing FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'create_split_invoices_from_order';
    IF v_existing IS NOT NULL THEN RETURN string_to_array(v_existing, ',')::uuid[]; END IF;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM order_item_field_allocations oifa
    JOIN order_items oi ON oi.id = oifa.order_item_id
    WHERE oi.order_id = p_order_id
  ) INTO v_has_alloc;

  -- No per-line field allocations anywhere on this order -> single invoice (unchanged).
  IF NOT v_has_alloc THEN
    v_invoice_id := create_invoice_from_order(p_order_id, p_salesman_id, p_invoice_type, p_idempotency_key);
    RETURN ARRAY[v_invoice_id];
  END IF;

  -- The split path inserts invoices DIRECTLY (the single-invoice path above delegates to
  -- create_invoice_from_order, which carries these guards). Replicate them so an allocated order
  -- that already has an active invoice or an active delivery cannot be double-billed (Codex P1).
  SELECT COUNT(*) INTO v_existing_count FROM invoices
    WHERE order_id = p_order_id AND status NOT IN ('voided', 'cancelled');
  IF v_existing_count > 0 THEN
    RAISE EXCEPTION 'Active invoice already exists for order % (% existing invoice(s)). Void or cancel the existing invoice first if you need to recreate.', v_order.order_number, v_existing_count;
  END IF;
  SELECT COUNT(*) INTO v_delivery_count FROM deliveries
    -- U7 SAFE-SCOPE (#43): only an OPEN (scheduled/in_progress) delivery blocks now;
    -- a COMPLETED delivery on a field/acre-allocated order left NO auto-draft to
    -- double against (complete_delivery skipped the mono-bill), so the split can run.
    WHERE order_id = p_order_id AND status IN ('scheduled', 'in_progress');
  IF v_delivery_count > 0 THEN
    RAISE EXCEPTION 'Cannot create an order-level invoice for order % — it has % active delivery(ies); invoices are created per delivery on completion. Cancel/void those deliveries first to bill the whole order manually.', v_order.order_number, v_delivery_count;
  END IF;

  -- U7 SAFE-SCOPE (#43, refined R3 P2): this engine bills the WHOLE order (off
  -- order_items.total_price). Block ONLY the partial-delivery-in-progress case — a
  -- delivery has COMPLETED but product still remains — where whole-order billing would
  -- bill undelivered product. A PRE-delivery order (no completed delivery) can still be
  -- invoiced up front (invoice-on-order, like create_invoice_from_order), and a fully
  -- delivered order passes. (Per-delivery split billing would be a larger redesign.)
  IF EXISTS (SELECT 1 FROM deliveries WHERE order_id = p_order_id AND status = 'completed')
     AND EXISTS (SELECT 1 FROM order_items WHERE order_id = p_order_id AND COALESCE(quantity_remaining, 0) > 0) THEN
    RAISE EXCEPTION 'Order % is partially delivered — split invoicing bills the whole order and would bill undelivered product. Finish delivering (or void the open deliveries) first.', v_order.order_number;
  END IF;

  -- Split-by-acre needs real line prices: a price-pending order would allocate $0 across fields
  -- (meaningless) and price_order cannot re-split a multi-customer invoice, so the single-invoice
  -- path's "create $0 drafts, sweep later" does not transfer here. Reject EXPLICITLY rather than
  -- silently produce no invoice (Codex round-2 P2). Price the order first, then split.
  IF EXISTS (SELECT 1 FROM order_items WHERE order_id = p_order_id AND pricing_pending) THEN
    RAISE EXCEPTION 'PRICING_INCOMPLETE: price the order before generating split invoices';
  END IF;

  -- PASS 1: compute every (customer, line) cents + prorated qty into v_rows.
  FOR v_item IN
    SELECT * FROM order_items WHERE order_id = p_order_id ORDER BY sort_order NULLS LAST, id
  LOOP
    v_line_cents := round(v_item.total_price * 100)::bigint;

    IF NOT EXISTS (SELECT 1 FROM order_item_field_allocations WHERE order_item_id = v_item.id) THEN
      -- Unallocated line: bill the whole line (incl. its full acres) to the order's own customer.
      v_rows := v_rows || jsonb_build_object(
        'c', v_order.customer_id, 'oi', v_item.id,
        'cents', v_line_cents, 'qty', COALESCE(v_item.total_units_needed, 0),
        'acres', COALESCE(v_item.acres, 0));
      CONTINUE;
    END IF;

    -- Split the line across its fields BY ACRES (stable order = field_id).
    SELECT sum(acres) INTO v_total_acres
      FROM order_item_field_allocations WHERE order_item_id = v_item.id;
    SELECT array_agg(acres / v_total_acres * 100 ORDER BY field_id) INTO v_acre_pcts
      FROM order_item_field_allocations WHERE order_item_id = v_item.id;
    v_field_cents := calculate_billing_splits(v_line_cents, v_acre_pcts);

    v_field_idx := 0;
    FOR v_alloc IN
      SELECT field_id, acres FROM order_item_field_allocations
      WHERE order_item_id = v_item.id ORDER BY field_id
    LOOP
      v_field_idx := v_field_idx + 1;

      -- Owners of this field, or fall back to the field's own customer at 100%.
      IF EXISTS (SELECT 1 FROM field_billing_defaults WHERE field_id = v_alloc.field_id) THEN
        SELECT array_agg(customer_id ORDER BY customer_id),
               array_agg(split_pct ORDER BY customer_id),
               sum(split_pct)
          INTO v_owner_ids, v_owner_pcts, v_sum_pct
          FROM field_billing_defaults WHERE field_id = v_alloc.field_id;
        IF v_sum_pct < 99.99 OR v_sum_pct > 100.01 THEN
          RAISE EXCEPTION 'FIELD_SPLIT_NOT_100: field % billing splits total % (must equal 100)',
            v_alloc.field_id, v_sum_pct;
        END IF;
        -- Normalize to sum EXACTLY 100 (order-preserving) so calculate_billing_splits — which assumes
        -- the percentages total 100 — cannot over-allocate within the tolerance band, e.g. 50.01+50.00
        -- would otherwise floor to MORE than the field's cents (Codex P2). v_owner_ids stays aligned.
        SELECT array_agg(p / v_sum_pct * 100 ORDER BY ord)
          INTO v_owner_pcts FROM unnest(v_owner_pcts) WITH ORDINALITY AS u(p, ord);
      ELSE
        SELECT ARRAY[customer_id] INTO v_owner_ids FROM fields WHERE id = v_alloc.field_id;
        v_owner_pcts := ARRAY[100::numeric];
      END IF;

      -- Split this field's portion among its owners BY split_pct (penny-exact).
      v_owner_cents := calculate_billing_splits(v_field_cents[v_field_idx], v_owner_pcts);

      FOR v_oidx IN 1..array_length(v_owner_ids, 1) LOOP
        -- This owner's slice of THIS field = field acres * their normalized pct. Bill that many
        -- acres to them (so split invoice items carry PRORATED acres, not the line's full acres —
        -- otherwise year-end/RUP acre reports double-count; Codex round-5 P2). qty is prorated by the
        -- same acre-share: well-defined even for a $0 line (v_total_acres > 0 for any allocated line)
        -- and it sums back to the line's total qty across owners.
        v_owner_acres := v_alloc.acres * v_owner_pcts[v_oidx] / 100;
        v_rows := v_rows || jsonb_build_object(
          'c', v_owner_ids[v_oidx], 'oi', v_item.id,
          'cents', v_owner_cents[v_oidx],
          'acres', round(v_owner_acres, 4),
          'qty', round(COALESCE(v_item.total_units_needed, 0) * v_owner_acres / v_total_acres, 4));
      END LOOP;
    END LOOP;
  END LOOP;

  -- A customer whose allocated subtotal is NEGATIVE (a discount line allocated to them exceeds their
  -- charges) cannot become a non-negative invoice; silently skipping them (the outer HAVING > 0 below)
  -- would make the OTHER customers' invoices over-sum the order total — breaking the penny-exact
  -- reconciliation guarantee. Fail loudly instead of mis-billing (Codex round-6 P2). A net-ZERO customer
  -- is safe to skip (contributes 0, reconciliation still holds); only a strictly-negative net is rejected.
  IF EXISTS (
    SELECT 1 FROM jsonb_to_recordset(v_rows) AS x(c uuid, oi uuid, cents bigint, qty numeric, acres numeric)
    GROUP BY x.c HAVING sum(x.cents) < 0
  ) THEN
    RAISE EXCEPTION 'SPLIT_NET_NEGATIVE: a customer''s allocated subtotal is negative — cannot create split invoices (adjust the discount/allocation or issue a credit memo)';
  END IF;

  -- PASS 2: one invoice per customer, from the accumulated contributions.
  v_group_id := gen_random_uuid();

  FOR v_cust IN
    SELECT x.c AS customer_id, sum(x.cents) AS cust_total
    FROM jsonb_to_recordset(v_rows) AS x(c uuid, oi uuid, cents bigint, qty numeric)
    GROUP BY x.c
    HAVING sum(x.cents) > 0
    ORDER BY x.c
  LOOP
    INSERT INTO invoices (order_id, customer_id, invoice_type, status, season, salesman_id,
      created_by, total_amount_cents, invoice_date, invoice_group_id, header_notes)
    VALUES (p_order_id, v_cust.customer_id, p_invoice_type, 'draft',
      COALESCE(v_order.season, current_season()),
      COALESCE(p_salesman_id, v_order.salesman_id), auth.uid(), 0, CURRENT_DATE, v_group_id,
      'Split invoice (by field/acre) from order ' || v_order.order_number)
    RETURNING id INTO v_invoice_id;

    v_total_cents := 0;
    FOR v_item IN
      SELECT oi.*, agg.cents AS cust_cents, agg.qty AS cust_qty, agg.acres AS cust_acres
      FROM (
        SELECT x.oi AS order_item_id, sum(x.cents)::bigint AS cents, sum(x.qty) AS qty, sum(x.acres) AS acres
        FROM jsonb_to_recordset(v_rows) AS x(c uuid, oi uuid, cents bigint, qty numeric, acres numeric)
        WHERE x.c = v_cust.customer_id
        GROUP BY x.oi
        -- Keep a line on the invoice if the customer has ANY contribution to it: non-zero cents
        -- (incl. a negative discount line, so the total reconciles to their net — Codex round-4 P2),
        -- OR non-zero qty/acres (so a legitimate $0 / no-charge product line still carries its product,
        -- quantity and acres for the PDF and year-end usage reports, matching create_invoice_from_order
        -- — Codex round-5 P2). The per-customer (outer) HAVING > 0 still gates which customers get a
        -- (CHECK-non-negative) invoice; a customer whose net is <= 0 is skipped (v1 — a net credit /
        -- a $0-only allocation would need a credit_memo / explicit $0 invoice, out of scope).
        HAVING sum(x.cents) <> 0 OR sum(x.qty) <> 0 OR sum(x.acres) <> 0
      ) agg
      JOIN order_items oi ON oi.id = agg.order_item_id
      ORDER BY oi.sort_order NULLS LAST, oi.id
    LOOP
      INSERT INTO invoice_items (invoice_id, order_item_id, product_id, description, quantity,
        unit_price_cents, extended_cents, cost_cents, sort_order, rate_per_acre, acres, unit_size)
      VALUES (v_invoice_id, v_item.id, v_item.product_id, COALESCE(v_item.product_name, ''),
        v_item.cust_qty, round(v_item.price_per_unit * 100)::bigint, v_item.cust_cents,
        round(v_item.cost_per_unit * 100)::bigint, COALESCE(v_item.sort_order, 0),
        v_item.actual_rate, v_item.cust_acres, v_item.unit_size);
      v_total_cents := v_total_cents + v_item.cust_cents;
    END LOOP;

    UPDATE invoices SET total_amount_cents = v_total_cents WHERE id = v_invoice_id;

    INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_role,
      new_values, total_impact_cents, description)
    VALUES ('invoice_created', 'invoice', v_invoice_id,
      COALESCE((SELECT role FROM profiles WHERE id = auth.uid()), 'admin'),
      jsonb_build_object('order_number', v_order.order_number, 'group_id', v_group_id,
        'split_basis', 'field_acre'),
      v_total_cents, 'Split invoice (by field/acre) from order ' || v_order.order_number);

    v_invoice_ids := v_invoice_ids || v_invoice_id;
  END LOOP;

  INSERT INTO activity_feed (event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id)
  VALUES ('split_invoices_created',
    COALESCE(array_length(v_invoice_ids, 1), 0) || ' split invoices from order ' || v_order.order_number,
    auth.uid(), 'order', p_order_id, v_order.customer_id);

  -- U7 SAFE-SCOPE (#43): the order is now split-billed per-owner — clear the
  -- "needs split billing" queue flag complete_delivery set when it skipped the mono-bill.
  UPDATE orders SET needs_split_billing = false, updated_at = now() WHERE id = p_order_id;

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'create_split_invoices_from_order',
      to_jsonb(array_to_string(v_invoice_ids, ',')));
  END IF;

  RETURN v_invoice_ids;
END;
$_$;


ALTER FUNCTION "public"."_create_split_invoices_from_order_provenance_impl_20260719"("p_order_id" "uuid", "p_salesman_id" "uuid", "p_invoice_type" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_delete_invoices_split_provenance_impl_20260719"("p_invoice_ids" "uuid"[], "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_inv        record;
  v_count      integer := 0;
  v_actor      uuid;
  v_actor_role text;
  v_existing   jsonb;
BEGIN
  PERFORM require_admin();  -- admin-only: matches invoices_update/invoices_delete RLS (is_admin())
  PERFORM check_rate_limit(auth.uid(), 'delete_invoices', 5, 60);
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'delete_invoices');
    IF v_existing IS NOT NULL THEN RETURN (v_existing->>'deleted_count')::integer; END IF;
  END IF;

  IF array_length(p_invoice_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'No invoice IDs provided';
  END IF;

  FOR v_inv IN
    SELECT id, status, invoice_number, total_amount_cents, blend_ticket_id,
           invoice_type, job_id  -- U8 (Codex R3 P1): job-born invoice cleanup below
    FROM invoices
    WHERE id = ANY(p_invoice_ids) AND deleted_at IS NULL
    ORDER BY id
    FOR UPDATE
  LOOP
    -- Only draft / unposted / voided invoices are soft-deletable (matches the UI gates).
    IF v_inv.status NOT IN ('draft', 'unposted', 'voided') THEN CONTINUE; END IF;

    -- CREDIT-APPLY: never soft-delete an invoice that still has an active credit application on
    -- either side (would strand the ledger). Void reverses applications first, so a voided
    -- invoice reaching here is already clean; this is a belt-and-suspenders guard.
    IF EXISTS (
      SELECT 1 FROM credit_memo_applications
       WHERE reversed_at IS NULL
         AND (credit_memo_id = v_inv.id OR target_invoice_id = v_inv.id)
    ) THEN
      RAISE EXCEPTION 'INVOICE_HAS_ACTIVE_CREDIT_APPLICATIONS: reverse the credit application on % first', v_inv.invoice_number;
    END IF;

    UPDATE invoices SET deleted_at = now() WHERE id = v_inv.id;

    IF v_inv.blend_ticket_id IS NOT NULL THEN
      UPDATE blend_tickets SET payment_status = 'unbilled', updated_at = now()
      WHERE id = v_inv.blend_ticket_id AND payment_status = 'billed'
        AND NOT EXISTS (
          SELECT 1 FROM invoices i
          WHERE i.blend_ticket_id = v_inv.blend_ticket_id
            AND i.status NOT IN ('voided', 'cancelled')
            AND i.deleted_at IS NULL
        );
    END IF;

    IF v_inv.invoice_type = 'field_application' AND v_inv.job_id IS NOT NULL THEN
      IF EXISTS (
        SELECT 1 FROM commissions c
        JOIN commission_payment_items cpi ON cpi.commission_id = c.id
        JOIN commission_payments cp ON cp.id = cpi.commission_payment_id
        WHERE c.job_id = v_inv.job_id AND c.invoice_id = v_inv.id
          AND c.status = 'pending' AND cp.status <> 'voided'
      ) THEN
        RAISE EXCEPTION 'JOB_HAS_BATCHED_COMMISSIONS: invoice % has pending commissions in an active payout batch — void that commission payment first', v_inv.invoice_number;
      END IF;
      IF EXISTS (
        SELECT 1 FROM commissions
        WHERE job_id = v_inv.job_id AND invoice_id = v_inv.id AND status = 'paid'
      ) THEN
        INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
        SELECT p.id, 'Job invoice deleted — commissions already paid',
          'Invoice ' || v_inv.invoice_number || ' was deleted but its commissions were already paid out. Manual review needed before the job is re-invoiced.',
          'commission_review', 'invoice', v_inv.id
        FROM profiles p WHERE p.role = 'admin' AND p.is_active = true;
      END IF;
      UPDATE commissions SET status = 'cancelled', commission_amount = 0
        WHERE job_id = v_inv.job_id AND invoice_id = v_inv.id AND status = 'pending';

      DECLARE
        v_job record;
      BEGIN
        SELECT * INTO v_job FROM jobs WHERE id = v_inv.job_id FOR UPDATE;
        IF FOUND AND v_job.status = 'invoiced' THEN
          IF EXISTS (SELECT 1 FROM invoices o
                     WHERE o.job_id = v_inv.job_id AND o.id <> v_inv.id
                       AND o.invoice_type = 'field_application'
                       AND o.status NOT IN ('voided', 'cancelled') AND o.deleted_at IS NULL) THEN
            IF v_job.invoice_id IS NOT DISTINCT FROM v_inv.id THEN
              UPDATE application_records SET invoice_id = (
                SELECT o.id FROM invoices o
                 WHERE o.job_id = v_inv.job_id AND o.id <> v_inv.id
                   AND o.invoice_type = 'field_application'
                   AND o.status NOT IN ('voided', 'cancelled') AND o.deleted_at IS NULL
                 ORDER BY o.created_at, o.id LIMIT 1)
                WHERE source_type = 'job' AND source_id = v_inv.job_id AND invoice_id = v_inv.id;
              SET LOCAL app.admin_override = 'true';
              UPDATE jobs SET invoice_id = (
                SELECT o.id FROM invoices o
                 WHERE o.job_id = v_inv.job_id AND o.id <> v_inv.id
                   AND o.invoice_type = 'field_application'
                   AND o.status NOT IN ('voided', 'cancelled') AND o.deleted_at IS NULL
                 ORDER BY o.created_at, o.id LIMIT 1)
                WHERE id = v_inv.job_id;
              RESET app.admin_override;
            END IF;
          ELSE
            UPDATE application_records SET invoice_id = NULL
              WHERE source_type = 'job' AND source_id = v_inv.job_id AND invoice_id = v_inv.id;
            SET LOCAL app.admin_override = 'true';
            UPDATE jobs SET status = 'completed', invoice_id = NULL WHERE id = v_inv.job_id;
            RESET app.admin_override;
          END IF;
        END IF;
      END;
    END IF;

    INSERT INTO financial_audit_log (
      operation_type, entity_type, entity_id, actor_role,
      old_values, new_values, total_impact_cents, description
    ) VALUES (
      'invoice_deleted', 'invoice', v_inv.id, v_actor_role,
      jsonb_build_object(
        'status', v_inv.status,
        'invoice_number', v_inv.invoice_number,
        'total_amount_cents', v_inv.total_amount_cents
      ),
      jsonb_build_object('deleted_at', now()),
      0,
      'Soft-deleted invoice ' || v_inv.invoice_number || ' (status ' || v_inv.status || ')'
    );

    v_count := v_count + 1;
  END LOOP;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'delete_invoices', jsonb_build_object('deleted_count', v_count));
  END IF;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."_delete_invoices_split_provenance_impl_20260719"("p_invoice_ids" "uuid"[], "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_allocation_not_over_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.total_allocated_cents IS NOT NULL
     AND NEW.total_payment_cents IS NOT NULL
     AND NEW.total_allocated_cents > NEW.total_payment_cents THEN
    RAISE EXCEPTION 'ALLOCATIONS_EXCEED_PAYMENT: allocated % exceeds payment % (allocation_set %)',
      NEW.total_allocated_cents, NEW.total_payment_cents, NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_enforce_allocation_not_over_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_applicator_license"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_has_licenses boolean;
  v_latest_expiry date;
BEGIN
  IF NEW.applicator_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.applicator_id IS NOT DISTINCT FROM OLD.applicator_id THEN
    RETURN NEW;
  END IF;
  IF _is_admin_override() THEN
    RETURN NEW;
  END IF;

  SELECT count(*) > 0, max(expiry_date)
    INTO v_has_licenses, v_latest_expiry
    FROM applicator_licenses
   WHERE profile_id = NEW.applicator_id
     AND is_active = true;

  IF NOT v_has_licenses THEN
    RETURN NEW;
  END IF;

  IF v_latest_expiry < CURRENT_DATE THEN
    RAISE EXCEPTION 'LICENSE_EXPIRED: applicator license expired %', v_latest_expiry;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_enforce_applicator_license"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_billed_job_applied_record_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_parent_record_id uuid;
  v_job_status text;
  v_job_number text;
  v_parent_xmin xid;
BEGIN
  -- Resolve the parent job's status + (for child tables) parent record's xmin.
  -- For the parent table (job_applied_records), OLD.job_id (UPDATE/DELETE) or
  -- NEW.job_id (INSERT — not gated here) points to the job. For child tables
  -- (_fields, _crew), walk via application_record_id → job_applied_records → jobs.
  IF TG_TABLE_NAME = 'job_applied_records' THEN
    SELECT status, job_number INTO v_job_status, v_job_number
      FROM public.jobs WHERE id = OLD.job_id;
  ELSE
    -- For child tables we also need the parent's xmin (PARKED-005 r3) so the
    -- INSERT path can distinguish "child of a record being created in this
    -- transaction" from "child added to old billed history".
    v_parent_record_id := COALESCE(
      CASE TG_OP WHEN 'DELETE' THEN OLD.application_record_id
                 ELSE NEW.application_record_id END,
      OLD.application_record_id
    );
    SELECT j.status, j.job_number, r.xmin INTO v_job_status, v_job_number, v_parent_xmin
      FROM public.job_applied_records r
      JOIN public.jobs j ON j.id = r.job_id
      WHERE r.id = v_parent_record_id;
  END IF;

  -- Parent missing (cascade race) — let the row through; the underlying FK / RLS will
  -- settle it. We're only the billed-status guard.
  IF v_job_status IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  -- Only billed/terminal jobs are immutable.
  IF v_job_status NOT IN ('invoiced', 'cancelled') THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  -- PARKED-005 r3: child INSERT is allowed IFF the parent applied_record was
  -- created in THIS transaction (age(xmin)=0 — same Postgres xid). Distinguishes
  -- "the standard save_job_applied_record NEW-record path" (parent + children
  -- INSERTed in one txn, parent xmin matches current) from "raw-REST tampering
  -- adding fields to old billed history" (parent xmin is an older txn).
  IF TG_OP = 'INSERT' AND TG_TABLE_NAME IN ('job_applied_record_fields', 'job_applied_record_crew') THEN
    IF age(v_parent_xmin) = 0 THEN
      RETURN NEW;  -- parent created in this txn — legitimate post-billing record
    END IF;
    -- fall through to admin / override check, then REJECT below
  END IF;

  -- Admins may correct billed history; the SECURITY DEFINER override hatch is honored
  -- so sanctioned server-side flows (e.g. a future transfer_invoice_to_job reversal
  -- that needs to clean up applied detail) still work.
  IF is_admin() OR _is_admin_override() THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  -- PARKED-005 (Codex r1): EXEMPT the recompute-only UPDATE on job_applied_records.
  -- settle_applied_record_acres (AFTER INSERT trg_jarf_recompute) UPDATEs only
  -- applied_acres on this table to SUM(child.applied_acres); that path is the
  -- "record after billing" intent. To exempt the recompute WITHOUT opening a
  -- tampering window:
  --   (a) NEW.applied_acres must equal the current child-sum exactly (so a user
  --       arbitrary value like 9999 is still rejected — only the recompute's
  --       computed sum slips through), AND
  --   (b) every OTHER non-generated column is unchanged (mirrors the jobs
  --       immutability exempt list pattern: created_at/id/created_by frozen,
  --       updated_at handled by the set_updated_at BEFORE trigger which fires
  --       AFTER ours, so OLD.updated_at = NEW.updated_at at this point).
  -- Children (_fields, _crew) have no analogous rollup → this exempt is parent-only.
  IF TG_OP = 'UPDATE' AND TG_TABLE_NAME = 'job_applied_records' THEN
    DECLARE v_child_sum numeric;
    BEGIN
      SELECT COALESCE(SUM(applied_acres), 0) INTO v_child_sum
        FROM public.job_applied_record_fields
        WHERE application_record_id = NEW.id;

      IF NEW.applied_acres IS DISTINCT FROM OLD.applied_acres
         AND NEW.applied_acres IS NOT DISTINCT FROM v_child_sum
         AND NEW.job_id              IS NOT DISTINCT FROM OLD.job_id
         AND NEW.applicator_id       IS NOT DISTINCT FROM OLD.applicator_id
         AND NEW.vehicle_id          IS NOT DISTINCT FROM OLD.vehicle_id
         AND NEW.application_date    IS NOT DISTINCT FROM OLD.application_date
         AND NEW.notes               IS NOT DISTINCT FROM OLD.notes
         AND NEW.start_weather_time  IS NOT DISTINCT FROM OLD.start_weather_time
         AND NEW.start_temp_f        IS NOT DISTINCT FROM OLD.start_temp_f
         AND NEW.start_wind_direction IS NOT DISTINCT FROM OLD.start_wind_direction
         AND NEW.start_wind_mph      IS NOT DISTINCT FROM OLD.start_wind_mph
         AND NEW.start_humidity_pct  IS NOT DISTINCT FROM OLD.start_humidity_pct
         AND NEW.start_weather_source IS NOT DISTINCT FROM OLD.start_weather_source
         AND NEW.end_weather_time    IS NOT DISTINCT FROM OLD.end_weather_time
         AND NEW.end_temp_f          IS NOT DISTINCT FROM OLD.end_temp_f
         AND NEW.end_wind_direction  IS NOT DISTINCT FROM OLD.end_wind_direction
         AND NEW.end_wind_mph        IS NOT DISTINCT FROM OLD.end_wind_mph
         AND NEW.end_humidity_pct    IS NOT DISTINCT FROM OLD.end_humidity_pct
         AND NEW.end_weather_source  IS NOT DISTINCT FROM OLD.end_weather_source
         AND NEW.beginning_tach      IS NOT DISTINCT FROM OLD.beginning_tach
         AND NEW.end_tach            IS NOT DISTINCT FROM OLD.end_tach
         AND NEW.created_by          IS NOT DISTINCT FROM OLD.created_by
         AND NEW.id                  IS NOT DISTINCT FROM OLD.id
         AND NEW.created_at          IS NOT DISTINCT FROM OLD.created_at
      THEN
        RETURN NEW;  -- recompute-only update matching child-sum — preserve "record after billing"
      END IF;
    END;
  END IF;

  -- Non-admin, billed job, no override → REJECT.
  RAISE EXCEPTION
    'A % job''s applied-record (or its child rows) is billed history and cannot be % by a non-admin (job %).',
    v_job_status, lower(TG_OP), v_job_number
    USING ERRCODE = 'check_violation';
END;
$$;


ALTER FUNCTION "public"."_enforce_billed_job_applied_record_immutability"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_enforce_billed_job_applied_record_immutability"() IS 'PARKED-005 (codex-driven cycle 3 #3): extends billed-job immutability to job_applied_records + its child tables (_fields, _crew). For a non-admin without the app.admin_override hatch, UPDATE or DELETE on an applied-record belonging to an invoiced/cancelled job RAISES. INSERT is allowed (preserves the "record after billing" intent of migration 20260625190000). Sibling of _enforce_billed_job_immutability.';



CREATE OR REPLACE FUNCTION "public"."_enforce_billed_job_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only billed/terminal jobs are immutable. A live job edits exactly as before.
  IF OLD.status NOT IN ('invoiced', 'cancelled') THEN
    RETURN NEW;
  END IF;

  -- Admins may correct billed history; the definer-flow override hatch (set by
  -- SECURITY DEFINER RPCs via SET LOCAL app.admin_override='true') is honored so
  -- sanctioned server-side flows (e.g. transfer_invoice_to_job) still work.
  IF is_admin() OR _is_admin_override() THEN
    RETURN NEW;
  END IF;

  -- (a) Most severe hole: block a non-admin soft-delete of a billed job.
  IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'A % job is billed history and cannot be deleted by a non-admin (job %).',
      OLD.status, OLD.job_number
      USING ERRCODE = 'check_violation';
  END IF;

  -- (b) Block a non-admin rewrite of any billed-relevant column. Allow the row
  -- through only when every NON-exempt column is unchanged. New columns are
  -- protected by default (they are not in the exempt set below).
  IF NOT (
       NEW.id                     IS NOT DISTINCT FROM OLD.id
   AND NEW.job_number             IS NOT DISTINCT FROM OLD.job_number
   AND NEW.customer_id            IS NOT DISTINCT FROM OLD.customer_id
   AND NEW.job_date               IS NOT DISTINCT FROM OLD.job_date
   AND NEW.scheduled_time         IS NOT DISTINCT FROM OLD.scheduled_time
   AND NEW.applicator_id          IS NOT DISTINCT FROM OLD.applicator_id
   AND NEW.vehicle_id             IS NOT DISTINCT FROM OLD.vehicle_id
   AND NEW.recipe_id              IS NOT DISTINCT FROM OLD.recipe_id
   AND NEW.notes                  IS NOT DISTINCT FROM OLD.notes
   AND NEW.tags                   IS NOT DISTINCT FROM OLD.tags
   AND NEW.batch_id               IS NOT DISTINCT FROM OLD.batch_id
   AND NEW.season                 IS NOT DISTINCT FROM OLD.season
   AND NEW.total_acres            IS NOT DISTINCT FROM OLD.total_acres
   AND NEW.total_cost_cents       IS NOT DISTINCT FROM OLD.total_cost_cents
   AND NEW.total_price_cents      IS NOT DISTINCT FROM OLD.total_price_cents
   AND NEW.created_by             IS NOT DISTINCT FROM OLD.created_by
   AND NEW.deleted_at             IS NOT DISTINCT FROM OLD.deleted_at
   AND NEW.created_at             IS NOT DISTINCT FROM OLD.created_at
   AND NEW.priority               IS NOT DISTINCT FROM OLD.priority
   AND NEW.estimated_hours        IS NOT DISTINCT FROM OLD.estimated_hours
   AND NEW.quote_id               IS NOT DISTINCT FROM OLD.quote_id
   AND NEW.quote_section_id       IS NOT DISTINCT FROM OLD.quote_section_id
   AND NEW.application_service_id IS NOT DISTINCT FROM OLD.application_service_id
   AND NEW.call_date              IS NOT DISTINCT FROM OLD.call_date
   AND NEW.date_proposed          IS NOT DISTINCT FROM OLD.date_proposed
   AND NEW.time_proposed          IS NOT DISTINCT FROM OLD.time_proposed
   AND NEW.schedule_date          IS NOT DISTINCT FROM OLD.schedule_date
   AND NEW.date_expires           IS NOT DISTINCT FROM OLD.date_expires
   AND NEW.consultant_id          IS NOT DISTINCT FROM OLD.consultant_id
   AND NEW.loader_comment         IS NOT DISTINCT FROM OLD.loader_comment
   AND NEW.additional_info        IS NOT DISTINCT FROM OLD.additional_info
   AND NEW.internal_memo          IS NOT DISTINCT FROM OLD.internal_memo
   AND NEW.ground_crew_id         IS NOT DISTINCT FROM OLD.ground_crew_id
   AND NEW.batch_ref              IS NOT DISTINCT FROM OLD.batch_ref
   AND NEW.carrier_rate_gpa       IS NOT DISTINCT FROM OLD.carrier_rate_gpa
   AND NEW.loader_tank_capacity   IS NOT DISTINCT FROM OLD.loader_tank_capacity
   -- P1 remediation: invoice_id is NOW protected (was exempt). A non-admin can
   -- no longer detach (->NULL) or repoint a billed job's invoice via direct PATCH.
   -- The two legitimate writers still pass: transfer_job_to_invoice writes it on a
   -- 'completed' job (guard early-returns), transfer_invoice_to_job clears it under
   -- the admin_override hatch (early-returns above the column check).
   AND NEW.invoice_id             IS NOT DISTINCT FROM OLD.invoice_id
   -- EXEMPT (intentionally NOT checked — see header): status, deleted_at*,
   -- applied_acres, remaining_acres (GENERATED), printed_at, last_printed_by,
   -- updated_at, updated_by.
   -- (*deleted_at's NULL->non-NULL case is already blocked above; an unchanged
   --  value passes the IS NOT DISTINCT FROM check we DO run on it.)
  ) THEN
    RAISE EXCEPTION 'A % job is billed history; a non-admin cannot edit its billed-relevant fields (job %).',
      OLD.status, OLD.job_number
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_enforce_billed_job_immutability"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_enforce_billed_job_immutability"() IS 'Field-app parity #12 (+P1 invoice_id remediation): DB guard for billed-history immutability. For a non-admin (and without the app.admin_override hatch), an invoiced/cancelled job cannot be soft-deleted (deleted_at NULL->non-NULL) nor have its billed-relevant columns rewritten — INCLUDING invoice_id (a non-admin can no longer detach or repoint a billed job''s invoice). Exempt: status (status-enforcer), applied_acres (recompute), printed_at/last_printed_by (print audit), updated_at/updated_by. Admins and sanctioned SECURITY DEFINER flows (override hatch) are unaffected.';



CREATE OR REPLACE FUNCTION "public"."_enforce_delivery_items_parent_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_status text;
BEGIN
  IF _is_admin_override() THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    SELECT status INTO v_status FROM deliveries WHERE id = OLD.delivery_id;
    IF v_status IS NOT NULL AND v_status <> 'scheduled' THEN
      RAISE EXCEPTION
        'DELIVERY_ITEMS_LOCKED: cannot % delivery items on a % delivery (items are editable only while scheduled)',
        lower(TG_OP), v_status;
    END IF;
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    SELECT status INTO v_status FROM deliveries WHERE id = NEW.delivery_id;
    IF v_status IS NOT NULL AND v_status <> 'scheduled' THEN
      RAISE EXCEPTION
        'DELIVERY_ITEMS_LOCKED: cannot % delivery items on a % delivery (items are editable only while scheduled)',
        lower(TG_OP), v_status;
    END IF;
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION "public"."_enforce_delivery_items_parent_lock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_delivery_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF _is_admin_override() THEN RETURN NEW; END IF;

  IF (OLD.status = 'scheduled' AND NEW.status IN ('in_progress', 'cancelled'))
  OR (OLD.status = 'in_progress' AND NEW.status IN ('completed', 'cancelled'))
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Invalid delivery status transition: % → %', OLD.status, NEW.status;
END;
$$;


ALTER FUNCTION "public"."_enforce_delivery_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_field_billing_defaults_sum_100"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_field_id uuid;
  v_row_count bigint;
  v_split_sum numeric;
BEGIN
  -- ONE global lock (constant key) for ALL field_billing_defaults constraint checks.
  -- A single lock key cannot form a deadlock cycle; and after the holding transaction
  -- commits, the waiter's fresh per-statement READ COMMITTED snapshot in the SELECT
  -- below sees the committed rows, so two concurrent inserts can't both pass at 200%.
  PERFORM pg_advisory_xact_lock(hashtext('field_billing_defaults_sum_100')::bigint);

  FOR v_field_id IN
    SELECT DISTINCT affected.field_id
    FROM (
      VALUES
        (CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.field_id END),
        (CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.field_id END)
    ) AS affected(field_id)
    WHERE affected.field_id IS NOT NULL
  LOOP
    SELECT count(*), COALESCE(sum(fbd.split_pct), 0)
      INTO v_row_count, v_split_sum
    FROM public.field_billing_defaults fbd
    WHERE fbd.field_id = v_field_id;

    -- Tolerance band 99.99–100.01 (matches transfer_job_to_invoice /
    -- create_split_invoices_from_order); split_pct is numeric(9,6) so a legit even
    -- 3-way split (33.333333*3 = 99.999999) must be accepted.
    IF v_row_count >= 1 AND (v_split_sum < 99.99 OR v_split_sum > 100.01) THEN
      RAISE EXCEPTION
        'FIELD_BILLING_SPLIT_NOT_100: field_id % has billing split sum %, expected 100 (within 99.99–100.01)',
        v_field_id,
        v_split_sum;
    END IF;
  END LOOP;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."_enforce_field_billing_defaults_sum_100"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_invoice_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF _is_admin_override() THEN RETURN NEW; END IF;

  IF (OLD.status = 'draft'    AND NEW.status IN ('unposted', 'posted', 'cancelled'))
  OR (OLD.status = 'unposted' AND NEW.status IN ('posted', 'cancelled'))
  OR (OLD.status = 'posted'   AND NEW.status IN ('voided', 'paid', 'overdue'))
  OR (OLD.status = 'overdue'  AND NEW.status IN ('paid', 'voided'))
  OR (OLD.status = 'paid'     AND NEW.status IN ('voided', 'posted', 'overdue'))
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Invalid invoice status transition: % → %', OLD.status, NEW.status;
END;
$$;


ALTER FUNCTION "public"."_enforce_invoice_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_job_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF _is_admin_override() THEN RETURN NEW; END IF;

  -- Cancel gate (overnight bug-hunt MED, 20260620): only allow cancel from a live
  -- source state, mirroring the order/delivery enforcers. A terminal completed/invoiced
  -- job must not be cancellable here (it would orphan its field_application invoice +
  -- application_records); the _is_admin_override() hatch above still permits a
  -- deliberate admin reversal.
  IF NEW.status = 'cancelled' AND OLD.status IN ('scheduled', 'in_progress') THEN RETURN NEW; END IF;

  IF (OLD.status = 'scheduled' AND NEW.status = 'in_progress')
  OR (OLD.status = 'in_progress' AND NEW.status = 'completed')
  OR (OLD.status = 'completed' AND NEW.status = 'invoiced')
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Invalid job status transition: % → %', OLD.status, NEW.status;
END;
$$;


ALTER FUNCTION "public"."_enforce_job_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_order_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF _is_admin_override() THEN RETURN NEW; END IF;

  IF (OLD.status = 'confirmed' AND NEW.status IN ('partially_fulfilled', 'fulfilled', 'cancelled'))
  OR (OLD.status = 'partially_fulfilled' AND NEW.status IN ('fulfilled', 'cancelled'))
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Invalid order status transition: % → %', OLD.status, NEW.status;
END;
$$;


ALTER FUNCTION "public"."_enforce_order_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_po_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF _is_admin_override() THEN RETURN NEW; END IF;

  -- Forward transitions
  IF (OLD.status = 'draft' AND NEW.status IN ('submitted', 'cancelled'))
  OR (OLD.status = 'submitted' AND NEW.status IN ('partially_received', 'fully_received', 'cancelled'))
  OR (OLD.status = 'partially_received' AND NEW.status IN ('fully_received', 'cancelled'))
  -- Reverse transitions (receiving reversals)
  OR (OLD.status = 'fully_received' AND NEW.status IN ('partially_received', 'submitted'))
  OR (OLD.status = 'partially_received' AND NEW.status = 'submitted')
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Invalid purchase order status transition: % → %', OLD.status, NEW.status;
END;
$$;


ALTER FUNCTION "public"."_enforce_po_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_quote_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF _is_admin_override() THEN RETURN NEW; END IF;

  -- U5 (Codex round-2 P2): a DIRECT status UPDATE to 'closed_short' (RLS lets
  -- admin/sales write quotes.status without the RPC) must honor the same
  -- active-jobs refusal as close_quote_as_short — otherwise the release trigger
  -- would drop this booking's holds while live jobs still expect to apply the
  -- product. The RPC passes this check trivially (it refuses first).
  -- NOTE (invoker-rights dependency): this EXISTS runs under the CALLER's jobs
  -- RLS. Safe today because everyone who passes quotes_update (admin / owning
  -- sales_rep) has UNFILTERED jobs SELECT. If jobs_select is ever row-scoped
  -- for sales_rep, this guard silently weakens — re-check then.
  IF NEW.status = 'closed_short' AND EXISTS (
    SELECT 1 FROM jobs
    WHERE quote_id = NEW.id AND deleted_at IS NULL
      AND status IN ('scheduled', 'in_progress')
  ) THEN
    RAISE EXCEPTION 'BOOKING_HAS_ACTIVE_JOBS: cancel or complete the booking''s scheduled/in-progress jobs before closing it as short';
  END IF;

  IF (OLD.status = 'draft' AND NEW.status IN ('sent', 'cancelled'))
  OR (OLD.status = 'sent' AND NEW.status IN ('revised', 'accepted', 'declined', 'expired', 'cancelled'))
  OR (OLD.status = 'revised' AND NEW.status IN ('sent', 'accepted', 'declined', 'expired', 'cancelled'))
  OR (OLD.status = 'accepted' AND NEW.status = 'sent')
  -- LAYER2<<< a booking we fulfilled by APPLYING product (job applications)
  -- closes to its own terminal status, distinct from 'accepted' (= convert-to-
  -- order, a chemical sale). Reachable only from an open booking. (owner 2026-07-03)
  OR (OLD.status IN ('sent', 'revised') AND NEW.status = 'closed_by_application')
  -- >>>LAYER2
  -- U5<<< a booking the customer ABANDONED (walked away / drew only part) closes
  -- to its own terminal 'closed_short', releasing the un-fulfilled remainder.
  -- Reachable only from an open booking, terminal (no outgoing edge). (#1)
  OR (OLD.status IN ('sent', 'revised') AND NEW.status = 'closed_short')
  -- >>>U5
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Invalid quote status transition: % → %', OLD.status, NEW.status;
END;
$$;


ALTER FUNCTION "public"."_enforce_quote_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_quote_terminal_not_drawn"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status IN ('declined', 'cancelled', 'expired')
     AND (
       -- order draws only exist on sent/revised bookings (baseline scope)
       (OLD.status IN ('sent', 'revised') AND EXISTS (
         SELECT 1 FROM quote_product_draws
         WHERE quote_id = NEW.id AND quantity_drawn > 0
       ))
       -- LAYER2<<< a job can be scheduled from a DRAFT planned quote before it's
       -- sent, so a live job reservation must block termination from ANY status
       -- (else draft -> cancelled releases the quote holds under the job).
       OR EXISTS (
         SELECT 1 FROM job_product_draws
         WHERE quote_id = NEW.id AND quantity_drawn > 0
       )
       -- >>>LAYER2
     )
  THEN
    RAISE EXCEPTION 'BOOKING_PARTIALLY_DRAWN';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_enforce_quote_terminal_not_drawn"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_return_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF _is_admin_override() THEN RETURN NEW; END IF;
  -- PARKED-004: a status change must originate from a return RPC (which sets this flag)
  -- or an admin_override block. Closes the direct-UPDATE bypass.
  IF current_setting('app.return_rpc', true) IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'RETURN_STATUS_VIA_RPC_ONLY: return status changes must go through the approve/receive/reject/cancel/issue_return_credit RPCs';
  END IF;

  IF (OLD.status = 'requested' AND NEW.status IN ('approved', 'rejected', 'cancelled'))
  OR (OLD.status = 'approved' AND NEW.status IN ('received', 'cancelled'))
  OR (OLD.status = 'received' AND NEW.status = 'credited')
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Invalid return status transition: % → %', OLD.status, NEW.status;
END;
$$;


ALTER FUNCTION "public"."_enforce_return_status_transition"() OWNER TO "postgres";


