CREATE OR REPLACE FUNCTION "public"."_insert_commissions_for_job"("p_job_id" "uuid", "p_invoice_id" "uuid", "p_customer_id" "uuid", "p_profit" numeric, "p_commission_split" "jsonb", "p_commission_date" "date" DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count int := 0;
BEGIN
  IF p_commission_split IS NULL OR NOT (p_commission_split ? 'splits') THEN
    RETURN 0;
  END IF;

  PERFORM public.validate_commission_split_json(p_commission_split);

  INSERT INTO public.commissions (
    job_id, invoice_id, customer_id, recipient, recipient_user_id, split_percentage,
    commission_amount, order_profit, order_date, status
  )
  WITH split_rows AS (
    SELECT
      s, ord,
      row_number() OVER (ORDER BY ord) AS rn,
      count(*) OVER () AS split_count,
      s->>'recipient' AS recipient,
      (s->>'percentage')::numeric AS percentage
    FROM jsonb_array_elements(p_commission_split->'splits') WITH ORDINALITY AS e(s, ord)
    WHERE NULLIF(btrim(s->>'recipient'), '') IS NOT NULL
      AND (s->>'percentage')::numeric > 0
  ),
  calculated AS (
    SELECT sr.*,
      CASE WHEN sr.rn = sr.split_count THEN
          GREATEST(ROUND(COALESCE(p_profit, 0), 2), 0)
          - COALESCE(SUM(public.compute_commission_amount(p_profit, sr.percentage))
              OVER (ORDER BY sr.rn ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0)
        ELSE public.compute_commission_amount(p_profit, sr.percentage)
      END AS reconciled_amount
    FROM split_rows sr
  )
  SELECT p_job_id, p_invoice_id, p_customer_id, c.recipient,
    (SELECT p.id FROM public.profiles p WHERE lower(trim(p.full_name)) = lower(trim(c.recipient)) AND p.is_active = true
       AND (SELECT count(*) FROM public.profiles p2 WHERE lower(trim(p2.full_name)) = lower(trim(c.recipient)) AND p2.is_active = true) = 1
     LIMIT 1),
    c.percentage, c.reconciled_amount, COALESCE(p_profit, 0), p_commission_date, 'pending'
  FROM calculated c;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."_insert_commissions_for_job"("p_job_id" "uuid", "p_invoice_id" "uuid", "p_customer_id" "uuid", "p_profit" numeric, "p_commission_split" "jsonb", "p_commission_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_insert_commissions_for_order"("p_order_id" "uuid", "p_customer_id" "uuid", "p_order_profit" numeric, "p_commission_split" "jsonb", "p_order_date" "date" DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count int := 0;
BEGIN
  IF p_commission_split IS NULL OR NOT (p_commission_split ? 'splits') THEN
    RETURN 0;
  END IF;

  PERFORM public.validate_commission_split_json(p_commission_split);

  INSERT INTO public.commissions (
    order_id, customer_id, recipient, recipient_user_id, split_percentage,
    commission_amount, order_profit, order_date, status
  )
  WITH split_rows AS (
    SELECT
      s,
      ord,
      row_number() OVER (ORDER BY ord) AS rn,
      count(*) OVER () AS split_count,
      s->>'recipient' AS recipient,
      (s->>'percentage')::numeric AS percentage
    FROM jsonb_array_elements(p_commission_split->'splits') WITH ORDINALITY AS e(s, ord)
    WHERE NULLIF(btrim(s->>'recipient'), '') IS NOT NULL
      AND (s->>'percentage')::numeric > 0
  ),
  calculated AS (
    SELECT
      sr.*,
      CASE
        WHEN sr.rn = sr.split_count THEN
          GREATEST(ROUND(COALESCE(p_order_profit, 0), 2), 0)
          - COALESCE(
              SUM(public.compute_commission_amount(p_order_profit, sr.percentage))
                OVER (ORDER BY sr.rn ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),
              0
            )
        ELSE public.compute_commission_amount(p_order_profit, sr.percentage)
      END AS reconciled_amount
    FROM split_rows sr
  )
  SELECT
    p_order_id,
    p_customer_id,
    c.recipient,
    (
      SELECT p.id
      FROM public.profiles p
      WHERE lower(trim(p.full_name)) = lower(trim(c.recipient))
        AND p.is_active = true
        AND (
          SELECT count(*)
          FROM public.profiles p2
          WHERE lower(trim(p2.full_name)) = lower(trim(c.recipient))
            AND p2.is_active = true
        ) = 1
      LIMIT 1
    ),
    c.percentage,
    c.reconciled_amount,
    COALESCE(p_order_profit, 0),
    p_order_date,
    'pending'
  FROM calculated c;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."_insert_commissions_for_order"("p_order_id" "uuid", "p_customer_id" "uuid", "p_order_profit" numeric, "p_commission_split" "jsonb", "p_order_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_insert_commissions_for_order"("p_order_id" "uuid", "p_customer_id" "uuid", "p_order_profit" numeric, "p_commission_split" "jsonb", "p_order_date" "date") IS 'Internal helper for the 3 canonical commission-creating RPCs. Populates recipient_user_id via case-insensitive full_name lookup against active profiles when exactly one match exists. No UUID aggregate. NOT callable from PostgREST.';



