CREATE OR REPLACE FUNCTION "public"."_is_dispatched_to_me"("p_job_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  -- The caller must be an ACTIVE profile — mirror is_applicator()/is_admin(), which
  -- re-check profiles.is_active, so a DEACTIVATED user with a still-valid token loses
  -- dispatch visibility immediately (Codex re-review-6 P2).
  SELECT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = (select auth.uid()) AND p.is_active)
  AND EXISTS (
    SELECT 1 FROM public.job_location_dispatches d
     WHERE d.job_id = p_job_id
       -- Only an ACTIVE ('dispatched') assignment — or, since A1b, the caller's own
       -- assignment COMPLETED within the last 7 days — grants visibility. The completed
       -- tail mirrors get_dispatched_list's A1 Done-section window exactly, so a split
       -- assignee's just-finished job keeps its customer name + expanded detail readable
       -- while it sits in Done. A 'cancelled' dispatch must still NOT keep granting the
       -- former assignee/crew read access to the parent job (Codex re-review P2).
       AND (
         d.dispatch_status = 'dispatched'
         OR (d.dispatch_status = 'completed' AND d.updated_at >= now() - interval '7 days')
       )
       AND (
         d.applicator_id = (select auth.uid())
         OR (
           d.crew_id IS NOT NULL
           AND EXISTS (
             -- the CREW must still be active AND the caller an active member —
             -- deactivating the crew revokes visibility even if member rows linger
             -- (Codex re-review-9 P2).
             SELECT 1 FROM public.ground_crew_members gcm
              JOIN public.ground_crews gc ON gc.id = gcm.crew_id
              WHERE gcm.crew_id = d.crew_id
                AND gcm.profile_id = (select auth.uid())
                AND gcm.is_active
                AND gc.is_active
           )
         )
       )
  );
$$;


ALTER FUNCTION "public"."_is_dispatched_to_me"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_issue_return_credit_impl"("p_return_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_return record;
  v_total bigint;
  v_invoice_id uuid;
  v_invoice_num text;
  v_customer_id uuid;
  v_order_id uuid;
  v_return_number text;
  v_salesman_id uuid;
  v_cached jsonb;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_actor_id IS NOT NULL AND p_actor_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached := check_idempotency(p_idempotency_key, 'issue_return_credit');
    IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
  END IF;

  SELECT r.id, r.status, r.customer_id, r.order_id, r.return_number
    INTO v_return
    FROM returns r
   WHERE r.id = p_return_id
   FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'RETURN_NOT_FOUND'; END IF;
  IF v_return.status <> 'received' THEN RAISE EXCEPTION 'INVALID_RETURN_STATUS: %', v_return.status; END IF;

  v_customer_id := v_return.customer_id;
  v_order_id := v_return.order_id;
  v_return_number := v_return.return_number;

  PERFORM check_period_open(CURRENT_DATE);

  SELECT COALESCE(SUM(ri.extended_cents), 0)
    INTO v_total
    FROM return_items ri
   WHERE ri.return_id = p_return_id;

  IF v_total <= 0 THEN RAISE EXCEPTION 'RETURN_CREDIT_EMPTY'; END IF;

  v_invoice_num := next_invoice_number('credit_memo');

  IF v_order_id IS NOT NULL THEN
    SELECT o.salesman_id INTO v_salesman_id
      FROM orders o
     WHERE o.id = v_order_id;
  END IF;

  INSERT INTO invoices (
    invoice_number, order_id, customer_id, invoice_type, status, season,
    salesman_id, created_by, total_amount_cents, paid_amount_cents,
    prepay_applied_cents, posted_by, posted_at, invoice_date, due_date,
    header_notes, parent_invoice_id
  ) VALUES (
    v_invoice_num, v_order_id, v_customer_id, 'credit_memo', 'posted', current_season(),
    v_salesman_id, v_actor, -v_total, 0, 0, v_actor, now(),
    CURRENT_DATE, CURRENT_DATE,
    'Credit memo for return ' || v_return_number, NULL
  )
  RETURNING id INTO v_invoice_id;

  PERFORM set_config('app.return_rpc', 'true', true);  -- PARKED-004
  UPDATE returns
     SET status = 'credited',
         total_credit_cents = v_total,
         credit_invoice_id = v_invoice_id,
         credited_at = now(),
         credited_by = v_actor,
         updated_at = now()
   WHERE id = p_return_id;

  INSERT INTO financial_audit_log (
    operation_type,
    entity_type,
    entity_id,
    actor_user_id, total_impact_cents, description, new_values
  ) VALUES (
    'credit_memo_created', 'credit_memo', v_invoice_id,
    v_actor, -v_total,
    'Credit memo ' || v_invoice_num || ' created for return ' || v_return_number,
    jsonb_build_object(
      'invoice_id', v_invoice_id,
      'invoice_number', v_invoice_num,
      'return_id', p_return_id,
      'return_number', v_return_number,
      'customer_id', v_customer_id,
      'credit_amount_cents', v_total
    )
  );

  INSERT INTO financial_audit_log (
    operation_type,
    entity_type,
    entity_id,
    actor_user_id, total_impact_cents, description, new_values
  ) VALUES (
    'return_credit_issued', 'return', p_return_id,
    v_actor, -v_total,
    'Credit issued for return ' || v_return_number || ' -> invoice ' || v_invoice_num,
    jsonb_build_object(
      'credit_invoice_id', v_invoice_id,
      'credit_invoice_number', v_invoice_num,
      'credit_amount_cents', v_total,
      'customer_id', v_customer_id
    )
  );

  v_result := jsonb_build_object(
    'success', true,
    'return_id', p_return_id,
    'return_number', v_return_number,
    'credit_invoice_id', v_invoice_id,
    'credit_invoice_number', v_invoice_num,
    'credit_amount_cents', v_total,
    'customer_id', v_customer_id,
    'credited_at', now()
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'issue_return_credit', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."_issue_return_credit_impl"("p_return_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_mark_delivery_aggregate_short_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_delivery_id text := current_setting(
    'app.delivery_aggregate_short_delivery_id',
    true
  );
  v_product_ids text := current_setting(
    'app.delivery_aggregate_short_product_ids',
    true
  );
BEGIN
  IF NEW.transaction_type = 'delivered'
     AND NEW.delivery_id IS NOT NULL
     AND NEW.product_id IS NOT NULL
     AND v_delivery_id IS NOT NULL
     AND v_product_ids IS NOT NULL
     AND NEW.delivery_id::text = v_delivery_id
     AND NEW.product_id = ANY(string_to_array(v_product_ids, ',')::uuid[]) THEN
    NEW.requires_review := true;
    IF COALESCE(NEW.notes, '') NOT LIKE '%[SHORT STOCK — review required]%' THEN
      NEW.notes := COALESCE(NEW.notes, '') || ' [SHORT STOCK — review required]';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_mark_delivery_aggregate_short_stock"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_mark_delivery_aggregate_short_stock"() IS 'Marks newly inserted delivered ledger rows for transaction-local aggregate short-stock products without mutating the append-only ledger later.';



CREATE OR REPLACE FUNCTION "public"."_parse_pricing_dollars"("p_value" "text") RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_value numeric;
BEGIN
  IF p_value !~ '^[0-9]+([.][0-9]{1,2})?$' THEN
    RAISE EXCEPTION 'PRICING_DOLLARS_INVALID';
  END IF;
  v_value := p_value::numeric;
  IF v_value > 92233720368547758.07 THEN
    RAISE EXCEPTION 'PRICING_DOLLARS_INVALID';
  END IF;
  RETURN (v_value * 100)::bigint;
EXCEPTION
  WHEN numeric_value_out_of_range OR invalid_text_representation THEN
    RAISE EXCEPTION 'PRICING_DOLLARS_INVALID';
END;
$_$;


ALTER FUNCTION "public"."_parse_pricing_dollars"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_parse_pricing_margin_percent"("p_value" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_value numeric;
BEGIN
  IF p_value !~ '^[0-9]+([.][0-9]+)?$' THEN
    RAISE EXCEPTION 'PRICING_MARGIN_PERCENT_INVALID';
  END IF;
  v_value := p_value::numeric;
  IF v_value < 0 OR v_value >= 100 THEN
    RAISE EXCEPTION 'PRICING_MARGIN_PERCENT_INVALID';
  END IF;
  RETURN v_value / 100;
EXCEPTION
  WHEN numeric_value_out_of_range OR invalid_text_representation THEN
    RAISE EXCEPTION 'PRICING_MARGIN_PERCENT_INVALID';
END;
$_$;


ALTER FUNCTION "public"."_parse_pricing_margin_percent"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_post_invoice_customer_scope_impl"("p_invoice_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing jsonb;
  v_group_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Not authorized to post invoices';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'post_invoice');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;

  SELECT invoice_group_id INTO v_group_id
  FROM public.invoices
  WHERE id = p_invoice_id AND deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found: %', p_invoice_id; END IF;
  IF v_group_id IS NOT NULL THEN
    RAISE EXCEPTION 'GROUP_POST_REQUIRED';
  END IF;

  PERFORM public._post_invoice_impl_20260714(p_invoice_id, p_idempotency_key);
END;
$$;


ALTER FUNCTION "public"."_post_invoice_customer_scope_impl"("p_invoice_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_post_invoice_group_customer_scope_impl"("p_invoice_group_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_inv record;
  v_posted_ids uuid[] := '{}';
  v_total_cents bigint := 0;
  v_member_count int := 0;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'Not authorized: admin or sales role required to post invoice groups';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'post_invoice_group');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF p_invoice_group_id IS NULL THEN
    RAISE EXCEPTION 'invoice_group_id is required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_invoice_group_id::text, 0));

  PERFORM 1
  FROM public.invoices
  WHERE invoice_group_id = p_invoice_group_id
    AND deleted_at IS NULL
  ORDER BY id
  LIMIT 1
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No invoices found in group %', p_invoice_group_id;
  END IF;

  PERFORM 1
  FROM public.invoices
  WHERE invoice_group_id = p_invoice_group_id
    AND deleted_at IS NULL
  ORDER BY id
  FOR UPDATE;

  SELECT count(*) INTO v_member_count
  FROM public.invoices
  WHERE invoice_group_id = p_invoice_group_id
    AND deleted_at IS NULL;

  FOR v_inv IN
    SELECT *
    FROM public.invoices
    WHERE invoice_group_id = p_invoice_group_id
      AND deleted_at IS NULL
    ORDER BY invoice_number
  LOOP
    IF v_inv.status NOT IN ('draft', 'unposted') THEN
      RAISE EXCEPTION 'Cannot post group -- invoice % has status %',
        v_inv.invoice_number, v_inv.status;
    END IF;
    IF v_inv.pricing_pending THEN
      RAISE EXCEPTION 'PRICING_INCOMPLETE';
    END IF;
    PERFORM public.check_period_open(v_inv.invoice_date);
  END LOOP;

  FOR v_inv IN
    SELECT *
    FROM public.invoices
    WHERE invoice_group_id = p_invoice_group_id
      AND deleted_at IS NULL
    ORDER BY invoice_number
  LOOP
    PERFORM public._post_invoice_impl_20260714(v_inv.id, NULL);
    v_posted_ids := array_append(v_posted_ids, v_inv.id);
    v_total_cents := v_total_cents + v_inv.total_amount_cents;
  END LOOP;

  INSERT INTO public.activity_feed (
    event_type, description, performed_by, related_entity_type, related_entity_id
  ) VALUES (
    'invoice_group_posted',
    'Posted ' || v_member_count || ' invoice(s) in group -- total $' ||
      (v_total_cents / 100.0)::numeric(12,2),
    p_performed_by, 'invoice', v_posted_ids[1]
  );

  v_result := jsonb_build_object(
    'posted_invoice_ids', to_jsonb(v_posted_ids),
    'invoice_group_id', p_invoice_group_id,
    'total_posted_cents', v_total_cents,
    'member_count', v_member_count
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(p_idempotency_key, 'post_invoice_group', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."_post_invoice_group_customer_scope_impl"("p_invoice_group_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_post_invoice_impl_20260714"("p_invoice_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE v_inv record; v_order_status text; v_order_pricing text; v_existing jsonb; v_terms_days integer;  -- A8: v_terms_days added
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales_rep')) THEN
    RAISE EXCEPTION 'Not authorized to post invoices';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'post_invoice');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;

  SELECT * INTO v_inv FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found: %', p_invoice_id; END IF;
  PERFORM check_period_open(v_inv.invoice_date);
  IF v_inv.status NOT IN ('draft', 'unposted') THEN RAISE EXCEPTION 'Cannot post invoice with status: %', v_inv.status; END IF;
  -- PRICING_INCOMPLETE gate (sell-side #2): never post an invoice for a still-
  -- unpriced rush order. Cleared by price_order (v2). Dormant until v1b.
  IF v_inv.pricing_pending THEN RAISE EXCEPTION 'PRICING_INCOMPLETE'; END IF;
  IF v_inv.order_id IS NOT NULL THEN
    SELECT status, pricing_status INTO v_order_status, v_order_pricing FROM orders WHERE id = v_inv.order_id;
    IF v_order_status = 'cancelled' THEN RAISE EXCEPTION 'Cannot post invoice — linked order % is cancelled', v_inv.order_id; END IF;
    IF v_order_pricing = 'needs_pricing' THEN RAISE EXCEPTION 'PRICING_INCOMPLETE'; END IF;
  END IF;

  -- A8: derive due_date from the payment terms; default Net 30 when blank/unparseable.
  -- The invoice-level override (invoices.payment_terms — the documented per-invoice terms that
  -- the PDF prints) WINS over the customer default; fall back to customers.payment_terms when
  -- the invoice override is blank. Applied only-when-NULL in the UPDATE below so a due_date set
  -- at creation (field-app +30) is preserved, and forward-only (runs at post time).
  SELECT parse_payment_terms_days(COALESCE(NULLIF(btrim(v_inv.payment_terms), ''), c.payment_terms))
    INTO v_terms_days
  FROM customers c WHERE c.id = v_inv.customer_id;

  SET LOCAL app.admin_override = 'true';
  UPDATE invoices SET status = 'posted', posted_by = auth.uid(), posted_at = now(), updated_at = now(),
    due_date = COALESCE(due_date, (v_inv.invoice_date + (v_terms_days || ' days')::interval)::date)  -- A8
    WHERE id = p_invoice_id;
  INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_role, old_values, new_values, total_impact_cents, description)
  VALUES ('invoice_posted', 'invoice', p_invoice_id, (SELECT role FROM profiles WHERE id = auth.uid()), jsonb_build_object('status', v_inv.status), jsonb_build_object('status', 'posted', 'posted_at', now()::text), v_inv.total_amount_cents, 'Posted ' || v_inv.invoice_number || ' for $' || (v_inv.total_amount_cents / 100.0)::numeric(12,2));
  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('invoice_posted', 'Posted invoice ' || v_inv.invoice_number || ' — $' || (v_inv.total_amount_cents / 100.0)::numeric(12,2), auth.uid(), 'invoice', p_invoice_id, v_inv.customer_id);
  PERFORM generate_rup_sales_records(p_invoice_id);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'post_invoice', jsonb_build_object('success', true, 'invoice_id', p_invoice_id));
  END IF;
END;
$_$;


ALTER FUNCTION "public"."_post_invoice_impl_20260714"("p_invoice_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_prebook_quick_delivery_inventory"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_delivery record;
  v_inv record;
BEGIN
  -- Only act on quick delivery items
  SELECT d.* INTO v_delivery
  FROM deliveries d
  WHERE d.id = NEW.delivery_id
    AND d.is_quick_delivery = true
    AND d.status = 'scheduled';

  IF NOT FOUND THEN
    -- M1 FIX: Log instead of silently returning
    RAISE WARNING 'Quick delivery prebooking skipped: delivery % not found or not quick/scheduled', NEW.delivery_id;
    RETURN NEW;
  END IF;

  -- Lock and update inventory
  SELECT * INTO v_inv
  FROM inventory
  WHERE product_id = NEW.product_id
    AND location = 'Main Warehouse'
  FOR UPDATE;

  IF FOUND THEN
    UPDATE inventory SET
      quantity_prebooked = quantity_prebooked + NEW.quantity,
      updated_at = now()
    WHERE product_id = NEW.product_id
      AND location = 'Main Warehouse';

    INSERT INTO inventory_transactions (
      product_id, transaction_type, quantity,
      from_location, order_id, delivery_id,
      performed_by, notes
    ) VALUES (
      NEW.product_id, 'booked', NEW.quantity,
      'Main Warehouse', v_delivery.order_id, NEW.delivery_id,
      auth.uid(),
      'Quick delivery prebooking for ' || v_delivery.delivery_number
    );
  ELSE
    -- M1 FIX: Create inventory row if missing instead of silently failing
    INSERT INTO inventory (product_id, location, quantity_available, quantity_on_order, quantity_prebooked, unit_size)
    VALUES (NEW.product_id, 'Main Warehouse', 0, 0, NEW.quantity, 'ea');

    RAISE WARNING 'Created missing inventory row for product % during quick delivery prebooking', NEW.product_id;

    INSERT INTO inventory_transactions (
      product_id, transaction_type, quantity,
      from_location, order_id, delivery_id,
      performed_by, notes
    ) VALUES (
      NEW.product_id, 'booked', NEW.quantity,
      'Main Warehouse', v_delivery.order_id, NEW.delivery_id,
      auth.uid(),
      'Quick delivery prebooking (created inventory row) for ' || v_delivery.delivery_number
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_prebook_quick_delivery_inventory"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_preserve_job_location_dispatch_on_field_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Stash this field's ACTIVE dispatch (if any) under the stable field_id key
  -- BEFORE the cascade wipes it. Cancelled/completed rows are not preserved.
  INSERT INTO job_dispatch_preservation
    (job_id, field_id, applicator_id, crew_id, dispatched_by, dispatched_at)
  SELECT d.job_id, OLD.field_id, d.applicator_id, d.crew_id, d.dispatched_by, d.dispatched_at
    FROM job_location_dispatches d
   WHERE d.job_field_id = OLD.id
     AND d.dispatch_status = 'dispatched'
  ON CONFLICT (job_id, field_id) DO UPDATE
    SET applicator_id = EXCLUDED.applicator_id,
        crew_id       = EXCLUDED.crew_id,
        dispatched_by = EXCLUDED.dispatched_by,
        dispatched_at = EXCLUDED.dispatched_at,
        preserved_at  = now();
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."_preserve_job_location_dispatch_on_field_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_purchase_order_item_unit_cost_cents"("p_item" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cents bigint;
  v_dollars numeric;
  v_scaled numeric;
BEGIN
  IF NULLIF(p_item->>'unit_cost_cents', '') IS NOT NULL THEN
    v_cents := (p_item->>'unit_cost_cents')::bigint;
  END IF;

  IF NULLIF(p_item->>'unit_cost', '') IS NOT NULL THEN
    v_dollars := (p_item->>'unit_cost')::numeric;
    v_scaled := v_dollars * 100;
    IF v_scaled IS DISTINCT FROM round(v_scaled) THEN
      RAISE EXCEPTION 'PO_UNIT_COST_FRACTIONAL_CENT: unit cost must resolve to whole cents'
        USING ERRCODE = '22003';
    END IF;
    IF v_cents IS NULL THEN
      v_cents := v_scaled::bigint;
    ELSIF v_cents IS DISTINCT FROM v_scaled::bigint THEN
      RAISE EXCEPTION 'PO_UNIT_COST_CENTS_MISMATCH: dollar and cent values disagree'
        USING ERRCODE = '22003';
    END IF;
  END IF;

  v_cents := COALESCE(v_cents, 0);
  IF v_cents < 0 THEN
    RAISE EXCEPTION 'PO_UNIT_COST_NEGATIVE: unit cost cannot be negative'
      USING ERRCODE = '22003';
  END IF;
  RETURN v_cents;
END;
$$;


ALTER FUNCTION "public"."_purchase_order_item_unit_cost_cents"("p_item" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_receive_return_impl_20260714"("p_return_id" "uuid", "p_received_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_return record; v_item record; v_cached jsonb; v_result jsonb;
  v_restocked_ids uuid[] := ARRAY[]::uuid[];
  v_restocked_qty bigint := 0; v_restocked_count int := 0; v_skipped_count int := 0;
  v_actor uuid;
BEGIN
  -- P2-E: strict-actor + role gate (canonical pattern from issue_return_credit).
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_received_by IS NOT NULL AND p_received_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached := check_idempotency(p_idempotency_key, 'receive_return');
    IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
  END IF;

  SELECT id, return_number, status, customer_id INTO v_return
  FROM returns WHERE id = p_return_id FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Return not found: %', p_return_id; END IF;
  IF v_return.status != 'approved' THEN
    RAISE EXCEPTION 'Only approved returns can be received (current status: %)', v_return.status;
  END IF;

  FOR v_item IN
    SELECT ri.id AS item_id, ri.product_id, ri.quantity, ri.product_name, ri.condition,
           inv.id AS inv_id, inv.location AS inv_location
    FROM return_items ri
    LEFT JOIN LATERAL (SELECT id, location FROM inventory WHERE product_id = ri.product_id AND location = 'Main Warehouse' LIMIT 1) inv ON true
    WHERE ri.return_id = p_return_id AND ri.restock = true AND ri.restocked = false
    ORDER BY ri.sort_order
  LOOP
    IF v_item.inv_id IS NOT NULL THEN
      UPDATE inventory SET quantity_available = quantity_available + v_item.quantity, updated_at = now() WHERE id = v_item.inv_id;
      INSERT INTO inventory_transactions (product_id, transaction_type, quantity, to_location, performed_by, notes)
      VALUES (v_item.product_id, 'returned', v_item.quantity, v_item.inv_location, p_received_by,
              'Return ' || v_return.return_number || ': ' || v_item.product_name || ' (' || v_item.condition || ')');
      v_restocked_ids := array_append(v_restocked_ids, v_item.item_id);
      v_restocked_qty := v_restocked_qty + v_item.quantity;
      v_restocked_count := v_restocked_count + 1;
    ELSE
      RAISE WARNING 'No inventory row for product % in return % - item NOT restocked.', v_item.product_id, v_return.return_number;
      v_skipped_count := v_skipped_count + 1;
    END IF;
  END LOOP;

  PERFORM set_config('app.return_rpc', 'true', true);  -- PARKED-004
  UPDATE returns SET status='received', received_by=p_received_by, received_at=now(), updated_at=now() WHERE id=p_return_id;

  IF array_length(v_restocked_ids, 1) > 0 THEN
    UPDATE return_items SET restocked = true WHERE id = ANY(v_restocked_ids);
  END IF;

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('return_received',
          'Return ' || v_return.return_number || ' received - ' || v_restocked_count || ' item(s) restocked' ||
          CASE WHEN v_skipped_count > 0 THEN ' (' || v_skipped_count || ' skipped: no inventory row)' ELSE '' END,
          p_received_by, 'return', p_return_id, v_return.customer_id);

  v_result := jsonb_build_object('success', true, 'return_id', p_return_id, 'return_number', v_return.return_number,
                                  'status', 'received', 'restocked_count', v_restocked_count,
                                  'restocked_quantity', v_restocked_qty, 'skipped_count', v_skipped_count);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'receive_return', v_result);
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."_receive_return_impl_20260714"("p_return_id" "uuid", "p_received_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_receiving_records_before_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('app.reversal_rpc_active', true) = 'true' THEN
    RETURN OLD;
  END IF;

  UPDATE inventory
  SET quantity_available = quantity_available - OLD.quantity_received,
      updated_at         = now()
  WHERE product_id = OLD.product_id
    AND location   = OLD.storage_location;

  INSERT INTO inventory_transactions (
    product_id, transaction_type, quantity, to_location,
    notes, performed_by
  ) VALUES (
    OLD.product_id,
    'adjusted',
    -1 * OLD.quantity_received,
    OLD.storage_location,
    'Auto-reversed by delete trigger on receiving_records ' || OLD.id::text,
    auth.uid()
  );

  UPDATE purchase_order_items
  SET quantity_received = GREATEST(quantity_received - OLD.quantity_received, 0)
  WHERE id = OLD.po_item_id;

  IF OLD.purchase_order_id IS NOT NULL THEN
    UPDATE purchase_orders
    SET status = CASE
      WHEN (
        SELECT bool_and(quantity_received = 0)
        FROM purchase_order_items
        WHERE purchase_order_id = OLD.purchase_order_id
      ) THEN 'submitted'
      WHEN (
        SELECT bool_and(quantity_received >= quantity_ordered)
        FROM purchase_order_items
        WHERE purchase_order_id = OLD.purchase_order_id
      ) THEN 'fully_received'
      ELSE 'partially_received'
    END,
    updated_at = now()
    WHERE id = OLD.purchase_order_id
      AND status <> 'cancelled';
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."_receiving_records_before_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recompute_prepay_credit_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_target uuid;
BEGIN
  v_target := COALESCE(NEW.prepay_credit_id, OLD.prepay_credit_id);

  UPDATE prepay_credits
     SET balance_cents = original_amount_cents - COALESCE(
           (SELECT SUM(applied_amount_cents)
              FROM prepay_applications
             WHERE prepay_credit_id = v_target),
           0
         ),
         updated_at = now()
   WHERE id = v_target;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."_recompute_prepay_credit_balance"() OWNER TO "postgres";


