    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM public.purchase_order_import_intents
     WHERE id = NEW.id
       AND content_fingerprint IS NOT NULL
  ) THEN
