CREATE OR REPLACE FUNCTION "public"."_reverse_completed_cycle_count_impl"("p_cycle_count_id" "uuid", "p_reversed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_count    record;
  v_item     record;
  v_new_qty  numeric;
  v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_reversed_by IS NOT NULL AND p_reversed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_reversed_by does not match authenticated user';
  END IF;
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Admin access required to reverse a cycle count';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'reverse_completed_cycle_count');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;

  SELECT * INTO v_count
    FROM cycle_counts
   WHERE id = p_cycle_count_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cycle count not found';
  END IF;

  IF v_count.status != 'completed' THEN
    RAISE EXCEPTION 'Only completed cycle counts can be reversed (current status: %)', v_count.status;
  END IF;

  FOR v_item IN
    SELECT cci.*, i.quantity_available
    FROM cycle_count_items cci
    LEFT JOIN inventory i ON i.id = cci.inventory_id
    WHERE cci.cycle_count_id = p_cycle_count_id
      AND cci.is_counted = true
      AND cci.variance IS NOT NULL
      AND cci.variance <> 0
  LOOP
    IF v_item.inventory_id IS NOT NULL AND v_item.quantity_available IS NOT NULL THEN
      IF COALESCE(v_item.quantity_available, 0) - v_item.variance < 0 THEN
        RAISE EXCEPTION 'Reversing cycle count for product % would set on-hand to % (currently %, would subtract %). Inventory has changed since the count completed; manual reconciliation required before reversing.',
          v_item.product_id,
          COALESCE(v_item.quantity_available, 0) - v_item.variance,
          COALESCE(v_item.quantity_available, 0),
          v_item.variance;
      END IF;

      v_new_qty := COALESCE(v_item.quantity_available, 0) - v_item.variance;

      UPDATE inventory
      SET quantity_available = v_new_qty,
          updated_at         = now()
      WHERE id = v_item.inventory_id;

      INSERT INTO inventory_transactions (
        product_id, transaction_type, quantity,
        to_location, performed_by, notes
      ) VALUES (
        v_item.product_id, 'adjusted', -v_item.variance,
        (SELECT location FROM inventory WHERE id = v_item.inventory_id),
        v_actor,
        'REVERSED cycle count ' || v_count.count_number ||
        ': undid adjustment of ' || v_item.variance ||
        ' (was ' || v_item.expected_qty || ' -> ' || v_item.counted_qty || ')'
      );
    END IF;
  END LOOP;

  UPDATE cycle_counts
  SET status = 'cancelled',
      notes  = COALESCE(notes || E'\n', '') || 'Reversed on ' ||
               to_char(now(), 'YYYY-MM-DD HH24:MI') || ' by user ' || v_actor::text
  WHERE id = p_cycle_count_id;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'reverse_completed_cycle_count', '{}'::jsonb);
  END IF;
END;
$$;


ALTER FUNCTION "public"."_reverse_completed_cycle_count_impl"("p_cycle_count_id" "uuid", "p_reversed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_reverse_credit_memo_application"("p_application_id" "uuid", "p_actor" "uuid", "p_actor_role" "text", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_app    record;
  v_first  uuid;
  v_second uuid;
  v_memo   record;
  v_target record;
BEGIN
  -- idempotency-body-check: exempt
  -- Internal helper: all EXECUTE is revoked (client-uncallable). Idempotency is enforced by its
  -- two SECDEF callers (reverse_credit_memo_application + void_invoice/unapply loops), so a
  -- p_idempotency_key here would be redundant.
  SELECT * INTO v_app FROM credit_memo_applications WHERE id = p_application_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CREDIT_APPLICATION_NOT_FOUND: %', p_application_id; END IF;
  IF v_app.reversed_at IS NOT NULL THEN
    RAISE EXCEPTION 'CREDIT_APPLICATION_ALREADY_REVERSED: %', p_application_id;
  END IF;

  -- lock both invoices by id order (deadlock-safe; re-entrant if a caller already locked one)
  IF v_app.credit_memo_id < v_app.target_invoice_id THEN
    v_first := v_app.credit_memo_id; v_second := v_app.target_invoice_id;
  ELSE
    v_first := v_app.target_invoice_id; v_second := v_app.credit_memo_id;
  END IF;
  PERFORM 1 FROM invoices WHERE id = v_first  FOR UPDATE;
  PERFORM 1 FROM invoices WHERE id = v_second FOR UPDATE;

  SELECT * INTO v_memo   FROM invoices WHERE id = v_app.credit_memo_id;
  SELECT * INTO v_target FROM invoices WHERE id = v_app.target_invoice_id;

  -- give the credit back to the memo (its balance falls back toward the issued amount)
  UPDATE invoices
     SET credit_applied_cents = credit_applied_cents - v_app.amount_cents,
         updated_at = now()
   WHERE id = v_app.credit_memo_id;

  -- restore the target's balance; re-open a fully-credited (paid) invoice to posted
  UPDATE invoices
     SET credit_applied_cents = credit_applied_cents - v_app.amount_cents,
         status = CASE
           WHEN status = 'paid'
             AND (total_amount_cents - paid_amount_cents - prepay_applied_cents - write_off_cents
                  - (credit_applied_cents - v_app.amount_cents)) > 0
           THEN 'posted' ELSE status END,
         updated_at = now()
   WHERE id = v_app.target_invoice_id;

  -- stamp the reversal (the immutability guard permits exactly this one-time transition)
  UPDATE credit_memo_applications
     SET reversed_at = now(), reversed_by = p_actor, reversal_reason = p_reason
   WHERE id = p_application_id;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_user_id, actor_role,
    new_values, total_impact_cents, description
  ) VALUES (
    'credit_memo_unapplied', 'credit_memo', p_application_id, p_actor, p_actor_role,
    jsonb_build_object(
      'kind', 'application_reversed',
      'application_id', p_application_id,
      'credit_memo_id', v_app.credit_memo_id,     'credit_memo_number', v_memo.invoice_number,
      'target_invoice_id', v_app.target_invoice_id, 'target_invoice_number', v_target.invoice_number,
      'amount_cents', v_app.amount_cents, 'reason', p_reason
    ),
    0,
    'Reversed $' || (v_app.amount_cents / 100.0)::numeric(12,2) || ' credit '
      || v_memo.invoice_number || ' from ' || v_target.invoice_number || ': ' || p_reason
  );
END;
$_$;


ALTER FUNCTION "public"."_reverse_credit_memo_application"("p_application_id" "uuid", "p_actor" "uuid", "p_actor_role" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_save_field_app_invoice_impl_20260714"("p_invoice_id" "uuid", "p_invoice" "jsonb", "p_locations" "jsonb", "p_chemicals" "jsonb", "p_performed_by" "uuid", "p_application_service_id" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor               uuid := auth.uid();
  v_existing            jsonb;
  v_existing_group_id   uuid;
  v_existing_status     text;
  v_locked_count        int;
  v_field_ids           uuid[];
  v_applied_acres_map   jsonb := '{}'::jsonb;
  v_total_applied_acres numeric := 0;
  v_this_applied        numeric;
  v_loc                 jsonb;
  v_chem                jsonb;
  v_shares              jsonb;
  v_customers           jsonb;
  v_customer            jsonb;
  v_customer_id         uuid;
  v_customer_name       text;
  v_customer_tier       int;
  v_is_primary          boolean;
  v_has_override        boolean;
  v_invoice_id          uuid;
  v_invoice_number      text;
  v_invoice_group_id    uuid;
  v_invoice_ids         uuid[] := '{}';
  v_app_service         record;
  v_fee_rate            bigint;
  v_loc_id              uuid;
  v_share_row           jsonb;
  v_share_pct           numeric;
  v_share_acres         numeric;
  v_field_id            uuid;
  v_field_applied_acres numeric;
  v_field_override      bigint;
  v_field_pricing_note  text;
  v_unit_price          bigint;
  v_unit_cost           bigint;
  v_qi_price            numeric;
  v_quoted_price        bigint;
  v_price_source        text;
  v_extended            bigint;
  v_invoice_total       bigint;
  v_invoice_cost        bigint;
  v_total_share_acres   numeric;
  v_grower_share_amount bigint;
  v_fee_acres           numeric;
  v_fee_extended        bigint;
  v_fee_cost            bigint;
  v_result              jsonb;
  v_customer_count      int;
  v_orphan              record;
  v_req_salesman        uuid;
  v_salesman_id         uuid;
  v_skipped_customer_ids uuid[] := '{}';
  v_is_new_invoice      boolean;
  v_surcharge_acres     numeric;
  v_surcharge_cents     bigint;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'Not authorized: admin or sales role required to save field application invoices';
  END IF;

  v_req_salesman := (p_invoice->>'salesman_id')::uuid;
  IF is_admin() THEN
    v_salesman_id := v_req_salesman;
  ELSE
    IF v_req_salesman IS NOT NULL AND v_req_salesman IS DISTINCT FROM v_actor THEN
      RAISE EXCEPTION 'Not authorized: cannot attribute this invoice to another user (salesman_id)';
    END IF;
    v_salesman_id := v_actor;
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing FROM idempotency_keys WHERE idempotency_key = p_idempotency_key AND operation = 'save_field_app_invoice';
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF p_invoice_id IS NOT NULL THEN
    SELECT status, invoice_group_id INTO v_existing_status, v_existing_group_id
      FROM invoices WHERE id = p_invoice_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found: %', p_invoice_id; END IF;
    SELECT COUNT(*) INTO v_locked_count
      FROM invoices
     WHERE (id = p_invoice_id OR invoice_group_id = v_existing_group_id)
       AND v_existing_group_id IS NOT NULL
       AND deleted_at IS NULL
       AND status NOT IN ('draft', 'unposted');
    IF v_locked_count > 0 OR v_existing_status NOT IN ('draft', 'unposted') THEN
      RAISE EXCEPTION 'Cannot edit field app invoice — % invoice(s) in this group are posted/voided. Use void/reissue.', GREATEST(v_locked_count, 1);
    END IF;

    IF v_existing_group_id IS NOT NULL THEN
      DELETE FROM field_app_location_shares WHERE location_id IN (
        SELECT id FROM field_app_locations WHERE invoice_group_id = v_existing_group_id
      );
      DELETE FROM field_app_locations WHERE invoice_group_id = v_existing_group_id;
      DELETE FROM invoice_items   WHERE invoice_id IN (SELECT id FROM invoices WHERE invoice_group_id = v_existing_group_id AND deleted_at IS NULL);
      DELETE FROM invoice_shares  WHERE invoice_id IN (SELECT id FROM invoices WHERE invoice_group_id = v_existing_group_id AND deleted_at IS NULL);
    ELSE
      DELETE FROM field_app_location_shares WHERE location_id IN (
        SELECT id FROM field_app_locations WHERE invoice_id = p_invoice_id
      );
      DELETE FROM field_app_locations WHERE invoice_id = p_invoice_id;
      DELETE FROM invoice_items  WHERE invoice_id = p_invoice_id;
      DELETE FROM invoice_shares WHERE invoice_id = p_invoice_id;
    END IF;
  END IF;

  FOR v_loc IN SELECT * FROM jsonb_array_elements(p_locations)
  LOOP
    v_this_applied := (v_loc->>'applied_acres')::numeric;
    IF v_this_applied IS NULL OR v_this_applied <= 0 THEN
      RAISE EXCEPTION 'ZERO_APPLIED_ACRES: applied acres must be greater than 0 for field % (enter applied acres, or remove the field)', v_loc->>'field_id';
    END IF;
    v_field_ids := array_append(v_field_ids, (v_loc->>'field_id')::uuid);
    v_total_applied_acres := v_total_applied_acres + v_this_applied;
    v_applied_acres_map := v_applied_acres_map || jsonb_build_object(v_loc->>'field_id', v_this_applied);
  END LOOP;

  IF v_field_ids IS NULL OR array_length(v_field_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'At least one field is required';
  END IF;

  v_shares    := derive_customer_shares_from_fields(v_field_ids, v_applied_acres_map);
  v_customers := v_shares -> 'customers';
  v_customer_count := jsonb_array_length(v_customers);

  IF v_customer_count = 0 THEN
    RAISE EXCEPTION 'No billing customers derived from selected fields';
  END IF;

  IF v_existing_group_id IS NOT NULL THEN
    FOR v_orphan IN
      SELECT id, invoice_number, customer_id
        FROM invoices
       WHERE invoice_group_id = v_existing_group_id
         AND deleted_at IS NULL
         AND customer_id NOT IN (
           SELECT (c->>'customer_id')::uuid FROM jsonb_array_elements(v_customers) c
         )
    LOOP
      UPDATE invoices SET
        status              = 'cancelled',
        invoice_group_id    = NULL,
        total_amount_cents  = 0,
        total_cost_cents    = 0,
        updated_at          = now()
      WHERE id = v_orphan.id;

      INSERT INTO activity_feed (
        event_type, description, performed_by,
        related_entity_type, related_entity_id, customer_id
      ) VALUES (
        'invoice_orphan_cancelled',
        'Field app invoice ' || v_orphan.invoice_number ||
          ' cancelled — customer removed from group during edit',
        p_performed_by, 'invoice', v_orphan.id, v_orphan.customer_id
      );
    END LOOP;
  END IF;

  IF p_application_service_id IS NOT NULL THEN
    SELECT * INTO v_app_service FROM application_services WHERE id = p_application_service_id;
    IF NOT FOUND OR NOT v_app_service.is_active THEN
      RAISE EXCEPTION 'Application service not found or inactive: %', p_application_service_id;
    END IF;
  END IF;

  IF v_customer_count > 1 THEN
    v_invoice_group_id := COALESCE(v_existing_group_id, gen_random_uuid());
  ELSE
    v_invoice_group_id := NULL;
  END IF;

  FOR v_customer IN SELECT * FROM jsonb_array_elements(v_customers)
  LOOP
    v_customer_id   := (v_customer->>'customer_id')::uuid;
    v_customer_name := v_customer->>'customer_name';
    v_customer_tier := COALESCE((v_customer->>'tier')::int, 1);
    v_is_primary    := COALESCE((v_customer->>'is_primary')::boolean, false);
    v_has_override  := COALESCE((v_customer->>'has_override')::boolean, false);

    v_invoice_total := 0;
    v_invoice_cost  := 0;

    v_invoice_id := NULL;
    IF v_existing_group_id IS NOT NULL THEN
      SELECT id INTO v_invoice_id FROM invoices
       WHERE invoice_group_id = v_existing_group_id AND customer_id = v_customer_id AND deleted_at IS NULL LIMIT 1;
    ELSIF p_invoice_id IS NOT NULL AND v_customer_count = 1 THEN
      v_invoice_id := p_invoice_id;
    END IF;

    IF v_invoice_id IS NULL AND v_existing_group_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM invoices
       WHERE invoice_group_id = v_existing_group_id
         AND customer_id = v_customer_id
         AND deleted_at IS NOT NULL
    ) THEN
      v_skipped_customer_ids := array_append(v_skipped_customer_ids, v_customer_id);
      CONTINUE;
    END IF;

    v_is_new_invoice := (v_invoice_id IS NULL);

    IF v_invoice_id IS NULL THEN
      v_invoice_number := next_invoice_number();
      INSERT INTO invoices (
        invoice_number, customer_id, invoice_type, status,
        invoice_date, salesman_id, header_notes, created_by,
        total_amount_cents, total_cost_cents,
        invoice_group_id, application_service_id,
        season
      ) VALUES (
        v_invoice_number, v_customer_id, 'field_application', 'draft',
        COALESCE((p_invoice->>'invoice_date')::date, CURRENT_DATE),
        v_salesman_id,
        p_invoice->>'header_notes',
        p_performed_by,
        0, 0,
        v_invoice_group_id,
        p_application_service_id,
        current_season()
      ) RETURNING id INTO v_invoice_id;
    ELSE
      UPDATE invoices SET
        invoice_date            = COALESCE((p_invoice->>'invoice_date')::date, invoice_date),
        salesman_id             = CASE WHEN is_admin() THEN COALESCE(v_salesman_id, salesman_id) ELSE salesman_id END,
        header_notes            = COALESCE(p_invoice->>'header_notes', header_notes),
        application_service_id  = p_application_service_id,
        invoice_group_id        = v_invoice_group_id,
        total_amount_cents      = 0,
        total_cost_cents        = 0,
        updated_at              = now()
      WHERE id = v_invoice_id;
    END IF;

    v_invoice_ids := array_append(v_invoice_ids, v_invoice_id);

    FOR v_share_row IN
      SELECT * FROM jsonb_array_elements(v_shares -> 'rows') AS value
      WHERE (value ->> 'customer_id')::uuid = v_customer_id
        AND (value ->> 'price_override_cents') IS NOT NULL
    LOOP
      v_field_id            := (v_share_row->>'field_id')::uuid;
      v_field_applied_acres := (v_share_row->>'field_applied_acres')::numeric;
      v_share_pct           := (v_share_row->>'split_pct')::numeric;
      v_share_acres         := (v_share_row->>'share_acres')::numeric;
      v_field_override      := (v_share_row->>'price_override_cents')::bigint;
      v_field_pricing_note  := v_share_row->>'pricing_note';

      v_grower_share_amount := safe_cents_qty(v_field_override, v_share_acres);

      INSERT INTO invoice_items (
        invoice_id, description, quantity, unit_size,
        unit_price_cents, extended_cents, cost_cents,
        sort_order, acres, rate_per_acre, rate_unit,
        is_application_fee, price_source
      ) VALUES (
        v_invoice_id,
        (v_share_row->>'field_name') || ' — grower share @ $' ||
          (v_field_override / 100.0)::numeric(12,2) || '/ac' ||
          CASE WHEN v_field_pricing_note IS NOT NULL AND v_field_pricing_note <> ''
               THEN ' (' || v_field_pricing_note || ')' ELSE '' END,
        v_share_acres, 'acre',
        v_field_override, v_grower_share_amount, 0,
        0, v_share_acres, v_field_override, 'acre',
        false, 'manual'
      );

      v_invoice_total := v_invoice_total + v_grower_share_amount;
    END LOOP;

    FOR v_chem IN SELECT * FROM jsonb_array_elements(p_chemicals)
    LOOP
      DECLARE
        v_chem_qty_a   numeric := 0;
        v_chem_qty_b   numeric := 0;
        v_rate         numeric;
        v_qa_unit_cost bigint;
        v_wh           text := NULLIF(v_chem->>'warehouse', '');
        v_vendor       text := NULLIF(v_chem->>'vendor', '');
        v_form         text;
        v_epa          text := NULLIF(v_chem->>'epa_registration', '');
        v_ta_unit      text := COALESCE(NULLIF(v_chem->>'rate_unit',''), NULLIF(v_chem->>'unit_size',''));
        v_conv         record;
        v_inv_unit     text;       -- PARKED-010: product's sold/pricing unit (inventory_unit)
        v_priced_qty   numeric;    -- PARKED-010: applied qty converted into the pricing unit
      BEGIN
        v_rate := COALESCE((v_chem->>'rate_per_acre')::numeric, 0);

        IF (v_chem->>'product_id') IS NOT NULL THEN
          SELECT p.product_form::text, COALESCE(v_epa, p.epa_registration), COALESCE(v_vendor, p.vendor), p.inventory_unit
            INTO v_form, v_epa, v_vendor, v_inv_unit
            FROM products p WHERE p.id = (v_chem->>'product_id')::uuid;
        END IF;

        FOR v_share_row IN
          SELECT * FROM jsonb_array_elements(v_shares -> 'rows') AS value
          WHERE (value ->> 'customer_id')::uuid = v_customer_id
        LOOP
          v_share_acres := (v_share_row->>'share_acres')::numeric;
          IF (v_share_row->>'price_override_cents') IS NOT NULL THEN
            v_chem_qty_a := v_chem_qty_a + (v_rate * v_share_acres);
          ELSE
            v_chem_qty_b := v_chem_qty_b + (v_rate * v_share_acres);
          END IF;
        END LOOP;

        IF v_chem_qty_a > 0 THEN
          v_qa_unit_cost := COALESCE((v_chem->>'cost_cents')::bigint, 0);
          SELECT * INTO v_conv FROM convert_to_gl_lb(ROUND(v_chem_qty_a, 4), v_ta_unit, v_form);
          INSERT INTO invoice_items (
            invoice_id, product_id, description, quantity, unit_size,
            unit_price_cents, extended_cents, cost_cents,
            sort_order, rate_per_acre, rate_unit,
            is_application_fee, price_source,
            warehouse, vendor, total_applied, total_applied_unit,
            total_applied_gl_lb, gl_lb_unit, epa_registration, product_form
          ) VALUES (
            v_invoice_id,
            (v_chem->>'product_id')::uuid,
            (v_chem->>'description') || ' — included in grower share',
            ROUND(v_chem_qty_a, 4),
            v_chem->>'unit_size',
            0, 0, v_qa_unit_cost,
            COALESCE((v_chem->>'sort_order')::int, 0),
            v_rate,
            v_chem->>'rate_unit',
            false,
            'manual',
            v_wh, v_vendor, ROUND(v_chem_qty_a, 4), v_ta_unit,
            v_conv.converted_value, v_conv.converted_unit, v_epa, v_form
          );
          v_invoice_cost := v_invoice_cost + safe_cents_qty(v_qa_unit_cost, v_chem_qty_a);
        END IF;

        IF v_chem_qty_b > 0 THEN
          v_unit_price   := NULL;
          v_quoted_price := NULL;
          v_price_source := NULL;

          IF v_chem ? 'manual_override' AND (v_chem->>'manual_override')::boolean = true
             AND (v_chem->>'unit_price_cents') IS NOT NULL THEN
            v_unit_price   := (v_chem->>'unit_price_cents')::bigint;
            v_price_source := 'manual';
          END IF;

          IF v_unit_price IS NULL AND (v_chem->>'product_id') IS NOT NULL THEN
            SELECT qi.price_per_unit INTO v_qi_price
              FROM quote_items qi
              JOIN quote_sections qs ON qs.id = qi.section_id
             WHERE qi.product_id = (v_chem->>'product_id')::uuid
               AND qs.field_id   = ANY(v_field_ids)
             ORDER BY qi.id LIMIT 1;
            IF v_qi_price IS NOT NULL THEN
              v_unit_price   := ROUND(v_qi_price * 100)::bigint;
              v_quoted_price := v_unit_price;
              v_price_source := 'quoted';
            END IF;
          END IF;

          IF v_unit_price IS NULL AND (v_chem->>'product_id') IS NOT NULL THEN
            SELECT CASE v_customer_tier
              WHEN 1 THEN COALESCE(ROUND(p.tier1_price * 100), 0)
              WHEN 2 THEN COALESCE(ROUND(p.tier2_price * 100), ROUND(p.tier1_price * 100), 0)
              WHEN 3 THEN COALESCE(ROUND(p.tier3_price * 100), ROUND(p.tier1_price * 100), 0)
              ELSE COALESCE(ROUND(p.tier1_price * 100), 0)
            END INTO v_unit_price
            FROM products p WHERE p.id = (v_chem->>'product_id')::uuid;
            v_price_source := 'tier';
          END IF;

          v_unit_price := COALESCE(v_unit_price, 0);
          v_unit_cost  := COALESCE((v_chem->>'cost_cents')::bigint, 0);

          -- PARKED-010 (field-app billing unit fix): the applied amount (v_chem_qty_b) is in the
          -- RATE unit (e.g. oz), but v_unit_price is per the product's SOLD unit (inventory_unit,
          -- e.g. $/gal). Convert the applied amount into the pricing unit BEFORE multiplying, so a
          -- 16 oz/ac product at $32.10/gal bills $/gal x gallons (not $/gal x ounces = ~128x high).
          -- Manual line (no product_id): no inventory_unit, so price in the rate unit as entered
          -- (identity). If the units genuinely do not convert (e.g. an oz rate on a product sold
          -- "per unit"), refuse rather than silently mis-bill.
          v_priced_qty := field_app_priced_quantity(v_chem_qty_b, v_ta_unit, COALESCE(v_inv_unit, v_ta_unit), v_form);
          IF v_priced_qty IS NULL THEN
            RAISE EXCEPTION 'FIELD_APP_UNIT_UNCONVERTIBLE: cannot price "%" — rate unit "%" does not convert to the product''s sold unit "%". Fix this product''s units before invoicing this field application.',
              COALESCE(NULLIF(v_chem->>'description', ''), (v_chem->>'product_id')), v_ta_unit, COALESCE(v_inv_unit, v_ta_unit);
          END IF;
          -- Round once to the stored precision so quantity x unit_price == extended_cents
          -- (the invoice line stays internally consistent on any later re-compute).
          v_priced_qty := ROUND(v_priced_qty, 4);
          v_extended   := safe_cents_qty(v_unit_price, v_priced_qty);

          SELECT * INTO v_conv FROM convert_to_gl_lb(ROUND(v_chem_qty_b, 4), v_ta_unit, v_form);

          INSERT INTO invoice_items (
            invoice_id, product_id, description, quantity, unit_size,
            unit_price_cents, extended_cents, cost_cents,
            sort_order, rate_per_acre, rate_unit,
            quoted_price_cents, is_application_fee, price_source,
            warehouse, vendor, total_applied, total_applied_unit,
            total_applied_gl_lb, gl_lb_unit, epa_registration, product_form
          ) VALUES (
            v_invoice_id,
            (v_chem->>'product_id')::uuid,
            v_chem->>'description',
            ROUND(v_priced_qty, 4),
            COALESCE(v_inv_unit, v_chem->>'unit_size'),
            v_unit_price, v_extended, v_unit_cost,
            COALESCE((v_chem->>'sort_order')::int, 0),
            v_rate,
            v_chem->>'rate_unit',
            v_quoted_price, false, v_price_source,
            v_wh, v_vendor, ROUND(v_chem_qty_b, 4), v_ta_unit,
            v_conv.converted_value, v_conv.converted_unit, v_epa, v_form
          );

          v_invoice_total := v_invoice_total + v_extended;
          -- PARKED-010: cost (v_unit_cost is also per the SOLD unit) must use the converted
          -- quantity too, otherwise margin = revenue(gallons) - cost(ounces) is wildly wrong.
          v_invoice_cost  := v_invoice_cost + safe_cents_qty(v_unit_cost, v_priced_qty);
        END IF;
      END;
    END LOOP;

    IF p_application_service_id IS NOT NULL THEN
      SELECT car.rate_per_acre_cents INTO v_fee_rate
        FROM customer_application_rates car
       WHERE car.customer_id            = v_customer_id
         AND car.application_service_id = p_application_service_id
         AND car.season                 = current_season()
       LIMIT 1;
      IF v_fee_rate IS NULL THEN v_fee_rate := v_app_service.default_rate_per_acre_cents; END IF;

      SELECT COALESCE(SUM((value->>'share_acres')::numeric), 0)
        INTO v_fee_acres
        FROM jsonb_array_elements(v_shares -> 'rows') AS value
       WHERE (value->>'customer_id')::uuid = v_customer_id
         AND (value->>'price_override_cents') IS NULL;

      IF v_fee_rate > 0 AND v_fee_acres > 0 THEN
        v_fee_extended := safe_cents_qty(v_fee_rate, v_fee_acres);
        v_fee_cost     := safe_cents_qty(v_app_service.cost_per_acre_cents, v_fee_acres);
        INSERT INTO invoice_items (
          invoice_id, description, quantity, unit_price_cents, extended_cents,
          cost_cents, sort_order, acres, rate_per_acre, rate_unit,
          is_application_fee, price_source
        ) VALUES (
          v_invoice_id, v_app_service.name, v_fee_acres,
          v_fee_rate, v_fee_extended, v_fee_cost,
          9999, v_fee_acres, v_fee_rate, 'acre',
          true, 'tier'
        );
        v_invoice_total := v_invoice_total + v_fee_extended;
        v_invoice_cost  := v_invoice_cost + v_fee_cost;
      END IF;
    END IF;

    -- #32: FUEL SURCHARGE LINE (owner-configured; OFF + blank by default = NOTHING here).
    SELECT COALESCE(SUM((value->>'share_acres')::numeric), 0)
      INTO v_surcharge_acres
      FROM jsonb_array_elements(v_shares -> 'rows') AS value
     WHERE (value->>'customer_id')::uuid = v_customer_id
       AND (value->>'price_override_cents') IS NULL;

    v_surcharge_cents := compute_fuel_surcharge_cents(v_surcharge_acres, v_invoice_total);

    IF v_surcharge_cents > 0 THEN
      INSERT INTO invoice_items (
        invoice_id, description, quantity, unit_price_cents, extended_cents,
        cost_cents, sort_order, acres, rate_per_acre, rate_unit,
        is_application_fee, price_source
      ) VALUES (
        v_invoice_id, 'Fuel Surcharge', 1,
        v_surcharge_cents, v_surcharge_cents, 0,
        9998, NULL, NULL, NULL,
        true, 'manual'
      );
      v_invoice_total := v_invoice_total + v_surcharge_cents;
    END IF;
    -- #32 END

    UPDATE invoices SET
      total_amount_cents = v_invoice_total,
      total_cost_cents   = v_invoice_cost,
      updated_at         = now()
    WHERE id = v_invoice_id;

    IF v_is_new_invoice THEN
      INSERT INTO financial_audit_log (
        operation_type, entity_type, entity_id, actor_role,
        new_values, total_impact_cents, description
      ) VALUES (
        'invoice_created', 'invoice', v_invoice_id,
        (SELECT role FROM profiles WHERE id = v_actor),
        jsonb_build_object(
          'invoice_number', (SELECT invoice_number FROM invoices WHERE id = v_invoice_id),
          'customer_id', v_customer_id,
          'total_cents', v_invoice_total
        ),
        v_invoice_total,
        'Field application invoice created'
      );
    END IF;

    SELECT COALESCE(SUM((value->>'share_acres')::numeric), 0)
      INTO v_total_share_acres
      FROM jsonb_array_elements(v_shares -> 'rows') AS value
     WHERE (value->>'customer_id')::uuid = v_customer_id;

    INSERT INTO invoice_shares (
      invoice_id, customer_id, customer_name,
      split_percentage, acres, amount_cents,
      is_primary, sort_order,
      price_per_acre_cents, pricing_note
    ) VALUES (
      v_invoice_id, v_customer_id, v_customer_name,
      100.0, v_total_share_acres, v_invoice_total,
      v_is_primary, 0,
      CASE WHEN v_has_override
        THEN (SELECT (value->>'price_override_cents')::bigint
              FROM jsonb_array_elements(v_shares -> 'rows') AS value
              WHERE (value->>'customer_id')::uuid = v_customer_id
                AND (value->>'price_override_cents') IS NOT NULL LIMIT 1)
        ELSE NULL
      END,
      CASE WHEN v_has_override
        THEN (SELECT (value->>'pricing_note')
              FROM jsonb_array_elements(v_shares -> 'rows') AS value
              WHERE (value->>'customer_id')::uuid = v_customer_id
                AND (value->>'price_override_cents') IS NOT NULL LIMIT 1)
        ELSE NULL
      END
    );
  END LOOP;

  FOR v_loc IN SELECT * FROM jsonb_array_elements(p_locations)
  LOOP
    INSERT INTO field_app_locations (
      invoice_id, invoice_group_id,
      field_id, map_number, total_acres, planted_acres,
      applied_acres, crop_type, wind_direction, sort_order
    ) VALUES (
      CASE WHEN v_invoice_group_id IS NULL THEN v_invoice_ids[1] ELSE NULL END,
      v_invoice_group_id,
      (v_loc->>'field_id')::uuid,
      (v_loc->>'map_number')::int,
      (v_loc->>'total_acres')::numeric,
      (v_loc->>'planted_acres')::numeric,
      (v_loc->>'applied_acres')::numeric,
      v_loc->>'crop_type',
      v_loc->>'wind_direction',
      COALESCE((v_loc->>'sort_order')::int, 0)
    ) RETURNING id INTO v_loc_id;

    FOR v_share_row IN
      SELECT * FROM jsonb_array_elements(v_shares -> 'rows') AS value
      WHERE (value->>'field_id')::uuid = (v_loc->>'field_id')::uuid
        AND NOT ((value->>'customer_id')::uuid = ANY(v_skipped_customer_ids))
    LOOP
      INSERT INTO field_app_location_shares (
        location_id, customer_id, split_pct, acres, amount_cents
      ) VALUES (
        v_loc_id,
        (v_share_row->>'customer_id')::uuid,
        (v_share_row->>'split_pct')::numeric,
        (v_share_row->>'share_acres')::numeric,
        0
      );
    END LOOP;
  END LOOP;

  INSERT INTO activity_feed (
    event_type, description, performed_by, related_entity_type, related_entity_id
  ) VALUES (
    CASE WHEN p_invoice_id IS NULL THEN 'field_app_invoice_created' ELSE 'field_app_invoice_updated' END,
    'Field app invoice ' ||
      CASE WHEN v_invoice_group_id IS NOT NULL
           THEN '(group of ' || v_customer_count || ') '
           ELSE '' END ||
      'saved with ' || array_length(v_invoice_ids, 1) || ' invoice(s)',
    p_performed_by, 'invoice', v_invoice_ids[1]
  );

  v_result := jsonb_build_object(
    'invoice_ids',      to_jsonb(v_invoice_ids),
    'invoice_group_id', v_invoice_group_id
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'save_field_app_invoice', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."_save_field_app_invoice_impl_20260714"("p_invoice_id" "uuid", "p_invoice" "jsonb", "p_locations" "jsonb", "p_chemicals" "jsonb", "p_performed_by" "uuid", "p_application_service_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_save_invoice_scoped_impl"("p_invoice" "jsonb", "p_items" "jsonb" DEFAULT '[]'::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := auth.uid(); v_invoice_id uuid; v_is_new boolean := false; v_item jsonb;
  v_total_cents bigint := 0; v_qty numeric; v_unit_price bigint; v_extended bigint;
  v_cost_cents bigint; v_product record; v_order_id uuid; v_blend_id uuid; v_existing jsonb;
  v_total_cost bigint := 0;
  v_is_field boolean := false;
  v_is_fee boolean;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'Not authorized: admin or sales role required to save invoices';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'save_invoice');
    IF v_existing IS NOT NULL THEN RETURN (v_existing->>'invoice_id')::uuid; END IF;
  END IF;

  v_invoice_id := (p_invoice->>'id')::uuid;
  v_order_id := (p_invoice->>'order_id')::uuid;
  v_blend_id := (p_invoice->>'blend_ticket_id')::uuid;

  IF v_invoice_id IS NULL THEN
    -- PARKED-002 (codex-driven cycle 1 #1 MED): credit memos must come exclusively
    -- from issue_return_credit (the ONLY caller that derives the credit from a
    -- 'received' return and gates on check_period_open). save_invoice's NEW-invoice
    -- branch otherwise allows an admin/sales-rep to forge a posted credit memo by
    -- riding on the enforce_invoice_draft_on_insert credit_memo exemption. Reject
    -- BEFORE the order/blend check so the error surfaced is the intent-mismatch one.
    IF (p_invoice->>'invoice_type') = 'credit_memo' THEN
      RAISE EXCEPTION 'CREDIT_MEMO_VIA_SAVE_INVOICE: credit memos can only be created via issue_return_credit (from a received Return)';
    END IF;
    -- Manual miscellaneous charges are the one controlled orderless invoice
    -- type. Chemical sales still require a source order/blend ticket.
    IF v_order_id IS NULL
       AND v_blend_id IS NULL
       AND COALESCE(NULLIF(p_invoice->>'invoice_type', ''), 'chemical_sale') <> 'misc_charge' THEN
      RAISE EXCEPTION 'Invoices must link to an order or blend ticket. Provide order_id or blend_ticket_id in p_invoice payload.';
    END IF;
    IF COALESCE(NULLIF(p_invoice->>'invoice_type', ''), 'chemical_sale') = 'misc_charge'
       AND COALESCE(NULLIF(p_invoice->>'status', ''), 'draft') <> 'draft' THEN
      RAISE EXCEPTION 'MISC_CHARGE_MUST_START_DRAFT: orderless miscellaneous charges must be reviewed before posting';
    END IF;
    v_is_new := true;
    INSERT INTO invoices (order_id, blend_ticket_id, customer_id, invoice_type, status, season, salesman_id,
      invoice_date, due_date, purchase_order_ref, header_notes, footer_notes, total_amount_cents, created_by)
    VALUES (v_order_id, v_blend_id, (p_invoice->>'customer_id')::uuid,
      COALESCE(p_invoice->>'invoice_type', 'chemical_sale'),
      COALESCE(p_invoice->>'status', 'draft'),
      COALESCE((p_invoice->>'season')::int, (SELECT current_season())),
      (p_invoice->>'salesman_id')::uuid,
      COALESCE((p_invoice->>'invoice_date')::date, CURRENT_DATE),
      (p_invoice->>'due_date')::date,
      p_invoice->>'purchase_order_ref',
      p_invoice->>'header_notes',
      p_invoice->>'footer_notes',
      0, v_actor) RETURNING id INTO v_invoice_id;
  ELSE
    -- An orderless miscellaneous charge must remain a miscellaneous charge.
    -- The edit payload does not carry source IDs, so enforce this against the
    -- stored invoice rather than trusting the client to keep the type locked.
    IF EXISTS (
      SELECT 1
       FROM invoices
       WHERE id = v_invoice_id
         AND invoice_type = 'misc_charge'
         AND order_id IS NULL
         AND blend_ticket_id IS NULL
         AND COALESCE(NULLIF(p_invoice->>'invoice_type', ''), invoice_type) <> 'misc_charge'
    ) THEN
      RAISE EXCEPTION 'ORDERLESS_INVOICE_TYPE_LOCKED: an orderless miscellaneous charge cannot be reclassified';
    END IF;

    -- PARKED-002 (Codex r3): EXPLICIT pre-UPDATE guard on the credit_memo boundary.
    -- A silent CASE-keep would swallow an attempted chemical_sale -> credit_memo flip
    -- (other payload fields still save) so the caller never sees the rejection. Fail
    -- LOUDLY with CREDIT_MEMO_VIA_SAVE_INVOICE whenever OLD or NEW crosses 'credit_memo'.
    -- Mirrors how enforce_field_application_type_lock errors on its boundary cross,
    -- except this is RPC-side because credit_memo is born 'posted' and the trigger only
    -- fires on UPDATE OF invoice_type (a posted credit_memo never gets here at all).
    -- PARKED-002 (Codex r4): drop the status filter — surface the boundary cross even
    -- when the target invoice is posted/voided/etc. The existing post-UPDATE
    -- "NOT EXISTS ... status IN ('draft','unposted')" path would otherwise silently
    -- no-op a posted-invoice credit_memo attempt; the caller deserves a clear error.
    IF EXISTS (
      SELECT 1 FROM invoices
       WHERE id = v_invoice_id
         AND (
              invoice_type = 'credit_memo'
           OR COALESCE(p_invoice->>'invoice_type', invoice_type) = 'credit_memo'
         )
         AND invoice_type IS DISTINCT FROM COALESCE(p_invoice->>'invoice_type', invoice_type)
    ) THEN
      RAISE EXCEPTION 'CREDIT_MEMO_VIA_SAVE_INVOICE: credit memos can only be created via issue_return_credit (from a received Return)';
    END IF;

    UPDATE invoices SET
      customer_id = CASE WHEN invoice_type = 'field_application'
                         THEN customer_id
                         ELSE COALESCE((p_invoice->>'customer_id')::uuid, customer_id) END,
      -- PARKED-002 (Codex r2): symmetric lock — credit_memo is a SEGREGATION boundary like
      -- field_application. The pre-UPDATE guard above ALREADY rejected any cross-boundary
      -- attempt with CREDIT_MEMO_VIA_SAVE_INVOICE; this CASE is the second-line invariant
      -- so a bug in the guard can't silently let the column flip. Stacks on top of DELTA-F.
      invoice_type = CASE
        WHEN invoice_type = 'field_application'
          OR COALESCE(p_invoice->>'invoice_type', invoice_type) = 'field_application'
        THEN invoice_type
        WHEN invoice_type = 'credit_memo'
          OR COALESCE(p_invoice->>'invoice_type', invoice_type) = 'credit_memo'
        THEN invoice_type
        ELSE COALESCE(p_invoice->>'invoice_type', invoice_type) END,
      season = COALESCE((p_invoice->>'season')::int, season),
      salesman_id = (p_invoice->>'salesman_id')::uuid,
      invoice_date = COALESCE((p_invoice->>'invoice_date')::date, invoice_date),
      due_date = (p_invoice->>'due_date')::date,
      purchase_order_ref = p_invoice->>'purchase_order_ref',
      header_notes = p_invoice->>'header_notes',
      footer_notes = p_invoice->>'footer_notes',
      updated_at = now()
    WHERE id = v_invoice_id AND status IN ('draft', 'unposted');
  END IF;

  IF NOT v_is_new THEN
    IF NOT EXISTS (SELECT 1 FROM invoices WHERE id = v_invoice_id AND status IN ('draft', 'unposted')) THEN
      IF p_idempotency_key IS NOT NULL THEN
        PERFORM save_idempotency(p_idempotency_key, 'save_invoice', jsonb_build_object('invoice_id', v_invoice_id, 'no_op', true));
      END IF;
      RETURN v_invoice_id;
    END IF;
  END IF;

  v_is_field := (SELECT invoice_type FROM invoices WHERE id = v_invoice_id) = 'field_application';

  IF (SELECT invoice_type FROM invoices WHERE id = v_invoice_id) = 'field_application' THEN
    DECLARE v_share_n int; v_has_ovr boolean;
    BEGIN
      SELECT count(*), COALESCE(bool_or(price_per_acre_cents IS NOT NULL), false)
        INTO v_share_n, v_has_ovr
        FROM invoice_shares WHERE invoice_id = v_invoice_id;
      IF v_share_n > 1 OR v_has_ovr THEN
        RAISE EXCEPTION 'FIELD_INVOICE_SPLIT_LOCKED: this field invoice is split across growers (or has a fixed-price grower) — void and reissue to change it';
      END IF;
    END;
  END IF;

  DELETE FROM invoice_items WHERE invoice_id = v_invoice_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_qty := COALESCE((v_item->>'quantity')::numeric, 0);
    IF v_qty <= 0 THEN RAISE EXCEPTION 'Invoice line item quantity must be greater than zero'; END IF;
    v_unit_price := COALESCE((v_item->>'unit_price_cents')::bigint, 0);
    v_is_fee := COALESCE((v_item->>'is_application_fee')::boolean, false) AND (v_item->>'product_id') IS NULL;
    v_extended := ROUND(v_qty * v_unit_price)::bigint;
    IF v_is_fee
       AND (v_item->>'extended_cents') IS NOT NULL
       AND ABS((v_item->>'extended_cents')::bigint - v_extended) <= CEIL(v_qty)::bigint + 1 THEN
      v_extended := (v_item->>'extended_cents')::bigint;
    END IF;
    v_cost_cents := COALESCE((v_item->>'cost_cents')::bigint, 0);
    IF (v_item->>'product_id') IS NOT NULL AND NOT v_is_field THEN
      SELECT * INTO v_product FROM products WHERE id = (v_item->>'product_id')::uuid;
      IF FOUND AND v_product.current_cost IS NOT NULL THEN
        v_cost_cents := (v_product.current_cost * 100)::bigint;
      END IF;
    END IF;
    INSERT INTO invoice_items (invoice_id, product_id, description, quantity, unit_price_cents, extended_cents,
      cost_cents, sort_order, rate_per_acre, acres, unit_size, notes,
      rate_unit, is_application_fee, total_applied, total_applied_unit,
      total_applied_gl_lb, gl_lb_unit, epa_registration, product_form,
      price_source, quoted_price_cents)
    VALUES (v_invoice_id, (v_item->>'product_id')::uuid,
      COALESCE(v_item->>'description', ''),
      v_qty, v_unit_price, v_extended, v_cost_cents,
      COALESCE((v_item->>'sort_order')::int, 0),
      (v_item->>'rate_per_acre')::numeric, (v_item->>'acres')::numeric,
      v_item->>'unit_size', v_item->>'notes',
      v_item->>'rate_unit',
      v_is_fee,
      (v_item->>'total_applied')::numeric,
      v_item->>'total_applied_unit',
      (v_item->>'total_applied_gl_lb')::numeric,
      v_item->>'gl_lb_unit',
      v_item->>'epa_registration',
      v_item->>'product_form',
      CASE WHEN v_item->>'price_source' IN ('quoted','tier','manual') THEN v_item->>'price_source' ELSE NULL END,
      (v_item->>'quoted_price_cents')::bigint);
    v_total_cents := v_total_cents + v_extended;
    v_total_cost := v_total_cost + CASE
      WHEN v_is_fee THEN v_cost_cents
      ELSE ROUND(v_cost_cents * v_qty)::bigint END;
  END LOOP;

  UPDATE invoices SET total_amount_cents = v_total_cents,
    total_cost_cents = CASE WHEN invoice_type = 'field_application' THEN v_total_cost ELSE total_cost_cents END,
    updated_at = now()
  WHERE id = v_invoice_id AND status IN ('draft', 'unposted');

  IF (SELECT invoice_type FROM invoices WHERE id = v_invoice_id) = 'field_application' THEN
    WITH s AS (
      SELECT id, COALESCE(amount_cents, 0) AS amount_cents,
             row_number() OVER (ORDER BY is_primary DESC, sort_order, id) AS rn,
             SUM(COALESCE(amount_cents, 0)) OVER () AS tot
      FROM invoice_shares WHERE invoice_id = v_invoice_id
    ),
    alloc AS (
      SELECT id, rn,
             CASE WHEN tot > 0 THEN ROUND(v_total_cents * amount_cents / tot)::bigint
                  WHEN rn = 1 THEN v_total_cents ELSE 0 END AS part
      FROM s
    ),
    recon AS (
      SELECT id, rn, part, v_total_cents - COALESCE(SUM(part) OVER (), 0) AS rem
      FROM alloc
    )
    UPDATE invoice_shares isr
       SET amount_cents = r.part + CASE WHEN r.rn = 1 THEN r.rem ELSE 0 END
      FROM recon r WHERE isr.id = r.id;
  END IF;

  -- U8<<< (Codex R2 P1): a job-born field_application invoice stays editable while
  -- draft/unposted, and the items rewrite above changes chemical-line profit without
  -- touching the pending job commissions minted at transfer time. Recompute them from
  -- the just-written lines — the exact mirror of update_order_items' commission-
  -- recompute-on-edit (20260617040000), including its batch-freeze guard. Scoped by
  -- commissions.invoice_id (generation-precise): order-channel rows and other
  -- generations are untouched, and a non-job invoice simply matches zero rows.
  IF (SELECT invoice_type FROM invoices WHERE id = v_invoice_id) = 'field_application' THEN
    DECLARE
      v_u8_profit numeric;
    BEGIN
      -- Codex R6 P2: an edit while any of this generation's pending commissions sit
      -- in an active payout batch would leave that batch stale (post_commission_payment
      -- pays the OLD amount) — block, mirroring the reversal paths' guard.
      IF EXISTS (
        SELECT 1 FROM commissions c
        JOIN commission_payment_items cpi ON cpi.commission_id = c.id
        JOIN commission_payments cp ON cp.id = cpi.commission_payment_id
        WHERE c.invoice_id = v_invoice_id AND c.job_id IS NOT NULL
          AND c.status = 'pending' AND cp.status <> 'voided'
      ) THEN
        RAISE EXCEPTION 'JOB_HAS_BATCHED_COMMISSIONS: this invoice''s pending commissions are in an active payout batch — void that commission payment before editing';
      END IF;
      -- Codex R7 P1: commissions already PAID against this still-unposted invoice
      -- must also block the edit — the recompute below only touches pending rows,
      -- so an edit would silently strand the paid ledger on the old profit. Fully
      -- recoverable: void the commission payment (rows reset to pending because
      -- this invoice is live), edit, then re-batch.
      IF EXISTS (
        SELECT 1 FROM commissions c
        WHERE c.invoice_id = v_invoice_id AND c.job_id IS NOT NULL AND c.status = 'paid'
      ) THEN
        RAISE EXCEPTION 'JOB_COMMISSIONS_PAID: this invoice''s commissions were already paid out — void that commission payment before editing the invoice';
      END IF;

      -- Codex R6 P2: COGS per line is cost_cents × quantity (save_invoice stores
      -- per-unit cost — the SAME math its own v_total_cost uses); transfer-minted
      -- lines carry quantity=1 with line-total cost, so ×1 is identical there.
      SELECT COALESCE(SUM(COALESCE(ii.extended_cents, 0) - ROUND(COALESCE(ii.cost_cents, 0) * COALESCE(ii.quantity, 1))::bigint), 0)::numeric / 100.0
        INTO v_u8_profit
      FROM invoice_items ii
      WHERE ii.invoice_id = v_invoice_id
        AND COALESCE(ii.is_application_fee, false) = false
        AND ii.product_id IS NOT NULL;

      UPDATE commissions c
         SET order_profit      = ROUND(COALESCE(v_u8_profit, 0), 2),
             commission_amount = calc.new_amount
        FROM (
          SELECT x.id,
                 -- Codex R5 P2: mirror the mint's last-row penny reconciliation so the
                 -- recomputed rows sum EXACTLY to the rounded profit (a 33.33/33.33/33.34
                 -- split of $0.02 must not round up to $0.03). Only safe when the eligible
                 -- pending rows ARE the whole generation (x.cnt = x.cnt_all, and cnt_all
                 -- counts EVERY non-deleted row of the generation regardless of status —
                 -- drift-review R6 H1: a sibling already PAID via a posted batch must
                 -- force the per-row fallback, or the last pending row would absorb the
                 -- paid recipient's entire share, not a penny). The mixed case keeps the
                 -- per-row math (update_order_items parity).
                 CASE WHEN x.rn = x.cnt AND x.cnt = x.cnt_all THEN
                     GREATEST(ROUND(COALESCE(v_u8_profit, 0), 2), 0)
                     - COALESCE(SUM(compute_commission_amount(v_u8_profit, x.split_percentage))
                         OVER (ORDER BY x.rn ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0)
                   ELSE compute_commission_amount(v_u8_profit, x.split_percentage)
                 END AS new_amount
          FROM (
            SELECT c2.id, c2.split_percentage,
                   row_number() OVER (ORDER BY c2.id) AS rn,
                   count(*) OVER () AS cnt,
                   (SELECT count(*) FROM commissions c3
                     WHERE c3.invoice_id = v_invoice_id AND c3.job_id IS NOT NULL
                       AND c3.deleted_at IS NULL) AS cnt_all
            FROM commissions c2
            WHERE c2.invoice_id = v_invoice_id
              AND c2.job_id IS NOT NULL
              AND c2.status = 'pending'
              AND c2.deleted_at IS NULL
              AND NOT EXISTS (
                SELECT 1 FROM commission_payment_items cpi
                JOIN commission_payments cp ON cp.id = cpi.commission_payment_id
                WHERE cpi.commission_id = c2.id AND cp.status <> 'voided'
              )
          ) x
        ) calc
       WHERE c.id = calc.id;
    END;
  END IF;
  -- >>>U8

  IF v_is_new THEN
    INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
    VALUES ('invoice_created',
      'Invoice ' || (SELECT invoice_number FROM invoices WHERE id = v_invoice_id) || ' created',
      v_actor, 'invoice', v_invoice_id, (p_invoice->>'customer_id')::uuid);
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'save_invoice', jsonb_build_object('invoice_id', v_invoice_id, 'is_new', v_is_new));
  END IF;

  RETURN v_invoice_id;
END;
$_$;


ALTER FUNCTION "public"."_save_invoice_scoped_impl"("p_invoice" "jsonb", "p_items" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_save_invoice_scoped_impl"("p_invoice" "jsonb", "p_items" "jsonb", "p_idempotency_key" "text") IS 'Internal invoice writer. Direct execution is revoked; use public.save_invoice so active-role and customer scope checks run before replay lookup.';



CREATE OR REPLACE FUNCTION "public"."_save_invoice_split_provenance_impl_20260719"("p_invoice" "jsonb", "p_items" "jsonb" DEFAULT '[]'::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_role text;
  v_invoice_id uuid := NULLIF(p_invoice->>'id', '')::uuid;
  v_existing_customer_id uuid;
  v_requested_customer_id uuid := NULLIF(p_invoice->>'customer_id', '')::uuid;
  v_target_customer_id uuid;
  v_requested_salesman_id uuid := NULLIF(p_invoice->>'salesman_id', '')::uuid;
  v_cached jsonb;
  v_cached_invoice_id uuid;
  v_cached_customer_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;

  SELECT role
    INTO v_actor_role
    FROM public.profiles
   WHERE id = v_actor
     AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('save_invoice:' || p_idempotency_key, 0)
    );
    v_cached := public.check_idempotency(p_idempotency_key, 'save_invoice');
    IF v_cached IS NOT NULL THEN
      v_cached_invoice_id := NULLIF(v_cached->>'invoice_id', '')::uuid;
      IF v_cached_invoice_id IS NULL THEN
        RAISE EXCEPTION 'IDEMPOTENCY_RESULT_INVALID';
      END IF;
      IF v_invoice_id IS NOT NULL
         AND v_invoice_id IS DISTINCT FROM v_cached_invoice_id THEN
        RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_CONFLICT';
      END IF;

      SELECT customer_id
        INTO v_cached_customer_id
        FROM public.invoices
       WHERE id = v_cached_invoice_id
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'INVOICE_NOT_FOUND';
      END IF;
      IF v_requested_customer_id IS NOT NULL
         AND v_requested_customer_id IS DISTINCT FROM v_cached_customer_id THEN
        RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_CONFLICT';
      END IF;
      IF v_actor_role = 'sales_rep'
         AND NOT EXISTS (
           SELECT 1
             FROM public.customers
            WHERE id = v_cached_customer_id
              AND assigned_sales_rep = v_actor
         ) THEN
        RAISE EXCEPTION 'CUSTOMER_SCOPE_DENIED';
      END IF;
      RETURN v_cached_invoice_id;
    END IF;
  END IF;

  IF v_invoice_id IS NOT NULL THEN
    SELECT customer_id
      INTO v_existing_customer_id
      FROM public.invoices
     WHERE id = v_invoice_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'INVOICE_NOT_FOUND';
    END IF;
  END IF;

  v_target_customer_id := COALESCE(
    v_requested_customer_id,
    v_existing_customer_id
  );
  IF v_target_customer_id IS NULL THEN
    RAISE EXCEPTION 'CUSTOMER_REQUIRED';
  END IF;

  IF v_actor_role = 'sales_rep' THEN
    IF v_existing_customer_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
           FROM public.customers
          WHERE id = v_existing_customer_id
            AND assigned_sales_rep = v_actor
       ) THEN
      RAISE EXCEPTION 'CUSTOMER_SCOPE_DENIED';
    END IF;
    IF NOT EXISTS (
      SELECT 1
        FROM public.customers
       WHERE id = v_target_customer_id
         AND assigned_sales_rep = v_actor
    ) THEN
      RAISE EXCEPTION 'CUSTOMER_SCOPE_DENIED';
    END IF;
    IF v_requested_salesman_id IS NOT NULL
       AND v_requested_salesman_id IS DISTINCT FROM v_actor THEN
      RAISE EXCEPTION 'SALESMAN_SCOPE_DENIED';
    END IF;
  END IF;

  RETURN public._save_invoice_scoped_impl(
    p_invoice,
    p_items,
    p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."_save_invoice_split_provenance_impl_20260719"("p_invoice" "jsonb", "p_items" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_save_invoice_split_provenance_impl_20260719"("p_invoice" "jsonb", "p_items" "jsonb", "p_idempotency_key" "text") IS 'Saves an invoice for an active admin or for an active sales rep assigned to both the stored and requested customer.';



CREATE OR REPLACE FUNCTION "public"."_save_purchase_order_ascii_identity_impl"("p_po_id" "uuid", "p_po_payload" "jsonb", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_payload jsonb := COALESCE(p_po_payload, '{}'::jsonb);
  v_result jsonb;
  v_po_number text;
  v_bulk_import_requested boolean :=
    NULLIF(btrim(v_payload->>'bulk_import_intent_key'), '') IS NOT NULL;
  v_bulk_intent_key text;
  v_requested_vendor text := NULLIF(btrim(v_payload->>'vendor'), '');
  v_vendor_reference text := NULLIF(btrim(v_payload->>'bulk_import_vendor_reference'), '');
  v_invoice_date text := NULLIF(btrim(v_payload->>'bulk_import_invoice_date'), '');
  v_identity_vendor text;
  v_identity_vendor_reference text;
  v_expected_intent_key text;
  v_canonical_items jsonb;
  v_content_fingerprint text;
  v_existing_po_id uuid;
  v_existing_intent_key text;
  v_existing_content_fingerprint text;
  v_cached jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH: p_performed_by must match auth.uid()'
      USING ERRCODE = 'P0001';
  END IF;
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'Only admins or sales reps can manage purchase orders';
  END IF;

  IF v_bulk_import_requested THEN
    IF v_requested_vendor IS NULL THEN
      RAISE EXCEPTION 'BULK_PO_VENDOR_REQUIRED';
    END IF;
    IF v_vendor_reference IS NULL THEN
      RAISE EXCEPTION 'BULK_PO_VENDOR_REFERENCE_REQUIRED';
    END IF;

    v_identity_vendor := normalize(
      lower(normalize(v_requested_vendor, NFKC)),
      NFKC
    );
    v_identity_vendor_reference := normalize(
      lower(normalize(v_vendor_reference, NFKC)),
      NFKC
    );

    IF p_po_id IS NOT NULL
       OR p_idempotency_key IS NULL
       OR length(v_vendor_reference) > 512
       OR strpos(v_identity_vendor, chr(31)) > 0
       OR strpos(v_identity_vendor_reference, chr(31)) > 0 THEN
      RAISE EXCEPTION 'BULK_PO_INTENT_INVALID';
    END IF;
    IF jsonb_typeof(p_items) IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_items) = 0 THEN
      RAISE EXCEPTION 'PO_ITEMS_REQUIRED';
    END IF;

    v_expected_intent_key := 'bulk-po-document:' || encode(
      extensions.digest(
        convert_to(
          v_identity_vendor || chr(31) || v_identity_vendor_reference,
          'UTF8'
        ),
        'sha256'
      ),
      'hex'
    );
    v_bulk_intent_key := v_expected_intent_key;

    SELECT COALESCE(
      jsonb_agg(item.value ORDER BY item.value::text),
      '[]'::jsonb
    )
      INTO v_canonical_items
      FROM jsonb_array_elements(p_items) AS item(value);

    v_content_fingerprint := encode(
      extensions.digest(
        convert_to(
          jsonb_build_object(
            'invoice_date', v_invoice_date,
            'items', v_canonical_items
          )::text,
          'UTF8'
        ),
        'sha256'
      ),
      'hex'
    );

    -- Replace any legacy browser digest with the server-derived key consumed
    -- by the atomic writer's claim insert. The marker itself is not persisted.
    v_payload := jsonb_set(
      jsonb_set(
        jsonb_set(
          v_payload - 'bulk_import_document',
          '{bulk_import_intent_key}',
          to_jsonb(v_bulk_intent_key),
          true
        ),
        '{vendor}',
        to_jsonb(v_requested_vendor),
        true
      ),
      '{bulk_import_vendor_reference}',
      to_jsonb(v_vendor_reference),
      true
    );
  END IF;

  -- A committed same-key replay is valid only for the exact server-derived
  -- document identity and reviewed content. Do not compare the PO's mutable
  -- current vendor: an edit after commit must not break a lost-response retry.
  IF p_idempotency_key IS NOT NULL THEN
    v_cached := public.check_idempotency(
      p_idempotency_key,
      'save_purchase_order'
    );
    IF v_cached IS NOT NULL THEN
      v_existing_po_id := NULLIF(v_cached->>'po_id', '')::uuid;
      IF v_existing_po_id IS NULL THEN
        RAISE EXCEPTION 'SAVE_PURCHASE_ORDER_RESULT_INVALID';
      END IF;
      IF p_po_id IS NOT NULL AND p_po_id IS DISTINCT FROM v_existing_po_id THEN
        RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_CONFLICT';
      END IF;

      SELECT po.po_number
        INTO v_po_number
        FROM public.purchase_orders AS po
       WHERE po.id = v_existing_po_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Purchase order not found after save: %', v_existing_po_id;
      END IF;

      IF v_bulk_intent_key IS NOT NULL THEN
        SELECT claim.intent_key, claim.content_fingerprint
          INTO v_existing_intent_key, v_existing_content_fingerprint
          FROM public.purchase_order_import_intents AS claim
         WHERE claim.purchase_order_id = v_existing_po_id;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'BULK_PO_IMPORT_CLAIM_MISSING';
        END IF;
        IF v_existing_intent_key IS DISTINCT FROM v_bulk_intent_key THEN
          RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_CONFLICT';
        END IF;
        IF v_existing_content_fingerprint IS DISTINCT FROM v_content_fingerprint THEN
          RAISE EXCEPTION 'BULK_PO_DOCUMENT_CONTENT_CONFLICT';
        END IF;
      END IF;

      RETURN v_cached || jsonb_build_object('po_number', v_po_number);
    END IF;
  END IF;

  IF v_bulk_intent_key IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('bulk_po:' || v_bulk_intent_key, 0)
    );
    SELECT
      claim.purchase_order_id,
      po.po_number,
      claim.content_fingerprint
      INTO
        v_existing_po_id,
        v_po_number,
        v_existing_content_fingerprint
      FROM public.purchase_order_import_intents AS claim
      JOIN public.purchase_orders AS po
        ON po.id = claim.purchase_order_id
     WHERE claim.intent_key = v_bulk_intent_key;
    IF FOUND THEN
      IF v_existing_content_fingerprint IS DISTINCT FROM v_content_fingerprint THEN
        RAISE EXCEPTION 'BULK_PO_DOCUMENT_CONTENT_CONFLICT';
      END IF;
      RETURN jsonb_build_object(
        'status', 'already_imported',
        'po_id', v_existing_po_id,
        'po_number', v_po_number
      );
    END IF;
  END IF;

  IF p_po_id IS NULL THEN
    v_po_number := public.next_po_number();
    v_payload := jsonb_set(
      v_payload,
      '{po_number}',
      to_jsonb(v_po_number),
      true
    );
  END IF;

  v_result := public._save_purchase_order_atomic_number_impl(
    p_po_id,
    v_payload,
    p_items,
    p_performed_by,
    p_idempotency_key
  );

  IF NULLIF(v_result->>'po_id', '') IS NOT NULL THEN
    v_existing_po_id := (v_result->>'po_id')::uuid;
    SELECT po_number
      INTO v_po_number
      FROM public.purchase_orders
     WHERE id = v_existing_po_id;
    IF v_po_number IS NOT NULL THEN
      v_result := v_result || jsonb_build_object('po_number', v_po_number);
    END IF;
  END IF;

  IF v_bulk_intent_key IS NOT NULL THEN
    UPDATE public.purchase_order_import_intents
       SET content_fingerprint = v_content_fingerprint
     WHERE purchase_order_id = v_existing_po_id
       AND intent_key = v_bulk_intent_key;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'BULK_PO_IMPORT_CLAIM_MISSING';
    END IF;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."_save_purchase_order_ascii_identity_impl"("p_po_id" "uuid", "p_po_payload" "jsonb", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_save_purchase_order_ascii_identity_impl"("p_po_id" "uuid", "p_po_payload" "jsonb", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Internal directly non-executable purchase-order writer. PostgreSQL derives the durable Unicode bulk identity, passes it to the atomic claim insert, and binds replay to reviewed content.';



CREATE OR REPLACE FUNCTION "public"."_save_purchase_order_atomic_number_impl"("p_po_id" "uuid", "p_po_payload" "jsonb", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_hydrated_items jsonb;
  v_result jsonb;
  v_result_po_id uuid;
  v_result_po_number text;
  v_bulk_intent_key text := NULLIF(btrim(p_po_payload->>'bulk_import_intent_key'), '');
  v_cached jsonb;
  v_stored_total_cents bigint;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH: p_performed_by must match auth.uid()'
      USING ERRCODE = 'P0001';
  END IF;
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'Only admins or sales reps can manage purchase orders';
  END IF;

  -- Generic request replay remains scoped to the caller-provided key.
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('save_purchase_order:' || p_idempotency_key, 0)
    );
    v_cached := public.check_idempotency(
      p_idempotency_key,
      'save_purchase_order'
    );
    IF v_cached IS NOT NULL THEN
      v_result_po_id := NULLIF(v_cached->>'po_id', '')::uuid;
      IF p_po_id IS NOT NULL AND p_po_id IS DISTINCT FROM v_result_po_id THEN
        RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_CONFLICT';
      END IF;
      RETURN v_cached;
    END IF;
  END IF;

  IF v_bulk_intent_key IS NOT NULL THEN
    IF p_po_id IS NOT NULL OR p_idempotency_key IS NULL THEN
      RAISE EXCEPTION 'BULK_PO_INTENT_INVALID';
    END IF;
    IF length(v_bulk_intent_key) > 512 THEN
      RAISE EXCEPTION 'BULK_PO_INTENT_INVALID';
    END IF;

    -- Serialize and look up by document identity alone. The actor is retained
    -- only as provenance for the employee who created the first PO.
    PERFORM pg_advisory_xact_lock(
      hashtextextended('bulk_po:' || v_bulk_intent_key, 0)
    );
    SELECT claim.purchase_order_id, po.po_number
      INTO v_result_po_id, v_result_po_number
      FROM public.purchase_order_import_intents AS claim
      JOIN public.purchase_orders AS po
        ON po.id = claim.purchase_order_id
     WHERE claim.intent_key = v_bulk_intent_key;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'status', 'already_imported',
        'po_id', v_result_po_id,
        'po_number', v_result_po_number
      );
    END IF;
  END IF;

  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'PO_ITEMS_REQUIRED';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_items) AS item
     WHERE NULLIF(item->>'product_id', '') IS NULL
        OR NULLIF(item->>'quantity_ordered', '') IS NULL
        OR (item->>'quantity_ordered')::numeric <= 0
  ) THEN
    RAISE EXCEPTION 'PO_ITEM_INVALID: product and positive quantity are required';
  END IF;
  IF EXISTS (
    SELECT item->>'id'
      FROM jsonb_array_elements(p_items) AS item
     WHERE NULLIF(item->>'id', '') IS NOT NULL
     GROUP BY item->>'id'
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'PO_ITEM_ID_DUPLICATE';
  END IF;

  IF p_po_id IS NULL THEN
    IF EXISTS (
      SELECT 1
        FROM jsonb_array_elements(p_items) AS item
       WHERE NULLIF(item->>'id', '') IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'PO_NEW_ITEM_ID_FORBIDDEN';
    END IF;
    v_hydrated_items := p_items;
  ELSE
    PERFORM 1
      FROM public.purchase_orders
     WHERE id = p_po_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Purchase order not found: %', p_po_id;
    END IF;

    IF EXISTS (
      SELECT 1
        FROM jsonb_array_elements(p_items) AS item
       WHERE NULLIF(item->>'id', '') IS NOT NULL
         AND NOT EXISTS (
           SELECT 1
             FROM public.purchase_order_items poi
            WHERE poi.purchase_order_id = p_po_id
              AND poi.id = (item->>'id')::uuid
         )
    ) THEN
      RAISE EXCEPTION 'PO_ITEM_ID_NOT_IN_PURCHASE_ORDER';
    END IF;

    SELECT COALESCE(
      jsonb_agg(
        CASE
          WHEN poi.id IS NOT NULL
               AND NOT (item.value ? 'unit_cost')
               AND NOT (item.value ? 'unit_cost_cents')
            THEN item.value || jsonb_build_object(
              'unit_cost_cents',
              poi.unit_cost_cents
            )
          ELSE item.value
        END
        ORDER BY item.ordinality
      ),
      '[]'::jsonb
    )
      INTO v_hydrated_items
      FROM jsonb_array_elements(p_items) WITH ORDINALITY AS item(value, ordinality)
      LEFT JOIN public.purchase_order_items poi
        ON poi.purchase_order_id = p_po_id
       AND poi.id::text = item.value->>'id';
  END IF;

  v_result := public._save_purchase_order_cost_input_impl(
    p_po_id,
    p_po_payload,
    v_hydrated_items,
    p_performed_by,
    p_idempotency_key
  );
  v_result_po_id := NULLIF(v_result->>'po_id', '')::uuid;
  IF v_result_po_id IS NULL THEN
    RAISE EXCEPTION 'SAVE_PURCHASE_ORDER_RESULT_INVALID';
  END IF;

  SELECT COALESCE(
    SUM(round(poi.quantity_ordered * poi.unit_cost_cents)::bigint),
    0
  )::bigint
    INTO v_stored_total_cents
    FROM public.purchase_order_items poi
   WHERE poi.purchase_order_id = v_result_po_id;

  UPDATE public.purchase_orders
     SET total_cost = v_stored_total_cents::numeric / 100.0
   WHERE id = v_result_po_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Purchase order not found after save: %', v_result_po_id;
  END IF;

  IF v_bulk_intent_key IS NOT NULL THEN
    INSERT INTO public.purchase_order_import_intents (
      actor_id,
      intent_key,
      purchase_order_id
    ) VALUES (
      v_actor,
      v_bulk_intent_key,
      v_result_po_id
    );
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."_save_purchase_order_atomic_number_impl"("p_po_id" "uuid", "p_po_payload" "jsonb", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_save_purchase_order_atomic_number_impl"("p_po_id" "uuid", "p_po_payload" "jsonb", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Internal purchase-order writer. Direct execution is revoked; use public.save_purchase_order so new PO numbering and insertion share one transaction lock.';



CREATE OR REPLACE FUNCTION "public"."_save_purchase_order_cost_input_impl"("p_po_id" "uuid", "p_po_payload" "jsonb", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid; v_po_id uuid;
  v_is_new boolean := (p_po_id IS NULL);
  v_item jsonb; v_total_cost_cents bigint := 0;
  v_po_number text; v_existing_status text; v_new_status text;
  v_existing_item_ids uuid[]; v_incoming_item_ids uuid[];
  v_items_to_delete uuid[]; v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH: p_performed_by must match auth.uid()'
      USING ERRCODE = 'P0001';
  END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'Only admins or sales reps can manage purchase orders';
  END IF;

  IF v_is_new AND COALESCE(p_po_payload->>'status', 'draft') <> 'draft' THEN
    RAISE EXCEPTION 'INVALID_INITIAL_PO_STATUS: new purchase orders must start as draft'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'save_purchase_order');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF NOT v_is_new THEN
    PERFORM 1 FROM public.purchase_orders WHERE id = p_po_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Purchase order not found: %', p_po_id; END IF;

    IF EXISTS (
      SELECT 1
      FROM public.purchase_order_items existing
      WHERE existing.purchase_order_id = p_po_id
        AND existing.quantity_received > 0
        AND (
          NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(p_items) incoming
            WHERE incoming->>'id' = existing.id::text
          )
          OR EXISTS (
            SELECT 1 FROM jsonb_array_elements(p_items) incoming
            WHERE incoming->>'id' = existing.id::text
              AND (
                incoming->>'product_id' IS DISTINCT FROM existing.product_id::text
                OR NULLIF(incoming->>'quantity_ordered', '')::numeric IS DISTINCT FROM existing.quantity_ordered
                OR public._purchase_order_item_unit_cost_cents(incoming) IS DISTINCT FROM existing.unit_cost_cents
                OR incoming->>'unit_size' IS DISTINCT FROM existing.unit_size
              )
          )
        )
    ) THEN
      RAISE EXCEPTION 'RECEIVED_PO_LINE_IMMUTABLE: reverse the receiving record before changing or removing a received PO line'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_total_cost_cents := v_total_cost_cents + round(
      COALESCE((v_item->>'quantity_ordered')::numeric, 0)
      * public._purchase_order_item_unit_cost_cents(v_item)
    )::bigint;
  END LOOP;

  IF v_is_new THEN
    INSERT INTO public.purchase_orders (po_number, vendor, status, submitted_date,
      expected_delivery_date, notes, total_cost, created_by)
    VALUES (
      p_po_payload->>'po_number', p_po_payload->>'vendor', 'draft',
      (p_po_payload->>'submitted_date')::date,
      (p_po_payload->>'expected_delivery_date')::date,
      NULLIF(p_po_payload->>'notes', ''),
      v_total_cost_cents::numeric / 100.0, v_actor
    ) RETURNING id, po_number INTO v_po_id, v_po_number;

    INSERT INTO public.purchase_order_items (purchase_order_id, product_id, product_name, unit_size,
      quantity_ordered, unit_cost, quantity_received, notes)
    SELECT v_po_id, (item->>'product_id')::uuid, item->>'product_name', item->>'unit_size',
      COALESCE((item->>'quantity_ordered')::numeric, 0),
      public._purchase_order_item_unit_cost_cents(item)::numeric / 100.0,
      0, NULLIF(item->>'notes', '')
    FROM jsonb_array_elements(p_items) AS item
    WHERE (item->>'product_id') IS NOT NULL;

    v_new_status := 'draft';
  ELSE
    v_po_id := p_po_id;
    SELECT po_number, status INTO v_po_number, v_existing_status
    FROM public.purchase_orders WHERE id = v_po_id;
    IF v_po_number IS NULL THEN RAISE EXCEPTION 'Purchase order not found: %', v_po_id; END IF;
    IF v_existing_status IN ('fully_received', 'cancelled') THEN
      RAISE EXCEPTION 'Cannot edit a % purchase order', v_existing_status;
    END IF;

    v_new_status := p_po_payload->>'status';
    IF v_new_status IS NOT NULL AND v_new_status <> v_existing_status THEN
      RAISE EXCEPTION 'PO_STATUS_RPC_REQUIRED: use submit, receive, or cancel purchase-order workflow'
        USING ERRCODE = 'P0001';
    END IF;

    UPDATE public.purchase_orders SET
      vendor = COALESCE(p_po_payload->>'vendor', vendor),
      status = COALESCE(p_po_payload->>'status', status),
      submitted_date = CASE
        WHEN v_existing_status = 'draft' AND v_new_status = 'submitted'
          THEN (now() AT TIME ZONE 'America/Chicago')::date
        ELSE COALESCE((p_po_payload->>'submitted_date')::date, submitted_date)
      END,
      expected_delivery_date = COALESCE((p_po_payload->>'expected_delivery_date')::date, expected_delivery_date),
      notes = CASE WHEN p_po_payload ? 'notes' THEN NULLIF(p_po_payload->>'notes', '') ELSE notes END,
      total_cost = v_total_cost_cents::numeric / 100.0,
      updated_at = now()
    WHERE id = v_po_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Purchase order not found: %', v_po_id; END IF;

    SELECT ARRAY_AGG(id) INTO v_existing_item_ids
    FROM public.purchase_order_items WHERE purchase_order_id = v_po_id;

    SELECT ARRAY_AGG((item->>'id')::uuid) INTO v_incoming_item_ids
    FROM jsonb_array_elements(p_items) AS item WHERE item->>'id' IS NOT NULL;

    IF v_existing_item_ids IS NOT NULL THEN
      v_items_to_delete := ARRAY(
        SELECT poi.id FROM public.purchase_order_items poi
        WHERE poi.purchase_order_id = v_po_id
          AND (v_incoming_item_ids IS NULL OR poi.id != ALL(v_incoming_item_ids))
          AND poi.quantity_received = 0
          AND NOT EXISTS (SELECT 1 FROM public.receiving_records rr WHERE rr.po_item_id = poi.id)
      );
      IF array_length(v_items_to_delete, 1) > 0 THEN
        DELETE FROM public.purchase_order_items WHERE id = ANY(v_items_to_delete);
      END IF;
    END IF;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
      IF v_item->>'id' IS NOT NULL AND (v_item->>'id')::uuid = ANY(COALESCE(v_existing_item_ids, '{}')) THEN
        UPDATE public.purchase_order_items SET
          product_id = (v_item->>'product_id')::uuid,
          product_name = v_item->>'product_name',
          unit_size = COALESCE(v_item->>'unit_size', unit_size),
          quantity_ordered = COALESCE((v_item->>'quantity_ordered')::numeric, quantity_ordered),
          unit_cost = public._purchase_order_item_unit_cost_cents(v_item)::numeric / 100.0,
          notes = CASE WHEN v_item ? 'notes' THEN NULLIF(v_item->>'notes', '') ELSE notes END
        WHERE id = (v_item->>'id')::uuid AND purchase_order_id = v_po_id;
      ELSE
        INSERT INTO public.purchase_order_items (purchase_order_id, product_id, product_name, unit_size,
          quantity_ordered, unit_cost, quantity_received, notes)
        VALUES (v_po_id, (v_item->>'product_id')::uuid, v_item->>'product_name', v_item->>'unit_size',
          COALESCE((v_item->>'quantity_ordered')::numeric, 0),
          public._purchase_order_item_unit_cost_cents(v_item)::numeric / 100.0,
          0, NULLIF(v_item->>'notes', ''));
      END IF;
    END LOOP;
  END IF;

  INSERT INTO public.activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id)
  VALUES (
    CASE WHEN v_is_new THEN 'po_created' ELSE 'po_updated' END,
    CASE WHEN v_is_new THEN 'PO ' || COALESCE(v_po_number, '') || ' created'
         ELSE 'PO ' || COALESCE(v_po_number, '') || ' updated' END,
    v_actor, 'purchase_order', v_po_id
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'save_purchase_order',
      jsonb_build_object('status', 'saved', 'po_id', v_po_id));
  END IF;

  RETURN jsonb_build_object('status', 'saved', 'po_id', v_po_id);
END;
$$;


ALTER FUNCTION "public"."_save_purchase_order_cost_input_impl"("p_po_id" "uuid", "p_po_payload" "jsonb", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_snapshot_order_item_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.cost_at_time_cents IS NULL AND NEW.product_id IS NOT NULL THEN
    SELECT ROUND(current_cost * 100)::bigint INTO NEW.cost_at_time_cents
    FROM public.products WHERE id = NEW.product_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_snapshot_order_item_cost"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_split_invoice_content_claim"("p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'contract_version', 'split_invoice_provenance_v1',
    'invoice', jsonb_build_object(
      'invoice_id', i.id,
      'invoice_number', i.invoice_number,
      'order_id', i.order_id,
      'customer_id', i.customer_id,
      'invoice_type', i.invoice_type,
      'season', i.season,
      'salesman_id', i.salesman_id,
      'created_by', i.created_by,
      'total_amount_cents', i.total_amount_cents,
      'invoice_date', i.invoice_date,
      'invoice_group_id', i.invoice_group_id,
      'header_notes', i.header_notes,
      'pricing_pending', i.pricing_pending
    ),
    'items', COALESCE((
      SELECT jsonb_agg(
               to_jsonb(ii) - ARRAY['created_at', 'updated_at']::text[]
               ORDER BY ii.sort_order, ii.id
             )
        FROM public.invoice_items ii
       WHERE ii.invoice_id = i.id
    ), '[]'::jsonb)
  )
  FROM public.invoices i
  WHERE i.id = p_invoice_id;
$$;


ALTER FUNCTION "public"."_split_invoice_content_claim"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_sync_job_holds"("p_job_id" "uuid", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job jobs%ROWTYPE;
  v_actor uuid;
  v_item RECORD;
  v_active boolean;
  v_free numeric;
  v_shortfalls jsonb := '[]'::jsonb;
BEGIN
  v_actor := COALESCE(p_actor, auth.uid());

  -- Lock the job first (lock order: job -> quote -> inventory).
  SELECT * INTO v_job FROM jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('shortfalls', v_shortfalls); END IF;

  v_active := (v_job.deleted_at IS NULL AND v_job.status IN ('scheduled', 'in_progress'));

  IF v_job.quote_id IS NOT NULL THEN
    -- Quote-linked: coordinate ALL sibling jobs on the quote together. This
    -- reserves/releases THIS job, reallocates siblings on cancel/delete (#2),
    -- allocates the order coverage once across siblings (#3), and resyncs the
    -- parent quote's crop_program holds.
    PERFORM _sync_quote_job_reservations(v_job.quote_id, v_actor);
  ELSE
    -- Quote-less job: independent, no booking to draw from. Rebuild its holds
    -- (full demand per product, no draws). Release when terminal/deleted.
    DELETE FROM inventory_holds WHERE source_id = p_job_id AND hold_type = 'job';
    DELETE FROM job_product_draws WHERE job_id = p_job_id;
    IF v_active THEN
      FOR v_item IN
        SELECT jc.product_id,
               -- D2 (U11 follow-up): normalize FIRST — 'pt/ac'-style units NULL out of the converter; mirrors complete_job.
               SUM(COALESCE(field_app_priced_quantity(jc.quantity, normalize_rate_unit(jc.unit), p.inventory_unit, p.product_form), jc.quantity)) AS job_demand
        FROM job_chemicals jc
        JOIN products p ON p.id = jc.product_id
        -- U4<<< customer-supplied lines demand nothing from our shed. (#102)
        WHERE jc.job_id = p_job_id AND jc.product_id IS NOT NULL AND jc.customer_supplied = false
        -- >>>U4
        GROUP BY jc.product_id
        HAVING SUM(COALESCE(field_app_priced_quantity(jc.quantity, normalize_rate_unit(jc.unit), p.inventory_unit, p.product_form), jc.quantity)) > 0
      LOOP
        PERFORM 1 FROM inventory
        WHERE product_id = v_item.product_id AND location = 'Main Warehouse'
        FOR UPDATE;
        -- status-enum-check: exempt (writes the 'job' hold_type added by A1 20260702170000)
        INSERT INTO inventory_holds (
          product_id, customer_id, quantity, hold_type, source_id,
          notes, created_by, expires_at, is_active
        ) VALUES (
          v_item.product_id, v_job.customer_id, v_item.job_demand, 'job', p_job_id,
          'Job reservation for ' || COALESCE(v_job.job_number, p_job_id::text),
          COALESCE(v_actor, v_job.created_by), NULL, true
        );
      END LOOP;
    END IF;
  END IF;

  -- WARN (never block, §6.1): shortfalls for THIS job's products, only while the
  -- job is active. free = available - prebooked - active non-expired holds, read
  -- AFTER the (re)sync above so it reflects the final hold state. A released job
  -- returns empty shortfalls (matches the old RELEASE branch).
  IF v_active THEN
    FOR v_item IN
      SELECT jc.product_id,
             SUM(COALESCE(field_app_priced_quantity(jc.quantity, normalize_rate_unit(jc.unit), p.inventory_unit, p.product_form), jc.quantity)) AS job_demand
      FROM job_chemicals jc
      JOIN products p ON p.id = jc.product_id
      -- U4<<< customer-supplied lines demand nothing — never a shortfall. (#102)
      WHERE jc.job_id = p_job_id AND jc.product_id IS NOT NULL AND jc.customer_supplied = false
      -- >>>U4
      GROUP BY jc.product_id
      HAVING SUM(COALESCE(field_app_priced_quantity(jc.quantity, normalize_rate_unit(jc.unit), p.inventory_unit, p.product_form), jc.quantity)) > 0
    LOOP
      SELECT inv.quantity_available - inv.quantity_prebooked
             - COALESCE((
                 SELECT SUM(h.quantity) FROM inventory_holds h
                 WHERE h.product_id = v_item.product_id AND h.is_active = true
                   AND (h.expires_at IS NULL OR h.expires_at >= CURRENT_DATE)
               ), 0)
        INTO v_free
      FROM inventory inv
      WHERE inv.product_id = v_item.product_id AND inv.location = 'Main Warehouse';

      IF v_free IS NULL THEN
        -- No Main Warehouse inventory row => the whole demand is short (Codex P2).
        v_shortfalls := v_shortfalls || jsonb_build_object(
          'product_id', v_item.product_id,
          'product_name', (SELECT product_name FROM products WHERE id = v_item.product_id),
          'short', v_item.job_demand
        );
      ELSIF v_free < 0 THEN
        v_shortfalls := v_shortfalls || jsonb_build_object(
          'product_id', v_item.product_id,
          'product_name', (SELECT product_name FROM products WHERE id = v_item.product_id),
          'short', -v_free
        );
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('shortfalls', v_shortfalls);
END;
$$;


ALTER FUNCTION "public"."_sync_job_holds"("p_job_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_sync_job_location_dispatch_on_applicator_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jf record;
BEGIN
  -- Clearing the whole-job applicator (Codex R2 P1): cancel the ACTIVE dispatch
  -- rows that belonged to the OLD whole-job applicator — otherwise the UI and
  -- jobs.applicator_id say "unassigned" while the old applicator still sees and
  -- can work the job, and the Needs-Dispatch surfaces won't flag it. Deliberate
  -- SPLIT rows are preserved: only rows held by OLD.applicator_id are touched
  -- (a crew-only or other-applicator split is not silently undone by clearing
  -- an unrelated job-level field).
  IF NEW.applicator_id IS NULL THEN
    IF OLD.applicator_id IS NOT NULL THEN
      UPDATE job_location_dispatches
         SET dispatch_status = 'cancelled',
             updated_at      = now()
       WHERE job_id = NEW.id
         AND applicator_id = OLD.applicator_id
         AND dispatch_status = 'dispatched';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.status NOT IN ('scheduled', 'in_progress') THEN RETURN NEW; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = NEW.applicator_id AND is_active = true AND role = 'applicator'
  ) THEN
    RETURN NEW;
  END IF;

  -- "Reassign via JobDetail replaces the whole-job dispatch" (mission brief):
  -- every CURRENT location on this job is overwritten to the new applicator,
  -- including one previously split to a different applicator/crew via the
  -- Dispatch Board wizard. Re-split via the wizard after this if needed.
  FOR v_jf IN SELECT id FROM job_fields WHERE job_id = NEW.id LOOP
    INSERT INTO job_location_dispatches
      (job_field_id, job_id, applicator_id, crew_id, dispatched_at, dispatch_status, dispatched_by)
    VALUES
      (v_jf.id, NEW.id, NEW.applicator_id, NULL, now(), 'dispatched',
       -- RLS review M1: same auth.uid()-first attribution as trigger 1 — the
       -- assign_job_applicator path never stamps jobs.updated_by, so without
       -- auth.uid() the row would credit the job's last editor, not the assigner.
       COALESCE(auth.uid(), NEW.updated_by, NEW.created_by))
    ON CONFLICT (job_field_id) DO UPDATE
      SET applicator_id   = EXCLUDED.applicator_id,
          crew_id         = NULL,
          job_id          = EXCLUDED.job_id,
          dispatched_at   = now(),
          dispatch_status = 'dispatched',
          dispatched_by   = EXCLUDED.dispatched_by;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_sync_job_location_dispatch_on_applicator_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_sync_job_location_dispatch_on_field_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job jobs%ROWTYPE;
  v_stash job_dispatch_preservation%ROWTYPE;
BEGIN
  SELECT * INTO v_job FROM jobs WHERE id = NEW.job_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  IF v_job.status NOT IN ('scheduled', 'in_progress') THEN RETURN NEW; END IF;

  -- Codex R3 P1: restore a stashed per-location assignee FIRST (save_job's
  -- delete+recreate cycle — the BEFORE DELETE trigger above stashed it under
  -- the stable (job_id, field_id) key moments ago in this same transaction).
  -- A wizard split survives an unrelated notes/chemicals edit byte-for-byte.
  -- Stash rows older than 1 hour are ignored AND purged (a field re-added to
  -- the job much later is a new decision, not a restore).
  DELETE FROM job_dispatch_preservation
   WHERE job_id = NEW.job_id AND preserved_at < now() - interval '1 hour';

  SELECT * INTO v_stash
    FROM job_dispatch_preservation
   WHERE job_id = NEW.job_id AND field_id = NEW.field_id;

  IF FOUND THEN
    INSERT INTO job_location_dispatches
      (job_field_id, job_id, applicator_id, crew_id, dispatched_at, dispatch_status, dispatched_by)
    VALUES
      (NEW.id, NEW.job_id, v_stash.applicator_id, v_stash.crew_id,
       COALESCE(v_stash.dispatched_at, now()), 'dispatched', v_stash.dispatched_by)
    ON CONFLICT (job_field_id) DO NOTHING;

    DELETE FROM job_dispatch_preservation
     WHERE job_id = NEW.job_id AND field_id = NEW.field_id;

    RETURN NEW;
  END IF;

  -- No stash entry → fall back to the whole-job applicator (the original #15
  -- fix). No whole-job applicator to sync to, or the job isn't in a
  -- dispatchable lifecycle state (mirrors dispatch_job_locations's own gate) —
  -- leave the location undispatched; the Dispatch Board wizard is the tool for that.
  IF v_job.applicator_id IS NULL THEN RETURN NEW; END IF;

  -- Defensive mirror of dispatch_job_locations's INVALID_APPLICATOR check.
  -- License expiry is NOT re-checked: enforce_applicator_license (BEFORE
  -- INSERT/UPDATE OF applicator_id ON jobs) already validated it before this
  -- job_fields row could exist with this applicator_id.
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_job.applicator_id AND is_active = true AND role = 'applicator'
  ) THEN
    RETURN NEW;
  END IF;

  -- NEW.id is a freshly gen_random_uuid()'d job_fields row, so no existing
  -- job_location_dispatches row can already reference it — ON CONFLICT DO
  -- NOTHING is defensive belt-and-suspenders, not a live code path.
  INSERT INTO job_location_dispatches
    (job_field_id, job_id, applicator_id, crew_id, dispatched_at, dispatch_status, dispatched_by)
  VALUES
    (NEW.id, NEW.job_id, v_job.applicator_id, NULL, now(), 'dispatched',
     -- RLS review M1: auth.uid() is the real session actor for every
     -- authenticated-invoked path (assign_job_applicator / direct .update()
     -- don't stamp jobs.updated_by, so the fallbacks alone could name the
     -- job's LAST editor as the dispatcher). Fallbacks cover owner/service runs.
     COALESCE(auth.uid(), v_job.updated_by, v_job.created_by))
  ON CONFLICT (job_field_id) DO NOTHING;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_sync_job_location_dispatch_on_field_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_sync_planned_holds"("p_quote_id" "uuid", "p_actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_quote quotes%ROWTYPE;
  v_item RECORD;
  v_consumed_so_far numeric;
  v_remaining_drawn numeric;
  v_consume numeric;
  v_hold_qty numeric;
  v_holds_created integer := 0;
  v_consumed jsonb := '{}'::jsonb;
BEGIN
  -- Lock the quote row: draw_down_quote takes the same lock before touching
  -- the ledger/holds, so a rebuild can never interleave with a draw.
  SELECT * INTO v_quote FROM quotes
  WHERE id = p_quote_id AND deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN RETURN 0; END IF;

  IF NOT v_quote.is_planned OR v_quote.status NOT IN ('draft', 'sent', 'revised') THEN
    -- Not an open planned program: any active holds are stale — release them.
    -- (Terminal statuses are also covered by release_holds_on_quote_status_change;
    -- this additionally covers is_planned switched off without a status change.)
    UPDATE inventory_holds SET is_active = false, updated_at = now()
    WHERE source_id = p_quote_id AND is_active = true;
    RETURN 0;
  END IF;

  -- Rebuild from scratch (same DELETE semantics create_planned_holds used).
  DELETE FROM inventory_holds WHERE source_id = p_quote_id AND is_active = true;

  -- Reserve booked − drawn per product. Each product's drawn total consumes
  -- the earliest items first so expiry follows the still-reserved tail.
  FOR v_item IN
    SELECT qi.product_id, qi.total_units_needed, qs.needed_by_date,
           -- A2<<< order draws + job draws both consume the booking (§4A.3, §6.5)
           COALESCE(d.quantity_drawn, 0) + COALESCE(jd.job_drawn, 0) AS drawn_total
           -- >>>A2
    FROM quote_items qi
    JOIN quote_sections qs ON qs.id = qi.section_id
    LEFT JOIN quote_product_draws d
      ON d.quote_id = qi.quote_id AND d.product_id = qi.product_id
    -- A2<<< aggregate this quote's live job draws per product
    LEFT JOIN (
      SELECT product_id, SUM(quantity_drawn) AS job_drawn
      FROM job_product_draws
      WHERE quote_id = p_quote_id
      GROUP BY product_id
    ) jd ON jd.product_id = qi.product_id
    -- >>>A2
    WHERE qi.quote_id = p_quote_id
      AND qi.total_units_needed IS NOT NULL
      AND qi.total_units_needed > 0
    ORDER BY qs.needed_by_date NULLS LAST, qs.sort_order, qi.sort_order, qi.id
  LOOP
    v_consumed_so_far := COALESCE((v_consumed->>v_item.product_id::text)::numeric, 0);
    v_remaining_drawn := GREATEST(v_item.drawn_total - v_consumed_so_far, 0);
    v_consume := LEAST(v_item.total_units_needed, v_remaining_drawn);
    v_hold_qty := v_item.total_units_needed - v_consume;
    v_consumed := jsonb_set(v_consumed, ARRAY[v_item.product_id::text],
      to_jsonb(v_consumed_so_far + v_consume));

    IF v_hold_qty > 0 THEN
      INSERT INTO inventory_holds (
        product_id, customer_id, quantity, hold_type, source_id,
        notes, created_by, expires_at, is_active
      ) VALUES (
        v_item.product_id,
        v_quote.customer_id,
        v_hold_qty,
        'crop_program',
        p_quote_id,
        'Planned program hold for quote ' || v_quote.quote_number,
        COALESCE(p_actor, v_quote.created_by),
        v_item.needed_by_date + INTERVAL '14 days',
        true
      );
      v_holds_created := v_holds_created + 1;
    END IF;
  END LOOP;

  RETURN v_holds_created;
END;
$$;


ALTER FUNCTION "public"."_sync_planned_holds"("p_quote_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_sync_quote_job_reservations"("p_quote_id" "uuid", "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_quote quotes%ROWTYPE;
  v_planned_open boolean := false;
  v_actor uuid;
  v_row RECORD;
  v_prev_product uuid;
  v_booking numeric;
  v_order_drawn numeric;
  v_consumed_drawn numeric;
  v_crop_pool numeric := 0;
  v_draw numeric;
  v_hold numeric;
BEGIN
  v_actor := COALESCE(p_actor, auth.uid());

  -- Lock the parent quote (same rule the per-job engine used: 'accepted' still
  -- counts as open; only declined/expired/cancelled do not). This lock also
  -- serializes concurrent job syncs on the same quote AND the save_quote unplan
  -- guard (both take the quote FOR UPDATE first).
  SELECT * INTO v_quote FROM quotes
  WHERE id = p_quote_id AND deleted_at IS NULL
  FOR UPDATE;
  -- LAYER2<<< 'closed_by_application' (a booking fulfilled by us applying it) is
  -- a terminal, NOT-open booking too — exclude it so a stray later job event
  -- can't re-draw against the closed booking's balance. (owner 2026-07-03)
  -- U5<<< 'closed_short' (a booking the customer abandoned) is likewise terminal
  -- and NOT-open — exclude it so a stray later job event can't re-draw. (#1)
  v_planned_open := FOUND
    AND v_quote.is_planned
    AND v_quote.status NOT IN ('declined', 'expired', 'cancelled', 'closed_by_application', 'closed_short');
  -- >>>U5 >>>LAYER2

  -- Clean slate for this quote's job reservations:
  --   * drop every 'job' hold for jobs on this quote (the loop re-adds one per
  --     ACTIVE job);
  --   * drop draws for every NON-consumed job (ACTIVE -> rebuilt below;
  --     cancelled / soft-deleted-while-active -> stay gone). KEEP completed /
  --     invoiced job draws: that chemical was physically applied (complete_job
  --     already deducted the stock), so its draw permanently consumes the booking.
  DELETE FROM inventory_holds
   WHERE hold_type = 'job'
     AND source_id IN (SELECT id FROM jobs WHERE quote_id = p_quote_id);

  DELETE FROM job_product_draws jpd
   USING jobs j
   WHERE jpd.job_id = j.id
     AND jpd.quote_id = p_quote_id
     AND j.status NOT IN ('completed', 'invoiced');

  -- Coordinated allocation across ACTIVE sibling jobs, product by product.
  -- crop_pool = booking - order_drawn - consumed_job_drawn = the booking balance
  -- still open to draw. Active jobs draw from it FIFO (by job creation) so their
  -- DRAWS never exceed the booking (no double-BILL, and a cancelled sibling frees
  -- crop the next re-sync re-draws — push-gate #2). But the job HOLD is the FULL
  -- application demand: chemical-sale (order) stock is a SEPARATE channel — delivered
  -- to the customer, not available for us to apply — so it must NOT offset the shed
  -- reservation (owner 2026-07-03, push-gate #A). The drawn portion shrinks the crop
  -- hold (net-zero within the booking); demand beyond the drawable booking is real
  -- extra shed need. For a lone job this yields hold = demand (draw + undrawn excess).
  v_prev_product := NULL;
  FOR v_row IN
    SELECT j.id AS job_id, j.customer_id, j.job_number, j.created_by, j.created_at,
           jc.product_id,
           -- D2 (U11 follow-up): normalize FIRST — 'pt/ac'-style units NULL out of the converter; mirrors complete_job.
           SUM(COALESCE(field_app_priced_quantity(jc.quantity, normalize_rate_unit(jc.unit), p.inventory_unit, p.product_form), jc.quantity)) AS demand
    FROM jobs j
    JOIN job_chemicals jc ON jc.job_id = j.id
    JOIN products p ON p.id = jc.product_id
    WHERE j.quote_id = p_quote_id
      AND j.deleted_at IS NULL
      AND j.status IN ('scheduled', 'in_progress')
      AND jc.product_id IS NOT NULL
      -- U4<<< a grower-supplied line demands nothing from our shed — it must not
      -- draw the booking nor add a 'job' hold. (#102)
      AND jc.customer_supplied = false
      -- >>>U4
    GROUP BY j.id, j.customer_id, j.job_number, j.created_by, j.created_at, jc.product_id
    HAVING SUM(COALESCE(field_app_priced_quantity(jc.quantity, normalize_rate_unit(jc.unit), p.inventory_unit, p.product_form), jc.quantity)) > 0
    ORDER BY jc.product_id, j.created_at NULLS LAST, j.id
  LOOP
    IF v_row.product_id IS DISTINCT FROM v_prev_product THEN
      -- New product: lock its inventory row (serialize concurrent same-product
      -- reserves; lock order quote -> inventory matches draw_down_quote), then
      -- (re)compute the drawable crop pool.
      PERFORM 1 FROM inventory
      WHERE product_id = v_row.product_id AND location = 'Main Warehouse'
      FOR UPDATE;

      IF v_planned_open THEN
        SELECT COALESCE(SUM(qi.total_units_needed), 0) INTO v_booking
        FROM quote_items qi
        WHERE qi.quote_id = p_quote_id AND qi.product_id = v_row.product_id;

        SELECT COALESCE(quantity_drawn, 0) INTO v_order_drawn
        FROM quote_product_draws
        WHERE quote_id = p_quote_id AND product_id = v_row.product_id;
        v_order_drawn := COALESCE(v_order_drawn, 0);

        -- After the DELETE above, the only job_product_draws rows left for this
        -- quote+product belong to completed/invoiced (consumed) jobs -- their
        -- chemical was applied, so it permanently consumes the booking.
        SELECT COALESCE(SUM(quantity_drawn), 0) INTO v_consumed_drawn
        FROM job_product_draws
        WHERE quote_id = p_quote_id AND product_id = v_row.product_id;

        v_crop_pool := GREATEST(v_booking - v_order_drawn - v_consumed_drawn, 0);
      ELSE
        v_crop_pool := 0;
      END IF;

      v_prev_product := v_row.product_id;
    END IF;

    -- Draw from the open booking balance (for billing / no double-bill), FIFO.
    v_draw := LEAST(v_row.demand, v_crop_pool);
    v_crop_pool := v_crop_pool - v_draw;
    -- Hold the FULL application demand in the shed (channels don't offset, #A).
    v_hold := v_row.demand;

    IF v_draw > 0 THEN
      INSERT INTO job_product_draws (job_id, quote_id, product_id, quantity_drawn)
      VALUES (v_row.job_id, p_quote_id, v_row.product_id, v_draw)
      ON CONFLICT (job_id, product_id)
      DO UPDATE SET quantity_drawn = EXCLUDED.quantity_drawn,
                    quote_id       = EXCLUDED.quote_id,
                    updated_at     = now();
    END IF;

    -- status-enum-check: exempt (writes the 'job' hold_type added by A1 20260702170000)
    IF v_hold > 0 THEN
      INSERT INTO inventory_holds (
        product_id, customer_id, quantity, hold_type, source_id,
        notes, created_by, expires_at, is_active
      ) VALUES (
        v_row.product_id, v_row.customer_id, v_hold, 'job', v_row.job_id,
        'Job reservation for ' || COALESCE(v_row.job_number, v_row.job_id::text),
        COALESCE(v_actor, v_row.created_by), NULL, true
      );
    END IF;
  END LOOP;

  -- Resync the parent quote's crop_program holds to reflect the new job draws
  -- (A2 made _sync_planned_holds job-draw-aware). Self-guards on a missing /
  -- deleted quote, so calling it unconditionally is safe.
  PERFORM _sync_planned_holds(p_quote_id, v_actor);
END;
$$;


ALTER FUNCTION "public"."_sync_quote_job_reservations"("p_quote_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_trg_release_job_holds_on_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status
     OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
    PERFORM _sync_job_holds(NEW.id, auth.uid());
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_trg_release_job_holds_on_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_trg_sync_job_holds"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN SELECT DISTINCT job_id FROM affected WHERE job_id IS NOT NULL LOOP
    PERFORM _sync_job_holds(r.job_id, auth.uid());
  END LOOP;
  RETURN NULL;  -- AFTER STATEMENT: return value ignored
END;
$$;


ALTER FUNCTION "public"."_trg_sync_job_holds"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_update_order_items_impl"("p_order_id" "uuid", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid; v_order record; v_old_item record; v_item jsonb; v_qty_diff numeric; v_new_total numeric;
  v_result jsonb; v_passed_ids uuid[]; v_new_item_id uuid; v_product record; v_new_qty numeric;
  v_new_price numeric; v_new_cost numeric; v_new_items_added integer := 0; v_new_product_id uuid;
  v_old_remaining numeric; v_blocking_table text; v_existing jsonb;
BEGIN
  -- Strict actor pattern (codex audit F2)
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found: %', p_order_id; END IF;
  IF v_order.status NOT IN ('confirmed', 'pending') THEN
    RAISE EXCEPTION 'Cannot edit order in status: %', v_order.status;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND role IN ('admin', 'sales_rep')) THEN
    RAISE EXCEPTION 'Not authorized to update order items';
  END IF;

  -- BEGIN active-actor guard (20260611120000)
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;
  -- END active-actor guard (20260611120000)

  -- BEGIN draw-order lock guard (20260611120000)
  IF v_order.booking_draw THEN
    RAISE EXCEPTION 'BOOKING_DRAW_ORDER_LOCKED: order % was created by a booking draw-down — its items mirror the booking ledger. Void or cancel the order to return quantity to the booking, then draw again', v_order.order_number;
  END IF;
  -- END draw-order lock guard (20260611120000)

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'update_order_items');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT array_agg((el->>'id')::uuid) INTO v_passed_ids
    FROM jsonb_array_elements(p_items) el WHERE (el->>'id') IS NOT NULL;

  FOR v_old_item IN SELECT oi.* FROM order_items oi
    WHERE oi.order_id = p_order_id AND (v_passed_ids IS NULL OR oi.id != ALL(v_passed_ids))
  LOOP
    IF v_old_item.quantity_delivered > 0 THEN
      RAISE EXCEPTION 'Cannot remove "%" — % unit(s) have already been delivered. Edit the quantity instead.',
        v_old_item.product_name, v_old_item.quantity_delivered;
    END IF;

    IF EXISTS (SELECT 1 FROM delivery_items di JOIN deliveries d ON d.id = di.delivery_id
       WHERE di.order_item_id = v_old_item.id AND d.status NOT IN ('cancelled', 'voided') LIMIT 1) THEN
      RAISE EXCEPTION 'Cannot remove "%" — it is linked to an active delivery. Remove it from the delivery first.', v_old_item.product_name;
    END IF;

    -- BEGIN delivery-item lock pairing (20260616220000)
    PERFORM set_config('app.admin_override', 'true', true);
    DELETE FROM delivery_items WHERE order_item_id = v_old_item.id
      AND delivery_id IN (SELECT id FROM deliveries WHERE status IN ('cancelled', 'voided'));
    PERFORM set_config('app.admin_override', 'false', true);
    -- END delivery-item lock pairing (20260616220000)

    IF EXISTS (SELECT 1 FROM return_items ri JOIN returns r ON r.id = ri.return_id
       WHERE ri.order_item_id = v_old_item.id AND r.status NOT IN ('cancelled', 'rejected') LIMIT 1) THEN
      RAISE EXCEPTION 'Cannot remove "%" — it is linked to a return/RMA. Process or cancel the return first.', v_old_item.product_name;
    END IF;

    UPDATE return_items SET order_item_id = NULL WHERE order_item_id = v_old_item.id
      AND return_id IN (SELECT id FROM returns WHERE status IN ('cancelled', 'rejected'));

    DELETE FROM delivery_remainders WHERE order_item_id = v_old_item.id
      AND (status IN ('resolved', 'cancelled')
           OR original_delivery_id IN (SELECT id FROM deliveries WHERE status IN ('cancelled', 'voided')));

    IF EXISTS (SELECT 1 FROM delivery_remainders WHERE order_item_id = v_old_item.id LIMIT 1) THEN
      RAISE EXCEPTION 'Cannot remove "%" — it has active delivery remainder records. Resolve or cancel them first.', v_old_item.product_name;
    END IF;

    DELETE FROM order_line_allocations WHERE order_item_id = v_old_item.id;

    IF EXISTS (SELECT 1 FROM invoice_items ii JOIN invoices inv ON inv.id = ii.invoice_id
       WHERE ii.order_item_id = v_old_item.id AND inv.status NOT IN ('draft', 'voided', 'cancelled') LIMIT 1) THEN
      RAISE EXCEPTION 'Cannot remove "%" — it is linked to a posted or paid invoice. Void the invoice first.', v_old_item.product_name;
    END IF;

    UPDATE invoice_items SET order_item_id = NULL WHERE order_item_id = v_old_item.id
      AND invoice_id IN (SELECT id FROM invoices WHERE status IN ('draft', 'voided', 'cancelled'));

    IF v_old_item.quantity_remaining > 0 THEN
      UPDATE inventory SET quantity_prebooked = GREATEST(quantity_prebooked - v_old_item.quantity_remaining, 0), updated_at = now()
        WHERE product_id = v_old_item.product_id AND location = 'Main Warehouse';
      INSERT INTO inventory_transactions (product_id, transaction_type, quantity, order_id, performed_by, notes)
      VALUES (v_old_item.product_id, 'released', v_old_item.quantity_remaining, p_order_id, v_actor,
        'Order edit: item removed from ' || v_order.order_number);
    END IF;

    DELETE FROM order_items WHERE id = v_old_item.id;
  END LOOP;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    IF (v_item->>'id') IS NOT NULL THEN
      SELECT * INTO v_old_item FROM order_items WHERE id = (v_item->>'id')::uuid;
      IF NOT FOUND THEN CONTINUE; END IF;

      v_new_product_id := COALESCE((v_item->>'product_id')::uuid, v_old_item.product_id);
      v_qty_diff := (v_item->>'total_units_needed')::numeric - v_old_item.total_units_needed;

      IF v_new_product_id IS DISTINCT FROM v_old_item.product_id THEN
        v_old_remaining := GREATEST(v_old_item.total_units_needed - v_old_item.quantity_delivered, 0);
        IF v_old_remaining > 0 THEN
          UPDATE inventory SET quantity_prebooked = GREATEST(quantity_prebooked - v_old_remaining, 0), updated_at = now()
          WHERE product_id = v_old_item.product_id AND location = 'Main Warehouse';
          INSERT INTO inventory_transactions (product_id, transaction_type, quantity, order_id, performed_by, notes)
          VALUES (v_old_item.product_id, 'released', v_old_remaining, p_order_id, v_actor,
            'Order edit: product swapped from ' || v_old_item.product_name || ' on ' || v_order.order_number);
        END IF;

        v_new_qty := (v_item->>'total_units_needed')::numeric;
        IF v_new_qty > 0 THEN
          UPDATE inventory SET quantity_prebooked = quantity_prebooked + v_new_qty, updated_at = now()
          WHERE product_id = v_new_product_id AND location = 'Main Warehouse';
          INSERT INTO inventory_transactions (product_id, transaction_type, quantity, order_id, performed_by, notes)
          VALUES (v_new_product_id, 'prebooked', v_new_qty, p_order_id, v_actor,
            'Order edit: product swapped to ' || COALESCE(v_item->>'product_name', '') || ' on ' || v_order.order_number);
        END IF;

        v_new_cost := COALESCE((v_item->>'cost_per_unit')::numeric, 0);
        IF v_new_cost = 0 THEN
          SELECT current_cost INTO v_new_cost FROM products WHERE id = v_new_product_id;
          v_new_cost := COALESCE(v_new_cost, 0);
        END IF;

        UPDATE order_items SET
          product_id = v_new_product_id,
          product_name = COALESCE(v_item->>'product_name', product_name),
          unit_size = COALESCE(v_item->>'unit_size', unit_size),
          cost_per_unit = v_new_cost,
          price_per_unit = (v_item->>'price_per_unit')::numeric,
          total_units_needed = (v_item->>'total_units_needed')::numeric,
          quantity_remaining = GREATEST((v_item->>'total_units_needed')::numeric - v_old_item.quantity_delivered, 0),
          total_price = (v_item->>'price_per_unit')::numeric * (v_item->>'total_units_needed')::numeric,
          profit = ((v_item->>'price_per_unit')::numeric - v_new_cost) * (v_item->>'total_units_needed')::numeric,
          net_margin = CASE WHEN (v_item->>'price_per_unit')::numeric > 0
            THEN ROUND((((v_item->>'price_per_unit')::numeric - v_new_cost) / (v_item->>'price_per_unit')::numeric) * 100, 2)
            ELSE 0 END
        WHERE id = v_old_item.id;
      ELSE
        UPDATE order_items SET
          product_name = COALESCE(v_item->>'product_name', product_name),
          price_per_unit = (v_item->>'price_per_unit')::numeric,
          total_units_needed = (v_item->>'total_units_needed')::numeric,
          quantity_remaining = GREATEST((v_item->>'total_units_needed')::numeric - v_old_item.quantity_delivered, 0),
          total_price = (v_item->>'price_per_unit')::numeric * (v_item->>'total_units_needed')::numeric,
          -- BEGIN same-product line profit/margin refresh (20260617123503)
          profit = ((v_item->>'price_per_unit')::numeric - COALESCE(v_old_item.cost_per_unit, 0)) * (v_item->>'total_units_needed')::numeric,
          net_margin = CASE WHEN (v_item->>'price_per_unit')::numeric > 0
            THEN ROUND((((v_item->>'price_per_unit')::numeric - COALESCE(v_old_item.cost_per_unit, 0)) / (v_item->>'price_per_unit')::numeric) * 100, 2)
            ELSE 0 END
          -- END same-product line profit/margin refresh (20260617123503)
        WHERE id = v_old_item.id;

        IF v_qty_diff <> 0 THEN
          UPDATE inventory SET quantity_prebooked = GREATEST(quantity_prebooked + v_qty_diff, 0), updated_at = now()
          WHERE product_id = v_old_item.product_id AND location = 'Main Warehouse';
          INSERT INTO inventory_transactions (product_id, transaction_type, quantity, order_id, performed_by, notes)
          VALUES (v_old_item.product_id, CASE WHEN v_qty_diff > 0 THEN 'prebooked' ELSE 'released' END,
            ABS(v_qty_diff), p_order_id, v_actor, 'Order edit: adjusted prebooked by ' || v_qty_diff);
        END IF;
      END IF;
    ELSE
      v_new_qty := COALESCE((v_item->>'total_units_needed')::numeric, 0);
      v_new_price := COALESCE((v_item->>'price_per_unit')::numeric, 0);
      v_new_cost := COALESCE((v_item->>'cost_per_unit')::numeric, 0);
      IF v_new_cost = 0 AND (v_item->>'product_id') IS NOT NULL THEN
        SELECT current_cost INTO v_new_cost FROM products WHERE id = (v_item->>'product_id')::uuid;
        v_new_cost := COALESCE(v_new_cost, 0);
      END IF;
      IF v_new_qty <= 0 THEN CONTINUE; END IF;

      v_new_item_id := gen_random_uuid();
      INSERT INTO order_items (id, order_id, product_id, product_name, price_per_unit, cost_per_unit,
        total_units_needed, unit_size, section_name, total_price, profit, net_margin, quantity_delivered, quantity_remaining)
      VALUES (v_new_item_id, p_order_id, (v_item->>'product_id')::uuid, COALESCE(v_item->>'product_name', ''),
        v_new_price, v_new_cost, v_new_qty, v_item->>'unit_size', v_item->>'section_name',
        v_new_price * v_new_qty, (v_new_price - v_new_cost) * v_new_qty,
        CASE WHEN v_new_price > 0 THEN ROUND(((v_new_price - v_new_cost) / v_new_price) * 100, 2) ELSE 0 END,
        0, v_new_qty);

      UPDATE inventory SET quantity_prebooked = quantity_prebooked + v_new_qty, updated_at = now()
      WHERE product_id = (v_item->>'product_id')::uuid AND location = 'Main Warehouse';

      INSERT INTO inventory_transactions (product_id, transaction_type, quantity, order_id, performed_by, notes)
      VALUES ((v_item->>'product_id')::uuid, 'prebooked', v_new_qty, p_order_id, v_actor,
        'New item added to existing order ' || v_order.order_number);

      v_new_items_added := v_new_items_added + 1;
    END IF;
  END LOOP;

  SELECT COALESCE(SUM(total_price), 0) INTO v_new_total FROM order_items WHERE order_id = p_order_id;
  UPDATE orders SET total_price = v_new_total, updated_at = now() WHERE id = p_order_id;

  -- BEGIN commission recompute on edit (20260617040000)
  UPDATE commissions c
     SET order_profit      = ROUND(COALESCE(o.total_profit, 0), 2),
         commission_amount = compute_commission_amount(o.total_profit, c.split_percentage)
    FROM orders o
   WHERE c.order_id = p_order_id
     AND o.id = p_order_id
     AND c.status = 'pending'
     AND c.deleted_at IS NULL
     AND NOT EXISTS (
       SELECT 1 FROM commission_payment_items cpi
       JOIN commission_payments cp ON cp.id = cpi.commission_payment_id
       WHERE cpi.commission_id = c.id AND cp.status <> 'voided'
     );
  -- END commission recompute on edit (20260617040000)

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('order_edited',
    'Order ' || v_order.order_number || ' items updated' ||
    CASE WHEN v_new_items_added > 0 THEN ' (' || v_new_items_added || ' new item(s) added)' ELSE '' END ||
    ' — new total $' || ROUND(v_new_total, 2),
    v_actor, 'order', p_order_id, v_order.customer_id);

  v_result := jsonb_build_object('status', 'updated', 'new_items_added', v_new_items_added);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'update_order_items', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."_update_order_items_impl"("p_order_id" "uuid", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_validate_order_shares_total"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_total numeric;
BEGIN
  PERFORM 1 FROM orders WHERE id = NEW.order_id FOR UPDATE;
  SELECT COALESCE(SUM(split_percentage), 0) INTO v_total
  FROM order_shares
  WHERE order_id = NEW.order_id
    AND id <> NEW.id;
  v_total := v_total + NEW.split_percentage;
  IF v_total > 100.01 THEN
    RAISE EXCEPTION 'ORDER_SHARES_OVER_100: order % bill-split total would be % (max 100)',
      NEW.order_id, v_total;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_validate_order_shares_total"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_void_invoice_split_provenance_impl_20260719"("p_invoice_id" "uuid", "p_void_reason" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_inv record; v_alloc record; v_total_allocations_reversed bigint := 0;
  v_total_prepay_restored bigint := 0; v_prepay_app record; v_actor_role text;
  v_allocation_set_ids uuid[]; v_commissions_cancelled integer := 0; v_existing jsonb;
  v_job record;  -- U6 #65: job-release locals
  v_capp record;  -- CREDIT-APPLY: active-application cursor
BEGIN
  SELECT role INTO v_actor_role FROM profiles WHERE id = auth.uid() AND is_active = true;
  IF v_actor_role IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Only admin users can void invoices'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'void_invoice');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;

  SELECT * INTO v_inv FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found: %', p_invoice_id; END IF;
  IF v_inv.status = 'voided' THEN RAISE EXCEPTION 'Invoice already voided'; END IF;
  IF v_inv.status = 'cancelled' THEN RAISE EXCEPTION 'Cannot void a cancelled invoice'; END IF;

  -- draft/unposted invoices were never posted: no allocations/prepay/commissions to reverse,
  -- and the status trigger only allows →voided from posted/overdue. Route to 'cancelled'
  -- (draft→cancelled / unposted→cancelled are allowed transitions) and return.
  -- (A draft/unposted invoice can never carry a credit application — apply requires posted on
  --  both sides — so no credit reversal is needed on this branch.)
  IF v_inv.status IN ('draft', 'unposted') THEN
    UPDATE invoices SET status = 'cancelled', void_reason = p_void_reason, updated_at = now()
    WHERE id = p_invoice_id;

    IF v_inv.invoice_type = 'field_application' AND v_inv.job_id IS NOT NULL THEN
      SELECT * INTO v_job FROM jobs WHERE id = v_inv.job_id FOR UPDATE;
      IF FOUND AND v_job.status = 'invoiced' THEN
        IF EXISTS (SELECT 1 FROM invoices o
                   WHERE o.job_id = v_inv.job_id AND o.id <> p_invoice_id
                     AND o.invoice_type = 'field_application'
                     AND o.status NOT IN ('voided', 'cancelled') AND o.deleted_at IS NULL) THEN
          IF v_job.invoice_id IS NOT DISTINCT FROM p_invoice_id THEN
            UPDATE application_records SET invoice_id = (
              SELECT o.id FROM invoices o
               WHERE o.job_id = v_inv.job_id AND o.id <> p_invoice_id
                 AND o.invoice_type = 'field_application'
                 AND o.status NOT IN ('voided', 'cancelled') AND o.deleted_at IS NULL
               ORDER BY o.created_at, o.id LIMIT 1)
              WHERE source_type = 'job' AND source_id = v_inv.job_id AND invoice_id = p_invoice_id;
            SET LOCAL app.admin_override = 'true';
            UPDATE jobs SET invoice_id = (
              SELECT o.id FROM invoices o
               WHERE o.job_id = v_inv.job_id AND o.id <> p_invoice_id
                 AND o.invoice_type = 'field_application'
                 AND o.status NOT IN ('voided', 'cancelled') AND o.deleted_at IS NULL
               ORDER BY o.created_at, o.id LIMIT 1)
              WHERE id = v_inv.job_id;
            RESET app.admin_override;
          END IF;
        ELSE
          UPDATE application_records SET invoice_id = NULL
            WHERE source_type = 'job' AND source_id = v_inv.job_id AND invoice_id = p_invoice_id;
          SET LOCAL app.admin_override = 'true';
          UPDATE jobs SET status = 'completed', invoice_id = NULL WHERE id = v_inv.job_id;
          RESET app.admin_override;
        END IF;
      END IF;
    END IF;

    IF v_inv.invoice_type = 'field_application' AND v_inv.job_id IS NOT NULL THEN
      IF EXISTS (
        SELECT 1 FROM commissions c
        JOIN commission_payment_items cpi ON cpi.commission_id = c.id
        JOIN commission_payments cp ON cp.id = cpi.commission_payment_id
        WHERE c.job_id = v_inv.job_id AND c.invoice_id = p_invoice_id
          AND c.status = 'pending' AND cp.status <> 'voided'
      ) THEN
        RAISE EXCEPTION 'JOB_HAS_BATCHED_COMMISSIONS: this job invoice''s pending commissions are in an active payout batch — void that commission payment first';
      END IF;
      IF EXISTS (
        SELECT 1 FROM commissions
        WHERE job_id = v_inv.job_id AND invoice_id = p_invoice_id AND status = 'paid'
      ) THEN
        INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
        SELECT p.id, 'Job invoice cancelled — commissions already paid',
          'Invoice ' || v_inv.invoice_number || ' was cancelled but its commissions were already paid out. Manual review needed before the job is re-invoiced.',
          'commission_review', 'invoice', p_invoice_id
        FROM profiles p WHERE p.role = 'admin' AND p.is_active = true;
      END IF;
      UPDATE commissions SET status = 'cancelled', commission_amount = 0
        WHERE job_id = v_inv.job_id AND invoice_id = p_invoice_id AND status = 'pending';
      GET DIAGNOSTICS v_commissions_cancelled = ROW_COUNT;
    END IF;

    INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_role, old_values, new_values, total_impact_cents, description)
    VALUES ('invoice_cancelled', 'invoice', p_invoice_id, v_actor_role,
      jsonb_build_object('status', v_inv.status, 'total_cents', v_inv.total_amount_cents),
      jsonb_build_object('status', 'cancelled', 'void_reason', p_void_reason, 'commissions_cancelled', v_commissions_cancelled),
      0,
      'Cancelled ' || v_inv.invoice_number || ' (was ' || v_inv.status || ') — ' || p_void_reason);

    INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
    VALUES ('invoice_cancelled',
      'Cancelled invoice ' || v_inv.invoice_number || ' — ' || p_void_reason,
      auth.uid(), 'invoice', p_invoice_id, v_inv.customer_id);

    IF p_idempotency_key IS NOT NULL THEN
      PERFORM save_idempotency(p_idempotency_key, 'void_invoice', jsonb_build_object(
        'success', true, 'invoice_id', p_invoice_id, 'status', 'cancelled',
        'allocations_reversed_cents', 0, 'prepay_restored_cents', 0, 'commissions_cancelled', v_commissions_cancelled));
    END IF;
    RETURN;
  END IF;

  -- H3 fix: refuse to void a posted/overdue/paid invoice that still has direct
  -- cash applied. void_invoice reverses prepay + credit-memo applications below,
  -- but does NOT re-bank direct payments (paid_amount_cents) or payment
  -- allocations (invoice_line_allocations) — voiding would strand that cash.
  -- The admin must void/unapply those payments first (void_payment re-banks the
  -- cash as customer prepay), then void the invoice. Prepay-only and
  -- credit-memo-only voids carry neither and are unaffected.
  IF v_inv.paid_amount_cents > 0
     OR EXISTS (
       SELECT 1
       FROM invoice_line_allocations ila
       JOIN allocation_sets aset ON aset.id = ila.allocation_set_id
       WHERE ila.invoice_id = p_invoice_id
         AND aset.entity_type = 'payment'
         AND aset.is_active = true
     ) THEN
    RAISE EXCEPTION 'INVOICE_HAS_APPLIED_PAYMENTS: invoice % has $% in applied payments — void or unapply those payments first (that re-banks the cash as prepay), then void the invoice',
      v_inv.invoice_number, (v_inv.paid_amount_cents / 100.0)::numeric(12,2);
  END IF;

  IF v_inv.status IN ('posted', 'paid', 'overdue') THEN PERFORM check_period_open(v_inv.invoice_date); END IF;

  -- CREDIT-APPLY: reverse every active credit-memo application that touches this invoice
  -- (as the credit memo OR as the target) BEFORE zeroing its levers. This restores the other
  -- side and drains this invoice's credit_applied_cents to 0; without it a voided target would
  -- leave credit_applied_cents set and violate invoices_balance_non_negative, and a voided memo
  -- would strand the credit it handed out (Codex #4).
  -- Codex BLOCKER: the enclosing void only period-checks status='posted', but a credited target is
  -- 'paid'/'overdue'. Each application's reversal is a money movement, so gate it on THAT
  -- application's own period (applied_at) before touching it.
  -- Codex MED (accepted, not fixed): void locks THIS invoice first, then the helper locks both sides
  -- in id order — two concurrent voids of a memo and its target can deadlock. Postgres detects it and
  -- aborts one cleanly (money stays atomic; the operator retries). Rare + non-corrupting, so it is
  -- left as a safe-abort rather than a global pre-lock of all counterparties.
  FOR v_capp IN
    SELECT id, applied_at FROM credit_memo_applications
     WHERE reversed_at IS NULL
       AND (credit_memo_id = p_invoice_id OR target_invoice_id = p_invoice_id)
     ORDER BY id
  LOOP
    PERFORM check_period_open(v_capp.applied_at::date);
    PERFORM _reverse_credit_memo_application(v_capp.id, auth.uid(), v_actor_role,
      'Auto-reversed: invoice ' || v_inv.invoice_number || ' voided — ' || p_void_reason);
  END LOOP;

  SELECT ARRAY(SELECT DISTINCT ila.allocation_set_id FROM invoice_line_allocations ila
    WHERE ila.invoice_id = p_invoice_id AND ila.allocation_set_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM allocation_sets hist WHERE hist.id = ila.allocation_set_id
        AND hist.entity_type = 'payment' AND hist.is_active = false)) INTO v_allocation_set_ids;

  FOR v_alloc IN SELECT ila.id, ila.amount_cents, ila.allocation_set_id FROM invoice_line_allocations ila
    WHERE ila.invoice_id = p_invoice_id
      AND NOT EXISTS (SELECT 1 FROM allocation_sets hist WHERE hist.id = ila.allocation_set_id
        AND hist.entity_type = 'payment' AND hist.is_active = false) LOOP
    v_total_allocations_reversed := v_total_allocations_reversed + v_alloc.amount_cents;
    DELETE FROM invoice_line_allocations WHERE id = v_alloc.id;
  END LOOP;

  IF v_total_allocations_reversed > 0 AND array_length(v_allocation_set_ids, 1) > 0 THEN
    UPDATE allocation_sets SET total_allocated_cents = (SELECT COALESCE(SUM(amount_cents), 0)
      FROM invoice_line_allocations WHERE allocation_set_id = allocation_sets.id),
      updated_at = now() WHERE id = ANY(v_allocation_set_ids);
  END IF;

  FOR v_prepay_app IN SELECT pa.id, pa.applied_amount_cents, pa.prepay_credit_id FROM prepay_applications pa
    WHERE pa.invoice_id = p_invoice_id LOOP
    v_total_prepay_restored := v_total_prepay_restored + v_prepay_app.applied_amount_cents;
    UPDATE prepay_credits SET balance_cents = balance_cents + v_prepay_app.applied_amount_cents,
      updated_at = now() WHERE id = v_prepay_app.prepay_credit_id;
    DELETE FROM prepay_applications WHERE id = v_prepay_app.id;
  END LOOP;

  IF v_total_prepay_restored > 0 THEN
    UPDATE customers SET prepay_balance_cents = COALESCE(prepay_balance_cents, 0) + v_total_prepay_restored,
      updated_at = now() WHERE id = v_inv.customer_id;
  END IF;

  -- CREDIT-APPLY: credit_applied_cents = 0 added (all applications reversed above → already 0;
  -- explicit for safety so the voided row's balance is unambiguously 0).
  UPDATE invoices SET status = 'voided', voided_by = auth.uid(), voided_at = now(),
    void_reason = p_void_reason, total_amount_cents = 0, paid_amount_cents = 0,
    prepay_applied_cents = 0, write_off_cents = 0, credit_applied_cents = 0, updated_at = now()
  WHERE id = p_invoice_id;

  -- Codex HIGH: a generic void of a CREDIT MEMO must also release its linked return (mirroring
  -- unapply_credit_memo), or the return stays 'credited' pointing at a voided memo and can never be
  -- re-credited. Regular invoices have no such link, so the guard scopes this to credit memos.
  IF v_inv.invoice_type = 'credit_memo' THEN
    PERFORM set_config('app.admin_override', 'true', true);
    UPDATE returns SET
      status = 'received', credit_invoice_id = NULL, total_credit_cents = 0,
      credited_at = NULL, credited_by = NULL, updated_at = now()
    WHERE credit_invoice_id = p_invoice_id;
    PERFORM set_config('app.admin_override', 'false', true);
  END IF;

  IF v_inv.invoice_type = 'field_application' AND v_inv.job_id IS NOT NULL THEN
    SELECT * INTO v_job FROM jobs WHERE id = v_inv.job_id FOR UPDATE;
    IF FOUND AND v_job.status = 'invoiced' THEN
      IF EXISTS (SELECT 1 FROM invoices o
                 WHERE o.job_id = v_inv.job_id AND o.id <> p_invoice_id
                   AND o.invoice_type = 'field_application'
                   AND o.status NOT IN ('voided', 'cancelled') AND o.deleted_at IS NULL) THEN
        IF v_job.invoice_id IS NOT DISTINCT FROM p_invoice_id THEN
          UPDATE application_records SET invoice_id = (
            SELECT o.id FROM invoices o
             WHERE o.job_id = v_inv.job_id AND o.id <> p_invoice_id
               AND o.invoice_type = 'field_application'
               AND o.status NOT IN ('voided', 'cancelled') AND o.deleted_at IS NULL
             ORDER BY o.created_at, o.id LIMIT 1)
            WHERE source_type = 'job' AND source_id = v_inv.job_id AND invoice_id = p_invoice_id;
          SET LOCAL app.admin_override = 'true';
          UPDATE jobs SET invoice_id = (
            SELECT o.id FROM invoices o
             WHERE o.job_id = v_inv.job_id AND o.id <> p_invoice_id
               AND o.invoice_type = 'field_application'
               AND o.status NOT IN ('voided', 'cancelled') AND o.deleted_at IS NULL
             ORDER BY o.created_at, o.id LIMIT 1)
            WHERE id = v_inv.job_id;
          RESET app.admin_override;
        END IF;
      ELSE
        UPDATE application_records SET invoice_id = NULL
          WHERE source_type = 'job' AND source_id = v_inv.job_id AND invoice_id = p_invoice_id;
        SET LOCAL app.admin_override = 'true';
        UPDATE jobs SET status = 'completed', invoice_id = NULL WHERE id = v_inv.job_id;
        RESET app.admin_override;
      END IF;
    END IF;
  END IF;

  IF v_inv.order_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM invoices WHERE order_id = v_inv.order_id
        AND id != p_invoice_id AND status NOT IN ('voided', 'cancelled') AND deleted_at IS NULL) THEN
      UPDATE commissions SET status = 'cancelled' WHERE order_id = v_inv.order_id AND status = 'pending';
      GET DIAGNOSTICS v_commissions_cancelled = ROW_COUNT;
    END IF;
  END IF;

  IF v_inv.invoice_type = 'field_application' AND v_inv.job_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM commissions c
      JOIN commission_payment_items cpi ON cpi.commission_id = c.id
      JOIN commission_payments cp ON cp.id = cpi.commission_payment_id
      WHERE c.job_id = v_inv.job_id AND c.invoice_id = p_invoice_id
        AND c.status = 'pending' AND cp.status <> 'voided'
    ) THEN
      RAISE EXCEPTION 'JOB_HAS_BATCHED_COMMISSIONS: this job invoice''s pending commissions are in an active payout batch — void that commission payment first';
    END IF;
    IF EXISTS (
      SELECT 1 FROM commissions
      WHERE job_id = v_inv.job_id AND invoice_id = p_invoice_id AND status = 'paid'
    ) THEN
      INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
      SELECT p.id, 'Job invoice voided — commissions already paid',
        'Invoice ' || v_inv.invoice_number || ' was voided but its commissions were already paid out. Manual review needed before the job is re-invoiced.',
        'commission_review', 'invoice', p_invoice_id
      FROM profiles p WHERE p.role = 'admin' AND p.is_active = true;
    END IF;
    UPDATE commissions SET status = 'cancelled', commission_amount = 0
      WHERE job_id = v_inv.job_id AND invoice_id = p_invoice_id AND status = 'pending';
    GET DIAGNOSTICS v_commissions_cancelled = ROW_COUNT;
  END IF;

  INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_role, old_values, new_values, total_impact_cents, description)
  VALUES ('invoice_voided', 'invoice', p_invoice_id, v_actor_role,
    jsonb_build_object('status', v_inv.status, 'total_cents', v_inv.total_amount_cents, 'paid_amount_cents', v_inv.paid_amount_cents, 'prepay_applied_cents', v_inv.prepay_applied_cents, 'write_off_cents', v_inv.write_off_cents),
    jsonb_build_object('status', 'voided', 'void_reason', p_void_reason, 'allocations_reversed_cents', v_total_allocations_reversed, 'prepay_restored_cents', v_total_prepay_restored, 'commissions_cancelled', v_commissions_cancelled),
    -1 * v_inv.total_amount_cents,
    'Voided ' || v_inv.invoice_number || ' — ' || p_void_reason ||
      CASE WHEN v_total_allocations_reversed > 0 THEN '. Reversed $' || (v_total_allocations_reversed / 100.0)::text || ' in allocations.' ELSE '' END ||
      CASE WHEN v_total_prepay_restored > 0 THEN ' Restored $' || (v_total_prepay_restored / 100.0)::text || ' in prepay credits.' ELSE '' END ||
      CASE WHEN v_commissions_cancelled > 0 THEN ' Cancelled ' || v_commissions_cancelled || ' pending commission(s).' ELSE '' END);

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('invoice_voided',
    'Voided invoice ' || v_inv.invoice_number || ' — ' || p_void_reason ||
      CASE WHEN v_total_allocations_reversed > 0 THEN '. Reversed $' || (v_total_allocations_reversed / 100.0)::text || ' in allocations.' ELSE '' END ||
      CASE WHEN v_total_prepay_restored > 0 THEN ' Restored $' || (v_total_prepay_restored / 100.0)::text || ' in prepay credits.' ELSE '' END ||
      CASE WHEN v_commissions_cancelled > 0 THEN ' Cancelled ' || v_commissions_cancelled || ' pending commission(s).' ELSE '' END,
    auth.uid(), 'invoice', p_invoice_id, v_inv.customer_id);

  IF v_total_allocations_reversed > 0 OR v_total_prepay_restored > 0 OR v_commissions_cancelled > 0 THEN
    INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
    SELECT p.id, 'Invoice Voided — Allocations Reversed',
      'Invoice ' || v_inv.invoice_number || ' voided. $' ||
        (v_total_allocations_reversed / 100.0)::text || ' in allocations reversed, $' ||
        (v_total_prepay_restored / 100.0)::text || ' in prepay credits restored.' ||
        CASE WHEN v_commissions_cancelled > 0 THEN ' ' || v_commissions_cancelled || ' pending commission(s) cancelled.' ELSE '' END,
      'invoice_void_reversal', 'invoice', p_invoice_id
    FROM profiles p WHERE p.role = 'admin' AND p.is_active = true;
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'void_invoice', jsonb_build_object(
      'success', true, 'invoice_id', p_invoice_id,
      'allocations_reversed_cents', v_total_allocations_reversed,
      'prepay_restored_cents', v_total_prepay_restored,
      'commissions_cancelled', v_commissions_cancelled));
  END IF;
END;
$_$;


ALTER FUNCTION "public"."_void_invoice_split_provenance_impl_20260719"("p_invoice_id" "uuid", "p_void_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_void_order_impl_20260714"("p_order_id" "uuid", "p_performed_by" "uuid", "p_reason" "text" DEFAULT 'Voided by admin'::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_order record;
  v_item record;
  v_invoice record;
  v_admin record;
  v_inventory_restored integer := 0;
  v_commissions_cancelled integer := 0;
  v_paid_commissions integer := 0;
  v_draft_voided integer := 0;
  v_posted_notified integer := 0;
  v_existing jsonb;
  v_result jsonb;
  -- A3<<<
  v_draw_item record;
  v_draw_quote record;
  v_draw_fully_drawn boolean;
  -- >>>A3
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT is_admin() THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'void_order');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF;
  IF v_order.status != 'fulfilled' THEN
    RAISE EXCEPTION 'INVALID_ORDER_STATUS: %', v_order.status;
  END IF;

  -- Commission batch-freeze guard (overnight bug-hunt HIGH, 20260620): a pending
  -- commission already committed to a non-voided commission_payments batch must not
  -- be silently cancelled here — post_commission_payment would later resurrect it to
  -- 'paid' and pay the retained snapshot. Force the admin to void the payout first.
  IF EXISTS (
    SELECT 1
    FROM public.commissions cm
    JOIN public.commission_payment_items cpi ON cpi.commission_id = cm.id
    JOIN public.commission_payments cp ON cp.id = cpi.commission_payment_id
    WHERE cm.order_id = p_order_id
      AND cm.status = 'pending'
      AND cp.status <> 'voided'
  ) THEN
    RAISE EXCEPTION 'ORDER_HAS_BATCHED_COMMISSIONS: order % has pending commission(s) committed to an active commission payment batch. Void that payment first, then void the order.', v_order.order_number;
  END IF;

  -- fulfilled→voided is a deliberate admin reversal the status-transition trigger does not
  -- include; bracket ONLY this write with the transaction-local admin override.
  PERFORM set_config('app.admin_override', 'true', true);
  UPDATE public.orders
    SET status = 'voided',
        updated_at = now()
  WHERE id = p_order_id;
  PERFORM set_config('app.admin_override', 'false', true);
  -- A3<<< draw-ledger reversal (finding A3, 20260610190000 — see file header).
  -- void = the order is nulled and goods return to the warehouse, so the FULL
  -- drawn quantity goes back to the booking balance.
  IF COALESCE(v_order.booking_draw, false) AND v_order.quote_id IS NOT NULL THEN
    -- Lock the parent quote first: same quote → inventory order as
    -- draw_down_quote, and serializes against a concurrent draw.
    SELECT * INTO v_draw_quote FROM public.quotes
    WHERE id = v_order.quote_id FOR UPDATE;

    FOR v_draw_item IN
      SELECT product_id, SUM(COALESCE(total_units_needed, 0)) AS qty_drawn
      FROM public.order_items
      WHERE order_id = p_order_id AND product_id IS NOT NULL
      GROUP BY product_id
      HAVING SUM(COALESCE(total_units_needed, 0)) > 0
    LOOP
      UPDATE public.quote_product_draws
        SET quantity_drawn = GREATEST(quantity_drawn - v_draw_item.qty_drawn, 0),
            updated_at = now()
      WHERE quote_id = v_order.quote_id
        AND product_id = v_draw_item.product_id;
    END LOOP;

    -- If this was the final draw, the quote sits at 'accepted'; with the
    -- balance restored it is no longer fully drawn, so reopen the booking.
    IF v_draw_quote.status = 'accepted' THEN
      SELECT COALESCE(bool_and(COALESCE(d.quantity_drawn, 0) >= b.booked), true) INTO v_draw_fully_drawn
      FROM (
        SELECT product_id, SUM(COALESCE(total_units_needed, 0)) AS booked
        FROM public.quote_items WHERE quote_id = v_order.quote_id
        GROUP BY product_id
      ) b
      LEFT JOIN public.quote_product_draws d
        ON d.quote_id = v_order.quote_id AND d.product_id = b.product_id
      WHERE b.booked > 0;

      IF NOT v_draw_fully_drawn THEN
        -- accepted→sent is enforcer-legal on the live enforcer today; the
        -- override bracket is defense-in-depth (see file header).
        PERFORM set_config('app.admin_override', 'true', true);
        UPDATE public.quotes SET status = 'sent', updated_at = now()
        WHERE id = v_order.quote_id;
        PERFORM set_config('app.admin_override', 'false', true);

        INSERT INTO public.activity_feed (event_type, description, performed_by,
          related_entity_type, related_entity_id, customer_id)
        VALUES ('booking_reopened',
          'Booking ' || v_draw_quote.quote_number || ' reopened (accepted → sent): draw order ' ||
            v_order.order_number || ' was voided, returning its drawn quantity to the booking balance',
          v_actor, 'quote', v_order.quote_id, v_draw_quote.customer_id);
      END IF;
    END IF;
    -- VOID-1 fix (2026-06-13): the draw moved hold→prebooked; complete_delivery
    -- drained the prebooked to 0 before fulfilment, and the drawn ledger was just
    -- reversed above, so the still-OPEN booking's hold must be REBUILT to
    -- booked−drawn — a preserved (decremented) hold leaks the returned quantity
    -- out of the reservation (Net Free over-counts). Runs for every booking_draw
    -- void (reopened or not). The helper self-gates for non-planned/closed quotes.
    -- Symmetric twin of the cancel_order fix (20260613150100).
    PERFORM _sync_planned_holds(v_order.quote_id, v_actor);
  END IF;
  -- >>>A3

  FOR v_item IN
    SELECT product_id, quantity_delivered
    FROM public.order_items
    WHERE order_id = p_order_id
      AND COALESCE(quantity_delivered, 0) > 0
  LOOP
    UPDATE public.inventory
      SET quantity_available = quantity_available + v_item.quantity_delivered,
          updated_at = now()
    WHERE product_id = v_item.product_id
      AND location = 'Main Warehouse';

    INSERT INTO public.inventory_transactions (
      product_id, transaction_type, quantity, to_location,
      order_id, performed_by, notes
    ) VALUES (
      v_item.product_id,
      'void_delivery_reversal',
      v_item.quantity_delivered,
      'Main Warehouse',
      p_order_id,
      v_actor,
      'Restored ' || v_item.quantity_delivered || ' units - order ' ||
        v_order.order_number || ' voided. Reason: ' || p_reason
    );

    v_inventory_restored := v_inventory_restored + 1;
  END LOOP;

  UPDATE public.commissions
    SET status = 'cancelled',
        commission_amount = 0
  WHERE order_id = p_order_id
    AND status = 'pending';
  GET DIAGNOSTICS v_commissions_cancelled = ROW_COUNT;

  SELECT COUNT(*) INTO v_paid_commissions
  FROM public.commissions
  WHERE order_id = p_order_id AND status = 'paid';

  IF v_paid_commissions > 0 THEN
    FOR v_admin IN
      SELECT id FROM public.profiles WHERE role = 'admin' AND is_active = true
    LOOP
      INSERT INTO public.notifications (
        user_id, title, message,
        notification_type,
        related_entity_type,
        related_entity_id
      ) VALUES (
        v_admin.id,
        'Voided Order Has Paid Commissions',
        'Order ' || v_order.order_number || ' was voided but has ' ||
          v_paid_commissions || ' paid commission(s). Manual review required.',
        'void_review', 'order', p_order_id
      );
    END LOOP;
  END IF;

  FOR v_invoice IN
    SELECT * FROM public.invoices
    WHERE order_id = p_order_id
      AND deleted_at IS NULL
      AND status IN ('draft', 'posted')
  LOOP
    IF v_invoice.status = 'draft' THEN
      -- never-posted draft has no financial impact: cancel (allowed transition), do not void.
      UPDATE public.invoices
        SET status = 'cancelled',
            void_reason = 'Order ' || v_order.order_number || ' voided. ' || p_reason,
            updated_at = now()
      WHERE id = v_invoice.id;

      INSERT INTO public.financial_audit_log (
        operation_type,
        entity_type,
        entity_id,
        actor_role,
        old_values, new_values, total_impact_cents, description
      ) VALUES (
        'invoice_cancelled', 'invoice', v_invoice.id, 'admin',
        jsonb_build_object('status', 'draft', 'total_cents', v_invoice.total_amount_cents),
        jsonb_build_object('status', 'cancelled', 'void_reason', 'Order voided'),
        -1 * v_invoice.total_amount_cents,
        'Auto-cancelled draft invoice ' || v_invoice.invoice_number ||
          ' - order ' || v_order.order_number || ' voided'
      );

      v_draft_voided := v_draft_voided + 1;
    ELSIF v_invoice.status = 'posted' THEN
      FOR v_admin IN
        SELECT id FROM public.profiles WHERE role = 'admin' AND is_active = true
      LOOP
        INSERT INTO public.notifications (
          user_id, title, message,
          notification_type,
          related_entity_type,
          related_entity_id
        ) VALUES (
          v_admin.id,
          'Voided Order - Posted Invoice Needs Review',
          'Order ' || v_order.order_number || ' was voided. Invoice ' ||
            v_invoice.invoice_number || ' is posted and needs manual voiding.',
          'void_review', 'invoice', v_invoice.id
        );
      END LOOP;

      v_posted_notified := v_posted_notified + 1;
    END IF;
  END LOOP;

  INSERT INTO public.financial_audit_log (
    operation_type,
    entity_type,
    entity_id,
    actor_role,
    old_values, new_values, total_impact_cents, description
  ) VALUES (
    'order_voided', 'order', p_order_id, 'admin',
    jsonb_build_object('status', 'fulfilled', 'total_price', v_order.total_price),
    jsonb_build_object('status', 'voided', 'void_reason', p_reason),
    -1 * ROUND(v_order.total_price * 100)::bigint,
    'Order ' || v_order.order_number || ' voided. Reason: ' || p_reason
  );

  INSERT INTO public.activity_feed (
    event_type, description, performed_by,
    related_entity_type,
    related_entity_id,
    customer_id
  ) VALUES (
    'order_voided',
    'Order ' || v_order.order_number || ' voided. ' ||
      v_inventory_restored || ' product(s) inventory restored. ' ||
      v_commissions_cancelled || ' commission(s) cancelled. ' ||
      v_draft_voided || ' draft invoice(s) cancelled.' ||
      CASE WHEN v_posted_notified > 0
           THEN ' ' || v_posted_notified || ' posted invoice(s) flagged for review.'
           ELSE '' END ||
      CASE WHEN v_paid_commissions > 0
           THEN ' ' || v_paid_commissions || ' paid commission(s) flagged for review.'
           ELSE '' END ||
      ' Reason: ' || p_reason,
    v_actor, 'order', p_order_id, v_order.customer_id
  );

  v_result := jsonb_build_object(
    'status', 'voided',
    'order_number', v_order.order_number,
    'inventory_products_restored', v_inventory_restored,
    'commissions_cancelled', v_commissions_cancelled,
    'paid_commissions_flagged', v_paid_commissions,
    'draft_invoices_voided', v_draft_voided,
    'posted_invoices_flagged', v_posted_notified
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'void_order', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."_void_order_impl_20260714"("p_order_id" "uuid", "p_performed_by" "uuid", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_inventory"("p_inventory_id" "uuid", "p_delta" numeric, "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_inv record;
  v_new_qty numeric;
  v_cached_result jsonb;
  v_result jsonb;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    v_cached_result := check_idempotency(p_idempotency_key, 'adjust_inventory');
    IF v_cached_result IS NOT NULL THEN
      RETURN v_cached_result;
    END IF;
  END IF;

  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by <> v_actor THEN
    RAISE EXCEPTION 'Actor mismatch';
  END IF;

  IF p_delta = 0 THEN
    RAISE EXCEPTION 'Adjustment quantity cannot be zero';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_actor AND role = 'admin' AND is_active = true
  ) THEN
    RAISE EXCEPTION 'Only admins can adjust inventory';
  END IF;

  SELECT * INTO v_inv FROM inventory WHERE id = p_inventory_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory record not found';
  END IF;

  v_new_qty := v_inv.quantity_available + p_delta;

  IF v_new_qty < 0 THEN
    RAISE EXCEPTION 'Adjustment would result in negative inventory (current: %, delta: %, result: %)',
      v_inv.quantity_available, p_delta, v_new_qty;
  END IF;

  UPDATE inventory SET
    quantity_available = v_new_qty,
    updated_at = now()
  WHERE id = p_inventory_id;

  INSERT INTO inventory_transactions (
    product_id, transaction_type, quantity,
    to_location, performed_by, notes
  ) VALUES (
    v_inv.product_id, 'adjusted', p_delta,
    v_inv.location, v_actor,
    COALESCE(NULLIF(TRIM(p_reason), ''), 'Manual adjustment of ' || p_delta || ' units')
  );

  v_result := jsonb_build_object(
    'status', 'adjusted',
    'new_quantity', v_new_qty,
    'product_id', v_inv.product_id
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'adjust_inventory', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."adjust_inventory"("p_inventory_id" "uuid", "p_delta" numeric, "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_profile"("target_user_id" "uuid", "new_role" "text" DEFAULT NULL::"text", "new_full_name" "text" DEFAULT NULL::"text", "new_phone" "text" DEFAULT NULL::"text", "new_is_active" boolean DEFAULT NULL::boolean, "new_denied_pages" "text"[] DEFAULT NULL::"text"[], "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  caller_role text;
  caller_active boolean;
  updated_count int;
  v_final_role text;
  v_existing jsonb;
BEGIN
  PERFORM require_admin();
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'admin_update_profile');
    IF v_existing IS NOT NULL THEN RETURN v_existing::json; END IF;
  END IF;
  SELECT role, is_active INTO caller_role, caller_active
  FROM profiles WHERE id = (SELECT auth.uid());
  IF caller_role IS NULL OR caller_role != 'admin' OR caller_active != true THEN
    RETURN json_build_object('error', 'Active admin access required');
  END IF;
  IF new_role IS NOT NULL AND new_role NOT IN ('admin', 'sales_rep', 'driver', 'applicator') THEN
    RETURN json_build_object('error', 'Invalid role. Must be admin, sales_rep, driver, or applicator');
  END IF;
  IF new_role IS NOT NULL THEN
    v_final_role := new_role;
  ELSE
    SELECT role INTO v_final_role FROM profiles WHERE id = target_user_id;
  END IF;
  IF v_final_role = 'admin' AND new_denied_pages IS NOT NULL THEN
    new_denied_pages := '{}';
  END IF;
  UPDATE profiles SET
    role = COALESCE(new_role, role),
    full_name = COALESCE(new_full_name, full_name),
    phone = COALESCE(new_phone, phone),
    is_active = COALESCE(new_is_active, is_active),
    denied_pages = COALESCE(new_denied_pages, denied_pages),
    updated_at = now()
  WHERE id = target_user_id;
  GET DIAGNOSTICS updated_count = ROW_COUNT;
  IF updated_count = 0 THEN
    RETURN json_build_object('error', 'User not found');
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'admin_update_profile', '{"success": true}'::jsonb);
  END IF;
  RETURN json_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."admin_update_profile"("target_user_id" "uuid", "new_role" "text", "new_full_name" "text", "new_phone" "text", "new_is_active" boolean, "new_denied_pages" "text"[], "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."allocate_payment"("p_customer_id" "uuid", "p_total_cents" bigint, "p_payment_method" "text", "p_reference_number" "text" DEFAULT NULL::"text", "p_check_number" "text" DEFAULT NULL::"text", "p_payment_date" "date" DEFAULT CURRENT_DATE, "p_notes" "text" DEFAULT NULL::"text", "p_allocations" "jsonb" DEFAULT '[]'::"jsonb", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid;
  v_cached_result jsonb;
  v_alloc jsonb;
  v_inv record;
  v_alloc_cents bigint;
  v_sum_allocated bigint := 0;
  v_set_id uuid;
  v_current_season integer;
  v_prepay_cents bigint;
  v_result jsonb;
  v_allocation_count integer := 0;
  v_next_version integer;
  v_customer_name text;
  v_idem_request jsonb;
  v_idem_row record;
  v_idem_claim_count integer := 0;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_idem_request := jsonb_build_object(
      'customer_id', p_customer_id,
      'total_cents', p_total_cents,
      'payment_method', p_payment_method,
      'reference_number', p_reference_number,
      'check_number', p_check_number,
      'payment_date', p_payment_date,
      'notes', p_notes,
      'allocations', p_allocations,
      'performed_by', p_performed_by,
      'authenticated_actor', v_actor
    );

    -- Preserve check_idempotency()'s expiry behavior before claiming the key.
    DELETE FROM idempotency_keys WHERE expires_at < now();

    -- Atomic claim. A concurrent INSERT for this key blocks on the UNIQUE
    -- constraint. If its transaction commits, this INSERT takes the conflict
    -- path; if it rolls back, this INSERT succeeds and owns the claim.
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (
      p_idempotency_key,
      'allocate_payment',
      jsonb_build_object(
        '_contract', 'allocate_payment_v1',
        'request', v_idem_request,
        'response', NULL
      )
    )
    ON CONFLICT (idempotency_key) DO NOTHING;

    GET DIAGNOSTICS v_idem_claim_count = ROW_COUNT;

    IF v_idem_claim_count = 0 THEN
      SELECT operation, result INTO v_idem_row
      FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'IDEMPOTENCY_CLAIM_LOST: key % disappeared after conflict', p_idempotency_key;
      END IF;

      IF v_idem_row.operation IS DISTINCT FROM 'allocate_payment' THEN
        RAISE EXCEPTION 'IDEMPOTENCY_CROSS_OP_KEY_REUSE: idempotency_key % is already in use for operation %; cannot reuse it for operation %',
          p_idempotency_key, v_idem_row.operation, 'allocate_payment';
      END IF;

      IF v_idem_row.result->>'_contract' = 'allocate_payment_v1' THEN
        IF v_idem_row.result->'request' IS DISTINCT FROM v_idem_request THEN
          RAISE EXCEPTION 'IDEMPOTENCY_ARGUMENT_MISMATCH: key % was already used for different allocate_payment arguments',
            p_idempotency_key;
        END IF;

        v_cached_result := v_idem_row.result->'response';
        IF v_cached_result IS NULL OR v_cached_result = 'null'::jsonb THEN
          RAISE EXCEPTION 'IDEMPOTENCY_RESULT_NOT_READY: key % has no committed allocate_payment result',
            p_idempotency_key;
        END IF;

        RETURN v_cached_result;
      END IF;

      -- Rows written before this migration contain the bare cached response
      -- and no request metadata. Keep their sequential replay behavior.
      IF v_idem_row.result IS NOT NULL THEN
        RETURN v_idem_row.result;
      END IF;

      RAISE EXCEPTION 'IDEMPOTENCY_RESULT_NOT_READY: legacy key % has no cached allocate_payment result',
        p_idempotency_key;
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Not authorized to allocate payments';
  END IF;

  IF p_total_cents <= 0 THEN RAISE EXCEPTION 'Payment amount must be positive'; END IF;

  PERFORM check_period_open(p_payment_date);

  SELECT farm_name INTO v_customer_name FROM customers WHERE id = p_customer_id;

  v_current_season := CASE WHEN extract(month FROM CURRENT_DATE) >= 10
    THEN extract(year FROM CURRENT_DATE)::integer + 1
    ELSE extract(year FROM CURRENT_DATE)::integer END;

  SELECT COALESCE(MAX(version), 0) + 1 INTO v_next_version
  FROM allocation_sets WHERE entity_type = 'payment' AND entity_id = p_customer_id;

  INSERT INTO allocation_sets (
    entity_type, entity_id, version,
    customer_id, total_payment_cents, payment_method,
    reference_number, check_number, payment_date,
    notes, season, created_by
  ) VALUES (
    'payment', p_customer_id, v_next_version,
    p_customer_id, p_total_cents, p_payment_method,
    p_reference_number, p_check_number, p_payment_date,
    p_notes, v_current_season, v_actor
  ) RETURNING id INTO v_set_id;

  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations)
  LOOP
    v_alloc_cents := (v_alloc->>'amount_cents')::bigint;
    IF v_alloc_cents <= 0 THEN CONTINUE; END IF;

    SELECT * INTO v_inv FROM invoices
    WHERE id = (v_alloc->>'invoice_id')::uuid
      AND customer_id = p_customer_id
      AND status IN ('posted', 'overdue')
      AND deleted_at IS NULL
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Invoice % not found or not eligible for payment', (v_alloc->>'invoice_id');
    END IF;

    IF v_alloc_cents > v_inv.balance_cents THEN
      RAISE EXCEPTION 'Allocation ($%) exceeds balance ($%) on invoice %',
        v_alloc_cents, v_inv.balance_cents, v_inv.invoice_number;
    END IF;

    INSERT INTO invoice_line_allocations (
      allocation_set_id, invoice_id, amount_cents,
      bill_to_customer_id, split_percentage
    ) VALUES (
      v_set_id, v_inv.id, v_alloc_cents, p_customer_id, 100
    );

    UPDATE invoices SET
      paid_amount_cents = paid_amount_cents + v_alloc_cents,
      status = CASE
        -- CREDIT-APPLY: include credit_applied_cents in the →paid recompute
        WHEN (total_amount_cents - (paid_amount_cents + v_alloc_cents) - prepay_applied_cents - write_off_cents - credit_applied_cents) <= 0
        THEN 'paid'
        ELSE status
      END,
      updated_at = now()
    WHERE id = v_inv.id;

    v_sum_allocated := v_sum_allocated + v_alloc_cents;
    v_allocation_count := v_allocation_count + 1;
  END LOOP;

  IF v_sum_allocated > p_total_cents THEN
    RAISE EXCEPTION 'OVER_ALLOCATED: allocations total $% but payment is only $%',
      (v_sum_allocated / 100.0)::numeric(12,2), (p_total_cents / 100.0)::numeric(12,2);
  END IF;

  UPDATE allocation_sets SET
    total_allocated_cents = v_sum_allocated,
    updated_at = now()
  WHERE id = v_set_id;

  v_prepay_cents := p_total_cents - v_sum_allocated;
  IF v_prepay_cents > 0 THEN
    INSERT INTO prepay_credits (
      customer_id, season, original_amount_cents, balance_cents,
      source_type, source_reference, allocation_set_id, created_by
    ) VALUES (
      p_customer_id, v_current_season, v_prepay_cents, v_prepay_cents,
      'overpayment', 'From payment ' || COALESCE(p_reference_number, p_check_number, v_set_id::text),
      v_set_id,
      v_actor
    );
    UPDATE customers SET
      prepay_balance_cents = COALESCE(prepay_balance_cents, 0) + v_prepay_cents,
      updated_at = now()
    WHERE id = p_customer_id;
  END IF;

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'payment_allocated',
    'Payment of $' || (p_total_cents / 100.0)::text || ' allocated (' || v_allocation_count || ' invoices)',
    v_actor, 'allocation_set', v_set_id, p_customer_id
  );

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    new_values, total_impact_cents, description
  ) VALUES (
    'payment_allocated', 'allocation_set', v_set_id,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object(
      'customer_id', p_customer_id,
      'customer_name', v_customer_name,
      'payment_method', p_payment_method,
      'reference_number', p_reference_number,
      'total_cents', p_total_cents,
      'allocated_cents', v_sum_allocated,
      'prepay_cents', v_prepay_cents,
      'invoices_paid', v_allocation_count
    ),
    p_total_cents,
    'Payment $' || (p_total_cents / 100.0)::numeric(12,2) || ' from ' ||
    COALESCE(v_customer_name, 'customer') || ' via ' || p_payment_method ||
    CASE WHEN v_prepay_cents > 0 THEN ' ($' || (v_prepay_cents / 100.0)::numeric(12,2) || ' to prepay)' ELSE '' END
  );

  v_result := jsonb_build_object(
    'success', true,
    'allocation_set_id', v_set_id,
    'total_allocated_cents', v_sum_allocated,
    'prepay_created_cents', v_prepay_cents,
    'invoices_paid', v_allocation_count
  );

  IF p_idempotency_key IS NOT NULL THEN
    UPDATE idempotency_keys
    SET result = jsonb_build_object(
      '_contract', 'allocate_payment_v1',
      'request', v_idem_request,
      'response', v_result
    )
    WHERE idempotency_key = p_idempotency_key
      AND operation = 'allocate_payment';
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."allocate_payment"("p_customer_id" "uuid", "p_total_cents" bigint, "p_payment_method" "text", "p_reference_number" "text", "p_check_number" "text", "p_payment_date" "date", "p_notes" "text", "p_allocations" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_credit_memo_to_invoice"("p_credit_memo_id" "uuid", "p_target_invoice_id" "uuid", "p_amount_cents" bigint, "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor      uuid;
  v_actor_role text;
  v_memo       record;
  v_target     record;
  v_first      uuid;
  v_second     uuid;
  v_remaining  bigint;
  v_app_id     uuid;
  v_existing   jsonb;
BEGIN
  -- ---- gates (auth / actor / role) ----
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  -- Codex BLOCKER: an inactive/absent profile yields NULL, and `NULL NOT IN (...)` is NOT true,
  -- so the bare NOT IN would let a deactivated-but-still-authenticated user through. Guard the NULL.
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: only active admins and sales reps can apply credit memos';
  END IF;

  -- ---- cheap argument guards ----
  IF p_credit_memo_id = p_target_invoice_id THEN
    RAISE EXCEPTION 'INVALID_TARGET: a credit memo cannot be applied to itself';
  END IF;
  IF p_amount_cents IS NULL OR p_amount_cents <= 0 THEN
    RAISE EXCEPTION 'INVALID_AMOUNT: application amount must be positive';
  END IF;

  -- ---- idempotency bound to (memo, target, amount) — Codex #3 ----
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'apply_credit_memo_to_invoice');
    IF v_existing IS NOT NULL THEN
      IF (v_existing->>'credit_memo_id')::uuid    IS DISTINCT FROM p_credit_memo_id
      OR (v_existing->>'target_invoice_id')::uuid IS DISTINCT FROM p_target_invoice_id
      OR (v_existing->>'amount_cents')::bigint     IS DISTINCT FROM p_amount_cents THEN
        RAISE EXCEPTION 'IDEMPOTENCY_ARGUMENT_MISMATCH: key % was already used for a different credit application', p_idempotency_key;
      END IF;
      RETURN (v_existing->>'application_id')::uuid;
    END IF;
  END IF;

  -- ---- lock BOTH invoices, ordered by id (deadlock-safe), then read current state ----
  IF p_credit_memo_id < p_target_invoice_id THEN
    v_first := p_credit_memo_id; v_second := p_target_invoice_id;
  ELSE
    v_first := p_target_invoice_id; v_second := p_credit_memo_id;
  END IF;
  PERFORM 1 FROM invoices WHERE id = v_first  FOR UPDATE;
  PERFORM 1 FROM invoices WHERE id = v_second FOR UPDATE;

  -- Codex BLOCKER (concurrent replay): re-check idempotency AFTER acquiring the locks. Two
  -- simultaneous calls with the same key both pass the pre-lock check (neither committed yet),
  -- serialize on the lock, and would each create a separate application — double-applying the
  -- credit. The winner commits its cached result; the loser now sees it and returns it.
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'apply_credit_memo_to_invoice');
    IF v_existing IS NOT NULL THEN
      RETURN (v_existing->>'application_id')::uuid;
    END IF;
  END IF;

  SELECT * INTO v_memo   FROM invoices WHERE id = p_credit_memo_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'CREDIT_MEMO_NOT_FOUND'; END IF;
  SELECT * INTO v_target FROM invoices WHERE id = p_target_invoice_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'TARGET_INVOICE_NOT_FOUND'; END IF;

  -- ---- eligibility (re-checked after locking) ----
  IF v_memo.deleted_at IS NOT NULL OR v_target.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'INVOICE_DELETED';
  END IF;
  IF v_memo.invoice_type <> 'credit_memo' THEN
    RAISE EXCEPTION 'NOT_A_CREDIT_MEMO: % is a %', v_memo.invoice_number, v_memo.invoice_type;
  END IF;
  IF v_memo.status <> 'posted' THEN
    RAISE EXCEPTION 'CREDIT_MEMO_NOT_POSTED: % is %', v_memo.invoice_number, v_memo.status;
  END IF;
  IF v_target.invoice_type = 'credit_memo' THEN
    RAISE EXCEPTION 'TARGET_IS_CREDIT_MEMO: cannot apply a credit to another credit memo';
  END IF;
  IF v_target.status NOT IN ('posted', 'overdue') THEN
    RAISE EXCEPTION 'TARGET_NOT_OPEN: % is % (must be posted or overdue)', v_target.invoice_number, v_target.status;
  END IF;
  IF v_memo.customer_id IS DISTINCT FROM v_target.customer_id THEN
    RAISE EXCEPTION 'CUSTOMER_MISMATCH: credit memo and target invoice belong to different customers';
  END IF;

  PERFORM check_period_open(CURRENT_DATE);

  -- ---- amount bounds ----
  v_remaining := -v_memo.balance_cents;  -- memo balance is <= 0; remaining credit is its magnitude
  IF p_amount_cents > v_remaining THEN
    RAISE EXCEPTION 'AMOUNT_EXCEEDS_CREDIT: $% requested but only $% credit remains on %',
      (p_amount_cents / 100.0)::numeric(12,2), (v_remaining / 100.0)::numeric(12,2), v_memo.invoice_number;
  END IF;
  IF p_amount_cents > v_target.balance_cents THEN
    RAISE EXCEPTION 'AMOUNT_EXCEEDS_BALANCE: $% requested but % only owes $%',
      (p_amount_cents / 100.0)::numeric(12,2), v_target.invoice_number, (v_target.balance_cents / 100.0)::numeric(12,2);
  END IF;

  -- ---- ledger row ----
  INSERT INTO credit_memo_applications (credit_memo_id, target_invoice_id, amount_cents, applied_by)
  VALUES (p_credit_memo_id, p_target_invoice_id, p_amount_cents, v_actor)
  RETURNING id INTO v_app_id;

  -- ---- consume the memo (its negative balance rises toward 0); status unchanged ----
  UPDATE invoices
     SET credit_applied_cents = credit_applied_cents + p_amount_cents,
         updated_at = now()
   WHERE id = p_credit_memo_id;

  -- ---- reduce the target; flip to paid when the (5-lever) balance hits 0 ----
  UPDATE invoices
     SET credit_applied_cents = credit_applied_cents + p_amount_cents,
         status = CASE
           WHEN (total_amount_cents - paid_amount_cents - prepay_applied_cents - write_off_cents
                 - (credit_applied_cents + p_amount_cents)) <= 0
           THEN 'paid' ELSE status END,
         updated_at = now()
   WHERE id = p_target_invoice_id;

  -- ---- audit: net-zero on the ledger (the memo already reduced AR when issued) — Codex #6.
  -- entity_type='credit_memo' (the closest allowed value; 'credit_memo_application' is not in
  -- the financial_audit_log entity_type CHECK). operation_type 'credit_memo_applied' is allowed.
  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_user_id, actor_role,
    new_values, total_impact_cents, description
  ) VALUES (
    'credit_memo_applied', 'credit_memo', v_app_id, v_actor, v_actor_role,
    jsonb_build_object(
      'application_id', v_app_id,
      'credit_memo_id', p_credit_memo_id, 'credit_memo_number', v_memo.invoice_number,
      'target_invoice_id', p_target_invoice_id, 'target_invoice_number', v_target.invoice_number,
      'amount_cents', p_amount_cents
    ),
    0,
    'Applied $' || (p_amount_cents / 100.0)::numeric(12,2) || ' credit ' || v_memo.invoice_number
      || ' to ' || v_target.invoice_number
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'apply_credit_memo_to_invoice',
      jsonb_build_object(
        'application_id', v_app_id,
        'credit_memo_id', p_credit_memo_id,
        'target_invoice_id', p_target_invoice_id,
        'amount_cents', p_amount_cents
      ));
  END IF;

  RETURN v_app_id;
END;
$_$;


ALTER FUNCTION "public"."apply_credit_memo_to_invoice"("p_credit_memo_id" "uuid", "p_target_invoice_id" "uuid", "p_amount_cents" bigint, "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_prepay_to_invoice"("p_prepay_credit_id" "uuid", "p_invoice_id" "uuid", "p_amount_cents" bigint, "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_credit    record;
  v_inv       record;
  v_app_id    uuid;
  v_actor     uuid;
  v_actor_role text;
  v_existing  jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  -- H1 fix: an inactive/absent profile yields NULL, and `NULL NOT IN (...)` is
  -- NOT TRUE, so the bare NOT IN would let a deactivated-but-authenticated user
  -- through. Guard the NULL explicitly.
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: only active admins and sales reps can apply prepayments';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'apply_prepay_to_invoice');
    IF v_existing IS NOT NULL THEN
      RETURN (v_existing->>'application_id')::uuid;
    END IF;
  END IF;

  SELECT * INTO v_credit FROM prepay_credits WHERE id = p_prepay_credit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Prepay credit not found'; END IF;

  SELECT * INTO v_inv FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;

  IF v_credit.customer_id IS DISTINCT FROM v_inv.customer_id THEN
    RAISE EXCEPTION 'CUSTOMER_MISMATCH: prepay credit % (customer %) cannot be applied to invoice % (customer %)',
      p_prepay_credit_id, v_credit.customer_id, p_invoice_id, v_inv.customer_id;
  END IF;

  IF v_inv.status NOT IN ('posted', 'overdue') THEN
    RAISE EXCEPTION 'Can only apply prepay to posted/overdue invoices (current status: %)', v_inv.status;
  END IF;

  PERFORM check_period_open(CURRENT_DATE);

  IF p_amount_cents <= 0 THEN RAISE EXCEPTION 'Application amount must be positive'; END IF;

  IF p_amount_cents > v_credit.balance_cents THEN
    RAISE EXCEPTION 'Amount exceeds prepay balance ($%)', (v_credit.balance_cents / 100.0)::numeric(12,2);
  END IF;

  IF p_amount_cents > v_inv.balance_cents THEN
    RAISE EXCEPTION 'Amount exceeds invoice balance ($%)', (v_inv.balance_cents / 100.0)::numeric(12,2);
  END IF;

  INSERT INTO prepay_applications (prepay_credit_id, invoice_id, applied_amount_cents)
  VALUES (p_prepay_credit_id, p_invoice_id, p_amount_cents)
  RETURNING id INTO v_app_id;

  UPDATE customers SET
    prepay_balance_cents = GREATEST(COALESCE(prepay_balance_cents, 0) - p_amount_cents, 0),
    updated_at = now()
  WHERE id = v_inv.customer_id;

  UPDATE invoices SET
    prepay_applied_cents = prepay_applied_cents + p_amount_cents,
    status = CASE
      -- CREDIT-APPLY: include credit_applied_cents in the →paid recompute
      WHEN (total_amount_cents - (paid_amount_cents + prepay_applied_cents + p_amount_cents) - write_off_cents - credit_applied_cents) <= 0
      THEN 'paid' ELSE status END,
    updated_at = now()
  WHERE id = p_invoice_id;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    new_values, total_impact_cents, description
  ) VALUES (
    'prepay_applied', 'prepay', v_app_id, v_actor_role,
    jsonb_build_object(
      'prepay_credit_id', p_prepay_credit_id,
      'invoice_id', p_invoice_id,
      'invoice_number', v_inv.invoice_number,
      'amount_cents', p_amount_cents,
      'remaining_credit', v_credit.balance_cents - p_amount_cents
    ),
    p_amount_cents,
    'Applied $' || (p_amount_cents / 100.0)::numeric(12,2) || ' prepay to ' || v_inv.invoice_number
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(
      p_idempotency_key,
      'apply_prepay_to_invoice',
      jsonb_build_object('application_id', v_app_id)
    );
  END IF;

  RETURN v_app_id;
END;
$_$;


ALTER FUNCTION "public"."apply_prepay_to_invoice"("p_prepay_credit_id" "uuid", "p_invoice_id" "uuid", "p_amount_cents" bigint, "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_prepay_to_invoice"("p_prepay_credit_id" "uuid", "p_invoice_id" "uuid", "p_amount_cents" bigint, "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Phase 1.D — hardened with strict actor pattern, role gate (admin/sales_rep), and optional idempotency. Returns uuid for backward-compat with batch_apply_prepayments. Closes audit Critical #4.';



CREATE OR REPLACE FUNCTION "public"."apply_product_pricing_change_set"("p_change_set_id" "uuid", "p_request_fingerprint" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_idem_request_fp text;
  v_change_set public.pricing_change_sets%ROWTYPE;
  v_export public.pricing_workbook_exports%ROWTYPE;
  v_row public.pricing_change_set_rows%ROWTYPE;
  v_product public.products%ROWTYPE;
  v_calc jsonb;
  v_output jsonb;
  v_output_fp text;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;
  IF p_request_fingerprint IS NULL OR btrim(p_request_fingerprint) = '' THEN
    RAISE EXCEPTION 'CHANGE_SET_FINGERPRINT_REQUIRED';
  END IF;

  v_idem_request_fp := md5(jsonb_build_object(
    'actor_id', v_actor,
    'change_set_id', p_change_set_id,
    'request_fingerprint', p_request_fingerprint
  )::text);
  v_existing := public.check_idempotency(p_idempotency_key, 'apply_product_pricing_change_set');
  IF v_existing IS NOT NULL THEN
    IF v_existing->>'actor_id' IS DISTINCT FROM v_actor::text
       OR v_existing->>'request_fingerprint' IS DISTINCT FROM v_idem_request_fp THEN
      RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH';
    END IF;
    RETURN v_existing->'response';
  END IF;

  -- The shared cache expires, but an apply key may never be rebound to a
  -- different durable change set. The unique partial index closes the
  -- concurrent race; this check provides a stable owner-facing error for the
  -- ordinary sequential retry/reuse case.
  IF EXISTS (
    SELECT 1
    FROM public.pricing_change_sets
    WHERE apply_idempotency_key = p_idempotency_key
      AND id IS DISTINCT FROM p_change_set_id
  ) THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REUSED_FOR_DIFFERENT_CHANGE_SET';
  END IF;

  SELECT * INTO v_change_set
  FROM public.pricing_change_sets
  WHERE id = p_change_set_id
  FOR UPDATE;
  IF NOT FOUND OR v_change_set.created_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'CHANGE_SET_NOT_FOUND';
  END IF;
  IF v_change_set.request_fingerprint IS DISTINCT FROM p_request_fingerprint THEN
    RAISE EXCEPTION 'CHANGE_SET_FINGERPRINT_MISMATCH';
  END IF;
  IF v_change_set.status = 'applied' THEN
    -- The shared idempotency cache is finite-lived. The applied change set is
    -- the durable receipt, so the exact original key remains retry-safe even
    -- after that cache row expires; every different key still fails closed.
    IF v_change_set.apply_idempotency_key IS NOT DISTINCT FROM p_idempotency_key THEN
      RETURN v_change_set.apply_result;
    END IF;
    RAISE EXCEPTION 'CHANGE_SET_ALREADY_APPLIED';
  END IF;
  IF v_change_set.status <> 'previewed' OR v_change_set.row_count <= 0
     OR v_change_set.expires_at <= now() THEN
    RAISE EXCEPTION 'CHANGE_SET_INVALID_OR_EXPIRED';
  END IF;

  -- Lock and validate the retained workbook export before any product lock.
  -- This prevents a second preview from applying after the same workbook was
  -- already consumed. An exact apply idempotency retry returned above.
  IF v_change_set.export_id IS NOT NULL THEN
    SELECT * INTO v_export
    FROM public.pricing_workbook_exports
    WHERE id = v_change_set.export_id
    FOR UPDATE;
    IF NOT FOUND OR v_export.created_by IS DISTINCT FROM v_actor
       OR v_export.status <> 'active' OR v_export.expires_at <= now() THEN
      RAISE EXCEPTION 'WORKBOOK_EXPORT_CONSUMED_OR_EXPIRED';
    END IF;
  END IF;

  -- Stable lock order prevents two overlapping batches from deadlocking. No
  -- product is changed until every row has been locked and version-validated.
  PERFORM p.id
  FROM public.products p
  JOIN public.pricing_change_set_rows r ON r.product_id = p.id
  WHERE r.change_set_id = p_change_set_id
  ORDER BY p.id
  FOR UPDATE OF p;

  IF v_change_set.row_count IS DISTINCT FROM (
    SELECT count(*) FROM public.pricing_change_set_rows r WHERE r.change_set_id = p_change_set_id
  ) OR EXISTS (
    SELECT 1
    FROM public.pricing_change_set_rows r
    LEFT JOIN public.products p ON p.id = r.product_id
    WHERE r.change_set_id = p_change_set_id
      AND (
        p.id IS NULL
        OR NOT p.is_active
        OR p.pricing_version IS DISTINCT FROM r.expected_version
        OR md5(jsonb_build_object(
          'product_id', p.id,
          'sku', COALESCE(p.sku, ''),
          'product_name', p.product_name,
          'category', COALESCE(p.category, ''),
          'container_size', COALESCE(p.container_size::text, ''),
          'unit_size', COALESCE(p.unit_size, ''),
          'inventory_unit', COALESCE(p.inventory_unit, '')
        )::text) IS DISTINCT FROM r.identity_fingerprint
      )
  ) THEN
    RAISE EXCEPTION 'PRICING_ROW_CONFLICT';
  END IF;

  FOR v_row IN
    SELECT * FROM public.pricing_change_set_rows
    WHERE change_set_id = p_change_set_id
    ORDER BY product_id
  LOOP
    SELECT * INTO v_product FROM public.products WHERE id = v_row.product_id;
    v_calc := public._calculate_product_pricing(
      v_row.pricing_mode,
      v_row.input_cost_cents::numeric / 100,
      v_row.input_tier1_margin, v_row.input_tier2_margin, v_row.input_tier3_margin,
      CASE WHEN v_row.input_tier1_price_cents IS NULL THEN NULL ELSE v_row.input_tier1_price_cents::numeric / 100 END,
      CASE WHEN v_row.input_tier2_price_cents IS NULL THEN NULL ELSE v_row.input_tier2_price_cents::numeric / 100 END,
      CASE WHEN v_row.input_tier3_price_cents IS NULL THEN NULL ELSE v_row.input_tier3_price_cents::numeric / 100 END
    );
    v_output := jsonb_build_object(
      'cost_cents', round((v_calc->>'current_cost')::numeric * 100)::bigint,
      'tier1_margin', (v_calc->>'tier1_margin')::numeric,
      'tier2_margin', (v_calc->>'tier2_margin')::numeric,
      'tier3_margin', (v_calc->>'tier3_margin')::numeric,
      'tier1_price_cents', round((v_calc->>'tier1_price')::numeric * 100)::bigint,
      'tier2_price_cents', round((v_calc->>'tier2_price')::numeric * 100)::bigint,
      'tier3_price_cents', round((v_calc->>'tier3_price')::numeric * 100)::bigint,
      'tier1_gross_margin', v_calc->'tier1_gross_margin',
      'tier2_gross_margin', v_calc->'tier2_gross_margin',
      'tier3_gross_margin', v_calc->'tier3_gross_margin',
      'tier1_price_per_acre_cents', CASE
        WHEN public.product_price_per_acre((v_calc->>'tier1_price')::numeric,
          v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) IS NULL
        THEN NULL ELSE round(public.product_price_per_acre((v_calc->>'tier1_price')::numeric,
          v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) * 100)::bigint END,
      'tier2_price_per_acre_cents', CASE
        WHEN public.product_price_per_acre(COALESCE(NULLIF((v_calc->>'tier2_price')::numeric, 0), (v_calc->>'tier1_price')::numeric),
          v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) IS NULL
        THEN NULL ELSE round(public.product_price_per_acre(COALESCE(NULLIF((v_calc->>'tier2_price')::numeric, 0), (v_calc->>'tier1_price')::numeric),
          v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) * 100)::bigint END,
      'tier3_price_per_acre_cents', CASE
        WHEN public.product_price_per_acre(COALESCE(NULLIF((v_calc->>'tier3_price')::numeric, 0), (v_calc->>'tier1_price')::numeric),
          v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) IS NULL
        THEN NULL ELSE round(public.product_price_per_acre(COALESCE(NULLIF((v_calc->>'tier3_price')::numeric, 0), (v_calc->>'tier1_price')::numeric),
          v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) * 100)::bigint END
    );
    v_output_fp := md5(v_output::text);
    IF v_output_fp IS DISTINCT FROM v_row.output_fingerprint THEN
      RAISE EXCEPTION 'CHANGE_SET_OUTPUT_DRIFT';
    END IF;
  END LOOP;

  FOR v_row IN
    SELECT * FROM public.pricing_change_set_rows
    WHERE change_set_id = p_change_set_id
    ORDER BY product_id
  LOOP
    PERFORM set_config('crx.pricing_authorized', 'phase1a', true);
    PERFORM set_config('crx.pricing_actor', v_actor::text, true);
    PERFORM set_config('crx.pricing_source', v_change_set.source, true);
    PERFORM set_config('crx.pricing_reason', COALESCE(v_row.change_reason, ''), true);
    PERFORM set_config('crx.pricing_change_set_id', p_change_set_id::text, true);
    PERFORM set_config('crx.pricing_mode', v_row.pricing_mode, true);

    UPDATE public.products
    SET current_cost = v_row.output_cost_cents::numeric / 100,
        tier1_margin = v_row.output_tier1_margin,
        tier2_margin = v_row.output_tier2_margin,
        tier3_margin = v_row.output_tier3_margin,
        tier1_price = v_row.output_tier1_price_cents::numeric / 100,
        tier2_price = v_row.output_tier2_price_cents::numeric / 100,
        tier3_price = v_row.output_tier3_price_cents::numeric / 100,
        cost_updated_date = CASE
          WHEN current_cost IS DISTINCT FROM v_row.output_cost_cents::numeric / 100 THEN now()
          ELSE cost_updated_date END,
        updated_at = now()
    WHERE id = v_row.product_id;
  END LOOP;

  SELECT jsonb_build_object(
    'change_set_id', p_change_set_id,
    'status', 'applied',
    'applied_count', v_change_set.row_count,
    'rows', jsonb_agg(jsonb_build_object(
      'product_id', p.id,
      'pricing_version', p.pricing_version,
      'cost', public._format_pricing_dollars(round(p.current_cost * 100)::bigint),
      'cost_cents', round(p.current_cost * 100)::bigint,
      'tier1_margin_percent', public._format_pricing_margin_percent(p.tier1_margin),
      'tier1_margin', p.tier1_margin,
      'tier1_price', public._format_pricing_dollars(round(p.tier1_price * 100)::bigint),
      'tier1_price_cents', round(p.tier1_price * 100)::bigint,
      'tier2_margin_percent', public._format_pricing_margin_percent(p.tier2_margin),
      'tier2_margin', p.tier2_margin,
      'tier2_price', public._format_pricing_dollars(round(p.tier2_price * 100)::bigint),
      'tier2_price_cents', round(p.tier2_price * 100)::bigint,
      'tier3_margin_percent', public._format_pricing_margin_percent(p.tier3_margin),
      'tier3_margin', p.tier3_margin,
      'tier3_price', public._format_pricing_dollars(round(p.tier3_price * 100)::bigint),
      'tier3_price_cents', round(p.tier3_price * 100)::bigint
    ) ORDER BY p.id)
  ) INTO v_result
  FROM public.products p
  JOIN public.pricing_change_set_rows r ON r.product_id = p.id
  WHERE r.change_set_id = p_change_set_id;

  UPDATE public.pricing_change_sets
  SET status = 'applied', applied_by = v_actor, applied_at = now(),
      apply_idempotency_key = p_idempotency_key, apply_result = v_result
  WHERE id = p_change_set_id;

  IF v_change_set.export_id IS NOT NULL THEN
    UPDATE public.pricing_workbook_exports
    SET status = 'consumed'
    WHERE id = v_change_set.export_id AND status = 'active';
  END IF;

  PERFORM public.save_idempotency(
    p_idempotency_key,
    'apply_product_pricing_change_set',
    jsonb_build_object('actor_id', v_actor, 'request_fingerprint', v_idem_request_fp, 'response', v_result)
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."apply_product_pricing_change_set"("p_change_set_id" "uuid", "p_request_fingerprint" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_remaining_prepayments"("p_customer_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor         uuid;
  v_available     bigint;
  v_invoice       record;
  v_apply         bigint;
  v_applied_total bigint := 0;
  v_count         integer := 0;
  v_cached        jsonb;
  v_result        jsonb;
BEGIN
  -- OVERNIGHT BUG HUNT GUARD (HIGH: prepay double-spend, no-ledger).
  -- Hard-block bulk prepay apply until the reserved-pool redesign lands.
  -- Remove this RAISE block to restore the (still-defective) behavior.
  RAISE EXCEPTION 'PREPAY_BULK_APPLY_DISABLED'
    USING DETAIL = 'Bulk prepay application is temporarily disabled pending the prepay reserved-pool redesign. Apply prepayments one invoice at a time (apply_prepay_to_invoice).',
          ERRCODE = 'P0001';

  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'admin') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached := check_idempotency(p_idempotency_key, 'apply_remaining_prepayments');
    IF v_cached IS NOT NULL THEN
      RETURN v_cached;
    END IF;
  END IF;

  SELECT COALESCE(c.prepay_balance_cents, 0)
    INTO v_available
    FROM customers c
   WHERE c.id = p_customer_id
   FOR UPDATE;

  IF v_available IS NULL OR v_available <= 0 THEN
    v_result := jsonb_build_object(
      'applied_count', 0,
      'applied_cents', 0,
      'remaining_prepay_cents', 0,
      'message', 'No prepay balance available'
    );
    IF p_idempotency_key IS NOT NULL THEN
      PERFORM save_idempotency(p_idempotency_key, 'apply_remaining_prepayments', v_result);
    END IF;
    RETURN v_result;
  END IF;

  FOR v_invoice IN
    SELECT id, invoice_number, invoice_date, balance_cents
      FROM invoices
     WHERE customer_id = p_customer_id
       AND status = 'posted'
       AND balance_cents > 0
       AND deleted_at IS NULL
     ORDER BY invoice_date ASC, created_at ASC
     FOR UPDATE
  LOOP
    EXIT WHEN v_available <= 0;

    PERFORM check_period_open(v_invoice.invoice_date);

    v_apply := LEAST(v_available, v_invoice.balance_cents);

    UPDATE invoices
       SET prepay_applied_cents = COALESCE(prepay_applied_cents, 0) + v_apply,
           updated_at = now()
     WHERE id = v_invoice.id;

    v_available     := v_available - v_apply;
    v_applied_total := v_applied_total + v_apply;
    v_count         := v_count + 1;
  END LOOP;

  UPDATE customers
     SET prepay_balance_cents = GREATEST(0, COALESCE(prepay_balance_cents, 0) - v_applied_total),
         updated_at = now()
   WHERE id = p_customer_id;

  IF v_applied_total > 0 THEN
    INSERT INTO financial_audit_log (
      operation_type, entity_type, entity_id,
      actor_user_id, total_impact_cents, description
    ) VALUES (
      'prepay_batch_applied', 'prepay', p_customer_id,
      v_actor, v_applied_total,
      'Batch applied $' || (v_applied_total / 100.0)::numeric(12,2) ||
      ' prepay across ' || v_count || ' invoice(s) for customer ' ||
      (SELECT farm_name FROM customers WHERE id = p_customer_id)
    );
  END IF;

  v_result := jsonb_build_object(
    'applied_count', v_count,
    'applied_cents', v_applied_total,
    'remaining_prepay_cents', v_available
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'apply_remaining_prepayments', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."apply_remaining_prepayments"("p_customer_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_remaining_prepayments"("p_customer_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Applies a customer''s available prepay balance to oldest-unpaid posted invoices, enforcing check_period_open per-invoice (Wave A.4 / P3-4). Invoice in a closed period raises and rolls back the entire batch.';



CREATE OR REPLACE FUNCTION "public"."apply_write_off"("p_invoice_id" "uuid", "p_amount_cents" bigint, "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid;
  v_invoice record;
  v_wo_id uuid;
  v_cached_result jsonb;
  v_new_write_off bigint;
  v_new_balance bigint;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT is_admin() THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached_result := public.check_idempotency(p_idempotency_key, 'apply_write_off');
    IF v_cached_result IS NOT NULL THEN
      RETURN (v_cached_result->>'id')::uuid;
    END IF;
  END IF;

  SELECT id, customer_id, balance_cents, status, write_off_cents,
         invoice_number, invoice_date, total_amount_cents,
         paid_amount_cents, prepay_applied_cents,
         credit_applied_cents  -- CREDIT-APPLY: needed for the settled recompute
    INTO v_invoice
    FROM public.invoices
   WHERE id = p_invoice_id
   FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'INVOICE_NOT_FOUND'; END IF;
  IF v_invoice.status NOT IN ('posted', 'overdue') THEN
    RAISE EXCEPTION 'INVALID_INVOICE_STATUS: %', v_invoice.status;
  END IF;
  PERFORM public.check_period_open(CURRENT_DATE);
  IF p_amount_cents <= 0 THEN RAISE EXCEPTION 'INVALID_AMOUNT'; END IF;
  IF p_amount_cents > v_invoice.balance_cents THEN RAISE EXCEPTION 'AMOUNT_EXCEEDS_BALANCE'; END IF;

  INSERT INTO public.write_offs (invoice_id, customer_id, amount_cents, reason, approved_by, created_by)
  VALUES (p_invoice_id, v_invoice.customer_id, p_amount_cents, p_reason, v_actor, v_actor)
  RETURNING id INTO v_wo_id;

  v_new_write_off := COALESCE(v_invoice.write_off_cents, 0) + p_amount_cents;
  v_new_balance := v_invoice.total_amount_cents
                 - v_invoice.paid_amount_cents
                 - v_invoice.prepay_applied_cents
                 - v_new_write_off
                 - v_invoice.credit_applied_cents;  -- CREDIT-APPLY

  UPDATE public.invoices
     SET write_off_cents = v_new_write_off,
         status = CASE WHEN v_new_balance <= 0 THEN 'paid' ELSE status END,
         updated_at = now()
   WHERE id = p_invoice_id;

  INSERT INTO public.financial_audit_log (
    operation_type,
    entity_type,
    entity_id,
    actor_user_id, total_impact_cents, description
  ) VALUES (
    'write_off_applied', 'write_off', v_wo_id,
    v_actor, -p_amount_cents,
    'Write-off of $' || (p_amount_cents / 100.0)::numeric(12,2) ||
    ' on invoice ' || v_invoice.invoice_number || ': ' || p_reason ||
    CASE WHEN v_new_balance <= 0 THEN ' (fully settled - status set to paid)' ELSE '' END
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(
      p_idempotency_key,
      'apply_write_off',
      jsonb_build_object('id', v_wo_id)
    );
  END IF;

  RETURN v_wo_id;
END;
$_$;


ALTER FUNCTION "public"."apply_write_off"("p_invoice_id" "uuid", "p_amount_cents" bigint, "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_return"("p_return_id" "uuid", "p_approved_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_return record;
  v_cached jsonb;
  v_result jsonb;
  v_actor uuid;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_approved_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached := public.check_idempotency(p_idempotency_key, 'approve_return');
    IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
  END IF;

  SELECT id, return_number, status, customer_id INTO v_return
  FROM public.returns WHERE id = p_return_id FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Return not found: %', p_return_id; END IF;
  IF v_return.status != 'requested' THEN
    RAISE EXCEPTION 'Only requested returns can be approved (current status: %)', v_return.status;
  END IF;

  PERFORM set_config('app.return_rpc', 'true', true);
  UPDATE public.returns
     SET status = 'approved',
         approved_by = v_actor,
         approved_at = now(),
         updated_at = now()
   WHERE id = p_return_id;

  INSERT INTO public.activity_feed (
    event_type, description, performed_by, related_entity_type, related_entity_id, customer_id
  )
  VALUES (
    'return_approved',
    'Return ' || v_return.return_number || ' approved',
    v_actor,
    'return',
    p_return_id,
    v_return.customer_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'return_id', p_return_id,
    'return_number', v_return.return_number,
    'status', 'approved'
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(p_idempotency_key, 'approve_return', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."approve_return"("p_return_id" "uuid", "p_approved_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_supplier_price_import"("p_import_id" "uuid", "p_row_ids" "uuid"[], "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_request_fp text;
  v_import public.supplier_price_imports%ROWTYPE;
  v_row public.supplier_price_import_rows%ROWTYPE;
  v_observation_id uuid;
  v_approved_count integer := 0;
  v_eligible_count integer;
  v_nonterminal_count integer;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;
  IF p_row_ids IS NULL OR cardinality(p_row_ids) = 0 THEN
    RAISE EXCEPTION 'SUPPLIER_APPROVAL_ROWS_REQUIRED';
  END IF;
  IF cardinality(p_row_ids) <> (
    SELECT count(DISTINCT row_id)
    FROM unnest(p_row_ids) AS selected(row_id)
  ) THEN
    RAISE EXCEPTION 'SUPPLIER_APPROVAL_DUPLICATE_ROW_IDS';
  END IF;

  v_request_fp := md5(jsonb_build_object(
    'actor_id', v_actor,
    'import_id', p_import_id,
    'row_ids', to_jsonb(p_row_ids)
  )::text);
  v_existing := public.check_idempotency(p_idempotency_key, 'approve_supplier_price_import');
  IF v_existing IS NOT NULL THEN
    IF v_existing->>'actor_id' IS DISTINCT FROM v_actor::text
       OR v_existing->>'request_fingerprint' IS DISTINCT FROM v_request_fp THEN
      RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH';
    END IF;
    RETURN v_existing->'response';
  END IF;

  SELECT * INTO v_import
  FROM public.supplier_price_imports
  WHERE id = p_import_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'SUPPLIER_IMPORT_NOT_FOUND'; END IF;
  IF v_import.status <> 'needs_review' THEN
    RAISE EXCEPTION 'SUPPLIER_IMPORT_NOT_REVIEWABLE';
  END IF;

  SELECT count(*)::integer INTO v_eligible_count
  FROM public.supplier_price_import_rows
  WHERE import_id = p_import_id
    AND id = ANY(p_row_ids)
    AND row_status IN ('new', 'changed', 'cannot_compare');
  IF v_eligible_count <> cardinality(p_row_ids) THEN
    RAISE EXCEPTION 'SUPPLIER_APPROVAL_ROW_NOT_ELIGIBLE';
  END IF;

  FOR v_row IN
    SELECT *
    FROM public.supplier_price_import_rows
    WHERE import_id = p_import_id
      AND id = ANY(p_row_ids)
      AND row_status IN ('new', 'changed', 'cannot_compare')
    ORDER BY row_number
    FOR UPDATE
  LOOP
    INSERT INTO public.supplier_price_observations(
      product_id, vendor_id, product_supplier_link_id,
      import_id, import_row_id,
      price_kind, cost_cents, price_unit, package_quantity,
      effective_from, effective_to, observed_at, created_by
    ) VALUES (
      v_row.product_id, v_row.vendor_id, v_row.product_supplier_link_id,
      p_import_id, v_row.id,
      v_row.price_kind, v_row.cost_cents, v_row.price_unit, v_row.package_quantity,
      v_row.effective_from, v_row.effective_to, now(), v_actor
    ) RETURNING id INTO v_observation_id;

    UPDATE public.supplier_price_import_rows
    SET row_status = 'approved',
        reviewed_by = v_actor,
        reviewed_at = now(),
        observation_id = v_observation_id
    WHERE id = v_row.id;
    v_approved_count := v_approved_count + 1;
  END LOOP;

  UPDATE public.supplier_price_import_rows
  SET row_status = 'rejected',
      reviewed_by = v_actor,
      reviewed_at = now(),
      reviewer_note = COALESCE(reviewer_note, 'Not selected during import approval')
  WHERE import_id = p_import_id
    AND row_status IN ('new', 'changed', 'cannot_compare')
    AND NOT (id = ANY(p_row_ids));

  SELECT count(*)::integer INTO v_nonterminal_count
  FROM public.supplier_price_import_rows
  WHERE import_id = p_import_id
    AND row_status IN ('invalid', 'rejected');

  UPDATE public.supplier_price_imports
  SET status = CASE WHEN v_nonterminal_count = 0 THEN 'approved' ELSE 'partially_approved' END,
      approved_by = v_actor,
      approved_at = now(),
      approved_observation_count = v_approved_count
  WHERE id = p_import_id;

  v_result := public.get_supplier_price_import(p_import_id)
    || jsonb_build_object(
      'approved_count', v_approved_count,
      'sell_prices_changed', 0,
      'summary', format(
        'You are adding %s supplier observations. You are changing ZERO sell prices.',
        v_approved_count
      )
    );
  PERFORM public.save_idempotency(
    p_idempotency_key,
    'approve_supplier_price_import',
    jsonb_build_object(
      'actor_id', v_actor,
      'request_fingerprint', v_request_fp,
      'response', v_result
    )
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."approve_supplier_price_import"("p_import_id" "uuid", "p_row_ids" "uuid"[], "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_job_applicator"("p_job_id" "uuid", "p_applicator_id" "uuid" DEFAULT NULL::"uuid", "p_license_override" boolean DEFAULT false, "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_role text;
  v_existing jsonb;
  v_job jobs%ROWTYPE;
  v_applicator_name text;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales_rep required';
  END IF;
  IF p_license_override AND v_role <> 'admin' THEN
    RAISE EXCEPTION 'OVERRIDE_REQUIRES_ADMIN';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'assign_job_applicator');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_job FROM jobs WHERE id = p_job_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'JOB_NOT_FOUND'; END IF;

  IF p_license_override THEN
    PERFORM set_config('app.admin_override', 'true', true);
  END IF;

  UPDATE jobs SET applicator_id = p_applicator_id WHERE id = p_job_id;

  IF p_license_override THEN
    PERFORM set_config('app.admin_override', 'false', true);
  END IF;

  IF p_applicator_id IS NOT NULL THEN
    SELECT full_name INTO v_applicator_name FROM profiles WHERE id = p_applicator_id;
  END IF;

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES (
    'job_assigned',
    CASE WHEN p_applicator_id IS NULL THEN 'Job unassigned'
         ELSE 'Job assigned to ' || coalesce(v_applicator_name, 'unknown')
              || CASE WHEN p_license_override THEN ' (license override by admin)' ELSE '' END
    END,
    v_actor,
    'job',
    p_job_id,
    v_job.customer_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'job_id', p_job_id,
    'applicator_id', p_applicator_id,
    'license_override', p_license_override
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'assign_job_applicator', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."assign_job_applicator"("p_job_id" "uuid", "p_applicator_id" "uuid", "p_license_override" boolean, "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_expire_quotes"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_quote record;
  v_expired_count integer := 0;
  v_holds_released integer := 0;
  v_hold_count integer;
  v_actor uuid;
BEGIN
  FOR v_quote IN
    SELECT q.* FROM public.quotes q
    WHERE q.expires_at < CURRENT_DATE
      AND q.status IN ('sent', 'revised')
      AND q.deleted_at IS NULL
      -- A5 (2026-06-10): a quote with partial draw-downs is an open season
      -- booking — being past its quote-expiry date is normal business, not an
      -- expired quote. Never auto-expire it (the undrawn balance would be
      -- destroyed: 'expired' is terminal and releases the booking's holds).
      AND NOT EXISTS (
        SELECT 1 FROM public.quote_product_draws d
        WHERE d.quote_id = q.id AND d.quantity_drawn > 0
      )
      -- #5 (2026-06-13, owner gate G-AE = Option 1): Planned Programs are
      -- deliberate season commitments that reserve inventory on purpose — never
      -- silently auto-expire them (that would release the booking's holds out
      -- from under the forecast). Staff close planned quotes by hand if needed.
      AND q.is_planned = false
    FOR UPDATE SKIP LOCKED
  LOOP
    -- M1 (2026-06-10): release holds BEFORE the status flip so the AFTER
    -- UPDATE trigger finds 0 active holds and its FK-fragile log insert does
    -- not run. End state identical.
    UPDATE public.inventory_holds SET is_active = false, updated_at = now()
      WHERE source_id = v_quote.id AND is_active = true;
    GET DIAGNOSTICS v_hold_count = ROW_COUNT;
    v_holds_released := v_holds_released + v_hold_count;

    UPDATE public.quotes SET status = 'expired', updated_at = now() WHERE id = v_quote.id;
    v_expired_count := v_expired_count + 1;

    INSERT INTO public.notifications (
      user_id, title, message, notification_type, related_entity_type, related_entity_id
    )
    SELECT
      v_quote.created_by,
      'Quote expired',
      'Quote ' || v_quote.quote_number || ' expired',
      'quote_expired',
      'quote',
      v_quote.id
    FROM public.profiles p
    WHERE v_quote.created_by IS NOT NULL
      AND p.id = v_quote.created_by
      AND p.is_active = true;
  END LOOP;

  IF v_expired_count > 0 THEN
    v_actor := (
      SELECT id
      FROM public.profiles
      WHERE role = 'admin' AND is_active = true
      ORDER BY created_at
      LIMIT 1
    );

    -- Best-effort summary row using a real active admin actor when one exists;
    -- logging must never cancel the expiry work it summarizes.
    IF v_actor IS NOT NULL THEN
      BEGIN
        INSERT INTO public.activity_feed (event_type, description, performed_by)
        VALUES (
          'quotes_auto_expired',
          'Auto-expired ' || v_expired_count || ' quotes, deactivated ' || v_holds_released || ' inventory hold(s)',
          v_actor
        );
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;
  END IF;

  RETURN jsonb_build_object('expired_count', v_expired_count, 'holds_released', v_holds_released);
END;
$$;


ALTER FUNCTION "public"."auto_expire_quotes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."batch_apply_all_prepayments"("p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_cust       record;
  v_result     jsonb;
  v_details    jsonb := '[]'::jsonb;
  v_total_customers integer := 0;
  v_total_applied   bigint  := 0;
  v_actor      uuid;
  v_existing   jsonb;
  v_final      jsonb;
BEGIN
  -- OVERNIGHT BUG HUNT GUARD (HIGH: prepay double-spend, no-ledger).
  -- Hard-block bulk prepay apply until the reserved-pool redesign lands.
  -- Remove this RAISE block to restore the (still-defective) behavior.
  RAISE EXCEPTION 'PREPAY_BULK_APPLY_DISABLED'
    USING DETAIL = 'Bulk prepay application is temporarily disabled pending the prepay reserved-pool redesign. Apply prepayments one invoice at a time (apply_prepay_to_invoice).',
          ERRCODE = 'P0001';

  PERFORM require_admin_or_sales_rep();
  PERFORM check_rate_limit(auth.uid(), 'batch_apply_all_prepayments', 5, 60);
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'batch_apply_all_prepayments');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  FOR v_cust IN
    SELECT c.id, c.farm_name, c.prepay_balance_cents
    FROM customers c
    WHERE c.prepay_balance_cents > 0
      AND c.is_active = true
      AND EXISTS (
        SELECT 1 FROM invoices i
        WHERE i.customer_id = c.id
          AND i.status = 'posted'
          AND i.balance_cents > 0
          AND i.deleted_at IS NULL
      )
    ORDER BY c.farm_name
    FOR UPDATE OF c
  LOOP
    v_result := apply_remaining_prepayments(v_cust.id, v_actor);

    IF (v_result->>'applied_cents')::bigint > 0 THEN
      v_total_customers := v_total_customers + 1;
      v_total_applied := v_total_applied + (v_result->>'applied_cents')::bigint;
      v_details := v_details || jsonb_build_object(
        'customer_id', v_cust.id,
        'farm_name', v_cust.farm_name,
        'applied_count', (v_result->>'applied_count')::integer,
        'applied_cents', (v_result->>'applied_cents')::bigint,
        'remaining_prepay_cents', (v_result->>'remaining_prepay_cents')::bigint
      );
    END IF;
  END LOOP;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    old_values, new_values, total_impact_cents, description
  ) VALUES (
    'batch_prepay_apply', 'batch', v_actor,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object('total_customers_checked', (
      SELECT count(*) FROM customers WHERE prepay_balance_cents > 0 AND is_active = true
    )),
    jsonb_build_object('total_customers_applied', v_total_customers, 'total_applied_cents', v_total_applied),
    v_total_applied,
    'Batch applied prepayments: ' || v_total_customers || ' customer(s), ' ||
      '$' || ROUND(v_total_applied / 100.0, 2) || ' total'
  );

  v_final := jsonb_build_object(
    'total_customers', v_total_customers,
    'total_applied_cents', v_total_applied,
    'details', v_details
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'batch_apply_all_prepayments', v_final);
  END IF;

  RETURN v_final;
END;
$_$;


ALTER FUNCTION "public"."batch_apply_all_prepayments"("p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."batch_apply_prepayments"("p_allocations" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_alloc            jsonb;
  v_invoice_id       uuid;
  v_invoice_date     date;
  v_result_id        uuid;
  v_result_ids       uuid[] := ARRAY[]::uuid[];
  v_total_applied    bigint := 0;
  v_count            integer := 0;
  v_cached_result    jsonb;
  v_result           jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required'
      USING ERRCODE = '42501';
  END IF;

  -- Idempotency replay
  IF p_idempotency_key IS NOT NULL THEN
    v_cached_result := check_idempotency(p_idempotency_key, 'batch_apply_prepayments');
    IF v_cached_result IS NOT NULL THEN
      RETURN v_cached_result;
    END IF;
  END IF;

  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations)
  LOOP
    v_invoice_id := (v_alloc->>'invoice_id')::uuid;

    -- P3-4 FIX: look up the invoice's date and enforce period-close on it.
    -- This runs BEFORE the inner apply_prepay_to_invoice call, which itself
    -- only checks CURRENT_DATE.
    SELECT invoice_date INTO v_invoice_date
      FROM invoices
     WHERE id = v_invoice_id;
    IF v_invoice_date IS NULL THEN
      RAISE EXCEPTION 'Invoice not found for prepay allocation: %', v_invoice_id;
    END IF;
    PERFORM check_period_open(v_invoice_date);

    v_result_id := apply_prepay_to_invoice(
      (v_alloc->>'prepay_credit_id')::uuid,
      v_invoice_id,
      (v_alloc->>'amount_cents')::bigint
    );
    v_result_ids := array_append(v_result_ids, v_result_id);
    v_total_applied := v_total_applied + (v_alloc->>'amount_cents')::bigint;
    v_count := v_count + 1;
  END LOOP;

  v_result := jsonb_build_object(
    'success', true,
    'applied_count', v_count,
    'total_applied_cents', v_total_applied,
    'application_ids', to_jsonb(v_result_ids)
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'batch_apply_prepayments', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."batch_apply_prepayments"("p_allocations" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."batch_apply_prepayments"("p_allocations" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Admin-only atomic batch application of prepay credits to invoices. Enforces check_period_open per-invoice before mutating. Any invoice in a closed period raises and rolls back the entire batch.';



CREATE OR REPLACE FUNCTION "public"."batch_approve_blend_tickets"("p_ticket_ids" "uuid"[], "p_approved_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_count integer := 0;
  v_existing text;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_approved_by IS NOT NULL AND p_approved_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'batch_approve_blend_tickets';
    IF v_existing IS NOT NULL THEN RETURN v_existing::jsonb; END IF;
  END IF;

  UPDATE blend_tickets
  SET review_status = 'approved',
      reviewed_by = v_actor,
      reviewed_at = now()
  WHERE id = ANY(p_ticket_ids)
    AND status = 'completed'
    AND review_status = 'unreviewed'
    AND deleted_at IS NULL;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'batch_approve_blend_tickets', jsonb_build_object('approved_count', v_count));
  END IF;

  RETURN jsonb_build_object('approved_count', v_count);
END;
$$;


ALTER FUNCTION "public"."batch_approve_blend_tickets"("p_ticket_ids" "uuid"[], "p_approved_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."batch_cancel_deliveries"("p_delivery_ids" "uuid"[], "p_cancel_reason" "text" DEFAULT 'Batch cancelled'::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_del record;
  v_count integer := 0;
  v_actor uuid;
  v_result jsonb;
  v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  PERFORM check_rate_limit(v_actor, 'batch_cancel_deliveries', 3, 60);
  IF array_length(p_delivery_ids, 1) IS NULL THEN RAISE EXCEPTION 'No delivery IDs provided'; END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'batch_cancel_deliveries');
    IF v_existing IS NOT NULL THEN RETURN (v_existing->>'count')::integer; END IF;
  END IF;

  FOR v_del IN SELECT id, status FROM deliveries WHERE id = ANY(p_delivery_ids) ORDER BY id
  LOOP
    IF v_del.status NOT IN ('scheduled', 'in_progress', 'completed') THEN CONTINUE; END IF;
    v_result := cancel_delivery(p_delivery_id := v_del.id, p_cancel_reason := p_cancel_reason, p_performed_by := v_actor);
    IF (v_result->>'success')::boolean THEN v_count := v_count + 1; END IF;
  END LOOP;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'batch_cancel_deliveries', jsonb_build_object('count', v_count));
  END IF;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."batch_cancel_deliveries"("p_delivery_ids" "uuid"[], "p_cancel_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."batch_post_invoices"("p_invoice_ids" "uuid"[], "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_id uuid;
  v_count int := 0;
  v_total bigint := 0;
  v_actor uuid;
  v_actor_role text;
  v_existing jsonb;
  v_failures jsonb := '[]'::jsonb;
  v_first_posted uuid;
  v_posted_ids uuid[] := '{}';  -- P1: only invoices that actually posted
  v_err text;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  -- M4: admin+sales (was admin-only). Mirrors post_invoice's gate exactly.
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Not authorized to batch post invoices';
  END IF;
  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'batch_post_invoices';
    -- M4: return the actual cached result (was: an empty {count:0,idempotent:true} stub).
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF array_length(p_invoice_ids, 1) IS NULL THEN RAISE EXCEPTION 'No invoice IDs provided'; END IF;

  -- M4: partial-tolerant (was all-or-nothing). Each post_invoice runs in its own
  -- subtransaction; a failure rolls back only that invoice and is recorded in
  -- v_failures instead of aborting the batch.
  FOREACH v_id IN ARRAY p_invoice_ids LOOP
    BEGIN
      PERFORM post_invoice(v_id);
      v_count := v_count + 1;
      IF v_first_posted IS NULL THEN v_first_posted := v_id; END IF;
      v_posted_ids := array_append(v_posted_ids, v_id);  -- P1: track the actual posts
      v_total := v_total + COALESCE((SELECT total_amount_cents FROM invoices WHERE id = v_id), 0);
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
      v_failures := v_failures || jsonb_build_object('invoice_id', v_id, 'error', v_err);
    END;
  END LOOP;

  -- Append-only provenance: only when something actually posted. entity_id points at a
  -- REAL posted invoice (v_first_posted), never a row that failed.
  IF v_count > 0 THEN
    INSERT INTO financial_audit_log (
      operation_type, entity_type, entity_id, actor_role,
      new_values, total_impact_cents, description
    ) VALUES (
      'invoice_posted', 'invoice', v_first_posted, v_actor_role,
      jsonb_build_object(
        'batch_count', v_count,
        'failed_count', jsonb_array_length(v_failures),
        'invoice_ids', to_jsonb(v_posted_ids)  -- P1: only the posted IDs, not the full request
      ),
      v_total,
      'Batch posted ' || v_count || ' invoice(s) totaling $' || (v_total / 100.0)::numeric(12,2) ||
        CASE WHEN jsonb_array_length(v_failures) > 0
             THEN ' (' || jsonb_array_length(v_failures) || ' failed)' ELSE '' END
    );
  END IF;

  v_result := jsonb_build_object(
    'success', (jsonb_array_length(v_failures) = 0),
    'count', v_count,
    'total_cents', v_total,
    'failed', v_failures
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'batch_post_invoices', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."batch_post_invoices"("p_invoice_ids" "uuid"[], "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."batch_reject_blend_tickets"("p_ticket_ids" "uuid"[], "p_rejected_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_count integer := 0;
  v_existing text;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_rejected_by IS NOT NULL AND p_rejected_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'batch_reject_blend_tickets';
    IF v_existing IS NOT NULL THEN RETURN v_existing::jsonb; END IF;
  END IF;

  UPDATE blend_tickets
  SET review_status = 'rejected',
      reviewed_by = v_actor,
      reviewed_at = now()
  WHERE id = ANY(p_ticket_ids)
    AND status = 'completed'
    AND review_status = 'unreviewed'
    AND deleted_at IS NULL;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'batch_reject_blend_tickets', jsonb_build_object('rejected_count', v_count));
  END IF;

  RETURN jsonb_build_object('rejected_count', v_count);
END;
$$;


ALTER FUNCTION "public"."batch_reject_blend_tickets"("p_ticket_ids" "uuid"[], "p_rejected_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."batch_reschedule_deliveries"("p_delivery_ids" "uuid"[], "p_new_date" "date", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_count    int := 0;
  v_id       uuid;
  v_delivery record;
  v_result   jsonb;
  v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Not authorized to reschedule deliveries';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'batch_reschedule_deliveries');
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  IF p_new_date < CURRENT_DATE THEN
    RAISE EXCEPTION 'Cannot reschedule deliveries to a past date';
  END IF;

  FOREACH v_id IN ARRAY p_delivery_ids LOOP
    SELECT * INTO v_delivery FROM deliveries WHERE id = v_id FOR UPDATE;
    IF NOT FOUND THEN CONTINUE; END IF;
    IF v_delivery.status NOT IN ('scheduled', 'in_progress') THEN CONTINUE; END IF;

    UPDATE deliveries SET
      scheduled_date = p_new_date,
      last_edited_by = v_actor,
      last_edited_at = now(),
      updated_at = now()
    WHERE id = v_id;

    v_count := v_count + 1;
  END LOOP;

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id
  ) VALUES (
    'deliveries_rescheduled',
    v_count || ' delivery(ies) rescheduled to ' || p_new_date::text,
    v_actor, 'delivery', p_delivery_ids[1]
  );

  v_result := jsonb_build_object('status', 'rescheduled', 'count', v_count);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'batch_reschedule_deliveries', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."batch_reschedule_deliveries"("p_delivery_ids" "uuid"[], "p_new_date" "date", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."batch_void_invoices"("p_invoice_ids" "uuid"[], "p_void_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_inv       record;
  v_count     integer := 0;
  v_actor     uuid;
  v_actor_role text;
  v_existing  jsonb;
BEGIN
  PERFORM require_admin_or_sales_rep();
  PERFORM check_rate_limit(auth.uid(), 'batch_void_invoices', 5, 60);
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'batch_void_invoices');
    IF v_existing IS NOT NULL THEN RETURN (v_existing->>'voided_count')::integer; END IF;
  END IF;

  IF array_length(p_invoice_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'No invoice IDs provided';
  END IF;

  FOR v_inv IN
    SELECT id, status FROM invoices
    WHERE id = ANY(p_invoice_ids) AND deleted_at IS NULL
    ORDER BY id FOR UPDATE
  LOOP
    IF v_inv.status <> 'posted' THEN CONTINUE; END IF;

    PERFORM void_invoice(v_inv.id, p_void_reason);

    v_count := v_count + 1;
  END LOOP;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    old_values, new_values, total_impact_cents, description
  ) VALUES (
    'batch_void', 'invoice', p_invoice_ids[1], v_actor_role,
    jsonb_build_object('invoice_count', array_length(p_invoice_ids, 1)),
    jsonb_build_object('voided_count', v_count, 'void_reason', p_void_reason),
    0, 'Batch voided ' || v_count || ' invoice(s) — ' || p_void_reason
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'batch_void_invoices', jsonb_build_object('voided_count', v_count));
  END IF;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."batch_void_invoices"("p_invoice_ids" "uuid"[], "p_void_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_create_label_drafts"("p_drafts" "jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_cached   jsonb;
  v_item     jsonb;
  v_ids      uuid[] := '{}';
  v_draft_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_user_id AND role = 'admin' AND is_active = true
  ) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: admin role required';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_cached
    FROM idempotency_keys
    WHERE idempotency_key = p_idempotency_key
      AND operation       = 'bulk_create_label_drafts';
    IF FOUND THEN RETURN v_cached; END IF;
  END IF;

  FOR v_item IN SELECT jsonb_array_elements(p_drafts)
  LOOP
    -- Non-negativity guard: reject impossible regulatory values per element.
    IF (v_item->>'rei_hours') IS NOT NULL AND (v_item->>'rei_hours')::integer < 0 THEN
      RAISE EXCEPTION 'INVALID_LABEL_VALUE: rei_hours must be >= 0 (got %)', v_item->>'rei_hours';
    END IF;
    IF (v_item->>'phi_days') IS NOT NULL AND (v_item->>'phi_days')::integer < 0 THEN
      RAISE EXCEPTION 'INVALID_LABEL_VALUE: phi_days must be >= 0 (got %)', v_item->>'phi_days';
    END IF;
    IF (v_item->>'max_label_rate') IS NOT NULL AND (v_item->>'max_label_rate')::numeric < 0 THEN
      RAISE EXCEPTION 'INVALID_LABEL_VALUE: max_label_rate must be >= 0 (got %)', v_item->>'max_label_rate';
    END IF;

    INSERT INTO product_label_drafts (
      product_id, signal_word, rei_hours, phi_days, epa_registration,
      max_label_rate, max_label_rate_unit,
      source_note, confidence, status, created_by, run_idempotency_key
    ) VALUES (
      (v_item->>'product_id')::uuid,
      v_item->>'signal_word',
      (v_item->>'rei_hours')::integer,
      (v_item->>'phi_days')::integer,
      v_item->>'epa_registration',
      (v_item->>'max_label_rate')::numeric,
      v_item->>'max_label_rate_unit',
      COALESCE(v_item->>'source_note', ''),
      COALESCE(v_item->>'confidence', 'low'),
      -- clamp to a reviewable status: a bulk-created row never enters the queue already-decided
      CASE WHEN v_item->>'status' IN ('pending','needs_manual') THEN v_item->>'status' ELSE 'pending' END,
      v_user_id,
      p_idempotency_key
    )
    RETURNING id INTO v_draft_id;
    v_ids := array_append(v_ids, v_draft_id);
  END LOOP;

  DECLARE
    v_result jsonb := jsonb_build_object('draft_ids', to_jsonb(v_ids), 'count', array_length(v_ids, 1));
  BEGIN
    IF p_idempotency_key IS NOT NULL THEN
      INSERT INTO idempotency_keys (idempotency_key, operation, result)
      VALUES (p_idempotency_key, 'bulk_create_label_drafts', v_result)
      ON CONFLICT (idempotency_key) DO NOTHING;
    END IF;
    RETURN v_result;
  END;
END;
$$;


ALTER FUNCTION "public"."bulk_create_label_drafts"("p_drafts" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_import_order"("p_order_number" "text", "p_customer_id" "uuid", "p_status" "text", "p_total_price" numeric, "p_total_cost" numeric, "p_total_profit" numeric, "p_total_margin_pct" numeric, "p_order_date" "date", "p_items" "jsonb", "p_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_order_id    uuid;
  v_existing    jsonb;
  v_result      jsonb;
  v_item        jsonb;
  v_item_count  int := 0;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  IF p_order_number IS NULL OR p_order_number = '' THEN RAISE EXCEPTION 'ORDER_NUMBER_REQUIRED'; END IF;
  IF p_customer_id IS NULL THEN RAISE EXCEPTION 'CUSTOMER_ID_REQUIRED'; END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'ITEMS_REQUIRED';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'bulk_import_order');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  INSERT INTO public.orders (
    order_number, customer_id, status,
    total_price, total_cost, total_profit, total_margin_pct,
    order_date, notes
  ) VALUES (
    p_order_number, p_customer_id,
    CASE WHEN p_status IN ('confirmed', 'partially_fulfilled', 'fulfilled', 'cancelled')
         THEN p_status ELSE 'confirmed' END,
    p_total_price, p_total_cost, p_total_profit, p_total_margin_pct,
    p_order_date, p_notes
  )
  RETURNING id INTO v_order_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    IF (v_item->>'product_name') IS NULL THEN
      RAISE EXCEPTION 'ITEM_INVALID: product_name required';
    END IF;
    IF (v_item->>'total_units_needed') IS NULL OR (v_item->>'total_units_needed')::numeric <= 0 THEN
      RAISE EXCEPTION 'ITEM_INVALID: total_units_needed must be > 0';
    END IF;

    -- Codex P2 fix: seed quantity_remaining so items are deliverable.
    INSERT INTO public.order_items (
      order_id, product_id, product_name,
      price_per_unit, cost_per_unit,
      total_units_needed, unit_size, notes,
      sort_order, quantity_delivered, quantity_remaining
    ) VALUES (
      v_order_id,
      NULLIF(v_item->>'product_id', '')::uuid,
      v_item->>'product_name',
      COALESCE((v_item->>'price_per_unit')::numeric, 0),
      COALESCE((v_item->>'unit_cost')::numeric, 0),
      (v_item->>'total_units_needed')::numeric,
      NULLIF(v_item->>'unit_size', ''),
      NULLIF(v_item->>'notes', ''),
      COALESCE((v_item->>'sort_order')::int, v_item_count + 1),
      0,
      (v_item->>'total_units_needed')::numeric
    );
    v_item_count := v_item_count + 1;
  END LOOP;

  v_result := jsonb_build_object(
    'success',     true,
    'order_id',    v_order_id,
    'item_count',  v_item_count
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'bulk_import_order', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."bulk_import_order"("p_order_number" "text", "p_customer_id" "uuid", "p_status" "text", "p_total_price" numeric, "p_total_cost" numeric, "p_total_profit" numeric, "p_total_margin_pct" numeric, "p_order_date" "date", "p_items" "jsonb", "p_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_billing_splits"("p_total_cents" bigint, "p_percentages" numeric[]) RETURNS bigint[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count int := array_length(p_percentages, 1);
  v_raw numeric[]; v_floored bigint[]; v_remainders numeric[];
  v_floor_sum bigint := 0; v_remainder bigint; v_result bigint[];
  v_used boolean[]; v_max_rem numeric; v_max_idx int; i int; j int;
BEGIN
  IF v_count IS NULL OR v_count = 0 THEN RAISE EXCEPTION 'At least one split percentage required'; END IF;
  v_raw := ARRAY[]::numeric[]; v_floored := ARRAY[]::bigint[]; v_remainders := ARRAY[]::numeric[];
  FOR i IN 1..v_count LOOP
    v_raw := array_append(v_raw, (p_total_cents * p_percentages[i] / 100.0));
    v_floored := array_append(v_floored, floor(v_raw[i])::bigint);
    v_remainders := array_append(v_remainders, v_raw[i] - floor(v_raw[i]));
    v_floor_sum := v_floor_sum + v_floored[i];
  END LOOP;
  v_remainder := p_total_cents - v_floor_sum;
  v_result := v_floored;
  v_used := ARRAY[]::boolean[];
  FOR i IN 1..v_count LOOP v_used := array_append(v_used, false); END LOOP;
  FOR j IN 1..v_remainder LOOP
    v_max_rem := -1; v_max_idx := 1;
    FOR i IN 1..v_count LOOP
      IF NOT v_used[i] AND v_remainders[i] > v_max_rem THEN v_max_rem := v_remainders[i]; v_max_idx := i; END IF;
    END LOOP;
    v_result[v_max_idx] := v_result[v_max_idx] + 1;
    v_used[v_max_idx] := true;
  END LOOP;
  RETURN v_result;
END; $$;


ALTER FUNCTION "public"."calculate_billing_splits"("p_total_cents" bigint, "p_percentages" numeric[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_prices_from_margin"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_mode text := COALESCE(NULLIF(current_setting('crx.pricing_mode', true), ''), 'legacy_margin');
  v_calc jsonb;
BEGIN
  -- The live trigger historically does nothing when cost is null/nonpositive;
  -- preserve that exact early-return behavior for every non-governed write.
  IF v_mode = 'legacy_margin' AND (NEW.current_cost IS NULL OR NEW.current_cost <= 0) THEN
    RETURN NEW;
  END IF;

  v_calc := public._calculate_product_pricing(
    v_mode,
    NEW.current_cost,
    NEW.tier1_margin, NEW.tier2_margin, NEW.tier3_margin,
    NEW.tier1_price, NEW.tier2_price, NEW.tier3_price
  );

  NEW.current_cost := (v_calc->>'current_cost')::numeric;
  NEW.tier1_margin := (v_calc->>'tier1_margin')::numeric;
  NEW.tier2_margin := (v_calc->>'tier2_margin')::numeric;
  NEW.tier3_margin := (v_calc->>'tier3_margin')::numeric;
  NEW.tier1_price := (v_calc->>'tier1_price')::numeric;
  NEW.tier2_price := (v_calc->>'tier2_price')::numeric;
  NEW.tier3_price := (v_calc->>'tier3_price')::numeric;
  NEW.tier1_gross_margin := (v_calc->>'tier1_gross_margin')::numeric;
  NEW.tier2_gross_margin := (v_calc->>'tier2_gross_margin')::numeric;
  NEW.tier3_gross_margin := (v_calc->>'tier3_gross_margin')::numeric;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_prices_from_margin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_cycle_count"("p_cycle_count_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_existing jsonb;
  v_count    record;
  v_result   jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Admin access required to cancel a cycle count';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'cancel_cycle_count');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_count FROM cycle_counts WHERE id = p_cycle_count_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cycle count not found: %', p_cycle_count_id;
  END IF;

  IF v_count.status != 'in_progress' THEN
    RAISE EXCEPTION 'Cannot cancel: cycle count is % (only in_progress counts can be cancelled)', v_count.status;
  END IF;

  UPDATE cycle_counts
  SET status = 'cancelled',
      notes  = COALESCE(notes || E'\n', '') || 'Cancelled on ' ||
               to_char(now(), 'YYYY-MM-DD HH24:MI') || ' by user ' || v_actor::text
  WHERE id = p_cycle_count_id;

  v_result := jsonb_build_object(
    'cycle_count_id', p_cycle_count_id,
    'status',         'cancelled'
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'cancel_cycle_count', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."cancel_cycle_count"("p_cycle_count_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_delivery"("p_delivery_id" "uuid", "p_cancel_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_delivery record; v_actor uuid; v_item record; v_items_restored integer := 0;
  v_prebooked_reincremented integer := 0; v_invoice record; v_draft_cancelled integer := 0;
  v_posted_notified integer := 0; v_admin record; v_order_has_remaining boolean; v_order_status text;
  v_result jsonb;
  v_quick_scheduled_exclusive boolean := false; v_prebooked_released integer := 0;
  v_qd_item record; v_release_qty numeric; v_actor_role text; v_paid_commissions integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF p_performed_by IS NOT NULL AND auth.uid() IS DISTINCT FROM p_performed_by THEN RAISE EXCEPTION 'actor mismatch'; END IF;
  v_actor := COALESCE(p_performed_by, auth.uid());

  IF p_idempotency_key IS NOT NULL THEN
    DECLARE v_cached jsonb;
    BEGIN v_cached := check_idempotency(p_idempotency_key, 'cancel_delivery'); IF v_cached IS NOT NULL THEN RETURN v_cached; END IF; END;
  END IF;

  SELECT * INTO v_delivery FROM deliveries WHERE id = p_delivery_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found'; END IF;
  IF v_delivery.status NOT IN ('scheduled', 'in_progress', 'completed') THEN RAISE EXCEPTION 'Cannot cancel a % delivery', v_delivery.status; END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN RAISE EXCEPTION 'Not authorized to cancel deliveries'; END IF;

  PERFORM set_config('app.admin_override', 'true', true);

  IF v_delivery.status IN ('completed', 'in_progress') THEN
    FOR v_item IN SELECT di.*, p.product_name FROM delivery_items di JOIN products p ON p.id = di.product_id WHERE di.delivery_id = p_delivery_id
    LOOP
      IF COALESCE(v_item.quantity_delivered, 0) > 0 THEN
        UPDATE inventory SET quantity_available = quantity_available + v_item.quantity_delivered, quantity_prebooked = quantity_prebooked + v_item.quantity_delivered, updated_at = now() WHERE product_id = v_item.product_id AND location = 'Main Warehouse';
        INSERT INTO inventory_transactions (product_id, transaction_type, quantity, to_location, order_id, delivery_id, performed_by, notes)
        VALUES (v_item.product_id, 'cancelled_delivery_reversal', v_item.quantity_delivered, 'Main Warehouse', v_delivery.order_id, p_delivery_id, v_actor, 'Delivery ' || v_delivery.delivery_number || ' cancelled — restored ' || v_item.quantity_delivered || ' units of ' || v_item.product_name);
        UPDATE order_items SET quantity_delivered = GREATEST(quantity_delivered - v_item.quantity_delivered, 0), quantity_remaining = quantity_remaining + v_item.quantity_delivered WHERE id = v_item.order_item_id;
        v_items_restored := v_items_restored + 1;
      END IF;
    END LOOP;
  END IF;

  IF v_delivery.order_id IS NOT NULL THEN
    -- Codex P2 (20260616171449): lock the order row so a concurrent update_order_items
    -- (which holds orders FOR UPDATE) cannot add/increase prebook in the window between
    -- the release loop and the order cancel. cancel_order locks the order the same way.
    SELECT status INTO v_order_status FROM orders WHERE id = v_delivery.order_id FOR UPDATE;

    IF COALESCE(v_delivery.is_quick_delivery, false) AND v_delivery.status IN ('scheduled', 'in_progress') THEN
      SELECT NOT EXISTS (
        SELECT 1 FROM deliveries
        WHERE order_id = v_delivery.order_id AND id <> p_delivery_id
          AND status NOT IN ('cancelled', 'voided')
      ) INTO v_quick_scheduled_exclusive;
    END IF;

    IF v_order_status IS NOT NULL AND v_order_status NOT IN ('cancelled', 'voided') THEN
      IF v_quick_scheduled_exclusive THEN
        -- Commission batch-freeze guard (overnight bug-hunt HIGH, 20260620): this branch
        -- auto-cancels the order and zeroes its pending commissions. A pending commission
        -- already committed to a non-voided commission_payments batch must not be silently
        -- cancelled — post_commission_payment would later resurrect it to 'paid'. Force the
        -- admin to void the payout first.
        IF EXISTS (
          SELECT 1
          FROM commissions cm
          JOIN commission_payment_items cpi ON cpi.commission_id = cm.id
          JOIN commission_payments cp ON cp.id = cpi.commission_payment_id
          WHERE cm.order_id = v_delivery.order_id
            AND cm.status = 'pending'
            AND cp.status <> 'voided'
        ) THEN
          RAISE EXCEPTION 'ORDER_HAS_BATCHED_COMMISSIONS: the order auto-cancelled by this quick delivery has pending commission(s) committed to an active commission payment batch. Void that payment first.';
        END IF;
        -- P2-1: release by ORDER_ITEMS (the booking source of truth) so edited/added quantities prebooked via
        -- update_order_items (which never touches delivery_items) are released too. Mirrors cancel_order.
        FOR v_qd_item IN SELECT product_id, total_units_needed, COALESCE(quantity_delivered, 0) AS quantity_delivered FROM order_items WHERE order_id = v_delivery.order_id
        LOOP
          v_release_qty := GREATEST(v_qd_item.total_units_needed - v_qd_item.quantity_delivered, 0);
          IF v_release_qty <= 0 THEN CONTINUE; END IF;
          UPDATE inventory SET quantity_prebooked = GREATEST(quantity_prebooked - v_release_qty, 0), updated_at = now() WHERE product_id = v_qd_item.product_id AND location = 'Main Warehouse';
          INSERT INTO inventory_transactions (product_id, transaction_type, quantity, to_location, order_id, delivery_id, performed_by, notes)
          VALUES (v_qd_item.product_id, 'released', v_release_qty, 'Main Warehouse', v_delivery.order_id, p_delivery_id, v_actor, 'Released ' || v_release_qty || ' units — quick delivery ' || v_delivery.delivery_number || ' cancelled');
          v_prebooked_released := v_prebooked_released + 1;
        END LOOP;

        UPDATE orders SET status = 'cancelled', updated_at = now() WHERE id = v_delivery.order_id;
        UPDATE commissions SET status = 'cancelled', commission_amount = 0 WHERE order_id = v_delivery.order_id AND status = 'pending';

        -- P2-2: a quick order may have already-paid commissions — flag for admin review (mirror cancel_order).
        SELECT COUNT(*) INTO v_paid_commissions FROM commissions WHERE order_id = v_delivery.order_id AND status = 'paid';
        IF v_paid_commissions > 0 THEN
          FOR v_admin IN SELECT id FROM profiles WHERE role = 'admin' AND is_active = true LOOP
            INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
            VALUES (v_admin.id, 'Cancelled Order Has Paid Commissions',
              'Quick-delivery order auto-cancelled with delivery ' || v_delivery.delivery_number || ' has ' || v_paid_commissions || ' paid commission(s). Manual review required.',
              'cancellation_review', 'order', v_delivery.order_id);
          END LOOP;
        END IF;

        SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor;
        INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_role, old_values, new_values, total_impact_cents, description)
        VALUES ('order_cancelled', 'order', v_delivery.order_id, COALESCE(v_actor_role, 'sales_rep'),
          jsonb_build_object('status', v_order_status),
          jsonb_build_object('status', 'cancelled', 'reason', 'Quick delivery ' || v_delivery.delivery_number || ' cancelled', 'prebook_lines_released', v_prebooked_released, 'paid_commissions_flagged', v_paid_commissions),
          0,
          'Auto-cancelled quick-delivery order on cancellation of delivery ' || v_delivery.delivery_number);
      ELSE
        SELECT EXISTS (SELECT 1 FROM order_items WHERE order_id = v_delivery.order_id AND quantity_remaining > 0) INTO v_order_has_remaining;
        IF v_order_has_remaining THEN
          IF EXISTS (SELECT 1 FROM order_items WHERE order_id = v_delivery.order_id AND quantity_delivered > 0) THEN
            UPDATE orders SET status = 'partially_fulfilled', updated_at = now() WHERE id = v_delivery.order_id;
          ELSE
            UPDATE orders SET status = 'confirmed', updated_at = now() WHERE id = v_delivery.order_id;
          END IF;
        END IF;
      END IF;
    END IF;
    UPDATE delivery_remainders SET status = 'cancelled', updated_at = now() WHERE original_delivery_id = p_delivery_id AND status = 'pending' AND followup_delivery_id IS NULL;
    UPDATE delivery_remainders SET status = 'fulfilled', updated_at = now() WHERE original_delivery_id = p_delivery_id AND status IN ('pending', 'scheduled') AND followup_delivery_id IS NOT NULL;
  END IF;

  UPDATE deliveries SET status = 'cancelled', cancelled_at = now(), cancelled_by = v_actor, cancel_reason = p_cancel_reason, updated_at = now() WHERE id = p_delivery_id;

  IF v_delivery.order_id IS NOT NULL THEN
    -- U2 (Codex P1): scope the invoice reversal to THIS delivery's own invoice or an
    -- order-level one (delivery_id IS NULL) — NEVER a sibling delivery's invoice. Was
    -- an unscoped per-order loop, which with per-delivery invoices would auto-cancel a
    -- sibling's draft/unposted invoice and raise a false posted-invoice review alert.
    FOR v_invoice IN SELECT * FROM invoices WHERE order_id = v_delivery.order_id AND status IN ('draft', 'posted', 'unposted') AND deleted_at IS NULL AND (delivery_id = p_delivery_id OR delivery_id IS NULL)
    LOOP
      IF v_invoice.status IN ('draft', 'unposted') THEN
        UPDATE invoices SET status = 'cancelled', voided_by = v_actor, void_reason = 'Auto-cancelled: delivery ' || v_delivery.delivery_number || ' cancelled', updated_at = now() WHERE id = v_invoice.id;
        v_draft_cancelled := v_draft_cancelled + 1;
      ELSIF v_invoice.status = 'posted' THEN
        FOR v_admin IN SELECT id FROM profiles WHERE role = 'admin' AND is_active = true LOOP
          INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id) VALUES (v_admin.id, 'Posted Invoice Needs Review', 'Delivery ' || v_delivery.delivery_number || ' cancelled but invoice ' || v_invoice.invoice_number || ' is posted.', 'invoice_review', 'invoice', v_invoice.id);
        END LOOP;
        v_posted_notified := v_posted_notified + 1;
      END IF;
    END LOOP;
  END IF;

  IF v_delivery.assigned_driver IS NOT NULL THEN
    INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id) VALUES (v_delivery.assigned_driver, 'Delivery Cancelled', 'Delivery ' || v_delivery.delivery_number || ' cancelled. Reason: ' || p_cancel_reason, 'delivery_update', 'delivery', p_delivery_id);
  END IF;

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('delivery_cancelled', 'Delivery ' || v_delivery.delivery_number || ' cancelled. Reason: ' || p_cancel_reason || CASE WHEN v_items_restored > 0 THEN '. Restored ' || v_items_restored || ' items.' ELSE '' END, v_actor, 'delivery', p_delivery_id, v_delivery.customer_id);

  PERFORM set_config('app.admin_override', 'false', true);

  v_result := jsonb_build_object('success', true, 'delivery_id', p_delivery_id, 'items_restored', v_items_restored, 'prebooked_reincremented', v_prebooked_reincremented, 'prebooked_released', v_prebooked_released, 'paid_commissions_flagged', v_paid_commissions, 'draft_invoices_cancelled', v_draft_cancelled, 'posted_invoices_flagged', v_posted_notified);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'cancel_delivery', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."cancel_delivery"("p_delivery_id" "uuid", "p_cancel_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_order"("p_order_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_contract CONSTANT text := 'cancel_order_v1';
  v_request jsonb;
  v_fingerprint text;
  v_replay jsonb;
  v_governed_ids uuid[] := '{}'::uuid[];
  v_result jsonb;
  v_claim_count integer := 0;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  IF p_performed_by IS NOT NULL AND v_actor IS DISTINCT FROM p_performed_by THEN
    RAISE EXCEPTION 'actor mismatch';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles p
     WHERE p.id = v_actor
       AND p.is_active = true
       AND p.role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Only admins can cancel orders';
  END IF;

  v_request := jsonb_build_object(
    'contract_version', v_contract,
    'actor_id', v_actor,
    'order_id', p_order_id
  );
  v_fingerprint := md5(v_request::text);
  IF p_idempotency_key IS NOT NULL THEN
    v_replay := public._claim_bound_lifecycle_idempotency(
      p_idempotency_key,
      'cancel_order',
      v_contract,
      v_fingerprint,
      v_request
    );
    IF v_replay IS NOT NULL THEN
      RETURN v_replay;
    END IF;
  END IF;

  PERFORM 1
    FROM public.orders o
   WHERE o.id = p_order_id
   FOR UPDATE;

  SELECT COALESCE(array_agg(locked.invoice_id ORDER BY locked.invoice_id), '{}'::uuid[])
    INTO v_governed_ids
    FROM (
      SELECT i.id AS invoice_id
        FROM public.invoices i
        JOIN public.split_invoice_provenance p ON p.invoice_id = i.id
       WHERE i.order_id = p_order_id
       ORDER BY i.id
       FOR UPDATE OF i
    ) locked;

  INSERT INTO public.split_invoice_mutation_claims (
    transaction_id, invoice_id, operation
  )
  SELECT pg_current_xact_id(), governed.invoice_id, 'cancel_order'
    FROM unnest(v_governed_ids) AS governed(invoice_id);

  v_result := public._cancel_order_split_provenance_impl_20260719(
    p_order_id,
    p_performed_by,
    NULL::text
  );

  UPDATE public.split_invoice_provenance p
     SET total_amount_cents = i.total_amount_cents,
         content_claim = public._split_invoice_content_claim(i.id)
    FROM public.invoices i
   WHERE p.invoice_id = i.id
     AND p.invoice_id = ANY(v_governed_ids)
     AND p.order_id = i.order_id
     AND p.invoice_group_id = i.invoice_group_id
     AND p.customer_id = i.customer_id
     AND p.invoice_type = i.invoice_type
     AND p.season = i.season
     AND i.status IN ('voided', 'cancelled');

  IF EXISTS (
    SELECT 1
      FROM public.invoices i
      JOIN public.split_invoice_provenance p ON p.invoice_id = i.id
     WHERE i.id = ANY(v_governed_ids)
       AND i.status IN ('voided', 'cancelled')
       AND (
         p.total_amount_cents IS DISTINCT FROM i.total_amount_cents
         OR p.content_claim IS DISTINCT FROM public._split_invoice_content_claim(i.id)
       )
  ) THEN
    RAISE EXCEPTION 'SPLIT_INVOICE_CANCEL_PROVENANCE_REFRESH_FAILED';
  END IF;

  DELETE FROM public.split_invoice_mutation_claims claim
   WHERE claim.transaction_id = pg_current_xact_id()
     AND claim.operation = 'cancel_order'
     AND claim.invoice_id = ANY(v_governed_ids);
  GET DIAGNOSTICS v_claim_count = ROW_COUNT;
  IF v_claim_count IS DISTINCT FROM cardinality(v_governed_ids) THEN
    RAISE EXCEPTION 'SPLIT_INVOICE_CANCEL_CLAIM_LOST';
  END IF;

  PERFORM public._bind_completed_lifecycle_idempotency(
    p_idempotency_key,
    'cancel_order',
    v_contract,
    v_fingerprint,
    v_request,
    v_result
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."cancel_order"("p_order_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_purchase_order"("p_po_id" "uuid", "p_reason" "text" DEFAULT 'Cancelled'::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_po record;
  v_actor uuid;
  v_cached_result jsonb;
  v_result jsonb;
  v_received_qty numeric;
  v_active_bill_count integer;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by <> v_actor THEN
    RAISE EXCEPTION 'Actor mismatch';
  END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: only admins or sales reps can cancel purchase orders';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached_result := check_idempotency(p_idempotency_key, 'cancel_purchase_order');
    IF v_cached_result IS NOT NULL THEN RETURN v_cached_result; END IF;
  END IF;

  SELECT * INTO v_po FROM purchase_orders WHERE id = p_po_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase order not found'; END IF;

  IF v_po.status = 'cancelled' THEN
    v_result := jsonb_build_object('status', 'already_cancelled', 'po_id', p_po_id, 'po_number', v_po.po_number);
    IF p_idempotency_key IS NOT NULL THEN
      PERFORM save_idempotency(p_idempotency_key, 'cancel_purchase_order', v_result);
    END IF;
    RETURN v_result;
  END IF;

  SELECT count(*) INTO v_active_bill_count FROM vendor_bills
  WHERE purchase_order_id = p_po_id AND status NOT IN ('voided') AND deleted_at IS NULL;

  IF v_active_bill_count > 0 THEN
    RAISE EXCEPTION 'PO_HAS_ACTIVE_BILLS: cannot cancel PO % — % active vendor bill(s) reference it. Void the bill(s) first.',
      v_po.po_number, v_active_bill_count;
  END IF;

  SELECT COALESCE(SUM(quantity_received), 0) INTO v_received_qty
  FROM purchase_order_items WHERE purchase_order_id = p_po_id;

  IF v_received_qty > 0 THEN
    RAISE EXCEPTION 'Cannot cancel PO %: % units already received. Use partial receive workflow instead.',
      v_po.po_number, v_received_qty;
  END IF;

  IF v_po.status = 'fully_received' THEN
    RAISE EXCEPTION 'Cannot cancel PO %: already fully received', v_po.po_number;
  END IF;

  UPDATE purchase_orders SET status = 'cancelled', cancelled_at = now(),
    cancelled_by = v_actor,
    cancel_reason = COALESCE(NULLIF(TRIM(p_reason), ''), 'Cancelled'),
    updated_at = now()
  WHERE id = p_po_id;

  INSERT INTO activity_feed (
    event_type, description, performed_by, related_entity_type, related_entity_id
  ) VALUES (
    'po_cancelled',
    'Purchase order ' || v_po.po_number || ' cancelled. Reason: '
      || COALESCE(NULLIF(TRIM(p_reason), ''), 'Cancelled'),
    v_actor, 'purchase_order', p_po_id
  );

  v_result := jsonb_build_object('status', 'cancelled', 'po_id', p_po_id, 'po_number', v_po.po_number);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'cancel_purchase_order', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."cancel_purchase_order"("p_po_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_return"("p_return_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_return record;
  v_item record;
  v_cached jsonb;
  v_result jsonb;
  v_reversed_ids uuid[] := ARRAY[]::uuid[];
  v_skipped_ids uuid[] := ARRAY[]::uuid[];
  v_reversed_qty bigint := 0;
  v_reversed_count int := 0;
  v_skipped_count int := 0;
  v_was_received boolean;
  v_actor uuid;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached := public.check_idempotency(p_idempotency_key, 'cancel_return');
    IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required to cancel a return';
  END IF;

  SELECT id, return_number, status, customer_id INTO v_return
  FROM public.returns WHERE id = p_return_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Return not found: %', p_return_id;
  END IF;

  IF v_return.status NOT IN ('requested', 'approved', 'received') THEN
    RAISE EXCEPTION 'Cannot cancel return in status "%" - only requested/approved/received returns can be cancelled', v_return.status;
  END IF;

  v_was_received := (v_return.status = 'received');

  IF v_was_received THEN
    FOR v_item IN
      SELECT ri.id AS item_id, ri.product_id, ri.quantity, ri.product_name, ri.condition,
             inv.id AS inv_id, inv.location AS inv_location
      FROM public.return_items ri
      LEFT JOIN LATERAL (
        SELECT id, location FROM public.inventory
        WHERE product_id = ri.product_id AND location = 'Main Warehouse'
        LIMIT 1
      ) inv ON true
      WHERE ri.return_id = p_return_id AND ri.restocked = true
      ORDER BY ri.sort_order
    LOOP
      IF v_item.inv_id IS NOT NULL THEN
        UPDATE public.inventory
           SET quantity_available = quantity_available - v_item.quantity,
               updated_at = now()
         WHERE id = v_item.inv_id;

        INSERT INTO public.inventory_transactions (
          product_id, transaction_type, quantity, to_location, performed_by, notes
        )
        VALUES (
          v_item.product_id,
          'returned',
          -v_item.quantity,
          v_item.inv_location,
          v_actor,
          'Cancel of return ' || v_return.return_number || ': ' || v_item.product_name ||
          ' (' || v_item.condition || ') - restock reversed: ' || p_reason
        );

        v_reversed_ids := array_append(v_reversed_ids, v_item.item_id);
        v_reversed_qty := v_reversed_qty + v_item.quantity;
        v_reversed_count := v_reversed_count + 1;
      ELSE
        RAISE WARNING 'Cancel of return %: item % (product %) was restocked but inventory row no longer exists - skipping reversal, restocked flag will still be cleared.',
          v_return.return_number, v_item.item_id, v_item.product_id;
        v_skipped_ids := array_append(v_skipped_ids, v_item.item_id);
        v_skipped_count := v_skipped_count + 1;
      END IF;
    END LOOP;
  END IF;

  PERFORM set_config('app.admin_override', 'true', true);

  UPDATE public.returns
     SET status = 'cancelled',
         cancelled_at = now(),
         cancelled_by = v_actor,
         cancellation_reason = p_reason,
         updated_at = now()
   WHERE id = p_return_id;

  PERFORM set_config('app.admin_override', 'false', true);

  IF array_length(v_reversed_ids, 1) > 0 OR array_length(v_skipped_ids, 1) > 0 THEN
    UPDATE public.return_items
       SET restocked = false
     WHERE id = ANY(v_reversed_ids || v_skipped_ids);
  END IF;

  INSERT INTO public.activity_feed (
    event_type, description, performed_by, related_entity_type, related_entity_id, customer_id
  )
  VALUES (
    'return_cancelled',
    'Return ' || v_return.return_number || ' cancelled' ||
    CASE WHEN v_was_received
         THEN ' - ' || v_reversed_count || ' item(s) un-restocked' ||
              CASE WHEN v_skipped_count > 0
                   THEN ' (' || v_skipped_count || ' skipped: inventory row missing - admin must reconcile)'
                   ELSE '' END
         ELSE '' END ||
    ': ' || p_reason,
    v_actor,
    'return',
    p_return_id,
    v_return.customer_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'return_id', p_return_id,
    'return_number', v_return.return_number,
    'status', 'cancelled',
    'was_received', v_was_received,
    'reversed_count', v_reversed_count,
    'reversed_quantity', v_reversed_qty,
    'skipped_count', v_skipped_count
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(p_idempotency_key, 'cancel_return', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."cancel_return"("p_return_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_customer_credit_limit"("p_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_credit_limit_cents bigint;
  v_farm_name text;
  v_outstanding_ar_cents bigint;
BEGIN
  -- Get customer info
  SELECT credit_limit_cents, farm_name
  INTO v_credit_limit_cents, v_farm_name
  FROM customers
  WHERE id = p_customer_id;

  IF v_credit_limit_cents IS NULL OR v_credit_limit_cents <= 0 THEN
    RETURN jsonb_build_object(
      'exceeded', false,
      'credit_limit', 0,
      'outstanding_ar', 0,
      'farm_name', COALESCE(v_farm_name, '')
    );
  END IF;

  SELECT COALESCE(SUM(GREATEST(balance_cents, 0)), 0)
  INTO v_outstanding_ar_cents
  FROM invoices
  WHERE customer_id = p_customer_id
    AND status IN ('posted', 'overdue', 'unposted')
    AND deleted_at IS NULL;

  RETURN jsonb_build_object(
    'exceeded', v_outstanding_ar_cents > v_credit_limit_cents,
    'credit_limit', v_credit_limit_cents / 100.0,
    'outstanding_ar', v_outstanding_ar_cents / 100.0,
    'available_credit', GREATEST(v_credit_limit_cents - v_outstanding_ar_cents, 0) / 100.0,
    'farm_name', COALESCE(v_farm_name, '')
  );
END;
$$;


ALTER FUNCTION "public"."check_customer_credit_limit"("p_customer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_customer_credit_limit"("p_customer_id" "uuid") IS 'Returns credit limit status for a customer including outstanding AR and whether limit is exceeded.';



CREATE OR REPLACE FUNCTION "public"."check_duplicate_blend_ticket"("p_ticket_number" "text", "p_ticket_date" "date") RETURNS TABLE("id" "uuid", "ticket_number" "text", "ticket_date" "date", "status" "text", "review_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
    SELECT bt.id, bt.ticket_number, bt.ticket_date, bt.status, bt.review_status
    FROM blend_tickets bt
    WHERE bt.ticket_number = p_ticket_number
      AND bt.ticket_date = p_ticket_date
      AND bt.deleted_at IS NULL;
END;
$$;


ALTER FUNCTION "public"."check_duplicate_blend_ticket"("p_ticket_number" "text", "p_ticket_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_duplicate_delivery"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'delivery_id', d.id,
    'delivery_number', d.delivery_number,
    'status', d.status,
    'scheduled_date', d.scheduled_date
  )), '[]'::jsonb)
  INTO v_result
  FROM deliveries d
  WHERE d.order_id = p_order_id
    AND d.status IN ('scheduled', 'in_progress');

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."check_duplicate_delivery"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_idempotency"("p_key" "text", "p_operation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing public.idempotency_keys%ROWTYPE;
BEGIN
  IF p_key IS NULL THEN
    RETURN NULL;
  END IF;
  IF btrim(p_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;
  IF p_operation IS NULL OR btrim(p_operation) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_OPERATION_REQUIRED';
  END IF;

  -- Serialize every transaction using the same key. The lock is intentionally
  -- key-only so same-operation retries replay and cross-operation reuse fails
  -- before either caller can perform business side effects.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('crx:idempotency:' || p_key, 0)
  );

  DELETE FROM public.idempotency_keys
   WHERE idempotency_key = p_key
     AND expires_at < now();

  SELECT *
    INTO v_existing
    FROM public.idempotency_keys
   WHERE idempotency_key = p_key;

  IF FOUND AND v_existing.operation IS DISTINCT FROM p_operation THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_CROSS_OP_KEY_REUSE: idempotency_key % is already in use for operation %; cannot reuse it for operation %',
      p_key, v_existing.operation, p_operation;
  END IF;

  IF FOUND THEN
    RETURN v_existing.result;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."check_idempotency"("p_key" "text", "p_operation" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_period_open"("p_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_period record;
BEGIN
  SELECT id, period_start, period_end
    INTO v_period
    FROM public.accounting_periods
   WHERE status = 'closed'
     AND p_date BETWEEN period_start AND period_end
   LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Date % falls in closed accounting period (% to %)',
      p_date, v_period.period_start, v_period.period_end;
  END IF;
END;
$$;


ALTER FUNCTION "public"."check_period_open"("p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_operation" "text", "p_max_calls" integer DEFAULT 10, "p_window_seconds" integer DEFAULT 60) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_window_start timestamptz;
  v_count int;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Round to window boundary
  v_window_start := date_trunc('minute', now()) 
    + (floor(extract(epoch from (now() - date_trunc('minute', now()))) / p_window_seconds) * p_window_seconds) * interval '1 second';

  -- Upsert and get count (uses new rate_limits table)
  INSERT INTO rate_limits (user_id, action_name, window_start, request_count)
  VALUES (p_user_id, p_operation, v_window_start, 1)
  ON CONFLICT (user_id, action_name, window_start)
  DO UPDATE SET request_count = rate_limits.request_count + 1
  RETURNING request_count INTO v_count;

  IF v_count > p_max_calls THEN
    RAISE EXCEPTION 'Rate limit exceeded: % requests per % seconds for %', 
      p_max_calls, p_window_seconds, p_operation;
  END IF;
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_operation" "text", "p_max_calls" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_remainder_reminders"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_remainder record;
  v_admin record;
  v_sales_rep_id uuid;
  v_reminders_sent integer := 0;
  v_escalations_sent integer := 0;
BEGIN
  -- B10 (2026-05-26): admin-only when an authenticated user calls this.
  -- pg_cron (job `check-remainder-reminders`, runs as superuser) and
  -- service_role have auth.uid() = NULL and bypass this check.
  IF auth.uid() IS NOT NULL AND NOT is_admin() THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- M3 FIX: Use FOR UPDATE SKIP LOCKED to prevent duplicate notifications
  FOR v_remainder IN
    SELECT dr.*, p.product_name, d.delivery_number,
           o.customer_id AS order_customer_id
    FROM delivery_remainders dr
    JOIN products p ON p.id = dr.product_id
    JOIN deliveries d ON d.id = dr.original_delivery_id
    JOIN orders o ON o.id = dr.order_id
    WHERE dr.status = 'pending'
      AND dr.created_at < NOW() - INTERVAL '7 days'
      AND dr.reminder_sent_at IS NULL
    FOR UPDATE OF dr SKIP LOCKED
  LOOP
    SELECT c.assigned_sales_rep INTO v_sales_rep_id
    FROM customers c WHERE c.id = v_remainder.customer_id;

    FOR v_admin IN
      SELECT id FROM profiles WHERE role = 'admin' AND is_active = true
    LOOP
      INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
      VALUES (
        v_admin.id,
        'Delivery Remainder Pending 7+ Days',
        v_remainder.product_name || ' (' || v_remainder.quantity_remaining || ' units) from delivery ' || v_remainder.delivery_number || ' has been pending for 7+ days.',
        'remainder_reminder', 'delivery', v_remainder.original_delivery_id
      );
    END LOOP;

    IF v_sales_rep_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM profiles WHERE id = v_sales_rep_id AND role = 'admin'
    ) THEN
      INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
      VALUES (
        v_sales_rep_id,
        'Delivery Remainder Pending 7+ Days',
        v_remainder.product_name || ' (' || v_remainder.quantity_remaining || ' units) from delivery ' || v_remainder.delivery_number || ' has been pending for 7+ days.',
        'remainder_reminder', 'delivery', v_remainder.original_delivery_id
      );
    END IF;

    UPDATE delivery_remainders SET reminder_sent_at = NOW() WHERE id = v_remainder.id;
    v_reminders_sent := v_reminders_sent + 1;
  END LOOP;

  FOR v_remainder IN
    SELECT dr.*, p.product_name, d.delivery_number
    FROM delivery_remainders dr
    JOIN products p ON p.id = dr.product_id
    JOIN deliveries d ON d.id = dr.original_delivery_id
    WHERE dr.status = 'pending'
      AND dr.created_at < NOW() - INTERVAL '14 days'
      AND dr.reminder_sent_at IS NOT NULL
      AND dr.escalation_sent_at IS NULL
    FOR UPDATE OF dr SKIP LOCKED
  LOOP
    FOR v_admin IN
      SELECT id FROM profiles WHERE role = 'admin' AND is_active = true
    LOOP
      INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
      VALUES (
        v_admin.id,
        'URGENT: Delivery Remainder Pending 14+ Days',
        v_remainder.product_name || ' (' || v_remainder.quantity_remaining || ' units) from delivery ' || v_remainder.delivery_number || ' has been pending for 14+ days. Please schedule follow-up or cancel.',
        'remainder_escalation', 'delivery', v_remainder.original_delivery_id
      );
    END LOOP;

    UPDATE delivery_remainders SET escalation_sent_at = NOW() WHERE id = v_remainder.id;
    v_escalations_sent := v_escalations_sent + 1;
  END LOOP;

  RETURN jsonb_build_object('reminders_sent', v_reminders_sent, 'escalations_sent', v_escalations_sent);
END;
$$;


ALTER FUNCTION "public"."check_remainder_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_unpriced_orders"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order       record;
  v_admin       record;
  v_rep         uuid;
  v_reminders   integer := 0;
  v_escalations integer := 0;
BEGIN
  -- admin-only when an authenticated user calls this; pg_cron / service_role
  -- (auth.uid() = NULL) bypass. Same pattern as check_remainder_reminders.
  IF auth.uid() IS NOT NULL AND NOT is_admin() THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- 48h reminder
  FOR v_order IN
    SELECT o.id, o.order_number, c.farm_name, c.assigned_sales_rep
    FROM orders o
    JOIN customers c ON c.id = o.customer_id
    WHERE o.pricing_status = 'needs_pricing'
      AND o.status NOT IN ('cancelled', 'voided')  -- Codex P2: don't remind on terminal orders
      AND o.deleted_at IS NULL
      AND o.created_at < NOW() - INTERVAL '48 hours'
      AND o.pricing_reminder_sent_at IS NULL
    FOR UPDATE OF o SKIP LOCKED
  LOOP
    FOR v_admin IN SELECT id FROM profiles WHERE role = 'admin' AND is_active = true LOOP
      INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
      VALUES (v_admin.id, 'Order needs pricing (48h+)',
        'Order ' || v_order.order_number || ' for ' || COALESCE(v_order.farm_name, 'customer') ||
        ' has been unpriced for 48h+ — set its prices so it can be invoiced.',
        'needs_pricing', 'order', v_order.id);
    END LOOP;

    v_rep := v_order.assigned_sales_rep;
    IF v_rep IS NOT NULL AND NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_rep AND role = 'admin') THEN
      INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
      VALUES (v_rep, 'Order needs pricing (48h+)',
        'Order ' || v_order.order_number || ' for ' || COALESCE(v_order.farm_name, 'customer') ||
        ' has been unpriced for 48h+ — set its prices so it can be invoiced.',
        'needs_pricing', 'order', v_order.id);
    END IF;

    UPDATE orders SET pricing_reminder_sent_at = NOW() WHERE id = v_order.id;
    v_reminders := v_reminders + 1;
  END LOOP;

  -- 7-day escalation
  FOR v_order IN
    SELECT o.id, o.order_number, c.farm_name
    FROM orders o
    JOIN customers c ON c.id = o.customer_id
    WHERE o.pricing_status = 'needs_pricing'
      AND o.status NOT IN ('cancelled', 'voided')  -- Codex P2: don't escalate terminal orders
      AND o.deleted_at IS NULL
      AND o.created_at < NOW() - INTERVAL '7 days'
      AND o.pricing_reminder_sent_at IS NOT NULL
      AND o.pricing_escalation_sent_at IS NULL
    FOR UPDATE OF o SKIP LOCKED
  LOOP
    FOR v_admin IN SELECT id FROM profiles WHERE role = 'admin' AND is_active = true LOOP
      INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
      VALUES (v_admin.id, 'URGENT: Order unpriced 7+ days',
        'Order ' || v_order.order_number || ' for ' || COALESCE(v_order.farm_name, 'customer') ||
        ' has been unpriced for 7+ days. Price it now or cancel — its invoice cannot post until priced.',
        'needs_pricing_escalation', 'order', v_order.id);
    END LOOP;

    UPDATE orders SET pricing_escalation_sent_at = NOW() WHERE id = v_order.id;
    v_escalations := v_escalations + 1;
  END LOOP;

  RETURN jsonb_build_object('reminders_sent', v_reminders, 'escalations_sent', v_escalations);
END;
$$;


ALTER FUNCTION "public"."check_unpriced_orders"() OWNER TO "postgres";


