CREATE OR REPLACE FUNCTION "public"."close_accounting_period"("p_period_end" "date", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_actor uuid; v_period_start date; v_unposted_count integer; v_period_id uuid; v_summary jsonb; v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Actor mismatch';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.profiles
    WHERE id = v_actor AND role = 'admin' AND is_active = true) THEN
    RAISE EXCEPTION 'Only admin users can close accounting periods';
  END IF;

  -- A9 guard 1: a period must be exactly one whole calendar month.
  -- date_trunc() silently accepts a mid-month end date, which would insert a SECOND,
  -- overlapping closed row alongside the full-month row (unique key is start+end).
  IF p_period_end IS NULL
     OR p_period_end <> (date_trunc('month', p_period_end) + INTERVAL '1 month - 1 day')::date THEN
    RAISE EXCEPTION 'Period end % must be the last day of a calendar month', p_period_end;
  END IF;

  -- A9 guard 2: a period may only be closed AFTER it has ended (owner rule 2026-07-10).
  -- The business day is America/Chicago; the DB session is UTC, so CURRENT_DATE would
  -- be about five hours ahead of the Crop RX accounting day during Central evening.
  IF p_period_end >= (now() AT TIME ZONE 'America/Chicago')::date THEN
    RAISE EXCEPTION 'Cannot close period ending %: the period has not ended yet', p_period_end;
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'close_accounting_period');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  v_period_start := date_trunc('month', p_period_end)::date;

  SELECT count(*) INTO v_unposted_count FROM public.invoices
  WHERE invoice_date BETWEEN v_period_start AND p_period_end
    AND status IN ('draft', 'unposted') AND deleted_at IS NULL;

  IF v_unposted_count > 0 THEN
    RAISE EXCEPTION 'Cannot close period: % unposted invoice(s) exist between % and %',
      v_unposted_count, v_period_start, p_period_end;
  END IF;

  IF EXISTS (SELECT 1 FROM public.accounting_periods
    WHERE period_start = v_period_start AND period_end = p_period_end AND status = 'closed') THEN
    RAISE EXCEPTION 'Period % to % is already closed', v_period_start, p_period_end;
  END IF;

  INSERT INTO public.accounting_periods (period_start, period_end, status, closed_by, closed_at)
  VALUES (v_period_start, p_period_end, 'closed', v_actor, now())
  ON CONFLICT (period_start, period_end)
  DO UPDATE SET status = 'closed', closed_by = v_actor, closed_at = now(), updated_at = now()
  RETURNING id INTO v_period_id;

  SELECT jsonb_build_object('period_id', v_period_id,
    'period_start', v_period_start, 'period_end', p_period_end,
    'invoices_posted', (SELECT count(*) FROM public.invoices
      WHERE invoice_date BETWEEN v_period_start AND p_period_end
        AND status = 'posted' AND deleted_at IS NULL),
    'total_invoiced_cents', COALESCE((SELECT sum(total_amount_cents) FROM public.invoices
      WHERE invoice_date BETWEEN v_period_start AND p_period_end
        AND status = 'posted' AND deleted_at IS NULL), 0),
    'payments_received_cents', COALESCE((SELECT (sum(amount) * 100)::bigint FROM public.payments
      WHERE payment_date BETWEEN v_period_start AND p_period_end), 0),
    'orders_count', (SELECT count(*) FROM public.orders
      WHERE order_date BETWEEN v_period_start AND p_period_end AND deleted_at IS NULL),
    'deliveries_count', (SELECT count(*) FROM public.deliveries
      WHERE scheduled_date BETWEEN v_period_start AND p_period_end AND deleted_at IS NULL))
  INTO v_summary;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'close_accounting_period', v_summary);
  END IF;

  RETURN v_summary;
END;
$$;


ALTER FUNCTION "public"."close_accounting_period"("p_period_end" "date", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_quote_as_applied"("p_quote_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_actor_role text;
  v_quote record;
  v_customer record;
  v_existing jsonb;
  v_released_units numeric := 0;
  v_released_lines jsonb := '[]'::jsonb;
  v_active_jobs integer := 0;
  v_warnings text[] := '{}'::text[];
  v_result jsonb;
BEGIN
  -- Auth + strict actor (a forged p_performed_by is rejected).
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_actor_role
  FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- Lock the quote: serialize with concurrent draws / job syncs on this booking.
  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found'; END IF;

  -- Idempotency AFTER the lock (same ordering as draw_down_quote): the row lock
  -- serializes same-key duplicates so the non-atomic check/save can't both pass.
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'close_quote_as_applied');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  -- Already closed this way? Return gracefully (repeat click without a key).
  IF v_quote.status = 'closed_by_application' THEN
    RETURN jsonb_build_object(
      'success', true, 'status', 'closed_by_application', 'already_closed', true,
      'quote_id', p_quote_id, 'released_units', 0, 'warnings', '[]'::jsonb);
  END IF;

  -- Only an OPEN booking can be closed as fulfilled-by-application.
  IF v_quote.status NOT IN ('sent', 'revised') THEN
    RAISE EXCEPTION 'BOOKING_CLOSED: quote % is % — only sent or revised bookings can be closed as fulfilled by application',
      v_quote.quote_number, v_quote.status;
  END IF;

  -- Only a PLANNED booking (the application channel) can be closed this way. A
  -- plain non-planned sales quote belongs to the chemical-sale / convert channel
  -- and must not be mislabeled "fulfilled by application". (Codex 2026-07-03 P2)
  IF NOT v_quote.is_planned THEN
    RAISE EXCEPTION 'NOT_A_PLANNED_BOOKING: quote % is not a planned booking — only a planned application program can be closed as fulfilled by application',
      v_quote.quote_number;
  END IF;

  SELECT * INTO v_customer FROM customers WHERE id = v_quote.customer_id;

  -- Measure the un-applied / un-delivered leftover this close will release:
  -- booked − order draws − job draws, per product (>= 0). This is exactly the
  -- crop_program hold quantity the release trigger will drop.
  WITH booked AS (
    SELECT qi.product_id, SUM(COALESCE(qi.total_units_needed, 0)) AS booked_qty
    FROM quote_items qi WHERE qi.quote_id = p_quote_id GROUP BY qi.product_id
  ),
  ord AS (
    SELECT product_id, quantity_drawn
    FROM quote_product_draws WHERE quote_id = p_quote_id
  ),
  job AS (
    SELECT product_id, SUM(quantity_drawn) AS qty
    FROM job_product_draws WHERE quote_id = p_quote_id GROUP BY product_id
  ),
  leftover AS (
    SELECT b.product_id,
           GREATEST(b.booked_qty - COALESCE(o.quantity_drawn, 0) - COALESCE(j.qty, 0), 0) AS remaining_qty
    FROM booked b
    LEFT JOIN ord o ON o.product_id = b.product_id
    LEFT JOIN job j ON j.product_id = b.product_id
  )
  SELECT
    COALESCE(SUM(l.remaining_qty), 0),
    COALESCE(jsonb_agg(jsonb_build_object(
      'product_id', l.product_id,
      'product_name', p.product_name,
      'released_qty', l.remaining_qty) ORDER BY p.product_name)
      FILTER (WHERE l.remaining_qty > 0), '[]'::jsonb)
  INTO v_released_units, v_released_lines
  FROM leftover l LEFT JOIN products p ON p.id = l.product_id;

  -- Informational (never blocks): jobs still scheduled/in-progress on this booking.
  SELECT COUNT(*) INTO v_active_jobs FROM jobs
  WHERE quote_id = p_quote_id AND deleted_at IS NULL
    AND status IN ('scheduled', 'in_progress');

  IF v_released_units > 0 THEN
    v_warnings := array_append(v_warnings,
      'Released ' || v_released_units || ' un-applied unit(s) back to free inventory');
  END IF;
  IF v_active_jobs > 0 THEN
    v_warnings := array_append(v_warnings,
      v_active_jobs || ' job(s) are still scheduled against this booking');
  END IF;

  -- Flip to the terminal status. This UPDATE fires:
  --   _enforce_quote_status_transition   (edge sent/revised -> closed added above)
  --   release_holds_on_quote_status_change (deactivates the quote's crop_program
  --     holds — the leftover; job holds have source_id=job_id, untouched)
  --   trg_enforce_quote_terminal_not_drawn only blocks declined/cancelled/expired
  --   enforce_quote_accepted_fully_drawn fires only for 'accepted'
  UPDATE quotes SET status = 'closed_by_application', updated_at = now()
  WHERE id = p_quote_id;

  -- No financial_audit_log entry: closing moves NO money (billing already
  -- happened via each job's application invoice). Log to activity_feed only —
  -- always, even when nothing was released, so the close itself is visible.
  INSERT INTO activity_feed (event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id)
  VALUES ('quote_closed_by_application',
    'Booking ' || v_quote.quote_number || ' closed — fulfilled by application for ' ||
      COALESCE(v_customer.farm_name, 'customer') ||
      CASE WHEN v_released_units > 0
        THEN ' (released ' || v_released_units || ' un-applied unit(s))' ELSE '' END,
    v_actor, 'quote', p_quote_id, v_quote.customer_id);

  v_result := jsonb_build_object(
    'success', true,
    'status', 'closed_by_application',
    'quote_id', p_quote_id,
    'quote_number', v_quote.quote_number,
    'released_units', v_released_units,
    'released_lines', v_released_lines,
    'active_jobs_remaining', v_active_jobs,
    'warnings', to_jsonb(v_warnings));

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'close_quote_as_applied', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."close_quote_as_applied"("p_quote_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_quote_as_short"("p_quote_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_actor_role text;
  v_quote record;
  v_customer record;
  v_existing jsonb;
  v_released_units numeric := 0;
  v_released_lines jsonb := '[]'::jsonb;
  v_active_jobs integer := 0;
  v_warnings text[] := '{}'::text[];
  v_result jsonb;
BEGIN
  -- Auth + strict actor (a forged p_performed_by is rejected).
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_actor_role
  FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- Lock the quote: serialize with concurrent draws / job syncs on this booking.
  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found'; END IF;

  -- Idempotency AFTER the lock (same ordering as draw_down_quote): the row lock
  -- serializes same-key duplicates so the non-atomic check/save can't both pass.
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'close_quote_as_short');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  -- Already closed short? Return gracefully (repeat click without a key).
  IF v_quote.status = 'closed_short' THEN
    RETURN jsonb_build_object(
      'success', true, 'status', 'closed_short', 'already_closed', true,
      'quote_id', p_quote_id, 'released_units', 0, 'warnings', '[]'::jsonb);
  END IF;

  -- Only an OPEN booking can be short-closed.
  IF v_quote.status NOT IN ('sent', 'revised') THEN
    RAISE EXCEPTION 'BOOKING_CLOSED: quote % is % — only sent or revised bookings can be closed as short',
      v_quote.quote_number, v_quote.status;
  END IF;

  -- DIVERGENCE #1 vs close_quote_as_applied: is_planned is NOT required. A
  -- non-planned open booking a customer walked away from is a valid short-close;
  -- it simply has no crop_program holds to release (the release trigger no-ops).

  -- DIVERGENCE #2 vs close_quote_as_applied: REFUSE while any job is still
  -- scheduled/in-progress. A live job still reserves + expects to APPLY its
  -- chemicals, which contradicts "walked away, release the remainder". The user
  -- must cancel or complete those jobs first.
  SELECT COUNT(*) INTO v_active_jobs FROM jobs
  WHERE quote_id = p_quote_id AND deleted_at IS NULL
    AND status IN ('scheduled', 'in_progress');
  IF v_active_jobs > 0 THEN
    RAISE EXCEPTION 'BOOKING_HAS_ACTIVE_JOBS: quote % still has % scheduled/in-progress job(s) — cancel or complete them before closing the booking as short',
      v_quote.quote_number, v_active_jobs;
  END IF;

  SELECT * INTO v_customer FROM customers WHERE id = v_quote.customer_id;

  -- Measure what this close will actually release: the quote's ACTIVE
  -- crop_program holds — exactly the rows the release trigger deactivates.
  -- (Codex round-2 P2: computing this from quote_items over-reported a
  -- "release" on a NON-planned booking, which has no holds at all — the
  -- trigger no-ops there and released_units correctly comes out 0.)
  SELECT
    COALESCE(SUM(h.quantity), 0),
    COALESCE(jsonb_agg(jsonb_build_object(
      'product_id', h.product_id,
      'product_name', p.product_name,
      'released_qty', h.quantity) ORDER BY p.product_name)
      FILTER (WHERE h.quantity > 0), '[]'::jsonb)
  INTO v_released_units, v_released_lines
  FROM inventory_holds h
  LEFT JOIN products p ON p.id = h.product_id
  WHERE h.source_id = p_quote_id
    AND h.is_active = true
    AND h.hold_type = 'crop_program';

  IF v_released_units > 0 THEN
    v_warnings := array_append(v_warnings,
      'Released ' || v_released_units || ' un-fulfilled unit(s) back to free inventory');
  END IF;

  -- Flip to the terminal status. This UPDATE fires:
  --   _enforce_quote_status_transition   (edge sent/revised -> closed_short added above)
  --   release_holds_on_quote_status_change (deactivates the quote's crop_program
  --     holds — the released remainder)
  --   trg_enforce_quote_terminal_not_drawn only blocks declined/cancelled/expired
  --     -> closed_short passes even for a partially-drawn booking (the whole point)
  --   enforce_quote_accepted_fully_drawn fires only for 'accepted'
  UPDATE quotes SET status = 'closed_short', updated_at = now()
  WHERE id = p_quote_id;

  -- No financial_audit_log entry: closing moves NO money (any drawn portion was
  -- billed via its order; the released remainder was never billed). Log to
  -- activity_feed only — always, even when nothing was released.
  INSERT INTO activity_feed (event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id)
  VALUES ('quote_closed_short',
    'Booking ' || v_quote.quote_number || ' closed short — customer walked away, for ' ||
      COALESCE(v_customer.farm_name, 'customer') ||
      CASE WHEN v_released_units > 0
        THEN ' (released ' || v_released_units || ' un-fulfilled unit(s))' ELSE '' END,
    v_actor, 'quote', p_quote_id, v_quote.customer_id);

  v_result := jsonb_build_object(
    'success', true,
    'status', 'closed_short',
    'quote_id', p_quote_id,
    'quote_number', v_quote.quote_number,
    'released_units', v_released_units,
    'released_lines', v_released_lines,
    'warnings', to_jsonb(v_warnings));

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'close_quote_as_short', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."close_quote_as_short"("p_quote_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commit_blend_ticket_ocr_result"("p_blend_ticket_id" "uuid", "p_queue_id" "uuid", "p_lease_token" "uuid", "p_ticket_update" "jsonb", "p_products" "jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ticket public.blend_tickets%ROWTYPE;
  v_queue public.ocr_processing_queue%ROWTYPE;
  v_existing jsonb;
  v_result jsonb;
  v_product jsonb;
  v_status text;
  v_confidence numeric;
  v_quantity numeric;
  v_product_confidence numeric;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'OCR_COMMIT_IDEMPOTENCY_REQUIRED';
  END IF;

  v_existing := public.check_idempotency(
    p_idempotency_key,
    'commit_blend_ticket_ocr_result'
  );
  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  IF jsonb_typeof(p_ticket_update) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_products) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_products) > 200 THEN
    RAISE EXCEPTION 'OCR_COMMIT_PAYLOAD_INVALID';
  END IF;

  v_status := btrim(COALESCE(p_ticket_update->>'status', ''));
  IF v_status NOT IN ('completed', 'needs_review') THEN
    RAISE EXCEPTION 'OCR_COMMIT_STATUS_INVALID';
  END IF;

  v_confidence := (p_ticket_update->>'ocr_confidence_score')::numeric;
  IF v_confidence IS NULL
     OR v_confidence::text IN ('NaN', 'Infinity', '-Infinity')
     OR v_confidence < 0 OR v_confidence > 100 THEN
    RAISE EXCEPTION 'OCR_COMMIT_CONFIDENCE_INVALID';
  END IF;

  SELECT * INTO v_ticket
    FROM public.blend_tickets
   WHERE id = p_blend_ticket_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OCR_COMMIT_TICKET_NOT_FOUND';
  END IF;

  SELECT * INTO v_queue
    FROM public.ocr_processing_queue
   WHERE id = p_queue_id
     AND blend_ticket_id = p_blend_ticket_id
   FOR UPDATE;
  IF NOT FOUND
     OR v_queue.status <> 'processing'
     OR v_queue.lease_token IS DISTINCT FROM p_lease_token THEN
    RAISE EXCEPTION 'OCR_COMMIT_LEASE_LOST';
  END IF;

  IF v_ticket.review_status <> 'unreviewed'
     OR v_ticket.order_link_status <> 'unlinked'
     OR v_ticket.payment_status <> 'unbilled' THEN
    RAISE EXCEPTION 'OCR_COMMIT_LIFECYCLE_CHANGED';
  END IF;

  IF EXISTS (
       SELECT 1 FROM public.invoices
        WHERE blend_ticket_id = p_blend_ticket_id
          AND deleted_at IS NULL
          AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
     ) OR EXISTS (
       SELECT 1 FROM public.application_records
        WHERE source_type = 'blend_ticket'
          AND source_id = p_blend_ticket_id
     ) THEN
    RAISE EXCEPTION 'OCR_COMMIT_DOWNSTREAM_RECORD_EXISTS';
  END IF;

  -- Validate the whole product payload before deleting any previous OCR rows.
  FOR v_product IN SELECT value FROM jsonb_array_elements(p_products)
  LOOP
    IF jsonb_typeof(v_product) IS DISTINCT FROM 'object'
       OR NULLIF(btrim(v_product->>'product_name'), '') IS NULL THEN
      RAISE EXCEPTION 'OCR_COMMIT_PRODUCT_INVALID';
    END IF;

    v_quantity := (v_product->>'quantity')::numeric;
    v_product_confidence := NULLIF(v_product->>'confidence_score', '')::numeric;
    IF v_quantity IS NULL
       OR v_quantity::text IN ('NaN', 'Infinity', '-Infinity')
       OR v_quantity < 0
       OR v_product_confidence::text IN ('NaN', 'Infinity', '-Infinity')
       OR v_product_confidence < 0 OR v_product_confidence > 100 THEN
      RAISE EXCEPTION 'OCR_COMMIT_PRODUCT_NUMERIC_INVALID';
    END IF;
    IF NULLIF(v_product->>'product_id', '') IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.products p
       WHERE p.id = (v_product->>'product_id')::uuid
         AND p.is_active = true
    ) THEN
      RAISE EXCEPTION 'OCR_COMMIT_PRODUCT_MATCH_INVALID';
    END IF;
  END LOOP;

  UPDATE public.blend_tickets
     SET status = v_status,
         raw_ocr_text = p_ticket_update->>'raw_ocr_text',
         ocr_confidence_score = v_confidence,
         signature_detected = COALESCE(
           (p_ticket_update->>'signature_detected')::boolean,
           false
         ),
         customer_id = CASE
           WHEN v_ticket.customer_id IS NULL
             AND NOT ('customer_id' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             AND NULLIF(p_ticket_update->>'customer_id', '') IS NOT NULL
             THEN (p_ticket_update->>'customer_id')::uuid
           ELSE v_ticket.customer_id
         END,
         ticket_date = CASE
           WHEN v_ticket.ticket_date IS NULL
             AND NOT ('ticket_date' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             AND NULLIF(p_ticket_update->>'ticket_date', '') IS NOT NULL
             THEN (p_ticket_update->>'ticket_date')::date
           ELSE v_ticket.ticket_date
         END,
         driver_name = CASE
           WHEN NULLIF(btrim(v_ticket.driver_name), '') IS NULL
             AND NOT ('driver_name' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             THEN COALESCE(NULLIF(p_ticket_update->>'driver_name', ''), v_ticket.driver_name)
           ELSE v_ticket.driver_name
         END,
         tank_number = CASE
           WHEN NULLIF(btrim(v_ticket.tank_number), '') IS NULL
             AND NOT ('tank_number' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             THEN COALESCE(NULLIF(p_ticket_update->>'tank_number', ''), v_ticket.tank_number)
           ELSE v_ticket.tank_number
         END,
         applicator_name = CASE
           WHEN NULLIF(btrim(v_ticket.applicator_name), '') IS NULL
             AND NOT ('applicator_name' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             THEN COALESCE(NULLIF(p_ticket_update->>'applicator_name', ''), v_ticket.applicator_name)
           ELSE v_ticket.applicator_name
         END,
         job_number = CASE
           WHEN NULLIF(btrim(v_ticket.job_number), '') IS NULL
             AND NOT ('job_number' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             THEN COALESCE(NULLIF(p_ticket_update->>'job_number', ''), v_ticket.job_number)
           ELSE v_ticket.job_number
         END,
         ticket_time = CASE
           WHEN v_ticket.ticket_time IS NULL
             AND NOT ('ticket_time' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             AND NULLIF(p_ticket_update->>'ticket_time', '') IS NOT NULL
             THEN p_ticket_update->>'ticket_time'
           ELSE v_ticket.ticket_time
         END,
         vehicle_info = CASE
           WHEN NULLIF(btrim(v_ticket.vehicle_info), '') IS NULL
             AND NOT ('vehicle_info' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             THEN COALESCE(NULLIF(p_ticket_update->>'vehicle_info', ''), v_ticket.vehicle_info)
           ELSE v_ticket.vehicle_info
         END,
         mixer_name = CASE
           WHEN NULLIF(btrim(v_ticket.mixer_name), '') IS NULL
             AND NOT ('mixer_name' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             THEN COALESCE(NULLIF(p_ticket_update->>'mixer_name', ''), v_ticket.mixer_name)
           ELSE v_ticket.mixer_name
         END,
         field_names = CASE
           WHEN NULLIF(btrim(v_ticket.field_names), '') IS NULL
             AND NOT ('field_names' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             THEN COALESCE(NULLIF(p_ticket_update->>'field_names', ''), v_ticket.field_names)
           ELSE v_ticket.field_names
         END,
         total_acres = CASE
           WHEN v_ticket.total_acres IS NULL
             AND NOT ('total_acres' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             AND NULLIF(p_ticket_update->>'total_acres', '') IS NOT NULL
             THEN (p_ticket_update->>'total_acres')::numeric
           ELSE v_ticket.total_acres
         END,
         application_rate = CASE
           WHEN NULLIF(btrim(v_ticket.application_rate), '') IS NULL
             AND NOT ('application_rate' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             THEN COALESCE(NULLIF(p_ticket_update->>'application_rate', ''), v_ticket.application_rate)
           ELSE v_ticket.application_rate
         END,
         total_volume = CASE
           WHEN v_ticket.total_volume IS NULL
             AND NOT ('total_volume' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             AND NULLIF(p_ticket_update->>'total_volume', '') IS NOT NULL
             THEN (p_ticket_update->>'total_volume')::numeric
           ELSE v_ticket.total_volume
         END,
         invoice_number = CASE
           WHEN NULLIF(btrim(v_ticket.invoice_number), '') IS NULL
             AND NOT ('invoice_number' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             THEN COALESCE(NULLIF(p_ticket_update->>'invoice_number', ''), v_ticket.invoice_number)
           ELSE v_ticket.invoice_number
         END,
         notes = CASE
           WHEN NULLIF(btrim(v_ticket.notes), '') IS NULL
             AND NOT ('notes' = ANY(COALESCE(v_ticket.manually_corrected_fields, '{}'::text[])))
             THEN COALESCE(NULLIF(p_ticket_update->>'notes', ''), v_ticket.notes)
           ELSE v_ticket.notes
         END,
         updated_at = now()
   WHERE id = p_blend_ticket_id;

  DELETE FROM public.blend_ticket_products
   WHERE blend_ticket_id = p_blend_ticket_id
     AND COALESCE(manually_corrected, false) = false;

  FOR v_product IN SELECT value FROM jsonb_array_elements(p_products)
  LOOP
    INSERT INTO public.blend_ticket_products (
      blend_ticket_id, product_id, product_name, quantity, unit,
      lot_number, sequence_order, confidence_score, manually_corrected
    ) VALUES (
      p_blend_ticket_id,
      NULLIF(v_product->>'product_id', '')::uuid,
      btrim(v_product->>'product_name'),
      (v_product->>'quantity')::numeric,
      NULLIF(v_product->>'unit', ''),
      NULLIF(v_product->>'lot_number', ''),
      (v_product->>'sequence_order')::integer,
      NULLIF(v_product->>'confidence_score', '')::numeric,
      false
    );
  END LOOP;

  UPDATE public.ocr_processing_queue
     SET status = 'completed',
         completed_at = now(),
         lease_token = NULL,
         lease_heartbeat_at = NULL,
         updated_at = now()
   WHERE id = p_queue_id
     AND lease_token = p_lease_token
     AND status = 'processing';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OCR_COMMIT_LEASE_LOST';
  END IF;

  v_result := jsonb_build_object(
    'success', true,
    'ticket_id', p_blend_ticket_id,
    'queue_id', p_queue_id,
    'status', v_status,
    'product_count', jsonb_array_length(p_products)
  );
  PERFORM public.save_idempotency(
    p_idempotency_key,
    'commit_blend_ticket_ocr_result',
    v_result
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."commit_blend_ticket_ocr_result"("p_blend_ticket_id" "uuid", "p_queue_id" "uuid", "p_lease_token" "uuid", "p_ticket_update" "jsonb", "p_products" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commit_label_draft"("p_draft_id" "uuid", "p_decision" "text", "p_signal_word" "text" DEFAULT NULL::"text", "p_rei_hours" integer DEFAULT NULL::integer, "p_phi_days" integer DEFAULT NULL::integer, "p_epa_registration" "text" DEFAULT NULL::"text", "p_max_label_rate" numeric DEFAULT NULL::numeric, "p_max_label_rate_unit" "text" DEFAULT NULL::"text", "p_force_overwrite" boolean DEFAULT false, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_cached   jsonb;
  v_draft    product_label_drafts%ROWTYPE;
  v_product  products%ROWTYPE;
  v_new_sw   text;
  v_new_rei  integer;
  v_new_phi  integer;
  v_new_epa  text;
  v_new_mlr  numeric;
  v_new_mlru text;
  v_skipped  text[] := '{}';
  v_applied  text[] := '{}';
  v_result   jsonb;
BEGIN
  -- Auth gate
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_user_id AND role = 'admin' AND is_active = true
  ) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: admin role required';
  END IF;

  -- Validate decision
  IF p_decision NOT IN ('accepted', 'edited', 'rejected') THEN
    RAISE EXCEPTION 'INVALID_DECISION: must be accepted, edited, or rejected';
  END IF;

  -- Idempotency
  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_cached
    FROM idempotency_keys
    WHERE idempotency_key = p_idempotency_key
      AND operation       = 'commit_label_draft';
    IF FOUND THEN
      RETURN v_cached;
    END IF;
  END IF;

  -- Load draft (with lock for safety)
  SELECT * INTO v_draft FROM product_label_drafts WHERE id = p_draft_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DRAFT_NOT_FOUND: %', p_draft_id;
  END IF;

  -- Don't re-commit already-decided drafts (unless idempotency key matched above)
  IF v_draft.status IN ('accepted', 'edited', 'rejected') THEN
    RAISE EXCEPTION 'DRAFT_ALREADY_DECIDED: draft % has status %', p_draft_id, v_draft.status;
  END IF;

  -- Load product
  SELECT * INTO v_product FROM products WHERE id = v_draft.product_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRODUCT_NOT_FOUND: %', v_draft.product_id;
  END IF;

  -- For accepted/edited: resolve which values to write
  IF p_decision IN ('accepted', 'edited') THEN
    -- Use edited override if provided, else draft value
    IF p_decision = 'edited' THEN
      v_new_sw   := p_signal_word;
      v_new_rei  := p_rei_hours;
      v_new_phi  := p_phi_days;
      v_new_epa  := p_epa_registration;
      v_new_mlr  := p_max_label_rate;
      v_new_mlru := p_max_label_rate_unit;
    ELSE
      v_new_sw   := v_draft.signal_word;
      v_new_rei  := v_draft.rei_hours;
      v_new_phi  := v_draft.phi_days;
      v_new_epa  := v_draft.epa_registration;
      v_new_mlr  := v_draft.max_label_rate;
      v_new_mlru := v_draft.max_label_rate_unit;
    END IF;

    -- Non-negativity guard on the RESOLVED values (authoritative — runs before any
    -- write to products). A negative regulatory interval/rate is a safety-impossible
    -- value and must never reach the products table, even via the 'edited' path.
    IF v_new_rei IS NOT NULL AND v_new_rei < 0 THEN
      RAISE EXCEPTION 'INVALID_LABEL_VALUE: rei_hours must be >= 0 (got %)', v_new_rei;
    END IF;
    IF v_new_phi IS NOT NULL AND v_new_phi < 0 THEN
      RAISE EXCEPTION 'INVALID_LABEL_VALUE: phi_days must be >= 0 (got %)', v_new_phi;
    END IF;
    IF v_new_mlr IS NOT NULL AND v_new_mlr < 0 THEN
      RAISE EXCEPTION 'INVALID_LABEL_VALUE: max_label_rate must be >= 0 (got %)', v_new_mlr;
    END IF;

    -- Normalize blank text to NULL so an empty string is treated as "no value" everywhere below
    -- (skip decision, empty/no-values guards, and what we store). The UI already sends '' as null,
    -- but this also covers OCR/bulk-created drafts and products carrying a blank string.
    v_new_sw   := NULLIF(btrim(v_new_sw), '');
    v_new_epa  := NULLIF(btrim(v_new_epa), '');
    v_new_mlru := NULLIF(btrim(v_new_mlru), '');

    -- Empty-decision guard: an accept/edit with NO resolved values is a no-op that
    -- would mark the draft 'decided' while writing nothing. Reject it so a value-less
    -- draft (e.g. a fresh "New Draft" or a needs_manual row) can't leave the queue
    -- without the admin actually entering values first.
    IF v_new_sw IS NULL AND v_new_rei IS NULL AND v_new_phi IS NULL
       AND v_new_epa IS NULL AND v_new_mlr IS NULL AND v_new_mlru IS NULL THEN
      RAISE EXCEPTION 'NO_VALUES_TO_APPLY: % decision has no values to write — enter values before accepting', p_decision;
    END IF;

    -- No-overwrite guard: if product field is non-empty and p_force_overwrite=false → skip that field
    -- signal_word
    IF v_new_sw IS NOT NULL THEN
      IF NULLIF(btrim(v_product.signal_word), '') IS NULL OR p_force_overwrite THEN
        v_applied := array_append(v_applied, 'signal_word');
      ELSE
        v_skipped := array_append(v_skipped, 'signal_word');
        v_new_sw  := v_product.signal_word; -- keep existing
      END IF;
    END IF;
    -- rei_hours
    IF v_new_rei IS NOT NULL THEN
      IF v_product.rei_hours IS NULL OR p_force_overwrite THEN
        v_applied := array_append(v_applied, 'rei_hours');
      ELSE
        v_skipped := array_append(v_skipped, 'rei_hours');
        v_new_rei := v_product.rei_hours;
      END IF;
    END IF;
    -- phi_days
    IF v_new_phi IS NOT NULL THEN
      IF v_product.phi_days IS NULL OR p_force_overwrite THEN
        v_applied := array_append(v_applied, 'phi_days');
      ELSE
        v_skipped := array_append(v_skipped, 'phi_days');
        v_new_phi := v_product.phi_days;
      END IF;
    END IF;
    -- epa_registration
    IF v_new_epa IS NOT NULL THEN
      IF NULLIF(btrim(v_product.epa_registration), '') IS NULL OR p_force_overwrite THEN
        v_applied := array_append(v_applied, 'epa_registration');
      ELSE
        v_skipped := array_append(v_skipped, 'epa_registration');
        v_new_epa := v_product.epa_registration;
      END IF;
    END IF;
    -- max_label_rate + max_label_rate_unit (ATOMIC PAIR — only ever written TOGETHER, from ONE source.
    -- A one-sided draft (rate without unit, or unit without rate) is never partially applied, so a new
    -- unit can never glue onto an old rate (or vice versa), even under force-overwrite.)
    IF v_new_mlr IS NOT NULL OR v_new_mlru IS NOT NULL THEN
      IF v_new_mlr IS NOT NULL AND v_new_mlru IS NOT NULL
         AND ((v_product.max_label_rate IS NULL AND v_product.max_label_rate_unit IS NULL) OR p_force_overwrite) THEN
        -- both sides present AND (target pair empty OR explicit force): apply the pair together
        v_applied := array_append(v_applied, 'max_label_rate');
        v_applied := array_append(v_applied, 'max_label_rate_unit');
      ELSE
        -- one-sided draft, OR target pair non-empty without force: skip the pair, keep the existing pair intact
        IF v_new_mlr  IS NOT NULL THEN v_skipped := array_append(v_skipped, 'max_label_rate'); END IF;
        IF v_new_mlru IS NOT NULL THEN v_skipped := array_append(v_skipped, 'max_label_rate_unit'); END IF;
        v_new_mlr  := v_product.max_label_rate;       -- revert BOTH to existing so the stored pair stays consistent
        v_new_mlru := v_product.max_label_rate_unit;
      END IF;
    END IF;

    -- Nothing was actually applied (every proposed field was skipped as already-filled, or only a
    -- one-sided max-rate pair was supplied) -> reject so the draft is NOT closed without writing anything.
    -- (The earlier empty-decision guard catches a value-less draft; this catches a draft that HAD values
    -- but where all of them ended up skipped — e.g. a lone rate without a unit.)
    IF array_length(v_applied, 1) IS NULL THEN
      RAISE EXCEPTION 'NO_VALUES_TO_APPLY: nothing was applied (all proposed fields were skipped as already-filled, or formed a one-sided max-rate pair) — nothing to accept';
    END IF;

    -- Write to products
    UPDATE products
    SET
      signal_word         = COALESCE(v_new_sw,   signal_word),
      rei_hours           = COALESCE(v_new_rei,  rei_hours),
      phi_days            = COALESCE(v_new_phi,  phi_days),
      epa_registration    = COALESCE(v_new_epa,  epa_registration),
      max_label_rate      = COALESCE(v_new_mlr,  max_label_rate),
      max_label_rate_unit = COALESCE(v_new_mlru, max_label_rate_unit),
      updated_at          = now()
    WHERE id = v_draft.product_id;
  END IF;

  -- Mark draft as decided. For accept/edit store the FINAL resolved values (v_new_*) that reflect what
  -- the product actually holds now (applied fields = the written value; skipped fields = the existing
  -- product value) — NEVER the raw proposed edits, so the queue can't display a value as saved when it
  -- was actually skipped. For 'rejected', leave the drafted values untouched.
  UPDATE product_label_drafts
  SET status      = p_decision,
      reviewed_by  = v_user_id,
      reviewed_at  = now(),
      signal_word          = CASE WHEN p_decision = 'rejected' THEN signal_word         ELSE v_new_sw   END,
      rei_hours            = CASE WHEN p_decision = 'rejected' THEN rei_hours            ELSE v_new_rei  END,
      phi_days             = CASE WHEN p_decision = 'rejected' THEN phi_days             ELSE v_new_phi  END,
      epa_registration     = CASE WHEN p_decision = 'rejected' THEN epa_registration     ELSE v_new_epa  END,
      max_label_rate       = CASE WHEN p_decision = 'rejected' THEN max_label_rate       ELSE v_new_mlr  END,
      max_label_rate_unit  = CASE WHEN p_decision = 'rejected' THEN max_label_rate_unit  ELSE v_new_mlru END
  WHERE id = p_draft_id;

  v_result := jsonb_build_object(
    'draft_id',   p_draft_id,
    'product_id', v_draft.product_id,
    'decision',   p_decision,
    'applied',    to_jsonb(v_applied),
    'skipped',    to_jsonb(v_skipped)
  );

  -- Store idempotency
  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'commit_label_draft', v_result)
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."commit_label_draft"("p_draft_id" "uuid", "p_decision" "text", "p_signal_word" "text", "p_rei_hours" integer, "p_phi_days" integer, "p_epa_registration" "text", "p_max_label_rate" numeric, "p_max_label_rate_unit" "text", "p_force_overwrite" boolean, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_cycle_count"("p_cycle_count_id" "uuid", "p_completed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_completed_by IS NOT NULL AND p_completed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'complete_cycle_count');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;
  PERFORM 1 FROM public.cycle_counts WHERE id = p_cycle_count_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CYCLE_COUNT_NOT_FOUND'; END IF;
  PERFORM 1
  FROM public.inventory i
  JOIN public.cycle_count_items cci ON cci.inventory_id = i.id
  WHERE cci.cycle_count_id = p_cycle_count_id
  ORDER BY i.id
  FOR UPDATE OF i;
  PERFORM public._complete_cycle_count_impl(p_cycle_count_id, v_actor, p_idempotency_key);
END;
$$;


ALTER FUNCTION "public"."complete_cycle_count"("p_cycle_count_id" "uuid", "p_completed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_delivery"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_quantities" "jsonb" DEFAULT NULL::"jsonb", "p_issue_type" "text" DEFAULT NULL::"text", "p_issue_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_completed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_role text;
  v_delivery record;
  v_existing jsonb;
  v_effective_completion_date date;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;

  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT id, assigned_driver
    INTO v_delivery
    FROM public.deliveries
   WHERE id = p_delivery_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Delivery not found: %', p_delivery_id;
  END IF;

  SELECT role
    INTO v_actor_role
    FROM public.profiles
   WHERE id = v_actor
     AND is_active = true;

  IF v_actor_role IS NULL OR NOT (
    v_actor_role IN ('admin', 'sales_rep')
    OR (v_actor_role = 'driver' AND v_actor = v_delivery.assigned_driver)
  ) THEN
    RAISE EXCEPTION 'Not authorized to complete this delivery';
  END IF;

  -- Preserve committed replay even if the historical business date has since
  -- moved into a closed period. No mutation occurs on this branch.
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(
      p_idempotency_key,
      'complete_delivery'
    );
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  v_effective_completion_date := COALESCE(
    (p_completed_at AT TIME ZONE 'America/Chicago')::date,
    (now() AT TIME ZONE 'America/Chicago')::date
  );

  PERFORM public.check_period_open(v_effective_completion_date);

  RETURN public._complete_delivery_period_preflight_impl(
    p_delivery_id,
    p_signed_by,
    p_performed_by,
    p_quantities,
    p_issue_type,
    p_issue_notes,
    p_idempotency_key,
    p_completed_at
  );
END;
$$;


ALTER FUNCTION "public"."complete_delivery"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid", "p_quantities" "jsonb", "p_issue_type" "text", "p_issue_notes" "text", "p_idempotency_key" "text", "p_completed_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_delivery"("p_delivery_id" "uuid", "p_signed_by" "text", "p_performed_by" "uuid", "p_quantities" "jsonb", "p_issue_type" "text", "p_issue_notes" "text", "p_idempotency_key" "text", "p_completed_at" timestamp with time zone) IS 'Completes a delivery after active authorization, replay lookup, and side-effect-free accounting-period preflight.';



CREATE OR REPLACE FUNCTION "public"."complete_job"("p_job_id" "uuid", "p_applied_info" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor          uuid := auth.uid();
  v_existing       jsonb;
  v_job            record;
  v_record_number  text;
  v_record_id      uuid;
  v_product_data   jsonb;
  v_weather        jsonb;
  v_chem           record;
  v_inv            record;
  v_inv_found      boolean;
  v_jf             record;
  v_first_field_id uuid;
  v_field_count    int := 0;
  v_short_count    int := 0;
  v_new_avail      numeric;
  v_short_flag     boolean;
  v_result         jsonb;
  v_deduct_qty     numeric;
  -- U11<<< raw-fallback bookkeeping for unconvertible units
  v_unconverted    boolean;
  v_unconv_count   int := 0;
  -- >>>U11
  -- U12 (Codex R2 P2): running sum of the per-field acres actually recorded, so
  -- the record header can be corrected when the caller sent 'field_acres' overrides.
  v_acres_sum      numeric := 0;
  v_auto_draft_on    boolean := false;
  v_existing_invoice uuid;
  v_auto_draft_key   text;
  -- N2-7 #106a/#106b<<< actual application date + applicator snapshot locals.
  v_application_date date;
  v_applicator_id      uuid;
  v_applicator_name    text;
  v_applicator_license text;
  -- >>>N2-7
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key AND operation = 'complete_job';
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT j.*, c.farm_name AS customer_name
    INTO v_job
    FROM jobs j
    JOIN customers c ON c.id = j.customer_id
   WHERE j.id = p_job_id
   FOR UPDATE OF j;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found: %', p_job_id;
  END IF;

  -- U12: widened with an OR branch — but NARROWER than start_job's (Codex R1 P1,
  -- tightened again R2 P1): complete_job stamps application records + acres for
  -- EVERY field and deducts inventory for EVERY chemical on the job, so a
  -- location-only dispatchee may complete it ONLY when BOTH hold:
  --   (1) EVERY job_fields row on the job is covered by an ACTIVE dispatch owned
  --       by the caller (directly, or via active membership in the dispatched
  --       crew) — an undispatched field means someone's work isn't even assigned
  --       yet, so the whole-job close stays with the office / whole-job assignee;
  --   (2) no OTHER party holds an ACTIVE dispatch anywhere on the job.
  -- On any split/partial-dispatch job this branch stays closed — admin/sales_rep
  -- or jobs.applicator_id complete those, exactly as before this migration.
  -- Still a strict superset of live behavior.
  IF NOT (
    is_admin() OR is_sales_rep()
    -- NULL-SAFE (U12 live-verify finding): when jobs.applicator_id IS NULL this
    -- comparison yielded NULL, and IF NOT (NULL) skips the RAISE — any active
    -- applicator could start/complete a NULL-applicator job. Wrap it so the
    -- branch is FALSE, not NULL, and authorization falls through to the
    -- dispatch-based branch (which is already null-safe).
    OR (is_applicator() AND v_job.applicator_id IS NOT NULL AND v_job.applicator_id = v_actor)
    OR (
      is_applicator()
      AND public._is_dispatched_to_me(p_job_id)
      -- (1) every field on the job is actively dispatched to the caller.
      -- Crew ownership requires BOTH the membership row AND the crew itself to
      -- be active (RLS R2 M2) — matching _is_dispatched_to_me and the
      -- job_location_dispatches_select policy, so the completion power is never
      -- looser than the read power.
      AND NOT EXISTS (
        SELECT 1
          FROM job_fields jf2
         WHERE jf2.job_id = p_job_id
           AND NOT EXISTS (
             SELECT 1
               FROM job_location_dispatches d2
              WHERE d2.job_field_id = jf2.id
                AND d2.dispatch_status = 'dispatched'
                AND (
                  d2.applicator_id = v_actor
                  OR (d2.crew_id IS NOT NULL AND EXISTS (
                        SELECT 1
                          FROM ground_crew_members gcm
                          JOIN ground_crews gc ON gc.id = gcm.crew_id
                         WHERE gcm.crew_id = d2.crew_id
                           AND gcm.profile_id = v_actor
                           AND gcm.is_active
                           AND gc.is_active))
                )
           )
      )
      -- (2) and nobody ELSE holds an active dispatch on the job. The applicator
      -- comparison is wrapped null-safe (RLS R2 M1): on a crew-held dispatch
      -- d.applicator_id IS NULL, and `NULL = v_actor` would poison the NOT()
      -- into NULL and silently drop the row from the EXISTS.
      AND NOT EXISTS (
        SELECT 1
          FROM job_location_dispatches d
         WHERE d.job_id = p_job_id
           AND d.dispatch_status = 'dispatched'
           AND NOT (
             (d.applicator_id IS NOT NULL AND d.applicator_id = v_actor)
             OR (d.crew_id IS NOT NULL AND EXISTS (
                   SELECT 1
                     FROM ground_crew_members gcm
                     JOIN ground_crews gc ON gc.id = gcm.crew_id
                    WHERE gcm.crew_id = d.crew_id
                      AND gcm.profile_id = v_actor
                      AND gcm.is_active
                      AND gc.is_active))
           )
      )
    )
  ) THEN
    RAISE EXCEPTION 'Not authorized to complete this job';
  END IF;

  IF v_job.status != 'in_progress' THEN
    RAISE EXCEPTION 'Job must be in_progress before completion. Current status: %. Use start_job() first.', v_job.status;
  END IF;

  -- Fires A4's jobs lifecycle trigger → _sync_job_holds releases this job's hold
  -- and re-syncs the parent quote (keeping the draw). The quote hold / booking is
  -- owned by A4 from here; the loop below only deducts physical stock.
  UPDATE jobs SET status = 'completed' WHERE id = p_job_id;

  INSERT INTO job_applied_info (
    job_id, actual_start_time, actual_end_time,
    wind_speed, wind_direction, temperature, humidity,
    actual_gallons_applied, notes
  ) VALUES (
    p_job_id,
    CASE WHEN p_applied_info->>'actual_start_time' IS NOT NULL
      THEN (p_applied_info->>'actual_start_time')::timestamptz ELSE NULL END,
    CASE WHEN p_applied_info->>'actual_end_time' IS NOT NULL
      THEN (p_applied_info->>'actual_end_time')::timestamptz ELSE NULL END,
    (p_applied_info->>'wind_speed')::numeric,
    p_applied_info->>'wind_direction',
    (p_applied_info->>'temperature')::numeric,
    (p_applied_info->>'humidity')::numeric,
    (p_applied_info->>'actual_gallons_applied')::numeric,
    p_applied_info->>'notes'
  )
  ON CONFLICT (job_id) DO UPDATE SET
    actual_start_time      = COALESCE(EXCLUDED.actual_start_time,      job_applied_info.actual_start_time),
    actual_end_time        = EXCLUDED.actual_end_time,
    wind_speed             = EXCLUDED.wind_speed,
    wind_direction         = EXCLUDED.wind_direction,
    temperature            = EXCLUDED.temperature,
    humidity               = EXCLUDED.humidity,
    actual_gallons_applied = EXCLUDED.actual_gallons_applied,
    notes                  = EXCLUDED.notes;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'product_id',       jc.product_id,
        'product_name',     p.product_name,
        'quantity',         jc.quantity,
        'unit',             jc.unit,
        'rate_per_acre',    jc.rate_per_acre,
        'rate_unit',        jc.rate_unit,
        'epa_registration', p.epa_registration,
        'is_rup',           COALESCE(p.is_rup, false),
        -- U4<<< legal record marks a grower-supplied product; the row STAYS in
        -- product_data (REI/PHI watchdog + as-applied proof still see it). (#53/#54)
        'customer_supplied', jc.customer_supplied
        -- >>>U4
      )
      ORDER BY jc.sort_order
    ),
    '[]'::jsonb
  )
  INTO v_product_data
  FROM job_chemicals jc
  LEFT JOIN products p ON p.id = jc.product_id
  WHERE jc.job_id = p_job_id;

  v_weather := jsonb_build_object(
    'wind_speed',     (p_applied_info->>'wind_speed')::numeric,
    'wind_direction', p_applied_info->>'wind_direction',
    'temperature',    (p_applied_info->>'temperature')::numeric,
    'humidity',       (p_applied_info->>'humidity')::numeric
  );

  v_record_number := next_application_record_number();

  SELECT field_id INTO v_first_field_id
    FROM job_fields
   WHERE job_id = p_job_id
   ORDER BY sort_order, id
   LIMIT 1;

  -- N2-7 #106a<<< the ACTUAL application date. The job_applied_info upsert above already
  -- merged the completer-sent start with the start_job-stamped start
  -- (COALESCE(EXCLUDED.actual_start_time, existing)), so that row's actual_start_time is
  -- the single source of truth for "when it was actually applied". Prefer the just-sent
  -- value, then the stored start, then fall back to v_job.job_date EXACTLY as before this
  -- migration when no actual start exists anywhere (byte-identical to old behavior).
  -- Codex R1 P2: cast through the BUSINESS timezone, not the session default
  -- (UTC on Supabase) — a 7:30 PM Central start is still "today" on the legal
  -- record, not tomorrow. CRX operates in US Central only (single-region ag
  -- retailer); if that ever changes this becomes an app_settings value.
  v_application_date := COALESCE(
    (
      COALESCE(
        (p_applied_info->>'actual_start_time')::timestamptz,
        (SELECT jai.actual_start_time FROM job_applied_info jai WHERE jai.job_id = p_job_id)
      ) AT TIME ZONE 'America/Chicago'
    )::date,
    v_job.job_date
  );
  -- >>>N2-7 #106a

  -- N2-7 #106b<<< snapshot the applicator's identity as-of NOW onto the legal record.
  -- Same applicator the record is attributed to (below): the completer when they're an
  -- applicator, else the job-header applicator (which may be NULL for wizard-dispatched
  -- jobs → both snapshot columns stay NULL, additive-safe).
  v_applicator_id := CASE WHEN is_applicator() THEN v_actor ELSE v_job.applicator_id END;
  IF v_applicator_id IS NOT NULL THEN
    SELECT pr.full_name, pr.applicator_license_number
      INTO v_applicator_name, v_applicator_license
      FROM profiles pr WHERE pr.id = v_applicator_id;
    -- Codex R1 P2: applicator_licenses is the CANONICAL license store for staff
    -- (the assignment gate + UI read it); profiles.applicator_license_number is
    -- not maintained by the current frontend. Prefer the newest active canonical
    -- license; keep the profiles value only as a fallback for shops that typed
    -- it there.
    SELECT COALESCE(
             (SELECT al.license_number
                FROM applicator_licenses al
               WHERE al.profile_id = v_applicator_id
                 AND al.is_active = true
               ORDER BY al.expiry_date DESC NULLS LAST
               LIMIT 1),
             v_applicator_license
           )
      INTO v_applicator_license;
  END IF;
  -- >>>N2-7 #106b

  INSERT INTO application_records (
    record_number, source_type, source_id,
    customer_id, applicator_id, field_id,
    application_date, product_data,
    total_acres, total_volume, total_volume_unit,
    vehicle_id, weather_conditions,
    notes, season, created_by,
    -- N2-7 #106b: legal-record applicator snapshot columns.
    applicator_name, applicator_license_number
  ) VALUES (
    v_record_number, 'job', p_job_id,
    v_job.customer_id,
    -- U12 (Codex R2 P1): attribute the legal application record to the person who
    -- ACTUALLY completed it when that person is an applicator — the new location-
    -- dispatch path means the completer may not be jobs.applicator_id (which can
    -- even be NULL for wizard-dispatched jobs). For the whole-job assignee this is
    -- the same value as before (v_actor = v_job.applicator_id); for office closes
    -- (admin/sales_rep) keep the job-header applicator exactly as today.
    -- N2-7: this is exactly v_applicator_id (computed above from the same CASE), so
    -- applicator_id is byte-identical to live; reusing the local keeps it in lockstep
    -- with the name/license snapshot.
    v_applicator_id,
    v_first_field_id,
    -- N2-7 #106a: actual application date (was v_job.job_date).
    v_application_date, v_product_data,
    v_job.total_acres,
    (p_applied_info->>'actual_gallons_applied')::numeric,
    'gallons',
    v_job.vehicle_id, v_weather, v_job.notes, v_job.season,
    p_performed_by,
    -- N2-7 #106b: applicator identity snapshot.
    v_applicator_name, v_applicator_license
  )
  RETURNING id INTO v_record_id;

  FOR v_jf IN
    SELECT jf.field_id,
           -- U12 addition: an optional per-field override from
           -- p_applied_info->'field_acres' = [{"field_id":uuid,"acres_applied":n}, ...].
           -- Falls through to the ORIGINAL chain when absent/no match — byte-identical
           -- to the pre-U12 behavior for every caller that doesn't pass it.
           COALESCE(
             (SELECT GREATEST(0, (elem->>'acres_applied')::numeric)
                FROM jsonb_array_elements(COALESCE(p_applied_info->'field_acres', '[]'::jsonb)) elem
               WHERE nullif(elem->>'field_id', '')::uuid = jf.field_id
               LIMIT 1),
             jf.acres_to_treat, f.total_acres, 0
           ) AS acres,
           COALESCE(jf.sort_order, 0)                    AS sort_order
      FROM job_fields jf
      JOIN fields f ON f.id = jf.field_id
     WHERE jf.job_id = p_job_id
     ORDER BY jf.sort_order, jf.id
  LOOP
    INSERT INTO application_record_fields (application_record_id, field_id, acres, sort_order)
    VALUES (v_record_id, v_jf.field_id, v_jf.acres, v_jf.sort_order);
    v_field_count := v_field_count + 1;
    v_acres_sum   := v_acres_sum + COALESCE(v_jf.acres, 0);
  END LOOP;

  -- U12 (Codex R2 P2): when the caller sent per-field applied-acres overrides,
  -- the record HEADER must reflect what was actually recorded, not the planned
  -- job total — reports read application_records.total_acres. Only corrected
  -- when 'field_acres' was provided: callers that omit it keep today's header
  -- value byte-for-byte (v_job.total_acres), preserving backward compatibility.
  IF p_applied_info ? 'field_acres' AND v_field_count > 0 THEN
    UPDATE application_records
       SET total_acres = v_acres_sum
     WHERE id = v_record_id;
  END IF;

  FOR v_chem IN
    SELECT jc.product_id, jc.quantity, jc.unit, p.inventory_unit AS inv_unit, p.product_form AS prod_form
      FROM job_chemicals jc
      JOIN products p ON p.id = jc.product_id
     -- U4<<< skip customer-supplied lines: they came from the grower, not our
     -- shed — no stock to deduct, no 'job_applied' inventory transaction. (#53/#54)
     WHERE jc.job_id = p_job_id AND jc.quantity > 0 AND jc.customer_supplied = false
     -- >>>U4
  LOOP
    -- U11<<< convert the rate-unit job-chem quantity to the product's inventory unit
    -- before deducting stock (a 16-pt line on a gallons-stocked product must remove 2
    -- gal, not 16). On an unconvertible / blank / unknown unit, DO NOT block the field
    -- job (a stuck applicator can't ship the day's work): fall back to the RAW quantity
    -- and flag the row for office review. This mirrors the hold engine EXACTLY —
    -- _sync_job_holds reserved COALESCE(field_app_priced_quantity(...), jc.quantity)
    -- inventory-units for this same line, so deducting the same fallback keeps the
    -- "reserved X → removed X" invariant intact (was: A6 hard RAISE JOB_INV_UNIT_UNCONVERTIBLE,
    -- which blocked completion of ANY job carrying an unconvertible unit).
    -- Codex P1: normalize FIRST — legacy rows may carry per-acre-suffixed units
    -- ('pt/ac'); the raw string NULLs out of the converter and would raw-deduct
    -- 16 "pt/ac" as 16 gal. normalize_rate_unit('pt/ac')='pt' → converts to 2 gal.
    -- (The hold engines share this normalization gap — queued as a follow-up;
    -- correcting the PHYSICAL deduction takes precedence over symmetry.)
    v_deduct_qty  := field_app_priced_quantity(v_chem.quantity, normalize_rate_unit(v_chem.unit), v_chem.inv_unit, v_chem.prod_form);
    v_unconverted := (v_deduct_qty IS NULL);
    IF v_unconverted THEN
      v_deduct_qty   := v_chem.quantity;      -- raw fallback, equals the reserved hold
      v_unconv_count := v_unconv_count + 1;
    END IF;
    -- >>>U11

    SELECT * INTO v_inv
      FROM inventory
     WHERE product_id = v_chem.product_id AND location = 'Main Warehouse'
     FOR UPDATE;
    v_inv_found := FOUND;

    v_new_avail  := COALESCE(v_inv.quantity_available, 0) - v_deduct_qty;
    v_short_flag := v_new_avail < 0;
    IF v_short_flag THEN
      v_short_count := v_short_count + 1;
    END IF;

    -- LAYER2<<< §3.5 fix: deduct physical stock ONLY. The parent quote's holds
    -- and prebooked are owned by A4's jobs lifecycle trigger (which already fired
    -- on the status='completed' update above). The removed "Phase 7" drain
    -- (v_hold_qty / v_decrement_pb / prebooked decrement / crop_program FIFO
    -- drain) double-reduced free stock for order-drawn planned quotes.
    IF NOT v_inv_found THEN
      INSERT INTO inventory (product_id, location, quantity_available, quantity_prebooked, quantity_on_order)
      VALUES (v_chem.product_id, 'Main Warehouse', -v_deduct_qty, 0, 0);
    ELSE
      UPDATE inventory SET
        quantity_available = quantity_available - v_deduct_qty,
        updated_at         = now()
      WHERE product_id = v_chem.product_id AND location = 'Main Warehouse';
    END IF;
    -- >>>LAYER2

    INSERT INTO inventory_transactions (
      product_id, transaction_type, quantity, from_location,
      performed_by, notes, job_id, requires_review
    ) VALUES (
      v_chem.product_id, 'job_applied', v_deduct_qty, 'Main Warehouse',
      p_performed_by,
      -- U11<<< recorded qty ALWAYS = what stock moved (converted, or raw fallback). Name
      -- the original line qty/unit when a conversion (or a raw fallback) happened, so the
      -- audit row is self-explaining and reconcilable (mirrors A5's link/audit-row lesson).
      'Job ' || v_job.job_number || ' completed — ' || v_deduct_qty || ' units applied' ||
        CASE
          WHEN v_unconverted
            THEN ' [UNIT NOT CONVERTIBLE — line ' || v_chem.quantity || ' ' || COALESCE(NULLIF(v_chem.unit, ''), '?')
                 || ' recorded raw vs inventory unit ' || COALESCE(NULLIF(v_chem.inv_unit, ''), '?') || '; review required]'
          WHEN lower(btrim(COALESCE(v_chem.unit, ''))) IS DISTINCT FROM lower(btrim(COALESCE(v_chem.inv_unit, '')))
            THEN ' (converted from ' || v_chem.quantity || ' ' || COALESCE(NULLIF(v_chem.unit, ''), '?') || ')'
          ELSE ''
        END ||
        CASE WHEN v_short_flag THEN ' [SHORT STOCK — review required]' ELSE '' END,
      p_job_id,
      (v_short_flag OR v_unconverted)
      -- >>>U11
    );
  END LOOP;

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'job_completed',
    'Job ' || v_job.job_number || ' completed across ' || v_field_count || ' field(s). Application record: ' || v_record_number ||
      CASE WHEN v_short_count > 0
           THEN ' (⚠ ' || v_short_count || ' short-stock chemical(s) — review required)'
           ELSE '' END ||
      -- U11<<< surface raw-fallback lines to the office the same way short-stock is surfaced
      CASE WHEN v_unconv_count > 0
           THEN ' (⚠ ' || v_unconv_count || ' chemical(s) with non-convertible units — recorded raw, review required)'
           ELSE '' END,
      -- >>>U11
    p_performed_by, 'job', p_job_id, v_job.customer_id
  );

  v_result := jsonb_build_object(
    'success',                true,
    'job_id',                 p_job_id,
    'application_record_id',  v_record_id,
    'record_number',          v_record_number,
    'field_count',            v_field_count,
    'short_stock_count',      v_short_count
  );

  BEGIN
    SELECT (setting_value = 'true')
      INTO v_auto_draft_on
      FROM app_settings
     WHERE setting_key = 'auto_draft_invoice_on_job_completion';
    v_auto_draft_on := COALESCE(v_auto_draft_on, false);

    IF v_auto_draft_on AND (is_admin() OR is_sales_rep()) THEN
      SELECT i.id INTO v_existing_invoice
        FROM invoices i
       WHERE i.job_id = p_job_id
         AND i.deleted_at IS NULL
         AND i.status NOT IN ('voided', 'cancelled')
       LIMIT 1;

      IF v_existing_invoice IS NULL THEN
        v_auto_draft_key := 'auto_draft_job:' || p_job_id::text;
        PERFORM transfer_job_to_invoice(p_job_id, p_performed_by, v_auto_draft_key);
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      INSERT INTO activity_feed (
        event_type, description, performed_by,
        related_entity_type, related_entity_id, customer_id
      ) VALUES (
        'auto_draft_failed',
        'Job ' || v_job.job_number || ' completed, but the automatic draft invoice could '
          || 'not be created (needs attention — bill it manually). Reason: ' || SQLERRM,
        p_performed_by, 'job', p_job_id, v_job.customer_id
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END;

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'complete_job', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."complete_job"("p_job_id" "uuid", "p_applied_info" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_job"("p_job_id" "uuid", "p_applied_info" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Marks a field job completed (application record, inventory decrement, hold drain). Beyond-parity §4: when app_settings.auto_draft_invoice_on_job_completion = ''true'', also auto-creates a DRAFT (never posted) field-app invoice via transfer_job_to_invoice — idempotent (skips if a non-voided invoice already exists for the job) and fail-soft (a draft failure never blocks completion; logs auto_draft_failed instead).';



CREATE OR REPLACE FUNCTION "public"."compute_application_service_fee"("p_service_id" "uuid", "p_customer_id" "uuid", "p_acres" numeric, "p_season" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_service  record;
  v_override bigint;
  v_rate     bigint;
  v_source   text;
  v_total    bigint;
  v_season   int;
BEGIN
  IF p_service_id IS NULL OR p_acres IS NULL OR p_acres <= 0 THEN
    RETURN jsonb_build_object(
      'rate_per_acre_cents', 0,
      'total_fee_cents',     0,
      'cost_per_acre_cents', 0,
      'total_cost_cents',    0,
      'source',              'none',
      'service_name',        NULL
    );
  END IF;

  SELECT * INTO v_service FROM application_services WHERE id = p_service_id;
  IF NOT FOUND OR NOT v_service.is_active THEN
    RETURN jsonb_build_object(
      'rate_per_acre_cents', 0,
      'total_fee_cents',     0,
      'cost_per_acre_cents', 0,
      'total_cost_cents',    0,
      'source',              'inactive',
      'service_name',        v_service.name
    );
  END IF;

  v_season := COALESCE(p_season, current_season());
  v_override := NULL;

  IF p_customer_id IS NOT NULL THEN
    SELECT car.rate_per_acre_cents INTO v_override
      FROM customer_application_rates car
     WHERE car.customer_id            = p_customer_id
       AND car.application_service_id = p_service_id
       AND car.season                 = v_season
     LIMIT 1;
  END IF;

  IF v_override IS NOT NULL THEN
    v_rate   := v_override;
    v_source := 'customer_override';
  ELSE
    v_rate   := COALESCE(v_service.default_rate_per_acre_cents, 0);
    v_source := 'service_default';
  END IF;

  v_total := ROUND(v_rate * p_acres)::bigint;

  RETURN jsonb_build_object(
    'rate_per_acre_cents', v_rate,
    'total_fee_cents',     v_total,
    'cost_per_acre_cents', COALESCE(v_service.cost_per_acre_cents, 0),
    'total_cost_cents',    ROUND(COALESCE(v_service.cost_per_acre_cents, 0) * p_acres)::bigint,
    'source',              v_source,
    'service_name',        v_service.name
  );
END;
$$;


ALTER FUNCTION "public"."compute_application_service_fee"("p_service_id" "uuid", "p_customer_id" "uuid", "p_acres" numeric, "p_season" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_application_service_fee"("p_service_id" "uuid", "p_customer_id" "uuid", "p_acres" numeric, "p_season" integer) IS 'Phase 4 (2026-04-30): single source of truth for application service fee math.';



CREATE OR REPLACE FUNCTION "public"."compute_commission_amount"("p_profit" numeric, "p_percentage" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT GREATEST(ROUND(COALESCE(p_profit, 0) * COALESCE(p_percentage, 0) / 100, 2), 0);
$$;


ALTER FUNCTION "public"."compute_commission_amount"("p_profit" numeric, "p_percentage" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_fuel_surcharge_cents"("p_acres" numeric, "p_subtotal_cents" bigint) RETURNS bigint
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cfg       jsonb;
  v_enabled   boolean;
  v_basis     text;
  v_rate_text text;
  v_rate      numeric;
BEGIN
  -- MED 2: the read + ::jsonb cast is wrapped so a MALFORMED, non-JSON value in
  -- the admin-editable (CHECK-less) app_settings.fuel_surcharge row behaves as if
  -- the feature were disabled (returns 0) instead of throwing and aborting EVERY
  -- field-app invoice save/preview. Contract: malformed config → return 0.
  BEGIN
    SELECT setting_value::jsonb INTO v_cfg
      FROM app_settings WHERE setting_key = 'fuel_surcharge';
  EXCEPTION WHEN others THEN
    RETURN 0;
  END;

  -- No config row, or malformed → behave exactly as if the feature did not exist.
  IF v_cfg IS NULL THEN RETURN 0; END IF;

  v_enabled := COALESCE((v_cfg->>'enabled')::boolean, false);
  IF NOT v_enabled THEN RETURN 0; END IF;     -- OFF (the shipped default) → no surcharge.

  v_basis     := COALESCE(v_cfg->>'basis', '');
  v_rate_text := NULLIF(TRIM(COALESCE(v_cfg->>'rate', '')), '');
  IF v_rate_text IS NULL THEN RETURN 0; END IF;  -- BLANK rate → no surcharge (even if "enabled").

  -- Parse the owner's number defensively; a non-numeric value yields no surcharge
  -- rather than an error that would block saving an invoice.
  BEGIN
    v_rate := v_rate_text::numeric;
  EXCEPTION WHEN others THEN
    RETURN 0;
  END;

  IF v_rate IS NULL OR v_rate <= 0 THEN RETURN 0; END IF;  -- non-positive → no surcharge.

  -- All math in exact numeric, ROUND to whole cents, cast to bigint. No float.
  IF v_basis = 'per_acre' THEN
    -- rate is DOLLARS/acre → cents/acre = rate*100; × acres.
    IF p_acres IS NULL OR p_acres <= 0 THEN RETURN 0; END IF;
    RETURN ROUND(v_rate * 100 * p_acres)::bigint;
  ELSIF v_basis = 'percent' THEN
    -- rate is a percentage of the customer subtotal.
    IF p_subtotal_cents IS NULL OR p_subtotal_cents <= 0 THEN RETURN 0; END IF;
    RETURN ROUND(p_subtotal_cents::numeric * v_rate / 100)::bigint;
  ELSIF v_basis = 'flat' THEN
    -- rate is a flat DOLLARS amount per customer invoice → cents.
    RETURN ROUND(v_rate * 100)::bigint;
  ELSE
    -- Unknown/blank basis → no surcharge (owner hasn't finished configuring).
    RETURN 0;
  END IF;
END;
$$;


ALTER FUNCTION "public"."compute_fuel_surcharge_cents"("p_acres" numeric, "p_subtotal_cents" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_fuel_surcharge_cents"("p_acres" numeric, "p_subtotal_cents" bigint) IS 'Field-app parity #32: pure bigint-cents fuel-surcharge amount from app_settings.fuel_surcharge. Returns 0 unless enabled=true AND a positive owner-entered rate is set (OFF/blank by default = 0). Never invents a rate. basis per_acre/flat = dollars, percent = percent of subtotal.';



CREATE OR REPLACE FUNCTION "public"."compute_season"("p_date" "date") RETURNS integer
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE WHEN extract(month FROM p_date) >= 10
    THEN extract(year FROM p_date)::integer + 1
    ELSE extract(year FROM p_date)::integer END;
$$;


ALTER FUNCTION "public"."compute_season"("p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_delivery"("p_delivery_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_delivery record;
  v_actor uuid;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'confirm_delivery');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_delivery FROM deliveries WHERE id = p_delivery_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found'; END IF;

  IF v_delivery.status != 'scheduled' THEN
    RAISE EXCEPTION 'Delivery must be in scheduled status to start. Current status: %', v_delivery.status;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = v_actor AND is_active = true
      AND (
        role IN ('admin', 'sales_rep')
        OR (role = 'driver' AND v_actor = v_delivery.assigned_driver)
      )
  ) THEN
    RAISE EXCEPTION 'Not authorized to start this delivery';
  END IF;

  UPDATE deliveries SET status = 'in_progress', updated_at = now() WHERE id = p_delivery_id;

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('delivery_confirmed',
    'Delivery ' || v_delivery.delivery_number || ' confirmed and started',
    v_actor, 'delivery', p_delivery_id, v_delivery.customer_id);

  IF v_delivery.assigned_driver IS NOT NULL AND v_actor != v_delivery.assigned_driver THEN
    INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
    VALUES (
      v_delivery.assigned_driver,
      'Delivery Started',
      'Delivery ' || v_delivery.delivery_number || ' has been started and is ready for completion.',
      'delivery_update', 'delivery', p_delivery_id
    );
  END IF;

  v_result := jsonb_build_object('status', 'confirmed', 'delivery_id', p_delivery_id);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'confirm_delivery', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."confirm_delivery"("p_delivery_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_job_notification_sent"("p_notification_id" "uuid", "p_subject" "text" DEFAULT NULL::"text", "p_message" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_role     text;
  v_existing jsonb;
  v_status   text;
  v_result   jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales_rep required';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'confirm_job_notification_sent');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT status INTO v_status FROM job_notifications WHERE id = p_notification_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOTIFICATION_NOT_FOUND: % does not exist', p_notification_id;
  END IF;

  -- Only a row that actually HAS a recipient email is confirmable (a no-email row
  -- stays 'failed'); confirming an already-'sent' row is an idempotent no-op. When
  -- the caller passes the per-recipient rendered subject/message, store THAT exact
  -- text (so the audit row matches the email), else keep what was recorded.
  IF v_status <> 'sent' THEN
    UPDATE job_notifications
       SET status  = 'sent',
           sent_at = now(),
           subject = COALESCE(p_subject, subject),
           message = COALESCE(p_message, message)
     WHERE id = p_notification_id
       AND recipient_email IS NOT NULL;
  END IF;

  v_result := jsonb_build_object('success', true, 'notification_id', p_notification_id);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'confirm_job_notification_sent', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."confirm_job_notification_sent"("p_notification_id" "uuid", "p_subject" "text", "p_message" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."confirm_job_notification_sent"("p_notification_id" "uuid", "p_subject" "text", "p_message" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Field-app #40: flips a job_notifications row from failed to sent after the outbound email succeeds, storing the exact per-recipient subject/message sent. SECURITY DEFINER; admin/sales_rep only; idempotent.';



CREATE OR REPLACE FUNCTION "public"."consolidate_draft_invoices"("p_order_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor      uuid;
  v_cached     jsonb;
  v_order      record;
  v_source_ids uuid[];
  v_others     uuid[];
  v_survivor   uuid;
  v_total      bigint;
  v_merged     int;
  v_result     jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  SELECT * INTO v_order FROM orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF;

  -- Lock + collect the order's draft invoices FOR THE ORDER'S OWN CUSTOMER only
  -- (oldest first — created_at then invoice_number → deterministic survivor).
  -- Codex P1: create_split_invoices_from_order makes same-order drafts for
  -- DIFFERENT customers (field-billing splits); scoping to v_order.customer_id
  -- guarantees we never merge one customer's lines onto another's invoice (which
  -- would bill the wrong farm and cancel the others' invoices). Split-customer
  -- drafts are intentionally left untouched.
  PERFORM 1 FROM invoices
    WHERE order_id = p_order_id AND status = 'draft' AND customer_id = v_order.customer_id FOR UPDATE;

  -- Codex round-11-class hardening: idempotency check AFTER the draft FOR UPDATE (TOCTOU).
  -- A pre-lock check_idempotency let two same-key calls both miss the cache; the lock
  -- serializes them, so the 2nd resumes here after the 1st committed and returns the 1st
  -- call's saved result instead of re-evaluating (which would report 'fewer than 2 drafts'
  -- after the 1st already merged). Canonical post-lock pattern (draw_down_quote 20260610181726).
  IF p_idempotency_key IS NOT NULL THEN
    v_cached := check_idempotency(p_idempotency_key, 'consolidate_draft_invoices');
    IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
  END IF;

  SELECT array_agg(id ORDER BY created_at, invoice_number) INTO v_source_ids
    FROM invoices
    WHERE order_id = p_order_id AND status = 'draft' AND customer_id = v_order.customer_id;

  IF v_source_ids IS NULL OR array_length(v_source_ids, 1) < 2 THEN
    -- 0 or 1 draft — nothing to merge. Idempotent no-op.
    v_result := jsonb_build_object('success', true, 'consolidated', false,
      'reason', 'fewer than 2 draft invoices', 'order_number', v_order.order_number);
    IF p_idempotency_key IS NOT NULL THEN
      PERFORM save_idempotency(p_idempotency_key, 'consolidate_draft_invoices', v_result);
    END IF;
    RETURN v_result;
  END IF;

  v_survivor := v_source_ids[1];
  v_others   := v_source_ids[2:array_length(v_source_ids, 1)];
  v_merged   := array_length(v_others, 1);

  -- Move every other draft's items onto the survivor.
  UPDATE invoice_items SET invoice_id = v_survivor
   WHERE invoice_id = ANY(v_others);

  -- Recompute BOTH money columns of the survivor from its now-merged items
  -- (Codex P1: total_cost_cents was left at the original delivery's cost →
  -- overstated gross profit. total_cost_cents = SUM(cost_cents * quantity), the
  -- create_invoice_from_delivery convention; cost_cents is per-unit).
  SELECT COALESCE(sum(extended_cents), 0) INTO v_total
    FROM invoice_items WHERE invoice_id = v_survivor;
  UPDATE invoices SET
    total_amount_cents = v_total,
    total_cost_cents   = COALESCE((SELECT round(sum(cost_cents * quantity))::bigint FROM invoice_items WHERE invoice_id = v_survivor), 0),
    updated_at         = now()
   WHERE id = v_survivor;

  -- Cancel the now-empty source drafts AND zero their money columns (Codex P2:
  -- after moving all items to the survivor, the sources keep their original
  -- total_amount_cents/total_cost_cents — and balance_cents is GENERATED from
  -- total_amount_cents, so a cancelled, item-less invoice would still report a
  -- nonzero total/balance and could be double-counted by any consumer that
  -- doesn't exclude cancelled rows). Zero both stored columns; balance_cents
  -- (GENERATED) follows total_amount_cents → 0. draft→cancelled is allowed by the
  -- enforcer; never posted, so period + financial_audit_log are untouched.
  UPDATE invoices SET
    status = 'cancelled',
    total_amount_cents = 0,
    total_cost_cents = 0,
    updated_at = now()
   WHERE id = ANY(v_others);

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('invoices_consolidated',
    'Consolidated ' || (v_merged + 1) || ' draft invoice(s) into one for order ' || v_order.order_number,
    v_actor, 'invoice', v_survivor, v_order.customer_id);

  v_result := jsonb_build_object(
    'success', true, 'consolidated', true,
    'surviving_invoice_id', v_survivor, 'merged_count', v_merged,
    'total_cents', v_total, 'order_number', v_order.order_number
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'consolidate_draft_invoices', v_result);
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."consolidate_draft_invoices"("p_order_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_quote_to_order"("p_quote_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid; v_actor_role text;
  v_quote record; v_order_number text; v_order_id uuid; v_item record;
  v_customer record; v_inv record; v_shortfalls text[] := '{}'; v_net_position numeric;
  v_result jsonb; v_existing jsonb;
  v_has_draws boolean; v_fully_drawn boolean;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_actor_role
  FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'convert_quote_to_order');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found'; END IF;

  -- Draws guard FIRST and status-independent (2026-06-10 BLOCKER fix): the UI
  -- may have pre-flipped status to 'accepted' before calling this RPC, so the
  -- guard can never key off status. A booking with an undrawn balance is
  -- never whole-convertible; a fully-drawn booking is never re-bookable.
  SELECT EXISTS (
    SELECT 1 FROM quote_product_draws
    WHERE quote_id = p_quote_id AND quantity_drawn > 0
  )
  -- LAYER2<<< job reservations count as draws too (§6.5): a job that reserved
  -- booking units makes this a partially-drawn booking — whole conversion would
  -- re-order units a job already holds/bills.
  OR EXISTS (
    SELECT 1 FROM job_product_draws
    WHERE quote_id = p_quote_id AND quantity_drawn > 0
  )
  -- >>>LAYER2
  INTO v_has_draws;
  IF v_has_draws THEN
    -- ORDER draws only (see header): job draws never satisfy 'fully drawn'.
    SELECT COALESCE(bool_and(COALESCE(d.quantity_drawn, 0) >= b.booked), true) INTO v_fully_drawn
    FROM (
      SELECT product_id, SUM(COALESCE(total_units_needed, 0)) AS booked
      FROM quote_items WHERE quote_id = p_quote_id
      GROUP BY product_id
    ) b
    LEFT JOIN quote_product_draws d
      ON d.quote_id = p_quote_id AND d.product_id = b.product_id
    WHERE b.booked > 0;
    IF NOT v_fully_drawn THEN
      RAISE EXCEPTION 'BOOKING_PARTIALLY_DRAWN: this quote has partial draw-downs — draw the remaining balance from the booking instead';
    END IF;
    -- Fully ORDER-drawn: every booked unit is already on an order. Surface the
    -- most recent draw order; never create another.
    SELECT id INTO v_order_id FROM orders WHERE quote_id = p_quote_id LIMIT 1;
    -- LAYER2<<< defensive (Codex): the order-only fully-drawn check is vacuously
    -- TRUE when the booked-rows set is empty (e.g. a job-drawn product was
    -- dropped from quote_items). Never return a null-order 'already_converted'
    -- the caller force-uses (result.order_id!) — treat as an unresolved booking.
    IF v_order_id IS NULL THEN
      RAISE EXCEPTION 'BOOKING_PARTIALLY_DRAWN: this booking has no order to convert (reservations exist) — review the booking''s jobs and draws';
    END IF;
    -- >>>LAYER2
    v_result := jsonb_build_object('status', 'already_converted', 'order_id', v_order_id);
    IF p_idempotency_key IS NOT NULL THEN
      PERFORM save_idempotency(p_idempotency_key, 'convert_quote_to_order', v_result);
    END IF;
    RETURN v_result;
  END IF;

  IF v_quote.status = 'accepted' THEN
    SELECT id INTO v_order_id FROM orders WHERE quote_id = p_quote_id LIMIT 1;
    IF v_order_id IS NOT NULL THEN
      v_result := jsonb_build_object('status', 'already_converted', 'order_id', v_order_id);
      IF p_idempotency_key IS NOT NULL THEN
        PERFORM save_idempotency(p_idempotency_key, 'convert_quote_to_order', v_result);
      END IF;
      RETURN v_result;
    END IF;
  END IF;

  IF v_quote.status NOT IN ('sent', 'revised', 'accepted') THEN
    RAISE EXCEPTION 'BOOKING_CLOSED: cannot convert a % quote', v_quote.status;
  END IF;

  SELECT * INTO v_customer FROM customers WHERE id = v_quote.customer_id;

  FOR v_item IN
    SELECT qi.product_id, p.product_name, SUM(COALESCE(qi.total_units_needed, 0)) AS qty_needed
    FROM quote_items qi JOIN products p ON p.id = qi.product_id
    WHERE qi.quote_id = p_quote_id AND qi.product_id IS NOT NULL
      AND COALESCE(qi.total_units_needed, 0) > 0
    GROUP BY qi.product_id, p.product_name
  LOOP
    SELECT * INTO v_inv FROM inventory
    WHERE product_id = v_item.product_id AND location = 'Main Warehouse' FOR UPDATE;
    IF NOT FOUND THEN
      v_shortfalls := array_append(v_shortfalls,
        v_item.product_name || ': need ' || v_item.qty_needed || ', net position is 0 (no inventory record)');
    ELSE
      v_net_position := v_inv.quantity_available - v_inv.quantity_prebooked + COALESCE(v_inv.quantity_on_order, 0);
      IF v_net_position < v_item.qty_needed THEN
        v_shortfalls := array_append(v_shortfalls,
          v_item.product_name || ': need ' || v_item.qty_needed ||
          ', net position is ' || GREATEST(v_net_position, 0) ||
          ' (on floor: ' || (v_inv.quantity_available - v_inv.quantity_prebooked) ||
          ', on order: ' || COALESCE(v_inv.quantity_on_order, 0) || ')');
      END IF;
    END IF;
  END LOOP;

  SET LOCAL app.admin_override = 'true';
  UPDATE quotes SET status = 'accepted', updated_at = now() WHERE id = p_quote_id;
  UPDATE inventory_holds SET is_active = false, updated_at = now()
  WHERE source_id = p_quote_id AND is_active = true;

  v_order_number := generate_order_number();

  INSERT INTO orders (order_number, quote_id, customer_id, status, commission_split,
    total_price, total_cost, total_profit, total_margin_pct, order_date, program_notes)
  VALUES (v_order_number, p_quote_id, v_quote.customer_id, 'confirmed',
    v_quote.commission_split, v_quote.total_price, v_quote.total_cost,
    v_quote.total_profit, v_quote.total_margin_pct, current_date,
    (SELECT string_agg(qs.section_name || ': ' || qs.section_header_notes, E'\n')
     FROM quote_sections qs WHERE qs.quote_id = p_quote_id
       AND qs.section_header_notes IS NOT NULL AND qs.section_header_notes <> ''))
  RETURNING id INTO v_order_id;

  INSERT INTO order_items (order_id, product_id, quote_item_id, section_name, product_name,
    price_per_unit, cost_per_unit, actual_rate, rate_unit, acres,
    total_units_needed, unit_size, total_price, profit, net_margin,
    quantity_delivered, quantity_remaining, notes)
  SELECT v_order_id, qi.product_id, qi.id, qs.section_name, p.product_name,
    qi.price_per_unit, qi.current_cost, qi.actual_rate, qi.rate_unit, qi.acres,
    COALESCE(qi.total_units_needed, 0), qi.unit_size,
    qi.total_price, qi.profit, qi.net_margin,
    0, COALESCE(qi.total_units_needed, 0), qi.notes
  FROM quote_items qi
  JOIN quote_sections qs ON qs.id = qi.section_id
  JOIN products p ON p.id = qi.product_id
  WHERE qi.quote_id = p_quote_id AND qi.product_id IS NOT NULL;

  INSERT INTO quote_product_draws (quote_id, product_id, quantity_drawn)
  SELECT qi.quote_id, qi.product_id, SUM(COALESCE(qi.total_units_needed, 0))
  FROM quote_items qi
  WHERE qi.quote_id = p_quote_id AND qi.product_id IS NOT NULL
  GROUP BY qi.quote_id, qi.product_id
  HAVING SUM(COALESCE(qi.total_units_needed, 0)) > 0
  ON CONFLICT (quote_id, product_id)
  DO UPDATE SET quantity_drawn = EXCLUDED.quantity_drawn, updated_at = now();

  FOR v_item IN
    SELECT oi.product_id, oi.total_units_needed, oi.unit_size FROM order_items oi
    WHERE oi.order_id = v_order_id AND oi.product_id IS NOT NULL AND oi.total_units_needed > 0
  LOOP
    UPDATE inventory SET quantity_prebooked = quantity_prebooked + v_item.total_units_needed,
      updated_at = now()
    WHERE product_id = v_item.product_id AND location = 'Main Warehouse';
    IF NOT FOUND THEN
      INSERT INTO inventory (product_id, location, quantity_available, quantity_prebooked, quantity_on_order, unit_size)
      VALUES (v_item.product_id, 'Main Warehouse', 0, v_item.total_units_needed, 0, v_item.unit_size);
    END IF;
    INSERT INTO inventory_transactions (product_id, transaction_type, quantity, to_location,
      order_id, performed_by, notes)
    VALUES (v_item.product_id, 'booked', v_item.total_units_needed, 'Main Warehouse',
      v_order_id, v_actor, 'Pre-booked for order ' || v_order_number);
  END LOOP;

  PERFORM _insert_commissions_for_order(
    v_order_id, v_quote.customer_id, v_quote.total_profit,
    v_quote.commission_split, current_date
  );

  INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_role, new_values, total_impact_cents, description)
  VALUES (
    'quote_converted', 'order', v_order_id, v_actor_role,
    jsonb_build_object(
      'quote_id', p_quote_id,
      'quote_number', v_quote.quote_number,
      'order_number', v_order_number,
      'customer_id', v_quote.customer_id,
      'customer_name', COALESCE(v_customer.farm_name, 'unknown'),
      'total_price_dollars', v_quote.total_price,
      'inventory_warnings', to_jsonb(v_shortfalls)
    ),
    ROUND(v_quote.total_price * 100)::bigint,
    'Converted quote ' || v_quote.quote_number || ' to order ' || v_order_number ||
      ' for ' || COALESCE(v_customer.farm_name, 'customer') ||
      CASE WHEN array_length(v_shortfalls, 1) > 0
        THEN ' (inventory shortfalls: ' || array_to_string(v_shortfalls, '; ') || ')'
        ELSE '' END
  );

  INSERT INTO activity_feed (event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id)
  VALUES ('order_created',
    'Order ' || v_order_number || ' created from quote ' || v_quote.quote_number ||
    ' for ' || COALESCE(v_customer.farm_name, 'customer') ||
    CASE WHEN array_length(v_shortfalls, 1) > 0
      THEN ' (inventory warnings: ' || array_to_string(v_shortfalls, '; ') || ')'
      ELSE '' END,
    v_actor, 'order', v_order_id, v_quote.customer_id);

  v_result := jsonb_build_object('status', 'created', 'order_id', v_order_id,
    'order_number', v_order_number, 'warnings', to_jsonb(v_shortfalls));

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'convert_quote_to_order', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."convert_quote_to_order"("p_quote_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_to_gl_lb"("p_total_applied" numeric, "p_rate_unit" "text", "p_product_form" "text") RETURNS TABLE("converted_value" numeric, "converted_unit" "text")
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_total_applied IS NULL OR p_rate_unit IS NULL THEN
    RETURN QUERY SELECT NULL::numeric, NULL::text;
    RETURN;
  END IF;

  IF p_product_form = 'dry' THEN
    CASE upper(p_rate_unit)
      WHEN 'OZ', 'OUNCE', 'OUNCES' THEN converted_value := p_total_applied / 16.0; converted_unit := 'LB';
      WHEN 'LB', 'LBS', 'POUND', 'POUNDS' THEN converted_value := p_total_applied;  converted_unit := 'LB';
      WHEN 'TON', 'TONS' THEN converted_value := p_total_applied * 2000.0;          converted_unit := 'LB';
      ELSE converted_value := NULL; converted_unit := NULL;
    END CASE;
  ELSE
    CASE upper(p_rate_unit)
      WHEN 'OZ', 'FL OZ', 'FLOZ', 'FLUID OUNCE' THEN converted_value := p_total_applied / 128.0; converted_unit := 'GL';
      WHEN 'PT', 'PINT', 'PINTS' THEN converted_value := p_total_applied / 8.0;   converted_unit := 'GL';
      WHEN 'QT', 'QUART', 'QUARTS' THEN converted_value := p_total_applied / 4.0;   converted_unit := 'GL';
      WHEN 'GL', 'GAL', 'GALLON', 'GALLONS' THEN converted_value := p_total_applied; converted_unit := 'GL';
      ELSE converted_value := NULL; converted_unit := NULL;
    END CASE;
  END IF;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."convert_to_gl_lb"("p_total_applied" numeric, "p_rate_unit" "text", "p_product_form" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."convert_to_gl_lb"("p_total_applied" numeric, "p_rate_unit" "text", "p_product_form" "text") IS 'Field-app gal/lb equivalent for tank planning (display only). Liquid: OZ=q/128, PT=q/8, QT=q/4, GL/GAL/GALLON/GALLONS=q. Dry: OZ=q/16, LB=q. An unrecognized unit returns NULL value+unit (UI shows a dash) — never a guessed number. Matches src/lib/chemCalculator.ts toGallonOrLbEquivalent.';



CREATE OR REPLACE FUNCTION "public"."correct_supplier_price_observation"("p_observation_id" "uuid", "p_corrected_cost" "text", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_request_fp text;
  v_reason text;
  v_cost_cents bigint;
  v_original public.supplier_price_observations%ROWTYPE;
  v_import_id uuid;
  v_row_id uuid;
  v_observation_id uuid;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;
  v_reason := NULLIF(btrim(COALESCE(p_reason, '')), '');
  IF v_reason IS NULL THEN RAISE EXCEPTION 'CORRECTION_REASON_REQUIRED'; END IF;

  -- Single dollars->cents boundary, reusing the same parser the staging path uses.
  BEGIN
    v_cost_cents := public._parse_pricing_dollars(btrim(COALESCE(p_corrected_cost, '')));
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'CORRECTION_COST_INVALID';
  END;
  IF v_cost_cents IS NULL OR v_cost_cents <= 0 THEN
    RAISE EXCEPTION 'CORRECTION_COST_MUST_BE_POSITIVE';
  END IF;

  v_request_fp := md5(jsonb_build_object(
    'actor_id', v_actor,
    'observation_id', p_observation_id,
    'cost_cents', v_cost_cents,
    'reason', v_reason
  )::text);
  v_existing := public.check_idempotency(p_idempotency_key, 'correct_supplier_price_observation');
  IF v_existing IS NOT NULL THEN
    IF v_existing->>'actor_id' IS DISTINCT FROM v_actor::text
       OR v_existing->>'request_fingerprint' IS DISTINCT FROM v_request_fp THEN
      RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH';
    END IF;
    RETURN v_existing->'response';
  END IF;

  SELECT * INTO v_original
  FROM public.supplier_price_observations
  WHERE id = p_observation_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'SUPPLIER_OBSERVATION_NOT_FOUND'; END IF;

  -- Only the current observation is correctable; a re-correction extends the chain.
  IF EXISTS (
    SELECT 1
    FROM public.supplier_price_observations correction
    WHERE correction.supersedes_observation_id = v_original.id
  ) THEN
    RAISE EXCEPTION 'SUPPLIER_OBSERVATION_ALREADY_SUPERSEDED';
  END IF;

  IF v_cost_cents = v_original.cost_cents THEN
    RAISE EXCEPTION 'CORRECTION_MUST_CHANGE_COST';
  END IF;

  INSERT INTO public.supplier_price_imports(
    vendor_id, document_date, ingestion_method, format_version, status,
    request_fingerprint, idempotency_key, row_count, eligible_row_count,
    approved_observation_count, created_by, approved_by, approved_at
  ) VALUES (
    v_original.vendor_id, current_date, 'quick_quote',
    'crx-supplier-correction-phase1b-v1', 'approved',
    v_request_fp, 'correction:' || p_idempotency_key, 1, 1, 1,
    v_actor, v_actor, now()
  ) RETURNING id INTO v_import_id;

  -- Row first (not yet approved: the approved-shape CHECK needs observation_id, which
  -- only exists after the observation is inserted below).
  INSERT INTO public.supplier_price_import_rows(
    import_id, row_number, submitted_row,
    product_id, vendor_id, product_supplier_link_id,
    supplier_sku, supplier_product_name,
    cost_cents, price_unit, package_quantity,
    effective_from, effective_to, price_kind,
    row_status, validation_errors
  ) VALUES (
    v_import_id, 1,
    jsonb_build_object(
      'correction_of_observation_id', v_original.id,
      'reason', v_reason,
      'new_cost', public._format_pricing_dollars(v_cost_cents),
      'prior_cost', public._format_pricing_dollars(v_original.cost_cents)
    ),
    v_original.product_id, v_original.vendor_id, v_original.product_supplier_link_id,
    NULL, NULL,
    v_cost_cents, v_original.price_unit, v_original.package_quantity,
    v_original.effective_from, v_original.effective_to, v_original.price_kind,
    'changed', ARRAY[]::text[]
  ) RETURNING id INTO v_row_id;

  -- Superseding observation. The validate/no-cycle trigger confirms the product,
  -- vendor, and link all match the original before the row is written.
  INSERT INTO public.supplier_price_observations(
    product_id, vendor_id, product_supplier_link_id,
    import_id, import_row_id,
    price_kind, cost_cents, price_unit, package_quantity,
    effective_from, effective_to, observed_at,
    supersedes_observation_id, created_by
  ) VALUES (
    v_original.product_id, v_original.vendor_id, v_original.product_supplier_link_id,
    v_import_id, v_row_id,
    v_original.price_kind, v_cost_cents, v_original.price_unit, v_original.package_quantity,
    v_original.effective_from, v_original.effective_to, now(),
    v_original.id, v_actor
  ) RETURNING id INTO v_observation_id;

  UPDATE public.supplier_price_import_rows
  SET row_status = 'approved',
      reviewed_by = v_actor,
      reviewed_at = now(),
      reviewer_note = v_reason,
      observation_id = v_observation_id
  WHERE id = v_row_id;

  SELECT jsonb_build_object(
    'observation_id', o.id,
    'supersedes_observation_id', o.supersedes_observation_id,
    'product_id', o.product_id,
    'vendor_id', o.vendor_id,
    'product_supplier_link_id', o.product_supplier_link_id,
    'cost_cents', o.cost_cents,
    'price_unit', o.price_unit,
    'package_quantity', o.package_quantity,
    'price_kind', o.price_kind,
    'effective_from', o.effective_from,
    'effective_to', o.effective_to,
    'import_id', o.import_id,
    'import_row_id', o.import_row_id,
    'reason', v_reason,
    'sell_prices_changed', 0,
    'summary', format(
      'Correction recorded. The prior quote is superseded and no sell price changed. New supplier cost: $%s.',
      public._format_pricing_dollars(o.cost_cents)
    )
  ) INTO v_result
  FROM public.supplier_price_observations o
  WHERE o.id = v_observation_id;

  PERFORM public.save_idempotency(
    p_idempotency_key,
    'correct_supplier_price_observation',
    jsonb_build_object(
      'actor_id', v_actor,
      'request_fingerprint', v_request_fp,
      'response', v_result
    )
  );
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."correct_supplier_price_observation"("p_observation_id" "uuid", "p_corrected_cost" "text", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_application_record_from_blend_ticket"("p_blend_ticket_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor          uuid := auth.uid();
  v_existing       jsonb;
  v_ticket         record;
  v_product_data   jsonb;
  v_season         integer;
  v_bt_product     record;
  v_field          record;
  v_record_id      uuid;
  v_record_ids     uuid[] := '{}';
  v_record_number  text;
  v_applicator_id  uuid;
  v_inv            record;
  v_inv_found      boolean;
  v_new_avail      numeric;
  v_short_flag     boolean;
  v_short_count    int := 0;
  v_field_count    int := 0;
  v_first_field_id uuid;
  v_app_time       time;
  -- A5: quantity converted to the product's inventory unit for the stock deduction
  v_deduct_qty     numeric;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales role required to create application records from blend tickets';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key
        AND operation = 'create_app_record_from_bt';
    IF v_existing IS NOT NULL THEN
      RETURN ARRAY(SELECT jsonb_array_elements_text(v_existing))::uuid[];
    END IF;
  END IF;

  SELECT bt.* INTO v_ticket FROM blend_tickets bt WHERE bt.id = p_blend_ticket_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Blend ticket not found: %', p_blend_ticket_id; END IF;
  IF v_ticket.review_status != 'approved' THEN
    RAISE EXCEPTION 'Blend ticket must be approved. Current status: %', v_ticket.review_status;
  END IF;

  IF EXISTS (
    SELECT 1 FROM application_records
    WHERE source_type = 'blend_ticket' AND source_id = p_blend_ticket_id
  ) THEN
    RAISE EXCEPTION 'Application record(s) already exist for this blend ticket';
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'product_id', btp.product_id, 'product_name', btp.product_name,
        'quantity', btp.quantity, 'unit', btp.unit,
        'rate_per_acre', btp.rate_per_acre, 'rate_unit', btp.rate_per_acre_unit,
        'epa_registration', p.epa_registration, 'is_rup', COALESCE(p.is_rup, false)
      ) ORDER BY btp.sequence_order
    ), '[]'::jsonb
  ) INTO v_product_data
  FROM blend_ticket_products btp
  LEFT JOIN products p ON p.id = btp.product_id
  WHERE btp.blend_ticket_id = p_blend_ticket_id;

  v_season := CASE
    WHEN EXTRACT(MONTH FROM COALESCE(v_ticket.ticket_date, v_ticket.upload_date)::date) >= 10
    THEN EXTRACT(YEAR FROM COALESCE(v_ticket.ticket_date, v_ticket.upload_date)::date) + 1
    ELSE EXTRACT(YEAR FROM COALESCE(v_ticket.ticket_date, v_ticket.upload_date)::date)
  END;

  BEGIN
    v_app_time := NULLIF(btrim(v_ticket.ticket_time), '')::time;
  EXCEPTION WHEN OTHERS THEN
    v_app_time := NULL;
  END;

  v_applicator_id := v_ticket.applicator_id;
  IF v_applicator_id IS NULL AND v_ticket.applicator_name IS NOT NULL THEN
    SELECT id INTO v_applicator_id FROM profiles
    WHERE full_name = v_ticket.applicator_name AND role = 'applicator' LIMIT 1;
  END IF;

  SELECT btf.field_id INTO v_first_field_id
    FROM blend_ticket_fields btf
   WHERE btf.blend_ticket_id = p_blend_ticket_id
   ORDER BY btf.sort_order
   LIMIT 1;

  v_record_number := next_application_record_number();
  INSERT INTO application_records (
    record_number, source_type, source_id, customer_id, applicator_id, field_id,
    application_date, application_time, product_data, total_acres,
    total_volume, total_volume_unit, weather_conditions, notes, season, created_by
  ) VALUES (
    v_record_number, 'blend_ticket', p_blend_ticket_id,
    v_ticket.customer_id, v_applicator_id, COALESCE(v_first_field_id, v_ticket.field_id),
    COALESCE(v_ticket.ticket_date, v_ticket.upload_date)::date, v_app_time,
    v_product_data, v_ticket.total_acres,
    v_ticket.total_volume, v_ticket.total_volume_unit, NULL, v_ticket.notes, v_season, p_performed_by
  ) RETURNING id INTO v_record_id;
  v_record_ids := v_record_ids || v_record_id;

  -- B1 lot propagation (ADDED): auto-fill application_record_lots from the blend ticket's
  -- per-product lot numbers so blend-sourced applications carry lots with no re-typing.
  -- Skips null product_id and blank lot_number; dedupes identical (product_id, lot_number)
  -- component rows; source_receiving_record_id stays NULL (these came from the blend, not a
  -- receiving record). Filtering keeps this insert from ever rolling back the whole RPC.
  INSERT INTO application_record_lots (application_record_id, product_id, lot_number, created_by)
  SELECT v_record_id, d.product_id, d.lot_number, p_performed_by
  FROM (
    SELECT DISTINCT ON (btp.product_id, lower(btrim(btp.lot_number)))
           btp.product_id, btrim(btp.lot_number) AS lot_number
    FROM blend_ticket_products btp
    WHERE btp.blend_ticket_id = p_blend_ticket_id
      AND btp.product_id IS NOT NULL
      AND btp.lot_number IS NOT NULL
      AND btrim(btp.lot_number) <> ''
    ORDER BY btp.product_id, lower(btrim(btp.lot_number))
  ) d;

  FOR v_field IN
    SELECT btf.field_id,
           COALESCE(btf.actual_acres, btf.planned_acres, f.total_acres, 0) AS acres,
           COALESCE(btf.sort_order, 0) AS sort_order
    FROM blend_ticket_fields btf
    LEFT JOIN fields f ON f.id = btf.field_id
    WHERE btf.blend_ticket_id = p_blend_ticket_id ORDER BY btf.sort_order
  LOOP
    INSERT INTO application_record_fields (application_record_id, field_id, acres, sort_order)
    VALUES (v_record_id, v_field.field_id, v_field.acres, v_field.sort_order);
    v_field_count := v_field_count + 1;
  END LOOP;

  FOR v_bt_product IN
    -- A5: join products for the inventory unit + form so the deduction converts.
    SELECT btp.product_id, btp.quantity, btp.unit AS qty_unit, btp.product_name,
           p.inventory_unit, p.unit_size, p.product_form
      FROM blend_ticket_products btp
      LEFT JOIN products p ON p.id = btp.product_id
    WHERE btp.blend_ticket_id = p_blend_ticket_id AND btp.product_id IS NOT NULL AND btp.quantity > 0
  LOOP
    -- A5: deduct in the product's inventory unit. The blend line quantity may be in a
    -- different unit (e.g. pints on a gallons-stocked product) — deducting the raw
    -- number corrupts stock by the unit ratio (the complete_job bug class).
    IF v_bt_product.inventory_unit IS NULL AND v_bt_product.unit_size IS NULL THEN
      RAISE EXCEPTION 'BLEND_TICKET_UNIT_UNCONVERTIBLE: product % (id %) has inventory_unit and unit_size unset',
        v_bt_product.product_name, v_bt_product.product_id;
    ELSE
      v_deduct_qty := field_app_priced_quantity(
                        v_bt_product.quantity,
                        normalize_rate_unit(NULLIF(btrim(v_bt_product.qty_unit), '')),
                        normalize_rate_unit(COALESCE(NULLIF(btrim(v_bt_product.inventory_unit), ''), v_bt_product.unit_size)),
                        v_bt_product.product_form);
      IF v_deduct_qty IS NULL THEN
        RAISE EXCEPTION 'BLEND_TICKET_UNIT_UNCONVERTIBLE: product % quantity unit "%" cannot convert to inventory unit "%"',
          v_bt_product.product_name, v_bt_product.qty_unit, COALESCE(v_bt_product.inventory_unit, v_bt_product.unit_size);
      END IF;
    END IF;

    SELECT * INTO v_inv
      FROM inventory
     WHERE product_id = v_bt_product.product_id AND location = 'Main Warehouse'
     FOR UPDATE;
    v_inv_found := FOUND;

    v_new_avail  := COALESCE(v_inv.quantity_available, 0) - v_deduct_qty;
    v_short_flag := v_new_avail < 0;
    IF v_short_flag THEN
      v_short_count := v_short_count + 1;
    END IF;

    IF NOT v_inv_found THEN
      INSERT INTO inventory (product_id, location, quantity_available, quantity_prebooked, quantity_on_order)
      VALUES (v_bt_product.product_id, 'Main Warehouse', -v_deduct_qty, 0, 0);
    ELSE
      UPDATE inventory
      SET quantity_available = quantity_available - v_deduct_qty,
          updated_at         = now()
      WHERE product_id = v_bt_product.product_id AND location = 'Main Warehouse';
    END IF;

    INSERT INTO inventory_transactions (
      product_id, transaction_type, quantity, from_location,
      performed_by, notes, requires_review
    ) VALUES (
      v_bt_product.product_id, 'job_applied', v_deduct_qty, 'Main Warehouse',
      p_performed_by,
      'Blend ticket application: ' || v_ticket.ticket_number ||
        ' (application record ' || v_record_id::text || ')' ||
        CASE WHEN v_short_flag THEN ' [SHORT STOCK — review required]' ELSE '' END,
      v_short_flag
    );
  END LOOP;

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'application_record_created',
    'Application record ' || v_record_number || ' created from blend ticket ' || v_ticket.ticket_number ||
      ' (' || v_field_count || ' field(s))' ||
      CASE WHEN v_short_count > 0
           THEN ' (⚠ ' || v_short_count || ' short-stock chemical(s) — review required)'
           ELSE '' END,
    p_performed_by, 'blend_ticket', p_blend_ticket_id, v_ticket.customer_id
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'create_app_record_from_bt', to_jsonb(v_record_ids));
  END IF;

  RETURN v_record_ids;
END;
$$;


ALTER FUNCTION "public"."create_application_record_from_blend_ticket"("p_blend_ticket_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_blend_ticket"("p_ticket_id" "uuid", "p_ticket_payload" "jsonb", "p_products" "jsonb" DEFAULT '[]'::"jsonb", "p_images" "jsonb" DEFAULT '[]'::"jsonb", "p_enqueue_ocr" boolean DEFAULT false, "p_performed_by" "uuid" DEFAULT "auth"."uid"(), "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_ticket_number text;
  v_customer_id uuid;
  v_existing jsonb;
  v_result jsonb;
  v_image_count integer;
  v_product jsonb;
  v_image jsonb;
  v_ordinality bigint;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: active admin or sales role required';
  END IF;
  IF p_ticket_id IS NULL THEN
    RAISE EXCEPTION 'BLEND_TICKET_ID_REQUIRED';
  END IF;
  IF jsonb_typeof(COALESCE(p_ticket_payload, '{}'::jsonb)) <> 'object'
     OR jsonb_typeof(COALESCE(p_products, '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(COALESCE(p_images, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'BLEND_TICKET_PAYLOAD_INVALID';
  END IF;
  IF jsonb_array_length(COALESCE(p_products, '[]'::jsonb)) > 200 THEN
    RAISE EXCEPTION 'BLEND_TICKET_PRODUCT_COUNT_INVALID';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(
      p_idempotency_key,
      'create_blend_ticket'
    );
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  v_customer_id := NULLIF(p_ticket_payload->>'customer_id', '')::uuid;
  IF v_customer_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.customers c
     WHERE c.id = v_customer_id
       AND c.is_active = true
  ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_CUSTOMER_INVALID';
  END IF;

  IF NOT p_enqueue_ocr AND v_customer_id IS NULL THEN
    RAISE EXCEPTION 'BLEND_TICKET_CUSTOMER_REQUIRED';
  END IF;

  IF (NULLIF(p_ticket_payload->>'total_acres', '')::numeric)::text
       IN ('NaN', 'Infinity', '-Infinity')
     OR (NULLIF(p_ticket_payload->>'total_volume', '')::numeric)::text
       IN ('NaN', 'Infinity', '-Infinity')
     OR COALESCE(NULLIF(p_ticket_payload->>'total_acres', '')::numeric, 0) < 0
     OR COALESCE(NULLIF(p_ticket_payload->>'total_volume', '')::numeric, 0) < 0 THEN
    RAISE EXCEPTION 'BLEND_TICKET_NUMERIC_INVALID';
  END IF;

  v_image_count := jsonb_array_length(COALESCE(p_images, '[]'::jsonb));
  IF p_enqueue_ocr AND (v_image_count < 1 OR v_image_count > 20) THEN
    RAISE EXCEPTION 'BLEND_TICKET_IMAGE_COUNT_INVALID: OCR uploads require 1 to 20 images';
  END IF;
  IF NOT p_enqueue_ocr AND v_image_count <> 0 THEN
    RAISE EXCEPTION 'BLEND_TICKET_IMAGE_MODE_INVALID';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(COALESCE(p_images, '[]'::jsonb)) image
     WHERE COALESCE((image->>'file_size')::bigint, 0) < 1
        OR COALESCE((image->>'file_size')::bigint, 0) > 10485760
        OR image->>'mime_type' NOT IN ('image/jpeg', 'image/png', 'image/webp')
        OR NULLIF(btrim(image->>'storage_path'), '') IS NULL
        OR image->>'storage_path' !~ (
          '^' || p_ticket_id::text || '/[1-9][0-9]*\.(jpg|jpeg|png|webp)$'
        )
        OR COALESCE((image->>'upload_order')::integer, 0) < 1
        OR COALESCE((image->>'upload_order')::integer, 0) > 20
  ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_IMAGE_METADATA_INVALID';
  END IF;

  IF (
    SELECT count(DISTINCT image->>'storage_path')
      FROM jsonb_array_elements(COALESCE(p_images, '[]'::jsonb)) image
  ) <> v_image_count OR (
    SELECT count(DISTINCT (image->>'upload_order')::integer)
      FROM jsonb_array_elements(COALESCE(p_images, '[]'::jsonb)) image
  ) <> v_image_count THEN
    RAISE EXCEPTION 'BLEND_TICKET_IMAGE_METADATA_DUPLICATE';
  END IF;

  -- serialize MAX+1 ticket-number generation for this date
  PERFORM pg_advisory_xact_lock(
    hashtextextended('crx:blend-ticket-number:' || current_date::text, 0)
  );
  v_ticket_number := public.generate_ticket_number();

  INSERT INTO public.blend_tickets (
    id, ticket_number, uploaded_by, upload_date,
    customer_id, ticket_date, ticket_time,
    status, review_status, source, ocr_confidence_score,
    signature_detected, job_number, invoice_number,
    driver_name, applicator_name, mixer_name, tank_number, vehicle_info,
    field_names, total_acres, application_rate, total_volume,
    total_volume_unit, notes
  ) VALUES (
    p_ticket_id, v_ticket_number, v_actor, now(),
    v_customer_id,
    NULLIF(p_ticket_payload->>'ticket_date', '')::date,
    NULLIF(p_ticket_payload->>'ticket_time', ''),
    CASE WHEN p_enqueue_ocr THEN 'pending' ELSE 'completed' END,
    'unreviewed',
    CASE WHEN p_enqueue_ocr THEN 'ocr' ELSE 'manual' END,
    CASE WHEN p_enqueue_ocr THEN 0 ELSE 100 END,
    false,
    NULLIF(btrim(p_ticket_payload->>'job_number'), ''),
    NULLIF(btrim(p_ticket_payload->>'invoice_number'), ''),
    NULLIF(btrim(p_ticket_payload->>'driver_name'), ''),
    NULLIF(btrim(p_ticket_payload->>'applicator_name'), ''),
    NULLIF(btrim(p_ticket_payload->>'mixer_name'), ''),
    NULLIF(btrim(p_ticket_payload->>'tank_number'), ''),
    NULLIF(btrim(p_ticket_payload->>'vehicle_info'), ''),
    NULLIF(btrim(p_ticket_payload->>'field_names'), ''),
    NULLIF(p_ticket_payload->>'total_acres', '')::numeric,
    NULLIF(btrim(p_ticket_payload->>'application_rate'), ''),
    NULLIF(p_ticket_payload->>'total_volume', '')::numeric,
    NULLIF(btrim(p_ticket_payload->>'total_volume_unit'), ''),
    NULLIF(btrim(p_ticket_payload->>'notes'), '')
  );

  FOR v_product, v_ordinality IN
    SELECT value, ordinality
      FROM jsonb_array_elements(COALESCE(p_products, '[]'::jsonb))
      WITH ORDINALITY
  LOOP
    IF jsonb_typeof(v_product) <> 'object'
       OR NULLIF(btrim(v_product->>'product_name'), '') IS NULL
       OR COALESCE((v_product->>'quantity')::numeric, 0) < 0
       OR ((v_product->>'quantity')::numeric)::text IN ('NaN', 'Infinity', '-Infinity')
       OR (NULLIF(v_product->>'rate_per_acre', '')::numeric)::text IN ('NaN', 'Infinity', '-Infinity')
       OR COALESCE(NULLIF(v_product->>'rate_per_acre', '')::numeric, 0) < 0
       OR (NULLIF(v_product->>'confidence_score', '')::numeric)::text IN ('NaN', 'Infinity', '-Infinity')
       OR COALESCE(NULLIF(v_product->>'confidence_score', '')::numeric, 0) < 0
       OR COALESCE(NULLIF(v_product->>'confidence_score', '')::numeric, 0) > 100 THEN
      RAISE EXCEPTION 'BLEND_TICKET_PRODUCT_INVALID';
    END IF;
    IF NULLIF(v_product->>'product_id', '') IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.products p
       WHERE p.id = (v_product->>'product_id')::uuid
         AND p.is_active = true
    ) THEN
      RAISE EXCEPTION 'BLEND_TICKET_PRODUCT_MATCH_INVALID';
    END IF;

    INSERT INTO public.blend_ticket_products (
      blend_ticket_id, product_id, product_name, quantity, unit,
      rate_per_acre, rate_per_acre_unit, lot_number, sequence_order,
      confidence_score, manually_corrected
    ) VALUES (
      p_ticket_id,
      NULLIF(v_product->>'product_id', '')::uuid,
      btrim(v_product->>'product_name'),
      COALESCE((v_product->>'quantity')::numeric, 0),
      NULLIF(btrim(v_product->>'unit'), ''),
      NULLIF(v_product->>'rate_per_acre', '')::numeric,
      NULLIF(btrim(v_product->>'rate_per_acre_unit'), ''),
      NULLIF(btrim(v_product->>'lot_number'), ''),
      COALESCE(NULLIF(v_product->>'sequence_order', '')::integer, v_ordinality::integer),
      CASE WHEN p_enqueue_ocr
        THEN COALESCE(NULLIF(v_product->>'confidence_score', '')::numeric, 0)
        ELSE 100
      END,
      false
    );
  END LOOP;

  FOR v_image IN
    SELECT value
      FROM jsonb_array_elements(COALESCE(p_images, '[]'::jsonb))
  LOOP
    INSERT INTO public.blend_ticket_images (
      blend_ticket_id, storage_path, image_url,
      file_size, mime_type, upload_order
    ) VALUES (
      p_ticket_id,
      v_image->>'storage_path',
      v_image->>'storage_path',
      (v_image->>'file_size')::bigint,
      v_image->>'mime_type',
      (v_image->>'upload_order')::integer
    );
  END LOOP;

  IF p_enqueue_ocr THEN
    INSERT INTO public.ocr_processing_queue (
      blend_ticket_id, status, priority, retry_count, max_retries
    ) VALUES (
      p_ticket_id, 'pending', 0, 0, 3
    );
  END IF;

  INSERT INTO public.activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'blend_ticket_created',
    'Blend ticket ' || v_ticket_number ||
      CASE WHEN p_enqueue_ocr THEN ' uploaded for OCR' ELSE ' created manually' END,
    v_actor, 'blend_ticket', p_ticket_id, v_customer_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'ticket_id', p_ticket_id,
    'ticket_number', v_ticket_number
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(
      p_idempotency_key,
      'create_blend_ticket',
      v_result
    );
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."create_blend_ticket"("p_ticket_id" "uuid", "p_ticket_payload" "jsonb", "p_products" "jsonb", "p_images" "jsonb", "p_enqueue_ocr" boolean, "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_commission_payment"("p_commission_ids" "uuid"[], "p_payment_method" "text", "p_reference" "text", "p_payment_date" "date", "p_notes" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor             uuid;
  v_existing          jsonb;
  v_payment_id        uuid;
  v_payment_num       text;
  v_total             numeric := 0;
  v_recipient_id      uuid;
  v_season            integer;
  v_payment_dt        date;
  v_selected_count    integer := 0;
  v_locked_count      integer := 0;
  v_non_pending_count integer := 0;
  v_recipient_count   integer := 0;
  v_already_in_payment integer := 0;
  v_item_count        integer := 0;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Admin access required to create a commission payment';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'create_commission_payment');
    IF v_existing IS NOT NULL THEN
      RETURN (v_existing #>> '{}')::uuid;
    END IF;
  END IF;

  v_payment_dt := COALESCE(p_payment_date, CURRENT_DATE);

  PERFORM check_period_open(v_payment_dt);

  IF array_length(p_commission_ids, 1) IS NULL OR array_length(p_commission_ids, 1) = 0 THEN
    RAISE EXCEPTION 'No commissions selected for payment';
  END IF;

  SELECT count(*)
    INTO v_selected_count
    FROM (
      SELECT DISTINCT id
      FROM unnest(p_commission_ids) AS selected(id)
    ) selected_ids;

  IF v_selected_count = 0 THEN
    RAISE EXCEPTION 'No commissions selected for payment';
  END IF;

  -- Lock every selected existing row, regardless of status. The later checks
  -- then run against the locked set and cannot silently filter stale rows out.
  PERFORM 1
     FROM commissions c
     JOIN (
       SELECT DISTINCT id
       FROM unnest(p_commission_ids) AS selected(id)
     ) selected_ids ON selected_ids.id = c.id
    FOR UPDATE OF c;

  SELECT count(*)
    INTO v_locked_count
    FROM commissions c
    JOIN (
      SELECT DISTINCT id
      FROM unnest(p_commission_ids) AS selected(id)
    ) selected_ids ON selected_ids.id = c.id;

  IF v_locked_count <> v_selected_count THEN
    RAISE EXCEPTION 'COMMISSION_PAYMENT_SELECTION_STALE: one or more selected commissions no longer exist';
  END IF;

  SELECT count(*)
    INTO v_non_pending_count
    FROM commissions c
    JOIN (
      SELECT DISTINCT id
      FROM unnest(p_commission_ids) AS selected(id)
    ) selected_ids ON selected_ids.id = c.id
   WHERE c.deleted_at IS NOT NULL
      OR c.status IS DISTINCT FROM 'pending';

  IF v_non_pending_count > 0 THEN
    RAISE EXCEPTION 'COMMISSION_PAYMENT_SELECTION_STALE: every selected commission must still be pending';
  END IF;

  SELECT count(*)
    INTO v_already_in_payment
    FROM commission_payment_items cpi
    JOIN commission_payments cp ON cp.id = cpi.commission_payment_id
    JOIN (
      SELECT DISTINCT id
      FROM unnest(p_commission_ids) AS selected(id)
    ) selected_ids ON selected_ids.id = cpi.commission_id
   WHERE cp.status IS DISTINCT FROM 'voided';

  IF v_already_in_payment > 0 THEN
    RAISE EXCEPTION 'One or more commissions are already in an existing (non-voided) payment. Void that payment first or remove those commissions from the selection.';
  END IF;

  SELECT count(DISTINCT c.recipient_user_id)
    INTO v_recipient_count
    FROM commissions c
    JOIN (
      SELECT DISTINCT id
      FROM unnest(p_commission_ids) AS selected(id)
    ) selected_ids ON selected_ids.id = c.id;

  IF v_recipient_count <> 1 THEN
    RAISE EXCEPTION 'All commissions in a payment must belong to the same recipient';
  END IF;

  SELECT c.recipient_user_id
    INTO v_recipient_id
    FROM commissions c
    JOIN (
      SELECT DISTINCT id
      FROM unnest(p_commission_ids) AS selected(id)
    ) selected_ids ON selected_ids.id = c.id
   LIMIT 1;

  SELECT sum(c.commission_amount)
    INTO v_total
    FROM commissions c
    JOIN (
      SELECT DISTINCT id
      FROM unnest(p_commission_ids) AS selected(id)
    ) selected_ids ON selected_ids.id = c.id;

  v_season := compute_season(v_payment_dt);
  v_payment_num := next_commission_payment_number();

  INSERT INTO commission_payments (
    payment_number, recipient_id, total_amount, status,
    payment_method, reference_number, payment_date, notes, season, created_by
  ) VALUES (
    v_payment_num, v_recipient_id, v_total, 'unposted',
    p_payment_method, p_reference, v_payment_dt,
    p_notes, v_season, v_actor
  ) RETURNING id INTO v_payment_id;

  INSERT INTO commission_payment_items (
    commission_payment_id, commission_id, amount
  )
  SELECT v_payment_id, c.id, c.commission_amount
    FROM commissions c
    JOIN (
      SELECT DISTINCT id
      FROM unnest(p_commission_ids) AS selected(id)
    ) selected_ids ON selected_ids.id = c.id
   WHERE c.deleted_at IS NULL
     AND c.status = 'pending';

  GET DIAGNOSTICS v_item_count = ROW_COUNT;
  IF v_item_count <> v_selected_count THEN
    RAISE EXCEPTION 'COMMISSION_PAYMENT_SELECTION_STALE: expected % commission payment item(s), inserted %',
      v_selected_count, v_item_count;
  END IF;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id,
    actor_user_id, total_impact_cents, description
  ) VALUES (
    'commission_payment_created', 'commission_payment', v_payment_id,
    v_actor, (v_total * 100)::bigint,
    'Commission payment ' || v_payment_num || ' created (UNPOSTED) for $' ||
    to_char(v_total, 'FM999,999,990.00') || ' to ' ||
    (SELECT full_name FROM profiles WHERE id = v_recipient_id)
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'create_commission_payment', to_jsonb(v_payment_id::text));
  END IF;

  RETURN v_payment_id;
END;
$_$;


ALTER FUNCTION "public"."create_commission_payment"("p_commission_ids" "uuid"[], "p_payment_method" "text", "p_reference" "text", "p_payment_date" "date", "p_notes" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_delivery_with_items"("p_order_id" "uuid", "p_customer_id" "uuid", "p_scheduled_date" "date", "p_items" "jsonb", "p_delivery_address_id" "uuid" DEFAULT NULL::"uuid", "p_assigned_driver" "uuid" DEFAULT NULL::"uuid", "p_scheduled_time" "text" DEFAULT NULL::"text", "p_delivery_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor              uuid := auth.uid();
  v_delivery_id        uuid;
  v_delivery_no        text;
  v_existing           jsonb;
  v_result             jsonb;
  v_item               jsonb;
  v_item_count         int := 0;
  v_order              record;
  v_item_oid           uuid;
  v_item_pid           uuid;
  v_item_qty           numeric;
  v_order_item         record;
  v_other_scheduled    numeric;
  v_max_allowed        numeric;
  v_dup_oid            uuid;
  v_address_customer   uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  IF p_order_id IS NULL THEN RAISE EXCEPTION 'ORDER_ID_REQUIRED'; END IF;
  IF p_customer_id IS NULL THEN RAISE EXCEPTION 'CUSTOMER_ID_REQUIRED'; END IF;
  IF p_scheduled_date IS NULL THEN RAISE EXCEPTION 'SCHEDULED_DATE_REQUIRED'; END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'ITEMS_REQUIRED';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'create_delivery_with_items');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT (elem->>'order_item_id')::uuid INTO v_dup_oid
  FROM jsonb_array_elements(p_items) AS elem
  GROUP BY (elem->>'order_item_id')::uuid
  HAVING COUNT(*) > 1
  LIMIT 1;
  IF v_dup_oid IS NOT NULL THEN
    RAISE EXCEPTION 'ITEM_DUPLICATE_IN_REQUEST: order_item_id % appears more than once in items', v_dup_oid;
  END IF;

  SELECT customer_id, status INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND: order_id % does not exist', p_order_id;
  END IF;
  IF v_order.customer_id IS DISTINCT FROM p_customer_id THEN
    RAISE EXCEPTION 'CUSTOMER_ORDER_MISMATCH: order % belongs to customer %, caller sent %',
      p_order_id, v_order.customer_id, p_customer_id;
  END IF;
  IF v_order.status NOT IN ('confirmed', 'partially_fulfilled') THEN
    RAISE EXCEPTION 'ORDER_NOT_SCHEDULABLE: order % is in status %, cannot create delivery (must be confirmed or partially_fulfilled)',
      p_order_id, v_order.status;
  END IF;

  IF p_delivery_address_id IS NOT NULL THEN
    SELECT customer_id INTO v_address_customer
    FROM public.customer_addresses
    WHERE id = p_delivery_address_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'ADDRESS_NOT_FOUND: delivery_address_id % does not exist', p_delivery_address_id;
    END IF;
    IF v_address_customer IS DISTINCT FROM p_customer_id THEN
      RAISE EXCEPTION 'ADDRESS_CUSTOMER_MISMATCH: delivery_address_id % belongs to customer %, not %',
        p_delivery_address_id, v_address_customer, p_customer_id;
    END IF;
  END IF;

  v_delivery_no := next_delivery_number();

  INSERT INTO public.deliveries (
    delivery_number, order_id, customer_id, delivery_address_id,
    assigned_driver, scheduled_date, scheduled_time, delivery_notes,
    status, created_by
  ) VALUES (
    v_delivery_no, p_order_id, p_customer_id, p_delivery_address_id,
    p_assigned_driver, p_scheduled_date, p_scheduled_time, p_delivery_notes,
    'scheduled', v_actor
  )
  RETURNING id INTO v_delivery_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    IF (v_item->>'order_item_id') IS NULL OR (v_item->>'product_id') IS NULL THEN
      RAISE EXCEPTION 'ITEM_INVALID: order_item_id and product_id required';
    END IF;
    IF (v_item->>'quantity') IS NULL OR (v_item->>'quantity')::numeric <= 0 THEN
      RAISE EXCEPTION 'ITEM_INVALID: quantity must be > 0';
    END IF;

    v_item_oid := (v_item->>'order_item_id')::uuid;
    v_item_pid := (v_item->>'product_id')::uuid;
    v_item_qty := (v_item->>'quantity')::numeric;

    SELECT id, order_id, product_id, quantity_remaining INTO v_order_item
    FROM public.order_items
    WHERE id = v_item_oid
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'ITEM_NOT_FOUND: order_item_id % does not exist', v_item_oid;
    END IF;
    IF v_order_item.order_id IS DISTINCT FROM p_order_id THEN
      RAISE EXCEPTION 'ITEM_ORDER_MISMATCH: order_item_id % belongs to order %, not %',
        v_item_oid, v_order_item.order_id, p_order_id;
    END IF;
    IF v_order_item.product_id IS DISTINCT FROM v_item_pid THEN
      RAISE EXCEPTION 'ITEM_PRODUCT_MISMATCH: order_item_id % has product %, caller sent %',
        v_item_oid, v_order_item.product_id, v_item_pid;
    END IF;

    SELECT COALESCE(SUM(di.quantity), 0) INTO v_other_scheduled
    FROM public.delivery_items di
    JOIN public.deliveries d ON d.id = di.delivery_id
    WHERE di.order_item_id = v_item_oid
      AND d.status IN ('scheduled', 'in_progress')
      AND d.id <> v_delivery_id;

    v_max_allowed := COALESCE(v_order_item.quantity_remaining, 0) - COALESCE(v_other_scheduled, 0);

    IF v_item_qty > v_max_allowed THEN
      RAISE EXCEPTION 'ITEM_OVER_REMAINING_INCL_ACTIVE: order_item_id % has % units on other active deliveries; only % available (% remaining on order minus % active)',
        v_item_oid,
        COALESCE(v_other_scheduled, 0),
        GREATEST(v_max_allowed, 0),
        COALESCE(v_order_item.quantity_remaining, 0),
        COALESCE(v_other_scheduled, 0);
    END IF;

    INSERT INTO public.delivery_items (
      delivery_id, order_item_id, product_id, quantity,
      unit_size, tote_number, notes
    ) VALUES (
      v_delivery_id,
      v_item_oid,
      v_item_pid,
      v_item_qty,
      NULLIF(v_item->>'unit_size', ''),
      NULLIF(v_item->>'tote_number', ''),
      NULLIF(v_item->>'notes', '')
    );
    v_item_count := v_item_count + 1;
  END LOOP;

  v_result := jsonb_build_object(
    'success',          true,
    'delivery_id',      v_delivery_id,
    'delivery_number',  v_delivery_no,
    'item_count',       v_item_count
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'create_delivery_with_items', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."create_delivery_with_items"("p_order_id" "uuid", "p_customer_id" "uuid", "p_scheduled_date" "date", "p_items" "jsonb", "p_delivery_address_id" "uuid", "p_assigned_driver" "uuid", "p_scheduled_time" "text", "p_delivery_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_direct_order"("p_customer_id" "uuid", "p_order_date" "date", "p_order_name" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_items" "jsonb" DEFAULT '[]'::"jsonb", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_customer_po_number" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_actor_role text;
  v_order_id uuid;
  v_order_number text;
  v_item jsonb;
  v_total_price numeric := 0;
  v_total_cost numeric := 0;
  v_total_profit numeric;
  v_total_margin_pct numeric;
  v_customer record;
  v_cached_result jsonb;
  v_result jsonb;
  v_inv record;
  v_warnings text[] := '{}';
  v_qty numeric;
  v_net_position numeric;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by <> v_actor THEN
    RAISE EXCEPTION 'Actor mismatch';
  END IF;

  SELECT role INTO v_actor_role
  FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached_result := check_idempotency(p_idempotency_key, 'create_direct_order');
    IF v_cached_result IS NOT NULL THEN RETURN v_cached_result; END IF;
  END IF;

  SELECT * INTO v_customer FROM customers WHERE id = p_customer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found: %', p_customer_id; END IF;

  v_order_number := generate_order_number();

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    IF (v_item->>'product_id') IS NULL THEN CONTINUE; END IF;
    v_qty := COALESCE((v_item->>'quantity')::numeric, 0);
    IF v_qty <= 0 THEN CONTINUE; END IF;
    SELECT * INTO v_inv FROM inventory
    WHERE product_id = (v_item->>'product_id')::uuid AND location = 'Main Warehouse';
    IF NOT FOUND THEN
      v_warnings := array_append(v_warnings,
        COALESCE(v_item->>'product_name', 'Unknown product') ||
        ': need ' || v_qty || ', net position is 0 (no inventory record)');
    ELSE
      v_net_position := v_inv.quantity_available - v_inv.quantity_prebooked + COALESCE(v_inv.quantity_on_order, 0);
      IF v_net_position < v_qty THEN
        v_warnings := array_append(v_warnings,
          COALESCE(v_item->>'product_name', 'Unknown product') ||
          ': need ' || v_qty ||
          ', net position is ' || GREATEST(v_net_position, 0) ||
          ' (on floor: ' || (v_inv.quantity_available - v_inv.quantity_prebooked) ||
          ', on order: ' || COALESCE(v_inv.quantity_on_order, 0) || ')');
      END IF;
    END IF;
  END LOOP;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_total_price := v_total_price
      + COALESCE((v_item->>'quantity')::numeric, 0)
      * COALESCE((v_item->>'price_per_unit')::numeric, 0);
    v_total_cost := v_total_cost
      + COALESCE((v_item->>'quantity')::numeric, 0)
      * COALESCE((v_item->>'unit_cost')::numeric, 0);
  END LOOP;

  v_total_profit := v_total_price - v_total_cost;
  v_total_margin_pct := CASE
    WHEN v_total_price > 0 THEN (v_total_profit / v_total_price) * 100
    ELSE 0
  END;

  INSERT INTO orders (
    order_number, order_name, customer_id, status,
    total_price, total_cost, total_profit, total_margin_pct,
    order_date, notes,
    customer_po_number  -- DELTA-2 (create_direct_order_customer_po_param)
  ) VALUES (
    v_order_number, NULLIF(TRIM(COALESCE(p_order_name, '')), ''),
    p_customer_id, 'confirmed',
    v_total_price, v_total_cost, v_total_profit, v_total_margin_pct,
    p_order_date,
    NULLIF(TRIM(COALESCE(p_notes, '')), ''),
    NULLIF(TRIM(COALESCE(p_customer_po_number, '')), '')  -- DELTA-2
  ) RETURNING id INTO v_order_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    IF (v_item->>'product_id') IS NULL OR COALESCE((v_item->>'quantity')::numeric, 0) <= 0 THEN
      CONTINUE;
    END IF;
    INSERT INTO order_items (
      order_id, product_id, product_name,
      price_per_unit, cost_per_unit,
      total_units_needed, unit_size,
      total_price, profit, net_margin,
      quantity_delivered, quantity_remaining
    ) VALUES (
      v_order_id, (v_item->>'product_id')::uuid, v_item->>'product_name',
      COALESCE((v_item->>'price_per_unit')::numeric, 0),
      COALESCE((v_item->>'unit_cost')::numeric, 0),
      (v_item->>'quantity')::numeric, v_item->>'unit_size',
      COALESCE((v_item->>'quantity')::numeric, 0) * COALESCE((v_item->>'price_per_unit')::numeric, 0),
      (COALESCE((v_item->>'price_per_unit')::numeric, 0) - COALESCE((v_item->>'unit_cost')::numeric, 0))
        * COALESCE((v_item->>'quantity')::numeric, 0),
      CASE WHEN COALESCE((v_item->>'price_per_unit')::numeric, 0) > 0
        THEN ((COALESCE((v_item->>'price_per_unit')::numeric, 0) - COALESCE((v_item->>'unit_cost')::numeric, 0))
              / (v_item->>'price_per_unit')::numeric) * 100
        ELSE 0
      END,
      0, (v_item->>'quantity')::numeric
    );
    UPDATE inventory SET
      quantity_prebooked = quantity_prebooked + (v_item->>'quantity')::numeric,
      updated_at = now()
    WHERE product_id = (v_item->>'product_id')::uuid AND location = 'Main Warehouse';
    IF NOT FOUND THEN
      INSERT INTO inventory (product_id, location, quantity_available, quantity_prebooked, quantity_on_order, unit_size)
      VALUES ((v_item->>'product_id')::uuid, 'Main Warehouse', 0, (v_item->>'quantity')::numeric, 0, v_item->>'unit_size');
    END IF;
    INSERT INTO inventory_transactions (
      product_id, transaction_type, quantity, to_location,
      order_id, performed_by, notes
    ) VALUES (
      (v_item->>'product_id')::uuid, 'booked', (v_item->>'quantity')::numeric,
      'Main Warehouse', v_order_id, v_actor,
      'Pre-booked for order ' || v_order_number
    );
  END LOOP;

  PERFORM _insert_commissions_for_order(
    v_order_id, p_customer_id, v_total_profit,
    v_customer.default_commission_split, p_order_date
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'order_created',
    'Direct order ' || v_order_number || COALESCE(' (' || NULLIF(TRIM(COALESCE(p_order_name, '')), '') || ')', '') || ' created for ' || COALESCE(v_customer.farm_name, 'customer') ||
    CASE WHEN array_length(v_warnings, 1) > 0
      THEN ' (inventory warnings: ' || array_to_string(v_warnings, '; ') || ')'
      ELSE '' END,
    v_actor, 'order', v_order_id, p_customer_id
  );

  v_result := jsonb_build_object(
    'status', 'created', 'order_id', v_order_id,
    'order_number', v_order_number, 'warnings', to_jsonb(v_warnings)
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'create_direct_order', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."create_direct_order"("p_customer_id" "uuid", "p_order_date" "date", "p_order_name" "text", "p_notes" "text", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text", "p_customer_po_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_followup_delivery"("p_original_delivery_id" "uuid", "p_scheduled_date" "date" DEFAULT NULL::"date", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_original record;
  v_rem record;
  v_new_del_id uuid;
  v_del_number text;
  v_item_count integer := 0;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'create_followup_delivery');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_original
  FROM deliveries
  WHERE id = p_original_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_NOT_FOUND'; END IF;

  PERFORM 1 FROM delivery_remainders
  WHERE original_delivery_id = p_original_delivery_id AND status = 'pending'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NO_PENDING_REMAINDERS';
  END IF;

  SELECT next_delivery_number() INTO v_del_number;

  INSERT INTO deliveries (
    delivery_number, order_id, customer_id, delivery_address_id,
    assigned_driver, scheduled_date, scheduled_time, delivery_notes,
    status, priority, created_by
  ) VALUES (
    v_del_number,
    v_original.order_id,
    v_original.customer_id,
    v_original.delivery_address_id,
    v_original.assigned_driver,
    COALESCE(p_scheduled_date, CURRENT_DATE + interval '1 day'),
    v_original.scheduled_time,
    'Follow-up for ' || v_original.delivery_number,
    'scheduled',
    v_original.priority,
    v_actor
  )
  RETURNING id INTO v_new_del_id;

  FOR v_rem IN
    SELECT * FROM delivery_remainders
    WHERE original_delivery_id = p_original_delivery_id AND status = 'pending'
    FOR UPDATE
  LOOP
    INSERT INTO delivery_items (
      delivery_id, order_item_id, product_id, quantity, unit_size
    ) VALUES (
      v_new_del_id,
      v_rem.order_item_id,
      v_rem.product_id,
      v_rem.quantity_remaining,
      v_rem.unit_size
    );

    UPDATE delivery_remainders SET
      status = 'scheduled',
      followup_delivery_id = v_new_del_id,
      updated_at = now()
    WHERE id = v_rem.id;

    v_item_count := v_item_count + 1;
  END LOOP;

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type,
    related_entity_id,
    customer_id
  ) VALUES (
    'delivery_created',
    'Follow-up delivery ' || v_del_number || ' created from ' || v_original.delivery_number || ' remainders (' || v_item_count || ' items)',
    v_actor, 'delivery', v_new_del_id, v_original.customer_id
  );

  IF v_original.assigned_driver IS NOT NULL THEN
    INSERT INTO notifications (
      user_id,
      title,
      message,
      notification_type,
      related_entity_type,
      related_entity_id
    )
    VALUES (
      v_original.assigned_driver,
      'Follow-up Delivery Scheduled',
      'Follow-up delivery ' || v_del_number || ' created for remaining items from ' || v_original.delivery_number || '.',
      'delivery_update', 'delivery', v_new_del_id
    );
  END IF;

  v_result := jsonb_build_object(
    'status', 'created',
    'delivery_id', v_new_del_id,
    'delivery_number', v_del_number,
    'item_count', v_item_count
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'create_followup_delivery', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."create_followup_delivery"("p_original_delivery_id" "uuid", "p_scheduled_date" "date", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_inventory_hold"("p_product_id" "uuid", "p_customer_id" "uuid", "p_quantity" numeric, "p_hold_type" "text", "p_expires_at" "date", "p_notes" "text", "p_performed_by" "uuid", "p_force" boolean DEFAULT false, "p_force_reason" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_role text;
  v_hold_id uuid;
  v_existing jsonb;
  v_inventory record;
  v_active_holds numeric;
  v_todays_free numeric;
  v_result jsonb;
BEGIN
  -- PARKED-010 (codex-driven cycle 6 #3 MED): auth gate FIRST — without this,
  -- any authenticated caller who learns a known idempotency_key for this op
  -- can read the cached hold_id (+ uncommitted-stock figure) without first
  -- proving they are admin/sales_rep AND the original requester (strict-actor).
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by != v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_role FROM profiles WHERE id = v_actor;
  IF v_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- Idempotency cache check NOW runs after the caller is authenticated AND
  -- role-gated. Same-key, same-op replay still returns the cached result; an
  -- attacker without the right role hits INSUFFICIENT_ROLE above instead.
  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key
       AND operation = 'create_inventory_hold';
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  IF p_hold_type NOT IN ('manual', 'crop_program') THEN
    RAISE EXCEPTION 'INVALID_HOLD_TYPE: %', p_hold_type;
  END IF;

  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'INVALID_QUANTITY: must be > 0';
  END IF;

  -- F1 fix: validate the force contract BEFORE any inventory-based branching.
  IF p_force THEN
    IF v_role != 'admin' THEN
      RAISE EXCEPTION 'FORCE_REQUIRES_ADMIN';
    END IF;
    IF p_force_reason IS NULL OR length(trim(p_force_reason)) = 0 THEN
      RAISE EXCEPTION 'FORCE_REQUIRES_REASON';
    END IF;
  END IF;

  SELECT id, quantity_available, quantity_prebooked
    INTO v_inventory
    FROM inventory
   WHERE product_id = p_product_id
     AND location = 'Main Warehouse'
   FOR UPDATE;

  IF NOT FOUND THEN
    v_todays_free := 0;
    v_active_holds := 0;
  ELSE
    SELECT COALESCE(SUM(quantity), 0) INTO v_active_holds
      FROM inventory_holds
     WHERE product_id = p_product_id
       AND is_active = true
       AND (expires_at IS NULL OR expires_at >= CURRENT_DATE);
    v_todays_free := v_inventory.quantity_available
                     - v_inventory.quantity_prebooked
                     - v_active_holds;
  END IF;

  IF v_todays_free - p_quantity < 0 AND NOT p_force THEN
    RAISE EXCEPTION 'INSUFFICIENT_HOLD_INVENTORY: only % units uncommitted (Available % - Prebooked % - Active Holds %); requested %',
      v_todays_free,
      COALESCE(v_inventory.quantity_available, 0),
      COALESCE(v_inventory.quantity_prebooked, 0),
      v_active_holds,
      p_quantity;
  END IF;

  INSERT INTO inventory_holds (
    product_id, customer_id, quantity, hold_type, expires_at, notes,
    is_active, created_by, created_at, updated_at
  ) VALUES (
    p_product_id, p_customer_id, p_quantity, p_hold_type, p_expires_at,
    p_notes, true, v_actor, NOW(), NOW()
  ) RETURNING id INTO v_hold_id;

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'inventory_hold_created',
    CASE
      WHEN p_force THEN 'WARNING: Hold created with admin override (' || p_force_reason || ')'
      ELSE 'Hold created'
    END,
    v_actor, 'inventory_hold', v_hold_id, p_customer_id
  );

  v_result := jsonb_build_object(
    'hold_id', v_hold_id,
    'todays_free_before', v_todays_free,
    'forced', p_force
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result, expires_at)
    VALUES (p_idempotency_key, 'create_inventory_hold', v_result,
            now() + interval '24 hours')
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."create_inventory_hold"("p_product_id" "uuid", "p_customer_id" "uuid", "p_quantity" numeric, "p_hold_type" "text", "p_expires_at" "date", "p_notes" "text", "p_performed_by" "uuid", "p_force" boolean, "p_force_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_invoice_for_unbilled_delivery"("p_delivery_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid; v_existing jsonb; v_delivery record; v_existing_count integer;
  v_invoice_id uuid; v_invoice_number text; v_total_cents bigint := 0;
  v_cost_cents bigint := 0; v_item record; v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin access required to create an invoice for a delivery'; END IF;
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'create_invoice_for_unbilled_delivery');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;
  SELECT * INTO v_delivery FROM deliveries WHERE id = p_delivery_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found: %', p_delivery_id; END IF;
  IF v_delivery.status != 'completed' THEN
    RAISE EXCEPTION 'Delivery is not completed (current status: %). Only completed deliveries can be invoiced retroactively.', v_delivery.status;
  END IF;
  IF v_delivery.order_id IS NULL THEN RAISE EXCEPTION 'Delivery has no order_id — cannot auto-invoice an orphan delivery'; END IF;
  PERFORM 1 FROM orders WHERE id = v_delivery.order_id FOR UPDATE;

  -- CODE-RABBIT FIX: child allocation inserts take a KEY SHARE lock on their
  -- parent item. Lock every item in stable id order before checking OIFA rows.
  PERFORM 1
    FROM order_items
   WHERE order_id = v_delivery.order_id
   ORDER BY id
   FOR UPDATE;

  IF (SELECT COALESCE(needs_split_billing, false) FROM orders WHERE id = v_delivery.order_id)
     OR EXISTS (
       SELECT 1 FROM order_item_field_allocations oifa
       JOIN order_items oi ON oi.id = oifa.order_item_id
       WHERE oi.order_id = v_delivery.order_id
     ) THEN
    RAISE EXCEPTION 'ORDER_NEEDS_SPLIT_BILLING: delivery %''s order uses split billing — a single backfilled invoice would mono-bill it and mis-attribute AR. Create the split invoices through the split-billing flow instead.', v_delivery.delivery_number;
  END IF;

  SELECT COUNT(*) INTO v_existing_count FROM invoices
  WHERE order_id = v_delivery.order_id AND status NOT IN ('voided', 'cancelled')
    AND (delivery_id = p_delivery_id OR delivery_id IS NULL) AND deleted_at IS NULL;
  IF v_existing_count > 0 THEN
    RAISE EXCEPTION 'This delivery already has an active invoice (or an order-level invoice covers the whole order) — nothing to backfill. Find and review the existing invoice instead.';
  END IF;
  v_invoice_number := next_invoice_number('chemical_sale');
  INSERT INTO invoices (invoice_number, invoice_type, order_id, customer_id, delivery_id,
    status, invoice_date, total_amount_cents, total_cost_cents, created_by)
  VALUES (v_invoice_number, 'chemical_sale', v_delivery.order_id, v_delivery.customer_id,
    p_delivery_id, 'draft', CURRENT_DATE, 0, 0, v_actor) RETURNING id INTO v_invoice_id;
  FOR v_item IN
    SELECT di.product_id, di.quantity_delivered, di.unit_size, di.order_item_id,
      oi.price_per_unit, oi.cost_per_unit, oi.product_name AS oi_product_name, p.product_name AS p_name
    FROM delivery_items di JOIN order_items oi ON oi.id = di.order_item_id
    JOIN products p ON p.id = di.product_id
    WHERE di.delivery_id = p_delivery_id AND COALESCE(di.quantity_delivered, 0) > 0
  LOOP
    v_total_cents := v_total_cents + ROUND(v_item.quantity_delivered * v_item.price_per_unit * 100)::bigint;
    v_cost_cents := v_cost_cents + ROUND(v_item.quantity_delivered * COALESCE(v_item.cost_per_unit, 0) * 100)::bigint;
    INSERT INTO invoice_items (invoice_id, order_item_id, product_id, description,
      quantity, unit_price_cents, extended_cents, cost_cents, unit_size)
    VALUES (v_invoice_id, v_item.order_item_id, v_item.product_id,
      COALESCE(v_item.oi_product_name, v_item.p_name), v_item.quantity_delivered,
      ROUND(v_item.price_per_unit * 100)::bigint,
      ROUND(v_item.quantity_delivered * v_item.price_per_unit * 100)::bigint,
      ROUND(COALESCE(v_item.cost_per_unit, 0) * 100)::bigint, v_item.unit_size);
  END LOOP;
  UPDATE invoices SET total_amount_cents = v_total_cents, total_cost_cents = v_cost_cents WHERE id = v_invoice_id;
  INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_role,
    new_values, total_impact_cents, description)
  VALUES ('invoice_created', 'invoice', v_invoice_id,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object('invoice_number', v_invoice_number, 'delivery_id', p_delivery_id,
      'order_id', v_delivery.order_id, 'customer_id', v_delivery.customer_id, 'total_cents', v_total_cents),
    v_total_cents, 'Invoice ' || v_invoice_number || ' backfilled for completed delivery ' || v_delivery.delivery_number);
  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('invoice_backfilled_for_delivery', 'Backfilled draft invoice ' || v_invoice_number ||
    ' for completed delivery ' || v_delivery.delivery_number, v_actor, 'invoice', v_invoice_id, v_delivery.customer_id);
  v_result := jsonb_build_object('success', true, 'delivery_id', p_delivery_id,
    'invoice_id', v_invoice_id, 'invoice_number', v_invoice_number, 'total_cents', v_total_cents);
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'create_invoice_for_unbilled_delivery', v_result);
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."create_invoice_for_unbilled_delivery"("p_delivery_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_invoice_from_blend_ticket"("p_blend_ticket_id" "uuid", "p_created_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor               uuid := auth.uid();
  v_existing            jsonb;
  v_ticket              record;
  v_field_ids           uuid[];
  v_applied_acres_map   jsonb := '{}'::jsonb;
  v_btf                 record;
  v_field_acres         numeric;
  v_shares              jsonb;
  v_customers           jsonb;
  v_customer            jsonb;
  v_customer_id         uuid;
  v_customer_name       text;
  v_customer_tier       int;
  v_is_primary          boolean;
  v_has_override        boolean;
  v_invoice_id          uuid;
  v_invoice_number      text;
  v_invoice_group_id    uuid;
  v_invoice_ids         uuid[] := '{}';
  v_app_service         record;
  v_has_app_service     boolean := false;
  v_fee_rate            bigint;
  v_btp                 record;
  v_share_row           jsonb;
  v_share_acres         numeric;
  v_field_override      bigint;
  v_field_pricing_note  text;
  v_unit_price          bigint;
  v_unit_cost           bigint;
  v_qi_price            numeric;
  v_quoted_price        bigint;
  v_quote_section_id    uuid;
  v_price_source        text;
  v_extended            bigint;
  v_invoice_total       bigint;
  v_invoice_cost        bigint;
  v_total_share_acres   numeric;
  v_grower_share_amount bigint;
  v_fee_acres           numeric;
  v_fee_extended        bigint;
  v_fee_cost            bigint;
  v_result              jsonb;
  v_customer_count      int;
  v_chem_qty_a          numeric;
  v_chem_qty_b          numeric;
  v_rate                numeric;
  -- A5: unit-conversion + pre-billing validation locals
  v_rate_unit_line      text;
  v_inv_unit_line       text;
  v_chem_qty_a_conv     numeric;
  v_chem_qty_b_conv     numeric;
  v_bad_rate            text;
  v_bad_unit            text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_created_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_created_by does not match authenticated user';
  END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'Not authorized: admin or sales role required to create blend ticket invoices';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(
      p_idempotency_key,
      'create_invoice_from_blend_ticket'
    );
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_ticket
    FROM blend_tickets
   WHERE id = p_blend_ticket_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Blend ticket not found: %', p_blend_ticket_id; END IF;
  IF v_ticket.review_status != 'approved' THEN
    RAISE EXCEPTION 'Blend ticket must be approved (status: %)', v_ticket.review_status;
  END IF;
  IF v_ticket.payment_status IS DISTINCT FROM 'unbilled' THEN
    RAISE EXCEPTION 'Blend ticket cannot be billed (payment_status: %); only an unbilled ticket can generate an invoice', v_ticket.payment_status;
  END IF;

  -- A linked sales-order path and a direct blend-ticket invoice are mutually
  -- exclusive billing provenance. The ticket row is already locked, and these
  -- checks run before field derivation, invoice numbering, commissions, or writes.
  IF v_ticket.order_link_status = 'linked'
     OR EXISTS (
       SELECT 1 FROM public.blend_ticket_to_order_items
        WHERE blend_ticket_id = p_blend_ticket_id
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_LINKED_ORDER_INVOICE_LOCKED';
  END IF;

  -- Do not trust the cached payment flag alone: an active invoice may exist
  -- while payment_status is stale/unbilled. Terminal invoices release the lock.
  IF EXISTS (
    SELECT 1 FROM public.invoices i
     WHERE i.blend_ticket_id = p_blend_ticket_id
       AND i.deleted_at IS NULL
       AND COALESCE(i.status, '') NOT IN ('voided', 'cancelled')
  ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_ACTIVE_INVOICE_EXISTS';
  END IF;

  -- U6 #91a: refuse to bill the blend ticket if its linked job has ALREADY been
  -- invoiced (job.status='invoiced', or job.invoice_id points at a still-active
  -- invoice). The blend ticket and the job invoice bill the SAME application, so
  -- letting both through double-bills the customer. Block, do not warn.
  IF v_ticket.job_id IS NOT NULL THEN
    -- U6 (Codex P1): lock the JOB row first — transfer_job_to_invoice locks this
    -- same row (FOR UPDATE) before ITS blend-ticket guard, so the two paths
    -- serialize on it; without the lock both guards could read pre-commit state
    -- concurrently and both invoices would land (the exact double-bill this
    -- guard exists to stop). Lock order is safe: neither path row-locks
    -- blend_tickets after jobs.
    PERFORM 1 FROM jobs WHERE id = v_ticket.job_id FOR UPDATE;
    -- Codex R2 P2: test for a LIVE invoice directly (invoices.job_id, non-void/
    -- cancel, not deleted) instead of trusting jobs.status — a job stranded as
    -- 'invoiced' by a PRE-U6 void (dead invoice, status never reverted) must not
    -- block billing the ticket forever.
    IF EXISTS (
      SELECT 1 FROM invoices i
      WHERE i.job_id = v_ticket.job_id
        AND i.status NOT IN ('voided', 'cancelled')
        AND i.deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'JOB_ALREADY_INVOICED: this blend ticket''s job has already been invoiced; billing the ticket too would double-bill the customer. Void the job invoice first if you meant to re-bill.';
    END IF;
  END IF;

  -- A5 BEGIN: refuse to bill blend lines that can't be priced correctly.
  -- (1) A billable product line with no per-acre rate would silently bill $0.
  SELECT string_agg(DISTINCT btp.product_name, ', ')
    INTO v_bad_rate
    FROM blend_ticket_products btp
   WHERE btp.blend_ticket_id = p_blend_ticket_id
     AND btp.product_id IS NOT NULL
     AND (btp.rate_per_acre IS NULL OR btp.rate_per_acre <= 0);
  IF v_bad_rate IS NOT NULL THEN
    RAISE EXCEPTION 'BLEND_TICKET_ZERO_RATE: product(s) have no per-acre rate and cannot be billed: %', v_bad_rate;
  END IF;
  -- (2) A billable line whose rate unit cannot convert to the product's inventory
  --     (pricing) unit would mis-bill by the unit ratio (the oz-vs-gal 128x class).
  SELECT string_agg(DISTINCT btp.product_name, ', ')
    INTO v_bad_unit
    FROM blend_ticket_products btp
    JOIN products p ON p.id = btp.product_id
   WHERE btp.blend_ticket_id = p_blend_ticket_id
     AND btp.product_id IS NOT NULL
     AND field_app_priced_quantity(
           1,
           normalize_rate_unit(COALESCE(NULLIF(btrim(btp.rate_per_acre_unit), ''), p.rate_unit)),
           normalize_rate_unit(COALESCE(NULLIF(btrim(p.inventory_unit), ''), p.unit_size)),
           p.product_form
         ) IS NULL;
  IF v_bad_unit IS NOT NULL THEN
    RAISE EXCEPTION 'BLEND_TICKET_UNIT_UNCONVERTIBLE: product(s) have a rate unit that cannot convert to the inventory unit: %', v_bad_unit;
  END IF;
  -- A5 END

  FOR v_btf IN
    SELECT btf.field_id,
           COALESCE(btf.actual_acres, btf.planned_acres, f.total_acres, 0) AS field_acres
      FROM blend_ticket_fields btf
      JOIN fields f ON f.id = btf.field_id
     WHERE btf.blend_ticket_id = p_blend_ticket_id
  LOOP
    v_field_ids := array_append(v_field_ids, v_btf.field_id);
    v_applied_acres_map := v_applied_acres_map || jsonb_build_object(v_btf.field_id::text, v_btf.field_acres);
  END LOOP;

  IF v_field_ids IS NULL OR array_length(v_field_ids, 1) IS NULL THEN
    IF v_ticket.field_id IS NOT NULL THEN
      v_field_ids := ARRAY[v_ticket.field_id];
      SELECT COALESCE(v_ticket.total_acres, f.total_acres, 0) INTO v_field_acres
        FROM fields f WHERE f.id = v_ticket.field_id;
      v_applied_acres_map := jsonb_build_object(v_ticket.field_id::text, v_field_acres);
    ELSE
      RAISE EXCEPTION 'Blend ticket has no fields';
    END IF;
  END IF;

  v_shares    := derive_customer_shares_from_fields(v_field_ids, v_applied_acres_map);
  v_customers := v_shares -> 'customers';
  v_customer_count := jsonb_array_length(v_customers);

  IF v_customer_count = 0 THEN
    RAISE EXCEPTION 'No billing customers derived from blend ticket fields';
  END IF;

  IF v_ticket.application_service_id IS NOT NULL THEN
    SELECT * INTO v_app_service FROM application_services WHERE id = v_ticket.application_service_id;
    v_has_app_service := FOUND
                         AND (v_app_service IS NOT NULL)
                         AND COALESCE(v_app_service.is_active, false);
  END IF;

  v_quote_section_id := NULL;
  IF v_ticket.job_id IS NOT NULL THEN
    SELECT j.quote_section_id INTO v_quote_section_id FROM jobs j WHERE j.id = v_ticket.job_id;
  END IF;

  IF v_customer_count > 1 THEN
    v_invoice_group_id := gen_random_uuid();
  ELSE
    v_invoice_group_id := NULL;
  END IF;

  FOR v_customer IN SELECT * FROM jsonb_array_elements(v_customers)
  LOOP
    v_customer_id   := (v_customer->>'customer_id')::uuid;
    v_customer_name := v_customer->>'customer_name';
    v_customer_tier := COALESCE((v_customer->>'tier')::int, 1);
    v_is_primary    := COALESCE((v_customer->>'is_primary')::boolean, false);
    v_has_override  := COALESCE((v_customer->>'has_override')::boolean, false);

    v_invoice_total := 0;
    v_invoice_cost  := 0;
    v_invoice_number := next_invoice_number();

    INSERT INTO invoices (
      blend_ticket_id, customer_id, invoice_type, status, season,
      invoice_number, salesman_id, created_by,
      total_amount_cents, total_cost_cents,
      invoice_date, invoice_group_id, application_service_id
    ) VALUES (
      p_blend_ticket_id, v_customer_id, 'field_application', 'draft',
      COALESCE(v_ticket.season, current_season()),
      v_invoice_number, v_ticket.salesman_id, p_created_by,
      0, 0,
      CURRENT_DATE, v_invoice_group_id, v_ticket.application_service_id
    ) RETURNING id INTO v_invoice_id;

    v_invoice_ids := array_append(v_invoice_ids, v_invoice_id);

    FOR v_share_row IN
      SELECT * FROM jsonb_array_elements(v_shares -> 'rows') AS value
      WHERE (value ->> 'customer_id')::uuid = v_customer_id
        AND (value ->> 'price_override_cents') IS NOT NULL
    LOOP
      v_share_acres        := (v_share_row->>'share_acres')::numeric;
      v_field_override     := (v_share_row->>'price_override_cents')::bigint;
      v_field_pricing_note := v_share_row->>'pricing_note';
      v_grower_share_amount := safe_cents_qty(v_field_override, v_share_acres);

      INSERT INTO invoice_items (
        invoice_id, description, quantity, unit_size,
        unit_price_cents, extended_cents, cost_cents,
        sort_order, acres, rate_per_acre, rate_unit,
        is_application_fee, price_source
      ) VALUES (
        v_invoice_id,
        (v_share_row->>'field_name') || ' — grower share @ $' ||
          (v_field_override / 100.0)::numeric(12,2) || '/ac' ||
          CASE WHEN v_field_pricing_note IS NOT NULL AND v_field_pricing_note <> ''
               THEN ' (' || v_field_pricing_note || ')' ELSE '' END,
        v_share_acres, 'acre',
        v_field_override, v_grower_share_amount, 0,
        0, v_share_acres, v_field_override, 'acre',
        false, 'manual'
      );
      v_invoice_total := v_invoice_total + v_grower_share_amount;
    END LOOP;

    FOR v_btp IN
      SELECT btp.*, p.tier1_price, p.tier2_price, p.tier3_price,
             p.product_name AS full_product_name, p.current_cost AS product_cost,
             p.unit_size, p.rate_unit,
             -- A5: inventory unit + form drive the rate->pricing-unit conversion
             p.inventory_unit, p.product_form
        FROM blend_ticket_products btp
        LEFT JOIN products p ON p.id = btp.product_id
       WHERE btp.blend_ticket_id = p_blend_ticket_id
       ORDER BY btp.sequence_order
    LOOP
      v_chem_qty_a := 0;
      v_chem_qty_b := 0;
      v_rate := COALESCE(v_btp.rate_per_acre, 0);

      FOR v_share_row IN
        SELECT * FROM jsonb_array_elements(v_shares -> 'rows') AS value
        WHERE (value ->> 'customer_id')::uuid = v_customer_id
      LOOP
        v_share_acres := (v_share_row->>'share_acres')::numeric;
        IF (v_share_row->>'price_override_cents') IS NOT NULL THEN
          v_chem_qty_a := v_chem_qty_a + (v_rate * v_share_acres);
        ELSE
          v_chem_qty_b := v_chem_qty_b + (v_rate * v_share_acres);
        END IF;
      END LOOP;

      -- A5: convert the accumulated rate-unit quantities to the product's inventory
      -- (pricing) unit so money = price/inventory-unit x qty/inventory-unit. Unmatched
      -- products (no product row) keep the raw quantity (no price, nothing to convert).
      -- Convertibility was pre-validated above, so the helper is non-NULL here.
      -- Display units keep their original casing; the helper gets normalized units
      -- (strips /ac + maps plural/spelled aliases) so oz/ac, gallons, etc. convert.
      v_rate_unit_line := COALESCE(NULLIF(btrim(v_btp.rate_per_acre_unit), ''), v_btp.rate_unit);
      v_inv_unit_line  := COALESCE(NULLIF(btrim(v_btp.inventory_unit), ''), v_btp.unit_size);
      IF v_btp.product_id IS NOT NULL THEN
        v_chem_qty_a_conv := field_app_priced_quantity(v_chem_qty_a, normalize_rate_unit(v_rate_unit_line), normalize_rate_unit(v_inv_unit_line), v_btp.product_form);
        v_chem_qty_b_conv := field_app_priced_quantity(v_chem_qty_b, normalize_rate_unit(v_rate_unit_line), normalize_rate_unit(v_inv_unit_line), v_btp.product_form);
      ELSE
        v_chem_qty_a_conv := v_chem_qty_a;
        v_chem_qty_b_conv := v_chem_qty_b;
      END IF;

      IF v_chem_qty_a > 0 THEN
        INSERT INTO invoice_items (
          invoice_id, product_id, description, quantity, unit_size,
          unit_price_cents, extended_cents, cost_cents,
          sort_order, rate_per_acre, rate_unit,
          is_application_fee, price_source
        ) VALUES (
          v_invoice_id, v_btp.product_id,
          COALESCE(v_btp.full_product_name, v_btp.product_name) || ' — included in grower share',
          ROUND(v_chem_qty_a_conv, 4), v_inv_unit_line,
          0, 0, 0,
          v_btp.sequence_order, v_rate, v_rate_unit_line,
          false, 'manual'
        );
      END IF;

      IF v_chem_qty_b > 0 THEN
        v_unit_price   := NULL;
        v_quoted_price := NULL;
        v_price_source := NULL;

        IF v_btp.unit_price_cents IS NOT NULL THEN
          v_unit_price   := v_btp.unit_price_cents;
          v_price_source := 'manual';
        ELSIF v_quote_section_id IS NOT NULL AND v_btp.product_id IS NOT NULL THEN
          SELECT qi.price_per_unit INTO v_qi_price
            FROM quote_items qi
           WHERE qi.section_id = v_quote_section_id
             AND qi.product_id = v_btp.product_id
           ORDER BY qi.id LIMIT 1;
          IF v_qi_price IS NOT NULL THEN
            v_unit_price   := ROUND(v_qi_price * 100)::bigint;
            v_quoted_price := v_unit_price;
            v_price_source := 'quoted';
          END IF;
        END IF;

        IF v_unit_price IS NULL THEN
          IF v_btp.product_id IS NOT NULL THEN
            v_unit_price := CASE v_customer_tier
              WHEN 1 THEN COALESCE(ROUND(v_btp.tier1_price * 100), 0)
              WHEN 2 THEN COALESCE(ROUND(v_btp.tier2_price * 100), ROUND(v_btp.tier1_price * 100), 0)
              WHEN 3 THEN COALESCE(ROUND(v_btp.tier3_price * 100), ROUND(v_btp.tier1_price * 100), 0)
              ELSE COALESCE(ROUND(v_btp.tier1_price * 100), 0)
            END;
          ELSE
            v_unit_price := 0;
          END IF;
          IF v_price_source IS NULL THEN v_price_source := 'tier'; END IF;
        END IF;

        v_unit_cost := COALESCE(v_btp.unit_cost_cents,
                                ROUND(COALESCE(v_btp.product_cost, 0) * 100)::bigint, 0);
        v_extended := safe_cents_qty(v_unit_price, v_chem_qty_b_conv);

        INSERT INTO invoice_items (
          invoice_id, product_id, description, quantity, unit_size,
          unit_price_cents, extended_cents, cost_cents,
          sort_order, rate_per_acre, rate_unit,
          quoted_price_cents, is_application_fee, price_source
        ) VALUES (
          v_invoice_id, v_btp.product_id,
          COALESCE(v_btp.full_product_name, v_btp.product_name),
          ROUND(v_chem_qty_b_conv, 4), v_inv_unit_line,
          v_unit_price, v_extended, v_unit_cost,
          v_btp.sequence_order, v_rate, v_rate_unit_line,
          v_quoted_price, false, v_price_source
        );
        v_invoice_total := v_invoice_total + v_extended;
        v_invoice_cost  := v_invoice_cost + safe_cents_qty(v_unit_cost, v_chem_qty_b_conv);
      END IF;
    END LOOP;

    IF v_has_app_service THEN
      SELECT car.rate_per_acre_cents INTO v_fee_rate
        FROM customer_application_rates car
       WHERE car.customer_id            = v_customer_id
         AND car.application_service_id = v_ticket.application_service_id
         AND car.season                 = COALESCE(v_ticket.season, current_season())
       LIMIT 1;
      IF v_fee_rate IS NULL THEN v_fee_rate := v_app_service.default_rate_per_acre_cents; END IF;

      SELECT COALESCE(SUM((value->>'share_acres')::numeric), 0) INTO v_fee_acres
        FROM jsonb_array_elements(v_shares -> 'rows') AS value
       WHERE (value->>'customer_id')::uuid = v_customer_id
         AND (value->>'price_override_cents') IS NULL;

      IF v_fee_rate > 0 AND v_fee_acres > 0 THEN
        v_fee_extended := safe_cents_qty(v_fee_rate, v_fee_acres);
        v_fee_cost     := safe_cents_qty(v_app_service.cost_per_acre_cents, v_fee_acres);
        INSERT INTO invoice_items (
          invoice_id, description, quantity, unit_price_cents, extended_cents,
          cost_cents, sort_order, acres, rate_per_acre, rate_unit,
          is_application_fee, price_source
        ) VALUES (
          v_invoice_id, v_app_service.name, v_fee_acres,
          v_fee_rate, v_fee_extended, v_fee_cost,
          9999, v_fee_acres, v_fee_rate, 'acre',
          true, 'tier'
        );
        v_invoice_total := v_invoice_total + v_fee_extended;
        v_invoice_cost  := v_invoice_cost + v_fee_cost;
      END IF;
    END IF;

    UPDATE invoices SET
      total_amount_cents = v_invoice_total,
      total_cost_cents   = v_invoice_cost
    WHERE id = v_invoice_id;

    INSERT INTO financial_audit_log (
      operation_type, entity_type, entity_id, actor_role,
      new_values, total_impact_cents, description
    ) VALUES (
      'invoice_created', 'invoice', v_invoice_id,
      (SELECT role FROM profiles WHERE id = v_actor),
      jsonb_build_object(
        'invoice_number', v_invoice_number,
        'blend_ticket_number', v_ticket.ticket_number,
        'customer_id', v_customer_id,
        'total_cents', v_invoice_total
      ),
      v_invoice_total,
      'Invoice created from blend ticket ' || v_ticket.ticket_number
    );

    SELECT COALESCE(SUM((value->>'share_acres')::numeric), 0) INTO v_total_share_acres
      FROM jsonb_array_elements(v_shares -> 'rows') AS value
     WHERE (value->>'customer_id')::uuid = v_customer_id;

    INSERT INTO invoice_shares (
      invoice_id, customer_id, customer_name,
      split_percentage, acres, amount_cents,
      is_primary, sort_order,
      price_per_acre_cents, pricing_note
    ) VALUES (
      v_invoice_id, v_customer_id, v_customer_name,
      100.0, v_total_share_acres, v_invoice_total,
      v_is_primary, 0,
      CASE WHEN v_has_override THEN
        (SELECT (value->>'price_override_cents')::bigint
         FROM jsonb_array_elements(v_shares -> 'rows') AS value
         WHERE (value->>'customer_id')::uuid = v_customer_id
           AND (value->>'price_override_cents') IS NOT NULL LIMIT 1)
      ELSE NULL END,
      CASE WHEN v_has_override THEN
        (SELECT (value->>'pricing_note')
         FROM jsonb_array_elements(v_shares -> 'rows') AS value
         WHERE (value->>'customer_id')::uuid = v_customer_id
           AND (value->>'price_override_cents') IS NOT NULL LIMIT 1)
      ELSE NULL END
    );
  END LOOP;

  UPDATE blend_tickets SET payment_status = 'billed' WHERE id = p_blend_ticket_id;

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('invoice_created',
          'Invoice(s) created from blend ticket ' || v_ticket.ticket_number ||
            CASE WHEN v_invoice_group_id IS NOT NULL
                 THEN ' (group of ' || v_customer_count || ')' ELSE '' END,
          p_created_by, 'invoice', v_invoice_ids[1], v_ticket.customer_id);

  v_result := jsonb_build_object(
    'invoice_ids',      to_jsonb(v_invoice_ids),
    'invoice_group_id', v_invoice_group_id
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(
      p_idempotency_key,
      'create_invoice_from_blend_ticket',
      v_result
    );
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."create_invoice_from_blend_ticket"("p_blend_ticket_id" "uuid", "p_created_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_invoice_from_order"("p_order_id" "uuid", "p_salesman_id" "uuid" DEFAULT NULL::"uuid", "p_invoice_type" "text" DEFAULT 'chemical_sale'::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor          uuid := auth.uid();
  v_order          record;
  v_invoice_id     uuid;
  v_item           record;
  v_total_cents    bigint := 0;
  v_cost_cents     bigint := 0;
  v_existing       jsonb;
  v_existing_count int;
  v_delivery_count int;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'Not authorized: admin or sales role required to create invoices from orders';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'create_invoice_from_order');
    IF v_existing IS NOT NULL THEN RETURN (v_existing->>'invoice_id')::uuid; END IF;
  END IF;

  -- Codex P1: lock the order row FOR UPDATE before the existence checks below.
  -- create_delivery_with_items locks the order while it inserts a delivery; without
  -- this lock the invoice txn could read zero deliveries while a concurrent
  -- scheduled-delivery insert is still uncommitted, then create the order-level
  -- invoice anyway — recreating the exact double-billing this guard prevents.
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found: %', p_order_id; END IF;

  SELECT COUNT(*) INTO v_existing_count
    FROM invoices
   WHERE order_id = p_order_id
     AND status NOT IN ('voided', 'cancelled');
  IF v_existing_count > 0 THEN
    RAISE EXCEPTION 'Active invoice already exists for order % (% existing invoice(s)). Void or cancel the existing invoice first if you need to recreate.', v_order.order_number, v_existing_count;
  END IF;

  -- W5 (sell-side #4): the order is being fulfilled via deliveries, which each
  -- produce their own invoice on completion — a manual order-level invoice here
  -- would double-represent the order. The check above only catches deliveries
  -- that ALREADY produced an invoice; a still scheduled/in_progress delivery has
  -- none yet, so this closes that gap.
  SELECT COUNT(*) INTO v_delivery_count
    FROM deliveries
   WHERE order_id = p_order_id
     AND status NOT IN ('cancelled', 'voided');
  IF v_delivery_count > 0 THEN
    RAISE EXCEPTION 'Cannot create an order-level invoice for order % — it has % active delivery(ies); invoices are created per delivery on completion. Cancel/void those deliveries first to bill the whole order manually.', v_order.order_number, v_delivery_count;
  END IF;

  INSERT INTO invoices (
    order_id, customer_id, invoice_type, status, season,
    salesman_id, created_by, total_amount_cents, invoice_date
  ) VALUES (
    p_order_id, v_order.customer_id, p_invoice_type, 'draft',
    COALESCE(v_order.season, (SELECT current_season())),
    COALESCE(p_salesman_id, v_order.salesman_id),
    v_actor, 0, CURRENT_DATE
  )
  RETURNING id INTO v_invoice_id;

  FOR v_item IN
    SELECT * FROM order_items WHERE order_id = p_order_id ORDER BY sort_order NULLS LAST, id
  LOOP
    INSERT INTO invoice_items (
      invoice_id, order_item_id, product_id, description,
      quantity, unit_price_cents, extended_cents, cost_cents,
      sort_order, rate_per_acre, acres, unit_size
    ) VALUES (
      v_invoice_id, v_item.id, v_item.product_id,
      COALESCE(v_item.product_name, ''),
      v_item.total_units_needed,
      round(v_item.price_per_unit * 100)::bigint,
      round(v_item.total_price * 100)::bigint,
      round(v_item.cost_per_unit * 100)::bigint,
      COALESCE(v_item.sort_order, 0),
      v_item.actual_rate,
      v_item.acres,
      v_item.unit_size
    );
    v_total_cents := v_total_cents + round(v_item.total_price * 100)::bigint;
    v_cost_cents := v_cost_cents + round(COALESCE(v_item.cost_per_unit, 0) * v_item.total_units_needed * 100)::bigint;
  END LOOP;

  UPDATE invoices SET total_amount_cents = v_total_cents, total_cost_cents = v_cost_cents WHERE id = v_invoice_id;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    new_values, total_impact_cents, description
  ) VALUES (
    'invoice_created', 'invoice', v_invoice_id,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object(
      'invoice_number', (SELECT invoice_number FROM invoices WHERE id = v_invoice_id),
      'order_number', v_order.order_number,
      'customer_id', v_order.customer_id,
      'total_cents', v_total_cents
    ),
    v_total_cents,
    'Invoice created from order ' || v_order.order_number
  );

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('invoice_created',
    'Invoice created from order ' || v_order.order_number,
    v_actor, 'invoice', v_invoice_id, v_order.customer_id
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'create_invoice_from_order', jsonb_build_object('invoice_id', v_invoice_id));
  END IF;

  RETURN v_invoice_id;
END;
$$;


ALTER FUNCTION "public"."create_invoice_from_order"("p_order_id" "uuid", "p_salesman_id" "uuid", "p_invoice_type" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_job_from_quote_section"("p_quote_id" "uuid", "p_section_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_existing jsonb; v_quote RECORD; v_section RECORD; v_item RECORD;
  v_job_id uuid; v_job_number text; v_job_date date; v_season integer;
  v_total_acres numeric := 0; v_total_cost_cents bigint := 0;
  v_total_price_cents bigint := 0; v_sort integer := 0;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing FROM idempotency_keys WHERE idempotency_key = p_idempotency_key AND operation = 'create_job_from_quote_section';
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  -- U5 (Codex P2): lock the quote BEFORE the status checks so a concurrent
  -- convert/close (each takes this same row lock first) serializes with job
  -- scheduling — a plain read could pass the guards on a booking another
  -- transaction is mid-way through accepting or closing.
  SELECT q.* INTO v_quote FROM quotes q WHERE q.id = p_quote_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found: %', p_quote_id; END IF;
  IF NOT v_quote.is_planned THEN RAISE EXCEPTION 'Quote must be marked as planned to schedule a job'; END IF;

  -- U5<<< #103: an 'accepted' booking was converted to a chemical SALE (order +
  -- delivery). Scheduling a job from it would re-reserve/double-count the same
  -- product. Block with a distinct token so the UI can point the user to a
  -- standalone job instead. (finding #103, CONFIRMED 2026-07-05)
  IF v_quote.status = 'accepted' THEN
    RAISE EXCEPTION 'QUOTE_ALREADY_CONVERTED: quote % was accepted and converted to a chemical sale (order) — create a standalone job instead of scheduling from this booking', v_quote.quote_number;
  END IF;
  -- >>>U5

  IF v_quote.status IN ('declined', 'expired', 'cancelled', 'closed_by_application', 'closed_short') THEN
    RAISE EXCEPTION 'Cannot schedule job from quote with status: %', v_quote.status;
  END IF;

  SELECT qs.* INTO v_section FROM quote_sections qs WHERE qs.id = p_section_id AND qs.quote_id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Section not found or does not belong to quote'; END IF;

  IF EXISTS (SELECT 1 FROM jobs WHERE quote_section_id = p_section_id AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'A job already exists for this quote section. Delete or cancel the existing job first.';
  END IF;

  v_job_date := COALESCE(v_section.needed_by_date, CURRENT_DATE);
  v_season := CASE WHEN EXTRACT(MONTH FROM v_job_date) >= 10
    THEN EXTRACT(YEAR FROM v_job_date)::integer + 1 ELSE EXTRACT(YEAR FROM v_job_date)::integer END;
  v_job_number := next_job_number();

  INSERT INTO jobs (
    job_number, customer_id, status, job_date, notes, season, quote_id, quote_section_id,
    total_acres, total_cost_cents, total_price_cents, created_by,
    -- U8 (#99): snapshot the booking's commission split onto the job so pay attribution
    -- is locked at scheduling time (the same snapshot rule orders follow — a later quote
    -- or customer split edit must not re-attribute an already-scheduled job).
    commission_split
  ) VALUES (
    v_job_number, v_quote.customer_id, 'scheduled', v_job_date,
    COALESCE(v_section.section_name, 'Untitled') || COALESCE(': ' || v_section.section_header_notes, ''),
    v_season, p_quote_id, p_section_id, 0, 0, 0, v_actor,
    -- Codex R4 P1: a quote with no split locks the empty sentinel (no commission,
    -- order-channel parity) — NULL is reserved for pre-U8 jobs.
    COALESCE(v_quote.commission_split, '{"splits":[]}'::jsonb)
  ) RETURNING id INTO v_job_id;

  IF v_section.field_id IS NOT NULL THEN
    SELECT COALESCE(MAX(qi.acres), 0) INTO v_total_acres FROM quote_items qi WHERE qi.section_id = p_section_id;
    INSERT INTO job_fields (job_id, field_id, acres_to_treat, sort_order) VALUES (v_job_id, v_section.field_id, v_total_acres, 1);
  END IF;

  FOR v_item IN
    SELECT qi.product_id, qi.total_units_needed, qi.price_unit, qi.actual_rate, qi.rate_unit,
           qi.price_per_unit, qi.current_cost, qi.acres, qi.sort_order, p.unit_size
    FROM quote_items qi JOIN products p ON p.id = qi.product_id
    WHERE qi.section_id = p_section_id ORDER BY qi.sort_order
  LOOP
    v_sort := v_sort + 1;
    INSERT INTO job_chemicals (job_id, product_id, quantity, unit, rate_per_acre, rate_unit,
      cost_per_unit_cents, price_per_unit_cents, sort_order
    ) VALUES (v_job_id, v_item.product_id, COALESCE(v_item.total_units_needed, 0),
      COALESCE(v_item.price_unit, v_item.unit_size), v_item.actual_rate, v_item.rate_unit,
      ROUND(COALESCE(v_item.current_cost, 0) * 100)::bigint,
      ROUND(COALESCE(v_item.price_per_unit, 0) * 100)::bigint, v_sort);
    v_total_cost_cents := v_total_cost_cents + ROUND(COALESCE(v_item.current_cost, 0) * COALESCE(v_item.total_units_needed, 0) * 100)::bigint;
    v_total_price_cents := v_total_price_cents + ROUND(COALESCE(v_item.price_per_unit, 0) * COALESCE(v_item.total_units_needed, 0) * 100)::bigint;
  END LOOP;

  IF v_total_acres = 0 THEN
    SELECT COALESCE(MAX(qi.acres), 0) INTO v_total_acres FROM quote_items qi WHERE qi.section_id = p_section_id;
  END IF;
  UPDATE jobs SET total_acres = v_total_acres, total_cost_cents = v_total_cost_cents, total_price_cents = v_total_price_cents WHERE id = v_job_id;

  -- F1<<< 42P01 fix (plpgsql_check, 2026-06-10): the logging INSERT targeted
  -- the old log relation (named in the migration header; deliberately NOT
  -- spelled here — this comment lands in prosrc, and the self-verification
  -- block asserts the old relation name appears NOWHERE in the deployed
  -- body), which does not exist — every call aborted here at runtime.
  -- Re-pointed to activity_feed using its live column shape, the exact
  -- pattern draw_down_quote logs with; the old jsonb details payload
  -- (job_number / quote_id / quote_number / section_name) is folded into the
  -- description text. Event token 'job_created_from_quote' kept.
  INSERT INTO activity_feed (event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id)
  VALUES ('job_created_from_quote',
    'Job ' || v_job_number || ' scheduled from quote ' || v_quote.quote_number ||
    COALESCE(' — section ' || v_section.section_name, ''),
    v_actor, 'job', v_job_id, v_quote.customer_id);
  -- >>>F1

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'create_job_from_quote_section', jsonb_build_object('job_id', v_job_id));
  END IF;

  RETURN jsonb_build_object('job_id', v_job_id);
END;
$$;


ALTER FUNCTION "public"."create_job_from_quote_section"("p_quote_id" "uuid", "p_section_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_label_draft"("p_product_id" "uuid", "p_signal_word" "text" DEFAULT NULL::"text", "p_rei_hours" integer DEFAULT NULL::integer, "p_phi_days" integer DEFAULT NULL::integer, "p_epa_registration" "text" DEFAULT NULL::"text", "p_max_label_rate" numeric DEFAULT NULL::numeric, "p_max_label_rate_unit" "text" DEFAULT NULL::"text", "p_source_note" "text" DEFAULT ''::"text", "p_confidence" "text" DEFAULT 'low'::"text", "p_status" "text" DEFAULT 'pending'::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id   uuid := auth.uid();
  v_draft_id  uuid;
  v_cached    jsonb;
BEGIN
  -- Auth gate: admin only
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_user_id AND role = 'admin' AND is_active = true
  ) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: admin role required';
  END IF;

  -- A new draft is never created already-decided: clamp to a reviewable status so a row can't
  -- enter the queue as accepted/edited/rejected (which would bypass human review).
  IF p_status NOT IN ('pending', 'needs_manual') THEN
    p_status := 'pending';
  END IF;

  -- Non-negativity guard: regulatory intervals/rates can never be negative.
  -- (Reject at staging so an impossible value can't even be drafted.)
  IF p_rei_hours IS NOT NULL AND p_rei_hours < 0 THEN
    RAISE EXCEPTION 'INVALID_LABEL_VALUE: rei_hours must be >= 0 (got %)', p_rei_hours;
  END IF;
  IF p_phi_days IS NOT NULL AND p_phi_days < 0 THEN
    RAISE EXCEPTION 'INVALID_LABEL_VALUE: phi_days must be >= 0 (got %)', p_phi_days;
  END IF;
  IF p_max_label_rate IS NOT NULL AND p_max_label_rate < 0 THEN
    RAISE EXCEPTION 'INVALID_LABEL_VALUE: max_label_rate must be >= 0 (got %)', p_max_label_rate;
  END IF;

  -- Idempotency: return cached result if same key already processed
  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_cached
    FROM idempotency_keys
    WHERE idempotency_key = p_idempotency_key
      AND operation       = 'create_label_draft';
    IF FOUND THEN
      RETURN (v_cached->>'draft_id')::uuid;
    END IF;
  END IF;

  -- Insert the draft
  INSERT INTO product_label_drafts (
    product_id, signal_word, rei_hours, phi_days, epa_registration,
    max_label_rate, max_label_rate_unit,
    source_note, confidence, status, created_by, run_idempotency_key
  ) VALUES (
    p_product_id, p_signal_word, p_rei_hours, p_phi_days, p_epa_registration,
    p_max_label_rate, p_max_label_rate_unit,
    p_source_note, p_confidence, p_status, v_user_id, p_idempotency_key
  )
  RETURNING id INTO v_draft_id;

  -- Store idempotency result
  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'create_label_draft', jsonb_build_object('draft_id', v_draft_id))
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_draft_id;
END;
$$;


ALTER FUNCTION "public"."create_label_draft"("p_product_id" "uuid", "p_signal_word" "text", "p_rei_hours" integer, "p_phi_days" integer, "p_epa_registration" "text", "p_max_label_rate" numeric, "p_max_label_rate_unit" "text", "p_source_note" "text", "p_confidence" "text", "p_status" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_order_from_blend_ticket"("p_blend_ticket_id" "uuid", "p_order_number" "text", "p_order_date" "date" DEFAULT CURRENT_DATE, "p_notes" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT "auth"."uid"(), "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_ticket      blend_tickets%ROWTYPE;
  v_order_id    uuid;
  v_customer    customers%ROWTYPE;
  v_product     blend_ticket_products%ROWTYPE;
  v_db_product  products%ROWTYPE;
  v_item_id     uuid;
  v_tier        int;
  v_price       numeric;
  v_cost        numeric;
  v_total_price numeric := 0;
  v_total_cost  numeric := 0;
  v_item_count  int := 0;
  v_invalid_count int;
  v_link_result json;
  v_cached      jsonb;
  v_result      jsonb;
  -- A5: quantity converted to the product's inventory unit + the unit label to store
  v_qty_conv    numeric;
  v_unit_out    text;
  -- Per-blend-line mappings retain the ticket quantity/unit truth. The order
  -- line and inventory transaction may use a converted inventory-unit value.
  v_mappings    jsonb := '[]'::jsonb;
BEGIN
  -- A5-actor: reject a forged actor / non-admin up front, mirroring the two sibling
  -- blend-ticket RPCs (create_invoice_/create_application_record_from_blend_ticket).
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales role required to create orders from blend tickets';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached := check_idempotency(p_idempotency_key, 'create_order_from_blend_ticket');
    IF v_cached IS NOT NULL THEN
      RETURN v_cached::json;
    END IF;
  END IF;

  SELECT * INTO v_ticket FROM blend_tickets WHERE id = p_blend_ticket_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Blend ticket not found');
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.invoices
     WHERE blend_ticket_id = p_blend_ticket_id
       AND deleted_at IS NULL
       AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
  ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_ACTIVE_INVOICE_ORDER_LOCKED';
  END IF;
  IF v_ticket.order_link_status = 'linked' THEN
    RETURN json_build_object('success', false, 'error', 'Blend ticket is already linked to an order');
  END IF;
  IF v_ticket.customer_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Blend ticket has no customer assigned');
  END IF;
  IF v_ticket.status <> 'completed' OR v_ticket.review_status <> 'approved' THEN
    RETURN json_build_object('success', false, 'error', 'Blend ticket must be completed and approved before creating an order');
  END IF;
  IF v_ticket.payment_status <> 'unbilled' THEN
    RETURN json_build_object('success', false, 'error', 'Only an unbilled blend ticket can create an order');
  END IF;

  SELECT count(*) FILTER (
           WHERE btp.product_id IS NULL
              OR btp.quantity <= 0
              OR btp.quantity::text IN ('NaN', 'Infinity', '-Infinity')
              OR p.id IS NULL
              OR p.is_active IS DISTINCT FROM true
         )
    INTO v_invalid_count
    FROM blend_ticket_products btp
    LEFT JOIN products p ON p.id = btp.product_id
   WHERE btp.blend_ticket_id = p_blend_ticket_id;

  IF NOT EXISTS (
    SELECT 1 FROM blend_ticket_products
     WHERE blend_ticket_id = p_blend_ticket_id
  ) THEN
    RETURN json_build_object('success', false, 'error', 'Blend ticket has no products');
  END IF;
  IF v_invalid_count > 0 THEN
    RETURN json_build_object('success', false, 'error', 'Every blend-ticket product must be matched to an active catalog product with a positive quantity');
  END IF;

  SELECT * INTO v_customer FROM customers WHERE id = v_ticket.customer_id AND is_active = true;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Customer not found');
  END IF;
  v_tier := COALESCE(v_customer.assigned_tier, 1);

  -- CHANGED: Removed total_paid and balance_due from INSERT (AR tracked via invoices)
  v_order_id := gen_random_uuid();
  INSERT INTO orders (id, order_number, customer_id, status, order_date, notes, season, salesman_id, total_price, total_cost, total_profit, total_margin_pct)
  VALUES (
    v_order_id,
    p_order_number,
    v_ticket.customer_id,
    'confirmed',
    p_order_date,
    COALESCE(p_notes, 'Created from blend ticket ' || v_ticket.ticket_number),
    v_ticket.season,
    v_ticket.salesman_id,
    0, 0, 0, 0
  );

  FOR v_product IN
    SELECT * FROM blend_ticket_products
    WHERE blend_ticket_id = p_blend_ticket_id
    ORDER BY sequence_order
  LOOP
    v_price := 0;
    v_cost := 0;
    -- A5: default for an unmatched product (no product row) — no price, no conversion.
    v_qty_conv := v_product.quantity;
    v_unit_out := COALESCE(v_product.unit, 'ea');

    IF v_product.product_id IS NOT NULL THEN
      SELECT * INTO v_db_product FROM products WHERE id = v_product.product_id;
      IF FOUND THEN
        v_price := CASE v_tier
          WHEN 1 THEN COALESCE(v_db_product.tier1_price, 0)
          WHEN 2 THEN COALESCE(v_db_product.tier2_price, 0)
          WHEN 3 THEN COALESCE(v_db_product.tier3_price, 0)
          ELSE COALESCE(v_db_product.tier1_price, 0)
        END;
        v_cost := COALESCE(v_db_product.current_cost, 0);
        -- A5: convert the stored quantity (in v_product.unit) to the inventory unit
        -- so total_price, prebook, and the inventory txn all use the pricing/stock unit.
        v_qty_conv := field_app_priced_quantity(
                        v_product.quantity,
                        normalize_rate_unit(NULLIF(btrim(v_product.unit), '')),
                        normalize_rate_unit(COALESCE(NULLIF(btrim(v_db_product.inventory_unit), ''), v_db_product.unit_size)),
                        v_db_product.product_form);
        IF v_qty_conv IS NULL
           OR v_qty_conv <= 0
           OR v_qty_conv::text IN ('NaN', 'Infinity', '-Infinity') THEN
          RAISE EXCEPTION 'BLEND_TICKET_UNIT_UNCONVERTIBLE: product % quantity unit "%" cannot convert to inventory unit "%"',
            v_product.product_name, v_product.unit, COALESCE(v_db_product.inventory_unit, v_db_product.unit_size);
        END IF;
        v_unit_out := COALESCE(NULLIF(btrim(v_db_product.inventory_unit), ''), v_db_product.unit_size, v_product.unit, 'ea');
      END IF;
    END IF;

    v_item_id := gen_random_uuid();
    INSERT INTO order_items (
      id, order_id, product_id, product_name, price_per_unit, cost_per_unit,
      actual_rate, rate_unit, acres, total_units_needed, unit_size,
      total_price, profit, net_margin, quantity_delivered, quantity_remaining, sort_order
    )
    VALUES (
      v_item_id,
      v_order_id,
      v_product.product_id,
      v_product.product_name,
      v_price,
      v_cost,
      v_product.rate_per_acre,
      v_product.rate_per_acre_unit,
      v_ticket.total_acres,
      v_qty_conv,
      v_unit_out,
      v_price * v_qty_conv,
      (v_price - v_cost) * v_qty_conv,
      CASE WHEN v_price > 0 THEN ((v_price - v_cost) / v_price * 100) ELSE 0 END,
      0,
      v_qty_conv,
      v_product.sequence_order
    );

    -- Preserve exact blend-line identity and source quantity for link validation.
    IF v_product.product_id IS NOT NULL THEN
      v_mappings := v_mappings || jsonb_build_object(
        'blend_product_id', v_product.id,
        'order_item_id', v_item_id,
        'quantity_applied', v_product.quantity
      );
    END IF;

    IF v_product.product_id IS NOT NULL AND v_qty_conv > 0 THEN
      INSERT INTO inventory (
        product_id, location, quantity_available,
        quantity_prebooked, quantity_on_order, unit_size, updated_at
      ) VALUES (
        v_product.product_id, 'Main Warehouse', 0,
        v_qty_conv, 0, v_unit_out, now()
      )
      ON CONFLICT (product_id, location) DO UPDATE
        SET quantity_prebooked = COALESCE(inventory.quantity_prebooked, 0)
                                 + EXCLUDED.quantity_prebooked,
            updated_at = now();

      INSERT INTO inventory_transactions (
        product_id, transaction_type, quantity, to_location,
        order_id, performed_by, notes
      ) VALUES (
        v_product.product_id, 'booked', v_qty_conv, 'Main Warehouse',
        v_order_id, p_performed_by,
        'Prebooked for blend ticket order ' || p_order_number
      );
    END IF;

    v_total_price := v_total_price + (v_price * v_qty_conv);
    v_total_cost := v_total_cost + (v_cost * v_qty_conv);
    v_item_count := v_item_count + 1;
  END LOOP;

  -- CHANGED: Removed balance_due from UPDATE (AR tracked via invoices)
  UPDATE orders
  SET total_price = v_total_price,
      total_cost = v_total_cost,
      total_profit = v_total_price - v_total_cost,
      total_margin_pct = CASE WHEN v_total_price > 0 THEN ((v_total_price - v_total_cost) / v_total_price * 100) ELSE 0 END
  WHERE id = v_order_id;

  v_link_result := link_blend_ticket_to_order(p_blend_ticket_id, v_order_id, v_mappings, p_performed_by);
  IF COALESCE((v_link_result->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'BLEND_TICKET_ORDER_LINK_FAILED: %', COALESCE(v_link_result->>'error', 'unknown link failure');
  END IF;

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id)
  VALUES (
    'order_created_from_blend_ticket',
    'Order ' || p_order_number || ' created from blend ticket ' || v_ticket.ticket_number,
    p_performed_by,
    'order',
    v_order_id
  );

  v_result := jsonb_build_object(
     'success', true,
     'order_id', v_order_id,
     'order_number', p_order_number,
     'items_created', v_item_count,
     'total_price', v_total_price
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(
      p_idempotency_key,
      'create_order_from_blend_ticket',
      v_result
    );
  END IF;

  RETURN v_result::json;
END;
$$;


ALTER FUNCTION "public"."create_order_from_blend_ticket"("p_blend_ticket_id" "uuid", "p_order_number" "text", "p_order_date" "date", "p_notes" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_planned_holds"("p_quote_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_quote quotes%ROWTYPE;
  v_holds_created integer := 0;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'create_planned_holds' AND created_at > now() - interval '24 hours'
    ) THEN
      RETURN jsonb_build_object('status', 'duplicate', 'message', 'Already processed');
    END IF;
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'create_planned_holds', to_jsonb(p_quote_id));
  END IF;

  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Quote not found: %', p_quote_id;
  END IF;

  IF NOT v_quote.is_planned THEN
    RAISE EXCEPTION 'Quote is not marked as planned: %', p_quote_id;
  END IF;

  -- Planned-hold sync (20260611132115): the rebuild now reserves
  -- GREATEST(booked − drawn, 0) per product instead of the full booked
  -- quantity — quantity already drawn to orders lives in
  -- inventory.quantity_prebooked and must not be reserved twice.
  v_holds_created := _sync_planned_holds(p_quote_id, v_actor);

  RETURN jsonb_build_object('status', 'created', 'holds_created', v_holds_created);
END;
$$;


ALTER FUNCTION "public"."create_planned_holds"("p_quote_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_prepay_check_splits"("p_customer_id" "uuid", "p_reference_number" "text", "p_splits" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_expected_total_cents" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor         uuid;
  v_actor_role    text;
  v_split         jsonb;
  v_total_cents   bigint := 0;
  v_credit_id     uuid;
  v_credit_ids    uuid[] := '{}';
  v_label         text;
  v_amount_cents  bigint;
  v_season        integer;
  v_result        jsonb;
  v_existing      jsonb;
  v_declared_split_total bigint;
  v_expected_total_cents bigint;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  -- Codex P1 fix (2026-05-16): include is_active = true so deactivated admins
  -- with still-valid JWTs cannot create prepay credits.
  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role != 'admin' THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: only active admins can create prepay credits';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'create_prepay_check_splits');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF p_splits IS NULL OR jsonb_typeof(p_splits) <> 'array' OR jsonb_array_length(p_splits) = 0 THEN
    RAISE EXCEPTION 'INVALID_SPLITS: at least one split is required';
  END IF;
  SELECT COALESCE(SUM(NULLIF(split->>'amount_cents', '')::bigint), 0)
    INTO v_declared_split_total
    FROM jsonb_array_elements(p_splits) split;

  -- A missing value identifies a pre-deploy/stale client. Its historical contract
  -- declared the check total only through the splits themselves, so preserve that
  -- behavior during rollout. New clients send the independent expected total.
  v_expected_total_cents := COALESCE(p_expected_total_cents, v_declared_split_total);
  IF v_expected_total_cents <= 0 THEN
    RAISE EXCEPTION 'INVALID_CHECK_TOTAL: expected check total must be positive';
  END IF;

  IF v_declared_split_total IS DISTINCT FROM v_expected_total_cents THEN
    RAISE EXCEPTION 'PREPAY_SPLIT_TOTAL_MISMATCH: split total % must equal check total %',
      v_declared_split_total, v_expected_total_cents
      USING ERRCODE = 'P0001';
  END IF;

  v_season := current_season();

  FOR v_split IN SELECT * FROM jsonb_array_elements(p_splits)
  LOOP
    v_label        := NULLIF(v_split->>'label', '');
    v_amount_cents := (v_split->>'amount_cents')::bigint;

    IF v_amount_cents IS NULL OR v_amount_cents <= 0 THEN
      RAISE EXCEPTION 'INVALID_AMOUNT: each split amount must be positive (got %)', v_amount_cents;
    END IF;

    INSERT INTO prepay_credits (
      customer_id, season, original_amount_cents, balance_cents,
      payment_method, reference_number, notes, created_by,
      source_type, source_reference, bucket_label
    ) VALUES (
      p_customer_id, v_season, v_amount_cents, v_amount_cents,
      'check', p_reference_number,
      'Check #' || p_reference_number || COALESCE(' — ' || v_label, ''),
      v_actor, 'check', p_reference_number, v_label
    )
    RETURNING id INTO v_credit_id;

    v_credit_ids  := v_credit_ids || v_credit_id;
    v_total_cents := v_total_cents + v_amount_cents;
  END LOOP;

  UPDATE customers
     SET prepay_balance_cents = COALESCE(prepay_balance_cents, 0) + v_total_cents,
         updated_at = now()
   WHERE id = p_customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CUSTOMER_NOT_FOUND: %', p_customer_id;
  END IF;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    new_values, total_impact_cents, description
  ) VALUES (
    'prepay_credit_created', 'prepay_credit', p_customer_id,
    v_actor_role,
    jsonb_build_object(
      'reference_number', p_reference_number,
      'split_count', jsonb_array_length(p_splits),
      'credit_ids', to_jsonb(v_credit_ids),
      'total_cents', v_total_cents
    ),
    v_total_cents,
    'Check #' || p_reference_number || ' split into ' ||
      jsonb_array_length(p_splits) || ' bucket(s) — $' ||
      (v_total_cents / 100.0)::numeric(12,2)
  );

  v_result := jsonb_build_object(
    'success', true,
    'credit_ids', to_jsonb(v_credit_ids),
    'total_cents', v_total_cents,
    'split_count', jsonb_array_length(p_splits)
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'create_prepay_check_splits', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."create_prepay_check_splits"("p_customer_id" "uuid", "p_reference_number" "text", "p_splits" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text", "p_expected_total_cents" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_pricing_workbook_export"("p_product_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_request_fp text;
  v_export public.pricing_workbook_exports%ROWTYPE;
  v_export_id uuid;
  v_manifest_fp text;
  v_row_count integer;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;

  v_request_fp := md5(jsonb_build_object(
    'actor_id', v_actor,
    'product_ids', COALESCE(to_jsonb(p_product_ids), 'null'::jsonb)
  )::text);
  v_existing := public.check_idempotency(p_idempotency_key, 'create_pricing_workbook_export');
  IF v_existing IS NOT NULL THEN
    IF v_existing->>'actor_id' IS DISTINCT FROM v_actor::text
       OR v_existing->>'request_fingerprint' IS DISTINCT FROM v_request_fp THEN
      RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH';
    END IF;
    RETURN v_existing->'response';
  END IF;

  -- The shared cache expires after 24 hours. The export row and retained
  -- manifest are the durable receipt, so only the exact original actor,
  -- payload fingerprint, and idempotency key may replay it.
  SELECT * INTO v_export
  FROM public.pricing_workbook_exports e
  WHERE e.idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_export.created_by IS DISTINCT FROM v_actor
       OR v_export.request_fingerprint IS DISTINCT FROM v_request_fp THEN
      RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH';
    END IF;

    SELECT jsonb_build_object(
      'export_id', e.id,
      'manifest_fingerprint', e.manifest_fingerprint,
      'expires_at', e.expires_at,
      'rows', (
        SELECT jsonb_agg(jsonb_build_object(
          'product_id', r.product_id,
          'sku', COALESCE(r.sku_snapshot, ''),
          'product_name', r.product_name_snapshot,
          'category', COALESCE(r.category_snapshot, ''),
          'container_size', COALESCE(r.container_size_snapshot, ''),
          'unit_size', COALESCE(r.unit_size_snapshot, ''),
          'inventory_unit', COALESCE(r.inventory_unit_snapshot, ''),
          'identity_fingerprint', r.identity_fingerprint,
          'row_token', r.row_token,
          'row_version', r.row_version,
          'current_cost', COALESCE(public._format_pricing_dollars(r.current_cost_cents), ''),
          'current_tier1_margin_percent', COALESCE(public._format_pricing_margin_percent(r.current_tier1_margin), ''),
          'current_tier1_price', COALESCE(public._format_pricing_dollars(r.current_tier1_price_cents), ''),
          'current_tier2_margin_percent', COALESCE(public._format_pricing_margin_percent(r.current_tier2_margin), ''),
          'current_tier2_price', COALESCE(public._format_pricing_dollars(r.current_tier2_price_cents), ''),
          'current_tier3_margin_percent', COALESCE(public._format_pricing_margin_percent(r.current_tier3_margin), ''),
          'current_tier3_price', COALESCE(public._format_pricing_dollars(r.current_tier3_price_cents), '')
        ) ORDER BY r.product_id)
        FROM public.pricing_workbook_export_rows r
        WHERE r.export_id = e.id
      )
    ) INTO v_result
    FROM public.pricing_workbook_exports e
    WHERE e.id = v_export.id;

    RETURN v_result;
  END IF;

  IF p_product_ids IS NOT NULL AND (
    cardinality(p_product_ids) = 0
    OR cardinality(p_product_ids) <> (SELECT count(DISTINCT x) FROM unnest(p_product_ids) x)
  ) THEN
    RAISE EXCEPTION 'EXPORT_PRODUCT_IDS_INVALID';
  END IF;

  INSERT INTO public.pricing_workbook_exports(
    created_by, request_fingerprint, manifest_fingerprint,
    idempotency_key, row_count
  ) VALUES (
    v_actor, v_request_fp, 'pending', p_idempotency_key, 1
  ) RETURNING id INTO v_export_id;

  INSERT INTO public.pricing_workbook_export_rows(
    export_id, product_id, sku_snapshot, product_name_snapshot,
    category_snapshot, container_size_snapshot, unit_size_snapshot,
    inventory_unit_snapshot, identity_fingerprint, row_token, row_version,
    current_cost_cents,
    current_tier1_margin, current_tier1_price_cents,
    current_tier2_margin, current_tier2_price_cents,
    current_tier3_margin, current_tier3_price_cents
  )
  WITH export_products AS (
    SELECT
      p.id, p.sku, p.product_name, p.category,
      p.container_size::text AS container_size_text,
      p.unit_size, p.inventory_unit, p.pricing_version,
      md5(jsonb_build_object(
        'product_id', p.id,
        'sku', COALESCE(p.sku, ''),
        'product_name', p.product_name,
        'category', COALESCE(p.category, ''),
        'container_size', COALESCE(p.container_size::text, ''),
        'unit_size', COALESCE(p.unit_size, ''),
        'inventory_unit', COALESCE(p.inventory_unit, '')
      )::text) AS identity_fp,
      CASE WHEN p.current_cost IS NULL THEN NULL ELSE round(p.current_cost * 100)::bigint END AS cost_cents,
      p.tier1_margin,
      CASE WHEN p.tier1_price IS NULL THEN NULL ELSE round(p.tier1_price * 100)::bigint END AS tier1_price_cents,
      p.tier2_margin,
      CASE WHEN p.tier2_price IS NULL THEN NULL ELSE round(p.tier2_price * 100)::bigint END AS tier2_price_cents,
      p.tier3_margin,
      CASE WHEN p.tier3_price IS NULL THEN NULL ELSE round(p.tier3_price * 100)::bigint END AS tier3_price_cents
    FROM public.products p
    WHERE p.is_active = true
      AND (p_product_ids IS NULL OR p.id = ANY(p_product_ids))
  )
  SELECT
    v_export_id, ep.id, ep.sku, ep.product_name,
    ep.category, ep.container_size_text, ep.unit_size, ep.inventory_unit,
    ep.identity_fp,
    md5(jsonb_build_object(
      'export_id', v_export_id,
      'product_id', ep.id,
      'identity_fingerprint', ep.identity_fp,
      'row_version', ep.pricing_version,
      'current_cost_cents', ep.cost_cents,
      'current_tier1_margin', ep.tier1_margin,
      'current_tier1_price_cents', ep.tier1_price_cents,
      'current_tier2_margin', ep.tier2_margin,
      'current_tier2_price_cents', ep.tier2_price_cents,
      'current_tier3_margin', ep.tier3_margin,
      'current_tier3_price_cents', ep.tier3_price_cents
    )::text),
    ep.pricing_version, ep.cost_cents,
    ep.tier1_margin, ep.tier1_price_cents,
    ep.tier2_margin, ep.tier2_price_cents,
    ep.tier3_margin, ep.tier3_price_cents
  FROM export_products ep
  ORDER BY ep.id;

  GET DIAGNOSTICS v_row_count = ROW_COUNT;
  IF v_row_count = 0 THEN RAISE EXCEPTION 'EXPORT_HAS_NO_PRODUCTS'; END IF;
  IF p_product_ids IS NOT NULL AND v_row_count <> cardinality(p_product_ids) THEN
    RAISE EXCEPTION 'EXPORT_PRODUCT_NOT_FOUND_OR_INACTIVE';
  END IF;

  SELECT md5(string_agg(
    product_id::text || ':' || identity_fingerprint || ':' || row_version::text,
    '|' ORDER BY product_id
  )) INTO v_manifest_fp
  FROM public.pricing_workbook_export_rows
  WHERE export_id = v_export_id;

  UPDATE public.pricing_workbook_exports
  SET row_count = v_row_count, manifest_fingerprint = v_manifest_fp
  WHERE id = v_export_id;

  SELECT jsonb_build_object(
    'export_id', e.id,
    'manifest_fingerprint', e.manifest_fingerprint,
    'expires_at', e.expires_at,
    'rows', (
      SELECT jsonb_agg(jsonb_build_object(
        'product_id', r.product_id,
        'sku', COALESCE(r.sku_snapshot, ''),
        'product_name', r.product_name_snapshot,
        'category', COALESCE(r.category_snapshot, ''),
        'container_size', COALESCE(r.container_size_snapshot, ''),
        'unit_size', COALESCE(r.unit_size_snapshot, ''),
        'inventory_unit', COALESCE(r.inventory_unit_snapshot, ''),
        'identity_fingerprint', r.identity_fingerprint,
        'row_token', r.row_token,
        'row_version', r.row_version,
        'current_cost', COALESCE(public._format_pricing_dollars(r.current_cost_cents), ''),
        'current_tier1_margin_percent', COALESCE(public._format_pricing_margin_percent(r.current_tier1_margin), ''),
        'current_tier1_price', COALESCE(public._format_pricing_dollars(r.current_tier1_price_cents), ''),
        'current_tier2_margin_percent', COALESCE(public._format_pricing_margin_percent(r.current_tier2_margin), ''),
        'current_tier2_price', COALESCE(public._format_pricing_dollars(r.current_tier2_price_cents), ''),
        'current_tier3_margin_percent', COALESCE(public._format_pricing_margin_percent(r.current_tier3_margin), ''),
        'current_tier3_price', COALESCE(public._format_pricing_dollars(r.current_tier3_price_cents), '')
      ) ORDER BY r.product_id)
      FROM public.pricing_workbook_export_rows r
      WHERE r.export_id = e.id
    )
  ) INTO v_result
  FROM public.pricing_workbook_exports e
  WHERE e.id = v_export_id;

  PERFORM public.save_idempotency(
    p_idempotency_key,
    'create_pricing_workbook_export',
    jsonb_build_object('actor_id', v_actor, 'request_fingerprint', v_request_fp, 'response', v_result)
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."create_pricing_workbook_export"("p_product_ids" "uuid"[], "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_quick_delivery"("p_customer_id" "uuid", "p_items" "jsonb", "p_driver_id" "uuid" DEFAULT NULL::"uuid", "p_scheduled_date" "date" DEFAULT CURRENT_DATE, "p_delivery_notes" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_skip_invoice" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid; v_actor_role text;
  v_order_id uuid; v_order_number text;
  v_delivery_id uuid; v_delivery_number text;
  v_invoice_id uuid; v_invoice_number text;
  v_item jsonb; v_order_item_id uuid; v_product record;
  v_inv record; v_total_cents bigint := 0; v_total_cost_cents bigint := 0;
  v_item_price_cents bigint; v_item_qty numeric; v_sort integer := 0;
  v_customer record; v_split jsonb;
  v_order_profit numeric; v_split_total numeric; v_net_available numeric;
  v_ar_balance_cents bigint; v_projected_cents bigint;
  v_credit_warning boolean := false; v_admin record;
  v_result jsonb; v_existing jsonb;
  -- U9 stock-policy WARN-NOT-BLOCK
  v_short_count int := 0;
  v_stock_warnings text[] := '{}';
  v_short_product_ids uuid[] := '{}';
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_actor_role
  FROM profiles
  WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep', 'driver') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: only admins, sales reps, and drivers can create quick deliveries';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'create_quick_delivery');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_customer FROM customers WHERE id = p_customer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found'; END IF;
  IF NOT v_customer.is_active THEN RAISE EXCEPTION 'Customer is inactive'; END IF;
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'At least one item is required';
  END IF;

  FOR v_item IN
    SELECT jsonb_build_object('product_id', sub.product_id::text, 'quantity', sub.quantity) AS item
      FROM (
        SELECT (elem->>'product_id')::uuid AS product_id,
               SUM((elem->>'quantity')::numeric) AS quantity
          FROM jsonb_array_elements(p_items) elem
         GROUP BY (elem->>'product_id')::uuid
      ) sub
  LOOP
    SELECT * INTO v_product FROM products WHERE id = (v_item->>'product_id')::uuid AND is_active = true;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Product not found or inactive: %', v_item->>'product_id';
    END IF;
    v_item_qty := (v_item->>'quantity')::numeric;

    SELECT * INTO v_inv FROM inventory
    WHERE product_id = v_product.id AND location = 'Main Warehouse' FOR UPDATE;
    v_net_available := COALESCE(v_inv.quantity_available, 0) - COALESCE(v_inv.quantity_prebooked, 0);
    -- U9: WARN-NOT-BLOCK (was: RAISE EXCEPTION 'Insufficient inventory ...').
    -- Same net-available math; delivery proceeds, short products are flagged/notified.
    IF NOT FOUND OR v_net_available < v_item_qty THEN
      v_short_count := v_short_count + 1;
      v_short_product_ids := array_append(v_short_product_ids, v_product.id);
      v_stock_warnings := array_append(v_stock_warnings,
        v_product.product_name || ': need ' || v_item_qty || ', only ' ||
        GREATEST(v_net_available, 0) || ' net available (' ||
        COALESCE(v_inv.quantity_available, 0) || ' on hand, ' ||
        COALESCE(v_inv.quantity_prebooked, 0) || ' prebooked)');
      -- U9 (Codex R2 P2): with NO Main Warehouse row the later prebook UPDATE
      -- would no-op and the shortage would vanish from the position math. Seed a
      -- zero row so the aggregate goes visibly negative (complete_job pattern).
      IF NOT FOUND THEN
        INSERT INTO inventory (product_id, location, quantity_available, quantity_prebooked, manufactured_at_delivery)
        VALUES (v_product.id, 'Main Warehouse', 0, 0, true)  -- surfaces on /integrity-cleanup (P4-7 phantom-row flag)
        ON CONFLICT DO NOTHING;
      END IF;
    END IF;

    v_item_price_cents := CASE v_customer.assigned_tier
      WHEN 1 THEN ROUND(COALESCE(v_product.tier1_price, 0) * 100)
      WHEN 2 THEN ROUND(COALESCE(v_product.tier2_price, v_product.tier1_price, 0) * 100)
      ELSE ROUND(COALESCE(v_product.tier3_price, v_product.tier1_price, 0) * 100)
    END;
    v_total_cents := v_total_cents + safe_cents_qty(v_item_price_cents, v_item_qty);
  END LOOP;

  IF COALESCE(v_customer.credit_limit_cents, 0) > 0 THEN
    SELECT COALESCE(SUM(balance_cents), 0) INTO v_ar_balance_cents
      FROM invoices WHERE customer_id = p_customer_id
        AND status IN ('draft', 'posted', 'overdue');
    v_projected_cents := v_ar_balance_cents + v_total_cents;
    IF v_projected_cents >= v_customer.credit_limit_cents THEN
      v_credit_warning := true;
      INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
      VALUES ('credit_limit_warning',
        'WARNING: Quick delivery for "' || v_customer.farm_name || '" projected to push AR exposure to $' ||
          (v_projected_cents / 100.0)::numeric(12,2) ||
          ' (limit $' || (v_customer.credit_limit_cents / 100.0)::numeric(12,2) ||
          '). Current AR (draft+posted+overdue) is $' || (v_ar_balance_cents / 100.0)::numeric(12,2) ||
          '. Delivery proceeded; review with finance.',
        v_actor, 'customer', p_customer_id, p_customer_id);
      FOR v_admin IN SELECT id FROM profiles WHERE role = 'admin' AND is_active = true LOOP
        INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
        VALUES (v_admin.id,
          'Credit Limit Exceeded — ' || v_customer.farm_name,
          'A quick delivery was created for ' || v_customer.farm_name ||
            ' that projects AR exposure to $' || (v_projected_cents / 100.0)::numeric(12,2) ||
            ', exceeding the $' || (v_customer.credit_limit_cents / 100.0)::numeric(12,2) ||
            ' credit limit. Current AR (incl. draft+overdue) is $' ||
            (v_ar_balance_cents / 100.0)::numeric(12,2) ||
            '. The delivery proceeded; please review.',
          'credit_warning', 'customer', p_customer_id);
      END LOOP;
    END IF;
  END IF;

  v_split := v_customer.default_commission_split;
  IF v_split IS NOT NULL AND v_split ? 'splits' AND jsonb_array_length(v_split->'splits') > 0 THEN
    SELECT COALESCE(SUM((elem->>'percentage')::numeric), 0)
      INTO v_split_total FROM jsonb_array_elements(v_split->'splits') elem;
    IF ABS(v_split_total - 100) > 0.01 THEN
      RAISE EXCEPTION 'Customer commission splits must sum to 100%% (got %.2f%%). Fix customer settings before creating delivery.', v_split_total;
    END IF;
  END IF;

  v_order_id := gen_random_uuid();
  v_order_number := generate_order_number();
  INSERT INTO orders (id, order_number, customer_id, status, order_date, notes, total_price, total_cost, total_profit, total_margin_pct, commission_split)
  VALUES (v_order_id, v_order_number, p_customer_id, 'confirmed', CURRENT_DATE, 'Quick delivery', 0, 0, 0, 0, v_customer.default_commission_split);

  v_delivery_id := gen_random_uuid();
  v_delivery_number := next_delivery_number();
  INSERT INTO deliveries (id, delivery_number, order_id, customer_id, assigned_driver, scheduled_date, status, delivery_notes, is_quick_delivery, created_by)
  VALUES (v_delivery_id, v_delivery_number, v_order_id, p_customer_id, p_driver_id, p_scheduled_date, 'scheduled', p_delivery_notes, true, v_actor);

  IF NOT p_skip_invoice THEN
    v_invoice_id := gen_random_uuid();
    v_invoice_number := next_invoice_number('chemical_sale');
    INSERT INTO invoices (id, invoice_number, invoice_type, order_id, delivery_id, customer_id, status, total_amount_cents, paid_amount_cents, prepay_applied_cents, invoice_date, is_quick_delivery, created_by)
    VALUES (v_invoice_id, v_invoice_number, 'chemical_sale', v_order_id, v_delivery_id, p_customer_id, 'draft', 0, 0, 0, CURRENT_DATE, true, v_actor);
  END IF;

  v_total_cents := 0;
  v_total_cost_cents := 0;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_sort := v_sort + 1;
    SELECT * INTO v_product FROM products WHERE id = (v_item->>'product_id')::uuid;
    v_item_qty := (v_item->>'quantity')::numeric;

    v_item_price_cents := CASE v_customer.assigned_tier
      WHEN 1 THEN ROUND(COALESCE(v_product.tier1_price, 0) * 100)
      WHEN 2 THEN ROUND(COALESCE(v_product.tier2_price, v_product.tier1_price, 0) * 100)
      ELSE ROUND(COALESCE(v_product.tier3_price, v_product.tier1_price, 0) * 100)
    END;

    v_total_cents := v_total_cents + safe_cents_qty(v_item_price_cents, v_item_qty);
    v_total_cost_cents := v_total_cost_cents + ROUND(COALESCE(v_product.current_cost, 0) * 100 * v_item_qty)::bigint;

    INSERT INTO order_items (order_id, product_id, product_name, total_units_needed, price_per_unit, cost_per_unit, quantity_delivered, quantity_remaining, total_price, profit, net_margin, sort_order)
    VALUES (
      v_order_id, v_product.id, v_product.product_name, v_item_qty,
      (v_item_price_cents / 100.0)::numeric,
      COALESCE(v_product.current_cost, 0),
      0, v_item_qty,
      (v_item_price_cents / 100.0)::numeric * v_item_qty,
      ((v_item_price_cents / 100.0)::numeric - COALESCE(v_product.current_cost, 0)) * v_item_qty,
      CASE WHEN (v_item_price_cents / 100.0)::numeric > 0
        THEN (((v_item_price_cents / 100.0)::numeric - COALESCE(v_product.current_cost, 0))
              / (v_item_price_cents / 100.0)::numeric) * 100
        ELSE 0
      END,
      v_sort)
    RETURNING id INTO v_order_item_id;

    INSERT INTO delivery_items (delivery_id, order_item_id, product_id, quantity, quantity_delivered, unit_size)
    VALUES (v_delivery_id, v_order_item_id, v_product.id, v_item_qty, 0, COALESCE(v_item->>'unit_size', v_product.unit_size));

    IF NOT p_skip_invoice THEN
      INSERT INTO invoice_items (invoice_id, order_item_id, product_id, description, quantity, unit_price_cents, extended_cents, cost_cents, sort_order)
      VALUES (v_invoice_id, v_order_item_id, v_product.id, v_product.product_name, v_item_qty, v_item_price_cents,
        safe_cents_qty(v_item_price_cents, v_item_qty), ROUND(COALESCE(v_product.current_cost, 0) * 100)::bigint, v_sort);
    END IF;

    UPDATE inventory SET quantity_prebooked = quantity_prebooked + v_item_qty, updated_at = now()
    WHERE product_id = v_product.id AND location = 'Main Warehouse';

    -- U9: flag the prebooked ledger row for review when the product was short.
    INSERT INTO inventory_transactions (product_id, transaction_type, quantity, order_id, delivery_id, performed_by, notes, requires_review)
    VALUES (v_product.id, 'prebooked', v_item_qty, v_order_id, v_delivery_id, v_actor,
      'Quick delivery prebooked: ' || v_delivery_number ||
        CASE WHEN v_product.id = ANY(v_short_product_ids) THEN ' [SHORT STOCK — review required]' ELSE '' END,
      v_product.id = ANY(v_short_product_ids));
  END LOOP;

  UPDATE orders SET total_price = (v_total_cents / 100.0)::numeric, total_cost = (v_total_cost_cents / 100.0)::numeric,
    total_profit = ((v_total_cents - v_total_cost_cents) / 100.0)::numeric,
    total_margin_pct = CASE WHEN v_total_cents > 0 THEN ROUND((v_total_cents - v_total_cost_cents)::numeric / v_total_cents * 100, 2) ELSE 0 END
  WHERE id = v_order_id;

  IF NOT p_skip_invoice THEN
    UPDATE invoices SET total_amount_cents = v_total_cents, total_cost_cents = v_total_cost_cents WHERE id = v_invoice_id;
  END IF;

  v_order_profit := (v_total_cents - v_total_cost_cents) / 100.0;
  PERFORM _insert_commissions_for_order(
    v_order_id, p_customer_id, v_order_profit,
    v_split, CURRENT_DATE
  );

  -- U9: short-stock WARN emit (mirrors the credit-limit warn+notify pattern above).
  IF v_short_count > 0 THEN
    INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
    VALUES ('quick_delivery_short_stock',
      'WARNING: Quick delivery ' || v_delivery_number || ' for "' || v_customer.farm_name ||
        '" created with ' || v_short_count || ' product(s) short on stock: ' ||
        array_to_string(v_stock_warnings, ' | ') ||
        '. Delivery proceeded; net inventory may be negative — review with the warehouse.',
      v_actor, 'delivery', v_delivery_id, p_customer_id);
    FOR v_admin IN SELECT id FROM profiles WHERE role = 'admin' AND is_active = true LOOP
      INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
      VALUES (v_admin.id,
        'Short Stock — Quick Delivery ' || v_delivery_number,
        'Quick delivery ' || v_delivery_number || ' for ' || v_customer.farm_name ||
          ' was created but ' || v_short_count || ' product(s) did not have enough stock: ' ||
          array_to_string(v_stock_warnings, ' | ') ||
          '. The delivery proceeded; please review inventory.',
        'stock_warning', 'delivery', v_delivery_id);
    END LOOP;
  END IF;

  INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_role, new_values, total_impact_cents, description)
  VALUES (
    'order_created', 'order', v_order_id, v_actor_role,
    jsonb_build_object(
      'order_number', v_order_number,
      'customer_id', p_customer_id,
      'customer_name', v_customer.farm_name,
      'total_cents', v_total_cents,
      'total_cost_cents', v_total_cost_cents,
      'is_quick_delivery', true,
      'delivery_id', v_delivery_id,
      'invoice_id', v_invoice_id,
      'credit_warning', v_credit_warning
    ),
    v_total_cents,
    'Quick delivery order ' || v_order_number || ' for ' || v_customer.farm_name ||
      ' — $' || (v_total_cents / 100.0)::numeric(12,2)
  );

  INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_role, new_values, total_impact_cents, description)
  VALUES (
    'delivery_created', 'delivery', v_delivery_id, v_actor_role,
    jsonb_build_object(
      'delivery_number', v_delivery_number,
      'order_id', v_order_id,
      'order_number', v_order_number,
      'customer_id', p_customer_id,
      'scheduled_date', p_scheduled_date,
      'assigned_driver', p_driver_id,
      'is_quick_delivery', true
    ),
    v_total_cents,
    'Delivery ' || v_delivery_number || ' scheduled for ' || p_scheduled_date::text ||
      ' (' || v_customer.farm_name || ')'
  );

  -- U9: additive result fields — warnings[] + stock_warning flag.
  v_result := jsonb_build_object('order_id', v_order_id, 'delivery_id', v_delivery_id, 'invoice_id', v_invoice_id,
    'order_number', v_order_number, 'delivery_number', v_delivery_number, 'invoice_number', v_invoice_number,
    'total_cents', v_total_cents, 'credit_warning', v_credit_warning,
    'stock_warning', (v_short_count > 0), 'short_stock_count', v_short_count,
    'warnings', to_jsonb(v_stock_warnings));

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'create_quick_delivery', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."create_quick_delivery"("p_customer_id" "uuid", "p_items" "jsonb", "p_driver_id" "uuid", "p_scheduled_date" "date", "p_delivery_notes" "text", "p_performed_by" "uuid", "p_idempotency_key" "text", "p_skip_invoice" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_quote_from_template"("p_template_id" "uuid", "p_customer_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_template quote_templates%ROWTYPE;
  v_customer customers%ROWTYPE;
  v_quote_id uuid;
  v_quote_number text;
  v_section jsonb;
  v_item jsonb;
  v_section_id uuid;
  v_tier_price numeric;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'create_quote_from_template' AND created_at > now() - interval '24 hours'
    ) THEN
      RETURN jsonb_build_object('status', 'duplicate', 'message', 'Already processed');
    END IF;
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'create_quote_from_template', to_jsonb(p_template_id));
  END IF;

  SELECT * INTO v_template FROM quote_templates WHERE id = p_template_id AND is_active = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'Template not found: %', p_template_id; END IF;

  SELECT * INTO v_customer FROM customers WHERE id = p_customer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found: %', p_customer_id; END IF;

  SELECT generate_quote_number() INTO v_quote_number;

  INSERT INTO quotes (quote_number, customer_id, created_by, tier, status, valid_days,
    commission_split)
  VALUES (v_quote_number, p_customer_id, v_actor, v_customer.assigned_tier, 'draft', 15,
    v_customer.default_commission_split)
  RETURNING id INTO v_quote_id;

  FOR v_section IN SELECT * FROM jsonb_array_elements(v_template.sections)
  LOOP
    INSERT INTO quote_sections (quote_id, section_name, sort_order, section_notes, section_header_notes)
    VALUES (v_quote_id, v_section->>'section_name', (v_section->>'sort_order')::integer,
      v_section->>'section_notes', v_section->>'section_header_notes')
    RETURNING id INTO v_section_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(v_section->'items')
    LOOP
      SELECT CASE v_customer.assigned_tier
        WHEN 1 THEN COALESCE(tier1_price, 0)
        WHEN 2 THEN COALESCE(tier2_price, tier1_price, 0)
        WHEN 3 THEN COALESCE(tier3_price, tier1_price, 0)
        ELSE COALESCE(tier1_price, 0)
      END INTO v_tier_price
      FROM products WHERE id = (v_item->>'product_id')::uuid;

      INSERT INTO quote_items (quote_id, section_id, product_id, sort_order, notes,
        price_per_unit, current_cost, suggested_rate, actual_rate, rate_unit, calc_mode)
      VALUES (v_quote_id, v_section_id, (v_item->>'product_id')::uuid,
        (v_item->>'sort_order')::integer, v_item->>'notes',
        v_tier_price,
        (SELECT current_cost FROM products WHERE id = (v_item->>'product_id')::uuid),
        v_item->>'suggested_rate', (v_item->>'actual_rate')::numeric,
        v_item->>'rate_unit', v_item->>'calc_mode');
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('status', 'created', 'quote_id', v_quote_id, 'quote_number', v_quote_number);
END;
$$;


ALTER FUNCTION "public"."create_quote_from_template"("p_template_id" "uuid", "p_customer_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_quote_version"("p_quote_id" "uuid", "p_performed_by" "uuid", "p_method" "text" DEFAULT 'presented'::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_quote quotes%ROWTYPE;
  v_version_number integer;
  v_snapshot jsonb;
  v_version_id uuid;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM 1 FROM idempotency_keys WHERE idempotency_key = p_idempotency_key AND operation = 'create_quote_version';
    IF FOUND THEN
      RETURN jsonb_build_object('status', 'duplicate', 'message', 'Already processed');
    END IF;
  END IF;

  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Quote not found: %', p_quote_id;
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1 INTO v_version_number
  FROM quote_versions WHERE quote_id = p_quote_id;

  SELECT jsonb_build_object(
    'quote', jsonb_build_object(
      'quote_number', v_quote.quote_number,
      'customer_id', v_quote.customer_id,
      'tier', v_quote.tier,
      'status', v_quote.status,
      'total_price', v_quote.total_price,
      'total_cost', v_quote.total_cost,
      'total_profit', v_quote.total_profit,
      'total_margin_pct', v_quote.total_margin_pct,
      'valid_days', v_quote.valid_days,
      'expires_at', v_quote.expires_at,
      'header_notes', v_quote.header_notes,
      'footer_notes', v_quote.footer_notes,
      'is_planned', v_quote.is_planned,
      'commission_split', v_quote.commission_split
    ),
    'sections', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'section_name', qs.section_name,
          'sort_order', qs.sort_order,
          'section_notes', qs.section_notes,
          'section_header_notes', qs.section_header_notes,
          'needed_by_date', qs.needed_by_date,
          'items', (
            SELECT COALESCE(jsonb_agg(
              jsonb_build_object(
                'product_id', qi.product_id,
                'product_name', p.product_name,
                'sku', p.sku,
                'sort_order', qi.sort_order,
                'notes', qi.notes,
                'price_per_unit', qi.price_per_unit,
                'current_cost', qi.current_cost,
                'suggested_rate', qi.suggested_rate,
                'actual_rate', qi.actual_rate,
                'rate_unit', qi.rate_unit,
                'oz_per_acre', qi.oz_per_acre,
                'price_per_acre', qi.price_per_acre,
                'acres', qi.acres,
                'total_units_needed', qi.total_units_needed,
                'unit_size', qi.unit_size,
                'profit', qi.profit,
                'total_price', qi.total_price,
                'net_margin', qi.net_margin,
                'calc_mode', qi.calc_mode,
                'price_unit', qi.price_unit
              ) ORDER BY qi.sort_order
            ), '[]'::jsonb)
            FROM quote_items qi
            JOIN products p ON p.id = qi.product_id
            WHERE qi.section_id = qs.id
          )
        ) ORDER BY qs.sort_order
      ), '[]'::jsonb)
      FROM quote_sections qs
      WHERE qs.quote_id = p_quote_id
    )
  ) INTO v_snapshot;

  INSERT INTO quote_versions (quote_id, version_number, sent_by, sent_at, sent_method, snapshot_data)
  VALUES (p_quote_id, v_version_number, v_actor, now(), p_method, v_snapshot)
  RETURNING id INTO v_version_id;

  UPDATE quotes SET status = 'sent', sent_at = now(), updated_at = now()
  WHERE id = p_quote_id;

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'create_quote_version', to_jsonb(v_version_id))
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'status', 'created',
    'version_id', v_version_id,
    'version_number', v_version_number
  );
END;
$$;


ALTER FUNCTION "public"."create_quote_version"("p_quote_id" "uuid", "p_performed_by" "uuid", "p_method" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_rebate_claim"("p_program_id" "uuid", "p_quantity" numeric, "p_claim_amount_cents" bigint, "p_order_id" "uuid" DEFAULT NULL::"uuid", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_product_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_year        int := EXTRACT(YEAR FROM current_date)::int;
  v_seq         int;
  v_claim_no    text;
  v_claim_id    uuid;
  v_existing    jsonb;
  v_result      jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  IF p_program_id IS NULL THEN RAISE EXCEPTION 'PROGRAM_REQUIRED'; END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 THEN RAISE EXCEPTION 'QUANTITY_INVALID'; END IF;
  IF p_claim_amount_cents IS NULL OR p_claim_amount_cents <= 0 THEN
    RAISE EXCEPTION 'CLAIM_AMOUNT_INVALID';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'create_rebate_claim');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  INSERT INTO public.rebate_claim_counters (year, next_value)
  VALUES (v_year, 2)
  ON CONFLICT (year) DO UPDATE
    SET next_value = public.rebate_claim_counters.next_value + 1
  RETURNING next_value - 1 INTO v_seq;

  v_claim_no := format('RC-%s-%s', v_year, lpad(v_seq::text, 4, '0'));

  INSERT INTO public.rebate_claims (
    program_id, order_id, customer_id, product_id,
    claim_number, quantity, claim_amount_cents, notes, status,
    created_by
  ) VALUES (
    p_program_id, p_order_id, p_customer_id, p_product_id,
    v_claim_no, p_quantity, p_claim_amount_cents, p_notes, 'pending',
    v_actor
  )
  RETURNING id INTO v_claim_id;

  v_result := jsonb_build_object(
    'success',      true,
    'claim_id',     v_claim_id,
    'claim_number', v_claim_no
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'create_rebate_claim', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."create_rebate_claim"("p_program_id" "uuid", "p_quantity" numeric, "p_claim_amount_cents" bigint, "p_order_id" "uuid", "p_customer_id" "uuid", "p_product_id" "uuid", "p_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_return"("p_return" "jsonb", "p_items" "jsonb" DEFAULT '[]'::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_return_id uuid;
  v_return_number text;
  v_order_id uuid;
  v_customer_id uuid;
  v_order_status text;
  v_item jsonb;
  v_order_item record;
  v_qty numeric;
  v_prior_qty numeric;
  v_count integer := 0;
  v_existing jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'create_return');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  v_customer_id := nullif(p_return->>'customer_id', '')::uuid;
  v_order_id := nullif(p_return->>'order_id', '')::uuid;
  IF v_customer_id IS NULL THEN RAISE EXCEPTION 'CUSTOMER_REQUIRED'; END IF;
  IF v_order_id IS NULL THEN RAISE EXCEPTION 'RETURN_ORDER_REQUIRED'; END IF;
  IF coalesce(btrim(p_return->>'reason'), '') = '' THEN RAISE EXCEPTION 'REASON_REQUIRED'; END IF;
  IF jsonb_array_length(COALESCE(p_items, '[]'::jsonb)) = 0 THEN RAISE EXCEPTION 'ITEMS_REQUIRED'; END IF;

  SELECT status INTO v_order_status FROM public.orders
  WHERE id = v_order_id AND customer_id = v_customer_id AND deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'RETURN_ORDER_CUSTOMER_MISMATCH'; END IF;
  IF v_order_status IN ('voided', 'cancelled') THEN
    RAISE EXCEPTION 'RETURN_SOURCE_ORDER_INACTIVE';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_items) item
    WHERE nullif(item->>'order_item_id', '') IS NULL
  ) THEN RAISE EXCEPTION 'RETURN_ORDER_ITEM_REQUIRED'; END IF;

  IF (SELECT count(*) FROM jsonb_array_elements(p_items)) <>
     (SELECT count(DISTINCT item->>'order_item_id') FROM jsonb_array_elements(p_items) item) THEN
    RAISE EXCEPTION 'DUPLICATE_RETURN_ORDER_ITEM';
  END IF;

  PERFORM 1
  FROM public.order_items oi
  JOIN jsonb_array_elements(p_items) item
    ON oi.id = (item->>'order_item_id')::uuid
  WHERE oi.order_id = v_order_id
  ORDER BY oi.id
  FOR UPDATE OF oi;

  IF (SELECT count(*) FROM jsonb_array_elements(p_items)) <>
     (SELECT count(*) FROM public.order_items oi
      JOIN jsonb_array_elements(p_items) item ON oi.id = (item->>'order_item_id')::uuid
      WHERE oi.order_id = v_order_id) THEN
    RAISE EXCEPTION 'RETURN_ORDER_ITEM_MISMATCH';
  END IF;

  v_return_number := public.next_return_number();
  INSERT INTO public.returns (
    return_number, customer_id, order_id, reason, reason_notes, notes, requested_by, status
  ) VALUES (
    v_return_number, v_customer_id, v_order_id, p_return->>'reason',
    p_return->>'reason_notes', p_return->>'notes', v_actor, 'requested'
  ) RETURNING id INTO v_return_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    SELECT * INTO v_order_item
    FROM public.order_items
    WHERE id = (v_item->>'order_item_id')::uuid AND order_id = v_order_id;

    v_qty := coalesce((v_item->>'quantity')::numeric, 0);
    IF v_qty <= 0 THEN RAISE EXCEPTION 'RETURN_QUANTITY_MUST_BE_POSITIVE'; END IF;
    IF coalesce(v_order_item.quantity_delivered, 0) <= 0 THEN
      RAISE EXCEPTION 'RETURN_SOURCE_NOT_DELIVERED';
    END IF;
    IF v_order_item.price_per_unit IS NULL THEN
      RAISE EXCEPTION 'RETURN_SOURCE_PRICE_MISSING';
    END IF;

    SELECT coalesce(sum(ri.quantity), 0) INTO v_prior_qty
    FROM public.return_items ri
    JOIN public.returns r ON r.id = ri.return_id
    WHERE ri.order_item_id = v_order_item.id
      AND r.deleted_at IS NULL
      AND r.status NOT IN ('rejected', 'cancelled');

    IF v_prior_qty + v_qty > v_order_item.quantity_delivered THEN
      RAISE EXCEPTION 'RETURN_QUANTITY_EXCEEDS_DELIVERED';
    END IF;

    INSERT INTO public.return_items (
      return_id, order_item_id, product_id, product_name, quantity, unit,
      unit_price_cents, extended_cents, condition, restock, sort_order, notes
    ) VALUES (
      v_return_id, v_order_item.id, v_order_item.product_id, v_order_item.product_name,
      v_qty, coalesce(v_order_item.unit_size, 'ea'),
      round(v_order_item.price_per_unit * 100)::bigint,
      round(v_qty * v_order_item.price_per_unit * 100)::bigint,
      coalesce(v_item->>'condition', 'unopened'),
      coalesce((v_item->>'restock')::boolean, false),
      coalesce((v_item->>'sort_order')::integer, v_count), v_item->>'notes'
    );
    v_count := v_count + 1;
  END LOOP;

  INSERT INTO public.activity_feed (
    event_type, description, performed_by, related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'return_requested', 'Return ' || v_return_number || ' requested for ' || v_count || ' product(s)',
    v_actor, 'return', v_return_id, v_customer_id
  );

  v_existing := jsonb_build_object(
    'success', true, 'return_id', v_return_id,
    'return_number', v_return_number, 'item_count', v_count
  );
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(p_idempotency_key, 'create_return', v_existing);
  END IF;
  RETURN v_existing;
END;
$$;


ALTER FUNCTION "public"."create_return"("p_return" "jsonb", "p_items" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_rush_order"("p_customer_id" "uuid", "p_items" "jsonb" DEFAULT '[]'::"jsonb", "p_notes" "text" DEFAULT NULL::"text", "p_customer_po_number" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor       uuid;
  v_actor_role  text;
  v_order_id    uuid;
  v_order_number text;
  v_item        jsonb;
  v_customer    record;
  v_product     record;
  v_cached      jsonb;
  v_result      jsonb;
  v_inv         record;
  v_warnings    text[] := '{}';
  v_qty         numeric;
  v_net_position numeric;
  v_tier        int;
  v_item_count  int := 0;
BEGIN
  -- ── canonical strict-actor ────────────────────────────────────────────────
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  -- Codex round 3 / Mason 2026-06-13: NARROWED to admin/sales_rep. Field-staff
  -- (driver/applicator) rush ordering is deferred — it needs scoped RLS read
  -- policies on orders/order_items + a PAGE_PERMISSIONS change (a security-model
  -- decision), so it becomes a proper future feature rather than a partial one.
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin','sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    -- Codex round-10 P1: serialize same-key calls BEFORE the cache check. check_idempotency
    -- (read) → save_idempotency (write at end) is a TOCTOU: two concurrent same-key calls
    -- could both miss the cache and both create the order + prebook inventory + notify, with
    -- only the 2nd save_idempotency lost to the unique index (the duplicate business rows
    -- already committed). A transaction-scoped advisory lock keyed on the idempotency key
    -- makes the 2nd caller block until the 1st commits, after which check_idempotency below
    -- finds the saved result and returns it — no duplicate order/prebook/notification.
    -- Targeted (only same-key calls serialize; auto-released at txn end; placed after the
    -- auth/role gate so only authorized callers take it).
    PERFORM pg_advisory_xact_lock(hashtext('create_rush_order:' || p_idempotency_key));
    v_cached := check_idempotency(p_idempotency_key, 'create_rush_order');
    IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
  END IF;

  SELECT * INTO v_customer FROM customers WHERE id = p_customer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found: %', p_customer_id; END IF;
  v_tier := COALESCE(v_customer.assigned_tier, 1);

  SELECT count(*) INTO v_item_count
  FROM jsonb_array_elements(p_items) e
  WHERE (e->>'product_id') IS NOT NULL
    AND COALESCE((e->>'qty')::numeric, (e->>'quantity')::numeric, 0) > 0;
  IF v_item_count = 0 THEN RAISE EXCEPTION 'ITEMS_REQUIRED'; END IF;

  v_order_number := generate_order_number();

  -- Codex round-7 P1: SNAPSHOT the customer's commission split onto the order NOW,
  -- because rush-order commissions are DEFERRED to price_order (v2). If price_order
  -- re-read customers.default_commission_split at pricing time, a split change between
  -- ship and pricing would mis-attribute this sale. price_order uses orders.commission_split.
  -- (draw_down_quote snapshots the same way from the quote; create_direct_order doesn't
  -- need to — it computes commissions immediately at creation.)
  -- sql-safety: exempt-registry — orders.pricing_status is added by the sibling file-only
  -- migration 20260613170000 (see file header); commission_split is a live column.
  -- Codex round-9 P2: set customer_po_number INSIDE this SECDEF RPC. The orders UPDATE
  -- RLS is is_admin()-only, so the old frontend follow-up `orders.update({customer_po_number})`
  -- failed for a sales_rep AFTER the order was already created (false error + lost PO, not
  -- retryable). Setting it here (owner-privileged INSERT) makes it atomic and role-safe.
  -- sql-safety: exempt-registry — orders.pricing_status is added by the sibling file-only
  -- migration 20260613170000 (see file header); commission_split + customer_po_number are live.
  INSERT INTO orders (
    order_number, customer_id, status, pricing_status,
    commission_split, customer_po_number,
    total_price, total_cost, total_profit, total_margin_pct,
    order_date, notes
  ) VALUES (
    v_order_number, p_customer_id, 'confirmed', 'needs_pricing',
    v_customer.default_commission_split, NULLIF(TRIM(COALESCE(p_customer_po_number, '')), ''),
    0, 0, 0, 0,
    CURRENT_DATE,
    NULLIF(TRIM(COALESCE(p_notes, '')), '')
  ) RETURNING id INTO v_order_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    IF (v_item->>'product_id') IS NULL THEN CONTINUE; END IF;
    v_qty := COALESCE((v_item->>'qty')::numeric, (v_item->>'quantity')::numeric, 0);
    IF v_qty <= 0 THEN CONTINUE; END IF;

    SELECT
      product_name,
      unit_size,
      CASE v_tier WHEN 2 THEN tier2_price WHEN 3 THEN tier3_price ELSE tier1_price END AS tier_price
      INTO v_product
      FROM products WHERE id = (v_item->>'product_id')::uuid;
    IF NOT FOUND THEN RAISE EXCEPTION 'Product not found: %', (v_item->>'product_id'); END IF;

    -- inventory warning (prebook never blocks)
    SELECT * INTO v_inv FROM inventory
      WHERE product_id = (v_item->>'product_id')::uuid AND location = 'Main Warehouse';
    IF NOT FOUND THEN
      v_warnings := array_append(v_warnings,
        v_product.product_name || ': need ' || v_qty || ', net position is 0 (no inventory record)');
    ELSE
      v_net_position := v_inv.quantity_available - v_inv.quantity_prebooked + COALESCE(v_inv.quantity_on_order, 0);
      IF v_net_position < v_qty THEN
        v_warnings := array_append(v_warnings,
          v_product.product_name || ': need ' || v_qty ||
          ', net position is ' || GREATEST(v_net_position, 0) ||
          ' (on floor: ' || (v_inv.quantity_available - v_inv.quantity_prebooked) ||
          ', on order: ' || COALESCE(v_inv.quantity_on_order, 0) || ')');
      END IF;
    END IF;

    -- unpriced line: $ all 0 + pending; tier price snapshot for v2 pricing screen
    INSERT INTO order_items (
      order_id, product_id, product_name,
      price_per_unit, cost_per_unit,
      total_units_needed, unit_size,
      total_price, profit, net_margin,
      quantity_delivered, quantity_remaining,
      pricing_pending, suggested_price
    ) VALUES (
      v_order_id, (v_item->>'product_id')::uuid, v_product.product_name,
      0, 0,
      v_qty, v_product.unit_size,
      0, 0, 0,
      0, v_qty,
      true, v_product.tier_price
    );

    -- prebook (WARN never block)
    UPDATE inventory SET
      quantity_prebooked = quantity_prebooked + v_qty,
      updated_at = now()
    WHERE product_id = (v_item->>'product_id')::uuid AND location = 'Main Warehouse';
    IF NOT FOUND THEN
      INSERT INTO inventory (product_id, location, quantity_available, quantity_prebooked, quantity_on_order, unit_size)
      VALUES ((v_item->>'product_id')::uuid, 'Main Warehouse', 0, v_qty, 0, v_product.unit_size);
    END IF;
    INSERT INTO inventory_transactions (
      product_id, transaction_type, quantity, to_location, order_id, performed_by, notes
    ) VALUES (
      (v_item->>'product_id')::uuid, 'booked', v_qty, 'Main Warehouse', v_order_id, v_actor,
      'Pre-booked for rush order ' || v_order_number || ' (needs pricing)'
    );
  END LOOP;

  -- NO commissions yet — price_order (v2) inserts them on the FINAL profit.

  INSERT INTO activity_feed (
    event_type, description, performed_by, related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'order_created',
    'Rush order ' || v_order_number || ' created for ' || COALESCE(v_customer.farm_name, 'customer') ||
    ' — NEEDS PRICING' ||
    CASE WHEN array_length(v_warnings, 1) > 0
      THEN ' (inventory warnings: ' || array_to_string(v_warnings, '; ') || ')'
      ELSE '' END,
    v_actor, 'order', v_order_id, p_customer_id
  );

  -- #4 (Codex P2): notify admins server-side that this rush order needs pricing.
  -- create_rush_order is SECDEF (owner), so this bypasses the notifications RLS
  -- with_check (is_admin() OR user_id = auth.uid()). A sales_rep creator CANNOT
  -- insert notifications for other (admin) users from the frontend, so the immediate
  -- alert must come from here; the check_unpriced_orders cron is the longer-term backstop.
  INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
  SELECT p.id, 'Order needs pricing',
    'Rush order ' || v_order_number || ' for ' || COALESCE(v_customer.farm_name, 'customer') ||
    ' shipped without pricing — set its prices so it can be invoiced.',
    'needs_pricing', 'order', v_order_id
  FROM profiles p WHERE p.role = 'admin' AND p.is_active = true;

  v_result := jsonb_build_object(
    'status', 'created', 'order_id', v_order_id, 'order_number', v_order_number,
    'pricing_status', 'needs_pricing', 'warnings', to_jsonb(v_warnings)
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'create_rush_order', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."create_rush_order"("p_customer_id" "uuid", "p_items" "jsonb", "p_notes" "text", "p_customer_po_number" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_split_invoices_from_order"("p_order_id" "uuid", "p_salesman_id" "uuid" DEFAULT NULL::"uuid", "p_invoice_type" "text" DEFAULT 'chemical_sale'::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_contract CONSTANT text := 'create_split_invoices_from_order_v1';
  v_request jsonb;
  v_fingerprint text;
  v_replay jsonb;
  v_invoice_ids uuid[] := '{}'::uuid[];
  v_claim_nonce uuid := gen_random_uuid();
  v_has_split_evidence boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'Not authorized: admin or sales role required to create invoices from orders';
  END IF;

  v_request := jsonb_build_object(
    'contract_version', v_contract,
    'actor_id', v_actor,
    'order_id', p_order_id,
    'salesman_id', p_salesman_id,
    'invoice_type', p_invoice_type
  );
  v_fingerprint := md5(v_request::text);
  IF p_idempotency_key IS NOT NULL THEN
    v_replay := public._claim_bound_lifecycle_idempotency(
      p_idempotency_key,
      'create_split_invoices_from_order',
      v_contract,
      v_fingerprint,
      v_request
    );
  END IF;

  PERFORM 1
    FROM public.orders o
   WHERE o.id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found: %', p_order_id;
  END IF;

  PERFORM 1
    FROM public.order_items oi
   WHERE oi.order_id = p_order_id
   ORDER BY oi.id
   FOR UPDATE;

  SELECT EXISTS (
    SELECT 1
      FROM public.order_item_field_allocations oifa
      JOIN public.order_items oi ON oi.id = oifa.order_item_id
     WHERE oi.order_id = p_order_id
  ) INTO v_has_split_evidence;

  IF v_replay IS NOT NULL THEN
    SELECT COALESCE(
             array_agg(replayed.invoice_id ORDER BY replayed.ordinality),
             '{}'::uuid[]
           )
      INTO v_invoice_ids
      FROM (
        SELECT value::uuid AS invoice_id, ordinality
          FROM jsonb_array_elements_text(v_replay) WITH ORDINALITY
      ) replayed;
  ELSE
    INSERT INTO public.split_invoice_creation_claims (
      transaction_id,
      order_id,
      claim_nonce
    ) VALUES (
      pg_current_xact_id(),
      p_order_id,
      v_claim_nonce
    );

    v_invoice_ids := public._create_split_invoices_from_order_provenance_impl_20260719(
      p_order_id,
      p_salesman_id,
      p_invoice_type,
      NULL::text
    );

    INSERT INTO public.split_invoice_provenance (
      invoice_id,
      order_id,
      invoice_group_id,
      customer_id,
      invoice_type,
      season,
      total_amount_cents,
      content_claim,
      provenance_nonce,
      created_by
    )
    SELECT
      i.id,
      i.order_id,
      i.invoice_group_id,
      i.customer_id,
      i.invoice_type,
      i.season,
      i.total_amount_cents,
      public._split_invoice_content_claim(i.id),
      gen_random_uuid(),
      v_actor
    FROM unnest(COALESCE(v_invoice_ids, '{}'::uuid[])) AS returned(invoice_id)
    JOIN public.invoices i ON i.id = returned.invoice_id
    WHERE i.order_id = p_order_id
      AND i.invoice_group_id IS NOT NULL
      AND v_has_split_evidence
    ON CONFLICT (invoice_id) DO NOTHING;
  END IF;

  IF EXISTS (
       SELECT 1
         FROM unnest(COALESCE(v_invoice_ids, '{}'::uuid[])) AS returned(invoice_id)
        WHERE returned.invoice_id IS NULL
     )
     OR cardinality(COALESCE(v_invoice_ids, '{}'::uuid[])) IS DISTINCT FROM (
       SELECT count(DISTINCT returned.invoice_id)::integer
         FROM unnest(COALESCE(v_invoice_ids, '{}'::uuid[])) AS returned(invoice_id)
     )
     OR cardinality(COALESCE(v_invoice_ids, '{}'::uuid[])) IS DISTINCT FROM (
       SELECT count(*)::integer
         FROM unnest(COALESCE(v_invoice_ids, '{}'::uuid[])) AS returned(invoice_id)
         JOIN public.invoices i ON i.id = returned.invoice_id
        WHERE i.order_id = p_order_id
     ) THEN
    RAISE EXCEPTION
      'SPLIT_INVOICE_IDEMPOTENCY_RESPONSE_MISMATCH: every returned invoice must belong exactly to the requested order';
  END IF;

  IF v_has_split_evidence
     AND cardinality(COALESCE(v_invoice_ids, '{}'::uuid[])) IS DISTINCT FROM (
       SELECT count(*)::integer
         FROM unnest(COALESCE(v_invoice_ids, '{}'::uuid[])) AS returned(invoice_id)
         JOIN public.invoices i ON i.id = returned.invoice_id
         JOIN public.split_invoice_provenance p ON p.invoice_id = i.id
        WHERE i.order_id = p_order_id
          AND i.invoice_group_id IS NOT NULL
          AND p.order_id = i.order_id
          AND p.invoice_group_id = i.invoice_group_id
          AND p.customer_id = i.customer_id
          AND p.invoice_type = i.invoice_type
          AND p.season = i.season
          AND p.total_amount_cents = i.total_amount_cents
          AND p.content_claim = public._split_invoice_content_claim(i.id)
          AND p.contract_version = 'split_invoice_provenance_v1'
     ) THEN
    RAISE EXCEPTION
      'SPLIT_INVOICE_PROVENANCE_REPLAY_MISMATCH: returned split invoice content does not match its exact private claim';
  END IF;

  IF v_replay IS NULL THEN
    DELETE FROM public.split_invoice_creation_claims
     WHERE transaction_id = pg_current_xact_id()
       AND order_id = p_order_id
       AND claim_nonce = v_claim_nonce;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'SPLIT_INVOICE_CREATION_CLAIM_LOST';
    END IF;

    PERFORM public._bind_completed_lifecycle_idempotency(
      p_idempotency_key,
      'create_split_invoices_from_order',
      v_contract,
      v_fingerprint,
      v_request,
      to_jsonb(v_invoice_ids)
    );
  END IF;

  RETURN v_invoice_ids;
END;
$$;


ALTER FUNCTION "public"."create_split_invoices_from_order"("p_order_id" "uuid", "p_salesman_id" "uuid", "p_invoice_type" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_vendor_bill"("p_vendor_id" "uuid", "p_purchase_order_id" "uuid" DEFAULT NULL::"uuid", "p_bill_number" "text" DEFAULT ''::"text", "p_bill_date" "date" DEFAULT CURRENT_DATE, "p_due_date" "date" DEFAULT NULL::"date", "p_payment_terms" "text" DEFAULT NULL::"text", "p_subtotal_cents" bigint DEFAULT 0, "p_adjustment_cents" bigint DEFAULT 0, "p_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_total bigint;
  v_bill_id uuid;
  v_terms_days integer;
  v_terms text;
  v_actor uuid;
  v_actor_role text;
  v_existing jsonb;
  v_vendor_name text;
  v_po_vendor text;
  v_po_total_cents bigint;
  v_amount_drift_pct numeric;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  SELECT role INTO v_actor_role FROM public.profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role <> 'admin' THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin role required to create vendor bills';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'create_vendor_bill');
    IF v_existing IS NOT NULL THEN
      RETURN (v_existing->>'bill_id')::uuid;
    END IF;
  END IF;

  PERFORM public.check_period_open(p_bill_date);

  SELECT name INTO v_vendor_name
    FROM public.vendors
   WHERE id = p_vendor_id
     AND deleted_at IS NULL;
  IF v_vendor_name IS NULL THEN
    RAISE EXCEPTION 'VENDOR_NOT_FOUND: vendor % does not exist or is soft-deleted', p_vendor_id;
  END IF;

  IF p_subtotal_cents <= 0 THEN
    RAISE EXCEPTION 'INVALID_AMOUNT: subtotal must be positive';
  END IF;

  v_total := p_subtotal_cents + COALESCE(p_adjustment_cents, 0);
  IF v_total <= 0 THEN
    RAISE EXCEPTION 'INVALID_AMOUNT: bill total must be positive (got %)', v_total;
  END IF;

  IF p_purchase_order_id IS NOT NULL THEN
    -- total_cost_cents is maintained as the sum of individually rounded line
    -- extensions, so the bill comparison must consume that exact authority.
    SELECT vendor, total_cost_cents
      INTO v_po_vendor, v_po_total_cents
      FROM public.purchase_orders
     WHERE id = p_purchase_order_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'PO_NOT_FOUND: purchase order % does not exist', p_purchase_order_id;
    END IF;
    IF lower(trim(v_po_vendor)) <> lower(trim(v_vendor_name)) THEN
      RAISE EXCEPTION 'VENDOR_PO_MISMATCH: bill vendor "%" does not match PO vendor "%"',
        v_vendor_name, v_po_vendor;
    END IF;

    IF v_po_total_cents > 0 THEN
      v_amount_drift_pct := ABS(v_total - v_po_total_cents)::numeric / v_po_total_cents::numeric;
      IF v_amount_drift_pct > 0.05 THEN
        INSERT INTO public.notifications (
          user_id,
          title,
          message,
          notification_type,
          related_entity_type,
          related_entity_id
        )
        SELECT
          p.id,
          'Vendor bill amount differs from PO',
          'Bill ' || COALESCE(NULLIF(p_bill_number, ''), 'pending') ||
            ' for ' || v_vendor_name ||
            ' is $' || (v_total / 100.0)::numeric(12,2) ||
            ' but PO total is $' || (v_po_total_cents / 100.0)::numeric(12,2) ||
            ' (' || ROUND(v_amount_drift_pct * 100, 1) || '% drift). Verify the bill matches the PO.',
          'vendor_bill_drift',
          'purchase_order',
          p_purchase_order_id
        FROM public.profiles p
        WHERE p.role = 'admin'
          AND p.is_active = true;
      END IF;
    END IF;
  END IF;

  IF p_payment_terms IS NULL THEN
    SELECT default_payment_terms, default_payment_terms_days
      INTO v_terms, v_terms_days
      FROM public.vendors
     WHERE id = p_vendor_id;
  ELSE
    v_terms := p_payment_terms;
    v_terms_days := CASE
      WHEN p_payment_terms ILIKE '%90%' THEN 90
      WHEN p_payment_terms ILIKE '%60%' THEN 60
      WHEN p_payment_terms ILIKE '%45%' THEN 45
      WHEN p_payment_terms ILIKE '%30%' THEN 30
      WHEN p_payment_terms ILIKE '%15%' THEN 15
      WHEN p_payment_terms ILIKE '%10%' THEN 10
      ELSE 30
    END;
  END IF;

  INSERT INTO public.vendor_bills (
    vendor_id,
    purchase_order_id,
    bill_number,
    bill_date,
    due_date,
    payment_terms,
    subtotal_cents,
    adjustment_cents,
    total_cents,
    paid_cents,
    status,
    notes,
    created_by
  ) VALUES (
    p_vendor_id,
    p_purchase_order_id,
    p_bill_number,
    p_bill_date,
    COALESCE(
      p_due_date,
      p_bill_date + (COALESCE(v_terms_days, 30) || ' days')::interval
    ),
    v_terms,
    p_subtotal_cents,
    COALESCE(p_adjustment_cents, 0),
    v_total,
    0,
    'unpaid',
    p_notes,
    v_actor
  )
  RETURNING id INTO v_bill_id;

  INSERT INTO public.financial_audit_log (
    operation_type,
    entity_type,
    entity_id,
    actor_user_id,
    actor_role,
    new_values,
    total_impact_cents,
    description
  ) VALUES (
    'vendor_bill_created',
    'vendor_bill',
    v_bill_id,
    v_actor,
    v_actor_role,
    jsonb_build_object(
      'vendor_id', p_vendor_id,
      'purchase_order_id', p_purchase_order_id,
      'bill_number', p_bill_number,
      'bill_date', p_bill_date,
      'total_cents', v_total,
      'po_total_cents', v_po_total_cents,
      'drift_pct', v_amount_drift_pct
    ),
    v_total,
    'Vendor bill ' || COALESCE(NULLIF(p_bill_number, ''), v_bill_id::text) ||
      ' created for $' || (v_total / 100.0)::numeric(12,2)
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(
      p_idempotency_key,
      'create_vendor_bill',
      jsonb_build_object('bill_id', v_bill_id)
    );
  END IF;

  RETURN v_bill_id;
END;
$_$;


ALTER FUNCTION "public"."create_vendor_bill"("p_vendor_id" "uuid", "p_purchase_order_id" "uuid", "p_bill_number" "text", "p_bill_date" "date", "p_due_date" "date", "p_payment_terms" "text", "p_subtotal_cents" bigint, "p_adjustment_cents" bigint, "p_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_season"() RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT compute_season(CURRENT_DATE);
$$;


ALTER FUNCTION "public"."current_season"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dashboard_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  WITH
  -- 1. Inventory totals
  inv_agg AS (
    SELECT
      COALESCE(SUM(quantity_available), 0)  AS total_available,
      COALESCE(SUM(quantity_prebooked), 0)  AS total_prebooked
    FROM inventory
  ),

  -- 2. Low stock count
  low_stock AS (
    SELECT COUNT(*) AS cnt
    FROM inventory
    WHERE reorder_point > 0
      AND quantity_available <= reorder_point
  ),

  -- 3. Next 5 upcoming deliveries
  upcoming AS (
    SELECT jsonb_agg(row_to_json(ud)::jsonb ORDER BY ud.scheduled_date ASC) AS arr
    FROM (
      SELECT
        d.id,
        d.delivery_number,
        d.scheduled_date,
        d.status,
        jsonb_build_object('farm_name', cust.farm_name) AS customer,
        jsonb_build_object('full_name', drv.full_name)  AS driver
      FROM deliveries d
      LEFT JOIN customers cust ON cust.id = d.customer_id
      LEFT JOIN profiles  drv  ON drv.id  = d.assigned_driver
      WHERE d.status IN ('scheduled', 'in_progress')
      ORDER BY d.scheduled_date ASC
      LIMIT 5
    ) ud
  ),

  -- 4. Last 10 activity feed items
  activity AS (
    SELECT jsonb_agg(row_to_json(af)::jsonb ORDER BY af.created_at DESC) AS arr
    FROM (
      SELECT
        id,
        event_type,
        description,
        created_at
      FROM activity_feed
      ORDER BY created_at DESC
      LIMIT 10
    ) af
  ),

  -- 5. Driver issues count
  driver_issues AS (
    SELECT COUNT(*) AS cnt
    FROM deliveries
    WHERE issue_type IS NOT NULL
      AND status = 'completed'
  ),

  -- 6. Expired quote holds
  expired_holds AS (
    SELECT COUNT(DISTINCT q.id) AS cnt
    FROM quotes q
    JOIN inventory_holds ih ON ih.source_id = q.id AND ih.is_active = true
    WHERE q.status IN ('expired', 'declined')
  ),

  -- 7. Cancelled deliveries with posted invoices
  cancelled_posted AS (
    SELECT COUNT(DISTINCT d.id) AS cnt
    FROM deliveries d
    JOIN orders o ON o.id = d.order_id
    JOIN invoices i ON i.order_id = o.id
    WHERE d.status = 'cancelled'
      AND i.status = 'posted'
  )

  SELECT jsonb_build_object(
    'inventory_available',  ia.total_available,
    'inventory_prebooked',  ia.total_prebooked,
    'low_stock_count',      ls.cnt,
    'upcoming_deliveries',  COALESCE(ud.arr, '[]'::jsonb),
    'recent_activity',      COALESCE(ra.arr, '[]'::jsonb),
    'driver_issues_count',          di.cnt,
    'expired_holds_count',          eh.cnt,
    'cancelled_posted_count',       cp.cnt
  ) INTO result
  FROM inv_agg     ia
  CROSS JOIN low_stock   ls
  CROSS JOIN upcoming    ud
  CROSS JOIN activity    ra
  CROSS JOIN driver_issues   di
  CROSS JOIN expired_holds   eh
  CROSS JOIN cancelled_posted cp;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."dashboard_summary"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dashboard_summary"() IS 'Returns operational Dashboard KPIs: inventory, deliveries, activity, and integrity alerts. Financial data moved to financial_dashboard_summary().';



CREATE OR REPLACE FUNCTION "public"."delete_invoices"("p_invoice_ids" "uuid"[], "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_contract CONSTANT text := 'delete_invoices_v1';
  v_request_ids uuid[] := '{}'::uuid[];
  v_request jsonb;
  v_fingerprint text;
  v_replay jsonb;
  v_deleted_count integer;
  v_governed_ids uuid[] := '{}'::uuid[];
  v_claim_count integer := 0;
BEGIN
  PERFORM public.require_admin();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT requested.invoice_id ORDER BY requested.invoice_id), '{}'::uuid[])
    INTO v_request_ids
    FROM unnest(COALESCE(p_invoice_ids, '{}'::uuid[])) AS requested(invoice_id)
   WHERE requested.invoice_id IS NOT NULL;
  IF cardinality(v_request_ids) = 0 THEN
    RAISE EXCEPTION 'No invoice IDs provided';
  END IF;

  v_request := jsonb_build_object(
    'contract_version', v_contract,
    'actor_id', v_actor,
    'invoice_ids', to_jsonb(v_request_ids)
  );
  v_fingerprint := md5(v_request::text);
  IF p_idempotency_key IS NOT NULL THEN
    v_replay := public._claim_bound_lifecycle_idempotency(
      p_idempotency_key,
      'delete_invoices',
      v_contract,
      v_fingerprint,
      v_request
    );
    IF v_replay IS NOT NULL THEN
      RETURN (v_replay #>> '{}')::integer;
    END IF;
  END IF;

  SELECT COALESCE(array_agg(p.invoice_id ORDER BY p.invoice_id), '{}'::uuid[])
    INTO v_governed_ids
    FROM public.split_invoice_provenance p
   WHERE p.invoice_id = ANY(v_request_ids);

  INSERT INTO public.split_invoice_mutation_claims (
    transaction_id, invoice_id, operation
  )
  SELECT pg_current_xact_id(), governed.invoice_id, 'delete_invoices'
    FROM unnest(v_governed_ids) AS governed(invoice_id);

  v_deleted_count := public._delete_invoices_split_provenance_impl_20260719(
    v_request_ids,
    p_performed_by,
    NULL::text
  );

  UPDATE public.invoices i
     SET status = 'cancelled'
   WHERE i.id = ANY(v_governed_ids)
     AND i.deleted_at IS NOT NULL
     AND i.status IN ('draft', 'unposted');

  DELETE FROM public.split_invoice_mutation_claims claim
   WHERE claim.transaction_id = pg_current_xact_id()
     AND claim.operation = 'delete_invoices'
     AND claim.invoice_id = ANY(v_governed_ids);
  GET DIAGNOSTICS v_claim_count = ROW_COUNT;
  IF v_claim_count IS DISTINCT FROM cardinality(v_governed_ids) THEN
    RAISE EXCEPTION 'SPLIT_INVOICE_DELETE_CLAIM_LOST';
  END IF;

  IF cardinality(v_governed_ids) > 0
     AND NOT EXISTS (
       SELECT 1
         FROM public.split_invoice_provenance p
        WHERE p.invoice_id = ANY(v_governed_ids)
     ) THEN
    RAISE EXCEPTION 'SPLIT_INVOICE_PROVENANCE_IDENTITY_LOST';
  END IF;

  PERFORM public._bind_completed_lifecycle_idempotency(
    p_idempotency_key,
    'delete_invoices',
    v_contract,
    v_fingerprint,
    v_request,
    to_jsonb(v_deleted_count)
  );

  RETURN v_deleted_count;
END;
$$;


ALTER FUNCTION "public"."delete_invoices"("p_invoice_ids" "uuid"[], "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_prepay_credit"("p_credit_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_credit      record;
  v_old_balance bigint;
  v_actor       uuid;
  v_actor_role  text;
  v_existing    jsonb;
  v_sum_applied bigint;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'delete_prepay_credit';
    IF v_existing IS NOT NULL THEN
      RETURN jsonb_build_object('success', true, 'credit_id', p_credit_id, 'idempotent', true);
    END IF;
  END IF;

  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  -- Codex P1 fix (2026-05-16): null-safe admin check via IS DISTINCT FROM.
  SELECT role INTO v_actor_role
  FROM profiles
  WHERE id = v_actor AND is_active = true;

  IF v_actor_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'Admin access required to delete prepay credits';
  END IF;

  SELECT * INTO v_credit FROM prepay_credits WHERE id = p_credit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Prepay credit not found: %', p_credit_id; END IF;

  v_old_balance := v_credit.balance_cents;
  IF v_old_balance = 0 THEN RAISE EXCEPTION 'Prepay credit already has zero balance'; END IF;

  SELECT COALESCE(SUM(applied_amount_cents), 0) INTO v_sum_applied
  FROM prepay_applications WHERE prepay_credit_id = p_credit_id;

  UPDATE prepay_credits
  SET balance_cents         = 0,
      original_amount_cents = v_sum_applied,
      notes                 = COALESCE(notes, '') || ' [DELETED: ' || p_reason || ']',
      updated_at            = now()
  WHERE id = p_credit_id;

  UPDATE customers
  SET prepay_balance_cents = GREATEST(prepay_balance_cents - v_old_balance, 0)
  WHERE id = v_credit.customer_id;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id,
    actor_user_id, old_values, new_values,
    total_impact_cents, description
  ) VALUES (
    'prepay_deleted', 'prepay', p_credit_id, v_actor,
    jsonb_build_object(
      'balance_cents', v_old_balance,
      'original_amount_cents', v_credit.original_amount_cents,
      'sum_applied_cents', v_sum_applied,
      'reference_number', v_credit.reference_number,
      'bucket_label', v_credit.bucket_label
    ),
    jsonb_build_object('balance_cents', 0, 'original_amount_cents', v_sum_applied, 'reason', p_reason),
    -1 * v_old_balance,
    'Deleted prepay credit ' || COALESCE(v_credit.reference_number, v_credit.id::text) || ' — ' || p_reason
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'delete_prepay_credit', jsonb_build_object('credit_id', p_credit_id));
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'credit_id', p_credit_id, 'deleted_balance_cents', v_old_balance
  );
END;
$$;


ALTER FUNCTION "public"."delete_prepay_credit"("p_credit_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_purchase_order"("p_po_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid; v_po record; v_has_received boolean;
  v_active_bill_count integer; v_result jsonb; v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Actor mismatch';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND role = 'admin' AND is_active = true) THEN
    RAISE EXCEPTION 'Only admins can delete purchase orders';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'delete_purchase_order');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_po FROM purchase_orders WHERE id = p_po_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase order not found'; END IF;

  -- PR-22b #1: refuse if any vendor_bills (active or voided) are linked
  SELECT count(*) INTO v_active_bill_count FROM vendor_bills
  WHERE purchase_order_id = p_po_id AND deleted_at IS NULL;

  IF v_active_bill_count > 0 THEN
    RAISE EXCEPTION 'PO_HAS_LINKED_BILLS: cannot delete PO % — % vendor bill(s) reference it. Cancel the PO instead.',
      v_po.po_number, v_active_bill_count;
  END IF;

  SELECT EXISTS (SELECT 1 FROM purchase_order_items
    WHERE purchase_order_id = p_po_id AND quantity_received > 0) INTO v_has_received;

  IF v_has_received THEN
    RAISE EXCEPTION 'Cannot delete PO % — items have already been received. Cancel instead.', v_po.po_number;
  END IF;

  DELETE FROM purchase_order_items WHERE purchase_order_id = p_po_id;
  DELETE FROM purchase_orders WHERE id = p_po_id;

  INSERT INTO activity_feed (event_type, description, performed_by,
    related_entity_type, related_entity_id)
  VALUES ('po_deleted', 'PO ' || v_po.po_number || ' deleted',
    v_actor, 'purchase_order', p_po_id);

  v_result := jsonb_build_object('status', 'deleted');

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'delete_purchase_order', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."delete_purchase_order"("p_po_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_vendor"("p_vendor_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid; v_actor_role text; v_vendor record;
  v_active_po_count integer; v_active_bill_count integer;
  v_result jsonb; v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role <> 'admin' THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: only admins can delete vendors';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'delete_vendor');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_vendor FROM vendors WHERE id = p_vendor_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'VENDOR_NOT_FOUND: % (or already deleted)', p_vendor_id; END IF;

  v_active_po_count := 0; -- intentionally unchecked

  SELECT count(*) INTO v_active_bill_count FROM vendor_bills
  WHERE vendor_id = p_vendor_id AND status NOT IN ('paid', 'voided') AND deleted_at IS NULL;

  IF v_active_bill_count > 0 THEN
    RAISE EXCEPTION 'VENDOR_HAS_UNPAID_BILLS: cannot delete — % unpaid bill(s)', v_active_bill_count;
  END IF;

  UPDATE vendors SET deleted_at = now(), updated_at = now() WHERE id = p_vendor_id;

  INSERT INTO activity_feed (event_type, description, performed_by,
    related_entity_type, related_entity_id)
  VALUES ('vendor_deleted', 'Vendor ' || v_vendor.name || ' deleted',
    v_actor, 'vendor', p_vendor_id);

  v_result := jsonb_build_object('success', true, 'vendor_id', p_vendor_id);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'delete_vendor', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."delete_vendor"("p_vendor_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."derive_customer_shares_from_fields"("p_field_ids" "uuid"[], "p_applied_acres_map" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH field_data AS (
    SELECT
      f.id           AS field_id,
      f.field_name,
      f.customer_id  AS field_owner_id,
      f.total_acres,
      f.crop_type,
      COALESCE(
        (p_applied_acres_map ->> f.id::text)::numeric,
        f.total_acres
      ) AS applied_acres
    FROM fields f
    WHERE f.id = ANY(p_field_ids)
  ),
  billing_split AS (
    SELECT
      fd.field_id, fd.field_name, fd.applied_acres, fd.total_acres,
      fbd.customer_id, c.farm_name AS customer_name, c.assigned_tier AS tier,
      fbd.split_pct, fbd.is_primary,
      fbd.price_override_cents, fbd.pricing_note,
      false AS used_fallback
    FROM field_data fd
    JOIN field_billing_defaults fbd ON fbd.field_id = fd.field_id
    JOIN customers c               ON c.id        = fbd.customer_id
  ),
  billing_fallback AS (
    SELECT
      fd.field_id, fd.field_name, fd.applied_acres, fd.total_acres,
      fd.field_owner_id AS customer_id, c.farm_name AS customer_name, c.assigned_tier AS tier,
      100.0 AS split_pct, true AS is_primary,
      NULL::bigint AS price_override_cents, NULL::text AS pricing_note,
      true AS used_fallback
    FROM field_data fd
    JOIN customers c ON c.id = fd.field_owner_id
    WHERE NOT EXISTS (SELECT 1 FROM field_billing_defaults fbd WHERE fbd.field_id = fd.field_id)
  ),
  combined AS (
    SELECT * FROM billing_split UNION ALL SELECT * FROM billing_fallback
  ),
  agg AS (
    SELECT
      cb.customer_id, cb.customer_name,
      bool_or(cb.is_primary) AS is_primary,
      ROUND(SUM(cb.applied_acres * cb.split_pct / 100.0), 2) AS total_share_acres,
      CASE WHEN SUM(SUM(cb.applied_acres * cb.split_pct / 100.0)) OVER () > 0
        THEN ROUND(SUM(cb.applied_acres * cb.split_pct / 100.0)
                   / SUM(SUM(cb.applied_acres * cb.split_pct / 100.0)) OVER () * 100, 4)
        ELSE 0
      END AS overall_split_pct,
      MAX(cb.tier) AS tier,
      bool_or(cb.price_override_cents IS NOT NULL) AS has_override
    FROM combined cb
    GROUP BY cb.customer_id, cb.customer_name
  )
  SELECT jsonb_build_object(
    'rows', COALESCE(jsonb_agg(
      jsonb_build_object(
        'field_id', cb.field_id, 'field_name', cb.field_name,
        'customer_id', cb.customer_id, 'customer_name', cb.customer_name,
        'is_primary', cb.is_primary, 'split_pct', cb.split_pct,
        'share_acres', ROUND(cb.applied_acres * cb.split_pct / 100.0, 2),
        'price_override_cents', cb.price_override_cents,
        'pricing_note', cb.pricing_note,
        'tier', cb.tier,
        'field_total_acres', cb.total_acres,
        'field_applied_acres', cb.applied_acres,
        'used_fallback', cb.used_fallback
      ) ORDER BY cb.is_primary DESC, cb.customer_name, cb.field_name
    ) FILTER (WHERE cb.field_id IS NOT NULL), '[]'::jsonb),
    'customers', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'customer_id', a.customer_id, 'customer_name', a.customer_name,
        'is_primary', a.is_primary,
        'total_share_acres', a.total_share_acres,
        'overall_split_pct', a.overall_split_pct,
        'tier', a.tier, 'has_override', a.has_override
      ) ORDER BY a.is_primary DESC, a.total_share_acres DESC) FROM agg a
    ), '[]'::jsonb),
    'total_applied_acres', (SELECT COALESCE(SUM(fd.applied_acres), 0) FROM field_data fd),
    'field_count', array_length(p_field_ids, 1),
    'fallback_used_field_ids', COALESCE((
      SELECT jsonb_agg(DISTINCT bf.field_id) FROM billing_fallback bf
    ), '[]'::jsonb)
  ) INTO v_result
  FROM combined cb;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."derive_customer_shares_from_fields"("p_field_ids" "uuid"[], "p_applied_acres_map" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dismiss_watchdog_flag"("p_flag_id" "uuid", "p_resolution" "text", "p_note" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_cached   jsonb;
  v_flag     watchdog_flags%ROWTYPE;
  v_dismiss  watchdog_flag_dismissals%ROWTYPE;
  v_result   jsonb;
BEGIN
  -- Resolve actor (canonical pattern: bind auth.uid first, then validate)
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: must be authenticated to dismiss watchdog flags';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH: p_performed_by must match the authenticated user';
  END IF;

  -- Gate: actor must be admin or sales_rep
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = v_actor AND (role IN ('admin','sales_rep')) AND is_active = true
  ) THEN
    RAISE EXCEPTION 'WATCHDOG_ACCESS_DENIED: admin or sales_rep role required';
  END IF;

  -- Validate resolution
  IF p_resolution NOT IN ('looks_fine','needs_fix') THEN
    RAISE EXCEPTION 'INVALID_RESOLUTION: must be looks_fine or needs_fix';
  END IF;

  -- Idempotency check
  IF NULLIF(btrim(COALESCE(p_idempotency_key,'')), '') IS NOT NULL THEN
    SELECT result INTO v_cached
    FROM idempotency_keys
    WHERE idempotency_key = p_idempotency_key
      AND operation = 'dismiss_watchdog_flag';
    IF FOUND THEN RETURN v_cached; END IF;
  END IF;

  -- Verify flag exists
  SELECT * INTO v_flag FROM watchdog_flags WHERE id = p_flag_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'WATCHDOG_FLAG_NOT_FOUND: flag % does not exist', p_flag_id;
  END IF;

  -- Insert dismissal
  INSERT INTO watchdog_flag_dismissals (flag_id, dismissed_by, resolution, note)
  VALUES (p_flag_id, v_actor, p_resolution, NULLIF(btrim(COALESCE(p_note,'')), ''))
  RETURNING * INTO v_dismiss;

  v_result := jsonb_build_object(
    'dismissal_id', v_dismiss.id,
    'flag_id',      p_flag_id,
    'resolution',   p_resolution,
    'dismissed_at', v_dismiss.dismissed_at
  );

  -- Store idempotency result
  IF NULLIF(btrim(COALESCE(p_idempotency_key,'')), '') IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'dismiss_watchdog_flag', v_result)
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."dismiss_watchdog_flag"("p_flag_id" "uuid", "p_resolution" "text", "p_note" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_job_locations"("p_assignments" "jsonb", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_license_override" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor        uuid;
  v_role         text;
  v_existing     jsonb;
  v_assignment   jsonb;
  v_job_field    uuid;
  v_applicator   uuid;
  v_crew         uuid;
  v_job_id       uuid;
  v_job_status   text;
  v_has_licenses boolean;
  v_latest_expiry date;
  v_count        int := 0;
  v_override_used int := 0;   -- # of expired-license applicators dispatched via override
  v_this_override boolean := false;  -- did THIS location use the license override?
  v_job_cust     uuid;
  v_assignee_label text;
  v_field_label  text;
  v_result       jsonb;
BEGIN
  -- actor / strict-actor / role gate (mirrors jobs_update RLS)
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales_rep required';
  END IF;
  -- The license-override hatch is admin-only (mirrors assign_job_applicator).
  IF p_license_override AND v_role <> 'admin' THEN
    RAISE EXCEPTION 'OVERRIDE_REQUIRES_ADMIN';
  END IF;

  -- idempotency: return the cached result if this key already ran for THIS op.
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'dispatch_job_locations');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF p_assignments IS NULL OR jsonb_typeof(p_assignments) <> 'array' THEN
    RAISE EXCEPTION 'INVALID_PAYLOAD: p_assignments must be a JSON array';
  END IF;
  IF jsonb_array_length(p_assignments) = 0 THEN
    RAISE EXCEPTION 'NO_ASSIGNMENTS: at least one assignment required';
  END IF;

  -- Reject a payload that lists the same location twice: each job_field_id maps to
  -- exactly ONE current dispatch, so a duplicate would upsert the same row twice and
  -- over-count the {dispatched} total + write a duplicate activity row (Codex
  -- re-review-9 P3). The wizard already de-dups via a selection Set; this guards a
  -- direct RPC caller.
  IF (SELECT count(*) FROM jsonb_array_elements(p_assignments) e) <>
     (SELECT count(DISTINCT nullif(e->>'job_field_id','')) FROM jsonb_array_elements(p_assignments) e) THEN
    RAISE EXCEPTION 'DUPLICATE_LOCATION: each job_field_id may appear at most once per dispatch';
  END IF;

  FOR v_assignment IN SELECT * FROM jsonb_array_elements(p_assignments)
  LOOP
    v_job_field  := nullif(v_assignment->>'job_field_id', '')::uuid;
    v_applicator := nullif(v_assignment->>'applicator_id', '')::uuid;
    v_crew       := nullif(v_assignment->>'crew_id', '')::uuid;

    IF v_job_field IS NULL THEN
      RAISE EXCEPTION 'INVALID_ASSIGNMENT: job_field_id is required';
    END IF;

    -- EXACTLY ONE assignee.
    IF (v_applicator IS NOT NULL) = (v_crew IS NOT NULL) THEN
      RAISE EXCEPTION 'ONE_ASSIGNEE_REQUIRED: each location needs exactly one of applicator_id / crew_id (job_field %)', v_job_field;
    END IF;

    -- Derive the real job for this location (never trust a client job_id).
    SELECT jf.job_id INTO v_job_id FROM job_fields jf WHERE jf.id = v_job_field;
    IF v_job_id IS NULL THEN
      RAISE EXCEPTION 'LOCATION_NOT_FOUND: job_field % does not exist', v_job_field;
    END IF;

    -- Only dispatch locations of a DISPATCHABLE job: a LIVE (not soft-deleted)
    -- job in scheduled/in_progress. This RPC is SECURITY DEFINER and bypasses RLS,
    -- so it must enforce deleted_at IS NULL itself — the board filters deleted_at,
    -- but a direct caller would otherwise dispatch a soft-deleted job (Codex #36 P2).
    -- FOR UPDATE locks the job row so a concurrent complete/cancel can't slip the
    -- job into a non-dispatchable status between this check and the upsert — the
    -- status-transition enforcer takes the same row lock, so they serialize and we
    -- never leave a dispatch row on a job that just became completed/cancelled
    -- (Codex re-review-8 P2 TOCTOU).
    SELECT status INTO v_job_status FROM jobs WHERE id = v_job_id AND deleted_at IS NULL FOR UPDATE;
    IF v_job_status IS NULL THEN
      RAISE EXCEPTION 'JOB_NOT_FOUND: job % missing or deleted', v_job_id;
    END IF;
    IF v_job_status NOT IN ('scheduled', 'in_progress') THEN
      RAISE EXCEPTION 'JOB_NOT_DISPATCHABLE: job % is % (must be scheduled or in_progress)', v_job_id, v_job_status;
    END IF;

    -- Validate the assignee.
    IF v_applicator IS NOT NULL THEN
      PERFORM 1 FROM profiles
        WHERE id = v_applicator AND is_active = true AND role = 'applicator';
      IF NOT FOUND THEN
        RAISE EXCEPTION 'INVALID_APPLICATOR: % is not an active applicator', v_applicator;
      END IF;

      -- LICENSE GATE (Codex re-review P1): dispatching a location to an applicator
      -- whose tracked active licenses are ALL expired is blocked, mirroring the
      -- enforce_applicator_license trigger that guards jobs.applicator_id (this RPC
      -- writes the new table, never jobs, so that trigger does NOT fire — replicate
      -- it here). No license on file = allowed (gate only applies once licenses are
      -- tracked). p_license_override is the admin-only hatch (checked above) and any
      -- ACTUAL override (expired license dispatched anyway) is logged below (P2).
      SELECT count(*) > 0, max(expiry_date)
        INTO v_has_licenses, v_latest_expiry
        FROM applicator_licenses
       WHERE profile_id = v_applicator
         AND is_active = true;
      v_this_override := false;
      IF v_has_licenses AND v_latest_expiry < CURRENT_DATE THEN
        IF NOT p_license_override THEN
          RAISE EXCEPTION 'LICENSE_EXPIRED: applicator % license expired %', v_applicator, v_latest_expiry;
        END IF;
        v_this_override := true;          -- override actually exercised on this loc
        v_override_used := v_override_used + 1;
      END IF;
    ELSE
      v_this_override := false;
      PERFORM 1 FROM ground_crews WHERE id = v_crew AND is_active = true;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'INVALID_CREW: % is not an active crew', v_crew;
      END IF;
    END IF;

    -- UPSERT: one current dispatch per location; re-dispatch replaces assignee.
    INSERT INTO job_location_dispatches
      (job_field_id, job_id, applicator_id, crew_id, dispatched_at, dispatch_status, dispatched_by)
    VALUES
      (v_job_field, v_job_id, v_applicator, v_crew, now(), 'dispatched', v_actor)
    ON CONFLICT (job_field_id) DO UPDATE
      SET applicator_id   = EXCLUDED.applicator_id,
          crew_id         = EXCLUDED.crew_id,
          job_id          = EXCLUDED.job_id,
          dispatched_at   = now(),
          dispatch_status = 'dispatched',
          dispatched_by   = v_actor;

    -- ACTIVITY LOG (Codex re-review-5 P2): every location dispatch lands on the
    -- job/customer timeline (the replaced assign_job_applicator flow logged each
    -- assignment; keep that audit trail). One row per location, with the assignee
    -- name, the field, and an override note when applicable.
    SELECT customer_id INTO v_job_cust FROM jobs WHERE id = v_job_id;
    IF v_applicator IS NOT NULL THEN
      SELECT full_name INTO v_assignee_label FROM profiles WHERE id = v_applicator;
      v_assignee_label := 'applicator ' || coalesce(v_assignee_label, v_applicator::text);
    ELSE
      SELECT name INTO v_assignee_label FROM ground_crews WHERE id = v_crew;
      v_assignee_label := 'crew ' || coalesce(v_assignee_label, v_crew::text);
    END IF;
    SELECT f.field_name INTO v_field_label
      FROM job_fields jf JOIN fields f ON f.id = jf.field_id WHERE jf.id = v_job_field;
    INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
    VALUES (
      'job_location_dispatched',
      'Location ' || coalesce(v_field_label, '') || ' dispatched to ' || v_assignee_label
        || CASE WHEN v_this_override
                THEN ' with EXPIRED license (' || v_latest_expiry || ') — admin license override'
                ELSE '' END,
      v_actor, 'job', v_job_id, v_job_cust
    );

    v_count := v_count + 1;
  END LOOP;

  v_result := jsonb_build_object('dispatched', v_count, 'license_overrides', v_override_used);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'dispatch_job_locations', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."dispatch_job_locations"("p_assignments" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text", "p_license_override" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."draw_down_quote"("p_quote_id" "uuid", "p_draws" "jsonb", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_actor_role text;
  v_quote record;
  v_customer record;
  v_draw jsonb;
  v_product_id uuid;
  v_product_name text;
  v_qty numeric;
  v_booked numeric;
  v_drawn numeric;
  v_remaining numeric;
  v_wavg_price numeric;
  v_wavg_cost numeric;
  v_total_acres numeric;
  v_unit_size text;
  v_acres numeric;
  v_inv record;
  v_net_position numeric;
  v_order_id uuid;
  v_order_number text;
  v_total_price numeric := 0;
  v_total_cost numeric := 0;
  v_total_profit numeric;
  v_total_margin_pct numeric;
  v_line_total numeric;
  v_line_cost numeric;
  v_shortfalls text[] := '{}';
  v_lines jsonb := '[]'::jsonb;
  v_hold record;
  v_to_consume numeric;
  v_fully_drawn boolean;
  v_line_count integer := 0;
  v_result jsonb;
  v_existing jsonb;
  -- LAYER2<<< job reservations consumed against this quote (§6.5)
  v_job_drawn numeric;
  -- >>>LAYER2
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_actor_role
  FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- Lock the quote: serializes concurrent draws on the same booking.
  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found'; END IF;

  -- Idempotency check AFTER the lock (2026-06-10 HIGH fix): the row lock
  -- serializes same-key duplicates so the non-atomic check/save pair cannot
  -- both pass. Kept BEFORE the status guard so a retry of the final draw
  -- (which flips status to 'accepted') returns the cached result rather than
  -- BOOKING_CLOSED.
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'draw_down_quote');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF v_quote.status NOT IN ('sent', 'revised') THEN
    RAISE EXCEPTION 'BOOKING_CLOSED: quote % is % — only sent or revised quotes can be drawn down', v_quote.quote_number, v_quote.status;
  END IF;

  IF p_draws IS NULL OR jsonb_typeof(p_draws) <> 'array' OR jsonb_array_length(p_draws) = 0 THEN
    RAISE EXCEPTION 'EMPTY_DRAW: no draw lines supplied';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_draws) d
    WHERE (d->>'product_id') IS NOT NULL AND COALESCE((d->>'quantity')::numeric, 0) > 0
  ) THEN
    RAISE EXCEPTION 'EMPTY_DRAW: no draw lines supplied';
  END IF;

  SELECT * INTO v_customer FROM customers WHERE id = v_quote.customer_id;

  v_order_number := generate_order_number();
  INSERT INTO orders (order_number, quote_id, customer_id, status, commission_split,
    total_price, total_cost, total_profit, total_margin_pct, order_date, program_notes)
  VALUES (v_order_number, p_quote_id, v_quote.customer_id, 'confirmed',
    v_quote.commission_split, 0, 0, 0, 0, current_date,
    (SELECT string_agg(qs.section_name || ': ' || qs.section_header_notes, E'\n')
     FROM quote_sections qs WHERE qs.quote_id = p_quote_id
       AND qs.section_header_notes IS NOT NULL AND qs.section_header_notes <> ''))
  RETURNING id INTO v_order_id;
  -- A3<<< mark this order as a booking draw so void_order/cancel_order know
  -- to reverse the quote_product_draws ledger (20260610190000). Kept as a
  -- separate statement (not folded into the INSERT) so the body above stays
  -- byte-identical to the live baseline.
  UPDATE orders SET booking_draw = true WHERE id = v_order_id;
  -- >>>A3

  FOR v_draw IN SELECT * FROM jsonb_array_elements(p_draws) LOOP
    v_product_id := (v_draw->>'product_id')::uuid;
    v_qty := COALESCE((v_draw->>'quantity')::numeric, 0);
    IF v_product_id IS NULL OR v_qty <= 0 THEN CONTINUE; END IF;

    -- Per-product booking balance (locked quote => stable within this txn)
    SELECT
      SUM(COALESCE(qi.total_units_needed, 0)),
      CASE WHEN SUM(COALESCE(qi.total_units_needed, 0)) > 0
        THEN SUM(qi.price_per_unit * COALESCE(qi.total_units_needed, 0)) / SUM(COALESCE(qi.total_units_needed, 0))
        ELSE 0 END,
      CASE WHEN SUM(COALESCE(qi.total_units_needed, 0)) > 0
        THEN SUM(qi.current_cost * COALESCE(qi.total_units_needed, 0)) / SUM(COALESCE(qi.total_units_needed, 0))
        ELSE 0 END,
      SUM(COALESCE(qi.acres, 0)),
      MIN(qi.unit_size)
    INTO v_booked, v_wavg_price, v_wavg_cost, v_total_acres, v_unit_size
    FROM quote_items qi
    WHERE qi.quote_id = p_quote_id AND qi.product_id = v_product_id;

    SELECT product_name INTO v_product_name FROM products WHERE id = v_product_id;

    IF v_booked IS NULL OR v_booked <= 0 THEN
      RAISE EXCEPTION 'BOOKING_OVERDRAWN: % is not booked on this quote', COALESCE(v_product_name, v_product_id::text);
    END IF;

    SELECT quantity_drawn INTO v_drawn
    FROM quote_product_draws
    WHERE quote_id = p_quote_id AND product_id = v_product_id;
    v_drawn := COALESCE(v_drawn, 0);
    -- LAYER2<<< job reservations also consume the booking (§6.5): subtract live
    -- job draws so demand a job already reserved can't be re-drawn to an order
    -- (no double-fulfilment via transfer_job_to_invoice + a later order draw).
    SELECT COALESCE(SUM(quantity_drawn), 0) INTO v_job_drawn
    FROM job_product_draws
    WHERE quote_id = p_quote_id AND product_id = v_product_id;
    v_remaining := GREATEST(v_booked - v_drawn - v_job_drawn, 0);
    IF v_qty > v_remaining THEN
      RAISE EXCEPTION 'BOOKING_OVERDRAWN: %: requested %, only % remaining (booked %, already drawn %)',
        COALESCE(v_product_name, v_product_id::text), v_qty, v_remaining, v_booked, (v_drawn + v_job_drawn);
    END IF;
    -- >>>LAYER2  (baseline: v_remaining := GREATEST(v_booked - v_drawn, 0); and
    -- the message's last arg was v_drawn — text is unchanged, only the value.)

    v_line_count := v_line_count + 1;
    v_line_total := ROUND(v_wavg_price * v_qty, 2);
    v_line_cost := ROUND(v_wavg_cost * v_qty, 2);
    v_acres := CASE WHEN v_total_acres > 0 THEN ROUND(v_total_acres * v_qty / v_booked, 2) ELSE NULL END;

    INSERT INTO order_items (order_id, product_id, product_name,
      price_per_unit, cost_per_unit, acres,
      total_units_needed, unit_size, total_price, profit, net_margin,
      quantity_delivered, quantity_remaining, sort_order, notes)
    VALUES (v_order_id, v_product_id, COALESCE(v_product_name, ''),
      v_wavg_price, v_wavg_cost, v_acres,
      v_qty, v_unit_size, v_line_total, v_line_total - v_line_cost,
      CASE WHEN v_wavg_price > 0 THEN ROUND(((v_wavg_price - v_wavg_cost) / v_wavg_price) * 100, 2) ELSE 0 END,
      0, v_qty, v_line_count,
      'Drawn from booking ' || v_quote.quote_number);

    -- Inventory: warn (never block) on net position, then prebook the draw
    SELECT * INTO v_inv FROM inventory
    WHERE product_id = v_product_id AND location = 'Main Warehouse' FOR UPDATE;
    IF NOT FOUND THEN
      v_shortfalls := array_append(v_shortfalls,
        COALESCE(v_product_name, 'Unknown product') || ': need ' || v_qty || ', net position is 0 (no inventory record)');
      INSERT INTO inventory (product_id, location, quantity_available, quantity_prebooked, quantity_on_order, unit_size)
      VALUES (v_product_id, 'Main Warehouse', 0, v_qty, 0, v_unit_size);
    ELSE
      v_net_position := v_inv.quantity_available - v_inv.quantity_prebooked + COALESCE(v_inv.quantity_on_order, 0);
      IF v_net_position < v_qty THEN
        v_shortfalls := array_append(v_shortfalls,
          COALESCE(v_product_name, 'Unknown product') || ': need ' || v_qty ||
          ', net position is ' || GREATEST(v_net_position, 0) ||
          ' (on floor: ' || (v_inv.quantity_available - v_inv.quantity_prebooked) ||
          ', on order: ' || COALESCE(v_inv.quantity_on_order, 0) || ')');
      END IF;
      UPDATE inventory SET quantity_prebooked = quantity_prebooked + v_qty, updated_at = now()
      WHERE product_id = v_product_id AND location = 'Main Warehouse';
    END IF;

    INSERT INTO inventory_transactions (product_id, transaction_type, quantity, to_location,
      order_id, performed_by, notes)
    VALUES (v_product_id, 'booked', v_qty, 'Main Warehouse',
      v_order_id, v_actor, 'Pre-booked for order ' || v_order_number || ' (draw from quote ' || v_quote.quote_number || ')');

    -- Move the drawn quantity out of this quote's active holds (FIFO).
    -- Net Free = available − holds − prebooked stays constant: the quantity
    -- leaves the hold bucket and enters the prebooked bucket.
    v_to_consume := v_qty;
    FOR v_hold IN
      SELECT id, quantity FROM inventory_holds
      WHERE source_id = p_quote_id AND product_id = v_product_id AND is_active = true
      ORDER BY created_at
      FOR UPDATE
    LOOP
      EXIT WHEN v_to_consume <= 0;
      IF v_hold.quantity <= v_to_consume THEN
        UPDATE inventory_holds SET quantity = 0, is_active = false, updated_at = now()
        WHERE id = v_hold.id;
        v_to_consume := v_to_consume - v_hold.quantity;
      ELSE
        UPDATE inventory_holds SET quantity = quantity - v_to_consume, updated_at = now()
        WHERE id = v_hold.id;
        v_to_consume := 0;
      END IF;
    END LOOP;

    -- Ledger: record the draw
    INSERT INTO quote_product_draws (quote_id, product_id, quantity_drawn)
    VALUES (p_quote_id, v_product_id, v_qty)
    ON CONFLICT (quote_id, product_id)
    DO UPDATE SET quantity_drawn = quote_product_draws.quantity_drawn + EXCLUDED.quantity_drawn,
                  updated_at = now();

    v_total_price := v_total_price + v_line_total;
    v_total_cost := v_total_cost + v_line_cost;
    v_lines := v_lines || jsonb_build_object(
      'product_id', v_product_id,
      'product_name', v_product_name,
      'drawn', v_qty,
      'remaining', v_remaining - v_qty);
  END LOOP;

  IF v_line_count = 0 THEN
    RAISE EXCEPTION 'EMPTY_DRAW: no draw lines supplied';
  END IF;

  v_total_profit := v_total_price - v_total_cost;
  v_total_margin_pct := CASE WHEN v_total_price > 0 THEN ROUND((v_total_profit / v_total_price) * 100, 2) ELSE 0 END;
  UPDATE orders SET total_price = v_total_price, total_cost = v_total_cost,
    total_profit = v_total_profit, total_margin_pct = v_total_margin_pct
  WHERE id = v_order_id;

  PERFORM _insert_commissions_for_order(
    v_order_id, v_quote.customer_id, v_total_profit,
    v_quote.commission_split, current_date
  );

  -- Fully drawn? Then the booking closes as 'accepted' (enforcer-legal from
  -- sent/revised) and the hold-release trigger clears any leftover holds.
  -- LAYER2 NOTE: this stays on ORDER draws only (quote_product_draws) by design
  -- — job draws are reversible, so letting them flip status to 'accepted' would
  -- require un-accepting on job cancel (a quote-lifecycle change out of scope).
  SELECT COALESCE(bool_and(COALESCE(d.quantity_drawn, 0) >= b.booked), true) INTO v_fully_drawn
  FROM (
    SELECT product_id, SUM(COALESCE(total_units_needed, 0)) AS booked
    FROM quote_items WHERE quote_id = p_quote_id
    GROUP BY product_id
  ) b
  LEFT JOIN quote_product_draws d
    ON d.quote_id = p_quote_id AND d.product_id = b.product_id
  WHERE b.booked > 0;

  IF v_fully_drawn THEN
    UPDATE quotes SET status = 'accepted', updated_at = now() WHERE id = p_quote_id;
  ELSE
    UPDATE quotes SET updated_at = now() WHERE id = p_quote_id;
  END IF;

  INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_role, new_values, total_impact_cents, description)
  VALUES (
    'quote_converted', 'order', v_order_id, v_actor_role,
    jsonb_build_object(
      'quote_id', p_quote_id,
      'quote_number', v_quote.quote_number,
      'order_number', v_order_number,
      'customer_id', v_quote.customer_id,
      'customer_name', COALESCE(v_customer.farm_name, 'unknown'),
      'total_price_dollars', v_total_price,
      'booking_draw', true,
      'fully_drawn', v_fully_drawn,
      'lines', v_lines,
      'inventory_warnings', to_jsonb(v_shortfalls)
    ),
    ROUND(v_total_price * 100)::bigint,
    'Drew down quote ' || v_quote.quote_number || ' to order ' || v_order_number ||
      ' for ' || COALESCE(v_customer.farm_name, 'customer') ||
      CASE WHEN v_fully_drawn THEN ' (booking now fully drawn)' ELSE ' (partial draw — booking stays open)' END ||
      CASE WHEN array_length(v_shortfalls, 1) > 0
        THEN ' (inventory shortfalls: ' || array_to_string(v_shortfalls, '; ') || ')'
        ELSE '' END
  );

  INSERT INTO activity_feed (event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id)
  VALUES ('order_created',
    'Order ' || v_order_number || ' created from booking ' || v_quote.quote_number ||
    ' for ' || COALESCE(v_customer.farm_name, 'customer') ||
    CASE WHEN v_fully_drawn THEN ' — booking fully drawn' ELSE ' — partial draw' END,
    v_actor, 'order', v_order_id, v_quote.customer_id);

  v_result := jsonb_build_object(
    'success', true, 'status', 'created',
    'order_id', v_order_id, 'order_number', v_order_number,
    'warnings', to_jsonb(v_shortfalls),
    'fully_drawn', v_fully_drawn,
    'lines', v_lines);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'draw_down_quote', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."draw_down_quote"("p_quote_id" "uuid", "p_draws" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_quote"("p_source_quote_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_orig record;
  v_new_quote_id uuid;
  v_new_quote_number text;
  v_section record;
  v_new_section_id uuid;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'duplicate_quote');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_orig FROM quotes WHERE id = p_source_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'QUOTE_NOT_FOUND'; END IF;

  SELECT generate_quote_number() INTO v_new_quote_number;

  INSERT INTO quotes (
    quote_number, customer_id, created_by, tier, status,
    commission_split, total_price, total_cost, total_profit,
    total_margin_pct, valid_days, expires_at,
    header_notes, footer_notes
  ) VALUES (
    v_new_quote_number,
    v_orig.customer_id,
    v_actor,
    v_orig.tier,
    'draft',
    v_orig.commission_split,
    v_orig.total_price,
    v_orig.total_cost,
    v_orig.total_profit,
    v_orig.total_margin_pct,
    COALESCE(v_orig.valid_days, 15),
    now() + (COALESCE(v_orig.valid_days, 15) || ' days')::interval,
    v_orig.header_notes,
    v_orig.footer_notes
  ) RETURNING id INTO v_new_quote_id;

  FOR v_section IN
    SELECT * FROM quote_sections WHERE quote_id = p_source_quote_id ORDER BY sort_order
  LOOP
    INSERT INTO quote_sections (
      quote_id, section_name, sort_order, section_notes
    ) VALUES (
      v_new_quote_id,
      v_section.section_name,
      v_section.sort_order,
      v_section.section_notes
    ) RETURNING id INTO v_new_section_id;

    INSERT INTO quote_items (
      quote_id, section_id, product_id, sort_order, notes,
      price_per_unit, current_cost, suggested_rate, actual_rate,
      rate_unit, oz_per_acre, price_per_acre, acres,
      total_units_needed, unit_size, profit, total_price, net_margin
    )
    SELECT
      v_new_quote_id,
      v_new_section_id,
      product_id, sort_order, notes,
      price_per_unit, current_cost, suggested_rate, actual_rate,
      rate_unit, oz_per_acre, price_per_acre, acres,
      total_units_needed, unit_size, profit, total_price, net_margin
    FROM quote_items
    WHERE quote_id = p_source_quote_id AND section_id = v_section.id
    ORDER BY sort_order;
  END LOOP;

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type,
    related_entity_id,
    customer_id
  ) VALUES (
    'quote_created',
    'Quote ' || v_new_quote_number || ' duplicated from ' || v_orig.quote_number,
    v_actor, 'quote', v_new_quote_id, v_orig.customer_id
  );

  v_result := jsonb_build_object(
    'status', 'duplicated',
    'quote_id', v_new_quote_id,
    'quote_number', v_new_quote_number
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'duplicate_quote', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."duplicate_quote"("p_source_quote_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."edit_delivery"("p_delivery_id" "uuid", "p_assigned_driver" "uuid" DEFAULT NULL::"uuid", "p_scheduled_date" "date" DEFAULT NULL::"date", "p_scheduled_time" "text" DEFAULT NULL::"text", "p_delivery_window_start" "text" DEFAULT NULL::"text", "p_delivery_window_end" "text" DEFAULT NULL::"text", "p_delivery_address_id" "uuid" DEFAULT NULL::"uuid", "p_delivery_notes" "text" DEFAULT NULL::"text", "p_priority" "text" DEFAULT NULL::"text", "p_items" "jsonb" DEFAULT NULL::"jsonb", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_delivery record;
  v_actor uuid;
  v_old_driver uuid;
  v_item jsonb;
  v_oi record;
  v_other_scheduled numeric;
  v_requested_qty numeric;
  v_max_allowed numeric;
  v_items_changed boolean := false;
  v_cached_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_cached_result
      FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'edit_delivery';
    IF v_cached_result IS NOT NULL THEN RETURN v_cached_result; END IF;
  END IF;

  SELECT * INTO v_delivery
  FROM deliveries WHERE id = p_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Delivery not found';
  END IF;

  IF v_delivery.status NOT IN ('scheduled', 'in_progress') THEN
    RAISE EXCEPTION 'Cannot edit a % delivery', v_delivery.status;
  END IF;

  v_old_driver := v_delivery.assigned_driver;

  UPDATE deliveries SET
    assigned_driver = COALESCE(p_assigned_driver, assigned_driver),
    scheduled_date = COALESCE(p_scheduled_date, scheduled_date),
    scheduled_time = CASE WHEN p_scheduled_time IS NOT NULL THEN p_scheduled_time ELSE scheduled_time END,
    delivery_window_start = CASE WHEN p_delivery_window_start IS NOT NULL THEN p_delivery_window_start ELSE delivery_window_start END,
    delivery_window_end = CASE WHEN p_delivery_window_end IS NOT NULL THEN p_delivery_window_end ELSE delivery_window_end END,
    delivery_address_id = CASE WHEN p_delivery_address_id IS NOT NULL THEN p_delivery_address_id ELSE delivery_address_id END,
    delivery_notes = CASE WHEN p_delivery_notes IS NOT NULL THEN p_delivery_notes ELSE delivery_notes END,
    priority = COALESCE(p_priority, priority),
    last_edited_by = v_actor,
    last_edited_at = now(),
    updated_at = now()
  WHERE id = p_delivery_id;

  IF p_items IS NOT NULL AND v_delivery.status = 'scheduled' THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      v_requested_qty := (v_item->>'quantity')::numeric;

      IF v_requested_qty <= 0 THEN
        CONTINUE;
      END IF;

      SELECT * INTO v_oi
      FROM order_items
      WHERE id = (v_item->>'order_item_id')::uuid
        AND order_id = v_delivery.order_id
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Order item % not found on order %',
          v_item->>'order_item_id', v_delivery.order_id;
      END IF;

      SELECT COALESCE(SUM(di.quantity), 0) INTO v_other_scheduled
      FROM delivery_items di
      JOIN deliveries d ON d.id = di.delivery_id
      WHERE di.order_item_id = v_oi.id
        AND d.status IN ('scheduled', 'in_progress')
        AND d.id != p_delivery_id;

      v_max_allowed := v_oi.quantity_remaining - v_other_scheduled;

      IF v_requested_qty > v_max_allowed THEN
        RAISE EXCEPTION 'Cannot schedule % units of % — only % available (% remaining on order, % on other deliveries)',
          v_requested_qty,
          v_oi.product_name,
          GREATEST(v_max_allowed, 0),
          v_oi.quantity_remaining,
          v_other_scheduled;
      END IF;
    END LOOP;

    DELETE FROM delivery_items WHERE delivery_id = p_delivery_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      IF (v_item->>'quantity')::numeric > 0 THEN
        INSERT INTO delivery_items (
          delivery_id, order_item_id, product_id, quantity, unit_size
        ) VALUES (
          p_delivery_id,
          (v_item->>'order_item_id')::uuid,
          (v_item->>'product_id')::uuid,
          (v_item->>'quantity')::numeric,
          v_item->>'unit_size'
        );
      END IF;
    END LOOP;

    v_items_changed := true;
  END IF;

  IF p_items IS NOT NULL AND v_delivery.status = 'in_progress' THEN
    RAISE EXCEPTION 'Cannot edit delivery items once delivery is in progress';
  END IF;

  IF p_assigned_driver IS NOT NULL AND v_old_driver IS DISTINCT FROM p_assigned_driver THEN
    IF v_old_driver IS NOT NULL THEN
      INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
      VALUES (
        v_old_driver,
        'Delivery Reassigned',
        'Delivery ' || v_delivery.delivery_number || ' has been reassigned to another driver.',
        'delivery_update', 'delivery', p_delivery_id
      );
    END IF;

    INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
    VALUES (
      p_assigned_driver,
      'New Delivery Assigned',
      'Delivery ' || v_delivery.delivery_number || ' has been assigned to you.',
      'delivery_update', 'delivery', p_delivery_id
    );
  END IF;

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'delivery_edited',
    'Delivery ' || v_delivery.delivery_number || ' edited' ||
      CASE WHEN v_items_changed THEN ' (items updated)' ELSE '' END,
    v_actor, 'delivery', p_delivery_id, v_delivery.customer_id
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'edit_delivery',
      jsonb_build_object('status', 'updated', 'delivery_id', p_delivery_id, 'items_changed', v_items_changed)
    );
  END IF;

  RETURN jsonb_build_object('status', 'updated', 'delivery_id', p_delivery_id, 'items_changed', v_items_changed);
END;
$$;


ALTER FUNCTION "public"."edit_delivery"("p_delivery_id" "uuid", "p_assigned_driver" "uuid", "p_scheduled_date" "date", "p_scheduled_time" "text", "p_delivery_window_start" "text", "p_delivery_window_end" "text", "p_delivery_address_id" "uuid", "p_delivery_notes" "text", "p_priority" "text", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."edit_prepay_credit"("p_credit_id" "uuid", "p_new_balance_cents" bigint DEFAULT NULL::bigint, "p_reference_number" "text" DEFAULT NULL::"text", "p_bucket_label" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_credit      record;
  v_old_balance bigint;
  v_delta       bigint;
  v_actor       uuid;
  v_actor_role  text;
  v_existing    jsonb;
  v_sum_applied bigint;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'edit_prepay_credit';
    IF v_existing IS NOT NULL THEN
      RETURN jsonb_build_object('success', true, 'credit_id', p_credit_id, 'idempotent', true);
    END IF;
  END IF;

  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  -- Codex P1 fix (2026-05-16): IS DISTINCT FROM treats NULL (deactivated user
  -- or missing profile row) as "not admin" and raises. Prior `!= 'admin'`
  -- evaluated to NULL when subquery was empty and silently allowed mutation.
  SELECT role INTO v_actor_role
  FROM profiles
  WHERE id = v_actor AND is_active = true;

  IF v_actor_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'Admin access required to edit prepay credits';
  END IF;

  SELECT * INTO v_credit FROM prepay_credits WHERE id = p_credit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Prepay credit not found: %', p_credit_id; END IF;

  v_old_balance := v_credit.balance_cents;

  SELECT COALESCE(SUM(applied_amount_cents), 0) INTO v_sum_applied
  FROM prepay_applications WHERE prepay_credit_id = p_credit_id;

  UPDATE prepay_credits SET
    balance_cents    = COALESCE(p_new_balance_cents, balance_cents),
    original_amount_cents = CASE
      WHEN p_new_balance_cents IS NOT NULL THEN p_new_balance_cents + v_sum_applied
      ELSE original_amount_cents
    END,
    reference_number = COALESCE(p_reference_number, reference_number),
    bucket_label     = COALESCE(p_bucket_label, bucket_label),
    notes            = COALESCE(p_notes, notes),
    updated_at       = now()
  WHERE id = p_credit_id;

  IF p_new_balance_cents IS NOT NULL AND p_new_balance_cents != v_old_balance THEN
    v_delta := p_new_balance_cents - v_old_balance;
    UPDATE customers
    SET prepay_balance_cents = GREATEST(prepay_balance_cents + v_delta, 0)
    WHERE id = v_credit.customer_id;
  END IF;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id,
    actor_user_id, old_values, new_values,
    total_impact_cents, description
  ) VALUES (
    'prepay_edited', 'prepay', p_credit_id, v_actor,
    jsonb_build_object(
      'balance_cents', v_old_balance,
      'original_amount_cents', v_credit.original_amount_cents,
      'sum_applied_cents', v_sum_applied,
      'reference_number', v_credit.reference_number,
      'bucket_label', v_credit.bucket_label
    ),
    jsonb_build_object(
      'balance_cents', COALESCE(p_new_balance_cents, v_old_balance),
      'original_amount_cents', CASE
        WHEN p_new_balance_cents IS NOT NULL THEN p_new_balance_cents + v_sum_applied
        ELSE v_credit.original_amount_cents
      END,
      'reference_number', COALESCE(p_reference_number, v_credit.reference_number),
      'bucket_label', COALESCE(p_bucket_label, v_credit.bucket_label)
    ),
    COALESCE(p_new_balance_cents - v_old_balance, 0),
    'Edited prepay credit ' || COALESCE(v_credit.reference_number, v_credit.id::text)
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'edit_prepay_credit', jsonb_build_object('credit_id', p_credit_id));
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'credit_id', p_credit_id,
    'old_balance_cents', v_old_balance,
    'new_balance_cents', COALESCE(p_new_balance_cents, v_old_balance)
  );
END;
$$;


ALTER FUNCTION "public"."edit_prepay_credit"("p_credit_id" "uuid", "p_new_balance_cents" bigint, "p_reference_number" "text", "p_bucket_label" "text", "p_notes" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_blend_ticket_fields_billed_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_locked boolean;
BEGIN
  -- OLD side (UPDATE/DELETE): block removing or moving a row OUT of a billed ticket.
  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.blend_ticket_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM invoices
       WHERE blend_ticket_id = OLD.blend_ticket_id
         AND status NOT IN ('voided', 'cancelled')
         AND deleted_at IS NULL
    ) INTO v_locked;
    IF v_locked THEN
      RAISE EXCEPTION 'BLEND_TICKET_INVOICE_LOCKED: blend ticket % has an active invoice — void the invoice(s) before changing its field allocations', OLD.blend_ticket_id;
    END IF;
  END IF;
  -- NEW side (INSERT/UPDATE): block adding or moving a row INTO a billed ticket.
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.blend_ticket_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM invoices
       WHERE blend_ticket_id = NEW.blend_ticket_id
         AND status NOT IN ('voided', 'cancelled')
         AND deleted_at IS NULL
    ) INTO v_locked;
    IF v_locked THEN
      RAISE EXCEPTION 'BLEND_TICKET_INVOICE_LOCKED: blend ticket % has an active invoice — void the invoice(s) before changing its field allocations', NEW.blend_ticket_id;
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."enforce_blend_ticket_fields_billed_lock"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_blend_ticket_fields_billed_lock"() IS 'PARKED-009 (codex-driven cycle 6 #1): extends 20260622080000''s content lock to blend_ticket_fields. Mirrors the products-side enforce_blend_ticket_products_billed_lock pattern.';



CREATE OR REPLACE FUNCTION "public"."enforce_blend_ticket_fields_downstream_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ticket_ids uuid[];
BEGIN
  v_ticket_ids := CASE
    WHEN TG_OP = 'INSERT' THEN ARRAY[NEW.blend_ticket_id]
    WHEN TG_OP = 'DELETE' THEN ARRAY[OLD.blend_ticket_id]
    ELSE ARRAY[OLD.blend_ticket_id, NEW.blend_ticket_id]
  END;

  PERFORM id
    FROM public.blend_tickets
   WHERE id = ANY(v_ticket_ids)
   ORDER BY id
   FOR UPDATE;

  IF EXISTS (
       SELECT 1 FROM public.invoices
        WHERE blend_ticket_id = ANY(v_ticket_ids)
          AND deleted_at IS NULL
          AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
     ) OR EXISTS (
       SELECT 1 FROM public.application_records
        WHERE source_type = 'blend_ticket'
          AND source_id = ANY(v_ticket_ids)
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_DOWNSTREAM_FIELDS_LOCKED';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION "public"."enforce_blend_ticket_fields_downstream_lock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_blend_ticket_products_billed_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_locked boolean;
BEGIN
  -- OLD side (UPDATE/DELETE): block removing or MOVING a line OUT of a ticket that has a live invoice
  -- (also closes the reparent bypass — moving a row to an uninvoiced ticket no longer escapes).
  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.blend_ticket_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM invoices
      WHERE blend_ticket_id = OLD.blend_ticket_id
        AND status NOT IN ('voided', 'cancelled')
        AND deleted_at IS NULL
    ) INTO v_locked;
    IF v_locked THEN
      RAISE EXCEPTION 'BLEND_TICKET_INVOICE_LOCKED: blend ticket % has an active invoice — void the invoice(s) before changing its line items', OLD.blend_ticket_id;
    END IF;
  END IF;
  -- NEW side (INSERT/UPDATE): block adding or MOVING a line INTO a ticket that has a live invoice.
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.blend_ticket_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM invoices
      WHERE blend_ticket_id = NEW.blend_ticket_id
        AND status NOT IN ('voided', 'cancelled')
        AND deleted_at IS NULL
    ) INTO v_locked;
    IF v_locked THEN
      RAISE EXCEPTION 'BLEND_TICKET_INVOICE_LOCKED: blend ticket % has an active invoice — void the invoice(s) before changing its line items', NEW.blend_ticket_id;
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."enforce_blend_ticket_products_billed_lock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_delivery_accounting_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old_effective_date date;
  v_new_effective_date date;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'completed' THEN
      v_new_effective_date := COALESCE(
        (NEW.completed_at AT TIME ZONE 'America/Chicago')::date,
        (now() AT TIME ZONE 'America/Chicago')::date
      );
      PERFORM public.check_period_open(v_new_effective_date);
    ELSIF NEW.status = 'voided' THEN
      v_new_effective_date := COALESCE(
        (NEW.completed_at AT TIME ZONE 'America/Chicago')::date,
        NEW.scheduled_date,
        (now() AT TIME ZONE 'America/Chicago')::date
      );
      PERFORM public.check_period_open(v_new_effective_date);
    END IF;

    RETURN NEW;
  END IF;

  IF OLD.status IN ('completed', 'voided')
     AND (
       OLD.status IS DISTINCT FROM NEW.status
       OR OLD.completed_at IS DISTINCT FROM NEW.completed_at
       OR OLD.scheduled_date IS DISTINCT FROM NEW.scheduled_date
     ) THEN
    v_old_effective_date := COALESCE(
      (OLD.completed_at AT TIME ZONE 'America/Chicago')::date,
      OLD.scheduled_date,
      (now() AT TIME ZONE 'America/Chicago')::date
    );
    PERFORM public.check_period_open(v_old_effective_date);
  END IF;

  IF NEW.status = 'completed'
     AND (
       OLD.status IS DISTINCT FROM NEW.status
       OR OLD.completed_at IS DISTINCT FROM NEW.completed_at
       OR OLD.scheduled_date IS DISTINCT FROM NEW.scheduled_date
     ) THEN
    v_new_effective_date := COALESCE(
      (NEW.completed_at AT TIME ZONE 'America/Chicago')::date,
      NEW.scheduled_date,
      (now() AT TIME ZONE 'America/Chicago')::date
    );
    PERFORM public.check_period_open(v_new_effective_date);
  ELSIF NEW.status = 'voided'
        AND (
          OLD.status IS DISTINCT FROM NEW.status
          OR OLD.completed_at IS DISTINCT FROM NEW.completed_at
          OR OLD.scheduled_date IS DISTINCT FROM NEW.scheduled_date
        ) THEN
    v_new_effective_date := COALESCE(
      (NEW.completed_at AT TIME ZONE 'America/Chicago')::date,
      (OLD.completed_at AT TIME ZONE 'America/Chicago')::date,
      NEW.scheduled_date,
      (now() AT TIME ZONE 'America/Chicago')::date
    );
    PERFORM public.check_period_open(v_new_effective_date);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_delivery_accounting_period"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_field_application_type_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- XOR over the field_application boundary: block any update that turns a
  -- field_application invoice into something else, or something else into a
  -- field_application invoice. NULL-safe (NULL treated as non-field).
  IF (COALESCE(OLD.invoice_type, '') = 'field_application')
       <> (COALESCE(NEW.invoice_type, '') = 'field_application') THEN
    RAISE EXCEPTION 'FIELD_APP_TYPE_LOCKED'
      USING DETAIL = format(
        'Invoice %s cannot change invoice_type from %L to %L: the field_application boundary is locked (field-app invoices are segregated; edit via save_field_app_invoice).',
        OLD.id, OLD.invoice_type, NEW.invoice_type),
        ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_field_application_type_lock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_invoice_draft_on_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Credit memos are created already-posted by issue_return_credit (which calls
  -- check_period_open before inserting); they never use the draft -> post flow.
  IF NEW.status <> 'draft' AND NEW.invoice_type <> 'credit_memo' THEN
    RAISE EXCEPTION 'Invoices must be created with status draft. Got: %', NEW.status;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_invoice_draft_on_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_linked_blend_ticket_header_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF (
       NEW.order_link_status = 'linked'
       OR NEW.payment_status = 'billed'
       OR EXISTS (
         SELECT 1 FROM public.invoices
          WHERE blend_ticket_id = NEW.id
            AND deleted_at IS NULL
            AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
       )
       OR EXISTS (
         SELECT 1 FROM public.application_records
          WHERE source_type = 'blend_ticket'
            AND source_id = NEW.id
       )
     )
     AND (
       NEW.status <> 'completed'
       OR NEW.review_status <> 'approved'
       OR NEW.deleted_at IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_SETTLED_LIFECYCLE_INVALID';
  END IF;

  IF (
       EXISTS (
         SELECT 1 FROM public.invoices
          WHERE blend_ticket_id = NEW.id
            AND deleted_at IS NULL
            AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
       )
       OR EXISTS (
         SELECT 1 FROM public.application_records
          WHERE source_type = 'blend_ticket'
            AND source_id = NEW.id
       )
     )
     AND (
       NEW.customer_id IS DISTINCT FROM OLD.customer_id
       OR NEW.season IS DISTINCT FROM OLD.season
       OR NEW.salesman_id IS DISTINCT FROM OLD.salesman_id
       OR NEW.ticket_date IS DISTINCT FROM OLD.ticket_date
       OR NEW.ticket_time IS DISTINCT FROM OLD.ticket_time
       OR NEW.job_number IS DISTINCT FROM OLD.job_number
       OR NEW.job_id IS DISTINCT FROM OLD.job_id
       OR NEW.invoice_number IS DISTINCT FROM OLD.invoice_number
       OR NEW.field_id IS DISTINCT FROM OLD.field_id
       OR NEW.field_names IS DISTINCT FROM OLD.field_names
       OR NEW.driver_name IS DISTINCT FROM OLD.driver_name
       OR NEW.applicator_id IS DISTINCT FROM OLD.applicator_id
       OR NEW.applicator_name IS DISTINCT FROM OLD.applicator_name
       OR NEW.mixer_name IS DISTINCT FROM OLD.mixer_name
       OR NEW.tank_number IS DISTINCT FROM OLD.tank_number
       OR NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id
       OR NEW.vehicle_info IS DISTINCT FROM OLD.vehicle_info
       OR NEW.application_service_id IS DISTINCT FROM OLD.application_service_id
       OR NEW.total_acres IS DISTINCT FROM OLD.total_acres
       OR NEW.application_rate IS DISTINCT FROM OLD.application_rate
       OR NEW.total_volume IS DISTINCT FROM OLD.total_volume
       OR NEW.total_volume_unit IS DISTINCT FROM OLD.total_volume_unit
       OR NEW.notes IS DISTINCT FROM OLD.notes
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_DOWNSTREAM_CONTENT_LOCKED';
  END IF;

  IF NEW.deleted_at IS NOT NULL
     AND NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
     AND (
       OLD.order_link_status = 'linked'
       OR OLD.payment_status = 'billed'
       OR EXISTS (
         SELECT 1 FROM public.invoices
          WHERE blend_ticket_id = OLD.id
            AND deleted_at IS NULL
            AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
       )
       OR EXISTS (
         SELECT 1 FROM public.application_records
          WHERE source_type = 'blend_ticket'
            AND source_id = OLD.id
       )
       OR EXISTS (
         SELECT 1 FROM public.ocr_processing_queue
          WHERE blend_ticket_id = OLD.id
            AND status IN ('pending', 'processing')
       )
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_DELETE_LIFECYCLE_LOCKED';
  END IF;

  IF NEW.payment_status = 'billed'
     AND NEW.order_link_status <> 'linked'
     AND NOT EXISTS (
       SELECT 1 FROM public.invoices
        WHERE blend_ticket_id = NEW.id
          AND deleted_at IS NULL
          AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_BILLING_REQUIRES_PROVENANCE';
  END IF;

  IF OLD.payment_status = 'billed'
     AND NEW.payment_status IS DISTINCT FROM 'billed'
     AND EXISTS (
       SELECT 1 FROM public.invoices
        WHERE blend_ticket_id = OLD.id
          AND deleted_at IS NULL
          AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_ACTIVE_INVOICE_BILLING_LOCK';
  END IF;

  -- Only the link/unlink RPC ordering may change this lifecycle flag: link
  -- rows are inserted before setting linked, and deleted before setting
  -- unlinked. Direct office table updates cannot forge either state.
  IF OLD.order_link_status IS DISTINCT FROM 'linked'
     AND NEW.order_link_status = 'linked'
     AND NOT EXISTS (
       SELECT 1 FROM public.blend_ticket_to_order_items
        WHERE blend_ticket_id = OLD.id
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_LINK_STATE_INVALID: linked status requires order-item links';
  END IF;

  IF OLD.order_link_status = 'linked'
     AND NEW.order_link_status IS DISTINCT FROM 'linked'
     AND EXISTS (
       SELECT 1 FROM public.blend_ticket_to_order_items
        WHERE blend_ticket_id = OLD.id
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_LINK_STATE_INVALID: remove order-item links before unlinking';
  END IF;

  IF OLD.order_link_status = 'linked'
     AND NEW.order_link_status = 'linked'
     AND (
       NEW.customer_id IS DISTINCT FROM OLD.customer_id
       OR NEW.season IS DISTINCT FROM OLD.season
       OR NEW.salesman_id IS DISTINCT FROM OLD.salesman_id
       OR NEW.ticket_date IS DISTINCT FROM OLD.ticket_date
       OR NEW.ticket_time IS DISTINCT FROM OLD.ticket_time
       OR NEW.job_number IS DISTINCT FROM OLD.job_number
       OR NEW.job_id IS DISTINCT FROM OLD.job_id
       OR NEW.invoice_number IS DISTINCT FROM OLD.invoice_number
       OR NEW.driver_name IS DISTINCT FROM OLD.driver_name
       OR NEW.applicator_id IS DISTINCT FROM OLD.applicator_id
       OR NEW.applicator_name IS DISTINCT FROM OLD.applicator_name
       OR NEW.mixer_name IS DISTINCT FROM OLD.mixer_name
       OR NEW.tank_number IS DISTINCT FROM OLD.tank_number
       OR NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id
       OR NEW.vehicle_info IS DISTINCT FROM OLD.vehicle_info
       OR NEW.application_service_id IS DISTINCT FROM OLD.application_service_id
       OR NEW.field_id IS DISTINCT FROM OLD.field_id
       OR NEW.field_names IS DISTINCT FROM OLD.field_names
       OR NEW.total_acres IS DISTINCT FROM OLD.total_acres
       OR NEW.application_rate IS DISTINCT FROM OLD.application_rate
       OR NEW.total_volume IS DISTINCT FROM OLD.total_volume
       OR NEW.total_volume_unit IS DISTINCT FROM OLD.total_volume_unit
       OR NEW.notes IS DISTINCT FROM OLD.notes
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_LINKED_CONTENT_LOCKED: unlink before changing ticket content';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_linked_blend_ticket_header_lock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_linked_blend_ticket_product_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ticket_ids uuid[];
BEGIN
  v_ticket_ids := CASE
    WHEN TG_OP = 'INSERT' THEN ARRAY[NEW.blend_ticket_id]
    WHEN TG_OP = 'DELETE' THEN ARRAY[OLD.blend_ticket_id]
    ELSE ARRAY[OLD.blend_ticket_id, NEW.blend_ticket_id]
  END;

  -- Lock both parents in UUID order so an UPDATE cannot re-parent a product
  -- out of a linked ticket, and concurrent link/edit operations serialize.
  PERFORM id
    FROM public.blend_tickets
   WHERE id = ANY(v_ticket_ids)
   ORDER BY id
   FOR UPDATE;

  IF EXISTS (
    SELECT 1
      FROM public.blend_tickets
     WHERE id = ANY(v_ticket_ids)
       AND order_link_status = 'linked'
  ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_LINKED_CONTENT_LOCKED: unlink before changing products';
  END IF;

  -- A direct invoice does not require an order link. Treat every non-terminal
  -- invoice as downstream provenance, and run as the function owner so invoice
  -- RLS cannot hide an admin-owned invoice from a sales caller. Voided and
  -- cancelled invoices are terminal and intentionally release this lock.
  IF EXISTS (
       SELECT 1
         FROM public.invoices
        WHERE blend_ticket_id = ANY(v_ticket_ids)
          AND deleted_at IS NULL
          AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
     ) OR EXISTS (
       SELECT 1
         FROM public.application_records
        WHERE source_type = 'blend_ticket'
          AND source_id = ANY(v_ticket_ids)
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_DOWNSTREAM_CONTENT_LOCKED: reverse downstream records before changing products';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION "public"."enforce_linked_blend_ticket_product_lock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_quote_accepted_fully_drawn"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_fully_drawn boolean;
BEGIN
  IF NEW.status = 'accepted' AND OLD.status IS DISTINCT FROM 'accepted' THEN
    -- Canonical RPC/admin escape hatch (convert_quote_to_order brackets its
    -- own status write AFTER explicitly guarding the draws ledger).
    IF _is_admin_override() THEN RETURN NEW; END IF;

    IF EXISTS (
      SELECT 1 FROM quote_product_draws
      WHERE quote_id = NEW.id AND quantity_drawn > 0
    )
    -- LAYER2<<< job reservations count as draws too (§6.5)
    OR EXISTS (
      SELECT 1 FROM job_product_draws
      WHERE quote_id = NEW.id AND quantity_drawn > 0
    )
    -- >>>LAYER2
    THEN
      -- v_fully_drawn counts ORDER draws ONLY: job draws are reversible until a
      -- job completes, so they must not satisfy 'accepted' (a later job cancel
      -- would strand restored balance). A quote with a live job draw that isn't
      -- fully ORDER-drawn therefore raises BOOKING_PARTIALLY_DRAWN below.
      --
      -- Codex A+B P1 #2: check for a REVERSIBLE (scheduled/in_progress) job draw
      -- DIRECTLY against job_product_draws, BEFORE the booked join — otherwise a
      -- save_quote edit that dropped the job-drawn product from quote_items leaves
      -- the booked set empty for that product, and COALESCE(bool_and(...), true)
      -- would wrongly report fully-drawn, letting an accept release/strand the
      -- booking held under the job. Any live reversible job draw => not fully drawn.
      IF EXISTS (
        SELECT 1 FROM job_product_draws jpd
        JOIN jobs j ON j.id = jpd.job_id
        WHERE jpd.quote_id = NEW.id AND jpd.quantity_drawn > 0
          AND j.deleted_at IS NULL
          AND j.status IN ('scheduled', 'in_progress')
      ) THEN
        v_fully_drawn := false;
      ELSE
        SELECT COALESCE(bool_and(COALESCE(d.quantity_drawn, 0) >= b.booked), true) INTO v_fully_drawn
        FROM (
          SELECT product_id, SUM(COALESCE(total_units_needed, 0)) AS booked
          FROM quote_items WHERE quote_id = NEW.id
          GROUP BY product_id
        ) b
        LEFT JOIN quote_product_draws d
          ON d.quote_id = NEW.id AND d.product_id = b.product_id
        WHERE b.booked > 0;
      END IF;

      IF NOT v_fully_drawn THEN
        RAISE EXCEPTION 'BOOKING_PARTIALLY_DRAWN: cannot mark quote % accepted — the booking still has an undrawn balance', NEW.quote_number;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_quote_accepted_fully_drawn"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_return_lifecycle_rpc_owned"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status NOT IN ('requested', 'rejected', 'cancelled') THEN
      RAISE EXCEPTION 'RETURN_DELETE_STATUS_LOCKED: only requested, rejected, or cancelled returns may be deleted';
    END IF;

    RETURN OLD;
  END IF;

  IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
     AND OLD.status NOT IN ('requested', 'rejected', 'cancelled') THEN
    RAISE EXCEPTION 'RETURN_DELETE_STATUS_LOCKED: only requested, rejected, or cancelled returns may be soft-deleted';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status
     OR NEW.requested_at IS DISTINCT FROM OLD.requested_at
     OR NEW.approved_by IS DISTINCT FROM OLD.approved_by
     OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
     OR NEW.received_by IS DISTINCT FROM OLD.received_by
     OR NEW.received_at IS DISTINCT FROM OLD.received_at
     OR NEW.cancelled_by IS DISTINCT FROM OLD.cancelled_by
     OR NEW.cancelled_at IS DISTINCT FROM OLD.cancelled_at
     OR NEW.cancellation_reason IS DISTINCT FROM OLD.cancellation_reason
     OR NEW.credit_invoice_id IS DISTINCT FROM OLD.credit_invoice_id
     OR NEW.total_credit_cents IS DISTINCT FROM OLD.total_credit_cents
     OR NEW.credited_by IS DISTINCT FROM OLD.credited_by
     OR NEW.credited_at IS DISTINCT FROM OLD.credited_at THEN
    IF public._is_admin_override()
       OR current_setting('app.return_rpc', true) = 'true' THEN
      RETURN NEW;
    END IF;

    RAISE EXCEPTION 'RETURN_LIFECYCLE_VIA_RPC_ONLY: return lifecycle and credit fields must be changed through return RPCs';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_return_lifecycle_rpc_owned"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_return_source_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.order_id IS DISTINCT FROM OLD.order_id
     OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
     OR NEW.return_number IS DISTINCT FROM OLD.return_number
     OR NEW.requested_by IS DISTINCT FROM OLD.requested_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'RETURN_SOURCE_IMMUTABLE';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_return_source_immutable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_sql_readonly"("sql_query" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_trimmed text;
BEGIN
  -- Trim whitespace and normalize
  v_trimmed := btrim(regexp_replace(sql_query, E'^\\s+', '', 'g'));
  v_trimmed := lower(v_trimmed);
  
  -- Only allow queries that START with SELECT or WITH (CTEs)
  IF NOT (v_trimmed LIKE 'select%' OR v_trimmed LIKE 'with%') THEN
    RAISE EXCEPTION 'Only SELECT queries are allowed';
  END IF;

  EXECUTE 'SELECT jsonb_agg(row_to_json(t)) FROM (' || sql_query || ') t'
    INTO v_result;
  
  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."execute_sql_readonly"("sql_query" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."execute_sql_readonly"("sql_query" "text") IS 'Read-only SQL executor for schema integrity tests. Only allows SELECT/WITH queries.';



CREATE OR REPLACE FUNCTION "public"."field_app_priced_quantity"("p_applied_qty" numeric, "p_rate_unit" "text", "p_inventory_unit" "text", "p_product_form" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  r  text := lower(btrim(coalesce(p_rate_unit, '')));
  i  text := lower(btrim(coalesce(p_inventory_unit, '')));
  sr numeric;  -- size of the rate unit in the form's base unit
  si numeric;  -- size of the inventory unit in the form's base unit
BEGIN
  IF p_applied_qty IS NULL THEN RETURN NULL; END IF;
  IF r = i THEN RETURN p_applied_qty; END IF;            -- same unit: no conversion needed
  IF r = '' OR i = '' THEN RETURN NULL; END IF;
  IF lower(coalesce(p_product_form, '')) = 'dry' THEN
    -- Dry base = ounce. (dry oz == oz == 1; lb = 16; ton = 32000.)
    sr := CASE WHEN r IN ('oz','dry oz','ounce','ounces') THEN 1
               WHEN r IN ('lb','lbs','pound','pounds')    THEN 16
               WHEN r IN ('ton','tons')                   THEN 32000 ELSE NULL END;
    si := CASE WHEN i IN ('oz','dry oz','ounce','ounces') THEN 1
               WHEN i IN ('lb','lbs','pound','pounds')    THEN 16
               WHEN i IN ('ton','tons')                   THEN 32000 ELSE NULL END;
  ELSE
    -- Liquid base = fluid ounce. (oz/fl oz = 1; pt = 16; qt = 32; gal = 128.)
    -- NULL/unknown product_form is treated as liquid, matching convert_to_gl_lb.
    sr := CASE WHEN r IN ('oz','fl oz','floz','fluid ounce') THEN 1
               WHEN r IN ('pt','pint','pints')                THEN 16
               WHEN r IN ('qt','quart','quarts')              THEN 32
               WHEN r IN ('gl','gal','gallon','gallons')      THEN 128 ELSE NULL END;
    si := CASE WHEN i IN ('oz','fl oz','floz','fluid ounce') THEN 1
               WHEN i IN ('pt','pint','pints')                THEN 16
               WHEN i IN ('qt','quart','quarts')              THEN 32
               WHEN i IN ('gl','gal','gallon','gallons')      THEN 128 ELSE NULL END;
  END IF;
  IF sr IS NULL OR si IS NULL THEN RETURN NULL; END IF;  -- not convertible -> caller errors
  RETURN p_applied_qty * sr / si;                        -- qty in inventory (pricing) unit
END;
$$;


ALTER FUNCTION "public"."field_app_priced_quantity"("p_applied_qty" numeric, "p_rate_unit" "text", "p_inventory_unit" "text", "p_product_form" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fields_acre_authority_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('app.acre_authority_write', true) = 'on' THEN
    RETURN NEW;   -- a SECURITY DEFINER acreage RPC authorized this write
  END IF;
  IF TG_OP = 'INSERT' THEN
    -- a direct field INSERT must not seed the authority columns (save_field leaves them NULL;
    -- they are populated only later by set_field_boundary / set_field_override_acres).
    IF NEW.measured_acres IS NOT NULL OR NEW.override_acres IS NOT NULL OR NEW.boundary_geom IS NOT NULL THEN
      RAISE EXCEPTION 'ACRE_AUTHORITY_VIOLATION: measured_acres/override_acres/boundary_geom are set only by set_field_boundary / set_field_override_acres, not on a direct insert';
    END IF;
  ELSE  -- UPDATE: boundary_geom compared via WKB bytes (geometry = geometry is ambiguous in PostGIS).
    IF NEW.measured_acres IS DISTINCT FROM OLD.measured_acres
       OR NEW.override_acres IS DISTINCT FROM OLD.override_acres
       OR ST_AsBinary(NEW.boundary_geom) IS DISTINCT FROM ST_AsBinary(OLD.boundary_geom) THEN
      RAISE EXCEPTION 'ACRE_AUTHORITY_VIOLATION: measured_acres/override_acres/boundary_geom are written only by set_field_boundary / set_field_override_acres';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fields_acre_authority_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financial_dashboard_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'permission denied: admin role required';
  END IF;

  WITH
  order_agg AS (
    SELECT
      COALESCE(SUM(total_price), 0) AS total_revenue,
      COALESCE(SUM(total_profit), 0) AS total_profit
    FROM public.orders
    WHERE deleted_at IS NULL
      AND status NOT IN ('cancelled', 'voided', 'draft')
  ),
  quote_agg AS (
    SELECT
      COUNT(*) FILTER (WHERE status = 'draft') AS draft_count,
      COUNT(*) FILTER (WHERE status = 'sent') AS sent_count,
      COUNT(*) FILTER (WHERE status = 'accepted') AS accepted_count,
      COALESCE(SUM(total_price) FILTER (WHERE status IN ('draft', 'sent')), 0) AS pipeline_value
    FROM public.quotes
  ),
  monthly AS (
    SELECT jsonb_agg(row_to_json(m)::jsonb ORDER BY m.month) AS arr
    FROM (
      SELECT
        TO_CHAR(COALESCE(order_date, created_at::date), 'YYYY-MM') AS month,
        COALESCE(SUM(total_price), 0) AS revenue,
        COALESCE(SUM(total_profit), 0) AS profit
      FROM public.orders
      WHERE deleted_at IS NULL
        AND status NOT IN ('cancelled', 'voided', 'draft')
      GROUP BY 1
      ORDER BY 1 DESC
      LIMIT 12
    ) m
  ),
  top_cust AS (
    SELECT jsonb_agg(row_to_json(tc)::jsonb ORDER BY tc.total DESC) AS arr
    FROM (
      SELECT c.farm_name, COALESCE(SUM(o.total_price), 0) AS total
      FROM public.orders o
      JOIN public.customers c ON c.id = o.customer_id
      WHERE o.deleted_at IS NULL
        AND o.status NOT IN ('cancelled', 'voided', 'draft')
      GROUP BY c.id, c.farm_name
      ORDER BY total DESC
      LIMIT 5
    ) tc
  ),
  ar AS (
    SELECT COALESCE(SUM(GREATEST(balance_cents, 0)), 0) / 100.0 AS balance
    FROM public.invoices
    WHERE status IN ('posted', 'overdue')
      AND deleted_at IS NULL
  ),
  over_credit AS (
    SELECT COUNT(*) AS cnt
    FROM public.customers c
    WHERE c.credit_limit_cents IS NOT NULL
      AND c.credit_limit_cents > 0
      AND (
        SELECT COALESCE(SUM(GREATEST(i.balance_cents, 0)), 0)
        FROM public.invoices i
        WHERE i.customer_id = c.id
          AND i.status IN ('posted', 'overdue')
          AND i.deleted_at IS NULL
      ) > c.credit_limit_cents
  ),
  ar_aging AS (
    SELECT
      COALESCE(SUM(CASE WHEN age_days <= 30 THEN balance ELSE 0 END), 0) AS current_bucket,
      COALESCE(SUM(CASE WHEN age_days BETWEEN 31 AND 60 THEN balance ELSE 0 END), 0) AS days_31_60,
      COALESCE(SUM(CASE WHEN age_days BETWEEN 61 AND 90 THEN balance ELSE 0 END), 0) AS days_61_90,
      COALESCE(SUM(CASE WHEN age_days > 90 THEN balance ELSE 0 END), 0) AS days_90_plus
    FROM (
      SELECT
        GREATEST(i.balance_cents, 0) / 100.0 AS balance,
        EXTRACT(DAY FROM NOW() - COALESCE(i.due_date, i.invoice_date))::int AS age_days
      FROM public.invoices i
      WHERE i.status IN ('posted', 'overdue')
        AND i.balance_cents > 0
        AND i.deleted_at IS NULL
    ) aged
  ),
  prepay_bal AS (
    SELECT COALESCE(SUM(prepay_balance_cents), 0) / 100.0 AS total_unallocated
    FROM public.customers
    WHERE prepay_balance_cents > 0
  ),
  commission_owed AS (
    SELECT COALESCE(SUM(commission_amount), 0) AS total_owed
    FROM public.commissions
    WHERE status = 'pending'
      AND paid_date IS NULL
  ),
  period_info AS (
    SELECT
      COALESCE(TO_CHAR(period_start, 'Mon YYYY'), TO_CHAR(NOW(), 'Mon YYYY')) AS name,
      COALESCE(status, 'open') AS status,
      CASE
        WHEN period_end IS NOT NULL
          THEN GREATEST(EXTRACT(DAY FROM period_end - NOW())::int, 0)
        ELSE EXTRACT(DAY FROM (DATE_TRUNC('month', NOW()) + INTERVAL '1 month' - INTERVAL '1 day') - NOW())::int
      END AS days_remaining
    FROM public.accounting_periods
    WHERE status = 'open'
    ORDER BY period_start DESC
    LIMIT 1
  ),
  po_unreceived AS (
    SELECT COALESCE(SUM(
      (poi.quantity_ordered - COALESCE(poi.quantity_received, 0)) * poi.unit_cost
    ), 0) AS value
    FROM public.purchase_order_items poi
    JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
    WHERE po.status IN ('submitted', 'partially_received')
  ),
  floor_inv AS (
    SELECT
      COALESCE(SUM(inv.quantity_available * COALESCE(p.current_cost, 0)), 0) AS total_value,
      COALESCE(SUM(
        GREATEST(inv.quantity_available - inv.quantity_prebooked, 0) * COALESCE(p.current_cost, 0)
      ), 0) AS free_value
    FROM public.inventory inv
    JOIN public.products p ON p.id = inv.product_id
    WHERE inv.quantity_available > 0
  ),
  committed_orders AS (
    SELECT COALESCE(SUM(oi.quantity_remaining * oi.cost_per_unit), 0) AS value
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    WHERE o.status IN ('confirmed', 'partially_fulfilled')
      AND o.deleted_at IS NULL
      AND oi.quantity_remaining > 0
  ),
  bottom_products AS (
    SELECT jsonb_agg(row_to_json(bp)::jsonb ORDER BY bp.margin_pct ASC) AS arr
    FROM (
      SELECT
        p.product_name,
        COALESCE(SUM(oi.total_units_needed * oi.price_per_unit), 0) AS total_revenue,
        COALESCE(SUM(oi.total_units_needed * oi.cost_per_unit), 0) AS total_cost,
        ROUND(
          CASE
            WHEN SUM(oi.total_units_needed * oi.price_per_unit) > 0 THEN
              ((SUM(oi.total_units_needed * oi.price_per_unit) -
                SUM(oi.total_units_needed * oi.cost_per_unit)) /
                NULLIF(SUM(oi.total_units_needed * oi.price_per_unit), 0)) * 100
            ELSE 0
          END,
          1
        ) AS margin_pct,
        COALESCE(SUM(oi.total_units_needed), 0) AS units_sold
      FROM public.order_items oi
      JOIN public.orders o ON o.id = oi.order_id
      JOIN public.products p ON p.id = oi.product_id
      WHERE o.deleted_at IS NULL
        AND o.status NOT IN ('cancelled', 'voided', 'draft')
        AND public.compute_season(COALESCE(o.order_date, o.created_at::date)) =
            public.compute_season(CURRENT_DATE)
      GROUP BY p.id, p.product_name
      HAVING SUM(oi.total_units_needed * oi.price_per_unit) > 0
      ORDER BY margin_pct ASC
      LIMIT 10
    ) bp
  ),
  bottom_customers AS (
    SELECT jsonb_agg(row_to_json(bc)::jsonb ORDER BY bc.margin_pct ASC) AS arr
    FROM (
      SELECT
        c.farm_name,
        COALESCE(SUM(o.total_price), 0) AS total_revenue,
        COALESCE(SUM(o.total_cost), 0) AS total_cost,
        ROUND(
          CASE
            WHEN SUM(o.total_price) > 0 THEN
              ((SUM(o.total_price) - SUM(o.total_cost)) /
                NULLIF(SUM(o.total_price), 0)) * 100
            ELSE 0
          END,
          1
        ) AS margin_pct,
        COUNT(*)::int AS order_count
      FROM public.orders o
      JOIN public.customers c ON c.id = o.customer_id
      WHERE o.deleted_at IS NULL
        AND o.status NOT IN ('cancelled', 'voided', 'draft')
        AND public.compute_season(COALESCE(o.order_date, o.created_at::date)) =
            public.compute_season(CURRENT_DATE)
      GROUP BY c.id, c.farm_name
      HAVING SUM(o.total_price) > 0
      ORDER BY margin_pct ASC
      LIMIT 10
    ) bc
  ),
  monthly_margin AS (
    SELECT jsonb_agg(row_to_json(mm)::jsonb ORDER BY mm.month) AS arr
    FROM (
      SELECT
        TO_CHAR(COALESCE(order_date, created_at::date), 'YYYY-MM') AS month,
        COALESCE(SUM(total_price), 0) AS revenue,
        COALESCE(SUM(total_cost), 0) AS cost,
        ROUND(
          CASE
            WHEN SUM(total_price) > 0 THEN
              ((SUM(total_price) - SUM(total_cost)) /
                NULLIF(SUM(total_price), 0)) * 100
            ELSE 0
          END,
          1
        ) AS margin_pct
      FROM public.orders
      WHERE deleted_at IS NULL
        AND status NOT IN ('cancelled', 'voided', 'draft')
      GROUP BY 1
      ORDER BY 1 DESC
      LIMIT 12
    ) mm
  )
  SELECT jsonb_build_object(
    'total_revenue', oa.total_revenue,
    'total_profit', oa.total_profit,
    'overall_margin', CASE
      WHEN oa.total_revenue > 0 THEN ROUND((oa.total_profit / oa.total_revenue) * 100, 1)
      ELSE 0
    END,
    'quote_counts', jsonb_build_object(
      'draft', qa.draft_count,
      'sent', qa.sent_count,
      'accepted', qa.accepted_count
    ),
    'quote_pipeline_value', qa.pipeline_value,
    'monthly_revenue', COALESCE(mr.arr, '[]'::jsonb),
    'top_customers', COALESCE(tc.arr, '[]'::jsonb),
    'open_ar_balance', ar_total.balance,
    'customers_over_credit_count', oc.cnt,
    'ar_aging_buckets', jsonb_build_object(
      'current', aa.current_bucket,
      'days_31_60', aa.days_31_60,
      'days_61_90', aa.days_61_90,
      'days_90_plus', aa.days_90_plus
    ),
    'total_prepay_unallocated', pb.total_unallocated,
    'total_commission_owed', co.total_owed,
    'current_period', jsonb_build_object(
      'name', COALESCE(pi.name, TO_CHAR(NOW(), 'Mon YYYY')),
      'status', COALESCE(pi.status, 'open'),
      'days_remaining', COALESCE(pi.days_remaining, 0)
    ),
    'po_unreceived_value', pour.value,
    'floor_inventory_value', fi.total_value,
    'floor_free_value', fi.free_value,
    'committed_order_value', co2.value,
    'bottom_products_by_margin', COALESCE(bpm.arr, '[]'::jsonb),
    'bottom_customers_by_margin', COALESCE(bcm.arr, '[]'::jsonb),
    'monthly_margin_trend', COALESCE(mmt.arr, '[]'::jsonb)
  ) INTO result
  FROM order_agg oa
  CROSS JOIN quote_agg qa
  CROSS JOIN monthly mr
  CROSS JOIN top_cust tc
  CROSS JOIN ar ar_total
  CROSS JOIN over_credit oc
  CROSS JOIN ar_aging aa
  CROSS JOIN prepay_bal pb
  CROSS JOIN commission_owed co
  CROSS JOIN po_unreceived pour
  CROSS JOIN floor_inv fi
  CROSS JOIN committed_orders co2
  CROSS JOIN bottom_products bpm
  CROSS JOIN bottom_customers bcm
  CROSS JOIN monthly_margin mmt
  LEFT JOIN period_info pi ON true;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."financial_dashboard_summary"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."financial_dashboard_summary"() IS 'Returns all financial KPIs for the Financial Dashboard: revenue, profit, margin, quote pipeline, AR aging buckets, prepay balances, commission owed, period status, inventory position (PO unreceived, floor value, committed orders), and margin alerts (bottom products/customers by margin, monthly margin trend).';



CREATE OR REPLACE FUNCTION "public"."find_overlapping_fields"("p_boundary_geojson" "text", "p_customer_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_geom   geometry;
  v_mpoly  geometry(MultiPolygon,4326);
  v_area   double precision;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  PERFORM require_admin_or_sales_rep();

  v_geom := ST_GeomFromGeoJSON(p_boundary_geojson);
  v_geom := ST_Force2D(v_geom);
  v_geom := ST_SetSRID(v_geom, 4326);
  IF NOT ST_IsValid(v_geom) THEN v_geom := ST_MakeValid(v_geom); END IF;
  v_geom := ST_UnaryUnion(ST_CollectionExtract(v_geom, 3));
  v_mpoly := ST_Multi(v_geom);
  IF v_mpoly IS NULL OR ST_IsEmpty(v_mpoly) OR GeometryType(v_mpoly) <> 'MULTIPOLYGON' THEN
    RAISE EXCEPTION 'INVALID_GEOMETRY: boundary did not resolve to a polygon';
  END IF;
  v_area := ST_Area(v_mpoly::geography);

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.overlap_pct DESC), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT f.id AS field_id,
           f.field_name,
           f.customer_id,
           f.measured_acres,
           round((ST_Area(ST_Intersection(f.boundary_geom, v_mpoly)::geography)
                  / NULLIF(LEAST(ST_Area(f.boundary_geom::geography), v_area), 0) * 100)::numeric, 1) AS overlap_pct
    FROM fields f
    WHERE f.boundary_geom IS NOT NULL
      AND f.is_active
      AND (p_customer_id IS NULL OR f.customer_id = p_customer_id)
      AND f.boundary_geom && v_mpoly                                  -- GIST bbox prefilter
      AND ST_Intersects(f.boundary_geom, v_mpoly)
      AND ST_Area(ST_Intersection(f.boundary_geom, v_mpoly)::geography)
          / NULLIF(LEAST(ST_Area(f.boundary_geom::geography), v_area), 0) > 0.8
  ) t;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."find_overlapping_fields"("p_boundary_geojson" "text", "p_customer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_batch_statements"("p_as_of_date" "date", "p_performed_by" "uuid", "p_mode" "text" DEFAULT 'summary'::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customers jsonb := '[]'::jsonb;
  v_cust RECORD;
  v_stmt jsonb;
BEGIN
  FOR v_cust IN
    SELECT DISTINCT c.id, c.farm_name
    FROM customers c
    INNER JOIN invoices i
      ON i.customer_id = c.id
      AND i.status = 'posted'
      AND i.balance_cents > 0
      AND i.deleted_at IS NULL
      AND i.invoice_date <= p_as_of_date
    WHERE c.is_active = true
    ORDER BY c.farm_name
  LOOP
    v_stmt := get_detailed_statement_data(v_cust.id, p_as_of_date, p_mode);
    v_customers := v_customers || v_stmt;
  END LOOP;

  RETURN v_customers;
END;
$$;


ALTER FUNCTION "public"."generate_batch_statements"("p_as_of_date" "date", "p_performed_by" "uuid", "p_mode" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_finance_charges"("p_as_of_date" "date", "p_performed_by" "uuid", "p_customer_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid;
  v_customer record;
  v_charge_amount bigint;
  v_invoice_id uuid;
  v_inv_num text;
  v_charges jsonb := '[]'::jsonb;
  v_count integer := 0;
  v_skipped integer := 0;
  v_min_balance bigint;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT is_admin() THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_as_of_date IS NULL THEN
    RAISE EXCEPTION 'FINANCE_CHARGE_DATE_REQUIRED';
  END IF;
  IF p_as_of_date > (now() AT TIME ZONE 'America/Chicago')::date THEN
    RAISE EXCEPTION 'FUTURE_FINANCE_CHARGE_DATE: finance charges cannot be generated for a future business date';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'generate_finance_charges');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  -- H2 fix: key the serialization lock on the MONTH, not the exact as-of date,
  -- so two concurrent runs in the same month (different as-of dates) serialize
  -- and the second sees the first's committed charge — matching the month-level
  -- dedup below. (Keying on the date let them take different locks and both pass
  -- the EXISTS check before either inserted — the double-charge this fixes.)
  PERFORM pg_advisory_xact_lock(hashtext('generate_finance_charges:' || to_char(p_as_of_date, 'YYYY-MM')));
  PERFORM public.check_period_open(p_as_of_date);

  SELECT COALESCE(s.setting_value::bigint, 500)
    INTO v_min_balance
    FROM public.app_settings s
   WHERE s.setting_key = 'finance_charge_min_balance_cents';

  IF v_min_balance IS NULL THEN
    v_min_balance := 500;
  END IF;

  FOR v_customer IN
    SELECT c.id AS customer_id, c.farm_name, c.finance_charge_rate,
           COALESCE(c.finance_charge_grace_days, 0) AS grace_days,
           COALESCE(sum(i.balance_cents), 0) AS overdue_balance
      FROM public.customers c
      INNER JOIN public.invoices i
        ON i.customer_id = c.id
        AND i.status IN ('posted', 'overdue')
        AND i.balance_cents > 0
        AND i.deleted_at IS NULL
        AND i.invoice_type != 'misc_charge'
        AND i.due_date IS NOT NULL
        AND i.due_date < (p_as_of_date - (COALESCE(c.finance_charge_grace_days, 0) || ' days')::interval)
      WHERE c.finance_charge_rate > 0
        AND c.is_active = true
        AND COALESCE(c.finance_charge_enabled, true) = true
        AND (p_customer_ids IS NULL OR c.id = ANY(p_customer_ids))
      GROUP BY c.id, c.farm_name, c.finance_charge_rate, c.finance_charge_grace_days
      HAVING sum(i.balance_cents) >= v_min_balance
  LOOP
    -- H2 fix: dedup on the CALENDAR MONTH, not the exact as-of date. Two runs
    -- in the same month (different as-of dates) must not both charge the same
    -- overdue balance; a genuinely new month still charges.
    IF EXISTS (
      SELECT 1 FROM public.finance_charges
      WHERE customer_id = v_customer.customer_id
        AND date_trunc('month', period_end) = date_trunc('month', p_as_of_date)
    ) THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    v_charge_amount := ROUND(v_customer.overdue_balance * (v_customer.finance_charge_rate / 100.0 / 12.0));

    IF v_charge_amount > 0 THEN
      v_inv_num := next_invoice_number('misc_charge');

      INSERT INTO public.invoices (
        invoice_number, customer_id, invoice_type, status, invoice_date, due_date,
        total_amount_cents, total_cost_cents,
        header_notes, season, created_by
      ) VALUES (
        -- OVERNIGHT FIX (finding #1): insert as 'draft' — the BEFORE INSERT trigger
        -- rejects any non-draft, non-credit_memo insert. Flipped to 'unposted' below
        -- once the item / finance_charges / audit rows are built. Live literal was 'unposted'.
        v_inv_num, v_customer.customer_id, 'misc_charge', 'draft', p_as_of_date,
        (p_as_of_date + interval '30 days')::date,
        v_charge_amount, 0,
        'Finance charge: ' || v_customer.finance_charge_rate || '% annual on overdue balance of $' ||
        to_char(v_customer.overdue_balance / 100.0, 'FM999,999,990.00') ||
        CASE WHEN v_customer.grace_days > 0
             THEN ' (after ' || v_customer.grace_days || ' day grace period)'
             ELSE '' END,
        CASE WHEN extract(month FROM p_as_of_date) >= 10
             THEN extract(year FROM p_as_of_date)::integer + 1
             ELSE extract(year FROM p_as_of_date)::integer END,
        v_actor
      ) RETURNING id INTO v_invoice_id;

      INSERT INTO public.invoice_items (
        invoice_id, description, quantity, unit_price_cents, extended_cents,
        cost_cents, is_application_fee, sort_order
      ) VALUES (
        v_invoice_id,
        'Finance Charge - ' || v_customer.finance_charge_rate || '% annual rate on overdue balance',
        1, v_charge_amount, v_charge_amount,
        0, false, 1
      );

      INSERT INTO public.finance_charges (
        customer_id, invoice_id, amount_cents, charge_rate,
        base_amount_cents, period_start, period_end, created_by
      ) VALUES (
        v_customer.customer_id, v_invoice_id, v_charge_amount,
        v_customer.finance_charge_rate, v_customer.overdue_balance,
        (p_as_of_date - interval '30 days')::date, p_as_of_date,
        v_actor
      );

      INSERT INTO public.financial_audit_log (
        operation_type,
        entity_type,
        entity_id,
        actor_user_id, total_impact_cents, description
      ) VALUES (
        'finance_charge', 'invoice', v_invoice_id,
        v_actor, v_charge_amount,
        'Finance charge generated for ' || v_customer.farm_name ||
        ': $' || to_char(v_charge_amount / 100.0, 'FM999,999,990.00') ||
        ' at ' || v_customer.finance_charge_rate || '% on $' ||
        to_char(v_customer.overdue_balance / 100.0, 'FM999,999,990.00') || ' overdue'
      );

      -- OVERNIGHT FIX (finding #1): now that the invoice and its child rows are fully
      -- built, flip draft -> unposted (the original intended end state). Allowed by
      -- _enforce_invoice_status_transition (draft -> unposted).
      UPDATE public.invoices SET status = 'unposted' WHERE id = v_invoice_id;

      v_count := v_count + 1;
      v_charges := v_charges || jsonb_build_object(
        'customer', v_customer.farm_name,
        'base_balance_cents', v_customer.overdue_balance,
        'charge_cents', v_charge_amount,
        'rate', v_customer.finance_charge_rate,
        'invoice_number', v_inv_num,
        'grace_days', v_customer.grace_days
      );
    END IF;
  END LOOP;

  v_result := jsonb_build_object(
    'charges_generated', v_count,
    'skipped_already_charged', v_skipped,
    'details', v_charges
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'generate_finance_charges', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."generate_finance_charges"("p_as_of_date" "date", "p_performed_by" "uuid", "p_customer_ids" "uuid"[], "p_idempotency_key" "text") OWNER TO "postgres";


