CREATE OR REPLACE FUNCTION "public"."generate_rup_sales_records"("p_invoice_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count integer := 0;
  v_invoice record;
  v_item record;
  v_license record;
  v_compliance_status text;
  v_compliance_notes text;
  v_season integer;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  -- N2-4 role gate (matches the sole caller post_invoice): block applicators/drivers.
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Not authorized to generate RUP sales records';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'generate_rup_sales_records');
    IF v_existing IS NOT NULL THEN
      RETURN (v_existing->>'count')::integer;
    END IF;
  END IF;

  SELECT i.id, i.order_id, o.customer_id, c.farm_name, i.created_at
  INTO v_invoice
  FROM invoices i
  JOIN orders o ON o.id = i.order_id
  JOIN customers c ON c.id = o.customer_id
  WHERE i.id = p_invoice_id;

  IF v_invoice IS NULL THEN RETURN 0; END IF;

  v_season := CASE
    WHEN EXTRACT(MONTH FROM v_invoice.created_at) >= 10
    THEN EXTRACT(YEAR FROM v_invoice.created_at)::integer + 1
    ELSE EXTRACT(YEAR FROM v_invoice.created_at)::integer
  END;

  FOR v_item IN
    SELECT ii.id, ii.product_id, p.product_name, ii.quantity, ii.unit_size,
           ii.unit_price_cents, ii.extended_cents,
           p.epa_registration, p.signal_word
    FROM invoice_items ii
    JOIN products p ON p.id = ii.product_id
    WHERE ii.invoice_id = p_invoice_id
      AND p.is_rup = true
  LOOP
    SELECT al.license_number, al.license_type, al.expiry_date
    INTO v_license
    FROM applicator_licenses al
    WHERE al.customer_id = v_invoice.customer_id
      AND al.is_active = true
    ORDER BY al.expiry_date DESC NULLS LAST
    LIMIT 1;

    IF v_license IS NULL OR v_license.license_number IS NULL THEN
      v_compliance_status := 'non_compliant';
      v_compliance_notes := 'No applicator license on file for this customer';
    ELSIF v_license.expiry_date IS NOT NULL AND v_license.expiry_date < CURRENT_DATE THEN
      v_compliance_status := 'warning';
      v_compliance_notes := 'Applicator license expired on ' || v_license.expiry_date::text;
    ELSE
      v_compliance_status := 'compliant';
      v_compliance_notes := NULL;
    END IF;

    -- PARKED-006: dedup ignores voided rows so a legitimate re-post can record
    -- a fresh active sale even when a prior voided row exists.
    IF NOT EXISTS (
      SELECT 1 FROM rup_sales_records
      WHERE invoice_id = p_invoice_id
        AND product_id = v_item.product_id
        AND voided_at IS NULL
    ) THEN
      INSERT INTO rup_sales_records (
        invoice_id, order_id, customer_id, product_id,
        sale_date, product_name, epa_registration, quantity, unit,
        unit_price_cents, total_cents,
        buyer_name, buyer_certification_number,
        buyer_certification_type, buyer_certification_expiry,
        signal_word, compliance_status, compliance_notes,
        season, created_by
      ) VALUES (
        p_invoice_id, v_invoice.order_id, v_invoice.customer_id, v_item.product_id,
        CURRENT_DATE, v_item.product_name, v_item.epa_registration, v_item.quantity, v_item.unit_size,
        v_item.unit_price_cents, v_item.extended_cents,
        v_invoice.farm_name,
        v_license.license_number,
        v_license.license_type,
        v_license.expiry_date,
        v_item.signal_word, v_compliance_status, v_compliance_notes,
        v_season, auth.uid()
      );
      v_count := v_count + 1;
    END IF;
  END LOOP;

  v_result := jsonb_build_object('count', v_count);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'generate_rup_sales_records', v_result);
  END IF;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."generate_rup_sales_records"("p_invoice_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_ticket_number"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_year text := extract(year FROM current_date)::text;
  v_max int;
BEGIN
  SELECT COALESCE(MAX(
    CASE WHEN ticket_number ~ ('^BT-' || v_year || '-\d+$')
    THEN CAST(split_part(ticket_number, '-', 3) AS int)
    ELSE 0 END
  ), 0) INTO v_max FROM blend_tickets;
  RETURN 'BT-' || v_year || '-' || lpad((v_max + 1)::text, 4, '0');
END;
$_$;


ALTER FUNCTION "public"."generate_ticket_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ap_aging"("p_as_of_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("vendor_id" "uuid", "vendor_name" "text", "current_amount" bigint, "days_31_60" bigint, "days_61_90" bigint, "over_90" bigint, "total_outstanding" bigint, "bill_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM require_admin();
  RETURN QUERY
  SELECT v.id AS vendor_id, v.name AS vendor_name,
    COALESCE(SUM(CASE WHEN (p_as_of_date - vb.bill_date) <= 30 THEN vb.balance_cents ELSE 0 END), 0)::bigint AS current_amount,
    COALESCE(SUM(CASE WHEN (p_as_of_date - vb.bill_date) BETWEEN 31 AND 60 THEN vb.balance_cents ELSE 0 END), 0)::bigint AS days_31_60,
    COALESCE(SUM(CASE WHEN (p_as_of_date - vb.bill_date) BETWEEN 61 AND 90 THEN vb.balance_cents ELSE 0 END), 0)::bigint AS days_61_90,
    COALESCE(SUM(CASE WHEN (p_as_of_date - vb.bill_date) > 90 THEN vb.balance_cents ELSE 0 END), 0)::bigint AS over_90,
    COALESCE(SUM(vb.balance_cents), 0)::bigint AS total_outstanding,
    COUNT(vb.id)::integer AS bill_count
  FROM vendors v
  LEFT JOIN vendor_bills vb ON vb.vendor_id = v.id
    AND vb.status IN ('unpaid', 'partially_paid')
    AND vb.deleted_at IS NULL
  WHERE v.deleted_at IS NULL
  GROUP BY v.id, v.name
  HAVING COALESCE(SUM(vb.balance_cents), 0) > 0
  ORDER BY COALESCE(SUM(vb.balance_cents), 0) DESC;
END;
$$;


ALTER FUNCTION "public"."get_ap_aging"("p_as_of_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ap_dashboard_summary"("p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM require_admin();
  SELECT jsonb_build_object(
    'total_owed_cents', COALESCE(SUM(CASE WHEN status IN ('unpaid', 'partially_paid') THEN balance_cents ELSE 0 END), 0),
    'overdue_cents', COALESCE(SUM(CASE WHEN status IN ('unpaid', 'partially_paid') AND due_date < CURRENT_DATE THEN balance_cents ELSE 0 END), 0),
    'overdue_count', COUNT(CASE WHEN status IN ('unpaid', 'partially_paid') AND due_date < CURRENT_DATE THEN 1 END),
    'due_this_week_cents', COALESCE(SUM(CASE WHEN status IN ('unpaid', 'partially_paid') AND due_date BETWEEN CURRENT_DATE AND CURRENT_DATE + 7 THEN balance_cents ELSE 0 END), 0),
    'due_this_week_count', COUNT(CASE WHEN status IN ('unpaid', 'partially_paid') AND due_date BETWEEN CURRENT_DATE AND CURRENT_DATE + 7 THEN 1 END),
    'due_this_month_cents', COALESCE(SUM(CASE WHEN status IN ('unpaid', 'partially_paid') AND due_date BETWEEN CURRENT_DATE AND CURRENT_DATE + 30 THEN balance_cents ELSE 0 END), 0),
    'total_bills', COUNT(*),
    'unpaid_count', COUNT(CASE WHEN status IN ('unpaid', 'partially_paid') THEN 1 END),
    'paid_this_month_cents', COALESCE((
      SELECT SUM(vp.amount_cents)
      FROM vendor_payments vp
      JOIN vendor_bills vb2 ON vb2.id = vp.vendor_bill_id
      WHERE vp.payment_date >= date_trunc('month', CURRENT_DATE)
        AND vp.voided_at IS NULL
    ), 0)
  )
  INTO v_result
  FROM vendor_bills
  WHERE deleted_at IS NULL AND status <> 'voided';

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_ap_dashboard_summary"("p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ar_aging"("p_as_of_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("customer_id" "uuid", "farm_name" "text", "current_amount" numeric, "days_30" numeric, "days_60" numeric, "days_90" numeric, "over_90" numeric, "total_outstanding" numeric, "prepay_balance_cents" bigint, "open_credit_cents" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_active = true AND role = 'admin') THEN
    RAISE EXCEPTION 'Admin access required for AR aging report';
  END IF;
  RETURN QUERY
  SELECT c.id AS customer_id, c.farm_name,
    COALESCE(SUM(CASE WHEN age_days <= 29 THEN balance END), 0) AS current_amount,
    COALESCE(SUM(CASE WHEN age_days BETWEEN 30 AND 59 THEN balance END), 0) AS days_30,
    COALESCE(SUM(CASE WHEN age_days BETWEEN 60 AND 89 THEN balance END), 0) AS days_60,
    COALESCE(SUM(CASE WHEN age_days BETWEEN 90 AND 119 THEN balance END), 0) AS days_90,
    COALESCE(SUM(CASE WHEN age_days >= 120 THEN balance END), 0) AS over_90,
    COALESCE(SUM(balance), 0) AS total_outstanding,
    c.prepay_balance_cents,
    COALESCE(cm.credit_cents, 0)::bigint AS open_credit_cents
  FROM customers c
  INNER JOIN (
    SELECT i.customer_id, (i.balance_cents::numeric / 100) AS balance, (p_as_of_date - COALESCE(i.due_date, i.invoice_date)::date) AS age_days
    FROM invoices i WHERE i.status IN ('posted', 'overdue') AND i.balance_cents > 0 AND i.deleted_at IS NULL
  ) ar ON ar.customer_id = c.id
  LEFT JOIN (
    SELECT ci.customer_id, -SUM(ci.balance_cents) AS credit_cents
    FROM invoices ci
    WHERE ci.invoice_type = 'credit_memo' AND ci.status = 'posted'
      AND ci.balance_cents < 0 AND ci.deleted_at IS NULL
    GROUP BY ci.customer_id
  ) cm ON cm.customer_id = c.id
  GROUP BY c.id, c.farm_name, c.prepay_balance_cents, cm.credit_cents
  HAVING SUM(balance) > 0 ORDER BY SUM(balance) DESC;
END;
$$;


ALTER FUNCTION "public"."get_ar_aging"("p_as_of_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ar_reminder_candidates"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  _role  text;
  v_setting_raw text;
  v_num numeric;
  v_threshold int;
BEGIN
  _role := COALESCE(
    current_setting('request.jwt.claims', true)::jsonb ->> 'user_role',
    (SELECT role FROM public.profiles WHERE id = auth.uid())
  );
  IF _role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'permission denied: admin role required';
  END IF;

  -- Configurable threshold (Settings > app_settings.ar_reminder_days). Robust: take the LEADING
  -- integer part (so '30', '30.0', ' 45 ' all read as 30/30/45 — NOT digit-stripping, which would
  -- turn '30.0'->300 or '1e2'->12), default 30 on blank/garbage/missing, clamp 1..3650 so a bad
  -- value can never break the report.
  SELECT setting_value INTO v_setting_raw FROM app_settings WHERE setting_key = 'ar_reminder_days';
  v_num := (regexp_match(COALESCE(v_setting_raw, ''), '^\s*(\d+)'))[1]::numeric;
  v_threshold := CASE WHEN v_num IS NULL THEN 30 ELSE LEAST(GREATEST(v_num, 1), 3650)::int END;

  SELECT COALESCE(jsonb_agg(row_to_json(cust_agg)::jsonb), '[]'::jsonb)
  INTO result
  FROM (
    SELECT
      c.id AS customer_id,
      c.farm_name,
      c.email,
      c.prepay_balance_cents,
      (SELECT COALESCE(-SUM(ci.balance_cents), 0)::bigint
         FROM invoices ci
        WHERE ci.customer_id = c.id
          AND ci.invoice_type = 'credit_memo'
          AND ci.status = 'posted'
          AND ci.balance_cents < 0
          AND ci.deleted_at IS NULL) AS open_credit_cents,
      MAX(EXTRACT(DAY FROM NOW() - COALESCE(i.due_date, i.invoice_date))::int) AS max_days_past_due,
      COALESCE(SUM(GREATEST(i.balance_cents, 0)), 0) / 100.0 AS total_balance,
      jsonb_agg(jsonb_build_object(
        'invoice_id', i.id,
        'invoice_number', i.invoice_number,
        'invoice_date', i.invoice_date,
        'balance_cents', i.balance_cents,
        'days_past_due', EXTRACT(DAY FROM NOW() - COALESCE(i.due_date, i.invoice_date))::int
      ) ORDER BY i.invoice_date) AS invoices
    FROM invoices i
    JOIN customers c ON c.id = i.customer_id
    WHERE i.status IN ('posted', 'overdue')
      AND i.balance_cents > 0
      AND EXTRACT(DAY FROM NOW() - COALESCE(i.due_date, i.invoice_date))::int > v_threshold
      AND c.email IS NOT NULL
      AND c.email <> ''
    GROUP BY c.id, c.farm_name, c.email, c.prepay_balance_cents
    ORDER BY max_days_past_due DESC
  ) cust_agg;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_ar_reminder_candidates"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ar_reminder_candidates"() IS 'Returns customers with overdue invoices (30+ days) grouped by customer, with invoice details, total balance, and max days past due. Only includes customers with email addresses on file.';



CREATE OR REPLACE FUNCTION "public"."get_batch_year_end_summaries"("p_customer_ids" "uuid"[], "p_season" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_results jsonb := '[]'::jsonb;
  v_cid     uuid;
  v_summary jsonb;
BEGIN
  FOREACH v_cid IN ARRAY p_customer_ids LOOP
    SELECT public.get_customer_year_end_summary(v_cid, p_season) INTO v_summary;
    IF v_summary IS NOT NULL THEN
      v_results := v_results || jsonb_build_array(v_summary);
    END IF;
  END LOOP;
  RETURN v_results;
END;
$$;


ALTER FUNCTION "public"."get_batch_year_end_summaries"("p_customer_ids" "uuid"[], "p_season" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_batch_year_end_summaries"("p_customer_ids" "uuid"[], "p_season" integer) IS 'Batch wrapper around get_customer_year_end_summary — one RPC call for N customers';



CREATE OR REPLACE FUNCTION "public"."get_booking_settlement"("p_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_role text;
  v_active boolean;
  v_quote record;
  v_lines jsonb;
  v_booked_cents bigint;
  v_drawn_cents bigint;
  v_remaining_cents bigint;
  v_prepay_earmarked_cents bigint;
  v_prepay_remaining_cents bigint;
  v_prepay_applied_cents bigint;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  SELECT role, is_active INTO v_role, v_active FROM profiles WHERE id = v_actor;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'sales_rep') OR v_active IS NOT TRUE THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  SELECT q.id, q.quote_number, q.customer_id, q.status, q.season, q.is_planned, q.deleted_at
    INTO v_quote
    FROM quotes q
    WHERE q.id = p_quote_id;

  IF NOT FOUND OR v_quote.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'found', false, 'quote_id', p_quote_id);
  END IF;

  WITH booked AS (
    SELECT qi.product_id,
           SUM(COALESCE(qi.total_units_needed, 0)) AS booked_qty,
           CASE WHEN SUM(COALESCE(qi.total_units_needed, 0)) > 0
                THEN SUM(qi.price_per_unit * COALESCE(qi.total_units_needed, 0))
                     / SUM(COALESCE(qi.total_units_needed, 0))
                ELSE 0 END AS wavg_price
      FROM quote_items qi
      WHERE qi.quote_id = p_quote_id
      GROUP BY qi.product_id
  ),
  drawn AS (
    SELECT d.product_id, d.quantity_drawn
      FROM quote_product_draws d
      WHERE d.quote_id = p_quote_id
  ),
  -- LAYER2<<< job draws consuming each booking line (§6.5)
  job_drawn AS (
    SELECT jd.product_id, SUM(jd.quantity_drawn) AS qty
      FROM job_product_draws jd
      WHERE jd.quote_id = p_quote_id
      GROUP BY jd.product_id
  ),
  -- >>>LAYER2
  locked AS (
    SELECT dle.product_id,
           CASE WHEN SUM(dle.eff_qty) > 0
                THEN SUM(dle.unit_price * dle.eff_qty) / SUM(dle.eff_qty)
                ELSE NULL END AS locked_price
      FROM (
        SELECT oi.product_id,
               oi.total_price / NULLIF(oi.total_units_needed, 0) AS unit_price,
               CASE WHEN o.status = 'voided'    THEN 0
                    WHEN o.status = 'cancelled' THEN COALESCE(oi.quantity_delivered, 0)
                    ELSE COALESCE(oi.total_units_needed, 0) END AS eff_qty
          FROM orders o
          JOIN order_items oi ON oi.order_id = o.id
          WHERE o.quote_id = p_quote_id AND o.booking_draw = true
      ) dle
      GROUP BY dle.product_id
  ),
  line_rows AS (
    SELECT b.product_id,
           p.product_name,
           b.booked_qty,
           -- LAYER2<<< "drawn" folds ORDER + JOB draws so booked = drawn + remaining
           -- reconciles in the existing settlement card (Codex round-3 P2); remaining
           -- subtracts both (§6.5): booked − order − job. Order draws keep their locked
           -- price; a job draw has no locked order price, valued at current wavg.
           (COALESCE(d.quantity_drawn, 0) + COALESCE(jd.qty, 0)) AS drawn_qty,
           GREATEST(b.booked_qty - COALESCE(d.quantity_drawn, 0) - COALESCE(jd.qty, 0), 0) AS remaining_qty,
           COALESCE(l.locked_price, b.wavg_price) AS locked_price,
           b.wavg_price AS current_price,
           ROUND((COALESCE(d.quantity_drawn, 0) * COALESCE(l.locked_price, b.wavg_price)
                  + COALESCE(jd.qty, 0) * b.wavg_price) * 100)::bigint AS drawn_cents,
           ROUND(GREATEST(b.booked_qty - COALESCE(d.quantity_drawn, 0) - COALESCE(jd.qty, 0), 0) * b.wavg_price * 100)::bigint AS remaining_cents
           -- >>>LAYER2
      FROM booked b
      LEFT JOIN drawn d ON d.product_id = b.product_id
      LEFT JOIN job_drawn jd ON jd.product_id = b.product_id
      LEFT JOIN locked l ON l.product_id = b.product_id
      LEFT JOIN products p ON p.id = b.product_id
  )
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'product_id', product_id,
      'product_name', product_name,
      'booked_qty', booked_qty,
      'drawn_qty', drawn_qty,               -- LAYER2: folds order + job draws
      'remaining_qty', remaining_qty,
      'locked_price', locked_price,
      'current_price', current_price,
      'booked_cents', drawn_cents + remaining_cents,
      'drawn_cents', drawn_cents,
      'remaining_cents', remaining_cents
    ) ORDER BY product_name), '[]'::jsonb),
    COALESCE(SUM(drawn_cents + remaining_cents), 0),
    COALESCE(SUM(drawn_cents), 0),
    COALESCE(SUM(remaining_cents), 0)
  INTO v_lines, v_booked_cents, v_drawn_cents, v_remaining_cents
  FROM line_rows;

  SELECT COALESCE(SUM(pc.balance_cents), 0)
    INTO v_prepay_remaining_cents
    FROM prepay_credits pc
    WHERE pc.quote_id = p_quote_id;
  SELECT COALESCE(SUM(pa.applied_amount_cents), 0)
    INTO v_prepay_applied_cents
    FROM prepay_applications pa
    JOIN prepay_credits pc ON pc.id = pa.prepay_credit_id
    WHERE pc.quote_id = p_quote_id;
  v_prepay_earmarked_cents := v_prepay_applied_cents + v_prepay_remaining_cents;

  RETURN jsonb_build_object(
    'success', true,
    'found', true,
    'quote_id', v_quote.id,
    'quote_number', v_quote.quote_number,
    'customer_id', v_quote.customer_id,
    'status', v_quote.status,
    'season', v_quote.season,
    'is_planned', v_quote.is_planned,
    'lines', v_lines,
    'booked_cents', v_booked_cents,
    'drawn_cents', v_drawn_cents,   -- LAYER2: folds order + job draws
    'remaining_cents', v_remaining_cents,
    'prepay_earmarked_cents', v_prepay_earmarked_cents,
    'prepay_applied_cents', v_prepay_applied_cents,
    'prepay_remaining_cents', v_prepay_remaining_cents
  );
END;
$$;


ALTER FUNCTION "public"."get_booking_settlement"("p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bottom_line_pnl"("p_start_date" "date", "p_end_date" "date") RETURNS TABLE("line_item" "text", "amount" numeric, "pct_of_revenue" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_revenue numeric := 0;
  v_cogs numeric := 0;
  v_gross_profit numeric := 0;
  v_commissions numeric := 0;
  v_net_profit numeric := 0;
BEGIN
  SELECT
    COALESCE(SUM(i.total_amount_cents), 0) / 100.0,
    COALESCE(SUM(
      (SELECT COALESCE(SUM(ii.cost_cents * ii.quantity), 0) FROM public.invoice_items ii WHERE ii.invoice_id = i.id)
    ), 0) / 100.0
  INTO v_revenue, v_cogs
  FROM public.invoices i
  WHERE i.status = 'posted'
    AND i.invoice_date >= p_start_date
    AND i.invoice_date <= p_end_date
    AND i.deleted_at IS NULL;

  v_gross_profit := v_revenue - v_cogs;

  SELECT COALESCE(SUM(commission_amount), 0)
  INTO v_commissions
  FROM public.commissions
  WHERE order_date >= p_start_date
    AND order_date <= p_end_date;

  v_net_profit := v_gross_profit - v_commissions;

  RETURN QUERY VALUES
    ('Revenue'::text, v_revenue, 100.0::numeric),
    ('Cost of Goods Sold', v_cogs, CASE WHEN v_revenue > 0 THEN ROUND(v_cogs / v_revenue * 100, 1) ELSE 0 END),
    ('Gross Profit', v_gross_profit, CASE WHEN v_revenue > 0 THEN ROUND(v_gross_profit / v_revenue * 100, 1) ELSE 0 END),
    ('Commissions', v_commissions, CASE WHEN v_revenue > 0 THEN ROUND(v_commissions / v_revenue * 100, 1) ELSE 0 END),
    ('Net Profit', v_net_profit, CASE WHEN v_revenue > 0 THEN ROUND(v_net_profit / v_revenue * 100, 1) ELSE 0 END);
END;
$$;


ALTER FUNCTION "public"."get_bottom_line_pnl"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_call_list_lapsed_products"("p_rep_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_season integer := public.current_season();
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.is_active
      AND (public.is_admin() OR public.is_sales_rep())
  ) OR (
    public.is_sales_rep()
    AND p_rep_id IS NOT NULL
    AND p_rep_id <> auth.uid()
  ) THEN
    RAISE EXCEPTION 'CALL_LIST_ACCESS_DENIED';
  END IF;

  RETURN (
    -- Authorization scope comes FIRST so the invoice-item aggregation below only
    -- ever runs over customers the caller may see (Codex gate finding: aggregating
    -- all customers' items before the rep filter wastes work at scale).
    WITH authorized_customers AS (
      SELECT c.id, c.farm_name, c.assigned_sales_rep
      FROM public.customers c
      WHERE c.is_active
        AND (
          (public.is_admin() AND (p_rep_id IS NULL OR c.assigned_sales_rep = p_rep_id))
          OR (public.is_sales_rep() AND c.assigned_sales_rep = auth.uid())
        )
    ),
    lapsed_products AS (
      SELECT
        i.customer_id,
        ii.product_id,
        COALESCE(p.product_name, ii.description) AS product_name,
        SUM(ii.extended_cents)::bigint AS prior_revenue_cents
      FROM public.invoices i
      JOIN authorized_customers ac ON ac.id = i.customer_id
      JOIN public.invoice_items ii ON ii.invoice_id = i.id
      LEFT JOIN public.products p ON p.id = ii.product_id
      WHERE i.season = v_season - 1
        AND i.deleted_at IS NULL
        AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
        AND i.status IN ('posted', 'paid', 'overdue')
        AND ii.product_id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM public.invoices current_invoice
          JOIN public.invoice_items current_item ON current_item.invoice_id = current_invoice.id
          WHERE current_invoice.customer_id = i.customer_id
            AND current_invoice.season = v_season
            AND current_invoice.deleted_at IS NULL
            AND COALESCE(current_invoice.invoice_type, 'invoice') <> 'credit_memo'
            AND current_invoice.status IN ('posted', 'paid', 'overdue')
            AND current_item.product_id = ii.product_id
        )
      GROUP BY i.customer_id, ii.product_id, COALESCE(p.product_name, ii.description)
    ),
    ranked_lapsed_products AS (
      SELECT
        lp.*,
        ROW_NUMBER() OVER (
          PARTITION BY lp.customer_id
          ORDER BY lp.prior_revenue_cents DESC, lp.product_name, lp.product_id
        ) AS product_rank
      FROM lapsed_products lp
    ),
    lapsed_accounts AS (
      SELECT
        rlp.customer_id,
        COUNT(*)::integer AS lapsed_count,
        MAX(rlp.product_name) FILTER (WHERE rlp.product_rank = 1) AS top_lapsed_product_name,
        MAX(rlp.prior_revenue_cents) FILTER (WHERE rlp.product_rank = 1)::bigint
          AS top_lapsed_product_prior_revenue_cents
      FROM ranked_lapsed_products rlp
      GROUP BY rlp.customer_id
    )
    SELECT jsonb_build_object(
      'success', true,
      'rows', COALESCE(jsonb_agg(jsonb_build_object(
        'customer_id', rows.customer_id,
        'farm_name', rows.farm_name,
        'assigned_sales_rep', rows.assigned_sales_rep,
        'primary_contact_name', rows.primary_contact_name,
        'phone_display', rows.phone_display,
        'phone_e164', rows.phone_e164,
        'last_interaction_at', rows.last_interaction_at,
        'lapsed_count', rows.lapsed_count,
        'top_lapsed_product_name', rows.top_lapsed_product_name,
        'top_lapsed_product_prior_revenue_cents', rows.top_lapsed_product_prior_revenue_cents
      ) ORDER BY rows.lapsed_count DESC, rows.top_lapsed_product_prior_revenue_cents DESC, rows.farm_name, rows.customer_id), '[]'::jsonb)
    )
    FROM (
      SELECT
        c.id AS customer_id,
        c.farm_name,
        c.assigned_sales_rep,
        contact.name AS primary_contact_name,
        contact.phone_display,
        contact.phone_e164,
        interaction.last_interaction_at,
        la.lapsed_count,
        la.top_lapsed_product_name,
        la.top_lapsed_product_prior_revenue_cents
      FROM lapsed_accounts la
      JOIN authorized_customers c ON c.id = la.customer_id
      LEFT JOIN LATERAL (
        SELECT cc.name, cc.phone_display, cc.phone_e164
        FROM public.customer_contacts cc
        WHERE cc.customer_id = c.id
          AND cc.is_primary
        LIMIT 1
      ) contact ON true
      LEFT JOIN LATERAL (
        SELECT MAX(ci.occurred_at) AS last_interaction_at
        FROM public.customer_interactions ci
        WHERE ci.customer_id = c.id
      ) interaction ON true
      ORDER BY la.lapsed_count DESC, la.top_lapsed_product_prior_revenue_cents DESC, c.farm_name, c.id
      LIMIT 200
    ) rows
  );
END;
$$;


ALTER FUNCTION "public"."get_call_list_lapsed_products"("p_rep_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_call_list_lapsed_products"("p_rep_id" "uuid") IS 'Returns authorized active customers summarized by products invoiced last season but not this season.';



CREATE OR REPLACE FUNCTION "public"."get_call_list_no_recent_contact"("p_rep_id" "uuid" DEFAULT NULL::"uuid", "p_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.is_active
      AND (public.is_admin() OR public.is_sales_rep())
  ) OR (
    public.is_sales_rep()
    AND p_rep_id IS NOT NULL
    AND p_rep_id <> auth.uid()
  ) THEN
    RAISE EXCEPTION 'CALL_LIST_ACCESS_DENIED';
  END IF;

  IF p_days < 0 THEN
    RAISE EXCEPTION 'CALL_LIST_INVALID_DAYS';
  END IF;

  RETURN (
    SELECT jsonb_build_object(
      'success', true,
      'rows', COALESCE(jsonb_agg(jsonb_build_object(
        'customer_id', rows.customer_id,
        'farm_name', rows.farm_name,
        'assigned_sales_rep', rows.assigned_sales_rep,
        'primary_contact_name', rows.primary_contact_name,
        'phone_display', rows.phone_display,
        'phone_e164', rows.phone_e164,
        'last_interaction_at', rows.last_interaction_at,
        'days_since_last_interaction', rows.days_since_last_interaction
      ) ORDER BY rows.last_interaction_at NULLS FIRST, rows.farm_name, rows.customer_id), '[]'::jsonb)
    )
    FROM (
      SELECT
        c.id AS customer_id,
        c.farm_name,
        c.assigned_sales_rep,
        contact.name AS primary_contact_name,
        contact.phone_display,
        contact.phone_e164,
        interaction.last_interaction_at,
        -- Same rolling-clock boundary as the WHERE filter below: a row shown with
        -- days_since >= p_days is always one the filter admitted (Codex M2).
        CASE
          WHEN interaction.last_interaction_at IS NULL THEN NULL
          ELSE floor(EXTRACT(epoch FROM (now() - interaction.last_interaction_at)) / 86400)::int
        END AS days_since_last_interaction
      FROM public.customers c
      LEFT JOIN LATERAL (
        SELECT cc.name, cc.phone_display, cc.phone_e164
        FROM public.customer_contacts cc
        WHERE cc.customer_id = c.id
          AND cc.is_primary
        LIMIT 1
      ) contact ON true
      LEFT JOIN LATERAL (
        SELECT MAX(ci.occurred_at) AS last_interaction_at
        FROM public.customer_interactions ci
        WHERE ci.customer_id = c.id
      ) interaction ON true
      WHERE c.is_active
        AND (
          interaction.last_interaction_at IS NULL
          OR interaction.last_interaction_at < now() - make_interval(days => p_days)
        )
        AND (
          (public.is_admin() AND (p_rep_id IS NULL OR c.assigned_sales_rep = p_rep_id))
          OR (public.is_sales_rep() AND c.assigned_sales_rep = auth.uid())
        )
      ORDER BY interaction.last_interaction_at NULLS FIRST, c.farm_name, c.id
      LIMIT 200
    ) rows
  );
END;
$$;


ALTER FUNCTION "public"."get_call_list_no_recent_contact"("p_rep_id" "uuid", "p_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_call_list_no_recent_contact"("p_rep_id" "uuid", "p_days" integer) IS 'Returns authorized active customers with no interaction in the requested number of days, including never-contacted customers.';



CREATE OR REPLACE FUNCTION "public"."get_call_list_prepay_prospects"("p_rep_id" "uuid" DEFAULT NULL::"uuid", "p_min_prior_spend_cents" bigint DEFAULT 100000) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_season integer := public.current_season();
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.is_active
      AND (public.is_admin() OR public.is_sales_rep())
  ) OR (
    public.is_sales_rep()
    AND p_rep_id IS NOT NULL
    AND p_rep_id <> auth.uid()
  ) THEN
    RAISE EXCEPTION 'CALL_LIST_ACCESS_DENIED';
  END IF;

  RETURN (
    WITH prior_spend AS (
      SELECT i.customer_id, SUM(i.total_amount_cents)::bigint AS prior_season_spend_cents
      FROM public.invoices i
      WHERE i.season = v_season - 1
        AND i.deleted_at IS NULL
        AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
        AND i.status IN ('posted', 'paid', 'overdue')
      GROUP BY i.customer_id
    ),
    current_prepay AS (
      SELECT pc.customer_id, SUM(pc.balance_cents)::bigint AS current_season_prepay_cents
      FROM public.prepay_credits pc
      WHERE pc.season = v_season
        AND pc.balance_cents > 0
      GROUP BY pc.customer_id
    )
    SELECT jsonb_build_object(
      'success', true,
      'rows', COALESCE(jsonb_agg(jsonb_build_object(
        'customer_id', rows.customer_id,
        'farm_name', rows.farm_name,
        'assigned_sales_rep', rows.assigned_sales_rep,
        'primary_contact_name', rows.primary_contact_name,
        'phone_display', rows.phone_display,
        'phone_e164', rows.phone_e164,
        'last_interaction_at', rows.last_interaction_at,
        'prior_season_spend_cents', rows.prior_season_spend_cents,
        'current_season_prepay_cents', rows.current_season_prepay_cents
      ) ORDER BY rows.prior_season_spend_cents DESC, rows.farm_name, rows.customer_id), '[]'::jsonb)
    )
    FROM (
      SELECT
        c.id AS customer_id,
        c.farm_name,
        c.assigned_sales_rep,
        contact.name AS primary_contact_name,
        contact.phone_display,
        contact.phone_e164,
        interaction.last_interaction_at,
        ps.prior_season_spend_cents,
        COALESCE(cp.current_season_prepay_cents, 0)::bigint AS current_season_prepay_cents
      FROM public.customers c
      JOIN prior_spend ps ON ps.customer_id = c.id
      LEFT JOIN current_prepay cp ON cp.customer_id = c.id
      LEFT JOIN LATERAL (
        SELECT cc.name, cc.phone_display, cc.phone_e164
        FROM public.customer_contacts cc
        WHERE cc.customer_id = c.id
          AND cc.is_primary
        LIMIT 1
      ) contact ON true
      LEFT JOIN LATERAL (
        SELECT MAX(ci.occurred_at) AS last_interaction_at
        FROM public.customer_interactions ci
        WHERE ci.customer_id = c.id
      ) interaction ON true
      WHERE c.is_active
        AND ps.prior_season_spend_cents >= p_min_prior_spend_cents
        AND COALESCE(cp.current_season_prepay_cents, 0) = 0
        AND (
          (public.is_admin() AND (p_rep_id IS NULL OR c.assigned_sales_rep = p_rep_id))
          OR (public.is_sales_rep() AND c.assigned_sales_rep = auth.uid())
        )
      ORDER BY ps.prior_season_spend_cents DESC, c.farm_name, c.id
      LIMIT 200
    ) rows
  );
END;
$$;


ALTER FUNCTION "public"."get_call_list_prepay_prospects"("p_rep_id" "uuid", "p_min_prior_spend_cents" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_call_list_prepay_prospects"("p_rep_id" "uuid", "p_min_prior_spend_cents" bigint) IS 'Returns authorized active customers with qualifying prior-season invoiced spend and no positive current-season prepay credit.';



CREATE OR REPLACE FUNCTION "public"."get_call_list_stale_quotes"("p_rep_id" "uuid" DEFAULT NULL::"uuid", "p_days" integer DEFAULT 14) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.is_active
      AND (public.is_admin() OR public.is_sales_rep())
  ) OR (
    public.is_sales_rep()
    AND p_rep_id IS NOT NULL
    AND p_rep_id <> auth.uid()
  ) THEN
    RAISE EXCEPTION 'CALL_LIST_ACCESS_DENIED';
  END IF;

  IF p_days < 0 THEN
    RAISE EXCEPTION 'CALL_LIST_INVALID_DAYS';
  END IF;

  RETURN (
    SELECT jsonb_build_object(
      'success', true,
      'rows', COALESCE(jsonb_agg(jsonb_build_object(
        'customer_id', rows.customer_id,
        'farm_name', rows.farm_name,
        'assigned_sales_rep', rows.assigned_sales_rep,
        'primary_contact_name', rows.primary_contact_name,
        'phone_display', rows.phone_display,
        'phone_e164', rows.phone_e164,
        'last_interaction_at', rows.last_interaction_at,
        'quote_id', rows.quote_id,
        'quote_number', rows.quote_number,
        'quote_total_cents', rows.quote_total_cents,
        'quote_updated_at', rows.quote_updated_at,
        'quote_age_days', rows.quote_age_days
      ) ORDER BY rows.quote_updated_at, rows.quote_number, rows.customer_id), '[]'::jsonb)
    )
    FROM (
      SELECT
        c.id AS customer_id,
        c.farm_name,
        c.assigned_sales_rep,
        contact.name AS primary_contact_name,
        contact.phone_display,
        contact.phone_e164,
        interaction.last_interaction_at,
        q.id AS quote_id,
        q.quote_number,
        ROUND(q.total_price * 100)::bigint AS quote_total_cents,
        q.updated_at AS quote_updated_at,
        (CURRENT_DATE - q.updated_at::date) AS quote_age_days
      FROM public.quotes q
      JOIN public.customers c ON c.id = q.customer_id
      LEFT JOIN LATERAL (
        SELECT cc.name, cc.phone_display, cc.phone_e164
        FROM public.customer_contacts cc
        WHERE cc.customer_id = c.id
          AND cc.is_primary
        LIMIT 1
      ) contact ON true
      LEFT JOIN LATERAL (
        SELECT MAX(ci.occurred_at) AS last_interaction_at
        FROM public.customer_interactions ci
        WHERE ci.customer_id = c.id
      ) interaction ON true
      WHERE c.is_active
        AND q.deleted_at IS NULL
        AND q.status IN ('draft', 'sent', 'revised')
        AND q.updated_at < now() - make_interval(days => p_days)
        AND (
          (public.is_admin() AND (p_rep_id IS NULL OR c.assigned_sales_rep = p_rep_id))
          OR (public.is_sales_rep() AND c.assigned_sales_rep = auth.uid())
        )
      ORDER BY q.updated_at, q.quote_number, c.id
      LIMIT 200
    ) rows
  );
END;
$$;


ALTER FUNCTION "public"."get_call_list_stale_quotes"("p_rep_id" "uuid", "p_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_call_list_stale_quotes"("p_rep_id" "uuid", "p_days" integer) IS 'Returns authorized active customers with open draft, sent, or revised quotes untouched for the requested number of days.';



CREATE OR REPLACE FUNCTION "public"."get_call_list_unassigned_accounts"("p_rep_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
