CREATE OR REPLACE FUNCTION "public"."get_chemical_history"("p_product_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("transaction_date" "text", "transaction_type" "text", "reference_number" "text", "customer_name" "text", "quantity" numeric, "unit" "text", "unit_price" numeric, "total_amount" numeric, "notes" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT * FROM (
    SELECT
      o.order_date::text AS td, 'Sale'::text AS tt, o.order_number AS rn, c.farm_name AS cn,
      oi.total_units_needed AS qty, oi.unit_size AS u, oi.price_per_unit AS up, oi.total_price AS ta, NULL::text AS n
    FROM public.order_items oi
    INNER JOIN public.orders o ON o.id = oi.order_id
    LEFT JOIN public.customers c ON c.id = o.customer_id
    WHERE oi.product_id = p_product_id
      AND o.order_date >= p_start_date
      AND o.order_date <= p_end_date
      AND o.deleted_at IS NULL
    UNION ALL
    SELECT
      COALESCE(po.submitted_date::text, po.created_at::date::text) AS td, 'Purchase'::text AS tt,
      po.po_number AS rn, po.vendor AS cn,
      poi.quantity_received AS qty, poi.unit_size AS u, poi.unit_cost AS up,
      poi.unit_cost * poi.quantity_received AS ta, poi.notes AS n
    FROM public.purchase_order_items poi
    INNER JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
    WHERE poi.product_id = p_product_id
      AND COALESCE(po.submitted_date, po.created_at::date) >= p_start_date
      AND COALESCE(po.submitted_date, po.created_at::date) <= p_end_date
  ) sub
  ORDER BY sub.td DESC;
END;
$$;


ALTER FUNCTION "public"."get_chemical_history"("p_product_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_commission_balance_report"("p_as_of_date" "date") RETURNS TABLE("recipient_id" "uuid", "recipient_name" "text", "total_earned" numeric, "total_paid" numeric, "outstanding_balance" numeric, "pending_count" bigint, "paid_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_active = true AND role = 'admin') THEN
    RAISE EXCEPTION 'Admin access required for commission balance report';
  END IF;
  RETURN QUERY
  SELECT cm.recipient_user_id, COALESCE(p.full_name, cm.recipient),
    ROUND(SUM(cm.commission_amount)::numeric, 2),
    ROUND(SUM(CASE WHEN cm.status = 'paid' THEN cm.commission_amount ELSE 0 END)::numeric, 2),
    ROUND(SUM(CASE WHEN cm.status = 'pending' THEN cm.commission_amount ELSE 0 END)::numeric, 2),
    COUNT(*) FILTER (WHERE cm.status = 'pending'),
    COUNT(*) FILTER (WHERE cm.status = 'paid')
  FROM commissions cm LEFT JOIN profiles p ON p.id = cm.recipient_user_id
  WHERE cm.order_date <= p_as_of_date
  GROUP BY cm.recipient_user_id, COALESCE(p.full_name, cm.recipient)
  ORDER BY SUM(CASE WHEN cm.status = 'pending' THEN cm.commission_amount ELSE 0 END) DESC;
END;
$$;


ALTER FUNCTION "public"."get_commission_balance_report"("p_as_of_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_balance_listing"("p_as_of_date" "date") RETURNS TABLE("customer_id" "uuid", "farm_name" "text", "total_invoiced" numeric, "total_paid" numeric, "prepay_applied" numeric, "outstanding_balance" numeric, "open_credit" numeric, "invoice_count" bigint, "oldest_unpaid_date" "date")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    c.id, c.farm_name,
    ROUND(COALESCE(SUM(i.total_amount_cents), 0) / 100.0, 2),
    ROUND(COALESCE(SUM(i.paid_amount_cents), 0) / 100.0, 2),
    ROUND(COALESCE(SUM(i.prepay_applied_cents), 0) / 100.0, 2),
    ROUND(COALESCE(SUM(i.balance_cents), 0) / 100.0, 2),
    ROUND(COALESCE(cm.credit_cents, 0) / 100.0, 2),
    COUNT(i.id),
    MIN(CASE WHEN i.balance_cents > 0 THEN i.invoice_date::date END)
  FROM public.customers c
  LEFT JOIN public.invoices i ON i.customer_id = c.id
    AND i.status IN ('posted', 'unposted')
    AND i.invoice_type <> 'credit_memo'
    AND i.deleted_at IS NULL
    AND i.invoice_date <= p_as_of_date
  LEFT JOIN (
    SELECT ci.customer_id, -SUM(ci.balance_cents) AS credit_cents
    FROM public.invoices ci
    WHERE ci.invoice_type = 'credit_memo' AND ci.status = 'posted'
      AND ci.balance_cents < 0 AND ci.deleted_at IS NULL
      AND ci.invoice_date <= p_as_of_date
    GROUP BY ci.customer_id
  ) cm ON cm.customer_id = c.id
  GROUP BY c.id, c.farm_name, cm.credit_cents
  HAVING COALESCE(SUM(i.balance_cents), 0) != 0 OR COALESCE(cm.credit_cents, 0) != 0
  ORDER BY COALESCE(SUM(i.balance_cents), 0) DESC;
$$;


ALTER FUNCTION "public"."get_customer_balance_listing"("p_as_of_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_delivery_remainders"("p_customer_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb) INTO v_result
  FROM (
    SELECT
      dr.id,
      dr.original_delivery_id,
      dr.order_id,
      dr.order_item_id,
      dr.customer_id,
      dr.product_id,
      dr.quantity_remaining,
      dr.unit_size,
      dr.status,
      dr.followup_delivery_id,
      dr.notes,
      dr.created_at,
      c.farm_name AS customer_name,
      p.product_name,
      d.delivery_number AS original_delivery_number,
      d.scheduled_date AS original_delivery_date,
      o.order_number
    FROM delivery_remainders dr
    JOIN customers c ON c.id = dr.customer_id
    JOIN products p ON p.id = dr.product_id
    JOIN deliveries d ON d.id = dr.original_delivery_id
    JOIN orders o ON o.id = dr.order_id
    WHERE (p_customer_id IS NULL OR dr.customer_id = p_customer_id)
    ORDER BY dr.created_at DESC
  ) r;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_customer_delivery_remainders"("p_customer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_farm_group"("p_customer_id" "uuid") RETURNS TABLE("id" "uuid", "farm_name" "text", "is_parent" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  -- Find the root parent (if selected customer IS a child, go up)
  WITH RECURSIVE root AS (
    SELECT c.id, c.farm_name, c.parent_customer_id
    FROM customers c WHERE c.id = p_customer_id
    UNION ALL
    SELECT p.id, p.farm_name, p.parent_customer_id
    FROM customers p
    JOIN root r ON r.parent_customer_id = p.id
  )
  -- The topmost customer is the parent
  , top_parent AS (
    SELECT id FROM root WHERE parent_customer_id IS NULL
    LIMIT 1
  )
  -- Return parent + all direct children
  SELECT c.id, c.farm_name,
         (c.id = tp.id) AS is_parent
  FROM customers c
  CROSS JOIN top_parent tp
  WHERE c.id = tp.id
     OR c.parent_customer_id = tp.id
  ORDER BY (c.id = tp.id) DESC, c.farm_name;
$$;


ALTER FUNCTION "public"."get_customer_farm_group"("p_customer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_customer_farm_group"("p_customer_id" "uuid") IS 'Returns the farm group: parent customer + all child customers linked via parent_customer_id.';



CREATE OR REPLACE FUNCTION "public"."get_customer_lapsed_products"("p_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_season integer := public.current_season();
  v_last_season integer := v_season - 1;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid() AND p.is_active
      AND (public.is_admin() OR (public.is_sales_rep() AND EXISTS (
        SELECT 1 FROM public.customers c
        WHERE c.id = p_customer_id AND c.assigned_sales_rep = auth.uid()
      )))
  ) THEN
    RAISE EXCEPTION 'PURCHASE_INTELLIGENCE_ACCESS_DENIED';
  END IF;

  RETURN jsonb_build_object(
    'season', v_season::text,
    'last_season', v_last_season::text,
    'products', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'product_name', lapsed.product_name,
        'last_season_qty', lapsed.last_season_qty,
        'last_season_revenue_cents', lapsed.last_season_revenue_cents
      ) ORDER BY lapsed.last_season_revenue_cents DESC, lapsed.product_name)
      FROM (
        SELECT
          ii.product_id,
          COALESCE(p.product_name, ii.description) AS product_name,
          SUM(ii.quantity) AS last_season_qty,
          SUM(ii.extended_cents)::bigint AS last_season_revenue_cents
        FROM public.invoices i
        JOIN public.invoice_items ii ON ii.invoice_id = i.id
        LEFT JOIN public.products p ON p.id = ii.product_id
        WHERE i.customer_id = p_customer_id
          AND i.season = v_last_season
          AND i.deleted_at IS NULL
          AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
          AND i.status IN ('posted', 'paid', 'overdue')
          AND ii.product_id IS NOT NULL
          AND NOT EXISTS (
            SELECT 1
            FROM public.invoices current_invoice
            JOIN public.invoice_items current_item ON current_item.invoice_id = current_invoice.id
            WHERE current_invoice.customer_id = p_customer_id
              AND current_invoice.season = v_season
              AND current_invoice.deleted_at IS NULL
              AND COALESCE(current_invoice.invoice_type, 'invoice') <> 'credit_memo'
              AND current_invoice.status IN ('posted', 'paid', 'overdue')
              AND current_item.product_id = ii.product_id
          )
        GROUP BY ii.product_id, COALESCE(p.product_name, ii.description)
      ) lapsed
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_customer_lapsed_products"("p_customer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_customer_lapsed_products"("p_customer_id" "uuid") IS 'Returns authorized customer products purchased last season but not this season.';



CREATE OR REPLACE FUNCTION "public"."get_customer_prep_card"("p_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid() AND p.is_active
      AND (public.is_admin() OR (public.is_sales_rep() AND EXISTS (
        SELECT 1 FROM public.customers c
        WHERE c.id = p_customer_id AND c.assigned_sales_rep = auth.uid()
      )))
  ) THEN
    RAISE EXCEPTION 'PURCHASE_INTELLIGENCE_ACCESS_DENIED';
  END IF;

  RETURN (
    SELECT jsonb_build_object(
      'customer_id', c.id,
      'farm_name', c.farm_name,
      'contacts', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', cc.id, 'name', cc.name, 'role', cc.role,
          'phone_display', cc.phone_display, 'phone_e164', cc.phone_e164,
          'preferred_contact_method', cc.preferred_contact_method
        ) ORDER BY cc.is_primary DESC, cc.name)
        FROM public.customer_contacts cc
        WHERE cc.customer_id = c.id AND (cc.is_primary OR cc.is_active)
      ), '[]'::jsonb),
      'balance_credit', jsonb_build_object(
        'credit_limit_cents', COALESCE(c.credit_limit_cents, 0),
        'prepay_balance_cents', COALESCE(c.prepay_balance_cents, 0),
        'open_ar_cents', COALESCE((
          SELECT SUM(i.balance_cents)::bigint FROM public.invoices i
          WHERE i.customer_id = c.id AND i.deleted_at IS NULL
            AND i.status IN ('posted', 'overdue')
        ), 0)
      ),
      'last_invoice', (
        SELECT jsonb_build_object('date', i.invoice_date, 'total_cents', i.total_amount_cents)
        FROM public.invoices i
        WHERE i.customer_id = c.id AND i.deleted_at IS NULL
          AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
          AND i.status IN ('posted', 'paid', 'overdue')
        ORDER BY i.invoice_date DESC, i.created_at DESC LIMIT 1
      ),
      'last_interaction', (
        SELECT jsonb_build_object(
          'occurred_at', ci.occurred_at, 'type', ci.interaction_type,
          'outcome', ci.outcome, 'summary', ci.summary, 'contact_name', cc.name
        )
        FROM public.customer_interactions ci
        LEFT JOIN public.customer_contacts cc ON cc.id = ci.contact_id
        WHERE ci.customer_id = c.id
        ORDER BY ci.occurred_at DESC LIMIT 1
      ),
      'open_follow_ups_count', (
        SELECT COUNT(*) FROM public.team_notes tn
        WHERE tn.linked_entity_type = 'customer' AND tn.linked_entity_id = c.id
          AND tn.note_type = 'todo' AND NOT tn.is_completed AND tn.deleted_at IS NULL
      ),
      -- Open workflow counts (Sol amendment 8): what is in flight right now.
      'open_workflow_counts', jsonb_build_object(
        'quotes', (
          SELECT COUNT(*) FROM public.quotes q
          WHERE q.customer_id = c.id AND q.deleted_at IS NULL
            AND q.status IN ('draft', 'sent', 'revised')
        ),
        'orders', (
          SELECT COUNT(*) FROM public.orders o
          WHERE o.customer_id = c.id AND o.deleted_at IS NULL
            AND o.status IN ('confirmed', 'partially_fulfilled')
        ),
        'deliveries', (
          SELECT COUNT(*) FROM public.deliveries d
          WHERE d.customer_id = c.id AND d.deleted_at IS NULL
            AND d.status IN ('scheduled', 'in_progress')
        )
      ),
      'top_verified_facts', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'category', facts.category, 'fact_key', facts.fact_key,
          'value_text', facts.value_text, 'value_json', facts.value_json
        ) ORDER BY facts.reviewed_at DESC)
        FROM (
          SELECT cf.category, cf.fact_key, cf.value_text, cf.value_json, cf.reviewed_at
          FROM public.customer_facts cf
          WHERE cf.customer_id = c.id AND cf.status = 'verified'
            AND cf.superseded_at IS NULL AND (cf.expires_at IS NULL OR cf.expires_at > now())
          ORDER BY cf.reviewed_at DESC LIMIT 6
        ) facts
      ), '[]'::jsonb),
      -- ONLY addition vs the live 20260716182318 body: top products ranked by
      -- QUANTITY. Grouped per (product, unit) so a sum NEVER mixes units: a
      -- product invoiced in two units appears as two separate lines, each
      -- labeled with its own unit ("unit" is NULL when the invoice lines carry
      -- none -- the UI renders the quantity bare in that case). Units still
      -- differ ACROSS products (gal vs lb vs AC), so line magnitudes are not
      -- directly comparable -- the UI displays the unit on every line. Same
      -- invoice scope/filters/period as
      -- get_customer_purchase_summary.top_products (current season,
      -- posted|paid|overdue, non-credit, not-deleted, product lines only) and
      -- the same LIMIT 10.
      'top_products_by_quantity', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'product_id', ranked_qty.product_id,
          'product_name', ranked_qty.product_name,
          'total_quantity', ranked_qty.total_quantity,
          'unit', ranked_qty.unit
        ) ORDER BY ranked_qty.total_quantity DESC, ranked_qty.product_name, ranked_qty.unit, ranked_qty.product_id)
        FROM (
          SELECT
            ii.product_id AS product_id,
            p.product_name AS product_name,
            SUM(ii.quantity) AS total_quantity,
            -- Unit shown next to quantity on the invoice PDF line:
            -- invoice_items.unit_size, falling back to invoice_items.rate_unit.
            -- Part of the GROUP BY, so each output row is single-unit.
            COALESCE(NULLIF(ii.unit_size, ''), NULLIF(ii.rate_unit, '')) AS unit
          FROM public.invoices i
          JOIN public.invoice_items ii ON ii.invoice_id = i.id
          JOIN public.products p ON p.id = ii.product_id
          WHERE i.customer_id = c.id
            AND i.season = public.current_season()
            AND i.deleted_at IS NULL
            AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
            AND i.status IN ('posted', 'paid', 'overdue')
            -- Products only: service-fee / misc lines have no product_id and
            -- must not rank in "top products".
            AND ii.product_id IS NOT NULL
          GROUP BY ii.product_id, p.product_name,
            COALESCE(NULLIF(ii.unit_size, ''), NULLIF(ii.rate_unit, ''))
          ORDER BY SUM(ii.quantity) DESC, p.product_name,
            COALESCE(NULLIF(ii.unit_size, ''), NULLIF(ii.rate_unit, '')),
            ii.product_id
          LIMIT 10
        ) ranked_qty
      ), '[]'::jsonb),
      'acres_tier', jsonb_build_object(
        'total_acres', c.total_acres, 'corn_acres', c.corn_acres,
        'soybean_acres', c.soybean_acres, 'other_acres', c.other_acres,
        'assigned_tier', c.assigned_tier
      )
    )
    FROM public.customers c WHERE c.id = p_customer_id
  );
END;
$$;


ALTER FUNCTION "public"."get_customer_prep_card"("p_customer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_customer_prep_card"("p_customer_id" "uuid") IS 'Returns one authorized customer prep-card snapshot: contacts, balances, recency, follow-ups, facts, top products by quantity, acres, and tier.';



CREATE OR REPLACE FUNCTION "public"."get_customer_purchase_summary"("p_customer_id" "uuid", "p_season" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_season integer := COALESCE(p_season::integer, public.current_season());
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.is_active
      AND (
        public.is_admin()
        OR (
          public.is_sales_rep()
          AND EXISTS (
            SELECT 1 FROM public.customers c
            WHERE c.id = p_customer_id
              AND c.assigned_sales_rep = auth.uid()
          )
        )
      )
  ) THEN
    RAISE EXCEPTION 'PURCHASE_INTELLIGENCE_ACCESS_DENIED';
  END IF;

  RETURN jsonb_build_object(
    'season', v_season::text,
    'total_invoiced_cents', COALESCE((
      SELECT SUM(i.total_amount_cents)::bigint
      FROM public.invoices i
      WHERE i.customer_id = p_customer_id
        AND i.season = v_season
        AND i.deleted_at IS NULL
        AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
        AND i.status IN ('posted', 'paid', 'overdue')
    ), 0),
    'invoice_count', (
      SELECT COUNT(*)
      FROM public.invoices i
      WHERE i.customer_id = p_customer_id
        AND i.season = v_season
        AND i.deleted_at IS NULL
        AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
        AND i.status IN ('posted', 'paid', 'overdue')
    ),
    'top_products', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'product_name', ranked.product_name,
        'total_qty', ranked.total_qty,
        'total_revenue_cents', ranked.total_revenue_cents
      ) ORDER BY ranked.total_revenue_cents DESC, ranked.product_name)
      FROM (
        SELECT
          p.product_name AS product_name,
          SUM(ii.quantity) AS total_qty,
          SUM(ii.extended_cents)::bigint AS total_revenue_cents
        FROM public.invoices i
        JOIN public.invoice_items ii ON ii.invoice_id = i.id
        JOIN public.products p ON p.id = ii.product_id
        WHERE i.customer_id = p_customer_id
          AND i.season = v_season
          AND i.deleted_at IS NULL
          AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
          AND i.status IN ('posted', 'paid', 'overdue')
          -- Products only: service-fee / misc lines have no product_id and
          -- must not rank in "top products".
          AND ii.product_id IS NOT NULL
        GROUP BY ii.product_id, p.product_name
        ORDER BY SUM(ii.extended_cents) DESC, p.product_name
        LIMIT 10
      ) ranked
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_customer_purchase_summary"("p_customer_id" "uuid", "p_season" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_customer_purchase_summary"("p_customer_id" "uuid", "p_season" "text") IS 'Returns one authorized customer''s seasonal invoiced total, count, and ten highest-revenue products.';



CREATE OR REPLACE FUNCTION "public"."get_customer_statement"("p_customer_id" "uuid", "p_start_date" "date" DEFAULT ((CURRENT_DATE - '90 days'::interval))::"date", "p_end_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("transaction_date" "date", "transaction_type" "text", "reference_number" "text", "description" "text", "amount_cents" bigint, "running_balance" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_role text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;

  SELECT role
    INTO v_actor_role
    FROM public.profiles
   WHERE id = v_actor
     AND is_active = true;

  IF v_actor_role = 'sales_rep' THEN
    IF NOT EXISTS (
      SELECT 1
        FROM public.customers
       WHERE id = p_customer_id
         AND assigned_sales_rep = v_actor
    ) THEN
      RAISE EXCEPTION 'CUSTOMER_SCOPE_DENIED';
    END IF;
  ELSIF v_actor_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  RETURN QUERY
  SELECT *
    FROM public._get_customer_statement_scoped_impl(
      p_customer_id,
      p_start_date,
      p_end_date
    );
END;
$$;


ALTER FUNCTION "public"."get_customer_statement"("p_customer_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_customer_statement"("p_customer_id" "uuid", "p_start_date" "date", "p_end_date" "date") IS 'Returns a customer statement to an active admin or the active sales rep assigned to that customer.';



CREATE OR REPLACE FUNCTION "public"."get_customer_summary"("p_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_ar_balance bigint;
  v_order_count int;
  v_delivery_count int;
  v_credit_tier int;
  v_last_activity timestamptz;
  v_season_start date;
  v_season_end date;
BEGIN
  IF extract(month FROM current_date) >= 10 THEN
    v_season_start := make_date(extract(year FROM current_date)::int, 10, 1);
    v_season_end := make_date(extract(year FROM current_date)::int + 1, 9, 30);
  ELSE
    v_season_start := make_date(extract(year FROM current_date)::int - 1, 10, 1);
    v_season_end := make_date(extract(year FROM current_date)::int, 9, 30);
  END IF;

  SELECT COALESCE(sum(balance_cents), 0)
  INTO v_ar_balance
  FROM invoices
  WHERE customer_id = p_customer_id
    AND status IN ('posted', 'overdue');

  SELECT count(*)
  INTO v_order_count
  FROM orders
  WHERE customer_id = p_customer_id
    AND order_date >= v_season_start
    AND order_date <= v_season_end
    AND status NOT IN ('cancelled', 'voided');

  SELECT count(*)
  INTO v_delivery_count
  FROM deliveries
  WHERE customer_id = p_customer_id
    AND status = 'completed'
    AND completed_at >= v_season_start
    AND completed_at <= v_season_end;

  SELECT assigned_tier
  INTO v_credit_tier
  FROM customers
  WHERE id = p_customer_id;

  SELECT max(created_at)
  INTO v_last_activity
  FROM activity_feed
  WHERE customer_id = p_customer_id;

  v_result := jsonb_build_object(
    'ar_balance_cents', v_ar_balance,
    'order_count', v_order_count,
    'delivery_count', v_delivery_count,
    'credit_tier', v_credit_tier,
    'last_activity', v_last_activity
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_customer_summary"("p_customer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_transaction_review"("p_customer_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("transaction_date" "date", "transaction_type" "text", "reference_number" "text", "description" "text", "debit_cents" bigint, "credit_cents" bigint, "running_balance_cents" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM require_admin();
  RETURN QUERY
  WITH all_transactions AS (
    SELECT i.invoice_date AS tx_date,
           'Invoice' AS tx_type,
           i.invoice_number AS ref_num,
           CASE i.invoice_type
             WHEN 'chemical_sale' THEN 'Chemical Sale'
             WHEN 'field_application' THEN 'Field Application'
             WHEN 'misc_charge' THEN 'Misc Charge'
             ELSE COALESCE(i.invoice_type, 'Invoice')
           END AS descr,
           i.total_amount_cents AS debit,
           0::bigint AS credit
      FROM public.invoices i
     WHERE i.customer_id = p_customer_id
       AND i.status IN ('posted', 'paid', 'overdue')
       AND i.deleted_at IS NULL
       AND i.invoice_date BETWEEN p_start_date AND p_end_date

    UNION ALL

    SELECT als.payment_date AS tx_date,
           'Payment' AS tx_type,
           COALESCE(als.reference_number, als.check_number, 'PMT-' || LEFT(als.id::text, 8)) AS ref_num,
           COALESCE(als.payment_method, 'Payment') ||
             CASE WHEN als.check_number IS NOT NULL THEN ' #' || als.check_number ELSE '' END ||
             COALESCE(' — ' || als.notes, '') AS descr,
           0::bigint AS debit,
           ila.amount_cents AS credit
      FROM public.allocation_sets als
      JOIN public.invoice_line_allocations ila ON ila.allocation_set_id = als.id
     WHERE als.customer_id = p_customer_id
       AND als.payment_date BETWEEN p_start_date AND p_end_date

    UNION ALL

    SELECT pa.applied_at::date AS tx_date,
           'Prepay Applied' AS tx_type,
           'PP-' || LEFT(pa.id::text, 8) AS ref_num,
           'Prepay credit applied' AS descr,
           0::bigint AS debit,
           pa.applied_amount_cents AS credit
      FROM public.prepay_applications pa
      JOIN public.invoices i ON i.id = pa.invoice_id
     WHERE i.customer_id = p_customer_id
       AND i.deleted_at IS NULL
       AND pa.applied_at::date BETWEEN p_start_date AND p_end_date

    UNION ALL

    SELECT w.created_at::date AS tx_date,
           'Write-Off' AS tx_type,
           'WO-' || LEFT(w.id::text, 8) AS ref_num,
           COALESCE(w.reason, 'Write-off') AS descr,
           0::bigint AS debit,
           w.amount_cents AS credit
      FROM public.write_offs w
     WHERE w.customer_id = p_customer_id
       AND w.created_at::date BETWEEN p_start_date AND p_end_date
  )
  SELECT t.tx_date AS transaction_date,
         t.tx_type AS transaction_type,
         t.ref_num AS reference_number,
         t.descr AS description,
         t.debit AS debit_cents,
         t.credit AS credit_cents,
         (SUM(t.debit - t.credit) OVER (ORDER BY t.tx_date, t.tx_type, t.ref_num))::bigint AS running_balance_cents
    FROM all_transactions t
   ORDER BY t.tx_date, t.tx_type, t.ref_num;
END;
$$;


ALTER FUNCTION "public"."get_customer_transaction_review"("p_customer_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_year_end_summary"("p_customer_id" "uuid", "p_season" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cust            record;
  v_season_start    date;
  v_season_end      date;
  v_financial       jsonb;
  v_product_usage   jsonb;
  v_acreage         jsonb;
  v_invoices        jsonb;
  v_shares          jsonb;
  v_prior_season    jsonb;
BEGIN
  -- ── Customer info ──
  SELECT * INTO v_cust FROM customers WHERE id = p_customer_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Customer not found: %', p_customer_id;
  END IF;

  -- Season dates: Oct 1 (season-1) through Sep 30 (season)
  v_season_start := season_start_date(p_season);
  v_season_end   := season_end_date(p_season);

  -- ── Financial summary ──
  SELECT jsonb_build_object(
    'total_invoiced_cents', COALESCE(SUM(total_amount_cents), 0),
    'total_paid_cents', COALESCE(SUM(paid_amount_cents), 0),
    'prepay_applied_cents', COALESCE(SUM(prepay_applied_cents), 0),
    'outstanding_balance_cents', COALESCE(SUM(balance_cents), 0),
    'invoice_count', COUNT(*)
  )
  INTO v_financial
  FROM invoices
  WHERE customer_id = p_customer_id
    AND season = p_season
    AND status IN ('posted', 'voided')
    AND deleted_at IS NULL;

  -- ── Product usage by category ──
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.category, t.product_name), '[]'::jsonb)
  INTO v_product_usage
  FROM (
    SELECT
      COALESCE(p.category, 'Uncategorized') AS category,
      COALESCE(p.product_name, ii.description) AS product_name,
      p.epa_registration,
      SUM(ii.quantity) AS total_quantity,
      MAX(ii.unit_size) AS unit_size,
      CASE WHEN SUM(COALESCE(ii.acres, 0)) > 0
        THEN ROUND(AVG(ii.rate_per_acre)::numeric, 2)
        ELSE NULL
      END AS avg_rate_per_acre,
      MAX(ii.rate_unit) AS rate_unit,
      SUM(COALESCE(ii.acres, 0)) AS total_acres_treated,
      SUM(ii.extended_cents) AS total_cost_cents,
      SUM(COALESCE(ii.total_applied, 0)) AS total_applied,
      MAX(ii.total_applied_unit) AS total_applied_unit,
      SUM(COALESCE(ii.total_applied_gl_lb, 0)) AS total_applied_gl_lb,
      MAX(ii.gl_lb_unit) AS gl_lb_unit,
      ii.is_application_fee
    FROM invoice_items ii
    JOIN invoices i ON i.id = ii.invoice_id
    LEFT JOIN products p ON p.id = ii.product_id
    WHERE i.customer_id = p_customer_id
      AND i.season = p_season
      AND i.status = 'posted'
      AND i.deleted_at IS NULL
    GROUP BY COALESCE(p.category, 'Uncategorized'),
             COALESCE(p.product_name, ii.description),
             p.epa_registration,
             ii.is_application_fee
  ) t;

  -- ── Acreage summary ──
  SELECT jsonb_build_object(
    'total_acres', COALESCE(SUM(i.total_acres), 0),
    'by_crop', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'crop_type', sub.crop_type,
        'acres', sub.total_acres
      ) ORDER BY sub.total_acres DESC)
      FROM (
        SELECT COALESCE(crop_type, 'Unknown') AS crop_type,
               SUM(total_acres) AS total_acres
        FROM invoices
        WHERE customer_id = p_customer_id
          AND season = p_season
          AND invoice_type = 'field_application'
          AND status = 'posted'
          AND deleted_at IS NULL
          AND total_acres IS NOT NULL
        GROUP BY COALESCE(crop_type, 'Unknown')
      ) sub
    ), '[]'::jsonb)
  )
  INTO v_acreage
  FROM invoices i
  WHERE i.customer_id = p_customer_id
    AND i.season = p_season
    AND i.invoice_type = 'field_application'
    AND i.status = 'posted'
    AND i.deleted_at IS NULL;

  -- ── Invoice history ──
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'invoice_number', i.invoice_number,
    'invoice_date', i.invoice_date,
    'invoice_type', i.invoice_type,
    'field_names', i.field_names,
    'total_acres', i.total_acres,
    'crop_type', i.crop_type,
    'total_amount_cents', i.total_amount_cents,
    'balance_cents', i.balance_cents,
    'status', i.status
  ) ORDER BY i.invoice_date, i.created_at), '[]'::jsonb)
  INTO v_invoices
  FROM invoices i
  WHERE i.customer_id = p_customer_id
    AND i.season = p_season
    AND i.status IN ('posted', 'voided')
    AND i.deleted_at IS NULL;

  -- ── Grower shares ──
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'invoice_number', i.invoice_number,
    'field_names', i.field_names,
    'share_customer_name', s.customer_name,
    'split_percentage', s.split_percentage,
    'acres', s.acres,
    'amount_cents', s.amount_cents,
    'price_per_acre_cents', s.price_per_acre_cents,
    'pricing_note', s.pricing_note
  ) ORDER BY i.invoice_date, s.sort_order), '[]'::jsonb)
  INTO v_shares
  FROM invoice_shares s
  JOIN invoices i ON i.id = s.invoice_id
  WHERE i.customer_id = p_customer_id
    AND i.season = p_season
    AND i.status = 'posted'
    AND i.deleted_at IS NULL;

  -- ── Prior season comparison ──
  SELECT CASE
    WHEN COUNT(*) > 0 THEN
      jsonb_build_object(
        'total_invoiced_cents', COALESCE(SUM(total_amount_cents), 0),
        'total_paid_cents', COALESCE(SUM(paid_amount_cents), 0),
        'invoice_count', COUNT(*),
        'total_acres', COALESCE((
          SELECT SUM(total_acres)
          FROM invoices
          WHERE customer_id = p_customer_id
            AND season = p_season - 1
            AND invoice_type = 'field_application'
            AND status IN ('posted', 'voided')
            AND deleted_at IS NULL
        ), 0)
      )
    ELSE NULL
  END
  INTO v_prior_season
  FROM invoices
  WHERE customer_id = p_customer_id
    AND season = p_season - 1
    AND status IN ('posted', 'voided')
    AND deleted_at IS NULL;

  -- ── Build and return ──
  RETURN jsonb_build_object(
    'customer', jsonb_build_object(
      'id', v_cust.id,
      'farm_name', v_cust.farm_name,
      'contact_name', v_cust.contact_name,
      'account_number', v_cust.account_number,
      'email', v_cust.email,
      'phone', v_cust.phone,
      'billing_address', v_cust.billing_address,
      'city', v_cust.city,
      'state', v_cust.state,
      'zip', v_cust.zip,
      'assigned_tier', v_cust.assigned_tier,
      'payment_terms', v_cust.payment_terms
    ),
    'season', p_season,
    'season_start', v_season_start,
    'season_end', v_season_end,
    'financial', v_financial,
    'product_usage', v_product_usage,
    'acreage', v_acreage,
    'invoices', v_invoices,
    'shares', v_shares,
    'prior_season', v_prior_season
  );
END;
$$;


ALTER FUNCTION "public"."get_customer_year_end_summary"("p_customer_id" "uuid", "p_season" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_action_items"("p_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb := '{}'::jsonb;
  v_today date := current_date;
BEGIN
  -- 1. Overdue Invoices
  SELECT jsonb_agg(row_to_json(t))
  INTO v_result
  FROM (
    SELECT
      'overdue_invoice' AS category,
      i.id,
      i.invoice_number AS primary_text,
      c.farm_name AS secondary_text,
      (v_today - i.due_date) AS days_overdue,
      i.balance_cents AS amount_cents
    FROM invoices i
    JOIN customers c ON c.id = i.customer_id
    WHERE i.status = 'overdue'
      AND i.balance_cents > 0
    ORDER BY (v_today - i.due_date) DESC
    LIMIT p_limit
  ) t;

  v_result := jsonb_build_object('overdue_invoices', COALESCE(v_result, '[]'::jsonb));

  -- 2. Cancelled Orders with Posted Invoices
  v_result := v_result || jsonb_build_object('cancelled_posted', (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
    FROM (
      SELECT
        o.id,
        o.order_number AS primary_text,
        c.farm_name AS secondary_text,
        i.invoice_number
      FROM orders o
      JOIN customers c ON c.id = o.customer_id
      JOIN invoices i ON i.order_id = o.id AND i.status = 'posted'
      WHERE o.status = 'cancelled'
      ORDER BY o.created_at DESC
      LIMIT p_limit
    ) t
  ));

  -- 3. Overdue Deliveries
  v_result := v_result || jsonb_build_object('overdue_deliveries', (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
    FROM (
      SELECT
        d.id,
        d.delivery_number AS primary_text,
        c.farm_name AS secondary_text,
        (v_today - d.scheduled_date) AS days_overdue
      FROM deliveries d
      JOIN customers c ON c.id = d.customer_id
      WHERE d.status IN ('scheduled', 'in_progress')
        AND d.scheduled_date < v_today
      ORDER BY d.scheduled_date ASC
      LIMIT p_limit
    ) t
  ));

  -- 4. Low Stock Items
  v_result := v_result || jsonb_build_object('low_stock', (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
    FROM (
      SELECT
        p.id,
        p.product_name AS primary_text,
        p.category AS secondary_text,
        COALESCE(inv.quantity_available, 0) AS current_qty,
        COALESCE(inv.reorder_point, 0) AS reorder_point
      FROM products p
      JOIN inventory inv ON inv.product_id = p.id
      WHERE p.is_active = true
        AND (
          (inv.reorder_point IS NOT NULL
            AND inv.reorder_point > 0
            AND COALESCE(inv.quantity_available, 0) < inv.reorder_point)
          OR COALESCE(inv.quantity_available, 0) < 0
        )
      ORDER BY (COALESCE(inv.quantity_available, 0)::float / NULLIF(inv.reorder_point, 0)) ASC
      LIMIT p_limit
    ) t
  ));

  -- 5. Expiring Quotes (within 7 days)
  v_result := v_result || jsonb_build_object('expiring_quotes', (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
    FROM (
      SELECT
        q.id,
        q.quote_number AS primary_text,
        c.farm_name AS secondary_text,
        (q.expires_at::date - v_today) AS days_until_expiry
      FROM quotes q
      JOIN customers c ON c.id = q.customer_id
      WHERE q.status IN ('sent', 'revised')
        AND q.is_planned = false
        AND q.expires_at IS NOT NULL
        AND q.expires_at::date BETWEEN v_today AND (v_today + interval '7 days')
      ORDER BY q.expires_at ASC
      LIMIT p_limit
    ) t
  ));

  -- 6. Unassigned Deliveries
  v_result := v_result || jsonb_build_object('unassigned_deliveries', (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
    FROM (
      SELECT
        d.id,
        d.delivery_number AS primary_text,
        c.farm_name AS secondary_text,
        d.scheduled_date
      FROM deliveries d
      JOIN customers c ON c.id = d.customer_id
      WHERE d.status = 'scheduled'
        AND d.assigned_driver IS NULL
      ORDER BY d.scheduled_date ASC
      LIMIT p_limit
    ) t
  ));

  -- U13<<< 7. Unassigned Jobs (findings #15-21/#111): a SCHEDULED job with no
  -- currently-active per-location dispatch — neither the wizard's per-location
  -- assignment NOR (indirectly, via the sync triggers above) a whole-job
  -- applicator has reached the field crew. deleted_at IS NULL mirrors the other
  -- job reads.
  v_result := v_result || jsonb_build_object('unassigned_jobs', (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
    FROM (
      SELECT
        j.id,
        j.job_number AS primary_text,
        c.farm_name AS secondary_text,
        j.job_date AS scheduled_date
      FROM jobs j
      JOIN customers c ON c.id = j.customer_id
      WHERE j.status = 'scheduled'
        AND j.deleted_at IS NULL
        -- Codex R1 P2: a job with a legacy WHOLE-JOB applicator is assigned,
        -- not "unassigned" — pre-trigger jobs have no dispatch rows yet (no
        -- backfill: business-data writes are outside this run's additive-only
        -- mandate; rows materialize via the triggers on the next edit, and
        -- FieldView already surfaces legacy assignments client-side).
        AND j.applicator_id IS NULL
        AND NOT EXISTS (
          SELECT 1 FROM job_location_dispatches d
          WHERE d.job_id = j.id AND d.dispatch_status = 'dispatched'
        )
      ORDER BY j.job_date ASC
      LIMIT p_limit
    ) t
  ));
  -- >>>U13

  -- 8. Due-today deliveries that have not been started.
  v_result := v_result || jsonb_build_object('due_today_not_started', (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
    FROM (
      SELECT
        d.id,
        d.delivery_number AS primary_text,
        c.farm_name AS secondary_text,
        d.scheduled_date
      FROM deliveries d
      JOIN customers c ON c.id = d.customer_id
      WHERE d.scheduled_date = v_today
        AND d.status = 'scheduled'
        AND d.deleted_at IS NULL
      ORDER BY d.delivery_number ASC
      LIMIT p_limit
    ) t
  ));

  -- 9. Completed deliveries not covered by an active delivery- or order-level invoice.
  v_result := v_result || jsonb_build_object('unbilled_deliveries', (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
    FROM (
      SELECT
        d.id,
        d.delivery_number AS primary_text,
        c.farm_name AS secondary_text,
        d.scheduled_date
      FROM deliveries d
      JOIN customers c ON c.id = d.customer_id
      WHERE d.status = 'completed'
        AND d.deleted_at IS NULL
        AND d.order_id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM invoices i
          WHERE i.order_id = d.order_id
            AND i.status NOT IN ('voided', 'cancelled')
            AND (i.delivery_id = d.id OR i.delivery_id IS NULL)
            AND i.deleted_at IS NULL
        )
      ORDER BY d.scheduled_date ASC
      LIMIT p_limit
    ) t
  ));

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_dashboard_action_items"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_detailed_statement_data"("p_customer_id" "uuid", "p_as_of_date" "date", "p_mode" "text" DEFAULT 'summary'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer RECORD;
  v_aging jsonb;
  v_balance bigint := 0;
  v_inv RECORD;
  v_items jsonb;
  v_shares jsonb;
  v_finance_cents bigint;
  v_txn_list jsonb := '[]'::jsonb;
  v_days_aged integer;
  v_description text;
  v_grower_names text[];
BEGIN
  PERFORM require_admin();
  SELECT * INTO v_customer FROM customers WHERE id = p_customer_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Customer not found: %', p_customer_id;
  END IF;

  FOR v_inv IN
    SELECT i.*
    FROM invoices i
    WHERE i.customer_id = p_customer_id
      AND i.status IN ('posted', 'overdue')
      AND i.balance_cents > 0
      AND i.deleted_at IS NULL
      AND i.invoice_date <= p_as_of_date
    ORDER BY i.invoice_date, i.invoice_number
  LOOP
    v_balance := v_balance + v_inv.balance_cents;
    v_days_aged := p_as_of_date - v_inv.invoice_date;

    IF v_inv.invoice_type = 'field_application' AND v_inv.crop_type IS NOT NULL THEN
      v_description := COALESCE(v_inv.crop_type, '')
        || ' - ' || COALESCE(v_inv.total_acres::text, '')
        || ' - ' || COALESCE(array_to_string(v_inv.field_names, ', '), '');
    ELSIF v_inv.invoice_type = 'chemical_sale' THEN
      v_description := 'Chemical Sale: ' || COALESCE(v_inv.header_notes, '');
    ELSE
      v_description := COALESCE(v_inv.header_notes, v_inv.invoice_type);
    END IF;

    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'customer_name', s.customer_name,
          'split_percentage', s.split_percentage,
          'acres', s.acres,
          'amount_cents', s.amount_cents,
          'is_primary', s.is_primary,
          'price_per_acre_cents', CASE
            WHEN s.customer_id = p_customer_id THEN s.price_per_acre_cents
            ELSE NULL
          END,
          'pricing_note', CASE
            WHEN s.customer_id = p_customer_id THEN s.pricing_note
            ELSE NULL
          END
        ) ORDER BY s.sort_order
      ),
      '[]'::jsonb
    )
    INTO v_shares
    FROM invoice_shares s
    WHERE s.invoice_id = v_inv.id;

    SELECT array_agg(s.customer_name ORDER BY s.sort_order)
    INTO v_grower_names
    FROM invoice_shares s
    WHERE s.invoice_id = v_inv.id;

    v_items := '[]'::jsonb;
    IF p_mode = 'detailed' THEN
      SELECT COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'product_name', ii.description,
            'epa_registration', ii.epa_registration,
            'rate_per_acre', ii.rate_per_acre,
            'rate_unit', ii.rate_unit,
            'total_applied', ii.total_applied,
            'total_applied_unit', ii.total_applied_unit,
            'total_applied_gl_lb', ii.total_applied_gl_lb,
            'gl_lb_unit', ii.gl_lb_unit,
            'unit_price_cents', ii.unit_price_cents,
            'total_cost_cents', ii.extended_cents,
            'is_application_fee', COALESCE(ii.is_application_fee, false),
            'quantity', ii.quantity,
            'unit_size', ii.unit_size,
            'product_form', ii.product_form
          ) ORDER BY ii.sort_order
        ),
        '[]'::jsonb
      )
      INTO v_items
      FROM invoice_items ii
      WHERE ii.invoice_id = v_inv.id;
    END IF;

    SELECT COALESCE(sum(fc.amount_cents), 0)
    INTO v_finance_cents
    FROM finance_charges fc
    WHERE fc.invoice_id = v_inv.id;

    v_txn_list := v_txn_list || jsonb_build_object(
      'invoice_number', v_inv.invoice_number,
      'invoice_date', v_inv.invoice_date,
      'due_date', v_inv.due_date,
      'invoice_type', v_inv.invoice_type,
      'status', v_inv.status,
      'days_aged', v_days_aged,
      'description', v_description,
      'crop_type', v_inv.crop_type,
      'field_names', v_inv.field_names,
      'total_acres', v_inv.total_acres,
      'grower_names', v_grower_names,
      'total_amount_cents', v_inv.total_amount_cents,
      'paid_amount_cents', v_inv.paid_amount_cents,
      'prepay_applied_cents', v_inv.prepay_applied_cents,
      'balance_cents', v_inv.balance_cents,
      'items', v_items,
      'shares', v_shares,
      'finance_charge_cents', v_finance_cents,
      'net_due_cents', v_inv.balance_cents + v_finance_cents,
      'price_per_acre', CASE
        WHEN v_inv.total_acres > 0 THEN
          round(v_inv.total_amount_cents / 100.0 / v_inv.total_acres, 2)
        ELSE NULL
      END
    );
  END LOOP;

  -- Fixed aging buckets: non-overlapping, includes overdue status
  -- A8-aging: basis switched invoice_date -> COALESCE(due_date, invoice_date); boundaries unchanged.
  SELECT jsonb_build_object(
    'current_cents', COALESCE(sum(CASE WHEN p_as_of_date - COALESCE(i.due_date, i.invoice_date) <= 30 THEN i.balance_cents ELSE 0 END), 0),
    'days_30_cents', COALESCE(sum(CASE WHEN p_as_of_date - COALESCE(i.due_date, i.invoice_date) BETWEEN 31 AND 60 THEN i.balance_cents ELSE 0 END), 0),
    'days_60_cents', COALESCE(sum(CASE WHEN p_as_of_date - COALESCE(i.due_date, i.invoice_date) BETWEEN 61 AND 90 THEN i.balance_cents ELSE 0 END), 0),
    'days_90_cents', COALESCE(sum(CASE WHEN p_as_of_date - COALESCE(i.due_date, i.invoice_date) BETWEEN 91 AND 120 THEN i.balance_cents ELSE 0 END), 0),
    'over_120_cents', COALESCE(sum(CASE WHEN p_as_of_date - COALESCE(i.due_date, i.invoice_date) > 120 THEN i.balance_cents ELSE 0 END), 0)
  )
  INTO v_aging
  FROM invoices i
  WHERE i.customer_id = p_customer_id
    AND i.status IN ('posted', 'overdue')
    AND i.balance_cents > 0
    AND i.deleted_at IS NULL
    AND i.invoice_date <= p_as_of_date;

  RETURN jsonb_build_object(
    'customer', jsonb_build_object(
      'id', v_customer.id,
      'farm_name', v_customer.farm_name,
      'contact_name', v_customer.contact_name,
      'account_number', v_customer.account_number,
      'email', v_customer.email,
      'phone', v_customer.phone,
      'billing_address', v_customer.billing_address,
      'city', v_customer.city,
      'state', v_customer.state,
      'zip', v_customer.zip,
      'payment_terms', v_customer.payment_terms
    ),
    'transactions', v_txn_list,
    'aging', v_aging,
    'outstanding_balance_cents', v_balance,
    'as_of_date', p_as_of_date,
    'mode', p_mode
  );
END;
$$;


ALTER FUNCTION "public"."get_detailed_statement_data"("p_customer_id" "uuid", "p_as_of_date" "date", "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dispatch_board_jobs"("p_applicator_id" "uuid", "p_status" "text" DEFAULT NULL::"text", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS SETOF "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  -- A dispatch row is VISIBLE to the caller (mirrors job_location_dispatches_select):
  --   admin/sales see all; the job's whole-job applicator sees every row on their job;
  --   otherwise a field user sees a row where they are the assignee or an active member
  --   of the assigned active crew.
  WITH matched AS (
    SELECT j.*
      FROM public.jobs j
     WHERE j.deleted_at IS NULL
       AND p_applicator_id IS NOT NULL
       AND (p_status IS NULL OR j.status = p_status)
       AND (p_start_date IS NULL OR j.job_date >= p_start_date)
       AND (p_end_date IS NULL OR j.job_date <= p_end_date)
       AND (
         -- (a) a CURRENT per-location dispatch to this applicator the CALLER can see
         EXISTS (
           SELECT 1 FROM public.job_location_dispatches d
            WHERE d.job_id = j.id
              AND d.dispatch_status = 'dispatched'
              AND d.applicator_id = p_applicator_id
              AND (
                is_admin()
                OR is_sales_rep()
                OR (is_applicator() AND j.applicator_id = (select auth.uid()))
                OR d.applicator_id = (select auth.uid())
              )
         )
         OR (
           -- (b) whole-job applicator = this one AND the job has NO per-location dispatch
           j.applicator_id = p_applicator_id
           AND NOT EXISTS (
             SELECT 1 FROM public.job_location_dispatches d2
              WHERE d2.job_id = j.id
                AND d2.dispatch_status = 'dispatched'
           )
         )
       )
       -- VISIBILITY GATE — the live jobs SELECT predicate. Never return a hidden job.
       AND (
         is_admin()
         OR is_sales_rep()
         OR (is_applicator() AND j.applicator_id = (select auth.uid()))
         OR public._is_dispatched_to_me(j.id)
       )
     ORDER BY j.job_date DESC NULLS LAST
     LIMIT 500
  )
  SELECT
    to_jsonb(m)
    || jsonb_build_object(
         -- CUSTOMER NAME — RLS-equivalent (Codex re-review-3 P2): this function is
         -- SECURITY DEFINER, so a raw `customers` read would bypass customers_select and
         -- could leak a farm_name the caller can't otherwise see (a sales_rep is limited
         -- to assigned customers; an applicator/driver to a time-windowed set). Return the
         -- name ONLY when the caller would pass customers_select OR
         -- customers_select_location_dispatchee for THIS job's customer; else farm_name
         -- is null (the board renders 'Unknown', exactly as the unfiltered RLS embed would).
         'customer',
         (SELECT jsonb_build_object(
                   'farm_name',
                   CASE WHEN (
                     is_admin()
                     OR (is_sales_rep() AND c.assigned_sales_rep = (select auth.uid()))
                     OR (is_driver() AND EXISTS (
                           SELECT 1 FROM public.deliveries d
                            WHERE d.customer_id = c.id
                              AND d.assigned_driver = (select auth.uid())
                              AND d.scheduled_date >= (CURRENT_DATE - interval '1 day')))
                     OR (is_applicator() AND EXISTS (
                           SELECT 1 FROM public.jobs j2
                            WHERE j2.customer_id = c.id
                              AND j2.applicator_id = (select auth.uid())
                              AND j2.job_date >= (CURRENT_DATE - interval '7 days')))
                     OR EXISTS (
                           SELECT 1 FROM public.jobs j3
                            WHERE j3.customer_id = c.id
                              AND public._is_dispatched_to_me(j3.id))
                   ) THEN c.farm_name ELSE NULL END)
            FROM public.customers c WHERE c.id = m.customer_id),
         -- JOB_FIELDS — job_fields_select is satisfied for every job that passed this
         -- function's visibility gate (admin/sales_rep/whole-job applicator/_is_dispatched_to_me
         -- are exactly its conditions), so listing the rows leaks nothing. field_name is
         -- gated to the fields_select predicate (admin/sales_rep/applicator) so a dispatched
         -- crew member whose role is NOT applicator doesn't get a field name they couldn't
         -- read under RLS (null → the board falls back to 'Field'). (Codex re-review-3 P2.)
         'job_fields',
         coalesce((
           SELECT jsonb_agg(
                    jsonb_build_object(
                      'id', jf.id,
                      'field_id', jf.field_id,
                      'acres_to_treat', jf.acres_to_treat,
                      'sort_order', jf.sort_order,
                      'field', jsonb_build_object(
                        'id', f.id,
                        'field_name', CASE WHEN (is_admin() OR is_sales_rep() OR is_applicator())
                                           THEN f.field_name ELSE NULL END)
                    ) ORDER BY jf.sort_order
                  )
             FROM public.job_fields jf
             JOIN public.fields f ON f.id = jf.field_id
            WHERE jf.job_id = m.id
         ), '[]'::jsonb),
         -- per-location dispatch rows the CALLER can see, for client-side label aggregation
         '_dispatches',
         coalesce((
           SELECT jsonb_agg(jsonb_build_object('applicator_id', d.applicator_id, 'crew_id', d.crew_id))
             FROM public.job_location_dispatches d
            WHERE d.job_id = m.id
              AND d.dispatch_status = 'dispatched'
              AND (
                is_admin()
                OR is_sales_rep()
                OR (is_applicator() AND m.applicator_id = (select auth.uid()))
                OR d.applicator_id = (select auth.uid())
                OR (
                  d.crew_id IS NOT NULL
                  AND EXISTS (
                    SELECT 1 FROM public.ground_crew_members gcm
                      JOIN public.ground_crews gc ON gc.id = gcm.crew_id
                     WHERE gcm.crew_id = d.crew_id
                       AND gcm.profile_id = (select auth.uid())
                       AND gcm.is_active
                       AND gc.is_active
                  )
                )
              )
         ), '[]'::jsonb)
       )
    FROM matched m;
$$;


ALTER FUNCTION "public"."get_dispatch_board_jobs"("p_applicator_id" "uuid", "p_status" "text", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dispatch_stock_status"("p_job_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM require_admin_or_sales_rep();

  IF p_job_ids IS NULL OR array_length(p_job_ids, 1) IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  RETURN (
    WITH jobs_in AS (
      SELECT j.id
      FROM jobs j
      WHERE j.id = ANY(p_job_ids)
        AND j.deleted_at IS NULL
        AND j.status IN ('scheduled', 'in_progress')
    ),
    demand AS (
      SELECT ji.id AS job_id, jc.product_id,
             SUM(COALESCE(
               -- D2 (U11 follow-up): normalize FIRST — 'pt/ac'-style units NULL out of the converter; mirrors complete_job.
               field_app_priced_quantity(jc.quantity, normalize_rate_unit(jc.unit), p.inventory_unit, p.product_form),
               jc.quantity
             )) AS demand_qty
      FROM jobs_in ji
      JOIN job_chemicals jc ON jc.job_id = ji.id
      JOIN products p ON p.id = jc.product_id
      -- U4<<< a grower-supplied line demands nothing from our shed — exclude it
      -- from the dispatch stock light. (#102)
      WHERE jc.quantity > 0 AND jc.customer_supplied = false
      -- >>>U4
      GROUP BY ji.id, jc.product_id
    ),
    avail AS (
      SELECT i.product_id,
             SUM(i.quantity_available - i.quantity_prebooked) AS free_base,
             MAX(i.reorder_point) AS reorder_point
      FROM inventory i
      GROUP BY i.product_id
    ),
    total_holds AS (
      SELECT ih.product_id, SUM(ih.quantity) AS holds_qty
      FROM inventory_holds ih
      WHERE ih.is_active = true
        AND (ih.expires_at IS NULL OR ih.expires_at >= CURRENT_DATE)
      GROUP BY ih.product_id
    ),
    own_hold AS (
      SELECT ih.source_id AS job_id, ih.product_id, SUM(ih.quantity) AS own_qty
      FROM inventory_holds ih
      WHERE ih.hold_type = 'job'
        AND ih.is_active = true
        AND (ih.expires_at IS NULL OR ih.expires_at >= CURRENT_DATE)
        AND ih.source_id = ANY(p_job_ids)
      GROUP BY ih.source_id, ih.product_id
    )
    SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
    FROM (
      SELECT
        d.job_id,
        d.product_id,
        d.demand_qty,
        (a.product_id IS NOT NULL) AS has_inventory,
        (COALESCE(a.free_base, 0) - (COALESCE(th.holds_qty, 0) - COALESCE(oh.own_qty, 0)))
          AS free_excluding_own_hold,
        COALESCE(a.reorder_point, 0) AS reorder_point
      FROM demand d
      LEFT JOIN avail a        ON a.product_id  = d.product_id
      LEFT JOIN total_holds th ON th.product_id = d.product_id
      LEFT JOIN own_hold oh    ON oh.job_id = d.job_id AND oh.product_id = d.product_id
    ) r
  );
END;
$$;


ALTER FUNCTION "public"."get_dispatch_stock_status"("p_job_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dispatched_list"("p_applicator_id" "uuid" DEFAULT NULL::"uuid", "p_crew_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'dispatch_id',     d.id,
    'job_field_id',    d.job_field_id,
    'job_id',          d.job_id,
    'job_number',      j.job_number,
    'job_status',      j.status,
    -- U12 addition: the job's scheduled date, so the FieldView card shows it
    -- and can sort Today-first / group a Done section without an extra fetch.
    'job_date',        j.job_date,
    -- U12 addition (Codex R1 P1): the underlying fields.id, so the FieldView
    -- completion form can send per-field applied acres keyed by the REAL field id
    -- (job_field_id is the join-row id — application_record_fields.field_id
    -- references fields.id, so the client needs this to build 'field_acres').
    -- Gated to the same role set as field_name (RLS R2 M3): the only consumer
    -- (the completion form) requires is_applicator() anyway, and a dispatched
    -- non-applicator crew member shouldn't get a dereferenceable fields.id when
    -- field_name is deliberately withheld from them.
    'field_id',        CASE WHEN (is_admin() OR is_sales_rep() OR is_applicator())
                            THEN jf.field_id ELSE NULL END,
    'dispatch_status', d.dispatch_status,
    'dispatched_at',   d.dispatched_at,
    'assignee_kind',   CASE WHEN d.applicator_id IS NOT NULL THEN 'applicator' ELSE 'crew' END,
    'applicator_id',   d.applicator_id,
    'crew_id',         d.crew_id,
    -- assignee NAME resolved server-side. field_name gated to the fields_select roles
    -- (admin/sales_rep/applicator) so a dispatched crew member whose role is not
    -- applicator never receives a field name they couldn't read under RLS (null ->
    -- the client falls back to 'Field'). Customer name gated likewise.
    'assignee_name',   CASE WHEN d.applicator_id IS NOT NULL
                            THEN (SELECT p.full_name FROM profiles p WHERE p.id = d.applicator_id)
                            ELSE (SELECT g.name FROM ground_crews g WHERE g.id = d.crew_id) END,
    'field_name',      CASE WHEN (is_admin() OR is_sales_rep() OR is_applicator())
                            THEN (SELECT f.field_name FROM fields f WHERE f.id = jf.field_id)
                            ELSE NULL END,
    'customer_name',   CASE WHEN (
                              is_admin()
                              OR (is_sales_rep() AND c.assigned_sales_rep = (select auth.uid()))
                              OR (is_applicator() AND EXISTS (
                                    SELECT 1 FROM public.jobs j2
                                     WHERE j2.customer_id = c.id
                                       AND j2.applicator_id = (select auth.uid())
                                       AND j2.job_date >= (CURRENT_DATE - interval '7 days')))
                              OR EXISTS (
                                    SELECT 1 FROM public.jobs j3
                                     WHERE j3.customer_id = c.id
                                       AND public._is_dispatched_to_me(j3.id))
                            ) THEN c.farm_name ELSE NULL END,
    'location_acres',  jf.acres_to_treat,
    'job_applied_acres', j.applied_acres,
    'job_total_acres',   j.total_acres
  )
    FROM public.job_location_dispatches d
    JOIN public.jobs j        ON j.id = d.job_id AND j.deleted_at IS NULL
    JOIN public.job_fields jf ON jf.id = d.job_field_id
    JOIN public.customers c   ON c.id = j.customer_id
   WHERE (
       d.dispatch_status = 'dispatched'
       -- A1: also return RECENTLY-completed dispatch rows (the job-terminal trigger
       -- flips rows to 'completed' when the job completes) so a just-finished job
       -- moves to the FieldView "Done" section instead of vanishing. 7-day window
       -- bounds the tail; 'cancelled' rows stay EXCLUDED — an undispatched
       -- applicator must not keep seeing the job (undispatch_job_locations also
       -- writes 'cancelled').
       OR (d.dispatch_status = 'completed' AND d.updated_at >= now() - interval '7 days')
     )
     AND (p_applicator_id IS NULL OR d.applicator_id = p_applicator_id)
     AND (p_crew_id IS NULL OR d.crew_id = p_crew_id)
     -- VISIBILITY GATE — mirrors job_location_dispatches_select, with ONE deliberate
     -- A1 relaxation: the table policy's assignee/crew branches require
     -- dispatch_status='dispatched', but this gate intentionally does NOT — otherwise
     -- a per-location assignee's just-completed rows would never reach their Done
     -- section (the whole point of the 7-day completed tail). The rows are still
     -- bounded to the caller's OWN dispatches (or their active crew's) — data they
     -- could already read while the row was 'dispatched'. is_admin()/is_sales_rep()/
     -- is_applicator() each re-check profiles.is_active internally, BUT the bare
     -- `applicator_id = auth.uid()` and crew-member branches must ALSO re-check is_active
     -- — this is a SECURITY DEFINER read that bypasses RLS, so without the re-check a
     -- DEACTIVATED user with a still-valid token would keep seeing their dispatch rows
     -- (the #36 policy includes this active-profile guard for exactly this reason —
     -- Codex #37 P1).
     AND (
       is_admin()
       OR is_sales_rep()
       OR (is_applicator() AND j.applicator_id = (select auth.uid()))
       OR (
         d.applicator_id = (select auth.uid())
         AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = (select auth.uid()) AND p.is_active)
       )
       OR (
         d.crew_id IS NOT NULL
         AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = (select auth.uid()) AND p.is_active)
         AND EXISTS (
           SELECT 1 FROM public.ground_crew_members gcm
             JOIN public.ground_crews gc ON gc.id = gcm.crew_id
            WHERE gcm.crew_id = d.crew_id
              AND gcm.profile_id = (select auth.uid())
              AND gcm.is_active
              AND gc.is_active
         )
       )
     )
   -- d.id is the UNIQUE tiebreaker that makes this a TOTAL order — without it two
   -- same-job/same-transaction rows (equal dispatched_at) can be skipped/duplicated
   -- across a .range() page boundary (Codex #37 follow-up LOW).
   ORDER BY j.job_number, d.dispatched_at DESC, d.id;
$$;


ALTER FUNCTION "public"."get_dispatched_list"("p_applicator_id" "uuid", "p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_expiring_planned_holds"("p_days_ahead" integer DEFAULT 7, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN (
    SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
    FROM (
      SELECT
        ih.id AS hold_id,
        ih.product_id,
        p.product_name,
        ih.quantity,
        ih.expires_at,
        (ih.expires_at - INTERVAL '14 days')::date AS needed_by_date,
        ih.source_id AS quote_id,
        q.quote_number,
        c.farm_name AS customer_name,
        ih.customer_id
      FROM inventory_holds ih
      JOIN products p ON p.id = ih.product_id
      JOIN quotes q ON q.id = ih.source_id
      JOIN customers c ON c.id = ih.customer_id
      WHERE ih.is_active = true
        AND ih.hold_type = 'crop_program'
        AND (ih.expires_at - INTERVAL '14 days')::date <= CURRENT_DATE + p_days_ahead
        AND ih.expires_at > CURRENT_DATE  -- not yet expired
      ORDER BY (ih.expires_at - INTERVAL '14 days')::date ASC
    ) r
  );
END;
$$;


ALTER FUNCTION "public"."get_expiring_planned_holds"("p_days_ahead" integer, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_field_billing_splits_for_blend_ticket"("p_blend_ticket_id" "uuid") RETURNS TABLE("customer_id" "uuid", "split_pct" numeric, "is_primary" boolean, "field_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
    SELECT DISTINCT fbd.customer_id, fbd.split_pct, fbd.is_primary, fbd.field_id
    FROM blend_ticket_fields btf JOIN field_billing_defaults fbd ON fbd.field_id = btf.field_id
    WHERE btf.blend_ticket_id = p_blend_ticket_id
    UNION
    SELECT DISTINCT fbd.customer_id, fbd.split_pct, fbd.is_primary, fbd.field_id
    FROM blend_tickets bt JOIN field_billing_defaults fbd ON fbd.field_id = bt.field_id
    WHERE bt.id = p_blend_ticket_id AND bt.field_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM blend_ticket_fields btf2 WHERE btf2.blend_ticket_id = p_blend_ticket_id);
END;
$$;


ALTER FUNCTION "public"."get_field_billing_splits_for_blend_ticket"("p_blend_ticket_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_field_billing_splits_for_order"("p_order_id" "uuid") RETURNS TABLE("customer_id" "uuid", "split_pct" numeric, "is_primary" boolean, "field_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
    SELECT DISTINCT fbd.customer_id, fbd.split_pct, fbd.is_primary, fbd.field_id
    FROM orders o JOIN quotes q ON q.id = o.quote_id
    JOIN quote_sections qs ON qs.quote_id = q.id
    JOIN field_billing_defaults fbd ON fbd.field_id = qs.field_id
    WHERE o.id = p_order_id AND qs.field_id IS NOT NULL;
END;
$$;


ALTER FUNCTION "public"."get_field_billing_splits_for_order"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_field_dashboard"("p_field_id" "uuid", "p_season" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_season integer;
  v_field jsonb;
  v_summary jsonb;
  v_records jsonb;
  v_activity jsonb;
BEGIN
  v_season := COALESCE(p_season, current_season());

  SELECT jsonb_build_object(
    'id', f.id,
    'customer_id', f.customer_id,
    'field_name', f.field_name,
    'legal_description', f.legal_description,
    'county', f.county,
    'state', f.state,
    'total_acres', f.total_acres,
    'crop_type', f.crop_type,
    'soil_type', f.soil_type,
    'irrigation', f.irrigation,
    'fsa_farm_number', f.fsa_farm_number,
    'fsa_tract_number', f.fsa_tract_number,
    'fsa_field_number', f.fsa_field_number,
    'notes', f.notes,
    'is_active', f.is_active,
    'centroid_geojson', ST_AsGeoJSON(f.centroid)::text,
    'boundary_geojson', ST_AsGeoJSON(f.boundary)::text,
    'created_at', f.created_at,
    'updated_at', f.updated_at,
    'customer_name', c.farm_name,
    'billing_defaults', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', bd.id,
        'customer_id', bd.customer_id,
        'split_pct', bd.split_pct,
        'is_primary', bd.is_primary,
        'notes', bd.notes,
        'price_override_cents', bd.price_override_cents,
        'pricing_note', bd.pricing_note,
        'customer_name', bc.farm_name
      ) ORDER BY bd.is_primary DESC, bc.farm_name)
      FROM field_billing_defaults bd
      JOIN customers bc ON bc.id = bd.customer_id
      WHERE bd.field_id = f.id
    ), '[]'::jsonb)
  ) INTO v_field
  FROM fields f
  LEFT JOIN customers c ON c.id = f.customer_id
  WHERE f.id = p_field_id;

  IF v_field IS NULL THEN
    RAISE EXCEPTION 'Field not found: %', p_field_id;
  END IF;

  SELECT jsonb_build_object(
    'total_applications', count(*)::integer,
    'total_acres_treated', COALESCE(sum(ar.total_acres), 0),
    'distinct_products', COALESCE((
      SELECT count(DISTINCT elem->>'product_name')::integer
      FROM application_records ar2,
           jsonb_array_elements(ar2.product_data) elem
      WHERE ar2.field_id = p_field_id AND ar2.season = v_season
    ), 0),
    'season', v_season
  ) INTO v_summary
  FROM application_records ar
  WHERE ar.field_id = p_field_id AND ar.season = v_season;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', ar.id,
    'record_number', ar.record_number,
    'application_date', ar.application_date,
    'application_time', ar.application_time,
    'total_acres', ar.total_acres,
    'total_volume', ar.total_volume,
    'total_volume_unit', ar.total_volume_unit,
    'product_data', ar.product_data,
    'weather_conditions', ar.weather_conditions,
    'notes', ar.notes,
    'source_type', ar.source_type,
    'source_id', ar.source_id,
    'applicator_name', COALESCE(ar.applicator_name, p.full_name, 'Unknown'), -- D1: prefer the completion-time snapshot (N2-7 #106b); profiles is the legacy fallback.
    'vehicle_name', v.vehicle_name
  ) ORDER BY ar.application_date DESC, ar.application_time DESC), '[]'::jsonb)
  INTO v_records
  FROM application_records ar
  LEFT JOIN profiles p ON p.id = ar.applicator_id
  LEFT JOIN vehicles v ON v.id = ar.vehicle_id
  WHERE ar.field_id = p_field_id AND ar.season = v_season;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', af.id,
    'event_type', af.event_type,
    'description', af.description,
    'performed_by_name', COALESCE(p.full_name, 'System'),
    'created_at', af.created_at
  ) ORDER BY af.created_at DESC), '[]'::jsonb)
  INTO v_activity
  FROM (
    SELECT * FROM activity_feed
    WHERE related_entity_type = 'field' AND related_entity_id = p_field_id
    ORDER BY created_at DESC
    LIMIT 10
  ) af
  LEFT JOIN profiles p ON p.id = af.performed_by;

  RETURN jsonb_build_object(
    'field', v_field,
    'season_summary', v_summary,
    'application_records', v_records,
    'recent_activity', v_activity
  );
END;
$$;


ALTER FUNCTION "public"."get_field_dashboard"("p_field_id" "uuid", "p_season" integer) OWNER TO "postgres";


