CREATE OR REPLACE FUNCTION "public"."get_fields_with_geojson"("p_customer_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "customer_id" "uuid", "field_name" "text", "legal_description" "text", "county" "text", "state" "text", "total_acres" numeric, "fsa_farm_number" "text", "fsa_tract_number" "text", "fsa_field_number" "text", "crop_type" "text", "soil_type" "text", "irrigation" boolean, "notes" "text", "is_active" boolean, "centroid_geojson" "text", "boundary_geojson" "text", "customer_name" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "parent_field_id" "uuid", "child_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT f.id, f.customer_id, f.field_name, f.legal_description,
    f.county, f.state, f.total_acres,
    f.fsa_farm_number, f.fsa_tract_number, f.fsa_field_number,
    f.crop_type, f.soil_type, f.irrigation, f.notes, f.is_active,
    ST_AsGeoJSON(f.centroid)::text AS centroid_geojson,
    ST_AsGeoJSON(f.boundary)::text AS boundary_geojson,
    c.farm_name AS customer_name, f.created_at, f.updated_at,
    f.parent_field_id,
    (SELECT count(*) FROM fields ch WHERE ch.parent_field_id = f.id) AS child_count
  FROM fields f LEFT JOIN customers c ON c.id = f.customer_id
  WHERE (p_customer_id IS NULL OR f.customer_id = p_customer_id)
  ORDER BY f.field_name;
$$;


ALTER FUNCTION "public"."get_fields_with_geojson"("p_customer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_gross_sales_report"("p_start_date" "date", "p_end_date" "date", "p_group_by" "text" DEFAULT 'product'::"text") RETURNS TABLE("group_name" "text", "total_revenue" numeric, "total_cost" numeric, "gross_profit" numeric, "margin_pct" numeric, "units_sold" numeric, "order_count" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'Access denied: active admin or sales_rep role required';
  END IF;

  IF p_group_by = 'product' THEN
    RETURN QUERY
    SELECT
      oi.product_name,
      ROUND(SUM(oi.total_price)::numeric, 2),
      ROUND(SUM(oi.cost_per_unit * oi.total_units_needed)::numeric, 2),
      ROUND(SUM(oi.profit)::numeric, 2),
      CASE
        WHEN SUM(oi.total_price) > 0
          THEN ROUND((SUM(oi.profit) / SUM(oi.total_price) * 100)::numeric, 1)
        ELSE 0
      END,
      ROUND(SUM(oi.total_units_needed)::numeric, 2),
      COUNT(DISTINCT oi.order_id)
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    WHERE o.order_date >= p_start_date
      AND o.order_date <= p_end_date
      AND o.deleted_at IS NULL
      AND o.status NOT IN ('cancelled', 'voided')
    GROUP BY oi.product_name
    ORDER BY SUM(oi.total_price) DESC;
  ELSIF p_group_by = 'customer' THEN
    RETURN QUERY
    SELECT
      c.farm_name,
      ROUND(SUM(o.total_price)::numeric, 2),
      ROUND(SUM(o.total_price - o.total_profit)::numeric, 2),
      ROUND(SUM(o.total_profit)::numeric, 2),
      CASE
        WHEN SUM(o.total_price) > 0
          THEN ROUND((SUM(o.total_profit) / SUM(o.total_price) * 100)::numeric, 1)
        ELSE 0
      END,
      0::numeric,
      COUNT(o.id)
    FROM public.orders o
    LEFT JOIN public.customers c ON c.id = o.customer_id
    WHERE o.order_date >= p_start_date
      AND o.order_date <= p_end_date
      AND o.deleted_at IS NULL
      AND o.status NOT IN ('cancelled', 'voided')
    GROUP BY c.farm_name
    ORDER BY SUM(o.total_price) DESC;
  ELSE
    RETURN QUERY
    SELECT
      COALESCE(p.full_name, 'Unassigned'),
      ROUND(SUM(o.total_price)::numeric, 2),
      ROUND(SUM(o.total_price - o.total_profit)::numeric, 2),
      ROUND(SUM(o.total_profit)::numeric, 2),
      CASE
        WHEN SUM(o.total_price) > 0
          THEN ROUND((SUM(o.total_profit) / SUM(o.total_price) * 100)::numeric, 1)
        ELSE 0
      END,
      0::numeric,
      COUNT(o.id)
    FROM public.orders o
    LEFT JOIN public.profiles p ON p.id = o.salesman_id
    WHERE o.order_date >= p_start_date
      AND o.order_date <= p_end_date
      AND o.deleted_at IS NULL
      AND o.status NOT IN ('cancelled', 'voided')
    GROUP BY p.full_name
    ORDER BY SUM(o.total_price) DESC;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_gross_sales_report"("p_start_date" "date", "p_end_date" "date", "p_group_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_cost_report"() RETURNS TABLE("product_id" "uuid", "product_name" "text", "sku" "text", "category" "text", "vendor" "text", "quantity_available" numeric, "quantity_prebooked" numeric, "net_available" numeric, "unit_cost" numeric, "total_cost_value" numeric, "reorder_point" numeric, "below_reorder" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales_rep')) THEN
    RAISE EXCEPTION 'Access denied: admin or sales_rep role required';
  END IF;
  RETURN QUERY
  SELECT pr.id, pr.product_name, pr.sku, pr.category, pr.vendor,
    COALESCE(inv.quantity_available, 0), COALESCE(inv.quantity_prebooked, 0),
    COALESCE(inv.quantity_available, 0) - COALESCE(inv.quantity_prebooked, 0),
    COALESCE(pr.current_cost, 0),
    ROUND((COALESCE(inv.quantity_available, 0) * COALESCE(pr.current_cost, 0))::numeric, 2),
    COALESCE(inv.reorder_point, 0),
    COALESCE(inv.quantity_available, 0) < COALESCE(inv.reorder_point, 0)
  FROM products pr LEFT JOIN inventory inv ON inv.product_id = pr.id
  -- BEGIN DELTA inventory_cost_report_column_fix (2026-06-10): the live filter
  -- referenced a soft-delete timestamp column that does not exist on products
  -- (42703). The real products soft-delete mechanism is the is_active flag
  -- (Products.tsx deactivates; every picker filters is_active = true).
  WHERE pr.is_active = true
  -- END DELTA inventory_cost_report_column_fix
  ORDER BY pr.product_name;
END;
$$;


ALTER FUNCTION "public"."get_inventory_cost_report"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_forecast"("p_months_ahead" integer DEFAULT 6) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN (
    SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
    FROM (
      WITH demand_rows AS (
        -- crop_program holds bucketed by expiry − 14d (live behavior, unchanged)
        SELECT ih.product_id, ih.source_id, ih.customer_id, ih.quantity,
               'crop_program'::text AS kind,
               DATE_TRUNC('month', (ih.expires_at - INTERVAL '14 days'))::date AS needed_month
        FROM inventory_holds ih
        WHERE ih.is_active = true
          AND ih.hold_type = 'crop_program'
          AND ih.expires_at IS NOT NULL
          AND (ih.expires_at - INTERVAL '14 days') <= CURRENT_DATE + (p_months_ahead || ' months')::interval
        UNION ALL
        -- LAYER2: job holds bucketed by jobs.job_date (expires_at is NULL for job holds)
        SELECT ih.product_id, ih.source_id, ih.customer_id, ih.quantity,
               'job'::text AS kind,
               DATE_TRUNC('month', j.job_date)::date AS needed_month
        FROM inventory_holds ih
        JOIN jobs j ON j.id = ih.source_id
        WHERE ih.is_active = true
          AND ih.hold_type = 'job'
          AND j.deleted_at IS NULL
          AND j.job_date IS NOT NULL
          AND j.job_date <= (CURRENT_DATE + (p_months_ahead || ' months')::interval)::date
      )
      SELECT
        p.id AS product_id,
        p.product_name,
        p.sku,
        dr.needed_month,
        SUM(dr.quantity) AS planned_demand,
        COALESCE(SUM(dr.quantity) FILTER (WHERE dr.kind = 'job'), 0) AS job_demand,
        -- Codex A+B P2 #5: wrap the scalar subquery in COALESCE so a NO-ROW result
        -- (product with a job hold but no Main Warehouse inventory row) yields 0, not
        -- NULL — the inner COALESCE only guards a NULL column, not a missing row, and
        -- the frontend calls .toLocaleString() on these (would crash on null).
        COALESCE((SELECT i.quantity_available FROM inventory i WHERE i.product_id = p.id AND i.location = 'Main Warehouse' LIMIT 1), 0) AS current_available,
        COALESCE((SELECT i.quantity_prebooked FROM inventory i WHERE i.product_id = p.id AND i.location = 'Main Warehouse' LIMIT 1), 0) AS prebooked,
        (SELECT COALESCE(SUM(poi.quantity_ordered - poi.quantity_received), 0)
         FROM purchase_order_items poi
         JOIN purchase_orders po ON po.id = poi.purchase_order_id
         WHERE poi.product_id = p.id AND po.status IN ('submitted', 'partially_received')
        ) AS on_order,
        COUNT(DISTINCT dr.source_id) FILTER (WHERE dr.kind = 'crop_program') AS quote_count,
        COUNT(DISTINCT dr.customer_id) AS customer_count
      FROM demand_rows dr
      JOIN products p ON p.id = dr.product_id
      GROUP BY p.id, p.product_name, p.sku, dr.needed_month
      ORDER BY dr.needed_month, p.product_name
    ) r
  );
END;
$$;


ALTER FUNCTION "public"."get_inventory_forecast"("p_months_ahead" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_position"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_season_start date;
BEGIN
  PERFORM require_admin_or_sales_rep();

  IF EXTRACT(MONTH FROM CURRENT_DATE) >= 10 THEN
    v_season_start := DATE_TRUNC('year', CURRENT_DATE)::date + INTERVAL '9 months';
  ELSE
    v_season_start := (DATE_TRUNC('year', CURRENT_DATE) - INTERVAL '1 year')::date + INTERVAL '9 months';
  END IF;

  RETURN (
    WITH on_order AS (
      SELECT poi.product_id, SUM(GREATEST(poi.quantity_ordered - COALESCE(poi.quantity_received, 0), 0)) AS qty
      FROM purchase_order_items poi
      JOIN purchase_orders po ON po.id = poi.purchase_order_id
      WHERE po.status IN ('submitted', 'partially_received')
      GROUP BY poi.product_id
    ),
    holds AS (
      SELECT ih.product_id,
             SUM(ih.quantity) AS qty,
             -- LAYER2<<< job-type subset broken out as its own column (§4B.2 #1)
             SUM(ih.quantity) FILTER (WHERE ih.hold_type = 'job') AS job_qty
             -- >>>LAYER2
      FROM inventory_holds ih
      WHERE ih.is_active = true
        AND (ih.expires_at IS NULL OR ih.expires_at >= CURRENT_DATE)
      GROUP BY ih.product_id
    ),
    planned_quotes AS (
      -- LAYER2<<< quantity-aware dedup (§4B.2 #2): unreserved remainder per booking line.
      -- Codex A+B round-2 P2: AGGREGATE the booking per (quote, product) FIRST, THEN
      -- subtract the product-level hold/draws ONCE. Subtracting them inside a per-line
      -- SUM over-deducts when a product appears on multiple quote lines (two 50-unit
      -- lines with a 60-unit job draw and no hold would report 0 instead of 40 unreserved).
      SELECT pq.product_id, SUM(pq.remainder) AS qty
      FROM (
        SELECT b.quote_id, b.product_id,
               GREATEST(
                 b.booked
                   - COALESCE(lh.linked_hold, 0)
                   - COALESCE(od.order_drawn, 0)
                   - COALESCE(jd.job_drawn, 0),
                 0) AS remainder
        FROM (
          SELECT qi.quote_id, qi.product_id, SUM(COALESCE(qi.total_units_needed, 0)) AS booked
          FROM quote_items qi
          JOIN quotes q ON q.id = qi.quote_id
          WHERE q.is_planned = true AND q.status IN ('draft', 'sent', 'revised')
          GROUP BY qi.quote_id, qi.product_id
        ) b
        LEFT JOIN LATERAL (
          SELECT COALESCE(SUM(ih.quantity), 0) AS linked_hold
          FROM inventory_holds ih
          WHERE ih.source_id = b.quote_id
            AND ih.product_id = b.product_id
            AND ih.is_active = true
            AND (ih.expires_at IS NULL OR ih.expires_at >= CURRENT_DATE)
        ) lh ON true
        LEFT JOIN LATERAL (
          SELECT COALESCE(SUM(qpd.quantity_drawn), 0) AS order_drawn
          FROM quote_product_draws qpd
          WHERE qpd.quote_id = b.quote_id
            AND qpd.product_id = b.product_id
        ) od ON true
        LEFT JOIN LATERAL (
          SELECT COALESCE(SUM(jpd.quantity_drawn), 0) AS job_drawn
          FROM job_product_draws jpd
          WHERE jpd.quote_id = b.quote_id
            AND jpd.product_id = b.product_id
        ) jd ON true
      ) pq
      GROUP BY pq.product_id
      -- >>>LAYER2
    ),
    order_voided_products AS (
      -- void_order records one product-level reversal for the entire order and
      -- intentionally has no delivery_id. Pair that row back to all delivery
      -- events for the same order/product so its later ledger timestamp cannot
      -- move old delivered volume across season boundaries.
      SELECT DISTINCT it.order_id, it.product_id
      FROM inventory_transactions it
      WHERE it.transaction_type = 'void_delivery_reversal'
        AND it.delivery_id IS NULL
        AND it.order_id IS NOT NULL
    ),
    delivered_ytd AS (
      SELECT it.product_id,
             GREATEST(SUM(
               CASE
                 WHEN it.transaction_type = 'delivered' THEN ABS(it.quantity)
                 WHEN it.transaction_type IN ('cancelled_delivery_reversal', 'void_delivery_reversal')
                   THEN -ABS(it.quantity)
                 ELSE 0
               END
              ), 0) AS qty
      FROM inventory_transactions it
      JOIN deliveries d ON d.id = it.delivery_id
      LEFT JOIN order_voided_products ovp
        ON ovp.order_id = it.order_id
       AND ovp.product_id = it.product_id
      WHERE it.transaction_type IN ('delivered', 'cancelled_delivery_reversal', 'void_delivery_reversal')
        -- Delivery-specific reversals retain delivery_id, so they use the
        -- original delivery business date. Order-level voids are excluded by
        -- the paired order/product key above instead of their reversal date.
        AND (COALESCE(d.completed_at, it.created_at) AT TIME ZONE 'America/Chicago')::date >= v_season_start
        AND ovp.order_id IS NULL
      GROUP BY it.product_id
    ),
    base AS (
      SELECT
        p.id AS product_id, p.product_name, p.inventory_unit,
        p.container_size, p.container_type, p.vendor, p.current_cost,
        i.id AS inventory_id, i.location, i.unit_size,
        COALESCE(i.quantity_available, 0) AS quantity_available,
        COALESCE(i.quantity_prebooked, 0) AS quantity_prebooked,
        COALESCE(i.reorder_point, 0) AS reorder_point,
        COALESCE(i.min_stock_level, 0) AS min_stock_level
      FROM products p
      LEFT JOIN inventory i ON i.product_id = p.id
      WHERE p.is_active = true
    )
    SELECT COALESCE(jsonb_agg(row_to_json(r) ORDER BY r.product_name), '[]'::jsonb)
    FROM (
      SELECT
        b.inventory_id, b.product_id, b.product_name, b.inventory_unit,
        b.container_size, b.container_type, b.vendor, b.current_cost,
        b.location, b.unit_size,
        b.quantity_available, b.quantity_prebooked,
        COALESCE(oo.qty, 0) AS quantity_on_order,
        COALESCE(h.qty, 0)  AS holds_qty,
        COALESCE(h.job_qty, 0) AS job_holds_qty,   -- LAYER2: new column
        COALESCE(pq.qty, 0) AS planned_qty,
        COALESCE(dy.qty, 0) AS delivered_ytd,
        (b.quantity_available - b.quantity_prebooked + COALESCE(oo.qty, 0)) AS net_position,
        b.reorder_point, b.min_stock_level,
        -- U18 #90: negative on-hand is always a stock problem, reorder_point set or not.
        ((b.reorder_point > 0 AND b.quantity_available <= b.reorder_point) OR b.quantity_available < 0) AS is_low_stock
      FROM base b
      LEFT JOIN on_order       oo ON oo.product_id = b.product_id
      LEFT JOIN holds          h  ON h.product_id  = b.product_id
      LEFT JOIN planned_quotes pq ON pq.product_id = b.product_id
      LEFT JOIN delivered_ytd  dy ON dy.product_id = b.product_id
      WHERE b.inventory_id IS NOT NULL OR COALESCE(oo.qty, 0) > 0
    ) r
  );
END;
$$;


ALTER FUNCTION "public"."get_inventory_position"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_inventory_position"() IS 'Wave B.3. Returns one row per (product, location) for active products with quantity_available, quantity_prebooked, quantity_on_order, holds_qty, planned_qty, delivered_ytd (season-to-date), net_position (= available - prebooked + on_order), reorder_point, min_stock_level, is_low_stock, plus product metadata (name, unit, container, vendor, current_cost). Read-only; replaces 4 separate fetches in InventoryPage.';



CREATE OR REPLACE FUNCTION "public"."get_job_billed_customers"("p_job_id" "uuid") RETURNS TABLE("customer_id" "uuid", "farm_name" "text", "account_number" "text", "is_primary" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_primary_customer_id uuid;
  v_applicator_id uuid;
BEGIN
  -- Load the job's gate columns (definer-privileged read).
  SELECT j.customer_id, j.applicator_id
    INTO v_primary_customer_id, v_applicator_id
  FROM jobs j
  WHERE j.id = p_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = 'no_data_found';
  END IF;

  -- SELF-GATE: mirror the FULL live jobs visibility — BOTH SELECT policies OR'd:
  --   jobs_select:                     is_admin OR is_sales_rep OR (is_applicator AND applicator_id = auth.uid())
  --   jobs_select_location_dispatchee: _is_dispatched_to_me(job_id)  (per-location / crew dispatch)
  -- Without the dispatch leg a per-location-dispatched applicator (who CAN see the
  -- job) is refused here and their compliance PDF is blocked — the exact bug FIX 5
  -- closes. The dispatch helper is SECURITY DEFINER + re-checks active profile / active
  -- crew, so it never widens visibility beyond the live policy. Reject a caller who
  -- can't view the job (do NOT return a partial set — compliance is complete-or-refused).
  IF NOT (
    is_admin()
    OR is_sales_rep()
    OR (is_applicator() AND v_applicator_id = (SELECT auth.uid()))
    OR _is_dispatched_to_me(p_job_id)
  ) THEN
    RAISE EXCEPTION 'Not authorized to view this job''s billed customers'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  WITH job_field_ids AS (
    -- Every field on the job (field_id is the unit of billing precedence).
    SELECT DISTINCT jf.field_id
    FROM job_fields jf
    WHERE jf.job_id = p_job_id AND jf.field_id IS NOT NULL
  ),
  fields_with_share AS (
    -- Only shares whose field is ACTUALLY on the job (guard against an orphan
    -- job_field_shares row for a field no longer on the job).
    SELECT DISTINCT jfs.field_id
    FROM job_field_shares jfs
    JOIN job_field_ids jfi ON jfi.field_id = jfs.field_id
    WHERE jfs.job_id = p_job_id
  ),
  resolved AS (
    -- 1. Saved per-field shares (explicit split) — only for fields on the job, so an
    --    orphan share (field removed from the job) never adds a customer (Codex LOW).
    SELECT jfs.customer_id
    FROM job_field_shares jfs
    JOIN job_field_ids jfi ON jfi.field_id = jfs.field_id
    WHERE jfs.job_id = p_job_id AND jfs.customer_id IS NOT NULL

    UNION ALL

    -- 2. field_billing_defaults for fields WITHOUT a saved share.
    SELECT fbd.customer_id
    FROM job_field_ids jfi
    JOIN field_billing_defaults fbd ON fbd.field_id = jfi.field_id
    WHERE jfi.field_id NOT IN (SELECT field_id FROM fields_with_share)
      AND fbd.customer_id IS NOT NULL

    UNION ALL

    -- 3. The job's PRIMARY customer for fields that have neither a saved share
    --    nor a billing default.
    SELECT v_primary_customer_id
    FROM job_field_ids jfi
    WHERE jfi.field_id NOT IN (SELECT field_id FROM fields_with_share)
      AND NOT EXISTS (
        SELECT 1 FROM field_billing_defaults fbd WHERE fbd.field_id = jfi.field_id
      )
      AND v_primary_customer_id IS NOT NULL

    UNION ALL

    -- 4. SAFETY FALLBACK: a job with NO fields at all still has a primary customer
    --    — surface it so the resolver never returns an empty set for a real job
    --    (mirrors the frontend "if custMap empty → add primary" fallback).
    SELECT v_primary_customer_id
    WHERE NOT EXISTS (SELECT 1 FROM job_field_ids)
      AND v_primary_customer_id IS NOT NULL
  )
  -- LEFT JOIN (not INNER) so a billed customer_id that does NOT resolve to a
  -- customers row (e.g. a since-removed customer) still surfaces — as a row with a
  -- NULL farm_name. The frontend resolver treats a NULL/blank name as an INCOMPLETE
  -- resolution and ABORTS the compliance PDF, rather than silently omitting that
  -- billed party.
  SELECT
    d.customer_id,
    c.farm_name,
    c.account_number,
    (d.customer_id = v_primary_customer_id) AS is_primary
  FROM (SELECT DISTINCT r.customer_id FROM resolved r) d
  LEFT JOIN customers c ON c.id = d.customer_id
  ORDER BY (d.customer_id = v_primary_customer_id) DESC, c.farm_name NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."get_job_billed_customers"("p_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_job_billed_customers"("p_job_id" "uuid") IS 'Field-app #11/#10 compliance: read-only resolver for a job''s billed customers (job_field_shares -> field_billing_defaults -> primary customer_id), bypassing per-customer RLS so an applicator''s compliance PDF includes co-billed customers. Self-gates on the FULL live jobs visibility (jobs_select applicator predicate OR _is_dispatched_to_me, Wave 2b FIX 5); RAISES if the caller cannot view the job.';



CREATE OR REPLACE FUNCTION "public"."get_job_fields_with_geojson"("p_job_id" "uuid") RETURNS TABLE("id" "uuid", "customer_id" "uuid", "field_name" "text", "total_acres" numeric, "measured_acres" numeric, "override_acres" numeric, "centroid_geojson" "text", "boundary_geojson" "text", "sort_order" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    f.id, f.customer_id, f.field_name, f.total_acres,
    -- Two-acre model (migration 20260623120000): the map's billable-acre label uses
    -- override ?? measured ?? total. Carry both so the label isn't stale legacy acres.
    f.measured_acres, f.override_acres,
    ST_AsGeoJSON(f.centroid)::text  AS centroid_geojson,
    -- Codex post-fix P2: fields.boundary_geom is the CANONICAL full-field MultiPolygon
    -- (set by set_field_boundary; multi-part fields union all field_polygons parts into
    -- it). The legacy geography(POLYGON) `boundary` holds only the first/single part, so
    -- using it would silently drop the other parts of a multi-part field on the map.
    -- Prefer boundary_geom; fall back to the legacy boundary only when geom is absent.
    ST_AsGeoJSON(COALESCE(f.boundary_geom, f.boundary::geometry))::text AS boundary_geojson,
    jf.sort_order
  FROM public.job_fields jf
  JOIN public.fields f ON f.id = jf.field_id
  WHERE jf.job_id = p_job_id
    -- Same visibility gate as the jobs SELECT policies: admin / sales_rep / the
    -- assigned applicator (jobs_select) OR a location-dispatched crew member
    -- (jobs_select_location_dispatchee).
    AND EXISTS (
      SELECT 1 FROM public.jobs j
      WHERE j.id = p_job_id
        AND (
          is_admin()
          OR is_sales_rep()
          OR (is_applicator() AND j.applicator_id = (SELECT auth.uid()))
          OR _is_dispatched_to_me(j.id)
        )
    )
  ORDER BY jf.sort_order NULLS LAST, f.field_name;
$$;


ALTER FUNCTION "public"."get_job_fields_with_geojson"("p_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_job_fields_with_geojson"("p_job_id" "uuid") IS 'Field-app parity #16: returns ONLY the fields selected on a job (job_fields), gated by the same visibility predicate as jobs_select. Server-side scoping so the per-job map never over-fetches a customer''s other field geometry. Boundary geojson comes from the canonical full-field boundary_geom (multi-part safe), falling back to the legacy single boundary. (Codex #16 P2.)';



CREATE OR REPLACE FUNCTION "public"."get_job_inventory_shortfalls"("p_days_ahead" integer DEFAULT 7) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM require_admin_or_sales_rep();

  RETURN (
    WITH win_jobs AS (
      SELECT j.id, j.job_number, j.quote_id
      FROM jobs j
      WHERE j.status IN ('scheduled', 'in_progress')
        AND j.deleted_at IS NULL
        AND j.job_date >= CURRENT_DATE
        AND j.job_date <= (CURRENT_DATE + (p_days_ahead || ' days')::interval)::date
    ),
    demand AS (
      -- Codex A+B P2 #3: needed = FULL job demand when the job HAS its own 'job' hold
      -- (that hold is excluded from active_holds below, so free isn't reduced by it);
      -- the leftover quote crop_program hold covers the UN-drawn booking, NOT this job,
      -- so subtracting it too would double-discount and hide real shortfalls (e.g.
      -- 100-booked quote, 60-unit job -> 40 crop hold; with 50 free the true shortfall
      -- is 60 - (50-40) = 50).
      -- Codex round-3 P2: BUT a PRE-EXISTING scheduled/in-progress job (one that
      -- existed before Layer 2 — A4 does no backfill, §6.6) has no own 'job' hold yet,
      -- so nothing is excluded from active_holds; falling through to full demand while
      -- the crop hold is still subtracted from free would report a PHANTOM shortfall.
      -- So: cover = 0 when the job has its own hold; otherwise fall back to the parent
      -- quote's crop coverage (the Layer-1 behavior) until the job is reserved.
      SELECT jc.product_id,
             SUM(GREATEST(cq.demand_qty - cov.covered, 0)) AS needed_qty,
             COUNT(DISTINCT wj.id) FILTER (WHERE cq.demand_qty - cov.covered > 0) AS job_count,
             ARRAY_AGG(DISTINCT wj.job_number ORDER BY wj.job_number)
               FILTER (WHERE cq.demand_qty - cov.covered > 0) AS job_numbers
      FROM win_jobs wj
      JOIN job_chemicals jc ON jc.job_id = wj.id
      JOIN products p ON p.id = jc.product_id
      CROSS JOIN LATERAL (
        SELECT COALESCE(
                 -- D2 (U11 follow-up): normalize FIRST — 'pt/ac'-style units NULL out of the converter; mirrors complete_job.
                 field_app_priced_quantity(jc.quantity, normalize_rate_unit(jc.unit), p.inventory_unit, p.product_form),
                 jc.quantity
               ) AS demand_qty
      ) cq
      CROSS JOIN LATERAL (
        SELECT CASE
                 WHEN EXISTS (
                   SELECT 1 FROM inventory_holds ih
                   WHERE ih.source_id = wj.id AND ih.hold_type = 'job'
                     AND ih.product_id = jc.product_id AND ih.is_active = true
                     AND (ih.expires_at IS NULL OR ih.expires_at >= CURRENT_DATE)
                 ) THEN 0
                 ELSE COALESCE((
                   SELECT SUM(ih.quantity) FROM inventory_holds ih
                   WHERE ih.source_id = wj.quote_id
                     AND ih.product_id = jc.product_id AND ih.is_active = true
                     AND (ih.expires_at IS NULL OR ih.expires_at >= CURRENT_DATE)
                 ), 0)
               END AS covered
      ) cov
      -- U4<<< a grower-supplied line demands nothing from our shed — exclude it
      -- from the planning-window shortfall so it never shows a phantom shortage. (#102)
      WHERE jc.quantity > 0 AND jc.customer_supplied = false
      -- >>>U4
      GROUP BY jc.product_id
    ),
    avail AS (
      SELECT i.product_id,
             COALESCE(SUM(i.quantity_available - i.quantity_prebooked), 0) AS avail_less_prebooked
      FROM inventory i
      GROUP BY i.product_id
    ),
    active_holds AS (
      SELECT ih.product_id, SUM(ih.quantity) AS holds_qty
      FROM inventory_holds ih
      WHERE ih.is_active = true
        AND (ih.expires_at IS NULL OR ih.expires_at >= CURRENT_DATE)
        -- LAYER2<<< don't subtract the window jobs' OWN job holds from free —
        -- their demand is already sized above, so counting their reservation
        -- here too would report a phantom shortfall (§4B.1).
        AND NOT (ih.hold_type = 'job' AND ih.source_id IN (SELECT id FROM win_jobs))
        -- >>>LAYER2
      GROUP BY ih.product_id
    )
    SELECT COALESCE(jsonb_agg(row_to_json(r) ORDER BY r.shortfall_qty DESC), '[]'::jsonb)
    FROM (
      SELECT
        d.product_id,
        p.product_name,
        p.inventory_unit,
        d.needed_qty,
        (COALESCE(a.avail_less_prebooked, 0) - COALESCE(ah.holds_qty, 0)) AS available_free,
        (d.needed_qty - (COALESCE(a.avail_less_prebooked, 0) - COALESCE(ah.holds_qty, 0))) AS shortfall_qty,
        d.job_count,
        d.job_numbers
      FROM demand d
      JOIN products p ON p.id = d.product_id
      LEFT JOIN avail a          ON a.product_id  = d.product_id
      LEFT JOIN active_holds ah  ON ah.product_id = d.product_id
      WHERE d.needed_qty > 0
        AND d.needed_qty > (COALESCE(a.avail_less_prebooked, 0) - COALESCE(ah.holds_qty, 0))
    ) r
  );
END;
$$;


ALTER FUNCTION "public"."get_job_inventory_shortfalls"("p_days_ahead" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_proof_data"("p_job_id" "uuid", "p_customer_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_actor               uuid;
  v_role                text;
  v_primary_customer_id uuid;
  v_job                 record;
  v_season              int;
  v_fields              jsonb := '[]'::jsonb;
  v_products            jsonb := '[]'::jsonb;
  v_weather             jsonb := NULL;
  v_result              jsonb;
BEGIN
  -- Role gate (office sending tool — admin/sales_rep). First executable statement.
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT role INTO v_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales_rep required';
  END IF;

  -- Job header + applicator display name. Validates the job exists.
  SELECT j.id, j.job_number, j.status, j.job_date, j.season, j.customer_id, j.applicator_id,
         pr.full_name AS applicator_name
  INTO v_job
  FROM jobs j
  LEFT JOIN profiles pr ON pr.id = j.applicator_id
  WHERE j.id = p_job_id AND j.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'JOB_NOT_FOUND: job % does not exist', p_job_id;
  END IF;
  v_season := v_job.season;
  v_primary_customer_id := v_job.customer_id;

  -- ── Resolve each job field to its OWNING customer (same precedence as the recipient
  -- resolver / get_job_billed_customers): explicit job_field_shares, else
  -- field_billing_defaults, else the job's primary customer. One row per (field) with the
  -- resolved customer_id, so we can filter to p_customer_id when scoping a recipient's proof.
  -- ── Per-field APPLIED acres come from job_applied_record_fields (the real sprayed acres,
  -- the §2/§5 source) joined via job_applied_records; fall back to the field's effective
  -- acres (override > measured > total) only when no applied record treated that field.
  SELECT COALESCE(jsonb_agg(fr ORDER BY (fr->>'sort_order')::int NULLS LAST, fr->>'field_name'), '[]'::jsonb)
  INTO v_fields
  FROM (
    SELECT jsonb_build_object(
      'field_id',         f.id,
      'field_name',       f.field_name,
      'county',           f.county,
      'state',            f.state,
      'acres',            CASE
                            WHEN applied.applied_acres IS NOT NULL
                              THEN GREATEST(applied.applied_acres, 0)
                            ELSE GREATEST(COALESCE(f.override_acres, f.measured_acres, f.total_acres, 0), 0)
                          END,
      'acres_source',     CASE
                            WHEN applied.applied_acres IS NOT NULL THEN 'applied'
                            WHEN f.override_acres IS NOT NULL THEN 'override'
                            WHEN f.measured_acres IS NOT NULL THEN 'measured'
                            WHEN f.total_acres   IS NOT NULL THEN 'total'
                            ELSE NULL END,
      'centroid_geojson', ST_AsGeoJSON(f.centroid)::text,
      'boundary_geojson', ST_AsGeoJSON(COALESCE(f.boundary_geom, f.boundary::geometry))::text,
      'harvest_date',     (
                            SELECT to_char(fch.harvest_date, 'YYYY-MM-DD')
                            FROM field_crop_history fch
                            WHERE fch.field_id = f.id
                              AND (v_season IS NULL OR fch.season = v_season)
                              AND fch.harvest_date IS NOT NULL
                            ORDER BY fch.season DESC NULLS LAST, fch.harvest_date DESC
                            LIMIT 1
                          ),
      'sort_order',       jf.sort_order
    ) AS fr
    FROM job_fields jf
    JOIN fields f ON f.id = jf.field_id
    -- the real sprayed acres for this field on this job (NULL when none recorded)
    LEFT JOIN LATERAL (
      SELECT SUM(rf.applied_acres) AS applied_acres
      FROM job_applied_records r
      JOIN job_applied_record_fields rf
        ON rf.application_record_id = r.id AND rf.field_id = f.id
      WHERE r.job_id = p_job_id AND rf.applied_acres IS NOT NULL
      HAVING SUM(rf.applied_acres) > 0
    ) applied ON true
    WHERE jf.job_id = p_job_id
      -- Scope to a recipient (P1 leak fix), but a field SHARED across MULTIPLE customers must
      -- appear for EACH of its billed customers (not collapse to one owner). Include field f for
      -- p_customer_id when: whole-job preview (NULL); OR p_customer_id holds an explicit share of f;
      -- OR f has NO explicit shares and p_customer_id is f's billing-default; OR f has neither and
      -- p_customer_id is the job's primary customer. A customer with NO claim to f never sees it.
      AND (
        p_customer_id IS NULL
        OR EXISTS (
             SELECT 1 FROM job_field_shares jfs
             WHERE jfs.job_id = p_job_id AND jfs.field_id = f.id AND jfs.customer_id = p_customer_id
           )
        OR (
          NOT EXISTS (SELECT 1 FROM job_field_shares jfs2 WHERE jfs2.job_id = p_job_id AND jfs2.field_id = f.id)
          AND (
            EXISTS (SELECT 1 FROM field_billing_defaults fbd WHERE fbd.field_id = f.id AND fbd.customer_id = p_customer_id)
            OR (
              NOT EXISTS (SELECT 1 FROM field_billing_defaults fbd2 WHERE fbd2.field_id = f.id)
              AND p_customer_id = v_primary_customer_id
            )
          )
        )
      )
  ) s;

  -- ── Products applied (job-wide — the same tank mix went on every field). REI/PHI prefer
  -- the job line's captured value, else the product master. Unchanged by the scoping fix.
  SELECT COALESCE(jsonb_agg(pr ORDER BY (pr->>'sort_order')::int NULLS LAST, pr->>'product_name'), '[]'::jsonb)
  INTO v_products
  FROM (
    SELECT jsonb_build_object(
      'product_name',     p.product_name,
      'rate_per_acre',    jc.rate_per_acre,
      'rate_unit',        jc.rate_unit,
      'rei_hours',        COALESCE(jc.rei_hours, p.rei_hours),
      'phi_days',         COALESCE(jc.phi_days, p.phi_days),
      'signal_word',      p.signal_word,
      'epa_registration', p.epa_registration,
      'sort_order',       jc.sort_order
    ) AS pr
    FROM job_chemicals jc
    JOIN products p ON p.id = jc.product_id
    WHERE jc.job_id = p_job_id
  ) s;

  -- ── Weather at application (job-wide). Graceful NULL when not captured. Unchanged.
  SELECT jsonb_build_object(
           'temperature',    ja.temperature,
           'wind_speed',     ja.wind_speed,
           'wind_direction', ja.wind_direction,
           'humidity',       ja.humidity,
           'actual_start',   ja.actual_start_time,
           'actual_end',     ja.actual_end_time
         )
  INTO v_weather
  FROM job_applied_info ja
  WHERE ja.job_id = p_job_id
    AND (ja.temperature IS NOT NULL
         OR ja.wind_speed IS NOT NULL
         OR ja.wind_direction IS NOT NULL
         OR ja.humidity IS NOT NULL)
  ORDER BY ja.updated_at DESC NULLS LAST, ja.created_at DESC
  LIMIT 1;

  v_result := jsonb_build_object(
    'job_id',           v_job.id,
    'job_number',       v_job.job_number,
    'status',           v_job.status,
    'application_date', to_char(v_job.job_date, 'YYYY-MM-DD'),
    'applicator_name',  v_job.applicator_name,
    'scoped_customer_id', p_customer_id,   -- echoes the scope (NULL = whole job)
    'fields',           v_fields,
    'products',         v_products,
    'weather',          v_weather
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_job_proof_data"("p_job_id" "uuid", "p_customer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_job_proof_data"("p_job_id" "uuid", "p_customer_id" "uuid") IS 'Beyond-parity §6 (per-customer + applied acres): read-only gatherer for the "your field was sprayed" proof. p_customer_id scopes the returned fields to ONE billed customer (job_field_shares -> field_billing_defaults -> primary precedence) so a split-billed recipient never sees another customer''s field; NULL = whole job (office preview). Per-field acres = job_applied_record_fields.applied_acres (real sprayed acres) when present, else the field''s effective acres. STABLE; SECURITY DEFINER; admin/sales_rep only.';



CREATE OR REPLACE FUNCTION "public"."get_jobs_billed_customers"("p_job_ids" "uuid"[]) RETURNS TABLE("job_id" "uuid", "customer_id" "uuid", "farm_name" "text", "account_number" "text", "is_primary" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_job_ids IS NULL OR array_length(p_job_ids, 1) IS NULL THEN
    RETURN;  -- empty input -> empty set
  END IF;

  RETURN QUERY
  WITH input_jobs AS (
    SELECT DISTINCT v.job_id FROM unnest(p_job_ids) AS v(job_id)
  ),
  -- VISIBLE jobs only: self-gate per job on the FULL live jobs visibility — BOTH
  -- SELECT policies OR'd together, so we never under-resolve a job the caller can
  -- actually see:
  --   jobs_select:                     is_admin OR is_sales_rep OR (is_applicator AND applicator_id = auth.uid())
  --   jobs_select_location_dispatchee: _is_dispatched_to_me(job_id)  (per-location / crew dispatch)
  -- Without the dispatch leg, a per-location-dispatched applicator's /jobs row would
  -- fall back to primary-only and HIDE co-billed split owners — the exact bug FIX 2
  -- closes (Codex). A job the caller can't view is SKIPPED (fail-soft), never raised on.
  visible_jobs AS (
    SELECT j.id AS job_id, j.customer_id AS primary_customer_id
    FROM jobs j
    JOIN input_jobs ij ON ij.job_id = j.id
    WHERE is_admin()
       OR is_sales_rep()
       OR (is_applicator() AND j.applicator_id = (SELECT auth.uid()))
       OR _is_dispatched_to_me(j.id)
  ),
  job_field_ids AS (
    -- Every field on each visible job (the unit of billing precedence).
    SELECT vj.job_id, jf.field_id
    FROM visible_jobs vj
    JOIN job_fields jf ON jf.job_id = vj.job_id AND jf.field_id IS NOT NULL
  ),
  fields_with_share AS (
    -- Shares whose field is ACTUALLY on the job (ignore an orphan share row).
    SELECT DISTINCT jfs.job_id, jfs.field_id
    FROM job_field_shares jfs
    JOIN job_field_ids jfi ON jfi.job_id = jfs.job_id AND jfi.field_id = jfs.field_id
  ),
  resolved AS (
    -- 1. Saved per-field shares (explicit split) — only for fields on the job.
    SELECT jfs.job_id, jfs.customer_id
    FROM job_field_shares jfs
    JOIN job_field_ids jfi ON jfi.job_id = jfs.job_id AND jfi.field_id = jfs.field_id
    WHERE jfs.customer_id IS NOT NULL

    UNION ALL

    -- 2. field_billing_defaults for fields WITHOUT a saved share.
    SELECT jfi.job_id, fbd.customer_id
    FROM job_field_ids jfi
    JOIN field_billing_defaults fbd ON fbd.field_id = jfi.field_id
    WHERE NOT EXISTS (
            SELECT 1 FROM fields_with_share fws
            WHERE fws.job_id = jfi.job_id AND fws.field_id = jfi.field_id
          )
      AND fbd.customer_id IS NOT NULL

    UNION ALL

    -- 3. The job's PRIMARY customer for fields with neither a share nor a default.
    SELECT jfi.job_id, vj.primary_customer_id
    FROM job_field_ids jfi
    JOIN visible_jobs vj ON vj.job_id = jfi.job_id
    WHERE NOT EXISTS (
            SELECT 1 FROM fields_with_share fws
            WHERE fws.job_id = jfi.job_id AND fws.field_id = jfi.field_id
          )
      AND NOT EXISTS (
            SELECT 1 FROM field_billing_defaults fbd WHERE fbd.field_id = jfi.field_id
          )
      AND vj.primary_customer_id IS NOT NULL

    UNION ALL

    -- 4. SAFETY FALLBACK: a visible job with NO fields still has a primary customer.
    SELECT vj.job_id, vj.primary_customer_id
    FROM visible_jobs vj
    WHERE NOT EXISTS (SELECT 1 FROM job_field_ids jfi WHERE jfi.job_id = vj.job_id)
      AND vj.primary_customer_id IS NOT NULL
  ),
  distinct_pairs AS (
    SELECT DISTINCT r.job_id, r.customer_id FROM resolved r
  )
  -- LEFT JOIN so a since-removed customer_id still surfaces (NULL farm_name); the
  -- client treats a NULL name as INCOMPLETE for compliance docs, but for the LIST
  -- it just shows whatever resolves. is_primary = the job's primary customer.
  SELECT
    d.job_id,
    d.customer_id,
    c.farm_name,
    c.account_number,
    (d.customer_id = vj.primary_customer_id) AS is_primary
  FROM distinct_pairs d
  JOIN visible_jobs vj ON vj.job_id = d.job_id
  LEFT JOIN customers c ON c.id = d.customer_id
  ORDER BY d.job_id, (d.customer_id = vj.primary_customer_id) DESC, c.farm_name NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."get_jobs_billed_customers"("p_job_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_jobs_billed_customers"("p_job_ids" "uuid"[]) IS 'Field-app FIX 2 (Wave 2a): batched, read-only resolver for many jobs'' billed customers (job_field_shares -> field_billing_defaults -> primary customer_id), bypassing per-customer RLS so an applicator''s /jobs list shows co-billed split customers. Self-gates per job on the live jobs_select applicator predicate; a non-viewable job is SKIPPED (fail-soft), never raised on. Batch sibling of get_job_billed_customers.';



CREATE OR REPLACE FUNCTION "public"."get_label_coverage_report"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_total   int;
  v_result  jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_user_id AND role = 'admin' AND is_active = true
  ) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: admin role required';
  END IF;

  SELECT count(*) INTO v_total FROM products WHERE is_active = true;

  SELECT jsonb_build_object(
    'total_active_products', v_total,
    'signal_word',       (SELECT count(*) FROM products WHERE is_active = true AND NULLIF(btrim(signal_word), '')      IS NOT NULL),
    'rei_hours',         (SELECT count(*) FROM products WHERE is_active = true AND rei_hours        IS NOT NULL),
    'phi_days',          (SELECT count(*) FROM products WHERE is_active = true AND phi_days         IS NOT NULL),
    'epa_registration',  (SELECT count(*) FROM products WHERE is_active = true AND NULLIF(btrim(epa_registration), '') IS NOT NULL),
    'max_label_rate',    (SELECT count(*) FROM products WHERE is_active = true AND max_label_rate   IS NOT NULL),
    'pending_drafts',    (SELECT count(*) FROM product_label_drafts WHERE status = 'pending'),
    'accepted_drafts',   (SELECT count(*) FROM product_label_drafts WHERE status IN ('accepted','edited')),
    'rejected_drafts',   (SELECT count(*) FROM product_label_drafts WHERE status = 'rejected'),
    'needs_manual',      (SELECT count(*) FROM product_label_drafts WHERE status = 'needs_manual')
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_label_coverage_report"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_logbook_by_applicator"("p_applicator_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("record_id" "uuid", "record_number" "text", "application_date" "date", "application_time" time without time zone, "customer_name" "text", "applicator_name" "text", "field_name" "text", "field_legal_description" "text", "total_acres" numeric, "total_volume" numeric, "total_volume_unit" "text", "vehicle_name" "text", "vehicle_type" "text", "vehicle_registration" "text", "weather_conditions" "jsonb", "product_data" "jsonb", "invoice_number" "text", "season" integer, "source_type" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    ar.id, ar.record_number, ar.application_date, ar.application_time,
    c.farm_name, COALESCE(ar.applicator_name, p.full_name), f.field_name, f.legal_description, -- D1: prefer the completion-time snapshot (N2-7 #106b); profiles is the legacy fallback.
    ar.total_acres, ar.total_volume, ar.total_volume_unit,
    v.vehicle_name, v.vehicle_type, v.registration,
    ar.weather_conditions, ar.product_data, inv.invoice_number,
    ar.season, ar.source_type, ar.created_at
  FROM public.application_records ar
  LEFT JOIN public.customers c ON c.id = ar.customer_id
  LEFT JOIN public.profiles p ON p.id = ar.applicator_id
  LEFT JOIN public.fields f ON f.id = ar.field_id
  LEFT JOIN public.vehicles v ON v.id = ar.vehicle_id
  LEFT JOIN public.invoices inv ON inv.id = ar.invoice_id
  WHERE ar.applicator_id = p_applicator_id
    AND ar.application_date >= p_start_date
    AND ar.application_date <= p_end_date
  ORDER BY ar.application_date DESC, ar.application_time DESC NULLS LAST;
$$;


