CREATE OR REPLACE FUNCTION "public"."get_lot_application_trace"("p_lot_number" "text") RETURNS TABLE("application_record_id" "uuid", "record_number" "text", "product_id" "uuid", "product_name" "text", "lot_number" "text", "quantity_from_lot" numeric, "unit" "text", "application_date" "date", "customer_id" "uuid", "customer_name" "text", "applicator_id" "uuid", "applicator_name" "text", "field_names" "text", "invoice_id" "uuid", "source_receiving_record_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales role required';
  END IF;

  RETURN QUERY
  SELECT
    arl.application_record_id,
    ar.record_number,
    arl.product_id,
    p.product_name,
    arl.lot_number,
    arl.quantity_from_lot,
    arl.unit,
    ar.application_date,
    ar.customer_id,
    c.farm_name AS customer_name,
    ar.applicator_id,
    COALESCE(ar.applicator_name, pr.full_name) AS applicator_name, -- D1: prefer the completion-time snapshot (N2-7 #106b); profiles is the legacy fallback.
    -- prefer the per-field acres rows; fall back to the legacy single application_records.field_id
    -- so single-field / legacy records (and blend records with no blend_ticket_fields) still answer
    -- "which field received this lot" (Codex P2).
    COALESCE(
      (SELECT string_agg(f.field_name, ', ' ORDER BY arf.sort_order)
         FROM application_record_fields arf
         JOIN fields f ON f.id = arf.field_id
        WHERE arf.application_record_id = ar.id),
      (SELECT f2.field_name FROM fields f2 WHERE f2.id = ar.field_id)
    ) AS field_names,
    -- Invoiced status — report "invoiced" ONLY when an ACTIVE invoice still exists.
    --   * Job-sourced records stamp application_records.invoice_id (transfer_job_to_invoice),
    --     but void_invoice flips invoices.status WITHOUT clearing ar.invoice_id — so returning
    --     ar.invoice_id raw would show Invoiced=Yes for a voided/cancelled/soft-deleted invoice
    --     on a recall trace. Filter it through invoices with the active predicate (Codex P2).
    --   * Blend-sourced records never stamp ar.invoice_id (create_invoice_from_blend_ticket
    --     links via invoices.blend_ticket_id), so fall back to the most recent ACTIVE blend
    --     invoice so a billed blend ticket isn't misreported as not-invoiced (Codex P2).
    COALESCE(
      (SELECT i.id FROM invoices i
         WHERE i.id = ar.invoice_id
           AND i.status NOT IN ('voided', 'cancelled')
           AND i.deleted_at IS NULL),
      CASE WHEN ar.source_type = 'blend_ticket' THEN (
        SELECT i.id FROM invoices i
        WHERE i.blend_ticket_id = ar.source_id
          AND i.status NOT IN ('voided', 'cancelled')
          AND i.deleted_at IS NULL
        ORDER BY i.created_at DESC
        LIMIT 1
      ) END
    ) AS invoice_id,
    arl.source_receiving_record_id
  FROM application_record_lots arl
  JOIN application_records ar ON ar.id = arl.application_record_id
  LEFT JOIN products p ON p.id = arl.product_id
  LEFT JOIN customers c ON c.id = ar.customer_id
  LEFT JOIN profiles pr ON pr.id = ar.applicator_id
  WHERE lower(btrim(arl.lot_number)) = lower(btrim(p_lot_number))
  ORDER BY ar.application_date DESC, ar.record_number, p.product_name;
END;
$$;


ALTER FUNCTION "public"."get_lot_application_trace"("p_lot_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_monthly_summary"("p_period_start" "date", "p_period_end" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM require_admin();
  SELECT jsonb_build_object(
    'period_start', p_period_start,
    'period_end', p_period_end,
    'invoices', jsonb_build_object(
      'posted_count', (SELECT count(*) FROM public.invoices WHERE invoice_date BETWEEN p_period_start AND p_period_end AND status IN ('posted', 'overdue') AND deleted_at IS NULL),
      'total_amount_cents', COALESCE((SELECT sum(total_amount_cents) FROM public.invoices WHERE invoice_date BETWEEN p_period_start AND p_period_end AND status IN ('posted', 'overdue') AND deleted_at IS NULL), 0),
      'total_cost_cents', COALESCE((
        SELECT sum(ii.cost_cents * ii.quantity)
        FROM public.invoice_items ii
        JOIN public.invoices inv ON inv.id = ii.invoice_id
        WHERE inv.invoice_date BETWEEN p_period_start AND p_period_end
          AND inv.status IN ('posted', 'overdue')
          AND inv.deleted_at IS NULL
      ), 0),
      'draft_count', (SELECT count(*) FROM public.invoices WHERE invoice_date BETWEEN p_period_start AND p_period_end AND status IN ('draft','unposted') AND deleted_at IS NULL),
      'voided_count', (SELECT count(*) FROM public.invoices WHERE invoice_date BETWEEN p_period_start AND p_period_end AND status = 'voided' AND deleted_at IS NULL)
    ),
    'payments', jsonb_build_object(
      'count', (SELECT count(*) FROM public.payments WHERE payment_date BETWEEN p_period_start AND p_period_end AND deleted_at IS NULL),
      'total_cents', COALESCE((SELECT sum((amount * 100)::bigint) FROM public.payments WHERE payment_date BETWEEN p_period_start AND p_period_end AND deleted_at IS NULL), 0)
    ),
    'orders', jsonb_build_object(
      'count', (SELECT count(*) FROM public.orders WHERE order_date BETWEEN p_period_start AND p_period_end AND deleted_at IS NULL AND status NOT IN ('cancelled', 'draft')),
      'total_cents', COALESCE((SELECT sum((total_price * 100)::bigint) FROM public.orders WHERE order_date BETWEEN p_period_start AND p_period_end AND deleted_at IS NULL AND status NOT IN ('cancelled', 'draft')), 0)
    ),
    'deliveries', jsonb_build_object(
      'count', (SELECT count(*) FROM public.deliveries WHERE scheduled_date BETWEEN p_period_start AND p_period_end AND deleted_at IS NULL),
      'completed_count', (SELECT count(*) FROM public.deliveries WHERE scheduled_date BETWEEN p_period_start AND p_period_end AND status = 'completed' AND deleted_at IS NULL)
    ),
    'applications', jsonb_build_object(
      'count', (SELECT count(*) FROM public.application_records WHERE application_date BETWEEN p_period_start AND p_period_end),
      'total_acres', COALESCE((SELECT sum(total_acres) FROM public.application_records WHERE application_date BETWEEN p_period_start AND p_period_end), 0)
    ),
    'commissions', jsonb_build_object(
      'earned_cents', COALESCE((SELECT sum((commission_amount * 100)::bigint) FROM public.commissions WHERE order_date BETWEEN p_period_start AND p_period_end), 0),
      'paid_count', (SELECT count(*) FROM public.commissions WHERE order_date BETWEEN p_period_start AND p_period_end AND status = 'paid')
    ),
    'ar_balance_cents', COALESCE((SELECT sum(balance_cents) FROM public.invoices WHERE status IN ('posted', 'overdue') AND balance_cents > 0 AND deleted_at IS NULL), 0)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_monthly_summary"("p_period_start" "date", "p_period_end" "date") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."team_notes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" DEFAULT ''::"text" NOT NULL,
    "content" "text",
    "note_type" "text" DEFAULT 'note'::"text" NOT NULL,
    "priority" "text" DEFAULT 'medium'::"text" NOT NULL,
    "is_completed" boolean DEFAULT false NOT NULL,
    "completed_by" "uuid",
    "completed_at" timestamp with time zone,
    "due_date" "date",
    "created_by" "uuid" NOT NULL,
    "assigned_to" "uuid",
    "is_pinned" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "deleted_by" "uuid",
    "linked_entity_type" "text",
    "linked_entity_id" "uuid",
    "last_escalated_at" timestamp with time zone,
    CONSTRAINT "team_notes_note_type_check" CHECK (("note_type" = ANY (ARRAY['note'::"text", 'todo'::"text", 'announcement'::"text"]))),
    CONSTRAINT "team_notes_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'urgent'::"text"])))
);


ALTER TABLE "public"."team_notes" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notes_for_entity"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS SETOF "public"."team_notes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
    SELECT tn.*
    FROM team_notes tn
    WHERE tn.linked_entity_type = p_entity_type
      AND tn.linked_entity_id = p_entity_id
      AND tn.deleted_at IS NULL
    ORDER BY tn.is_pinned DESC, tn.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_notes_for_entity"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_offline_action_review_queue"("p_include_resolved" boolean DEFAULT false, "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_limit integer;
  v_offset integer;
  v_items jsonb;
  v_total integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = v_actor
      AND p.is_active = true
      AND p.role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: active office role required';
  END IF;

  v_limit := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 200);
  v_offset := GREATEST(COALESCE(p_offset, 0), 0);

  SELECT count(*)::integer
    INTO v_total
    FROM public.offline_action_receipts r
   WHERE r.status = 'needs_review'
     AND (COALESCE(p_include_resolved, false) OR r.resolved_at IS NULL);

  SELECT COALESCE(jsonb_agg(q.item ORDER BY q.needs_review_at DESC, q.client_action_id), '[]'::jsonb)
    INTO v_items
    FROM (
      SELECT
        r.needs_review_at,
        r.client_action_id,
        jsonb_build_object(
          'client_action_id', r.client_action_id,
          'actor_id', r.actor_id,
          'actor_name', COALESCE(NULLIF(btrim(actor.full_name), ''), actor.email),
          'operation', r.operation,
          'entity_id', r.entity_id,
          'failure_code', r.failure_code,
          'failure_summary', r.failure_summary,
          'attempt_count', r.attempt_count,
          'client_created_at', r.client_created_at,
          'received_at', r.received_at,
          'needs_review_at', r.needs_review_at,
          'updated_at', r.updated_at,
          'review_resolution', r.review_resolution,
          'review_note', r.review_note,
          'resolved_at', r.resolved_at,
          'resolved_by', r.resolved_by,
          'resolver_name', CASE
            WHEN resolver.id IS NULL THEN NULL
            ELSE COALESCE(NULLIF(btrim(resolver.full_name), ''), resolver.email)
          END
        ) AS item
      FROM public.offline_action_receipts r
      JOIN public.profiles actor ON actor.id = r.actor_id
      LEFT JOIN public.profiles resolver ON resolver.id = r.resolved_by
      WHERE r.status = 'needs_review'
        AND (COALESCE(p_include_resolved, false) OR r.resolved_at IS NULL)
      ORDER BY r.needs_review_at DESC, r.client_action_id
      LIMIT v_limit
      OFFSET v_offset
    ) q;

  RETURN jsonb_build_object(
    'items', v_items,
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset
  );
END;
$$;


ALTER FUNCTION "public"."get_offline_action_review_queue"("p_include_resolved" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_offline_action_review_queue"("p_include_resolved" boolean, "p_limit" integer, "p_offset" integer) IS 'Returns safe needs_review receipt metadata to active admin/sales office users; never exposes payloads or idempotency keys.';



CREATE OR REPLACE FUNCTION "public"."get_offline_action_status"("p_client_action_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_role text;
  v_receipt public.offline_action_receipts%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;

  SELECT p.role
    INTO v_actor_role
    FROM public.profiles p
   WHERE p.id = v_actor
     AND p.is_active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: active profile required';
  END IF;

  SELECT *
    INTO v_receipt
    FROM public.offline_action_receipts r
   WHERE r.client_action_id = p_client_action_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TARGET_NOT_FOUND: offline receipt not found';
  END IF;

  IF v_receipt.actor_id IS DISTINCT FROM v_actor
     AND v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED';
  END IF;

  RETURN jsonb_build_object(
    'client_action_id', v_receipt.client_action_id,
    'actor_id', v_receipt.actor_id,
    'operation', v_receipt.operation,
    'entity_id', v_receipt.entity_id,
    'schema_version', v_receipt.schema_version,
    'client_created_at', v_receipt.client_created_at,
    'status', v_receipt.status,
    'result', v_receipt.result,
    'failure_code', v_receipt.failure_code,
    'failure_summary', v_receipt.failure_summary,
    'attempt_count', v_receipt.attempt_count,
    'last_attempt_at', v_receipt.last_attempt_at,
    'received_at', v_receipt.received_at,
    'succeeded_at', v_receipt.succeeded_at,
    'needs_review_at', v_receipt.needs_review_at,
    'review_resolution', v_receipt.review_resolution,
    'review_note', v_receipt.review_note,
    'resolved_at', v_receipt.resolved_at,
    'resolved_by', v_receipt.resolved_by,
    'updated_at', v_receipt.updated_at
  );
END;
$$;


ALTER FUNCTION "public"."get_offline_action_status"("p_client_action_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_offline_action_status"("p_client_action_id" "uuid") IS 'Returns sanitized receipt status to the active owner or active admin/sales office user.';



CREATE OR REPLACE FUNCTION "public"."get_open_booking_rollover"("p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_season" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_role text;
  v_active boolean;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  SELECT role, is_active INTO v_role, v_active FROM profiles WHERE id = v_actor;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'sales_rep') OR v_active IS NOT TRUE THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  WITH open_bookings AS (
    SELECT q.id, q.quote_number, q.customer_id, q.status, q.season
      FROM quotes q
      WHERE q.status IN ('sent', 'revised')
        AND q.deleted_at IS NULL
        AND (p_customer_id IS NULL OR q.customer_id = p_customer_id)
        AND (p_season IS NULL OR q.season = p_season)
  ),
  booked AS (
    SELECT qi.quote_id, qi.product_id,
           SUM(COALESCE(qi.total_units_needed, 0)) AS booked_qty,
           CASE WHEN SUM(COALESCE(qi.total_units_needed, 0)) > 0
                THEN SUM(qi.price_per_unit * COALESCE(qi.total_units_needed, 0))
                     / SUM(COALESCE(qi.total_units_needed, 0))
                ELSE 0 END AS wavg_price
      FROM quote_items qi
      WHERE qi.quote_id IN (SELECT id FROM open_bookings)
      GROUP BY qi.quote_id, qi.product_id
  ),
  -- LAYER2<<< job draws consuming each booking line (Layer 2 §6.5)
  job_drawn AS (
    SELECT jd.quote_id, jd.product_id, SUM(jd.quantity_drawn) AS qty
      FROM job_product_draws jd
      WHERE jd.quote_id IN (SELECT id FROM open_bookings)
      GROUP BY jd.quote_id, jd.product_id
  ),
  -- >>>LAYER2
  locked AS (
    SELECT dle.quote_id, dle.product_id,
           CASE WHEN SUM(dle.eff_qty) > 0
                THEN SUM(dle.unit_price * dle.eff_qty) / SUM(dle.eff_qty)
                ELSE NULL END AS locked_price
      FROM (
        SELECT o.quote_id, oi.product_id,
               oi.total_price / NULLIF(oi.total_units_needed, 0) AS unit_price,
               CASE WHEN o.status = 'voided'    THEN 0
                    WHEN o.status = 'cancelled' THEN COALESCE(oi.quantity_delivered, 0)
                    ELSE COALESCE(oi.total_units_needed, 0) END AS eff_qty
          FROM orders o
          JOIN order_items oi ON oi.order_id = o.id
          WHERE o.booking_draw = true AND o.quote_id IN (SELECT id FROM open_bookings)
      ) dle
      GROUP BY dle.quote_id, dle.product_id
  ),
  per_product AS (
    SELECT b.quote_id,
           -- LAYER2<<< "drawn" folds ORDER draws (at their locked price) AND JOB draws
           -- (at current wavg — a job carries no locked order price), so the existing
           -- Quotes rollover table reconciles booked = drawn + remaining WITHOUT a new
           -- field the UI would ignore (Codex round-3 P2). remaining subtracts both
           -- order and job draws (§6.5): booked − order − job.
           ROUND((COALESCE(d.quantity_drawn, 0) * COALESCE(l.locked_price, b.wavg_price)
                  + COALESCE(jd.qty, 0) * b.wavg_price) * 100)::bigint AS drawn_cents,
           ROUND(GREATEST(b.booked_qty - COALESCE(d.quantity_drawn, 0) - COALESCE(jd.qty, 0), 0) * b.wavg_price * 100)::bigint AS remaining_cents
           -- >>>LAYER2
      FROM booked b
      LEFT JOIN quote_product_draws d ON d.quote_id = b.quote_id AND d.product_id = b.product_id
      LEFT JOIN job_drawn jd ON jd.quote_id = b.quote_id AND jd.product_id = b.product_id
      LEFT JOIN locked l ON l.quote_id = b.quote_id AND l.product_id = b.product_id
  ),
  booking_money AS (
    SELECT quote_id,
           COALESCE(SUM(drawn_cents + remaining_cents), 0) AS booked_cents,
           COALESCE(SUM(drawn_cents), 0) AS drawn_cents,
           COALESCE(SUM(remaining_cents), 0) AS remaining_cents
      FROM per_product
      GROUP BY quote_id
  ),
  booking_prepay AS (
    SELECT pc.quote_id,
           COALESCE(SUM(pc.balance_cents), 0) AS remaining_prepay_cents
      FROM prepay_credits pc
      WHERE pc.quote_id IN (SELECT id FROM open_bookings)
      GROUP BY pc.quote_id
  ),
  booking_applied AS (
    SELECT pc.quote_id,
           COALESCE(SUM(pa.applied_amount_cents), 0) AS applied_cents
      FROM prepay_applications pa
      JOIN prepay_credits pc ON pc.id = pa.prepay_credit_id
      WHERE pc.quote_id IN (SELECT id FROM open_bookings)
      GROUP BY pc.quote_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'quote_id', ob.id,
    'quote_number', ob.quote_number,
    'customer_id', ob.customer_id,
    'customer_name', c.farm_name,
    'status', ob.status,
    'season', ob.season,
    'booked_cents', COALESCE(bm.booked_cents, 0),
    'drawn_cents', COALESCE(bm.drawn_cents, 0),   -- LAYER2: folds order + job draws
    'remaining_cents', COALESCE(bm.remaining_cents, 0),
    'prepay_earmarked_cents', COALESCE(ba.applied_cents, 0) + COALESCE(bp.remaining_prepay_cents, 0),
    'prepay_remaining_cents', COALESCE(bp.remaining_prepay_cents, 0),
    'prepay_applied_cents', COALESCE(ba.applied_cents, 0)
  ) ORDER BY c.farm_name, ob.quote_number), '[]'::jsonb)
  INTO v_result
  FROM open_bookings ob
  LEFT JOIN customers c ON c.id = ob.customer_id
  LEFT JOIN booking_money bm ON bm.quote_id = ob.id
  LEFT JOIN booking_prepay bp ON bp.quote_id = ob.id
  LEFT JOIN booking_applied ba ON ba.quote_id = ob.id;

  RETURN jsonb_build_object('success', true, 'bookings', v_result);
END;
$$;


ALTER FUNCTION "public"."get_open_booking_rollover"("p_customer_id" "uuid", "p_season" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_price_history"("p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'ADMIN_OR_SALES_REQUIRED';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.products WHERE id = p_product_id) THEN
    RAISE EXCEPTION 'PRODUCT_NOT_FOUND';
  END IF;

  WITH history_points AS (
    SELECT
      'supplier_observation'::text AS stream,
      o.id::text AS source_id,
      o.vendor_id,
      v.name AS supplier_name,
      o.cost_cents,
      CASE
        WHEN l.comparison_status = 'comparable'
         AND l.inventory_units_per_supplier_unit > 0
        THEN round(o.cost_cents::numeric / o.package_quantity / l.inventory_units_per_supplier_unit)::bigint
        ELSE NULL
      END AS normalized_cost_cents,
      o.effective_from::timestamptz AS occurred_at,
      o.price_kind AS detail,
      jsonb_build_object(
        'import_id', o.import_id,
        'import_row_id', o.import_row_id,
        'product_supplier_link_id', o.product_supplier_link_id,
        'price_unit', o.price_unit,
        'package_quantity', o.package_quantity
      ) AS provenance
    FROM public.supplier_price_observations o
    JOIN public.product_supplier_links l ON l.id = o.product_supplier_link_id
    JOIN public.vendors v ON v.id = o.vendor_id
    WHERE o.product_id = p_product_id

    UNION ALL

    SELECT
      'selected_cost_basis'::text,
      ch.id::text,
      NULL::uuid,
      NULL::text,
      round(ch.new_cost * 100)::bigint,
      round(ch.new_cost * 100)::bigint,
      ch.changed_at,
      COALESCE(ch.change_note, ch.change_source, 'Product pricing history'),
      jsonb_build_object('change_set_id', ch.change_set_id, 'changed_by', ch.changed_by)
    FROM public.cost_history ch
    WHERE ch.product_id = p_product_id
      AND ch.new_cost IS NOT NULL

    UNION ALL

    SELECT
      'actual_purchase'::text,
      poi.id::text,
      resolved.vendor_id,
      COALESCE(v.name, 'supplier unknown'),
      poi.unit_cost_cents,
      CASE
        WHEN poi.inventory_units_per_supplier_unit_snapshot > 0
        THEN round(poi.unit_cost_cents::numeric / poi.inventory_units_per_supplier_unit_snapshot)::bigint
        ELSE NULL
      END,
      COALESCE(po.submitted_date::timestamptz, po.created_at),
      'actual_purchase',
      jsonb_build_object(
        'purchase_order_id', po.id,
        'purchase_order_item_id', poi.id,
        'po_number', po.po_number,
        'legacy_vendor_text', po.vendor,
        'resolution_status', CASE WHEN resolved.vendor_id IS NULL THEN 'supplier unknown' ELSE 'reviewed' END,
        'cost_provenance', poi.cost_provenance
      )
    FROM public.purchase_order_items poi
    JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
    LEFT JOIN public.legacy_vendor_resolution resolved
      ON resolved.normalized_text = public.normalize_vendor_alias(po.vendor)
     AND resolved.review_status = 'approved'
    LEFT JOIN public.vendors v ON v.id = resolved.vendor_id
    WHERE poi.product_id = p_product_id
      AND poi.quantity_received > 0
      AND poi.unit_cost_cents IS NOT NULL
      AND po.status <> 'cancelled'
  )
  SELECT jsonb_build_object(
    'product_id', p_product_id,
    'summary', COALESCE(
      public.get_supplier_market_evidence(ARRAY[p_product_id])->0,
      jsonb_build_object(
        'product_id', p_product_id,
        'supplier_quote_count', 0,
        'comparable_quote_count', 0,
        'replacement_cost_cents', NULL,
        'replacement_cost_as_of', NULL,
        'best_supplier', NULL,
        'last_paid_cents', NULL,
        'last_paid_as_of', NULL,
        'recent_po_weighted_average_cents', NULL,
        'recent_po_window', 'trailing_12_months',
        'comparison_status', 'no_evidence',
        'suppliers', '[]'::jsonb
      )
    ),
    'suppliers', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', s.vendor_id, 'name', s.supplier_name) ORDER BY s.supplier_name)
      FROM (
        SELECT DISTINCT vendor_id, supplier_name
        FROM history_points
        WHERE vendor_id IS NOT NULL
      ) s
    ), '[]'::jsonb),
    'points', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'stream', h.stream,
        'source_id', h.source_id,
        'vendor_id', h.vendor_id,
        'supplier_name', h.supplier_name,
        'cost_cents', h.cost_cents,
        'normalized_cost_cents', h.normalized_cost_cents,
        'occurred_at', h.occurred_at,
        'detail', h.detail,
        'provenance', h.provenance
      ) ORDER BY h.occurred_at, h.stream, h.source_id)
      FROM history_points h
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_product_price_history"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_program_completion"("p_season" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_season integer; v_result jsonb;
BEGIN
  IF p_season IS NULL THEN v_season := current_season(); ELSE v_season := p_season; END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.customer_name, t.program_name), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      q.customer_id, c.farm_name AS customer_name,
      q.id AS quote_id, q.quote_number,
      qs.id AS section_id, qs.section_name AS program_name, qs.needed_by_date,
      COALESCE(MAX(qi.acres), 0) AS planned_acres,
      COALESCE((SELECT SUM(btf.actual_acres) FROM jobs j2 JOIN blend_tickets bt ON bt.job_id = j2.id
        JOIN blend_ticket_fields btf ON btf.blend_ticket_id = bt.id
        WHERE j2.quote_section_id = qs.id AND j2.deleted_at IS NULL), 0) AS completed_acres,
      CASE WHEN MAX(qi.acres) IS NULL OR MAX(qi.acres) = 0 THEN 0
        ELSE ROUND(COALESCE((SELECT SUM(btf.actual_acres) FROM jobs j2 JOIN blend_tickets bt ON bt.job_id = j2.id
          JOIN blend_ticket_fields btf ON btf.blend_ticket_id = bt.id
          WHERE j2.quote_section_id = qs.id AND j2.deleted_at IS NULL), 0) / MAX(qi.acres) * 100, 1) END AS completion_pct,
      CASE
        WHEN NOT EXISTS (SELECT 1 FROM jobs j3 WHERE j3.quote_section_id = qs.id AND j3.deleted_at IS NULL) THEN 'not_started'
        WHEN COALESCE((SELECT SUM(btf2.actual_acres) FROM jobs j4 JOIN blend_tickets bt2 ON bt2.job_id = j4.id
          JOIN blend_ticket_fields btf2 ON btf2.blend_ticket_id = bt2.id
          WHERE j4.quote_section_id = qs.id AND j4.deleted_at IS NULL), 0) >= COALESCE(MAX(qi.acres), 0) AND MAX(qi.acres) > 0
        THEN 'completed' ELSE 'in_progress' END AS status,
      (SELECT COUNT(*) FROM jobs j5 WHERE j5.quote_section_id = qs.id AND j5.deleted_at IS NULL)::integer AS job_count,
      (SELECT COUNT(*) FROM jobs j6 JOIN blend_tickets bt3 ON bt3.job_id = j6.id
        WHERE j6.quote_section_id = qs.id AND j6.deleted_at IS NULL)::integer AS blend_ticket_count,
      COALESCE((SELECT SUM(inv.total_amount_cents) FROM jobs j7 JOIN blend_tickets bt4 ON bt4.job_id = j7.id
        JOIN invoices inv ON inv.blend_ticket_id = bt4.id
        WHERE j7.quote_section_id = qs.id AND j7.deleted_at IS NULL
        AND inv.status NOT IN ('voided', 'cancelled')), 0)::bigint AS invoiced_amount_cents
    FROM quotes q
    JOIN customers c ON c.id = q.customer_id
    JOIN quote_sections qs ON qs.quote_id = q.id
    LEFT JOIN quote_items qi ON qi.section_id = qs.id
    WHERE q.is_planned = true AND q.season = v_season
      AND q.status NOT IN ('declined', 'expired', 'cancelled')
    GROUP BY q.customer_id, c.farm_name, q.id, q.quote_number, qs.id, qs.section_name, qs.needed_by_date
  ) t;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_program_completion"("p_season" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_receiving_log"("p_limit" integer DEFAULT 200, "p_offset" integer DEFAULT 0, "p_vendor" "text" DEFAULT NULL::"text", "p_condition" "text" DEFAULT NULL::"text", "p_received_by" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = (select auth.uid()) AND is_active = true
      AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb) INTO v_result
  FROM (
    SELECT
      rr.id,
      rr.purchase_order_id,
      rr.po_item_id,
      rr.product_id,
      rr.quantity_received,
      rr.received_at,
      rr.notes,
      rr.condition,
      rr.lot_number,
      rr.storage_location,
      rr.unit_size,
      po.po_number,
      po.vendor,
      p.product_name,
      prof.full_name AS received_by_name,
      (SELECT count(*) FROM receiving_photos rp
       WHERE rp.receiving_record_id = rr.id) AS photo_count
    FROM receiving_records rr
    JOIN purchase_orders po ON po.id = rr.purchase_order_id
    JOIN products p ON p.id = rr.product_id
    JOIN profiles prof ON prof.id = rr.received_by
    WHERE (p_vendor IS NULL OR po.vendor ILIKE '%' || p_vendor || '%')
      AND (p_condition IS NULL OR rr.condition = p_condition)
      AND (p_received_by IS NULL OR rr.received_by = p_received_by)
      AND (p_date_from IS NULL OR rr.received_at::date >= p_date_from)
      AND (p_date_to IS NULL OR rr.received_at::date <= p_date_to)
    ORDER BY rr.received_at DESC
    LIMIT p_limit OFFSET p_offset
  ) r;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_receiving_log"("p_limit" integer, "p_offset" integer, "p_vendor" "text", "p_condition" "text", "p_received_by" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_receiving_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_today date := current_date;
  v_week_start date := date_trunc('week', current_date)::date;
  v_year_start date := season_start_date(compute_season(current_date));
BEGIN
  -- Verify caller is admin or sales_rep
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = (select auth.uid()) AND is_active = true
      AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT jsonb_build_object(
    'expected_today', (
      SELECT count(*) FROM purchase_orders
      WHERE status IN ('submitted', 'partially_received')
        AND expected_delivery_date = v_today
    ),
    'pending_receipt', (
      SELECT count(*) FROM purchase_orders
      WHERE status IN ('submitted', 'partially_received')
    ),
    'received_this_week', (
      SELECT count(DISTINCT rr.id) FROM receiving_records rr
      WHERE rr.received_at::date >= v_week_start
    ),
    'items_received_ytd', (
      SELECT COALESCE(sum(rr.quantity_received), 0) FROM receiving_records rr
      WHERE rr.received_at::date >= v_year_start
    ),
    'damaged_this_week', (
      SELECT count(*) FROM receiving_records rr
      WHERE rr.received_at::date >= v_week_start
        AND rr.condition <> 'good'
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_receiving_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recent_lots_for_product"("p_product_id" "uuid") RETURNS TABLE("lot_number" "text", "last_received_at" timestamp with time zone, "receiving_record_id" "uuid", "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales role required';
  END IF;

  -- One row per distinct (case-insensitive) lot — the newest receiving record for that lot.
  -- receiving_record_id lets the editor save source_receiving_record_id so the provenance
  -- validation path in set_application_record_lots fires (a suggested lot keeps its receipt link).
  RETURN QUERY
  SELECT t.lot_number, t.last_received_at, t.receiving_record_id, 'receiving'::text AS source
  FROM (
    SELECT DISTINCT ON (lower(btrim(rr.lot_number)))
           btrim(rr.lot_number) AS lot_number,
           rr.received_at        AS last_received_at,
           rr.id                 AS receiving_record_id
    FROM receiving_records rr
    WHERE rr.product_id = p_product_id
      AND rr.lot_number IS NOT NULL
      AND btrim(rr.lot_number) <> ''
    ORDER BY lower(btrim(rr.lot_number)), rr.received_at DESC
  ) t
  ORDER BY t.last_received_at DESC
  LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."get_recent_lots_for_product"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rep_customer_purchase_flags"("p_season" "text" DEFAULT NULL::"text") RETURNS TABLE("customer_id" "uuid", "farm_name" "text", "this_season_cents" bigint, "last_season_cents" bigint, "lapsed" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_season integer := COALESCE(p_season::integer, public.current_season());
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid() AND p.is_active
      AND (public.is_admin() OR public.is_sales_rep())
  ) THEN
    RAISE EXCEPTION 'PURCHASE_INTELLIGENCE_ACCESS_DENIED';
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.farm_name,
    COALESCE(SUM(i.total_amount_cents) FILTER (
      WHERE i.season = v_season AND i.deleted_at IS NULL
        AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
        AND i.status IN ('posted', 'paid', 'overdue')
    ), 0)::bigint,
    COALESCE(SUM(i.total_amount_cents) FILTER (
      WHERE i.season = v_season - 1 AND i.deleted_at IS NULL
        AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
        AND i.status IN ('posted', 'paid', 'overdue')
    ), 0)::bigint,
    COALESCE(SUM(i.total_amount_cents) FILTER (
      WHERE i.season = v_season - 1 AND i.deleted_at IS NULL
        AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
        AND i.status IN ('posted', 'paid', 'overdue')
    ), 0) > 0
    AND COALESCE(SUM(i.total_amount_cents) FILTER (
      WHERE i.season = v_season AND i.deleted_at IS NULL
        AND COALESCE(i.invoice_type, 'invoice') <> 'credit_memo'
        AND i.status IN ('posted', 'paid', 'overdue')
    ), 0) = 0
  FROM public.customers c
  LEFT JOIN public.invoices i ON i.customer_id = c.id
  WHERE public.is_admin() OR c.assigned_sales_rep = auth.uid()
  GROUP BY c.id, c.farm_name;
END;
$$;


ALTER FUNCTION "public"."get_rep_customer_purchase_flags"("p_season" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_rep_customer_purchase_flags"("p_season" "text") IS 'Returns seasonal versus prior-season purchase flags for all customers an active caller may access.';



CREATE OR REPLACE FUNCTION "public"."get_rup_sales_register"("p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_product_id" "uuid" DEFAULT NULL::"uuid", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_compliance_status" "text" DEFAULT NULL::"text", "p_include_voided" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "sale_date" "date", "invoice_id" "uuid", "customer_id" "uuid", "buyer_name" "text", "product_name" "text", "epa_registration" "text", "quantity" numeric, "unit" "text", "unit_price_cents" bigint, "total_cents" bigint, "buyer_certification_number" "text", "buyer_certification_type" "text", "buyer_certification_expiry" "date", "signal_word" "text", "compliance_status" "text", "compliance_notes" "text", "season" integer, "voided_at" timestamp with time zone, "voided_by" "uuid", "void_reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    r.id, r.sale_date, r.invoice_id, r.customer_id,
    r.buyer_name, r.product_name, r.epa_registration,
    r.quantity, r.unit, r.unit_price_cents, r.total_cents,
    r.buyer_certification_number, r.buyer_certification_type,
    r.buyer_certification_expiry, r.signal_word,
    r.compliance_status, r.compliance_notes, r.season,
    r.voided_at, r.voided_by, r.void_reason
  FROM rup_sales_records r
  WHERE (p_start_date IS NULL OR r.sale_date >= p_start_date)
    AND (p_end_date   IS NULL OR r.sale_date <= p_end_date)
    AND (p_product_id IS NULL OR r.product_id = p_product_id)
    AND (p_customer_id IS NULL OR r.customer_id = p_customer_id)
    AND (p_compliance_status IS NULL OR r.compliance_status = p_compliance_status)
    AND (p_include_voided OR r.voided_at IS NULL)
  ORDER BY r.sale_date DESC, r.buyer_name;
END;
$$;


ALTER FUNCTION "public"."get_rup_sales_register"("p_start_date" "date", "p_end_date" "date", "p_product_id" "uuid", "p_customer_id" "uuid", "p_compliance_status" "text", "p_include_voided" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sales_detail_report"("p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_product_id" "uuid" DEFAULT NULL::"uuid", "p_customer_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_sales_rep_id" "uuid" DEFAULT NULL::"uuid", "p_category" "text" DEFAULT NULL::"text", "p_season" integer DEFAULT NULL::integer) RETURNS TABLE("order_date" "date", "order_number" "text", "customer_name" "text", "customer_id" "uuid", "product_name" "text", "product_id" "uuid", "sku" "text", "category" "text", "quantity" numeric, "unit" "text", "unit_price" numeric, "total_price" numeric, "cost" numeric, "profit" numeric, "margin_pct" numeric, "sales_rep_name" "text", "invoice_number" "text", "season" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE id = auth.uid()
      AND is_active = true
      AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Access denied: admin or sales_rep role required';
  END IF;

  RETURN QUERY
  SELECT
    o.order_date,
    o.order_number,
    c.farm_name AS customer_name,
    o.customer_id,
    oi.product_name,
    oi.product_id,
    p.sku,
    p.category,
    oi.total_units_needed AS quantity,
    oi.unit_size AS unit,
    oi.price_per_unit AS unit_price,
    oi.total_price,
    ROUND(oi.cost_per_unit * oi.total_units_needed, 2) AS cost,
    oi.profit,
    CASE
      WHEN oi.total_price > 0 THEN ROUND((oi.profit / oi.total_price) * 100, 1)
      ELSE 0::numeric
    END AS margin_pct,
    COALESCE(rep.full_name, 'Unassigned') AS sales_rep_name,
    inv.invoice_number,
    o.season
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  JOIN public.customers c ON c.id = o.customer_id
  JOIN public.products p ON p.id = oi.product_id
  LEFT JOIN public.profiles rep ON rep.id = o.salesman_id
  LEFT JOIN LATERAL (
    SELECT ii.invoice_id, i2.invoice_number
    FROM public.invoice_items ii
    JOIN public.invoices i2 ON i2.id = ii.invoice_id
    WHERE ii.order_item_id = oi.id
      AND i2.status NOT IN ('void', 'voided')
      AND i2.deleted_at IS NULL
    ORDER BY i2.created_at DESC
    LIMIT 1
  ) inv ON true
  WHERE o.deleted_at IS NULL
    AND o.status NOT IN ('cancelled', 'voided')
    AND (p_start_date IS NULL OR o.order_date >= p_start_date)
    AND (p_end_date IS NULL OR o.order_date <= p_end_date)
    AND (p_product_id IS NULL OR oi.product_id = p_product_id)
    AND (p_customer_ids IS NULL OR o.customer_id = ANY(p_customer_ids))
    AND (p_sales_rep_id IS NULL OR o.salesman_id = p_sales_rep_id)
    AND (p_category IS NULL OR p.category = p_category)
    AND (p_season IS NULL OR o.season = p_season)
  ORDER BY o.order_date DESC, c.farm_name, oi.product_name;
END;
$$;


ALTER FUNCTION "public"."get_sales_detail_report"("p_start_date" "date", "p_end_date" "date", "p_product_id" "uuid", "p_customer_ids" "uuid"[], "p_sales_rep_id" "uuid", "p_category" "text", "p_season" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_sales_detail_report"("p_start_date" "date", "p_end_date" "date", "p_product_id" "uuid", "p_customer_ids" "uuid"[], "p_sales_rep_id" "uuid", "p_category" "text", "p_season" integer) IS 'Line-item sales detail with all optional filters for the Sales Reports page.';



CREATE OR REPLACE FUNCTION "public"."get_sales_summary_report"("p_group_by" "text" DEFAULT 'product'::"text", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_product_id" "uuid" DEFAULT NULL::"uuid", "p_customer_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_sales_rep_id" "uuid" DEFAULT NULL::"uuid", "p_category" "text" DEFAULT NULL::"text", "p_season" integer DEFAULT NULL::integer) RETURNS TABLE("group_key" "text", "group_id" "uuid", "total_quantity" numeric, "total_revenue" numeric, "total_cost" numeric, "total_profit" numeric, "margin_pct" numeric, "order_count" bigint, "line_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE id = auth.uid()
      AND is_active = true
      AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Access denied: admin or sales_rep role required';
  END IF;

  RETURN QUERY
  WITH filtered AS (
    SELECT
      oi.product_id,
      oi.product_name,
      o.customer_id,
      c.farm_name,
      o.salesman_id,
      COALESCE(rep.full_name, 'Unassigned') AS rep_name,
      p.category,
      o.order_date,
      o.id AS order_id,
      oi.total_units_needed AS quantity,
      oi.total_price AS revenue,
      ROUND(oi.cost_per_unit * oi.total_units_needed, 2) AS cost,
      oi.profit
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    JOIN public.customers c ON c.id = o.customer_id
    JOIN public.products p ON p.id = oi.product_id
    LEFT JOIN public.profiles rep ON rep.id = o.salesman_id
    WHERE o.deleted_at IS NULL
      AND o.status NOT IN ('cancelled', 'voided')
      AND (p_start_date IS NULL OR o.order_date >= p_start_date)
      AND (p_end_date IS NULL OR o.order_date <= p_end_date)
      AND (p_product_id IS NULL OR oi.product_id = p_product_id)
      AND (p_customer_ids IS NULL OR o.customer_id = ANY(p_customer_ids))
      AND (p_sales_rep_id IS NULL OR o.salesman_id = p_sales_rep_id)
      AND (p_category IS NULL OR p.category = p_category)
      AND (p_season IS NULL OR o.season = p_season)
  )
  SELECT
    CASE p_group_by
      WHEN 'product' THEN f.product_name
      WHEN 'customer' THEN f.farm_name
      WHEN 'sales_rep' THEN f.rep_name
      WHEN 'month' THEN TO_CHAR(f.order_date, 'YYYY-MM')
      WHEN 'category' THEN COALESCE(f.category, 'Uncategorized')
      ELSE f.product_name
    END AS group_key,
    CASE p_group_by
      WHEN 'product' THEN f.product_id
      WHEN 'customer' THEN f.customer_id
      WHEN 'sales_rep' THEN f.salesman_id
      ELSE NULL
    END AS group_id,
    SUM(f.quantity) AS total_quantity,
    SUM(f.revenue) AS total_revenue,
    SUM(f.cost) AS total_cost,
    SUM(f.profit) AS total_profit,
    CASE
      WHEN SUM(f.revenue) > 0 THEN ROUND((SUM(f.profit) / SUM(f.revenue)) * 100, 1)
      ELSE 0::numeric
    END AS margin_pct,
    COUNT(DISTINCT f.order_id) AS order_count,
    COUNT(*) AS line_count
  FROM filtered f
  GROUP BY
    CASE p_group_by
      WHEN 'product' THEN f.product_name
      WHEN 'customer' THEN f.farm_name
      WHEN 'sales_rep' THEN f.rep_name
      WHEN 'month' THEN TO_CHAR(f.order_date, 'YYYY-MM')
      WHEN 'category' THEN COALESCE(f.category, 'Uncategorized')
      ELSE f.product_name
    END,
    CASE p_group_by
      WHEN 'product' THEN f.product_id
      WHEN 'customer' THEN f.customer_id
      WHEN 'sales_rep' THEN f.salesman_id
      ELSE NULL
    END
  ORDER BY SUM(f.revenue) DESC;
END;
$$;


ALTER FUNCTION "public"."get_sales_summary_report"("p_group_by" "text", "p_start_date" "date", "p_end_date" "date", "p_product_id" "uuid", "p_customer_ids" "uuid"[], "p_sales_rep_id" "uuid", "p_category" "text", "p_season" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_sales_summary_report"("p_group_by" "text", "p_start_date" "date", "p_end_date" "date", "p_product_id" "uuid", "p_customer_ids" "uuid"[], "p_sales_rep_id" "uuid", "p_category" "text", "p_season" integer) IS 'Aggregated sales summary grouped by product/customer/sales_rep/month/category.';



CREATE OR REPLACE FUNCTION "public"."get_season_comparison"("p_season_a" integer, "p_season_b" integer) RETURNS TABLE("metric" "text", "season_a_val" numeric, "season_b_val" numeric, "change_pct" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_a_start date;
  v_a_end date;
  v_b_start date;
  v_b_end date;
  v_a_revenue numeric;
  v_b_revenue numeric;
  v_a_profit numeric;
  v_b_profit numeric;
  v_a_orders int;
  v_b_orders int;
  v_a_customers int;
  v_b_customers int;
BEGIN
  PERFORM require_admin();
  v_a_start := season_start_date(p_season_a);
  v_a_end   := season_end_date(p_season_a);
  v_b_start := season_start_date(p_season_b);
  v_b_end   := season_end_date(p_season_b);

  SELECT COALESCE(SUM(total_price), 0), COALESCE(SUM(total_profit), 0), COUNT(*), COUNT(DISTINCT customer_id)
  INTO v_a_revenue, v_a_profit, v_a_orders, v_a_customers
  FROM orders
  WHERE order_date BETWEEN v_a_start AND v_a_end
    AND status <> 'cancelled';

  SELECT COALESCE(SUM(total_price), 0), COALESCE(SUM(total_profit), 0), COUNT(*), COUNT(DISTINCT customer_id)
  INTO v_b_revenue, v_b_profit, v_b_orders, v_b_customers
  FROM orders
  WHERE order_date BETWEEN v_b_start AND v_b_end
    AND status <> 'cancelled';

  RETURN QUERY VALUES
    ('Revenue'::text, v_a_revenue, v_b_revenue,
      CASE WHEN v_b_revenue > 0 THEN ROUND((v_a_revenue - v_b_revenue) / v_b_revenue * 100, 1) ELSE NULL END),
    ('Profit'::text, v_a_profit, v_b_profit,
      CASE WHEN v_b_profit > 0 THEN ROUND((v_a_profit - v_b_profit) / v_b_profit * 100, 1) ELSE NULL END),
    ('Orders'::text, v_a_orders::numeric, v_b_orders::numeric,
      CASE WHEN v_b_orders > 0 THEN ROUND((v_a_orders - v_b_orders)::numeric / v_b_orders * 100, 1) ELSE NULL END),
    ('Active Customers'::text, v_a_customers::numeric, v_b_customers::numeric,
      CASE WHEN v_b_customers > 0 THEN ROUND((v_a_customers - v_b_customers)::numeric / v_b_customers * 100, 1) ELSE NULL END);
END;
$$;


ALTER FUNCTION "public"."get_season_comparison"("p_season_a" integer, "p_season_b" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_market_evidence"("p_product_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'ADMIN_OR_SALES_REQUIRED';
  END IF;

  WITH latest AS (
    SELECT DISTINCT ON (o.product_supplier_link_id)
      o.product_id,
      o.vendor_id,
      o.product_supplier_link_id,
      o.cost_cents,
      o.package_quantity,
      o.effective_from,
      o.observed_at,
      l.inventory_units_per_supplier_unit,
      l.comparison_status,
      v.name AS vendor_name,
      CASE
        WHEN l.comparison_status = 'comparable'
         AND l.inventory_units_per_supplier_unit > 0
        THEN round(o.cost_cents::numeric / o.package_quantity / l.inventory_units_per_supplier_unit)::bigint
        ELSE NULL
      END AS normalized_cost_cents
    FROM public.supplier_price_observations o
    JOIN public.product_supplier_links l ON l.id = o.product_supplier_link_id AND l.is_active
    JOIN public.vendors v ON v.id = o.vendor_id AND v.deleted_at IS NULL
    WHERE (p_product_ids IS NULL OR o.product_id = ANY(p_product_ids))
      AND o.effective_from <= current_date
      AND (o.effective_to IS NULL OR o.effective_to >= current_date)
      AND NOT EXISTS (
        SELECT 1
        FROM public.supplier_price_observations correction
        WHERE correction.supersedes_observation_id = o.id
      )
    ORDER BY o.product_supplier_link_id, o.effective_from DESC, o.observed_at DESC, o.id DESC
  ), ranked AS (
    SELECT latest.*,
      dense_rank() OVER (
        PARTITION BY product_id
        ORDER BY normalized_cost_cents ASC NULLS LAST, effective_from DESC
      ) AS price_rank
    FROM latest
  ), product_summary AS (
    SELECT
      product_id,
      count(*)::integer AS supplier_quote_count,
      count(*) FILTER (WHERE normalized_cost_cents IS NOT NULL)::integer AS comparable_quote_count,
      min(normalized_cost_cents) AS replacement_cost_cents,
      max(effective_from) FILTER (WHERE normalized_cost_cents IS NOT NULL AND price_rank = 1) AS replacement_cost_as_of,
      min(vendor_name) FILTER (WHERE normalized_cost_cents IS NOT NULL AND price_rank = 1) AS best_supplier,
      jsonb_agg(jsonb_build_object(
        'vendor_id', vendor_id,
        'vendor_name', vendor_name,
        'product_supplier_link_id', product_supplier_link_id,
        'quoted_package_cost_cents', cost_cents,
        'normalized_cost_cents', normalized_cost_cents,
        'effective_from', effective_from,
        'comparison_status', CASE WHEN normalized_cost_cents IS NULL THEN 'cannot_compare' ELSE 'comparable' END,
        'is_best_comparable', normalized_cost_cents IS NOT NULL AND price_rank = 1
      ) ORDER BY normalized_cost_cents ASC NULLS LAST, vendor_name) AS suppliers
    FROM ranked
    GROUP BY product_id
  ), purchase_lines AS (
    SELECT
      poi.id,
      poi.product_id,
      poi.unit_cost_cents,
      poi.quantity_received,
      COALESCE(po.submitted_date, po.created_at::date) AS purchase_date
    FROM public.purchase_order_items poi
    JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
    WHERE poi.quantity_received > 0
      AND poi.unit_cost_cents IS NOT NULL
      AND po.status <> 'cancelled'
      AND (p_product_ids IS NULL OR poi.product_id = ANY(p_product_ids))
  ), purchase_summary AS (
    SELECT
      product_id,
      (array_agg(unit_cost_cents ORDER BY purchase_date DESC, id DESC))[1] AS last_paid_cents,
      (array_agg(purchase_date ORDER BY purchase_date DESC, id DESC))[1] AS last_paid_as_of,
      round(
        sum(unit_cost_cents::numeric * quantity_received)
          FILTER (WHERE purchase_date >= current_date - 365)
        / NULLIF(
          sum(quantity_received) FILTER (WHERE purchase_date >= current_date - 365),
          0
        )
      )::bigint AS recent_po_weighted_average_cents
    FROM purchase_lines
    GROUP BY product_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'product_id', p.id,
    'supplier_quote_count', COALESCE(s.supplier_quote_count, 0),
    'comparable_quote_count', COALESCE(s.comparable_quote_count, 0),
    'replacement_cost_cents', s.replacement_cost_cents,
    'replacement_cost_as_of', s.replacement_cost_as_of,
    'best_supplier', s.best_supplier,
    'last_paid_cents', purchase.last_paid_cents,
    'last_paid_as_of', purchase.last_paid_as_of,
    'recent_po_weighted_average_cents', purchase.recent_po_weighted_average_cents,
    'recent_po_window', 'trailing_12_months',
    'comparison_status', CASE
      WHEN COALESCE(s.supplier_quote_count, 0) = 0 THEN 'no_evidence'
      WHEN COALESCE(s.comparable_quote_count, 0) = 0 THEN 'cannot_compare'
      ELSE 'comparable'
    END,
    'suppliers', COALESCE(s.suppliers, '[]'::jsonb)
  ) ORDER BY p.product_name, p.id), '[]'::jsonb)
  INTO v_result
  FROM public.products p
  LEFT JOIN product_summary s ON s.product_id = p.id
  LEFT JOIN purchase_summary purchase ON purchase.product_id = p.id
  WHERE p.is_active
    AND (p_product_ids IS NULL OR p.id = ANY(p_product_ids));

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_supplier_market_evidence"("p_product_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_price_import"("p_import_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'ADMIN_OR_SALES_REQUIRED';
  END IF;

  SELECT jsonb_build_object(
    'id', i.id,
    'vendor_id', i.vendor_id,
    'vendor_name', v.name,
    'document_date', i.document_date,
    'ingestion_method', i.ingestion_method,
    'format_version', i.format_version,
    'status', i.status,
    'source_document_name', i.source_document_name,
    'row_count', i.row_count,
    'eligible_row_count', i.eligible_row_count,
    'approved_observation_count', i.approved_observation_count,
    'created_at', i.created_at,
    'rows', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', r.id,
        'row_number', r.row_number,
        'product_id', r.product_id,
        'product_name', p.product_name,
        'product_supplier_link_id', r.product_supplier_link_id,
        'supplier_sku', r.supplier_sku,
        'supplier_product_name', r.supplier_product_name,
        'cost_cents', r.cost_cents,
        'price_unit', r.price_unit,
        'package_quantity', r.package_quantity,
        'effective_from', r.effective_from,
        'effective_to', r.effective_to,
        'price_kind', r.price_kind,
        'row_status', r.row_status,
        'validation_errors', r.validation_errors,
        'observation_id', r.observation_id
      ) ORDER BY r.row_number), '[]'::jsonb)
      FROM public.supplier_price_import_rows r
      LEFT JOIN public.products p ON p.id = r.product_id
      WHERE r.import_id = i.id
    )
  ) INTO v_result
  FROM public.supplier_price_imports i
  JOIN public.vendors v ON v.id = i.vendor_id
  WHERE i.id = p_import_id;

  IF v_result IS NULL THEN RAISE EXCEPTION 'SUPPLIER_IMPORT_NOT_FOUND'; END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_supplier_price_import"("p_import_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_pricing_workspace"("p_product_id" "uuid" DEFAULT NULL::"uuid", "p_vendor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'ADMIN_OR_SALES_REQUIRED';
  END IF;

  SELECT jsonb_build_object(
    'vendors', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', v.id, 'name', v.name) ORDER BY v.name), '[]'::jsonb)
      FROM public.vendors v WHERE v.deleted_at IS NULL
    ),
    'products', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', p.id, 'product_name', p.product_name, 'sku', p.sku, 'inventory_unit', p.inventory_unit
      ) ORDER BY p.product_name), '[]'::jsonb)
      FROM public.products p
      WHERE p.is_active AND (p_product_id IS NULL OR p.id = p_product_id)
    ),
    'links', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', l.id,
        'product_id', l.product_id,
        'product_name', p.product_name,
        'vendor_id', l.vendor_id,
        'vendor_name', v.name,
        'supplier_sku', l.supplier_sku,
        'supplier_product_name', l.supplier_product_name,
        'supplier_uom', l.supplier_uom,
        'supplier_pack_description', l.supplier_pack_description,
        'inventory_units_per_supplier_unit', l.inventory_units_per_supplier_unit,
        'conversion_unit', l.conversion_unit,
        'comparison_status', l.comparison_status,
        'comparison_note', l.comparison_note,
        'link_status', l.link_status,
        'is_reusable', l.is_reusable,
        'is_preferred', l.is_preferred,
        'is_active', l.is_active
      ) ORDER BY p.product_name, v.name, l.supplier_sku), '[]'::jsonb)
      FROM public.product_supplier_links l
      JOIN public.products p ON p.id = l.product_id
      JOIN public.vendors v ON v.id = l.vendor_id
      WHERE (p_product_id IS NULL OR l.product_id = p_product_id)
        AND (p_vendor_id IS NULL OR l.vendor_id = p_vendor_id)
    ),
    'imports', (
      SELECT COALESCE(jsonb_agg(import_row ORDER BY (import_row->>'created_at') DESC), '[]'::jsonb)
      FROM (
        SELECT jsonb_build_object(
          'id', i.id,
          'vendor_id', i.vendor_id,
          'vendor_name', v.name,
          'document_date', i.document_date,
          'ingestion_method', i.ingestion_method,
          'status', i.status,
          'row_count', i.row_count,
          'eligible_row_count', i.eligible_row_count,
          'approved_observation_count', i.approved_observation_count,
          'source_document_name', i.source_document_name,
          'created_at', i.created_at
        ) AS import_row
        FROM public.supplier_price_imports i
        JOIN public.vendors v ON v.id = i.vendor_id
        WHERE (p_vendor_id IS NULL OR i.vendor_id = p_vendor_id)
        ORDER BY i.created_at DESC
        LIMIT 50
      ) recent
    ),
    'aliases', CASE WHEN public.is_admin() THEN (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', a.id,
        'vendor_id', a.vendor_id,
        'proposed_vendor_id', a.proposed_vendor_id,
        'alias_raw', a.alias_raw,
        'alias_normalized', a.alias_normalized,
        'alias_display', a.alias_display,
        'source', a.source,
        'review_status', a.review_status,
        'review_note', a.review_note,
        'created_at', a.created_at
      ) ORDER BY a.review_status, a.alias_display), '[]'::jsonb)
      FROM public.vendor_aliases a
    ) ELSE '[]'::jsonb END,
    'evidence', public.get_supplier_market_evidence(
      CASE WHEN p_product_id IS NULL THEN NULL ELSE ARRAY[p_product_id] END
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_supplier_pricing_workspace"("p_product_id" "uuid", "p_vendor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_quote_sheet"("p_vendor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_vendor public.vendors%ROWTYPE;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'ADMIN_OR_SALES_REQUIRED';
  END IF;

  SELECT * INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'VENDOR_NOT_FOUND'; END IF;

  SELECT jsonb_build_object(
    'format_version', 'crx-supplier-quote-phase1b-v1',
    'vendor_id', v_vendor.id,
    'vendor_name', v_vendor.name,
    'generated_at', now(),
    'rows', COALESCE(jsonb_agg(jsonb_build_object(
      'product_supplier_link_id', l.id,
      'product_id', p.id,
      'vendor_id', l.vendor_id,
      'supplier_sku', l.supplier_sku,
      'product_name', p.product_name,
      'supplier_product_name', l.supplier_product_name,
      'supplier_uom', l.supplier_uom,
      'supplier_pack_description', l.supplier_pack_description,
      'inventory_unit', p.inventory_unit,
      'inventory_units_per_supplier_unit', l.inventory_units_per_supplier_unit,
      'comparison_status', l.comparison_status,
      'last_cost', CASE WHEN latest.cost_cents IS NULL THEN NULL ELSE public._format_pricing_dollars(latest.cost_cents) END,
      'last_effective_date', latest.effective_from,
      'new_cost', '',
      'effective_date', current_date,
      'price_kind', 'quote'
    ) ORDER BY p.product_name, l.supplier_sku), '[]'::jsonb)
  ) INTO v_result
  FROM public.product_supplier_links l
  JOIN public.products p ON p.id = l.product_id AND p.is_active
  LEFT JOIN LATERAL (
    SELECT o.cost_cents, o.effective_from
    FROM public.supplier_price_observations o
    WHERE o.product_supplier_link_id = l.id
      AND o.effective_from <= current_date
      AND (o.effective_to IS NULL OR o.effective_to >= current_date)
      AND NOT EXISTS (
        SELECT 1
        FROM public.supplier_price_observations correction
        WHERE correction.supersedes_observation_id = o.id
      )
    ORDER BY o.effective_from DESC, o.observed_at DESC, o.id DESC
    LIMIT 1
  ) latest ON true
  WHERE l.vendor_id = p_vendor_id
    AND l.is_active
    AND l.is_reusable;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_supplier_quote_sheet"("p_vendor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_team_board_deliveries"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_role text;
  v_today date := CURRENT_DATE;
  v_tomorrow date := CURRENT_DATE + 1;
  v_result jsonb;
BEGIN
  SELECT role INTO v_role FROM profiles WHERE id = v_user_id;

  SELECT jsonb_build_object(
    'today', COALESCE((
      SELECT jsonb_agg(row_to_json(d.*)::jsonb ORDER BY d.scheduled_time NULLS LAST, d.priority_sort)
      FROM (
        SELECT
          del.id,
          del.delivery_number,
          del.status,
          del.priority,
          CASE del.priority
            WHEN 'urgent' THEN 0
            WHEN 'high' THEN 1
            WHEN 'medium' THEN 2
            WHEN 'low' THEN 3
            ELSE 4
          END AS priority_sort,
          del.scheduled_date,
          del.scheduled_time,
          ca.address_line AS delivery_address,
          del.delivery_notes,
          c.farm_name AS customer_name,
          p.full_name AS driver_name,
          del.assigned_driver,
          (SELECT count(*) FROM delivery_items di WHERE di.delivery_id = del.id) AS item_count
        FROM deliveries del
        JOIN customers c ON c.id = del.customer_id
        LEFT JOIN customer_addresses ca ON ca.id = del.delivery_address_id
        LEFT JOIN profiles p ON p.id = del.assigned_driver
        WHERE del.scheduled_date = v_today
          AND del.status IN ('scheduled', 'in_progress')
          AND (v_role IN ('admin', 'sales_rep') OR del.assigned_driver = v_user_id)
      ) d
    ), '[]'::jsonb),
    'tomorrow', COALESCE((
      SELECT jsonb_agg(row_to_json(d.*)::jsonb ORDER BY d.scheduled_time NULLS LAST, d.priority_sort)
      FROM (
        SELECT
          del.id,
          del.delivery_number,
          del.status,
          del.priority,
          CASE del.priority
            WHEN 'urgent' THEN 0
            WHEN 'high' THEN 1
            WHEN 'medium' THEN 2
            WHEN 'low' THEN 3
            ELSE 4
          END AS priority_sort,
          del.scheduled_date,
          del.scheduled_time,
          ca.address_line AS delivery_address,
          c.farm_name AS customer_name,
          p.full_name AS driver_name,
          del.assigned_driver
        FROM deliveries del
        JOIN customers c ON c.id = del.customer_id
        LEFT JOIN customer_addresses ca ON ca.id = del.delivery_address_id
        LEFT JOIN profiles p ON p.id = del.assigned_driver
        WHERE del.scheduled_date = v_tomorrow
          AND del.status = 'scheduled'
          AND (v_role IN ('admin', 'sales_rep') OR del.assigned_driver = v_user_id)
      ) d
    ), '[]'::jsonb),
    'unassigned_count', (
      SELECT count(*)
      FROM deliveries
      WHERE scheduled_date = v_today
        AND status = 'scheduled'
        AND assigned_driver IS NULL
    ),
    'today_total', (
      SELECT count(*)
      FROM deliveries
      WHERE scheduled_date = v_today
        AND status IN ('scheduled', 'in_progress')
        AND (v_role IN ('admin', 'sales_rep') OR assigned_driver = v_user_id)
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_team_board_deliveries"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_team_workload"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_today date := current_date;
BEGIN
  SELECT jsonb_agg(row_to_json(t) ORDER BY t.full_name)
  INTO v_result
  FROM (
    SELECT
      p.id,
      p.full_name,
      p.role,
      (SELECT count(*)
       FROM team_notes tn
       WHERE tn.assigned_to = p.id
         AND tn.is_completed = false
         AND tn.deleted_at IS NULL
      )::int AS open_tasks,
      (SELECT count(*)
       FROM team_notes tn
       WHERE tn.assigned_to = p.id
         AND tn.is_completed = false
         AND tn.deleted_at IS NULL
         AND tn.due_date < v_today
      )::int AS overdue_tasks,
      (SELECT count(*)
       FROM deliveries d
       WHERE d.assigned_driver = p.id
         AND d.scheduled_date = v_today
         AND d.status IN ('scheduled', 'in_progress')
      )::int AS today_deliveries,
      (SELECT count(*)
       FROM deliveries d
       WHERE d.assigned_driver = p.id
         AND d.scheduled_date >= date_trunc('week', v_today)
         AND d.scheduled_date < date_trunc('week', v_today) + interval '7 days'
         AND d.status IN ('scheduled', 'in_progress', 'completed')
      )::int AS week_deliveries
    FROM profiles p
    WHERE p.is_active = true
  ) t;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_team_workload"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_watchdog_flags"("p_job_id" "uuid" DEFAULT NULL::"uuid", "p_invoice_id" "uuid" DEFAULT NULL::"uuid", "p_flag_type" "text" DEFAULT NULL::"text", "p_include_dismissed" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "flag_type" "text", "severity" "text", "entity_type" "text", "entity_id" "uuid", "job_id" "uuid", "invoice_id" "uuid", "product_id" "uuid", "field_id" "uuid", "customer_id" "uuid", "message" "text", "detail" "jsonb", "created_at" timestamp with time zone, "is_dismissed" boolean, "dismissed_at" timestamp with time zone, "dismissed_by" "uuid", "resolution" "text", "dismiss_note" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Gate: authenticated admin or sales_rep only
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'WATCHDOG_ACCESS_DENIED: admin or sales_rep role required';
  END IF;

  RETURN QUERY
  SELECT
    wf.id,
    wf.flag_type,
    wf.severity,
    wf.entity_type,
    wf.entity_id,
    wf.job_id,
    wf.invoice_id,
    wf.product_id,
    wf.field_id,
    wf.customer_id,
    wf.message,
    wf.detail,
    wf.created_at,
    (wd.id IS NOT NULL)  AS is_dismissed,
    wd.dismissed_at,
    wd.dismissed_by,
    wd.resolution,
    wd.note              AS dismiss_note
  FROM watchdog_flags wf
  LEFT JOIN LATERAL (
    SELECT d.id, d.dismissed_at, d.dismissed_by, d.resolution, d.note
    FROM watchdog_flag_dismissals d
    WHERE d.flag_id = wf.id
    ORDER BY d.dismissed_at DESC
    LIMIT 1
  ) wd ON true
  WHERE
    (p_job_id     IS NULL OR wf.job_id     = p_job_id)
    AND (p_invoice_id IS NULL OR wf.invoice_id = p_invoice_id)
    AND (p_flag_type  IS NULL OR wf.flag_type  = p_flag_type)
    AND (p_include_dismissed OR wd.id IS NULL)
  ORDER BY wf.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_watchdog_flags"("p_job_id" "uuid", "p_invoice_id" "uuid", "p_flag_type" "text", "p_include_dismissed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_yesterday_delivery_recap"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_role text;
  v_yesterday date := CURRENT_DATE - 1;
  v_result jsonb;
BEGIN
  SELECT role INTO v_role FROM profiles WHERE id = v_user_id;

  SELECT jsonb_build_object(
    'completed', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', del.id,
        'delivery_number', del.delivery_number,
        'customer_name', c.farm_name,
        'driver_name', p.full_name,
        'completed_at', del.updated_at,
        'item_count', (SELECT count(*) FROM delivery_items di WHERE di.delivery_id = del.id),
        'has_issues', (del.issue_type IS NOT NULL)
      ) ORDER BY del.updated_at)
      FROM deliveries del
      JOIN customers c ON c.id = del.customer_id
      LEFT JOIN profiles p ON p.id = del.assigned_driver
      WHERE del.scheduled_date = v_yesterday
        AND del.status = 'completed'
        AND (v_role IN ('admin', 'sales_rep') OR del.assigned_driver = v_user_id)
    ), '[]'::jsonb),
    'issues', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', del.id,
        'delivery_number', del.delivery_number,
        'customer_name', c.farm_name,
        'driver_name', p.full_name,
        'issue_type', del.issue_type,
        'issue_description', del.issue_notes
      ))
      FROM deliveries del
      JOIN customers c ON c.id = del.customer_id
      LEFT JOIN profiles p ON p.id = del.assigned_driver
      WHERE del.scheduled_date = v_yesterday
        AND del.issue_type IS NOT NULL
        AND (v_role IN ('admin', 'sales_rep') OR del.assigned_driver = v_user_id)
    ), '[]'::jsonb),
    'summary', jsonb_build_object(
      'total_completed', (
        SELECT count(*) FROM deliveries
        WHERE scheduled_date = v_yesterday AND status = 'completed'
        AND (v_role IN ('admin', 'sales_rep') OR assigned_driver = v_user_id)
      ),
      'total_with_issues', (
        SELECT count(*) FROM deliveries
        WHERE scheduled_date = v_yesterday AND issue_type IS NOT NULL
        AND (v_role IN ('admin', 'sales_rep') OR assigned_driver = v_user_id)
      ),
      'total_cancelled', (
        SELECT count(*) FROM deliveries
        WHERE scheduled_date = v_yesterday AND status IN ('cancelled', 'voided')
        AND (v_role IN ('admin', 'sales_rep') OR assigned_driver = v_user_id)
      )
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_yesterday_delivery_recap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."global_search"("p_query" "text", "p_limit" integer DEFAULT 5) RETURNS TABLE("entity_type" "text", "id" "uuid", "primary_text" "text", "secondary_text" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_pattern text;
  v_escaped text;
BEGIN
  IF length(trim(p_query)) < 2 THEN
    RETURN;
  END IF;

  v_escaped := regexp_replace(trim(p_query), '([%_\\])', E'\\\\\\1', 'g');
  v_pattern := '%' || v_escaped || '%';

  RETURN QUERY
  (
    SELECT
      'customer'::text AS entity_type,
      c.id,
      c.farm_name AS primary_text,
      COALESCE(c.contact_name, '')::text AS secondary_text
    FROM customers c
    WHERE c.is_active = true
      AND (c.farm_name ILIKE v_pattern OR c.contact_name ILIKE v_pattern OR c.account_number ILIKE v_pattern)
    ORDER BY c.farm_name
    LIMIT p_limit
  )
  UNION ALL
  (
    SELECT
      'order'::text AS entity_type,
      o.id,
      o.order_number AS primary_text,
      COALESCE(c2.farm_name, '')::text AS secondary_text
    FROM orders o
    LEFT JOIN customers c2 ON c2.id = o.customer_id
    WHERE o.order_number ILIKE v_pattern
    ORDER BY o.created_at DESC
    LIMIT p_limit
  )
  UNION ALL
  (
    SELECT
      'invoice'::text AS entity_type,
      i.id,
      i.invoice_number AS primary_text,
      COALESCE(c3.farm_name, '')::text AS secondary_text
    FROM invoices i
    LEFT JOIN customers c3 ON c3.id = i.customer_id
    WHERE i.invoice_number ILIKE v_pattern
    ORDER BY i.created_at DESC
    LIMIT p_limit
  )
  UNION ALL
  (
    SELECT
      'delivery'::text AS entity_type,
      d.id,
      d.delivery_number AS primary_text,
      COALESCE(c4.farm_name, '')::text AS secondary_text
    FROM deliveries d
    LEFT JOIN customers c4 ON c4.id = d.customer_id
    WHERE d.delivery_number ILIKE v_pattern
    ORDER BY d.created_at DESC
    LIMIT p_limit
  )
  UNION ALL
  (
    SELECT
      'product'::text AS entity_type,
      p.id,
      p.product_name AS primary_text,
      COALESCE(p.category, '')::text AS secondary_text
    FROM products p
    WHERE p.is_active = true
      AND (p.product_name ILIKE v_pattern OR p.sku ILIKE v_pattern)
    ORDER BY p.product_name
    LIMIT p_limit
  );
END;
$$;


ALTER FUNCTION "public"."global_search"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_and_version_product_pricing"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_core_changed boolean;
  v_per_acre_changed boolean;
  v_actor uuid;
  v_change_set_id uuid;
  v_source text;
BEGIN
  IF NEW.current_cost::text IN ('NaN', 'Infinity', '-Infinity')
     OR NEW.tier1_price::text IN ('NaN', 'Infinity', '-Infinity')
     OR NEW.tier2_price::text IN ('NaN', 'Infinity', '-Infinity')
     OR NEW.tier3_price::text IN ('NaN', 'Infinity', '-Infinity')
     OR round(NEW.current_cost, 2) IS DISTINCT FROM NEW.current_cost
     OR round(NEW.tier1_price, 2) IS DISTINCT FROM NEW.tier1_price
     OR round(NEW.tier2_price, 2) IS DISTINCT FROM NEW.tier2_price
     OR round(NEW.tier3_price, 2) IS DISTINCT FROM NEW.tier3_price THEN
    RAISE EXCEPTION 'PRODUCT_PRICING_CENT_SCALE_INVALID';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.pricing_version := 1;
    RETURN NEW;
  END IF;
  IF NEW.pricing_version IS DISTINCT FROM OLD.pricing_version THEN
    RAISE EXCEPTION 'PRODUCT_PRICING_VERSION_MANAGED_BY_DATABASE';
  END IF;
  v_core_changed := OLD.current_cost IS DISTINCT FROM NEW.current_cost
    OR OLD.tier1_margin IS DISTINCT FROM NEW.tier1_margin
    OR OLD.tier2_margin IS DISTINCT FROM NEW.tier2_margin
    OR OLD.tier3_margin IS DISTINCT FROM NEW.tier3_margin
    OR OLD.tier1_price IS DISTINCT FROM NEW.tier1_price
    OR OLD.tier2_price IS DISTINCT FROM NEW.tier2_price
    OR OLD.tier3_price IS DISTINCT FROM NEW.tier3_price
    OR OLD.tier1_gross_margin IS DISTINCT FROM NEW.tier1_gross_margin
    OR OLD.tier2_gross_margin IS DISTINCT FROM NEW.tier2_gross_margin
    OR OLD.tier3_gross_margin IS DISTINCT FROM NEW.tier3_gross_margin;
  v_per_acre_changed := OLD.tier1_price_per_acre IS DISTINCT FROM NEW.tier1_price_per_acre
    OR OLD.tier2_price_per_acre IS DISTINCT FROM NEW.tier2_price_per_acre
    OR OLD.tier3_price_per_acre IS DISTINCT FROM NEW.tier3_price_per_acre;
  IF v_core_changed AND current_setting('crx.pricing_authorized', true) = 'phase1a' THEN
    v_actor := NULLIF(current_setting('crx.pricing_actor', true), '')::uuid;
    v_change_set_id := NULLIF(current_setting('crx.pricing_change_set_id', true), '')::uuid;
    v_source := NULLIF(current_setting('crx.pricing_source', true), '');
    IF v_actor IS NULL OR v_actor IS DISTINCT FROM auth.uid()
       OR v_source NOT IN ('pricing_worksheet', 'product_page', 'products_inline')
       OR NOT public.is_admin()
       OR NOT EXISTS (
         SELECT 1 FROM public.pricing_change_sets c JOIN public.pricing_change_set_rows r
           ON r.change_set_id = c.id
         WHERE c.id = v_change_set_id AND c.created_by = v_actor
           AND c.source = v_source AND c.status = 'previewed' AND r.product_id = NEW.id
       ) THEN
      RAISE EXCEPTION 'PRODUCT_PRICING_CONTEXT_INVALID';
    END IF;
  END IF;
  IF v_core_changed OR v_per_acre_changed THEN
    NEW.pricing_version := OLD.pricing_version + 1;
  ELSE
    NEW.pricing_version := OLD.pricing_version;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_and_version_product_pricing"() OWNER TO "postgres";


