CREATE OR REPLACE FUNCTION "public"."guard_customer_document_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.id IS DISTINCT FROM NEW.id
     OR OLD.customer_id IS DISTINCT FROM NEW.customer_id
     OR OLD.contact_id IS DISTINCT FROM NEW.contact_id
     OR OLD.storage_path IS DISTINCT FROM NEW.storage_path
     OR OLD.filename IS DISTINCT FROM NEW.filename
     OR OLD.mime_type IS DISTINCT FROM NEW.mime_type
     OR OLD.size_bytes IS DISTINCT FROM NEW.size_bytes
     OR OLD.uploaded_by IS DISTINCT FROM NEW.uploaded_by
     OR OLD.source IS DISTINCT FROM NEW.source
     OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN
    RAISE EXCEPTION
      'customer document identity and provenance are immutable';
  END IF;

  IF OLD.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'soft-deleted customer documents cannot be modified';
  END IF;

  IF NEW.deleted_at IS NULL AND NEW.deleted_by IS NOT NULL THEN
    RAISE EXCEPTION 'deleted_by requires deleted_at';
  END IF;

  IF NEW.deleted_at IS NOT NULL
     AND NEW.deleted_by IS DISTINCT FROM (SELECT auth.uid()) THEN
    RAISE EXCEPTION 'soft-delete attribution must match the acting user';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_customer_document_update"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guard_customer_document_update"() IS 'Makes document identity and provenance immutable and enforces one-way attributable soft deletes.';



CREATE OR REPLACE FUNCTION "public"."guard_customer_fact_provenance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.customer_id IS DISTINCT FROM NEW.customer_id
     OR OLD.category IS DISTINCT FROM NEW.category
     OR OLD.fact_key IS DISTINCT FROM NEW.fact_key
     OR OLD.source IS DISTINCT FROM NEW.source
     OR OLD.source_interaction_id IS DISTINCT FROM NEW.source_interaction_id
     OR OLD.entered_by IS DISTINCT FROM NEW.entered_by
     OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN
    RAISE EXCEPTION 'customer fact provenance is immutable; create a superseding fact instead';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_customer_fact_provenance"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guard_customer_fact_provenance"() IS 'Blocks all provenance changes to customer facts; corrections require supersession.';



