CREATE OR REPLACE FUNCTION "public"."increment_customer_prepay"("p_customer_id" "uuid", "p_amount_cents" bigint, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing jsonb;
  v_actor    uuid;
BEGIN
  -- Codex P1 fix: gate on auth.uid() + admin/sales_rep role before mutating.
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'increment_customer_prepay');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;

  UPDATE customers
  SET prepay_balance_cents = COALESCE(prepay_balance_cents, 0) + p_amount_cents
  WHERE id = p_customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Customer % not found', p_customer_id;
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(
      p_idempotency_key,
      'increment_customer_prepay',
      jsonb_build_object('success', true, 'customer_id', p_customer_id, 'amount_cents', p_amount_cents)
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."increment_customer_prepay"("p_customer_id" "uuid", "p_amount_cents" bigint, "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."increment_customer_prepay"("p_customer_id" "uuid", "p_amount_cents" bigint, "p_idempotency_key" "text") IS 'Internal helper for prepay flows. Not callable from PostgREST (REVOKEd from anon/authenticated). Other SECURITY DEFINER callers invoke via owner-bypass. Body still gates on auth.uid() + admin/sales_rep role for defense in depth. Codex P1 fix for PR #59 (2026-05-16).';



