CREATE OR REPLACE FUNCTION "public"."issue_return_credit"("p_return_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_order_id uuid;
  v_customer_id uuid;
  v_order_customer_id uuid;
  v_order_status text;
  v_is_legacy_unlinked boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_actor_id IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'issue_return_credit');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT r.order_id, r.customer_id INTO v_order_id, v_customer_id
  FROM public.returns r
  WHERE r.id = p_return_id AND r.status = 'received'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'RETURN_NOT_CREDITABLE'; END IF;

  IF v_order_id IS NULL THEN
    -- The same exact production record may be credited after receive_return
    -- advances it to received. No other source-free/caller-priced row qualifies.
    v_is_legacy_unlinked := p_return_id = '0cb556ed-467a-4949-866d-8d9edbb09522'::uuid
      AND EXISTS (
        SELECT 1
        FROM public.returns r
        WHERE r.id = p_return_id
          AND r.return_number = 'RMA-2026-0001'
          AND r.customer_id = 'df6087cb-232f-4962-bb33-c74580a06935'::uuid
          AND r.requested_by = '22c1fc50-4d2a-4baa-8ff8-341c0c7edd4f'::uuid
          AND r.approved_by = '22c1fc50-4d2a-4baa-8ff8-341c0c7edd4f'::uuid
          AND r.reason = 'overstock'
          AND r.created_at = timestamptz '2026-04-30 20:48:18.967975+00'
          AND r.requested_at = timestamptz '2026-04-30 20:48:18.967975+00'
          AND r.approved_at = timestamptz '2026-07-10 16:45:29.044351+00'
          AND r.total_credit_cents = 0
      )
      AND 1 = (
        SELECT count(*) FROM public.return_items ri WHERE ri.return_id = p_return_id
      )
      AND EXISTS (
        SELECT 1
        FROM public.return_items ri
        WHERE ri.return_id = p_return_id
          AND ri.id = 'c4f6cc7d-0bbd-4c25-8bc0-c2c9e84aaadd'::uuid
          AND ri.order_item_id IS NULL
          AND ri.product_id = 'fad3ea45-cd8c-4bb8-b0ce-8a515941586c'::uuid
          AND ri.product_name = 'Gen Capture LFR: (Batallion LFC, Seguro) - 2.5 Gal'
          AND ri.quantity = 15.00
          AND ri.unit = 'ea'
          AND ri.unit_price_cents = 7597
          AND ri.extended_cents = 113955
          AND ri.condition = 'unopened'
          AND ri.restock = true
          AND ri.sort_order = 0
          AND ri.notes IS NULL
          AND ri.created_at = timestamptz '2026-04-30 20:48:19.173027+00'
      );
    IF NOT v_is_legacy_unlinked THEN
      RAISE EXCEPTION 'RETURN_SOURCE_NOT_VERIFIED';
    END IF;
  ELSE
    SELECT o.status, o.customer_id INTO v_order_status, v_order_customer_id
    FROM public.orders o
    WHERE o.id = v_order_id AND o.deleted_at IS NULL
    FOR UPDATE;
    IF NOT FOUND OR v_order_status IN ('voided', 'cancelled') THEN
      RAISE EXCEPTION 'RETURN_SOURCE_ORDER_INACTIVE';
    END IF;
    IF v_order_customer_id IS DISTINCT FROM v_customer_id THEN
      RAISE EXCEPTION 'RETURN_ORDER_CUSTOMER_MISMATCH';
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.return_items ri WHERE ri.return_id = p_return_id
    ) OR EXISTS (
      SELECT 1 FROM public.return_items ri
      LEFT JOIN public.order_items oi
        ON oi.id = ri.order_item_id AND oi.order_id = v_order_id
      WHERE ri.return_id = p_return_id
        AND (
          ri.order_item_id IS NULL
          OR oi.id IS NULL
          OR oi.price_per_unit IS NULL
          OR ri.product_id IS DISTINCT FROM oi.product_id
          OR ri.unit IS DISTINCT FROM coalesce(oi.unit_size, 'ea')
          OR ri.quantity <= 0
          OR ri.quantity > coalesce(oi.quantity_delivered, 0)
          OR ri.unit_price_cents IS DISTINCT FROM round(oi.price_per_unit * 100)::bigint
          OR ri.extended_cents IS DISTINCT FROM round(ri.quantity * oi.price_per_unit * 100)::bigint
        )
    ) OR (
      SELECT count(*) <> count(DISTINCT ri.order_item_id)
      FROM public.return_items ri
      WHERE ri.return_id = p_return_id
    ) OR EXISTS (
      SELECT 1
      FROM public.return_items current_ri
      JOIN public.order_items oi
        ON oi.id = current_ri.order_item_id AND oi.order_id = v_order_id
      WHERE current_ri.return_id = p_return_id
        AND (
          SELECT coalesce(sum(other_ri.quantity), 0)
          FROM public.return_items other_ri
          JOIN public.returns other_r ON other_r.id = other_ri.return_id
          WHERE other_ri.order_item_id = oi.id
            AND other_r.deleted_at IS NULL
            AND other_r.status NOT IN ('rejected', 'cancelled')
        ) > coalesce(oi.quantity_delivered, 0)
    ) THEN RAISE EXCEPTION 'RETURN_SOURCE_NOT_VERIFIED'; END IF;
  END IF;

  RETURN public._issue_return_credit_impl(p_return_id, v_actor, p_idempotency_key);
END;
$$;


ALTER FUNCTION "public"."issue_return_credit"("p_return_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jobs_snapshot_commission_split"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.commission_split IS NULL AND NEW.quote_id IS NULL THEN
    SELECT c.default_commission_split INTO NEW.commission_split
    FROM public.customers c WHERE c.id = NEW.customer_id;
    -- Codex R4 P1: lock "no split" too. A customer with no default snapshots the
    -- empty sentinel {"splits":[]} (a valid no-commission split), so a default
    -- added AFTER scheduling can never re-attribute this job — NULL is reserved
    -- for pre-U8 jobs, which alone take the invoice-time fallback.
    NEW.commission_split := COALESCE(NEW.commission_split, '{"splits":[]}'::jsonb);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."jobs_snapshot_commission_split"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_blend_ticket_to_order"("p_blend_ticket_id" "uuid", "p_order_id" "uuid", "p_item_mappings" "jsonb" DEFAULT NULL::"jsonb", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_actor uuid; v_ticket blend_tickets%ROWTYPE; v_order orders%ROWTYPE; v_mapping jsonb; v_count int := 0; v_product_count int; v_invalid_count int; v_result json; v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  PERFORM require_admin_or_sales_rep();

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'link_blend_ticket_to_order');
    IF v_existing IS NOT NULL THEN RETURN v_existing::json; END IF;
  END IF;

  SELECT * INTO v_ticket FROM blend_tickets
   WHERE id = p_blend_ticket_id AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('success', false, 'error', 'Blend ticket not found'); END IF;
  IF EXISTS (
    SELECT 1 FROM public.invoices
     WHERE blend_ticket_id = p_blend_ticket_id
       AND deleted_at IS NULL
       AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
  ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_ACTIVE_INVOICE_ORDER_LOCKED';
  END IF;
  IF v_ticket.order_link_status = 'linked' THEN RETURN json_build_object('success', false, 'error', 'Already linked'); END IF;
  IF v_ticket.status <> 'completed' OR v_ticket.review_status <> 'approved' THEN
    RETURN json_build_object('success', false, 'error', 'Blend ticket must be completed and approved before linking an order');
  END IF;
  IF v_ticket.payment_status <> 'unbilled' THEN
    RETURN json_build_object('success', false, 'error', 'Only an unbilled blend ticket can be linked to an order');
  END IF;
  IF v_ticket.customer_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Blend ticket has no customer assigned');
  END IF;

  SELECT * INTO v_order FROM orders
   WHERE id = p_order_id AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('success', false, 'error', 'Order not found'); END IF;
  IF v_order.status NOT IN ('confirmed', 'partially_fulfilled') THEN
    RETURN json_build_object('success', false, 'error', 'Order must be confirmed or partially fulfilled');
  END IF;
  IF v_ticket.customer_id != v_order.customer_id THEN
    RETURN json_build_object('success', false, 'error', 'Customer mismatch');
  END IF;

  SELECT count(*),
         count(*) FILTER (
           WHERE btp.product_id IS NULL
              OR btp.quantity <= 0
              OR btp.quantity::text IN ('NaN', 'Infinity', '-Infinity')
              OR p.id IS NULL
              OR p.is_active IS DISTINCT FROM true
         )
    INTO v_product_count, v_invalid_count
    FROM blend_ticket_products btp
    LEFT JOIN products p ON p.id = btp.product_id
   WHERE btp.blend_ticket_id = p_blend_ticket_id;

  IF v_product_count = 0 THEN
    RETURN json_build_object('success', false, 'error', 'Blend ticket has no products');
  END IF;
  IF v_invalid_count > 0 THEN
    RETURN json_build_object('success', false, 'error', 'Every blend-ticket product must be matched to an active catalog product with a positive quantity');
  END IF;

  IF p_item_mappings IS NOT NULL AND jsonb_array_length(p_item_mappings) > 0 THEN
    IF EXISTS (
      SELECT 1
        FROM jsonb_array_elements(p_item_mappings) mapping
        LEFT JOIN blend_ticket_products btp
          ON btp.id = NULLIF(mapping->>'blend_product_id', '')::uuid
         AND btp.blend_ticket_id = p_blend_ticket_id
        LEFT JOIN order_items oi
          ON oi.id = NULLIF(mapping->>'order_item_id', '')::uuid
         AND oi.order_id = p_order_id
       WHERE btp.id IS NULL
          OR oi.id IS NULL
          OR oi.product_id IS DISTINCT FROM btp.product_id
          OR COALESCE((mapping->>'quantity_applied')::numeric, 0) <= 0
          OR ((mapping->>'quantity_applied')::numeric)::text IN ('NaN', 'Infinity', '-Infinity')
    ) OR EXISTS (
      SELECT 1 FROM blend_ticket_products btp
       WHERE btp.blend_ticket_id = p_blend_ticket_id
         AND COALESCE((
           SELECT sum((mapping->>'quantity_applied')::numeric)
             FROM jsonb_array_elements(p_item_mappings) mapping
            WHERE NULLIF(mapping->>'blend_product_id', '')::uuid = btp.id
         ), 0) IS DISTINCT FROM btp.quantity
    ) THEN
      RETURN json_build_object('success', false, 'error', 'Mappings must identify each blend line, use matching order items, and sum to the exact finite blend quantity');
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1 FROM blend_ticket_products btp
       WHERE btp.blend_ticket_id = p_blend_ticket_id
         AND NOT EXISTS (
           SELECT 1 FROM order_items oi
            WHERE oi.order_id = p_order_id
              AND oi.product_id = btp.product_id
         )
    ) THEN
      RETURN json_build_object('success', false, 'error', 'Selected order does not contain every blend-ticket product');
    END IF;
  END IF;

  IF p_item_mappings IS NOT NULL AND jsonb_array_length(p_item_mappings) > 0 THEN
    FOR v_mapping IN SELECT * FROM jsonb_array_elements(p_item_mappings) LOOP
      INSERT INTO blend_ticket_to_order_items (
        blend_ticket_id, blend_ticket_product_id, order_item_id,
        order_id, quantity_applied, created_by
      ) VALUES (
        p_blend_ticket_id, (v_mapping->>'blend_product_id')::uuid,
        (v_mapping->>'order_item_id')::uuid, p_order_id,
        COALESCE((v_mapping->>'quantity_applied')::numeric, 0), v_actor
      )
      ON CONFLICT (blend_ticket_product_id, order_item_id) DO NOTHING;
    END LOOP;
  ELSE
    INSERT INTO blend_ticket_to_order_items (
      blend_ticket_id, blend_ticket_product_id, order_item_id,
      order_id, quantity_applied, created_by
    )
    SELECT p_blend_ticket_id, btp.id, selected_oi.id,
           p_order_id, btp.quantity, v_actor
    FROM blend_ticket_products btp
    JOIN LATERAL (
      SELECT oi.id
        FROM order_items oi
       WHERE oi.order_id = p_order_id
         AND oi.product_id = btp.product_id
       ORDER BY oi.sort_order NULLS LAST, oi.id
       LIMIT 1
    ) selected_oi ON true
    WHERE btp.blend_ticket_id = p_blend_ticket_id
      AND btp.product_id IS NOT NULL
    ON CONFLICT (blend_ticket_product_id, order_item_id) DO NOTHING;
  END IF;

  SELECT count(*) INTO v_count
    FROM blend_ticket_to_order_items
   WHERE blend_ticket_id = p_blend_ticket_id
     AND order_id = p_order_id
     AND blend_ticket_product_id IS NOT NULL;

  IF v_count < v_product_count OR EXISTS (
    SELECT 1
      FROM blend_ticket_products btp
     WHERE btp.blend_ticket_id = p_blend_ticket_id
       AND COALESCE((
         SELECT sum(link.quantity_applied)
           FROM blend_ticket_to_order_items link
           JOIN order_items oi ON oi.id = link.order_item_id
          WHERE link.blend_ticket_product_id = btp.id
            AND link.order_id = p_order_id
            AND oi.product_id = btp.product_id
       ), 0) IS DISTINCT FROM btp.quantity
  ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_ORDER_LINK_EMPTY_OR_INEXACT';
  END IF;

  UPDATE blend_tickets SET order_link_status = 'linked', updated_at = now() WHERE id = p_blend_ticket_id;

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id)
  VALUES ('blend_ticket_linked_to_order', 'Blend ticket ' || v_ticket.ticket_number || ' linked to order ' || v_order.order_number, v_actor, 'blend_ticket', p_blend_ticket_id);

  INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_user_id, actor_role, new_values, description)
  VALUES ('blend_ticket_linked', 'blend_ticket', p_blend_ticket_id, v_actor, (SELECT role FROM profiles WHERE id = v_actor), jsonb_build_object('order_id', p_order_id, 'items_linked', v_count), 'Linked blend ticket ' || v_ticket.ticket_number || ' to order ' || v_order.order_number);

  v_result := json_build_object('success', true, 'items_linked', v_count, 'order_id', p_order_id, 'order_number', v_order.order_number);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'link_blend_ticket_to_order', v_result::jsonb);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."link_blend_ticket_to_order"("p_blend_ticket_id" "uuid", "p_order_id" "uuid", "p_item_mappings" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_fields_to_parent"("p_parent_id" "uuid", "p_child_ids" "uuid"[], "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_existing jsonb; v_parent_is_child boolean;
BEGIN
  PERFORM require_admin_or_sales_rep();
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'link_fields_to_parent');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;
  SELECT EXISTS(SELECT 1 FROM fields WHERE id = p_parent_id AND parent_field_id IS NOT NULL) INTO v_parent_is_child;
  IF v_parent_is_child THEN RAISE EXCEPTION 'Cannot use a child field as a parent'; END IF;
  UPDATE fields SET parent_field_id = p_parent_id, updated_at = now() WHERE id = ANY(p_child_ids) AND id != p_parent_id;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'link_fields_to_parent', '{}'::jsonb);
  END IF;
END; $$;


ALTER FUNCTION "public"."link_fields_to_parent"("p_parent_id" "uuid", "p_child_ids" "uuid"[], "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."load_recipe_into_job"("p_job_id" "uuid", "p_recipe_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_count integer := 0;
  v_item RECORD;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  PERFORM require_admin_or_sales_rep();
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'load_recipe_into_job');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM jobs WHERE id = p_job_id AND status IN ('scheduled', 'in_progress')) THEN
    RAISE EXCEPTION 'Job not found or not editable';
  END IF;
  DELETE FROM job_chemicals WHERE job_id = p_job_id;
  FOR v_item IN
    -- >>> DELTA:load_recipe_column_fix:1
    SELECT bri.*, p.current_cost AS cost_per_unit, p.inventory_unit AS product_unit, p.rate_unit
    -- <<< DELTA:load_recipe_column_fix:1
    FROM blend_recipe_items bri JOIN products p ON p.id = bri.product_id
    -- >>> DELTA:load_recipe_column_fix:2
    WHERE bri.recipe_id = p_recipe_id ORDER BY bri.sort_order
    -- <<< DELTA:load_recipe_column_fix:2
  LOOP
    INSERT INTO job_chemicals (job_id, product_id, quantity, unit, rate_per_acre, rate_unit, cost_per_unit_cents, price_per_unit_cents, sort_order)
    VALUES (p_job_id, v_item.product_id, v_item.quantity, v_item.unit, v_item.rate_per_acre, v_item.rate_unit,
    -- >>> DELTA:recipe_price (Phase 4): seed price_per_unit_cents from the recipe
    -- item instead of the hard-coded 0 (G5). Existing recipes default 0, so this
    -- is behaviour-preserving until a recipe price is set. Live literal was `0`.
      COALESCE(v_item.cost_per_unit * 100, 0)::bigint, COALESCE(v_item.price_per_unit_cents, 0), v_item.sort_order);
    -- <<< DELTA:recipe_price
    v_count := v_count + 1;
  END LOOP;
  -- >>> DELTA:recipe_price (Codex P1): now that recipe items can carry a real
  -- price, re-roll the job's money totals from the freshly-loaded job_chemicals
  -- (same per-line safe_cents_qty math the client + transfer_job_to_invoice use).
  -- Pre-pricing the recipe always loaded at $0 so jobs.total_price_cents stayed
  -- consistent; with prices, NOT updating it here left the invoice header/shares
  -- (read from jobs.total_price_cents) out of sync with the priced line items if
  -- the user transferred without another Save. Live literal was just recipe_id.
  UPDATE jobs SET
    recipe_id = p_recipe_id,
    total_price_cents = COALESCE((SELECT SUM(safe_cents_qty(price_per_unit_cents, quantity)) FROM job_chemicals WHERE job_id = p_job_id), 0),
    total_cost_cents  = COALESCE((SELECT SUM(safe_cents_qty(cost_per_unit_cents, quantity)) FROM job_chemicals WHERE job_id = p_job_id), 0)
  WHERE id = p_job_id;
  -- <<< DELTA:recipe_price
  v_result := jsonb_build_object('success', true, 'items_loaded', v_count);
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'load_recipe_into_job', v_result);
  END IF;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."load_recipe_into_job"("p_job_id" "uuid", "p_recipe_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_comment_activity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
IF TG_OP = 'INSERT' THEN
INSERT INTO note_activity_log (note_id, user_id, action_type, changes)
VALUES (NEW.note_id, NEW.created_by, 'commented', jsonb_build_object('comment', row_to_json(NEW)));
ELSIF TG_OP = 'UPDATE' THEN
INSERT INTO note_activity_log (note_id, user_id, action_type, changes)
VALUES (NEW.note_id, NEW.created_by, 'comment_edited', jsonb_build_object('old', row_to_json(OLD), 'new', row_to_json(NEW)));
ELSIF TG_OP = 'DELETE' THEN
INSERT INTO note_activity_log (note_id, user_id, action_type, changes)
VALUES (OLD.note_id, OLD.created_by, 'comment_deleted', jsonb_build_object('comment', row_to_json(OLD)));
END IF;
RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."log_comment_activity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_customer_interaction"("p_customer_id" "uuid", "p_interaction_type" "text", "p_direction" "text", "p_occurred_at" timestamp with time zone, "p_summary" "text", "p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_duration_seconds" integer DEFAULT NULL::integer, "p_outcome" "text" DEFAULT NULL::"text", "p_follow_up_title" "text" DEFAULT NULL::"text", "p_follow_up_content" "text" DEFAULT NULL::"text", "p_follow_up_assigned_to" "uuid" DEFAULT NULL::"uuid", "p_follow_up_due_date" "date" DEFAULT NULL::"date", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_interaction_id uuid;
  v_note_id uuid;
  v_follow_up_error text;
  v_existing jsonb;
  v_result jsonb;
  v_fingerprint text;
BEGIN
  -- Argument validation mirrors the customer_interactions CHECK constraints so
  -- callers get stable machine-readable tokens instead of raw constraint
  -- errors. All checks are deterministic on the arguments, so running them
  -- before the idempotency replay cannot reject a replay of a committed call.
  IF p_customer_id IS NULL THEN
    RAISE EXCEPTION 'CUSTOMER_ID_REQUIRED';
  END IF;
  IF p_interaction_type IS NULL OR p_interaction_type NOT IN
     ('call', 'visit', 'meeting', 'text', 'email', 'voicemail') THEN
    RAISE EXCEPTION 'INTERACTION_TYPE_INVALID';
  END IF;
  IF p_direction IS NOT NULL AND p_direction NOT IN ('inbound', 'outbound') THEN
    RAISE EXCEPTION 'INTERACTION_DIRECTION_INVALID';
  END IF;
  IF p_occurred_at IS NULL THEN
    RAISE EXCEPTION 'INTERACTION_OCCURRED_AT_REQUIRED';
  END IF;
  IF p_summary IS NULL OR btrim(p_summary) = '' THEN
    RAISE EXCEPTION 'INTERACTION_SUMMARY_REQUIRED';
  END IF;
  IF p_duration_seconds IS NOT NULL AND p_duration_seconds < 0 THEN
    RAISE EXCEPTION 'INTERACTION_DURATION_INVALID';
  END IF;
  IF p_outcome IS NOT NULL AND p_outcome NOT IN
     ('connected', 'left_voicemail', 'no_answer', 'busy', 'follow_up_needed',
      'order_placed', 'resolved', 'other') THEN
    RAISE EXCEPTION 'INTERACTION_OUTCOME_INVALID';
  END IF;
  -- Follow-up fields are only meaningful with a title; fail closed rather than
  -- silently dropping an assignee or due date the caller thought was saved.
  IF p_follow_up_title IS NULL
     AND (p_follow_up_content IS NOT NULL
          OR p_follow_up_assigned_to IS NOT NULL
          OR p_follow_up_due_date IS NOT NULL) THEN
    RAISE EXCEPTION 'FOLLOW_UP_TITLE_REQUIRED';
  END IF;
  IF p_follow_up_title IS NOT NULL AND btrim(p_follow_up_title) = '' THEN
    RAISE EXCEPTION 'FOLLOW_UP_TITLE_REQUIRED';
  END IF;

  -- Authorization mirrors the customer_interactions rep INSERT policy: an
  -- active admin, or an active sales rep assigned to this customer. The row is
  -- always pinned to source = 'rep' and the caller's own identity below, so
  -- AI/web/system provenance is never writable through this path.
  IF NOT EXISTS (
       SELECT 1 FROM public.profiles p
       WHERE p.id = auth.uid() AND p.is_active
     )
     OR NOT (public.is_admin() OR (public.is_sales_rep() AND EXISTS (
       SELECT 1 FROM public.customers c
       WHERE c.id = p_customer_id
         AND c.assigned_sales_rep = auth.uid()
     ))) THEN
    RAISE EXCEPTION 'INTERACTION_ACCESS_DENIED';
  END IF;

  -- Same-customer contact check (the composite FK also enforces this; the
  -- explicit check returns a stable token instead of an FK error).
  IF p_contact_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.customer_contacts cc
    WHERE cc.id = p_contact_id AND cc.customer_id = p_customer_id
  ) THEN
    RAISE EXCEPTION 'INTERACTION_CONTACT_INVALID';
  END IF;

  -- Exact-request replay only (Codex 2026-07-17, same pattern as the bulk-PO
  -- replay fix): a replayed key must carry the same payload. If the rep edited
  -- the form between a lost-response commit and the retry, silently returning
  -- the old result would discard the edits — raise instead so the UI can tell
  -- the rep the earlier attempt already saved.
  v_fingerprint := md5(jsonb_build_object(
    'customer_id', p_customer_id,
    'contact_id', p_contact_id,
    'interaction_type', p_interaction_type,
    'direction', p_direction,
    'occurred_at', to_char(p_occurred_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'duration_seconds', p_duration_seconds,
    'outcome', p_outcome,
    'summary', btrim(p_summary),
    'follow_up_title', CASE WHEN p_follow_up_title IS NULL THEN NULL ELSE btrim(p_follow_up_title) END,
    'follow_up_content', p_follow_up_content,
    'follow_up_assigned_to', p_follow_up_assigned_to,
    'follow_up_due_date', p_follow_up_due_date
  )::text);

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'log_customer_interaction');
    IF v_existing IS NOT NULL THEN
      IF v_existing->>'request_fingerprint' IS DISTINCT FROM v_fingerprint THEN
        RAISE EXCEPTION 'INTERACTION_REPLAY_PAYLOAD_MISMATCH: this key already logged an interaction with different values';
      END IF;
      RETURN v_existing;
    END IF;
  END IF;

  INSERT INTO public.customer_interactions (
    customer_id, contact_id, interaction_type, direction, source,
    occurred_at, duration_seconds, outcome, summary,
    owner_user_id, created_by
  ) VALUES (
    p_customer_id, p_contact_id, p_interaction_type, p_direction, 'rep',
    p_occurred_at, p_duration_seconds, p_outcome, btrim(p_summary),
    auth.uid(), auth.uid()
  )
  RETURNING id INTO v_interaction_id;

  IF p_follow_up_title IS NOT NULL THEN
    -- Partial-success seam: the interaction is the record of truth. A failed
    -- follow-up insert (bad assignee, constraint change, ...) reports back in
    -- the result instead of rolling back the committed call log — the same
    -- behavior the modal had when these were two separate writes.
    BEGIN
      INSERT INTO public.team_notes (
        title, content, note_type, priority, assigned_to, due_date,
        created_by, linked_entity_type, linked_entity_id
      ) VALUES (
        btrim(p_follow_up_title), p_follow_up_content, 'todo', 'medium',
        p_follow_up_assigned_to, p_follow_up_due_date,
        auth.uid(), 'customer', p_customer_id
      )
      RETURNING id INTO v_note_id;
    EXCEPTION WHEN OTHERS THEN
      v_note_id := NULL;
      v_follow_up_error := SQLERRM;
    END;
  END IF;

  v_result := jsonb_build_object(
    'success', true,
    'interaction_id', v_interaction_id,
    'follow_up_requested', p_follow_up_title IS NOT NULL,
    'follow_up_note_id', v_note_id,
    'follow_up_error', v_follow_up_error,
    'request_fingerprint', v_fingerprint
  );
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(p_idempotency_key, 'log_customer_interaction', v_result);
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."log_customer_interaction"("p_customer_id" "uuid", "p_interaction_type" "text", "p_direction" "text", "p_occurred_at" timestamp with time zone, "p_summary" "text", "p_contact_id" "uuid", "p_duration_seconds" integer, "p_outcome" "text", "p_follow_up_title" "text", "p_follow_up_content" "text", "p_follow_up_assigned_to" "uuid", "p_follow_up_due_date" "date", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_customer_interaction"("p_customer_id" "uuid", "p_interaction_type" "text", "p_direction" "text", "p_occurred_at" timestamp with time zone, "p_summary" "text", "p_contact_id" "uuid", "p_duration_seconds" integer, "p_outcome" "text", "p_follow_up_title" "text", "p_follow_up_content" "text", "p_follow_up_assigned_to" "uuid", "p_follow_up_due_date" "date", "p_idempotency_key" "text") IS 'Idempotently logs a rep customer interaction with an optional team-note follow-up under admin-or-assigned-rep authorization; a failed follow-up returns partial success instead of rolling back the call log.';



CREATE OR REPLACE FUNCTION "public"."log_failed_notification"("p_notification_type" "text", "p_entity_type" "text" DEFAULT NULL::"text", "p_entity_id" "uuid" DEFAULT NULL::"uuid", "p_error_message" "text" DEFAULT NULL::"text", "p_payload" "jsonb" DEFAULT NULL::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing jsonb;
  v_id       uuid;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'log_failed_notification');
    IF v_existing IS NOT NULL THEN
      RETURN (v_existing->>'id')::uuid;
    END IF;
  END IF;

  INSERT INTO failed_notifications (
    notification_type, entity_type, entity_id, error_message, payload
  ) VALUES (
    p_notification_type, p_entity_type, p_entity_id, p_error_message, p_payload
  )
  RETURNING id INTO v_id;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(
      p_idempotency_key,
      'log_failed_notification',
      jsonb_build_object('id', v_id)
    );
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."log_failed_notification"("p_notification_type" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_error_message" "text", "p_payload" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_note_activity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
IF TG_OP = 'INSERT' THEN
INSERT INTO note_activity_log (note_id, user_id, action_type, changes)
VALUES (NEW.id, auth.uid(), 'created', jsonb_build_object('note', row_to_json(NEW)));

ELSIF TG_OP = 'UPDATE' THEN
IF (OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL) THEN
INSERT INTO note_activity_log (note_id, user_id, action_type, changes)
VALUES (
NEW.id,
COALESCE(auth.uid(), NEW.deleted_by),
'deleted',
jsonb_build_object('old', row_to_json(OLD), 'new', row_to_json(NEW))
);

ELSIF OLD.is_completed != NEW.is_completed THEN
INSERT INTO note_activity_log (note_id, user_id, action_type, changes)
VALUES (NEW.id, auth.uid(),
CASE WHEN NEW.is_completed THEN 'completed' ELSE 'reopened' END,
jsonb_build_object('old', row_to_json(OLD), 'new', row_to_json(NEW)));

ELSIF OLD.assigned_to IS DISTINCT FROM NEW.assigned_to THEN
INSERT INTO note_activity_log (note_id, user_id, action_type, changes)
VALUES (NEW.id, auth.uid(), 'assigned',
jsonb_build_object('old_assignee', OLD.assigned_to, 'new_assignee', NEW.assigned_to));

ELSE
INSERT INTO note_activity_log (note_id, user_id, action_type, changes)
VALUES (NEW.id, auth.uid(), 'updated',
jsonb_build_object('old', row_to_json(OLD), 'new', row_to_json(NEW)));
END IF;

ELSIF TG_OP = 'DELETE' THEN
INSERT INTO note_activity_log (note_id, user_id, action_type, changes)
VALUES (OLD.id, auth.uid(), 'deleted', jsonb_build_object('note', row_to_json(OLD)));
END IF;

RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."log_note_activity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manual_inventory_add"("p_product_id" "uuid", "p_location" "text", "p_quantity" numeric, "p_unit_size" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text", "p_unit_cost" numeric DEFAULT NULL::numeric, "p_idempotency_key" "text" DEFAULT NULL::"text", "p_reorder_point" numeric DEFAULT NULL::numeric, "p_min_stock_level" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor    uuid;
  v_existing record;
  v_product  record;
  v_note     text;
  v_idemp_existing jsonb;
  v_result   jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_idemp_existing := check_idempotency(p_idempotency_key, 'manual_inventory_add');
    IF v_idemp_existing IS NOT NULL THEN RETURN v_idemp_existing; END IF;
  END IF;

  SELECT * INTO v_existing
  FROM inventory WHERE product_id = p_product_id AND location = COALESCE(p_location, 'Main Warehouse');

  IF FOUND THEN
    RAISE EXCEPTION 'Inventory record already exists for this product at this location. Use Receive or Adjust instead.';
  END IF;

  SELECT * INTO v_product FROM products WHERE id = p_product_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  INSERT INTO inventory (product_id, location, quantity_available, unit_size, reorder_point, min_stock_level)
  VALUES (
    p_product_id,
    COALESCE(p_location, 'Main Warehouse'),
    GREATEST(p_quantity, 0),
    COALESCE(p_unit_size, v_product.unit_size),
    GREATEST(COALESCE(p_reorder_point, 0), 0),
    GREATEST(COALESCE(p_min_stock_level, 0), 0)
  );

  v_note := COALESCE(p_notes, 'Initial inventory record created with ' || p_quantity || ' units');
  IF p_unit_cost IS NOT NULL AND p_unit_cost > 0 THEN
    v_note := v_note || ' (purchased @ $' || TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM p_unit_cost::text)) || '/unit)';
  END IF;

  IF p_quantity > 0 THEN
    INSERT INTO inventory_transactions (
      product_id, transaction_type, quantity,
      to_location, performed_by, notes
    ) VALUES (
      p_product_id, 'adjusted', p_quantity,
      COALESCE(p_location, 'Main Warehouse'), v_actor,
      v_note
    );
  END IF;

  v_result := jsonb_build_object('success', true);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'manual_inventory_add', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."manual_inventory_add"("p_product_id" "uuid", "p_location" "text", "p_quantity" numeric, "p_unit_size" "text", "p_performed_by" "uuid", "p_notes" "text", "p_unit_cost" numeric, "p_idempotency_key" "text", "p_reorder_point" numeric, "p_min_stock_level" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_inventory_row_verified"("p_inventory_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_role     text;
  v_existing jsonb;
  v_row      record;
  v_result   jsonb;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key
       AND operation = 'mark_inventory_row_verified';
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by != v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_role FROM profiles WHERE id = v_actor;
  IF v_role != 'admin' THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin required';
  END IF;

  SELECT id, product_id, quantity_available, manufactured_at_delivery
    INTO v_row
    FROM inventory
   WHERE id = p_inventory_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'INVENTORY_NOT_FOUND: %', p_inventory_id;
  END IF;

  IF NOT v_row.manufactured_at_delivery THEN
    v_result := jsonb_build_object(
      'inventory_id', p_inventory_id,
      'cleared', false,
      'reason', 'already_verified'
    );
  ELSE
    UPDATE inventory
       SET manufactured_at_delivery = false,
           updated_at = now()
     WHERE id = p_inventory_id;

    INSERT INTO activity_feed (
      event_type, description, performed_by,
      related_entity_type, related_entity_id
    ) VALUES (
      'inventory_row_verified',
      'Manufactured-at-delivery flag cleared after admin physical-stock verification.',
      v_actor, 'inventory', p_inventory_id
    );

    v_result := jsonb_build_object(
      'inventory_id', p_inventory_id,
      'cleared', true,
      'reason', 'verified_by_admin'
    );
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result, expires_at)
    VALUES (p_idempotency_key, 'mark_inventory_row_verified', v_result,
            now() + interval '24 hours')
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."mark_inventory_row_verified"("p_inventory_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_overdue_invoices"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_invoice record; v_count integer := 0;
BEGIN
  -- CREDIT-APPLY: never dun a credit memo (it is 'posted' with a negative balance) or an
  -- invoice already settled to <= 0 by any lever (payments, prepay, write-off, applied credit).
  FOR v_invoice IN SELECT id, invoice_number, customer_id, due_date FROM invoices
    WHERE status = 'posted' AND due_date < CURRENT_DATE AND deleted_at IS NULL
      AND invoice_type <> 'credit_memo' AND balance_cents > 0 FOR UPDATE
  LOOP
    UPDATE invoices SET status = 'overdue', updated_at = now() WHERE id = v_invoice.id;
    INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_user_id, actor_role, new_values, description)
    VALUES ('invoice_marked_overdue', 'invoice', v_invoice.id, '22c1fc50-4d2a-4baa-8ff8-341c0c7edd4f', 'system',
      jsonb_build_object('invoice_number', v_invoice.invoice_number, 'customer_id', v_invoice.customer_id, 'due_date', v_invoice.due_date, 'marked_at', now()),
      'Invoice ' || v_invoice.invoice_number || ' auto-marked overdue (due ' || v_invoice.due_date || ')');
    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('invoices_marked_overdue', v_count, 'run_at', now());
END;
$$;


ALTER FUNCTION "public"."mark_overdue_invoices"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_quick_receive_items"("p_items" "jsonb", "p_vendor" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item jsonb;
  v_product_id uuid;
  v_qty_to_allocate numeric;
  v_lot_number text;
  v_remaining numeric;
  v_alloc_qty numeric;
  v_multiple_costs boolean;
  v_result jsonb := '[]'::jsonb;
  v_allocations jsonb;
  v_po_cursor record;
  v_product_name text;
BEGIN
  -- Verify caller is admin or sales_rep
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = (select auth.uid()) AND is_active = true
      AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- Process each item in the input array
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::uuid;
    v_qty_to_allocate := (v_item->>'quantity')::numeric;
    v_lot_number := v_item->>'lot_number';
    v_remaining := v_qty_to_allocate;
    v_allocations := '[]'::jsonb;

    IF v_qty_to_allocate <= 0 THEN CONTINUE; END IF;

    -- Get product name for display
    SELECT product_name INTO v_product_name FROM products WHERE id = v_product_id;

    -- Check if this product has multiple open POs at different costs (no-return scenario)
    SELECT count(DISTINCT poi.unit_cost) > 1 INTO v_multiple_costs
    FROM purchase_order_items poi
    JOIN purchase_orders po ON po.id = poi.purchase_order_id
    WHERE poi.product_id = v_product_id
      AND po.status IN ('submitted', 'partially_received')
      AND poi.quantity_received < poi.quantity_ordered
      AND (p_vendor IS NULL OR p_vendor = '' OR po.vendor ILIKE '%' || p_vendor || '%');

    -- Loop through open PO items for this product, oldest PO first
    FOR v_po_cursor IN
      SELECT
        poi.id AS po_item_id,
        poi.purchase_order_id,
        po.po_number,
        po.vendor AS po_vendor,
        po.submitted_date,
        poi.unit_cost,
        poi.quantity_ordered,
        poi.quantity_received,
        (poi.quantity_ordered - poi.quantity_received) AS remaining_capacity,
        poi.unit_size
      FROM purchase_order_items poi
      JOIN purchase_orders po ON po.id = poi.purchase_order_id
      WHERE poi.product_id = v_product_id
        AND po.status IN ('submitted', 'partially_received')
        AND poi.quantity_received < poi.quantity_ordered
        AND (p_vendor IS NULL OR p_vendor = '' OR po.vendor ILIKE '%' || p_vendor || '%')
      ORDER BY po.submitted_date ASC NULLS LAST, po.created_at ASC
    LOOP
      IF v_remaining <= 0 THEN EXIT; END IF;

      v_alloc_qty := LEAST(v_remaining, v_po_cursor.remaining_capacity);

      v_allocations := v_allocations || jsonb_build_object(
        'po_item_id', v_po_cursor.po_item_id,
        'purchase_order_id', v_po_cursor.purchase_order_id,
        'po_number', v_po_cursor.po_number,
        'po_vendor', v_po_cursor.po_vendor,
        'unit_cost', v_po_cursor.unit_cost,
        'quantity_allocated', v_alloc_qty,
        'po_remaining_before', v_po_cursor.remaining_capacity,
        'po_remaining_after', v_po_cursor.remaining_capacity - v_alloc_qty,
        'unit_size', v_po_cursor.unit_size
      );

      v_remaining := v_remaining - v_alloc_qty;
    END LOOP;

    v_result := v_result || jsonb_build_object(
      'product_id', v_product_id,
      'product_name', COALESCE(v_product_name, 'Unknown'),
      'quantity_requested', v_qty_to_allocate,
      'quantity_allocated', v_qty_to_allocate - v_remaining,
      'quantity_unmatched', v_remaining,
      'has_multiple_costs', COALESCE(v_multiple_costs, false),
      'lot_number', v_lot_number,
      'allocations', v_allocations
    );
  END LOOP;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."match_quick_receive_items"("p_items" "jsonb", "p_vendor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_application_record_number"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_year text;
  v_max_num int;
  v_next text;
BEGIN
  v_year := extract(year FROM current_date)::text;
  PERFORM pg_advisory_xact_lock(hashtext('next_application_record_number'));
  SELECT COALESCE(
    MAX(
      CASE
        WHEN record_number ~ ('^APP-' || v_year || '-\d+$')
        THEN CAST(split_part(record_number, '-', 3) AS int)
        ELSE 0
      END
    ),
    0
  )
  INTO v_max_num
  FROM application_records;
  v_next := 'APP-' || v_year || '-' || lpad((v_max_num + 1)::text, 4, '0');
  RETURN v_next;
END;
$_$;


ALTER FUNCTION "public"."next_application_record_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_commission_payment_number"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_year text;
  v_seq  integer;
  v_num  text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('commission_payment_number'));
  v_year := to_char(CURRENT_DATE, 'YYYY');
  SELECT COALESCE(
    MAX(
      regexp_replace(payment_number, '^CP-' || v_year || '-', '')::integer
    ), 0) + 1
    INTO v_seq
    FROM public.commission_payments
   WHERE payment_number LIKE 'CP-' || v_year || '-%';
  v_num := 'CP-' || v_year || '-' || lpad(v_seq::text, 4, '0');
  RETURN v_num;
END;
$$;


ALTER FUNCTION "public"."next_commission_payment_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_cycle_count_number"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_year text;
  v_max_num integer;
  v_next_num integer;
BEGIN
  v_year := EXTRACT(YEAR FROM CURRENT_DATE)::text;
  
  -- Advisory lock to prevent race conditions (use unique lock ID for cycle counts)
  PERFORM pg_advisory_xact_lock(8675309);
  
  -- Find the highest existing number for this year
  SELECT COALESCE(MAX(
    CASE 
      WHEN count_number ~ ('^CC-' || v_year || '-\d+$')
      THEN (regexp_replace(count_number, '^CC-' || v_year || '-', ''))::integer
      ELSE 0
    END
  ), 0) INTO v_max_num
  FROM cycle_counts
  WHERE count_number LIKE 'CC-' || v_year || '-%';
  
  v_next_num := v_max_num + 1;
  
  RETURN 'CC-' || v_year || '-' || LPAD(v_next_num::text, 5, '0');
END;
$_$;


ALTER FUNCTION "public"."next_cycle_count_number"() OWNER TO "postgres";


