CREATE OR REPLACE FUNCTION "public"."normalize_phone_e164"("raw" "text", "default_region" "text" DEFAULT 'US'::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    AS $_$
DECLARE
  digits text;
BEGIN
  IF raw IS NULL OR btrim(raw) = '' THEN
    RETURN NULL;
  END IF;

  digits := regexp_replace(raw, '[^0-9]', '', 'g');

  IF left(btrim(raw), 1) = '+'
     AND ('+' || digits) ~ '^\+[1-9][0-9]{7,14}$' THEN
    RETURN '+' || digits;
  END IF;

  IF upper(default_region) = 'US' AND digits ~ '^[0-9]{10}$' THEN
    RETURN '+1' || digits;
  END IF;

  IF digits ~ '^1[0-9]{10}$' THEN
    RETURN '+' || digits;
  END IF;

  RETURN NULL;
END;
$_$;


ALTER FUNCTION "public"."normalize_phone_e164"("raw" "text", "default_region" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_product_category"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Keep the DEPRECATED timing-category aliases from re-entering products.category. Each legacy
  -- category NAME encodes a specific application timing, so on normalization the alias's canonical
  -- timing is authoritative (direct-assign — Codex R2). use_timing is otherwise FREE-TEXT operator
  -- data (no CHECK): the trigger does NOT police or clear typed values, so a legitimate free-text
  -- timing ('Burndown', 'In-Furrow', ...) is never silently discarded (Codex R6). Trade-off: a rare
  -- cross-category re-edit can leave a cosmetically-stale tag (e.g. Foliar Fertilizer keeping a
  -- herbicide timing); that is operator-fixable via the ProductDetail Use-Timing field — preferable
  -- to silently deleting typed input. (Codex R3/R4 flagged clearing; R6 flagged the resulting
  -- data-loss — the two are in tension, and preserving operator free-text is the safer call.)
  IF NEW.category = 'Post Emergence' THEN
    NEW.category := 'Herbicide'; NEW.use_timing := 'Post-Emergence';
  ELSIF NEW.category = 'Pre-Emerge Soybean' THEN
    NEW.category := 'Herbicide'; NEW.use_timing := 'Pre-Emerge Soybean';
  ELSIF NEW.category = 'Pre-Emerge Corn' THEN
    NEW.category := 'Herbicide'; NEW.use_timing := 'Pre-Emerge Corn';
  ELSIF NEW.category = 'Volunteer Corn' THEN
    NEW.category := 'Herbicide'; NEW.use_timing := 'Volunteer Corn';
  ELSIF NEW.category = 'Range Pasture Turf' THEN
    NEW.category := 'Herbicide'; NEW.use_timing := 'Range/Pasture/Turf';
  ELSIF NEW.category IN ('Foliar Nutrition', 'Foliar Nutrition & Liquid Fertilizer') THEN
    NEW.category := 'Foliar Fertilizer'; NEW.use_timing := 'Foliar';
  ELSIF NEW.category = 'Utility' THEN
    NEW.category := 'Other';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."normalize_product_category"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_rate_unit"("p_unit" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  raw  text := lower(btrim(COALESCE(p_unit, '')));
  base text;
BEGIN
  IF raw = '' THEN RETURN NULL; END IF;
  IF raw ~ '\s*/\s*(ac|acre|acres|a)\s*$' THEN
    base := btrim(regexp_replace(raw, '\s*/\s*(ac|acre|acres|a)\s*$', ''));
  ELSIF raw ~ '\s+per\s+acre$' THEN
    base := btrim(regexp_replace(raw, '\s+per\s+acre$', ''));
  ELSIF position('/' IN raw) > 0 THEN
    -- A non-acre denominator present → keep the whole string so it can't match a bare unit.
    RETURN raw;
  ELSE
    base := raw;
  END IF;
  IF base = '' THEN RETURN NULL; END IF;
  RETURN CASE base
    WHEN 'oz'    THEN 'oz'  WHEN 'ounce'    THEN 'oz'  WHEN 'ounces'    THEN 'oz'
    WHEN 'fl oz' THEN 'oz'  WHEN 'floz'     THEN 'oz'  WHEN 'fluid ounce' THEN 'oz'
    WHEN 'pt'    THEN 'pt'  WHEN 'pint'     THEN 'pt'  WHEN 'pints'     THEN 'pt'
    WHEN 'qt'    THEN 'qt'  WHEN 'quart'    THEN 'qt'  WHEN 'quarts'    THEN 'qt'
    WHEN 'gal'   THEN 'gal' WHEN 'gallon'   THEN 'gal' WHEN 'gallons'   THEN 'gal' WHEN 'gl' THEN 'gal'
    WHEN 'lb'    THEN 'lb'  WHEN 'lbs'      THEN 'lb'  WHEN 'pound'     THEN 'lb'  WHEN 'pounds' THEN 'lb'
    WHEN 'ton'   THEN 'ton' WHEN 'tons'     THEN 'ton'
    WHEN 'g'     THEN 'g'   WHEN 'gram'     THEN 'g'   WHEN 'grams'     THEN 'g'
    WHEN 'kg'    THEN 'kg'  WHEN 'kilogram' THEN 'kg'  WHEN 'kilograms' THEN 'kg'
    WHEN 'l'     THEN 'l'   WHEN 'liter'    THEN 'l'   WHEN 'liters'    THEN 'l' WHEN 'litre' THEN 'l' WHEN 'litres' THEN 'l'
    WHEN 'ml'    THEN 'ml'
    ELSE base
  END;
END;
$_$;


ALTER FUNCTION "public"."normalize_rate_unit"("p_unit" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_vendor_alias"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT lower(
    regexp_replace(
      regexp_replace(btrim(p_value), '[[:punct:]]+', '', 'g'),
      '[[:space:]]+',
      ' ',
      'g'
    )
  )
$$;


