CREATE OR REPLACE FUNCTION "public"."notify_damaged_receiving"("p_po_number" "text", "p_items_summary" "text", "p_po_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin record;
  v_existing jsonb;
BEGIN
  -- B10 (2026-05-26): admin or sales_rep when an authenticated user calls
  -- this (receiving flow is admin/sales_rep work). service_role bypasses.
  IF auth.uid() IS NOT NULL AND NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'notify_damaged_receiving');
    IF v_existing IS NOT NULL THEN
      RETURN;
    END IF;
  END IF;

  FOR v_admin IN
    SELECT id FROM profiles WHERE role = 'admin' AND is_active = true
  LOOP
    INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
    VALUES (
      v_admin.id,
      'Damaged Items Received on ' || p_po_number,
      'Items received in non-good condition on ' || p_po_number || ': ' || p_items_summary,
      'po_damaged_received', 'purchase_order', p_po_id
    );
  END LOOP;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'notify_damaged_receiving', '{}'::jsonb);
  END IF;
END;
$$;


ALTER FUNCTION "public"."notify_damaged_receiving"("p_po_number" "text", "p_items_summary" "text", "p_po_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_mentioned_users_in_comment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
mentioned_user_id text;
commenter_name text;
note_title text;
BEGIN
SELECT full_name INTO commenter_name
FROM profiles
WHERE id = NEW.created_by;

SELECT title INTO note_title
FROM team_notes
WHERE id = NEW.note_id;

IF NEW.mentions IS NOT NULL AND array_length(NEW.mentions, 1) > 0 THEN
FOREACH mentioned_user_id IN ARRAY NEW.mentions
LOOP
INSERT INTO notifications (user_id, notification_type, title, message, related_entity_type, related_entity_id)
VALUES (
mentioned_user_id::uuid,
'mention',
'You were mentioned',
commenter_name || ' mentioned you in "' || note_title || '"',
'team_note',
NEW.note_id
);
END LOOP;
END IF;

RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_mentioned_users_in_comment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."operational_dashboard_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  result       jsonb;
  _season_start date;
  _season_end   date;
BEGIN
  -- Role check (ROLE-8)
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- Calculate season boundaries (Oct 1 – Sep 30)
  IF EXTRACT(MONTH FROM CURRENT_DATE) >= 10 THEN
    _season_start := MAKE_DATE(EXTRACT(YEAR FROM CURRENT_DATE)::int, 10, 1);
    _season_end   := MAKE_DATE(EXTRACT(YEAR FROM CURRENT_DATE)::int + 1, 9, 30);
  ELSE
    _season_start := MAKE_DATE(EXTRACT(YEAR FROM CURRENT_DATE)::int - 1, 10, 1);
    _season_end   := MAKE_DATE(EXTRACT(YEAR FROM CURRENT_DATE)::int, 9, 30);
  END IF;

  WITH
  active_orders AS (
    SELECT COUNT(*) AS cnt
    FROM orders
    WHERE status IN ('confirmed', 'partially_fulfilled')
      AND deleted_at IS NULL
  ),
  open_quotes AS (
    SELECT
      COUNT(*) FILTER (WHERE status = 'draft') AS draft_cnt,
      COUNT(*) FILTER (WHERE status = 'sent')  AS sent_cnt
    FROM quotes
  ),
  pending_deliveries AS (
    SELECT COUNT(*) AS cnt
    FROM deliveries
    WHERE status IN ('scheduled', 'in_progress')
  ),
  open_pos AS (
    SELECT COUNT(*) AS cnt
    FROM purchase_orders
    WHERE status IN ('submitted', 'partially_received')
  ),
  inv_agg AS (
    SELECT
      COALESCE(SUM(quantity_available), 0) AS total_available,
      COALESCE(SUM(quantity_prebooked), 0) AS total_prebooked
    FROM inventory
  ),
  on_order_units AS (
    SELECT
      COALESCE(SUM(poi.quantity_ordered - COALESCE(poi.quantity_received, 0)), 0) AS units,
      COUNT(DISTINCT po.id) AS po_count
    FROM purchase_order_items poi
    JOIN purchase_orders po ON po.id = poi.purchase_order_id
    WHERE po.status IN ('submitted', 'partially_received')
  ),
  committed_units AS (
    SELECT
      COALESCE(SUM(oi.quantity_remaining), 0) AS units,
      COUNT(DISTINCT o.id) AS order_count
    FROM order_items oi
    JOIN orders o ON o.id = oi.order_id
    WHERE o.status IN ('confirmed', 'partially_fulfilled')
      AND o.deleted_at IS NULL
      AND oi.quantity_remaining > 0
  ),
  upcoming AS (
    SELECT jsonb_agg(row_to_json(ud)::jsonb ORDER BY ud.scheduled_date ASC) AS arr
    FROM (
      SELECT
        d.id,
        d.delivery_number,
        d.scheduled_date::text AS scheduled_date,
        d.status,
        cust.farm_name AS customer_name,
        drv.full_name  AS driver_name,
        d.assigned_driver
      FROM deliveries d
      LEFT JOIN customers cust ON cust.id = d.customer_id
      LEFT JOIN profiles  drv  ON drv.id  = d.assigned_driver
      WHERE d.status IN ('scheduled', 'in_progress')
      ORDER BY d.scheduled_date ASC
      LIMIT 10
    ) ud
  ),
  delivery_stats AS (
    SELECT
      COUNT(*) FILTER (WHERE d.scheduled_date = CURRENT_DATE)                                AS today_count,
      COUNT(*) FILTER (WHERE d.scheduled_date BETWEEN CURRENT_DATE AND CURRENT_DATE + 6)     AS this_week_count,
      COUNT(*) FILTER (WHERE d.assigned_driver IS NULL)                                       AS unassigned_count
    FROM deliveries d
    WHERE d.status IN ('scheduled', 'in_progress')
  ),
  remainder_count AS (
    SELECT COUNT(*) AS cnt
    FROM delivery_remainders
    WHERE status = 'pending'
  ),
  quote_pipeline AS (
    SELECT
      COUNT(*) FILTER (WHERE status = 'draft')    AS draft_cnt,
      COUNT(*) FILTER (WHERE status = 'sent')     AS sent_cnt,
      COUNT(*) FILTER (WHERE status = 'accepted') AS accepted_cnt
    FROM quotes
  ),
  orders_ytd AS (
    SELECT
      COUNT(*) AS season_total,
      COUNT(*) FILTER (
        WHERE DATE_TRUNC('month', COALESCE(order_date, created_at::date)) = DATE_TRUNC('month', CURRENT_DATE)
      ) AS this_month
    FROM orders
    WHERE COALESCE(order_date, created_at::date) >= _season_start
      AND deleted_at IS NULL
  ),
  deliveries_completed AS (
    SELECT
      COUNT(*) AS season_total,
      COUNT(*) FILTER (
        WHERE DATE_TRUNC('month', completed_at) = DATE_TRUNC('month', CURRENT_DATE)
      ) AS this_month
    FROM deliveries
    WHERE status = 'completed'
      AND completed_at >= _season_start
  ),
  low_stock AS (
    SELECT COUNT(*) AS cnt
    FROM inventory
    WHERE reorder_point > 0
      AND quantity_available <= reorder_point
  ),
  driver_issues AS (
    SELECT COUNT(*) AS cnt
    FROM deliveries
    WHERE issue_type IS NOT NULL
      AND status = 'completed'
  ),
  expired_holds AS (
    SELECT COUNT(DISTINCT q.id) AS cnt
    FROM quotes q
    JOIN inventory_holds ih ON ih.source_id = q.id AND ih.is_active = true
    WHERE q.status IN ('expired', 'declined')
  ),
  cancelled_posted AS (
    SELECT COUNT(DISTINCT d.id) AS cnt
    FROM deliveries d
    JOIN orders o ON o.id = d.order_id
    JOIN invoices i ON i.order_id = o.id
    WHERE d.status = 'cancelled'
      AND i.status = 'posted'
  ),
  expiring_quotes AS (
    SELECT COUNT(*) AS cnt
    FROM quotes
    WHERE status IN ('draft', 'sent')
      AND expires_at IS NOT NULL
      AND expires_at BETWEEN CURRENT_DATE AND CURRENT_DATE + 3
  ),
  overdue_deliveries AS (
    SELECT COUNT(*) AS cnt
    FROM deliveries
    WHERE scheduled_date < CURRENT_DATE
      AND status IN ('scheduled', 'in_progress')
  ),
  pos_expected_today AS (
    SELECT COUNT(*) AS cnt
    FROM purchase_orders
    WHERE expected_delivery_date = CURRENT_DATE
      AND status IN ('submitted', 'partially_received')
  ),
  expiring_licenses AS (
    SELECT COUNT(*) AS cnt
    FROM applicator_licenses
    WHERE is_active = true
      AND expiry_date BETWEEN CURRENT_DATE AND CURRENT_DATE + 30
  ),
  monthly_activity AS (
    SELECT jsonb_agg(row_to_json(ma)::jsonb ORDER BY ma.month) AS arr
    FROM (
      SELECT
        m.month,
        COALESCE(oc.cnt, 0) AS orders_created,
        COALESCE(dc.cnt, 0) AS deliveries_completed,
        COALESCE(pr.cnt, 0) AS pos_received
      FROM (
        SELECT TO_CHAR(d, 'YYYY-MM') AS month
        FROM generate_series(
          DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '11 months',
          DATE_TRUNC('month', CURRENT_DATE),
          '1 month'::interval
        ) d
      ) m
      LEFT JOIN (
        SELECT TO_CHAR(COALESCE(order_date, created_at::date), 'YYYY-MM') AS month, COUNT(*) AS cnt
        FROM orders WHERE deleted_at IS NULL GROUP BY 1
      ) oc ON oc.month = m.month
      LEFT JOIN (
        SELECT TO_CHAR(completed_at, 'YYYY-MM') AS month, COUNT(*) AS cnt
        FROM deliveries WHERE status = 'completed' AND completed_at IS NOT NULL GROUP BY 1
      ) dc ON dc.month = m.month
      LEFT JOIN (
        SELECT TO_CHAR(received_at, 'YYYY-MM') AS month, COUNT(*) AS cnt
        FROM receiving_records GROUP BY 1
      ) pr ON pr.month = m.month
      ORDER BY m.month
    ) ma
  ),
  period_info AS (
    SELECT
      COALESCE(TO_CHAR(period_start, 'Mon YYYY'), TO_CHAR(NOW(), 'Mon YYYY')) AS name,
      COALESCE(status, 'open') AS status,
      CASE
        WHEN period_end IS NOT NULL
          THEN GREATEST(EXTRACT(DAY FROM period_end - NOW())::int, 0)
        ELSE EXTRACT(DAY FROM (DATE_TRUNC('month', NOW()) + INTERVAL '1 month' - INTERVAL '1 day') - NOW())::int
      END AS days_remaining
    FROM accounting_periods
    WHERE status = 'open'
    ORDER BY period_start DESC
    LIMIT 1
  ),
  activity AS (
    SELECT jsonb_agg(row_to_json(af)::jsonb ORDER BY af.created_at DESC) AS arr
    FROM (
      SELECT id, event_type, description, created_at
      FROM activity_feed
      ORDER BY created_at DESC
      LIMIT 15
    ) af
  ),
  team_action_items AS (
    SELECT jsonb_agg(row_to_json(ti)::jsonb) AS arr
    FROM (
      SELECT
        tn.id,
        tn.title,
        tn.priority,
        tn.due_date::text AS due_date,
        tn.note_type,
        tn.is_pinned,
        tn.assigned_to,
        p.full_name AS assignee_name
      FROM team_notes tn
      LEFT JOIN profiles p ON p.id = tn.assigned_to
      WHERE tn.is_completed = false
        AND tn.deleted_at IS NULL
        AND (
          tn.is_pinned = true
          OR tn.priority IN ('urgent', 'high')
          OR (tn.due_date IS NOT NULL AND tn.due_date < CURRENT_DATE)
          OR tn.assigned_to = auth.uid()
        )
      ORDER BY
        CASE WHEN tn.is_pinned THEN 0 ELSE 1 END,
        CASE tn.priority
          WHEN 'urgent' THEN 0
          WHEN 'high'   THEN 1
          WHEN 'medium' THEN 2
          ELSE 3
        END,
        tn.due_date NULLS LAST
      LIMIT 10
    ) ti
  )

  SELECT jsonb_build_object(
    'active_orders_count',        ao.cnt,
    'open_quotes_draft',          oq.draft_cnt,
    'open_quotes_sent',           oq.sent_cnt,
    'pending_deliveries_count',   pd.cnt,
    'open_pos_count',             op.cnt,
    'team_action_items',          COALESCE(tai.arr, '[]'::jsonb),
    'inventory_available',        ia.total_available,
    'inventory_prebooked',        ia.total_prebooked,
    'on_order_units',             oou.units,
    'on_order_po_count',          oou.po_count,
    'committed_units',            cu.units,
    'committed_order_count',      cu.order_count,
    'upcoming_deliveries',        COALESCE(ud.arr, '[]'::jsonb),
    'delivery_today',             ds.today_count,
    'delivery_this_week',         ds.this_week_count,
    'delivery_unassigned',        ds.unassigned_count,
    'delivery_remainders_count',  rc.cnt,
    'quote_pipeline_draft',       qp.draft_cnt,
    'quote_pipeline_sent',        qp.sent_cnt,
    'quote_pipeline_accepted',    qp.accepted_cnt,
    'orders_ytd_total',           oytd.season_total,
    'orders_this_month',          oytd.this_month,
    'deliveries_completed_total', dcomp.season_total,
    'deliveries_completed_this_month', dcomp.this_month,
    'low_stock_count',            ls.cnt,
    'driver_issues_count',        di.cnt,
    'expired_holds_count',        eh.cnt,
    'cancelled_posted_count',     cp.cnt,
    'expiring_quotes_count',      eq.cnt,
    'overdue_deliveries_count',   od.cnt,
    'pos_expected_today_count',   pet.cnt,
    'expiring_licenses_count',    el.cnt,
    'monthly_activity',           COALESCE(mact.arr, '[]'::jsonb),
    'season_label',               CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) >= 10
                                    THEN EXTRACT(YEAR FROM CURRENT_DATE)::int || '-' || (EXTRACT(YEAR FROM CURRENT_DATE)::int + 1)
                                    ELSE (EXTRACT(YEAR FROM CURRENT_DATE)::int - 1) || '-' || EXTRACT(YEAR FROM CURRENT_DATE)::int
                                  END,
    'season_days_remaining',      (_season_end - CURRENT_DATE),
    'season_days_elapsed',        (CURRENT_DATE - _season_start),
    'period_name',                COALESCE(pi.name, TO_CHAR(NOW(), 'Mon YYYY')),
    'period_status',              COALESCE(pi.status, 'open'),
    'period_days_remaining',      COALESCE(pi.days_remaining, 0),
    'recent_activity',            COALESCE(act.arr, '[]'::jsonb)
  ) INTO result
  FROM active_orders       ao
  CROSS JOIN open_quotes        oq
  CROSS JOIN pending_deliveries pd
  CROSS JOIN open_pos           op
  CROSS JOIN inv_agg            ia
  CROSS JOIN on_order_units     oou
  CROSS JOIN committed_units    cu
  CROSS JOIN upcoming           ud
  CROSS JOIN delivery_stats     ds
  CROSS JOIN remainder_count    rc
  CROSS JOIN quote_pipeline     qp
  CROSS JOIN orders_ytd         oytd
  CROSS JOIN deliveries_completed dcomp
  CROSS JOIN low_stock          ls
  CROSS JOIN driver_issues      di
  CROSS JOIN expired_holds      eh
  CROSS JOIN cancelled_posted   cp
  CROSS JOIN expiring_quotes    eq
  CROSS JOIN overdue_deliveries od
  CROSS JOIN pos_expected_today pet
  CROSS JOIN expiring_licenses  el
  CROSS JOIN monthly_activity   mact
  CROSS JOIN activity           act
  CROSS JOIN team_action_items  tai
  LEFT JOIN  period_info        pi ON true;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."operational_dashboard_summary"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."operational_dashboard_summary"() IS 'Returns comprehensive operational dashboard data: KPIs (orders, quotes, deliveries, POs), inventory position (floor, on-order, committed), delivery command center, sales pipeline, operational alerts (9 types), monthly activity chart, season/period info, recent activity, and team board action items.';



CREATE OR REPLACE FUNCTION "public"."parse_payment_terms_days"("p_terms" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_match text;
  v_days  numeric;                   -- numeric (arbitrary precision), NOT integer: a pasted
                                     -- giant number ('Net 9999999999') would overflow an
                                     -- integer cast and RAISE before the clamp — Codex P2.
BEGIN
  -- first run of digits anywhere in the string: 'net_30' -> 30, 'Net 30' -> 30,
  -- 'Net 45' -> 45, '2/10 Net 30' -> 2 (rare; acceptable — no such live value)
  v_match := (regexp_match(COALESCE(p_terms, ''), '(\d+)'))[1];
  IF v_match IS NULL THEN
    RETURN 30;                       -- NULL / blank / no number -> default Net 30
  END IF;
  v_days := v_match::numeric;        -- numeric never overflows on an oversized digit run
  IF v_days < 1 OR v_days > 365 THEN
    RETURN 30;                       -- clamp a typo'd/pasted 'net 3000' etc. back to default
  END IF;
  RETURN v_days::integer;            -- safe: guaranteed 1..365
END;
$$;


ALTER FUNCTION "public"."parse_payment_terms_days"("p_terms" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_commission_payment"("p_payment_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor    uuid;
  v_existing jsonb;
  v_payment  record;
  v_count    integer;
  v_item_count integer;
  v_item_total numeric;
  v_result   jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Admin access required to post a commission payment';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'post_commission_payment');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_payment FROM commission_payments WHERE id = p_payment_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Commission payment not found';
  END IF;

  IF v_payment.status = 'posted' THEN
    RAISE EXCEPTION 'Commission payment is already posted';
  END IF;
  IF v_payment.status = 'voided' THEN
    RAISE EXCEPTION 'Cannot post a voided commission payment';
  END IF;

  -- Lock and validate the immutable batch snapshot before changing any status.
  PERFORM 1
    FROM commission_payment_items
   WHERE commission_payment_id = p_payment_id
   FOR UPDATE;

  SELECT count(*), COALESCE(sum(amount), 0)
    INTO v_item_count, v_item_total
    FROM commission_payment_items
   WHERE commission_payment_id = p_payment_id;

  IF v_item_count = 0 THEN
    RAISE EXCEPTION 'COMMISSION_PAYMENT_EMPTY: commission payment has no items and cannot be posted';
  END IF;
  IF v_item_total IS DISTINCT FROM v_payment.total_amount THEN
    RAISE EXCEPTION 'COMMISSION_PAYMENT_TOTAL_MISMATCH: item total % does not match header total %',
      v_item_total, v_payment.total_amount;
  END IF;

  PERFORM check_period_open(COALESCE(v_payment.payment_date, CURRENT_DATE));

  UPDATE commission_payments
     SET status = 'posted',
         posted_by = v_actor,
         posted_at = now(),
         updated_at = now()
   WHERE id = p_payment_id;

  UPDATE commissions
     SET status = 'paid',
         paid_date = v_payment.payment_date
   WHERE id IN (
     SELECT commission_id FROM commission_payment_items
     WHERE commission_payment_id = p_payment_id
   )
     AND status = 'pending';
  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- Commission batch-freeze guard (overnight bug-hunt HIGH, 20260620): every commission
  -- in this batch must still be 'pending'. If any was cancelled/voided out from under the
  -- batch (or already paid), the count flipped will differ from the batch's item count —
  -- refuse to post the stale batch rather than resurrect a cancelled commission to 'paid'
  -- and pay its retained snapshot. The admin must void and rebuild the batch.
  IF v_count <> v_item_count THEN
    RAISE EXCEPTION 'BATCH_COMMISSION_DRIFT: % of % batched commission(s) are no longer pending (cancelled or already paid). Void and rebuild this commission payment.', (v_item_count - v_count), v_item_count;
  END IF;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id,
    actor_user_id, total_impact_cents, description
  ) VALUES (
    'commission_payment_posted', 'commission_payment', p_payment_id,
    v_actor, (v_payment.total_amount * 100)::bigint,
    'Posted commission payment ' || v_payment.payment_number ||
    ' for $' || to_char(v_payment.total_amount, 'FM999,999,990.00') ||
    ' (' || v_count || ' commissions marked paid)'
  );

  v_result := jsonb_build_object(
    'success',           true,
    'payment_id',        p_payment_id,
    'payment_number',    v_payment.payment_number,
    'commissions_paid',  v_count
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'post_commission_payment', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."post_commission_payment"("p_payment_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_invoice"("p_invoice_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_role text;
  v_customer_id uuid;
  v_cached jsonb;
  v_cached_invoice_id uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT role INTO v_actor_role
    FROM public.profiles
   WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('post_invoice:' || p_idempotency_key, 0)
    );
    v_cached := public.check_idempotency(p_idempotency_key, 'post_invoice');
    IF v_cached IS NOT NULL THEN
      v_cached_invoice_id := NULLIF(v_cached->>'invoice_id', '')::uuid;
      IF v_cached_invoice_id IS NULL
         OR v_cached_invoice_id IS DISTINCT FROM p_invoice_id THEN
        RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_CONFLICT';
      END IF;
    END IF;
  END IF;

  SELECT customer_id
    INTO v_customer_id
    FROM public.invoices
   WHERE id = p_invoice_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'INVOICE_NOT_FOUND'; END IF;

  IF v_actor_role = 'sales_rep'
     AND NOT EXISTS (
       SELECT 1
         FROM public.customers
        WHERE id = v_customer_id
          AND assigned_sales_rep = v_actor
     ) THEN
    RAISE EXCEPTION 'CUSTOMER_SCOPE_DENIED';
  END IF;

  PERFORM public._post_invoice_customer_scope_impl(
    p_invoice_id,
    p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."post_invoice"("p_invoice_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_invoice_group"("p_invoice_group_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_role text;
  v_cached jsonb;
  v_cached_group_id uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  SELECT role INTO v_actor_role
    FROM public.profiles
   WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;
  IF p_invoice_group_id IS NULL THEN
    RAISE EXCEPTION 'invoice_group_id is required';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('post_invoice_group:' || p_idempotency_key, 0)
    );
    v_cached := public.check_idempotency(
      p_idempotency_key,
      'post_invoice_group'
    );
    IF v_cached IS NOT NULL THEN
      v_cached_group_id := NULLIF(v_cached->>'invoice_group_id', '')::uuid;
      IF v_cached_group_id IS NULL
         OR v_cached_group_id IS DISTINCT FROM p_invoice_group_id THEN
        RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_CONFLICT';
      END IF;
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_invoice_group_id::text, 0));
  PERFORM 1
    FROM public.invoices
   WHERE invoice_group_id = p_invoice_group_id
     AND deleted_at IS NULL
   ORDER BY id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No invoices found in group %', p_invoice_group_id;
  END IF;

  IF v_actor_role = 'sales_rep'
     AND EXISTS (
       SELECT 1
         FROM public.invoices invoice_row
         LEFT JOIN public.customers customer_row
           ON customer_row.id = invoice_row.customer_id
        WHERE invoice_row.invoice_group_id = p_invoice_group_id
          AND invoice_row.deleted_at IS NULL
          AND customer_row.assigned_sales_rep IS DISTINCT FROM v_actor
     ) THEN
    RAISE EXCEPTION 'CUSTOMER_SCOPE_DENIED';
  END IF;

  RETURN public._post_invoice_group_customer_scope_impl(
    p_invoice_group_id,
    p_performed_by,
    p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."post_invoice_group"("p_invoice_group_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_oifa_edit_after_post"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old_item_id  uuid;
  v_new_item_id  uuid;
  v_order_ids    uuid[];
  v_blocking_inv text;
BEGIN
  -- Branch before touching NEW/OLD: one of those records is unassigned on
  -- INSERT/DELETE triggers.
  IF TG_OP = 'INSERT' THEN
    v_new_item_id := NEW.order_item_id;
  ELSIF TG_OP = 'DELETE' THEN
    v_old_item_id := OLD.order_item_id;
  ELSE
    v_old_item_id := OLD.order_item_id;
    v_new_item_id := NEW.order_item_id;
  END IF;

  -- CONCURRENCY FIX: lock every OLD/NEW parent item before the invoice read.
  -- The FK's own KEY SHARE arrives after this BEFORE trigger, too late to close
  -- the race; this explicit stable-order lock is the shared serialization point.
  PERFORM 1
    FROM order_items oi
   WHERE oi.id = ANY (
     array_remove(ARRAY[v_old_item_id, v_new_item_id]::uuid[], NULL)
   )
   ORDER BY oi.id
   FOR KEY SHARE;

  SELECT array_agg(DISTINCT oi.order_id ORDER BY oi.order_id)
    INTO v_order_ids
    FROM order_items oi
   WHERE oi.id = ANY (
     array_remove(ARRAY[v_old_item_id, v_new_item_id]::uuid[], NULL)
   );

  IF COALESCE(cardinality(v_order_ids), 0) = 0 THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  SELECT i.invoice_number
    INTO v_blocking_inv
    FROM invoices i
   WHERE i.order_id = ANY (v_order_ids)
     AND i.deleted_at IS NULL
     AND i.status NOT IN ('voided', 'cancelled')
   ORDER BY i.created_at, i.id
   LIMIT 1;

  IF v_blocking_inv IS NOT NULL THEN
    RAISE EXCEPTION
      'ORDER_ALLOCATION_INVOICE_CONFLICT: cannot modify field allocation because active invoice % already covers the order; delete/void the draft or reverse the posted invoice first',
      v_blocking_inv
      USING ERRCODE = 'check_violation';
  END IF;

  IF (TG_OP = 'DELETE') THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_oifa_edit_after_post"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_order_shares_edit_after_post"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order_id     uuid;
  v_blocking_inv text;
BEGIN
  v_order_id := COALESCE(NEW.order_id, OLD.order_id);

  SELECT i.invoice_number
    INTO v_blocking_inv
    FROM invoices i
   WHERE i.order_id    = v_order_id
     AND i.deleted_at IS NULL
     AND i.status      IN ('posted', 'paid', 'overdue')
   ORDER BY i.created_at
   LIMIT 1;

  IF v_blocking_inv IS NOT NULL THEN
    RAISE EXCEPTION
      'Cannot modify bill split — invoice % is already posted. Void the invoice first or adjust the split on a new order.',
      v_blocking_inv
      USING ERRCODE = 'check_violation';
  END IF;

  IF (TG_OP = 'DELETE') THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_order_shares_edit_after_post"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."prevent_order_shares_edit_after_post"() IS 'Blocks INSERT/UPDATE/DELETE on order_shares when a posted/paid/overdue invoice exists for the order. Prevents drift between order_shares and the historical invoice_shares snapshot. See docs/OPEN_ITEMS.md item #1.';



CREATE OR REPLACE FUNCTION "public"."preview_field_app_invoice_split"("p_locations" "jsonb", "p_chemicals" "jsonb", "p_application_service_id" "uuid" DEFAULT NULL::"uuid", "p_invoice_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_field_ids         uuid[];
  v_applied_acres_map jsonb := '{}'::jsonb;
  v_loc               jsonb;
  v_shares            jsonb;
  v_customers         jsonb;
  v_customer          jsonb;
  v_customer_id       uuid;
  v_customer_tier     int;
  v_app_service       record;
  v_per_customer      jsonb := '[]'::jsonb;
  v_customer_lines    jsonb;
  v_grand_total       bigint := 0;
  v_chem              jsonb;
  v_share_row         jsonb;
  v_chem_qty_a        numeric;
  v_chem_qty_b        numeric;
  v_share_acres       numeric;
  v_field_override    bigint;
  v_unit_price        bigint;
  v_qi_price          numeric;
  v_extended          bigint;
  v_fee_rate          bigint;
  v_fee_acres         numeric;
  v_fee_extended      bigint;
  v_customer_total    bigint;
  v_rate              numeric;
  v_ta_unit           text;       -- PARKED-010: rate unit of the applied amount
  v_inv_unit          text;       -- PARKED-010: product's sold/pricing unit
  v_form              text;       -- PARKED-010: product_form (liquid/dry)
  v_priced_qty        numeric;    -- PARKED-010: applied qty converted into the pricing unit
  v_group_id          uuid;
  v_skipped_customer_ids uuid[] := '{}';
  v_surcharge_acres   numeric;
  v_surcharge_cents   bigint;
BEGIN
  -- PARKED-007 (codex-driven cycle 5 #1 HIGH): in-body role gate — without it
  -- ANY authenticated role (applicator, driver, etc.) can call this SECDEF
  -- function with arbitrary field_ids and receive private customer pricing
  -- and split detail. RLS doesn't apply (we're SECDEF), the EXECUTE grant to
  -- `authenticated` widens beyond billing roles. Mirrors the save side's gate.
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: only admins or sales reps can preview field-app invoice splits'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  FOR v_loc IN SELECT * FROM jsonb_array_elements(p_locations)
  LOOP
    v_field_ids := array_append(v_field_ids, (v_loc->>'field_id')::uuid);
    v_applied_acres_map := v_applied_acres_map || jsonb_build_object(
      v_loc->>'field_id',
      GREATEST(COALESCE((v_loc->>'applied_acres')::numeric, 0), 0)
    );
  END LOOP;

  IF v_field_ids IS NULL THEN
    RETURN jsonb_build_object('per_customer', '[]'::jsonb, 'grand_total_cents', 0, 'customer_count', 0);
  END IF;

  v_shares    := derive_customer_shares_from_fields(v_field_ids, v_applied_acres_map);
  v_customers := v_shares -> 'customers';

  IF p_invoice_id IS NOT NULL THEN
    SELECT invoice_group_id INTO v_group_id FROM invoices WHERE id = p_invoice_id;
    IF v_group_id IS NOT NULL THEN
      SELECT COALESCE(array_agg(DISTINCT d.customer_id), '{}') INTO v_skipped_customer_ids
        FROM invoices d
       WHERE d.invoice_group_id = v_group_id
         AND d.deleted_at IS NOT NULL
         AND NOT EXISTS (
           SELECT 1 FROM invoices l
            WHERE l.invoice_group_id = v_group_id
              AND l.customer_id = d.customer_id
              AND l.deleted_at IS NULL
         );
    END IF;
  END IF;

  IF p_application_service_id IS NOT NULL THEN
    SELECT * INTO v_app_service FROM application_services WHERE id = p_application_service_id;
    IF NOT FOUND OR NOT v_app_service.is_active THEN
      RAISE EXCEPTION 'Application service not found or inactive: %', p_application_service_id;
    END IF;
  END IF;

  FOR v_customer IN SELECT * FROM jsonb_array_elements(v_customers)
  LOOP
    v_customer_id    := (v_customer->>'customer_id')::uuid;
    IF v_customer_id = ANY(v_skipped_customer_ids) THEN CONTINUE; END IF;
    v_customer_tier  := COALESCE((v_customer->>'tier')::int, 1);
    v_customer_total := 0;
    v_customer_lines := '[]'::jsonb;

    FOR v_share_row IN
      SELECT * FROM jsonb_array_elements(v_shares -> 'rows') AS value
      WHERE (value->>'customer_id')::uuid = v_customer_id
        AND (value->>'price_override_cents') IS NOT NULL
    LOOP
      v_share_acres    := (v_share_row->>'share_acres')::numeric;
      v_field_override := (v_share_row->>'price_override_cents')::bigint;
      v_extended := ROUND(v_field_override * v_share_acres)::bigint;
      v_customer_lines := v_customer_lines || jsonb_build_object(
        'kind', 'grower_share',
        'description', (v_share_row->>'field_name') || ' grower share @ $' ||
                       (v_field_override / 100.0)::numeric(12,2) || '/ac',
        'quantity', v_share_acres,
        'unit_price_cents', v_field_override,
        'extended_cents', v_extended
      );
      v_customer_total := v_customer_total + v_extended;
    END LOOP;

    FOR v_chem IN SELECT * FROM jsonb_array_elements(p_chemicals)
    LOOP
      v_chem_qty_a := 0;
      v_chem_qty_b := 0;
      v_rate := COALESCE((v_chem->>'rate_per_acre')::numeric, 0);
      FOR v_share_row IN
        SELECT * FROM jsonb_array_elements(v_shares -> 'rows') AS value
        WHERE (value->>'customer_id')::uuid = v_customer_id
      LOOP
        v_share_acres := (v_share_row->>'share_acres')::numeric;
        IF (v_share_row->>'price_override_cents') IS NOT NULL THEN
          v_chem_qty_a := v_chem_qty_a + (v_rate * v_share_acres);
        ELSE
          v_chem_qty_b := v_chem_qty_b + (v_rate * v_share_acres);
        END IF;
      END LOOP;

      IF v_chem_qty_b > 0 THEN
        v_unit_price := NULL;
        IF v_chem ? 'manual_override' AND (v_chem->>'manual_override')::boolean = true
           AND (v_chem->>'unit_price_cents') IS NOT NULL THEN
          v_unit_price := (v_chem->>'unit_price_cents')::bigint;
        END IF;
        IF v_unit_price IS NULL AND (v_chem->>'product_id') IS NOT NULL THEN
          SELECT qi.price_per_unit INTO v_qi_price
            FROM quote_items qi
            JOIN quote_sections qs ON qs.id = qi.section_id
           WHERE qi.product_id = (v_chem->>'product_id')::uuid
             AND qs.field_id   = ANY(v_field_ids)
           ORDER BY qi.id LIMIT 1;
          IF v_qi_price IS NOT NULL THEN v_unit_price := ROUND(v_qi_price * 100)::bigint; END IF;
        END IF;
        IF v_unit_price IS NULL AND (v_chem->>'product_id') IS NOT NULL THEN
          SELECT CASE v_customer_tier
            WHEN 1 THEN COALESCE(ROUND(p.tier1_price * 100), 0)
            WHEN 2 THEN COALESCE(ROUND(p.tier2_price * 100), ROUND(p.tier1_price * 100), 0)
            WHEN 3 THEN COALESCE(ROUND(p.tier3_price * 100), ROUND(p.tier1_price * 100), 0)
            ELSE COALESCE(ROUND(p.tier1_price * 100), 0)
          END INTO v_unit_price FROM products p WHERE p.id = (v_chem->>'product_id')::uuid;
        END IF;
        v_unit_price := COALESCE(v_unit_price, 0);

        -- PARKED-010 (preview parity with save_field_app_invoice): the applied amount is in the
        -- RATE unit but v_unit_price is per the product's SOLD unit; convert before pricing so this
        -- on-page customer-split preview shows the same dollars the saved invoice will (not ~128x).
        v_ta_unit  := COALESCE(NULLIF(v_chem->>'rate_unit', ''), NULLIF(v_chem->>'unit_size', ''));
        v_inv_unit := NULL;
        v_form     := NULL;
        IF (v_chem->>'product_id') IS NOT NULL THEN
          SELECT p.inventory_unit, p.product_form::text INTO v_inv_unit, v_form
            FROM products p WHERE p.id = (v_chem->>'product_id')::uuid;
        END IF;
        v_priced_qty := field_app_priced_quantity(v_chem_qty_b, v_ta_unit, COALESCE(v_inv_unit, v_ta_unit), v_form);
        -- Unconvertible units (save blocks with FIELD_APP_UNIT_UNCONVERTIBLE): preview the line at
        -- $0 rather than the old ~128x figure or crashing the preview.
        v_priced_qty := CASE WHEN v_priced_qty IS NULL THEN 0 ELSE ROUND(v_priced_qty, 4) END;
        v_extended := ROUND(v_unit_price * v_priced_qty)::bigint;
        v_customer_lines := v_customer_lines || jsonb_build_object(
          'kind', 'chemical', 'description', v_chem->>'description',
          'quantity', v_priced_qty,
          'unit_price_cents', v_unit_price, 'extended_cents', v_extended
        );
        v_customer_total := v_customer_total + v_extended;
      END IF;
    END LOOP;

    IF p_application_service_id IS NOT NULL THEN
      SELECT car.rate_per_acre_cents INTO v_fee_rate
        FROM customer_application_rates car
       WHERE car.customer_id = v_customer_id
         AND car.application_service_id = p_application_service_id
         AND car.season = current_season() LIMIT 1;
      IF v_fee_rate IS NULL THEN v_fee_rate := v_app_service.default_rate_per_acre_cents; END IF;
      SELECT COALESCE(SUM((value->>'share_acres')::numeric), 0) INTO v_fee_acres
        FROM jsonb_array_elements(v_shares -> 'rows') AS value
       WHERE (value->>'customer_id')::uuid = v_customer_id
         AND (value->>'price_override_cents') IS NULL;
      IF v_fee_rate > 0 AND v_fee_acres > 0 THEN
        v_fee_extended := ROUND(v_fee_rate * v_fee_acres)::bigint;
        v_customer_lines := v_customer_lines || jsonb_build_object(
          'kind', 'service_fee', 'description', v_app_service.name,
          'quantity', v_fee_acres, 'unit_price_cents', v_fee_rate,
          'extended_cents', v_fee_extended
        );
        v_customer_total := v_customer_total + v_fee_extended;
      END IF;
    END IF;

    SELECT COALESCE(SUM((value->>'share_acres')::numeric), 0) INTO v_surcharge_acres
      FROM jsonb_array_elements(v_shares -> 'rows') AS value
     WHERE (value->>'customer_id')::uuid = v_customer_id
       AND (value->>'price_override_cents') IS NULL;

    v_surcharge_cents := compute_fuel_surcharge_cents(v_surcharge_acres, v_customer_total);

    IF v_surcharge_cents > 0 THEN
      v_customer_lines := v_customer_lines || jsonb_build_object(
        'kind', 'fuel_surcharge', 'description', 'Fuel Surcharge',
        'quantity', 1, 'unit_price_cents', v_surcharge_cents,
        'extended_cents', v_surcharge_cents
      );
      v_customer_total := v_customer_total + v_surcharge_cents;
    END IF;

    v_per_customer := v_per_customer || jsonb_build_object(
      'customer_id',   v_customer_id,
      'customer_name', v_customer->>'customer_name',
      'is_primary',    COALESCE((v_customer->>'is_primary')::boolean, false),
      'tier',          v_customer_tier,
      'total_cents',   v_customer_total,
      'lines',         v_customer_lines
    );
    v_grand_total := v_grand_total + v_customer_total;
  END LOOP;

  RETURN jsonb_build_object(
    'per_customer',      v_per_customer,
    'grand_total_cents', v_grand_total,
    'customer_count',    jsonb_array_length(v_per_customer),
    'shares_detail',     v_shares
  );
END;
$_$;


ALTER FUNCTION "public"."preview_field_app_invoice_split"("p_locations" "jsonb", "p_chemicals" "jsonb", "p_application_service_id" "uuid", "p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_finance_charges"("p_as_of_date" "date") RETURNS TABLE("customer_id" "uuid", "customer_name" "text", "account_number" "text", "overdue_balance_cents" bigint, "charge_rate" numeric, "grace_days" integer, "days_overdue" integer, "charge_amount_cents" bigint, "finance_charge_enabled" boolean, "open_credit_cents" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_min_balance bigint;
BEGIN
  PERFORM require_admin();
  IF p_as_of_date IS NULL THEN
    RAISE EXCEPTION 'FINANCE_CHARGE_DATE_REQUIRED';
  END IF;
  IF p_as_of_date > (now() AT TIME ZONE 'America/Chicago')::date THEN
    RAISE EXCEPTION 'FUTURE_FINANCE_CHARGE_DATE: finance charges cannot be previewed for a future business date';
  END IF;
  -- Exact operator parity: generation rejects a closed accounting period before
  -- selecting any customer, so preview must reject the same date too.
  PERFORM public.check_period_open(p_as_of_date);

  SELECT COALESCE(s.setting_value::bigint, 500)
    INTO v_min_balance
    FROM public.app_settings s
   WHERE s.setting_key = 'finance_charge_min_balance_cents';

  IF v_min_balance IS NULL THEN
    v_min_balance := 500;
  END IF;

  RETURN QUERY
  SELECT
    c.id AS customer_id,
    c.farm_name::text AS customer_name,
    c.account_number::text AS account_number,
    agg.overdue_balance_cents,
    c.finance_charge_rate AS charge_rate,
    COALESCE(c.finance_charge_grace_days, 0) AS grace_days,
    agg.max_days_overdue AS days_overdue,
    ROUND(agg.overdue_balance_cents * (c.finance_charge_rate / 100.0 / 12.0))::bigint AS charge_amount_cents,
    COALESCE(c.finance_charge_enabled, true) AS finance_charge_enabled,
    COALESCE(cm.credit_cents, 0)::bigint AS open_credit_cents
  FROM public.customers c
  INNER JOIN (
    -- Base overdue set — MUST mirror generate_finance_charges exactly so the previewed
    -- amount equals the billed amount: status IN ('posted','overdue') + grace-aware
    -- per-invoice due_date predicate (grace read per-customer via the cc join).
    SELECT
      i.customer_id,
      COALESCE(sum(i.balance_cents), 0)::bigint AS overdue_balance_cents,
      max((p_as_of_date - i.due_date))::integer AS max_days_overdue
    FROM public.invoices i
    JOIN public.customers cc ON cc.id = i.customer_id
    WHERE i.status IN ('posted', 'overdue')
      AND i.balance_cents > 0
      AND i.deleted_at IS NULL
      AND i.invoice_type != 'misc_charge'
      AND i.due_date IS NOT NULL
      AND i.due_date < (p_as_of_date - (COALESCE(cc.finance_charge_grace_days, 0) || ' days')::interval)
    GROUP BY i.customer_id
  ) agg ON agg.customer_id = c.id
  LEFT JOIN (
    SELECT ci.customer_id, -SUM(ci.balance_cents) AS credit_cents
    FROM public.invoices ci
    WHERE ci.invoice_type = 'credit_memo' AND ci.status = 'posted'
      AND ci.balance_cents < 0 AND ci.deleted_at IS NULL
    GROUP BY ci.customer_id
  ) cm ON cm.customer_id = c.id
  WHERE c.finance_charge_rate > 0
    AND c.is_active = true
    AND COALESCE(c.finance_charge_enabled, true) = true
    AND agg.overdue_balance_cents >= v_min_balance
    AND ROUND(agg.overdue_balance_cents * (c.finance_charge_rate / 100.0 / 12.0))::bigint > 0
    AND NOT EXISTS (
      SELECT 1
        FROM public.finance_charges fc
       WHERE fc.customer_id = c.id
         AND date_trunc('month', fc.period_end) = date_trunc('month', p_as_of_date)
    )
  ORDER BY c.farm_name;
END;
$$;


ALTER FUNCTION "public"."preview_finance_charges"("p_as_of_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_product_pricing_changes"("p_source" "text", "p_export_id" "uuid" DEFAULT NULL::"uuid", "p_rows" "jsonb" DEFAULT '[]'::"jsonb", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_request_fp text;
  v_change_set public.pricing_change_sets%ROWTYPE;
  v_change_set_id uuid;
  v_export public.pricing_workbook_exports%ROWTYPE;
  v_row jsonb;
  v_sequence integer;
  v_product public.products%ROWTYPE;
  v_manifest public.pricing_workbook_export_rows%ROWTYPE;
  v_preview_product_id uuid;
  v_mode text;
  v_cost_cents bigint;
  v_t1_margin numeric;
  v_t2_margin numeric;
  v_t3_margin numeric;
  v_t1_price_cents bigint;
  v_t2_price_cents bigint;
  v_t3_price_cents bigint;
  v_calc jsonb;
  v_output jsonb;
  v_output_fp text;
  v_identity_fp text;
  v_expected_version bigint;
  v_error_message text;
  v_error_code text;
  v_final_status text;
  v_changed_count integer := 0;
  v_unchanged_count integer := 0;
  v_conflict_count integer := 0;
  v_invalid_count integer := 0;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;
  IF p_source NOT IN ('pricing_worksheet', 'product_page', 'products_inline') THEN
    RAISE EXCEPTION 'PRICING_SOURCE_INVALID';
  END IF;
  IF jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RAISE EXCEPTION 'PRICING_ROWS_REQUIRED';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_rows) row_value
    GROUP BY row_value->>'product_id'
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'PRICING_DUPLICATE_PRODUCT_ID';
  END IF;

  v_request_fp := md5(jsonb_build_object(
    'actor_id', v_actor,
    'source', p_source,
    'export_id', p_export_id,
    'rows', p_rows
  )::text);
  v_existing := public.check_idempotency(p_idempotency_key, 'preview_product_pricing_changes');
  IF v_existing IS NOT NULL THEN
    IF v_existing->>'actor_id' IS DISTINCT FROM v_actor::text
       OR v_existing->>'request_fingerprint' IS DISTINCT FROM v_request_fp THEN
      RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH';
    END IF;
    RETURN v_existing->'response';
  END IF;

  -- The shared cache expires after 24 hours. The change set and retained
  -- preview rows are the durable receipt, so only the exact original actor,
  -- payload fingerprint, and idempotency key may replay it.
  SELECT * INTO v_change_set
  FROM public.pricing_change_sets c
  WHERE c.preview_idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_change_set.created_by IS DISTINCT FROM v_actor
       OR v_change_set.request_fingerprint IS DISTINCT FROM v_request_fp THEN
      RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH';
    END IF;

    SELECT
      count(*) FILTER (WHERE r.row_status = 'unchanged'),
      count(*) FILTER (WHERE r.row_status = 'conflict'),
      count(*) FILTER (WHERE r.row_status = 'invalid')
    INTO v_unchanged_count, v_conflict_count, v_invalid_count
    FROM public.pricing_change_set_preview_rows r
    WHERE r.change_set_id = v_change_set.id;

    v_final_status := CASE
      WHEN v_conflict_count > 0 OR v_invalid_count > 0 THEN 'invalid'
      WHEN v_change_set.row_count = 0 THEN 'no_changes'
      ELSE 'previewed'
    END;

    SELECT jsonb_build_object(
      'change_set_id', c.id,
      'request_fingerprint', c.request_fingerprint,
      'source', c.source,
      'status', v_final_status,
      'expires_at', c.expires_at,
      'submitted_row_count', c.submitted_row_count,
      'ready_count', c.row_count,
      'unchanged_count', v_unchanged_count,
      'conflict_count', v_conflict_count,
      'invalid_count', v_invalid_count,
      'apply_allowed', (v_final_status = 'previewed' AND c.row_count > 0),
      'rows', (
        SELECT jsonb_agg(to_jsonb(r) - 'change_set_id' ORDER BY r.sequence)
        FROM public.pricing_change_set_preview_rows r WHERE r.change_set_id = c.id
      )
    ) INTO v_result
    FROM public.pricing_change_sets c
    WHERE c.id = v_change_set.id;

    RETURN v_result;
  END IF;

  IF p_source = 'pricing_worksheet' THEN
    IF p_export_id IS NULL THEN RAISE EXCEPTION 'WORKBOOK_EXPORT_REQUIRED'; END IF;
    SELECT * INTO v_export FROM public.pricing_workbook_exports e
    WHERE e.id = p_export_id
      AND e.created_by = v_actor
      AND e.status = 'active'
      AND e.expires_at > now();
    IF NOT FOUND THEN RAISE EXCEPTION 'WORKBOOK_EXPORT_INVALID_OR_EXPIRED'; END IF;
    IF jsonb_array_length(p_rows) IS DISTINCT FROM v_export.row_count THEN
      RAISE EXCEPTION 'WORKBOOK_MANIFEST_ROW_COUNT_MISMATCH';
    END IF;
  ELSIF p_export_id IS NOT NULL THEN
    RAISE EXCEPTION 'DIRECT_PRICING_EXPORT_NOT_ALLOWED';
  END IF;

  INSERT INTO public.pricing_change_sets(
    export_id, created_by, source, request_fingerprint,
    preview_idempotency_key, submitted_row_count, row_count, status
  ) VALUES (
    p_export_id, v_actor, p_source, v_request_fp,
    p_idempotency_key, jsonb_array_length(p_rows), 0, 'invalid'
  ) RETURNING id INTO v_change_set_id;

  FOR v_sequence, v_row IN
    SELECT ordinality::integer, value
    FROM jsonb_array_elements(p_rows) WITH ORDINALITY
  LOOP
    v_preview_product_id := NULL;
    v_product.id := NULL;

    BEGIN
      IF jsonb_typeof(v_row) <> 'object'
         OR COALESCE(v_row->>'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
         OR COALESCE(v_row->>'row_version', '') !~ '^[0-9]+$' THEN
        RAISE EXCEPTION 'PRICING_ROW_IDENTITY_INVALID';
      END IF;

      IF p_source = 'pricing_worksheet' AND (
        NOT (v_row ? 'has_formula')
        OR jsonb_typeof(v_row->'has_formula') <> 'boolean'
        OR (v_row->>'has_formula')::boolean
        OR (v_row ? 'formula_cells' AND (
          jsonb_typeof(v_row->'formula_cells') <> 'array'
          OR jsonb_array_length(v_row->'formula_cells') > 0
        ))
      ) THEN
        RAISE EXCEPTION 'WORKBOOK_FORMULA_REJECTED';
      END IF;

      SELECT * INTO v_product
      FROM public.products
      WHERE id = (v_row->>'product_id')::uuid;
      IF NOT FOUND THEN RAISE EXCEPTION 'PRICING_PRODUCT_NOT_FOUND'; END IF;
      IF NOT v_product.is_active THEN RAISE EXCEPTION 'PRICING_PRODUCT_INACTIVE'; END IF;
      v_preview_product_id := v_product.id;

      v_expected_version := (v_row->>'row_version')::bigint;
      v_identity_fp := md5(jsonb_build_object(
        'product_id', v_product.id,
        'sku', COALESCE(v_product.sku, ''),
        'product_name', v_product.product_name,
        'category', COALESCE(v_product.category, ''),
        'container_size', COALESCE(v_product.container_size::text, ''),
        'unit_size', COALESCE(v_product.unit_size, ''),
        'inventory_unit', COALESCE(v_product.inventory_unit, '')
      )::text);

      IF p_source = 'pricing_worksheet' THEN
        SELECT * INTO v_manifest
        FROM public.pricing_workbook_export_rows
        WHERE export_id = p_export_id AND product_id = v_product.id;
        IF NOT FOUND THEN RAISE EXCEPTION 'WORKBOOK_UNKNOWN_PRODUCT'; END IF;

        IF NOT (v_row ?& ARRAY[
             'sku', 'product_name', 'category', 'container_size', 'unit_size',
             'inventory_unit', 'identity_fingerprint', 'row_token',
             'current_cost', 'current_tier1_margin_percent', 'current_tier1_price',
             'current_tier2_margin_percent', 'current_tier2_price',
             'current_tier3_margin_percent', 'current_tier3_price'
           ])
           OR v_row->>'sku' IS DISTINCT FROM COALESCE(v_manifest.sku_snapshot, '')
           OR v_row->>'product_name' IS DISTINCT FROM v_manifest.product_name_snapshot
           OR v_row->>'category' IS DISTINCT FROM COALESCE(v_manifest.category_snapshot, '')
           OR v_row->>'container_size' IS DISTINCT FROM COALESCE(v_manifest.container_size_snapshot, '')
           OR v_row->>'unit_size' IS DISTINCT FROM COALESCE(v_manifest.unit_size_snapshot, '')
           OR v_row->>'inventory_unit' IS DISTINCT FROM COALESCE(v_manifest.inventory_unit_snapshot, '')
           OR v_row->>'identity_fingerprint' IS DISTINCT FROM v_manifest.identity_fingerprint
           OR v_row->>'row_token' IS DISTINCT FROM v_manifest.row_token
           OR v_expected_version IS DISTINCT FROM v_manifest.row_version
           OR v_row->>'current_cost' IS DISTINCT FROM COALESCE(public._format_pricing_dollars(v_manifest.current_cost_cents), '')
           OR v_row->>'current_tier1_margin_percent' IS DISTINCT FROM COALESCE(public._format_pricing_margin_percent(v_manifest.current_tier1_margin), '')
           OR v_row->>'current_tier1_price' IS DISTINCT FROM COALESCE(public._format_pricing_dollars(v_manifest.current_tier1_price_cents), '')
           OR v_row->>'current_tier2_margin_percent' IS DISTINCT FROM COALESCE(public._format_pricing_margin_percent(v_manifest.current_tier2_margin), '')
           OR v_row->>'current_tier2_price' IS DISTINCT FROM COALESCE(public._format_pricing_dollars(v_manifest.current_tier2_price_cents), '')
           OR v_row->>'current_tier3_margin_percent' IS DISTINCT FROM COALESCE(public._format_pricing_margin_percent(v_manifest.current_tier3_margin), '')
           OR v_row->>'current_tier3_price' IS DISTINCT FROM COALESCE(public._format_pricing_dollars(v_manifest.current_tier3_price_cents), '') THEN
          RAISE EXCEPTION 'WORKBOOK_IDENTITY_OR_BASELINE_TAMPERED';
        END IF;
        IF v_product.pricing_version IS DISTINCT FROM v_manifest.row_version
           OR v_identity_fp IS DISTINCT FROM v_manifest.identity_fingerprint THEN
          RAISE EXCEPTION 'PRICING_ROW_CONFLICT';
        END IF;
      ELSIF v_product.pricing_version IS DISTINCT FROM v_expected_version THEN
        RAISE EXCEPTION 'PRICING_ROW_CONFLICT';
      END IF;

      v_mode := NULLIF(btrim(COALESCE(v_row->>'pricing_mode', '')), '');
      IF p_source = 'pricing_worksheet' AND v_mode IS NULL THEN
        -- Blank mode is the safe worksheet default. Proposed cells may remain
        -- blank or repeat the exact server-exported baseline, but cannot hide a
        -- pricing edit without an explicit mode.
        IF (COALESCE(v_row->>'new_cost', '') <> ''
              AND v_row->>'new_cost' IS DISTINCT FROM public._format_pricing_dollars(v_manifest.current_cost_cents))
           OR (COALESCE(v_row->>'tier1_margin_percent', '') <> ''
              AND v_row->>'tier1_margin_percent' IS DISTINCT FROM public._format_pricing_margin_percent(v_manifest.current_tier1_margin))
           OR (COALESCE(v_row->>'tier1_price', '') <> ''
              AND v_row->>'tier1_price' IS DISTINCT FROM public._format_pricing_dollars(v_manifest.current_tier1_price_cents))
           OR (COALESCE(v_row->>'tier2_margin_percent', '') <> ''
              AND v_row->>'tier2_margin_percent' IS DISTINCT FROM public._format_pricing_margin_percent(v_manifest.current_tier2_margin))
           OR (COALESCE(v_row->>'tier2_price', '') <> ''
              AND v_row->>'tier2_price' IS DISTINCT FROM public._format_pricing_dollars(v_manifest.current_tier2_price_cents))
           OR (COALESCE(v_row->>'tier3_margin_percent', '') <> ''
              AND v_row->>'tier3_margin_percent' IS DISTINCT FROM public._format_pricing_margin_percent(v_manifest.current_tier3_margin))
           OR (COALESCE(v_row->>'tier3_price', '') <> ''
              AND v_row->>'tier3_price' IS DISTINCT FROM public._format_pricing_dollars(v_manifest.current_tier3_price_cents)) THEN
          RAISE EXCEPTION 'WORKBOOK_BLANK_MODE_CHANGED_VALUES';
        END IF;

        v_output := jsonb_build_object(
          'product_id', v_product.id,
          'product_name', v_product.product_name,
          'sku', COALESCE(v_product.sku, ''),
          'before', jsonb_build_object(
            'cost', public._format_pricing_dollars(round(v_product.current_cost * 100)::bigint),
            'cost_cents', round(v_product.current_cost * 100)::bigint,
            'tier1_margin_percent', public._format_pricing_margin_percent(v_product.tier1_margin),
            'tier1_margin', v_product.tier1_margin,
            'tier1_price', public._format_pricing_dollars(round(v_product.tier1_price * 100)::bigint),
            'tier1_price_cents', round(v_product.tier1_price * 100)::bigint,
            'tier2_margin_percent', public._format_pricing_margin_percent(v_product.tier2_margin),
            'tier2_margin', v_product.tier2_margin,
            'tier2_price', public._format_pricing_dollars(round(v_product.tier2_price * 100)::bigint),
            'tier2_price_cents', round(v_product.tier2_price * 100)::bigint,
            'tier3_margin_percent', public._format_pricing_margin_percent(v_product.tier3_margin),
            'tier3_margin', v_product.tier3_margin,
            'tier3_price', public._format_pricing_dollars(round(v_product.tier3_price * 100)::bigint),
            'tier3_price_cents', round(v_product.tier3_price * 100)::bigint,
            'tier1_price_per_acre_cents', round(v_product.tier1_price_per_acre * 100)::bigint,
            'tier2_price_per_acre_cents', round(v_product.tier2_price_per_acre * 100)::bigint,
            'tier3_price_per_acre_cents', round(v_product.tier3_price_per_acre * 100)::bigint
          ),
          'cost', public._format_pricing_dollars(v_manifest.current_cost_cents),
          'cost_cents', v_manifest.current_cost_cents,
          'tier1_margin_percent', public._format_pricing_margin_percent(v_manifest.current_tier1_margin),
          'tier1_margin', v_manifest.current_tier1_margin,
          'tier1_price', public._format_pricing_dollars(v_manifest.current_tier1_price_cents),
          'tier1_price_cents', v_manifest.current_tier1_price_cents,
          'tier2_margin_percent', public._format_pricing_margin_percent(v_manifest.current_tier2_margin),
          'tier2_margin', v_manifest.current_tier2_margin,
          'tier2_price', public._format_pricing_dollars(v_manifest.current_tier2_price_cents),
          'tier2_price_cents', v_manifest.current_tier2_price_cents,
          'tier3_margin_percent', public._format_pricing_margin_percent(v_manifest.current_tier3_margin),
          'tier3_margin', v_manifest.current_tier3_margin,
          'tier3_price', public._format_pricing_dollars(v_manifest.current_tier3_price_cents),
          'tier3_price_cents', v_manifest.current_tier3_price_cents
        );
        INSERT INTO public.pricing_change_set_preview_rows(
          change_set_id, sequence, product_id, submitted_row, row_status, effect
        ) VALUES (
          v_change_set_id, v_sequence, v_product.id, v_row, 'unchanged', v_output
        );
        v_unchanged_count := v_unchanged_count + 1;
        CONTINUE;
      END IF;

      IF v_mode NOT IN ('margin_driven', 'price_driven') THEN
        RAISE EXCEPTION 'PRICING_MODE_INVALID';
      END IF;
      IF NOT (v_row ? 'new_cost') OR jsonb_typeof(v_row->'new_cost') <> 'string' THEN
        RAISE EXCEPTION 'PRICING_DOLLARS_INVALID';
      END IF;
      v_cost_cents := public._parse_pricing_dollars(v_row->>'new_cost');

      IF v_mode = 'margin_driven' THEN
        IF NOT (v_row ?& ARRAY['tier1_margin_percent', 'tier2_margin_percent', 'tier3_margin_percent'])
           OR jsonb_typeof(v_row->'tier1_margin_percent') <> 'string'
           OR jsonb_typeof(v_row->'tier2_margin_percent') <> 'string'
           OR jsonb_typeof(v_row->'tier3_margin_percent') <> 'string' THEN
          RAISE EXCEPTION 'MARGIN_DRIVEN_FIELDS_INVALID';
        END IF;
        IF p_source = 'pricing_worksheet' AND (
             (COALESCE(v_row->>'tier1_price', '') <> '' AND v_row->>'tier1_price' IS DISTINCT FROM public._format_pricing_dollars(v_manifest.current_tier1_price_cents))
          OR (COALESCE(v_row->>'tier2_price', '') <> '' AND v_row->>'tier2_price' IS DISTINCT FROM public._format_pricing_dollars(v_manifest.current_tier2_price_cents))
          OR (COALESCE(v_row->>'tier3_price', '') <> '' AND v_row->>'tier3_price' IS DISTINCT FROM public._format_pricing_dollars(v_manifest.current_tier3_price_cents))
        ) THEN
          RAISE EXCEPTION 'MARGIN_DRIVEN_COMPANION_FIELDS_CHANGED';
        ELSIF p_source <> 'pricing_worksheet' AND (
          COALESCE(v_row->>'tier1_price', '') <> '' OR COALESCE(v_row->>'tier2_price', '') <> ''
          OR COALESCE(v_row->>'tier3_price', '') <> ''
        ) THEN
          RAISE EXCEPTION 'MARGIN_DRIVEN_FIELDS_INVALID';
        END IF;
        v_t1_margin := public._parse_pricing_margin_percent(v_row->>'tier1_margin_percent');
        v_t2_margin := public._parse_pricing_margin_percent(v_row->>'tier2_margin_percent');
        v_t3_margin := public._parse_pricing_margin_percent(v_row->>'tier3_margin_percent');
        v_t1_price_cents := NULL; v_t2_price_cents := NULL; v_t3_price_cents := NULL;
      ELSE
        IF NOT (v_row ?& ARRAY['tier1_price', 'tier2_price', 'tier3_price'])
           OR jsonb_typeof(v_row->'tier1_price') <> 'string'
           OR jsonb_typeof(v_row->'tier2_price') <> 'string'
           OR jsonb_typeof(v_row->'tier3_price') <> 'string' THEN
          RAISE EXCEPTION 'PRICE_DRIVEN_FIELDS_INVALID';
        END IF;
        IF p_source = 'pricing_worksheet' AND (
             (COALESCE(v_row->>'tier1_margin_percent', '') <> '' AND v_row->>'tier1_margin_percent' IS DISTINCT FROM public._format_pricing_margin_percent(v_manifest.current_tier1_margin))
          OR (COALESCE(v_row->>'tier2_margin_percent', '') <> '' AND v_row->>'tier2_margin_percent' IS DISTINCT FROM public._format_pricing_margin_percent(v_manifest.current_tier2_margin))
          OR (COALESCE(v_row->>'tier3_margin_percent', '') <> '' AND v_row->>'tier3_margin_percent' IS DISTINCT FROM public._format_pricing_margin_percent(v_manifest.current_tier3_margin))
        ) THEN
          RAISE EXCEPTION 'PRICE_DRIVEN_COMPANION_FIELDS_CHANGED';
        ELSIF p_source <> 'pricing_worksheet' AND (
          COALESCE(v_row->>'tier1_margin_percent', '') <> '' OR COALESCE(v_row->>'tier2_margin_percent', '') <> ''
          OR COALESCE(v_row->>'tier3_margin_percent', '') <> ''
        ) THEN
          RAISE EXCEPTION 'PRICE_DRIVEN_FIELDS_INVALID';
        END IF;
        v_t1_margin := NULL; v_t2_margin := NULL; v_t3_margin := NULL;
        v_t1_price_cents := public._parse_pricing_dollars(v_row->>'tier1_price');
        v_t2_price_cents := public._parse_pricing_dollars(v_row->>'tier2_price');
        v_t3_price_cents := public._parse_pricing_dollars(v_row->>'tier3_price');
      END IF;

      v_calc := public._calculate_product_pricing(
        v_mode,
        v_cost_cents::numeric / 100,
        v_t1_margin, v_t2_margin, v_t3_margin,
        CASE WHEN v_t1_price_cents IS NULL THEN NULL ELSE v_t1_price_cents::numeric / 100 END,
        CASE WHEN v_t2_price_cents IS NULL THEN NULL ELSE v_t2_price_cents::numeric / 100 END,
        CASE WHEN v_t3_price_cents IS NULL THEN NULL ELSE v_t3_price_cents::numeric / 100 END
      );

      v_output := jsonb_build_object(
        'product_id', v_product.id,
        'product_name', v_product.product_name,
        'sku', COALESCE(v_product.sku, ''),
        'before', jsonb_build_object(
          'cost', public._format_pricing_dollars(round(v_product.current_cost * 100)::bigint),
          'cost_cents', round(v_product.current_cost * 100)::bigint,
          'tier1_margin_percent', public._format_pricing_margin_percent(v_product.tier1_margin),
          'tier1_margin', v_product.tier1_margin,
          'tier1_price', public._format_pricing_dollars(round(v_product.tier1_price * 100)::bigint),
          'tier1_price_cents', round(v_product.tier1_price * 100)::bigint,
          'tier2_margin_percent', public._format_pricing_margin_percent(v_product.tier2_margin),
          'tier2_margin', v_product.tier2_margin,
          'tier2_price', public._format_pricing_dollars(round(v_product.tier2_price * 100)::bigint),
          'tier2_price_cents', round(v_product.tier2_price * 100)::bigint,
          'tier3_margin_percent', public._format_pricing_margin_percent(v_product.tier3_margin),
          'tier3_margin', v_product.tier3_margin,
          'tier3_price', public._format_pricing_dollars(round(v_product.tier3_price * 100)::bigint),
          'tier3_price_cents', round(v_product.tier3_price * 100)::bigint,
          'tier1_price_per_acre_cents', round(v_product.tier1_price_per_acre * 100)::bigint,
          'tier2_price_per_acre_cents', round(v_product.tier2_price_per_acre * 100)::bigint,
          'tier3_price_per_acre_cents', round(v_product.tier3_price_per_acre * 100)::bigint
        ),
        'pricing_mode', v_mode,
        'cost', public._format_pricing_dollars(round((v_calc->>'current_cost')::numeric * 100)::bigint),
        'cost_cents', round((v_calc->>'current_cost')::numeric * 100)::bigint,
        'tier1_margin_percent', public._format_pricing_margin_percent((v_calc->>'tier1_margin')::numeric),
        'tier1_margin', (v_calc->>'tier1_margin')::numeric,
        'tier2_margin_percent', public._format_pricing_margin_percent((v_calc->>'tier2_margin')::numeric),
        'tier2_margin', (v_calc->>'tier2_margin')::numeric,
        'tier3_margin_percent', public._format_pricing_margin_percent((v_calc->>'tier3_margin')::numeric),
        'tier3_margin', (v_calc->>'tier3_margin')::numeric,
        'tier1_price', public._format_pricing_dollars(round((v_calc->>'tier1_price')::numeric * 100)::bigint),
        'tier1_price_cents', round((v_calc->>'tier1_price')::numeric * 100)::bigint,
        'tier2_price', public._format_pricing_dollars(round((v_calc->>'tier2_price')::numeric * 100)::bigint),
        'tier2_price_cents', round((v_calc->>'tier2_price')::numeric * 100)::bigint,
        'tier3_price', public._format_pricing_dollars(round((v_calc->>'tier3_price')::numeric * 100)::bigint),
        'tier3_price_cents', round((v_calc->>'tier3_price')::numeric * 100)::bigint,
        'tier1_gross_margin', v_calc->'tier1_gross_margin',
        'tier2_gross_margin', v_calc->'tier2_gross_margin',
        'tier3_gross_margin', v_calc->'tier3_gross_margin',
        'tier1_price_per_acre_cents', CASE
          WHEN public.product_price_per_acre((v_calc->>'tier1_price')::numeric,
            v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) IS NULL
          THEN NULL ELSE round(public.product_price_per_acre((v_calc->>'tier1_price')::numeric,
            v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) * 100)::bigint END,
        'tier2_price_per_acre_cents', CASE
          WHEN public.product_price_per_acre(COALESCE(NULLIF((v_calc->>'tier2_price')::numeric, 0), (v_calc->>'tier1_price')::numeric),
            v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) IS NULL
          THEN NULL ELSE round(public.product_price_per_acre(COALESCE(NULLIF((v_calc->>'tier2_price')::numeric, 0), (v_calc->>'tier1_price')::numeric),
            v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) * 100)::bigint END,
        'tier3_price_per_acre_cents', CASE
          WHEN public.product_price_per_acre(COALESCE(NULLIF((v_calc->>'tier3_price')::numeric, 0), (v_calc->>'tier1_price')::numeric),
            v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) IS NULL
          THEN NULL ELSE round(public.product_price_per_acre(COALESCE(NULLIF((v_calc->>'tier3_price')::numeric, 0), (v_calc->>'tier1_price')::numeric),
            v_product.rate_per_acre, v_product.rate_unit, v_product.inventory_unit, v_product.unit_size) * 100)::bigint END
      );
      v_output_fp := md5((v_output - ARRAY[
        'product_id', 'product_name', 'sku', 'before', 'pricing_mode', 'cost',
        'tier1_margin_percent', 'tier2_margin_percent', 'tier3_margin_percent',
        'tier1_price', 'tier2_price', 'tier3_price'
      ]::text[])::text);

      IF (v_output->>'cost_cents')::bigint IS NOT DISTINCT FROM round(v_product.current_cost * 100)::bigint
         AND (v_output->>'tier1_margin')::numeric IS NOT DISTINCT FROM v_product.tier1_margin
         AND (v_output->>'tier2_margin')::numeric IS NOT DISTINCT FROM v_product.tier2_margin
         AND (v_output->>'tier3_margin')::numeric IS NOT DISTINCT FROM v_product.tier3_margin
         AND (v_output->>'tier1_price_cents')::bigint IS NOT DISTINCT FROM round(v_product.tier1_price * 100)::bigint
         AND (v_output->>'tier2_price_cents')::bigint IS NOT DISTINCT FROM round(v_product.tier2_price * 100)::bigint
         AND (v_output->>'tier3_price_cents')::bigint IS NOT DISTINCT FROM round(v_product.tier3_price * 100)::bigint THEN
        INSERT INTO public.pricing_change_set_preview_rows(
          change_set_id, sequence, product_id, submitted_row, row_status, effect
        ) VALUES (
          v_change_set_id, v_sequence, v_product.id, v_row, 'unchanged', v_output
        );
        v_unchanged_count := v_unchanged_count + 1;
        CONTINUE;
      END IF;

      INSERT INTO public.pricing_change_set_rows(
        change_set_id, product_id, identity_fingerprint, expected_version,
        pricing_mode, change_reason,
        input_cost_cents, input_tier1_margin, input_tier2_margin, input_tier3_margin,
        input_tier1_price_cents, input_tier2_price_cents, input_tier3_price_cents,
        output_cost_cents, output_tier1_margin, output_tier2_margin, output_tier3_margin,
        output_tier1_price_cents, output_tier2_price_cents, output_tier3_price_cents,
        output_tier1_gross_margin, output_tier2_gross_margin, output_tier3_gross_margin,
        output_tier1_price_per_acre_cents, output_tier2_price_per_acre_cents,
        output_tier3_price_per_acre_cents, output_fingerprint
      ) VALUES (
        v_change_set_id, v_product.id, v_identity_fp, v_expected_version,
        v_mode, NULLIF(btrim(v_row->>'change_reason'), ''),
        v_cost_cents, v_t1_margin, v_t2_margin, v_t3_margin,
        v_t1_price_cents, v_t2_price_cents, v_t3_price_cents,
        (v_output->>'cost_cents')::bigint,
        (v_output->>'tier1_margin')::numeric,
        (v_output->>'tier2_margin')::numeric,
        (v_output->>'tier3_margin')::numeric,
        (v_output->>'tier1_price_cents')::bigint,
        (v_output->>'tier2_price_cents')::bigint,
        (v_output->>'tier3_price_cents')::bigint,
        (v_output->>'tier1_gross_margin')::numeric,
        (v_output->>'tier2_gross_margin')::numeric,
        (v_output->>'tier3_gross_margin')::numeric,
        (v_output->>'tier1_price_per_acre_cents')::bigint,
        (v_output->>'tier2_price_per_acre_cents')::bigint,
        (v_output->>'tier3_price_per_acre_cents')::bigint,
        v_output_fp
      );
      INSERT INTO public.pricing_change_set_preview_rows(
        change_set_id, sequence, product_id, submitted_row, row_status, effect
      ) VALUES (
        v_change_set_id, v_sequence, v_product.id, v_row, 'ready', v_output
      );
      v_changed_count := v_changed_count + 1;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
      v_error_code := CASE
        WHEN v_error_message ~ '^[A-Z0-9_]+$' THEN v_error_message
        ELSE 'PRICING_ROW_INVALID'
      END;
      IF v_error_code = 'PRICING_ROW_CONFLICT' THEN
        v_conflict_count := v_conflict_count + 1;
        INSERT INTO public.pricing_change_set_preview_rows(
          change_set_id, sequence, product_id, submitted_row, row_status, error_code
        ) VALUES (
          v_change_set_id, v_sequence, v_preview_product_id, v_row, 'conflict', v_error_code
        );
      ELSE
        v_invalid_count := v_invalid_count + 1;
        INSERT INTO public.pricing_change_set_preview_rows(
          change_set_id, sequence, product_id, submitted_row, row_status, error_code
        ) VALUES (
          v_change_set_id, v_sequence, v_preview_product_id, v_row, 'invalid', v_error_code
        );
      END IF;
    END;
  END LOOP;

  v_final_status := CASE
    WHEN v_conflict_count > 0 OR v_invalid_count > 0 THEN 'invalid'
    WHEN v_changed_count = 0 THEN 'no_changes'
    ELSE 'previewed'
  END;
  UPDATE public.pricing_change_sets
  SET row_count = v_changed_count, status = v_final_status
  WHERE id = v_change_set_id;
  SELECT jsonb_build_object(
    'change_set_id', c.id,
    'request_fingerprint', c.request_fingerprint,
    'source', c.source,
    'status', c.status,
    'expires_at', c.expires_at,
    'submitted_row_count', c.submitted_row_count,
    'ready_count', c.row_count,
    'unchanged_count', v_unchanged_count,
    'conflict_count', v_conflict_count,
    'invalid_count', v_invalid_count,
    'apply_allowed', (c.status = 'previewed' AND c.row_count > 0),
    'rows', (
      SELECT jsonb_agg(to_jsonb(r) - 'change_set_id' ORDER BY r.sequence)
      FROM public.pricing_change_set_preview_rows r WHERE r.change_set_id = c.id
    )
  ) INTO v_result
  FROM public.pricing_change_sets c WHERE c.id = v_change_set_id;

  PERFORM public.save_idempotency(
    p_idempotency_key,
    'preview_product_pricing_changes',
    jsonb_build_object('actor_id', v_actor, 'request_fingerprint', v_request_fp, 'response', v_result)
  );
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."preview_product_pricing_changes"("p_source" "text", "p_export_id" "uuid", "p_rows" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."price_order"("p_order_id" "uuid", "p_items" "jsonb" DEFAULT '[]'::"jsonb", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor       uuid;
  v_actor_role  text;
  v_order       record;
  v_cached      jsonb;
  v_result      jsonb;
  v_item        jsonb;
  v_oi          record;
  v_price       numeric;
  v_cost        numeric;
  v_remaining   int;
  v_was_pending boolean;
  v_total_profit numeric;
  v_inv         record;
  v_swept       int := 0;
BEGIN
  -- ── canonical strict-actor + role gate ────────────────────────────────────
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin','sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF;

  -- Codex round-11 P2: idempotency check AFTER the order FOR UPDATE (TOCTOU). A pre-lock
  -- check_idempotency let two same-key calls both miss the cache; the 1st prices the order
  -- (pricing_status→priced) and saves its result, then the 2nd — which was waiting on the
  -- FOR UPDATE — resumes and would hit the ALREADY_PRICED guard below, returning a FALSE
  -- failure even though the order was priced. Re-checking here (the order row lock
  -- serializes same-order/same-key calls) returns the 1st call's saved result instead.
  -- Canonical pattern from draw_down_quote (20260610181726).
  IF p_idempotency_key IS NOT NULL THEN
    v_cached := check_idempotency(p_idempotency_key, 'price_order');
    IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
  END IF;
  -- Terminal-order guard (Codex round 2 P1): a cancelled/voided/deleted rush order
  -- still carries pricing_status='needs_pricing' (the cancel/void RPCs don't clear
  -- it), so without this check price_order would price it and create commissions
  -- for a dead order. Reject terminal orders before any mutation.
  IF v_order.status IN ('cancelled', 'voided') OR v_order.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'ORDER_NOT_ACTIVE';
  END IF;
  -- State guard (Codex P1): only an unpriced order may be priced. Once an order
  -- is finalized to 'priced', reject re-pricing — a stale second tab would
  -- otherwise update prices/totals while the v_was_pending-gated invoice +
  -- commission refresh is skipped, desyncing the financial records. A partially
  -- priced order stays 'needs_pricing' (the flip to 'priced' only happens when no
  -- line remains pending), so legitimate multi-call pricing still passes here.
  IF v_order.pricing_status IS DISTINCT FROM 'needs_pricing' THEN
    RAISE EXCEPTION 'ALREADY_PRICED';
  END IF;
  v_was_pending := true;

  -- ── price each provided line (price-only) ─────────────────────────────────
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    IF (v_item->>'order_item_id') IS NULL THEN CONTINUE; END IF;
    v_price := COALESCE((v_item->>'price')::numeric, 0);
    IF v_price < 0 THEN RAISE EXCEPTION 'INVALID_PRICE'; END IF;
    SELECT * INTO v_oi FROM order_items
      WHERE id = (v_item->>'order_item_id')::uuid AND order_id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'ITEM_NOT_FOUND'; END IF;
    v_cost := COALESCE(v_oi.cost_at_time_cents, 0) / 100.0;  -- snapshot cost (cents→dollars)
    UPDATE order_items SET
      price_per_unit  = v_price,
      cost_per_unit   = v_cost,
      total_price     = v_price * total_units_needed,
      profit          = (v_price - v_cost) * total_units_needed,
      net_margin      = CASE WHEN v_price > 0 THEN ((v_price - v_cost) / v_price) * 100 ELSE 0 END,
      pricing_pending = false
    WHERE id = v_oi.id;
  END LOOP;

  -- ── any lines still pending? ──────────────────────────────────────────────
  SELECT count(*) INTO v_remaining
  FROM order_items WHERE order_id = p_order_id AND pricing_pending = true;

  IF v_remaining = 0 THEN
    -- pricing_status is NOT a trigger-gated column (enforce_order_status_transition
    -- is BEFORE UPDATE OF status only) — a plain UPDATE is safe.
    UPDATE orders SET pricing_status = 'priced', updated_at = now() WHERE id = p_order_id;

    -- deferred commissions on the FINAL profit, only on the needs_pricing→priced
    -- transition (re-read total_profit after trg_recalc_order_totals ran).
    IF v_was_pending THEN
      SELECT total_profit INTO v_total_profit FROM orders WHERE id = p_order_id;
      -- Codex round-7 P1: use the split SNAPSHOTTED onto the order at rush-order
      -- creation (create_rush_order stores customers.default_commission_split into
      -- orders.commission_split), NOT the customer's CURRENT default — a split change
      -- between ship and pricing must not re-attribute this sale's commissions.
      PERFORM _insert_commissions_for_order(
        p_order_id, v_order.customer_id, v_total_profit,
        v_order.commission_split, v_order.order_date
      );

      -- sweep linked DRAFT/UNPOSTED invoices to the now-known prices — gated on
      -- v_was_pending (the needs_pricing→priced transition) so a redundant re-call
      -- on an already-priced order never re-sweeps or re-dates a draft invoice.
      FOR v_inv IN SELECT * FROM invoices
                 WHERE order_id = p_order_id AND status IN ('draft','unposted') FOR UPDATE
    LOOP
      -- cost_cents is PER-UNIT by convention (create_invoice_from_delivery:
      -- total_cost_cents = SUM(cost_cents * quantity)). Codex P1: write per-unit
      -- cost, NOT the line total, or total_cost_cents double-counts quantity.
      UPDATE invoice_items ii SET
        unit_price_cents = round(oi.price_per_unit * 100)::bigint,
        extended_cents   = round(oi.price_per_unit * ii.quantity * 100)::bigint,
        cost_cents       = round(oi.cost_per_unit * 100)::bigint
      FROM order_items oi
      WHERE ii.invoice_id = v_inv.id AND ii.order_item_id = oi.id;

      -- Recompute BOTH header money columns (Codex P1: total_cost_cents was left
      -- at 0/stale → wrong posted margin + month-end profit). total_cost_cents
      -- mirrors the create_invoice_from_delivery convention SUM(cost_cents*qty).
      UPDATE invoices SET
        total_amount_cents = COALESCE((SELECT sum(extended_cents) FROM invoice_items WHERE invoice_id = v_inv.id), 0),
        total_cost_cents   = COALESCE((SELECT round(sum(cost_cents * quantity))::bigint FROM invoice_items WHERE invoice_id = v_inv.id), 0),
        invoice_date       = CURRENT_DATE,   -- G3: PRICE-MONTH
        pricing_pending    = false,
        updated_at         = now()
      WHERE id = v_inv.id;
      v_swept := v_swept + 1;
    END LOOP;
    END IF;  -- close v_was_pending (commissions + invoice sweep)
  END IF;  -- close v_remaining = 0

  INSERT INTO activity_feed (
    event_type, description, performed_by, related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'order_priced',
    'Priced order ' || v_order.order_number ||
    CASE WHEN v_remaining = 0 THEN ' — fully priced' ELSE ' — ' || v_remaining || ' line(s) still pending' END,
    v_actor, 'order', p_order_id, v_order.customer_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'pricing_status', CASE WHEN v_remaining = 0 THEN 'priced' ELSE 'needs_pricing' END,
    'remaining_pending', v_remaining,
    'invoices_swept', v_swept
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'price_order', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."price_order"("p_order_id" "uuid", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_offline_action"("p_client_action_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_receipt public.offline_action_receipts%ROWTYPE;
  v_result jsonb;
  v_sqlstate text;
  v_message text;
  v_failure_code text;
  v_failure_summary text;
  v_target_updated_at timestamptz;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = v_actor AND p.is_active = true
  ) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: active profile required';
  END IF;
  IF p_client_action_id IS NULL OR p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'PAYLOAD_INVALID: action ID and idempotency key are required';
  END IF;

  SELECT *
    INTO v_receipt
    FROM public.offline_action_receipts r
   WHERE r.client_action_id = p_client_action_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TARGET_NOT_FOUND: offline receipt not found';
  END IF;
  IF v_receipt.actor_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF v_receipt.idempotency_key IS DISTINCT FROM p_idempotency_key THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REUSE';
  END IF;

  IF v_receipt.status = 'succeeded' THEN
    RETURN jsonb_build_object(
      'client_action_id', v_receipt.client_action_id,
      'operation', v_receipt.operation,
      'entity_id', v_receipt.entity_id,
      'status', v_receipt.status,
      'result', v_receipt.result,
      'attempt_count', v_receipt.attempt_count,
      'succeeded_at', v_receipt.succeeded_at,
      'updated_at', v_receipt.updated_at
    );
  END IF;
  IF v_receipt.status = 'needs_review' THEN
    RAISE EXCEPTION 'OFFLINE_ACTION_NEEDS_REVIEW';
  END IF;

  -- Re-check immediately before the canonical mutation. This closes the gap
  -- where staging committed as received, the target changed, and processing
  -- retried later after a weak-connection interruption.
  IF v_receipt.entity_snapshot_at IS NOT NULL THEN
    IF v_receipt.operation = 'complete_delivery' THEN
      SELECT d.updated_at INTO v_target_updated_at
      FROM public.deliveries d
      WHERE d.id = v_receipt.entity_id
      FOR UPDATE;
    ELSE
      SELECT j.updated_at INTO v_target_updated_at
      FROM public.jobs j
      WHERE j.id = v_receipt.entity_id
      FOR UPDATE;
    END IF;
  END IF;

  IF v_receipt.entity_snapshot_at IS NULL
     OR v_target_updated_at IS DISTINCT FROM v_receipt.entity_snapshot_at THEN
    v_failure_code := CASE
      WHEN v_receipt.entity_snapshot_at IS NULL THEN 'LEGACY_OUTCOME_UNKNOWN'
      ELSE 'TARGET_STATE_CONFLICT'
    END;
    v_failure_summary := CASE
      WHEN v_receipt.entity_snapshot_at IS NULL
        THEN 'This saved action does not include a target snapshot. Office review is required before it can run.'
      ELSE 'The delivery or job changed after this action reached the server. Office review is required.'
    END;
    UPDATE public.offline_action_receipts
       SET status = 'needs_review',
           failure_code = v_failure_code,
           failure_summary = v_failure_summary,
           needs_review_at = now()
     WHERE client_action_id = p_client_action_id;
    RETURN jsonb_build_object(
      'client_action_id', v_receipt.client_action_id,
      'operation', v_receipt.operation,
      'entity_id', v_receipt.entity_id,
      'status', 'needs_review',
      'failure_code', v_failure_code,
      'failure_summary', v_failure_summary,
      'attempt_count', v_receipt.attempt_count
    );
  END IF;

  IF v_receipt.attempt_count >= 50 THEN
    UPDATE public.offline_action_receipts
       SET status = 'needs_review',
           failure_code = 'RETRY_LIMIT',
           failure_summary = 'The server retry limit was reached. Office review is required.',
           needs_review_at = now()
     WHERE client_action_id = p_client_action_id;
    RETURN jsonb_build_object(
      'client_action_id', v_receipt.client_action_id,
      'operation', v_receipt.operation,
      'entity_id', v_receipt.entity_id,
      'status', 'needs_review',
      'failure_code', 'RETRY_LIMIT',
      'failure_summary', 'The server retry limit was reached. Office review is required.'
    );
  END IF;

  UPDATE public.offline_action_receipts
     SET attempt_count = attempt_count + 1,
         last_attempt_at = now()
   WHERE client_action_id = p_client_action_id;

  BEGIN
    IF v_receipt.operation = 'complete_delivery' THEN
      SELECT public.complete_delivery(
        p_delivery_id => v_receipt.entity_id,
        p_signed_by => v_receipt.request_payload->>'signed_by',
        p_performed_by => v_actor,
        p_quantities => v_receipt.request_payload->'quantities',
        p_issue_type => v_receipt.request_payload->>'issue_type',
        p_issue_notes => v_receipt.request_payload->>'issue_notes',
        p_idempotency_key => v_receipt.idempotency_key,
        p_completed_at => (v_receipt.request_payload->>'completed_at')::timestamptz
      ) INTO v_result;

      IF jsonb_typeof(v_result) <> 'object'
         OR v_result->>'delivery_id' IS DISTINCT FROM v_receipt.entity_id::text
         OR v_result->>'status' NOT IN ('completed', 'partial') THEN
        RAISE EXCEPTION 'OFFLINE_RESULT_INVALID';
      END IF;

    ELSIF v_receipt.operation = 'complete_job' THEN
      SELECT public.complete_job(
        p_job_id => v_receipt.entity_id,
        p_applied_info => v_receipt.request_payload,
        p_performed_by => v_actor,
        p_idempotency_key => v_receipt.idempotency_key
      ) INTO v_result;

      IF jsonb_typeof(v_result) <> 'object'
         OR v_result->'success' IS DISTINCT FROM 'true'::jsonb
         OR v_result->>'job_id' IS DISTINCT FROM v_receipt.entity_id::text
         OR COALESCE(btrim(v_result->>'record_number'), '') = '' THEN
        RAISE EXCEPTION 'OFFLINE_RESULT_INVALID';
      END IF;

    ELSE
      RAISE EXCEPTION 'UNSUPPORTED_OPERATION';
    END IF;

  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
      v_sqlstate = RETURNED_SQLSTATE,
      v_message = MESSAGE_TEXT;

    -- These classes are retryable infrastructure/transaction failures. Re-raise
    -- so this entire call, including attempt_count, rolls back to received.
    IF left(v_sqlstate, 2) IN ('08', '40', '53', '57', '58') THEN
      RAISE;
    END IF;

    -- The canonical functions currently use stable English tokens rather than
    -- structured SQLSTATEs for business failures. Keep these phrases aligned
    -- with their live definitions; the rolled-back smoke deliberately catches
    -- drift in the lifecycle-conflict phrase.
    IF v_message = 'OFFLINE_RESULT_INVALID' THEN
      v_failure_code := 'RESULT_INVALID';
      v_failure_summary := 'The business action returned an unexpected result. Office review is required.';
    ELSIF v_message IN (
      'Not authorized to complete this delivery',
      'Not authorized to complete this job'
    ) THEN
      v_failure_code := 'NOT_AUTHORIZED';
      v_failure_summary := 'The current user is not authorized to complete this delivery or job.';
    ELSIF v_message LIKE 'Delivery not found:%'
       OR v_message LIKE 'Job not found:%' THEN
      v_failure_code := 'TARGET_NOT_FOUND';
      v_failure_summary := 'The referenced delivery or job no longer exists.';
    ELSIF v_message LIKE 'Delivery must be in_progress to complete%'
       OR v_message LIKE 'Job must be in_progress before completion.%' THEN
      v_failure_code := 'TARGET_STATE_CONFLICT';
      v_failure_summary := 'The delivery or job changed after this offline action was saved. Office comparison is required.';
    ELSIF v_message ILIKE '%IDEMPOTENCY%CROSS%OP%'
       OR v_message ILIKE '%idempotency%reuse%' THEN
      v_failure_code := 'IDEMPOTENCY_KEY_REUSE';
      v_failure_summary := 'The idempotency key is already tied to different work. Office review is required.';
    ELSIF v_sqlstate = '23505' THEN
      -- A canonical UNIQUE failure is not necessarily an idempotency collision
      -- (for example, a record-number collision). Do not mislabel it.
      v_failure_code := 'UNEXPECTED_SERVER_ERROR';
      v_failure_summary := 'The business action hit an unexpected uniqueness conflict. Office review is required.';
    ELSIF left(v_sqlstate, 2) IN ('22', '23') THEN
      v_failure_code := 'PAYLOAD_INVALID';
      v_failure_summary := 'The saved action no longer satisfies the database contract. Office review is required.';
    ELSE
      v_failure_code := 'UNEXPECTED_SERVER_ERROR';
      v_failure_summary := 'The server could not safely complete this action. Office review is required.';
    END IF;

    UPDATE public.offline_action_receipts
       SET status = 'needs_review',
           result = NULL,
           failure_code = v_failure_code,
           failure_summary = v_failure_summary,
           needs_review_at = now()
     WHERE client_action_id = p_client_action_id;

    RETURN jsonb_build_object(
      'client_action_id', v_receipt.client_action_id,
      'operation', v_receipt.operation,
      'entity_id', v_receipt.entity_id,
      'status', 'needs_review',
      'failure_code', v_failure_code,
      'failure_summary', v_failure_summary,
      'attempt_count', v_receipt.attempt_count + 1
    );
  END;

  UPDATE public.offline_action_receipts
     SET status = 'succeeded',
         result = v_result,
         failure_code = NULL,
         failure_summary = NULL,
         succeeded_at = now(),
         needs_review_at = NULL
   WHERE client_action_id = p_client_action_id
   RETURNING * INTO v_receipt;

  RETURN jsonb_build_object(
    'client_action_id', v_receipt.client_action_id,
    'operation', v_receipt.operation,
    'entity_id', v_receipt.entity_id,
    'status', v_receipt.status,
    'result', v_receipt.result,
    'attempt_count', v_receipt.attempt_count,
    'succeeded_at', v_receipt.succeeded_at,
    'updated_at', v_receipt.updated_at
  );
END;
$$;


ALTER FUNCTION "public"."process_offline_action"("p_client_action_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_offline_action"("p_client_action_id" "uuid", "p_idempotency_key" "text") IS 'Locks the durable receipt and target row, executes one canonical offline completion, and records its permanent outcome.';



CREATE OR REPLACE FUNCTION "public"."product_price_per_acre"("p_tier_price" numeric, "p_rate_per_acre" numeric, "p_rate_unit" "text", "p_inventory_unit" "text", "p_unit_size" "text") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rate_factor numeric;
  v_inv_factor  numeric;
  v_inv_unit    text;
BEGIN
  -- No usable rate -> no per-acre figure (matches frontend: returns null).
  IF p_rate_per_acre IS NULL OR p_rate_per_acre <= 0 THEN
    RETURN NULL;
  END IF;

  -- rate unit -> oz factor (case-insensitive; default 1 when absent/unknown).
  v_rate_factor := COALESCE(
    (SELECT factor_oz FROM unit_conversions WHERE lower(unit) = lower(p_rate_unit) LIMIT 1),
    1);

  -- inventory unit falls back to unit_size when blank/null (JS: inventory_unit || unit_size).
  v_inv_unit := COALESCE(NULLIF(p_inventory_unit, ''), p_unit_size);
  v_inv_factor := COALESCE(
    (SELECT factor_oz FROM unit_conversions WHERE lower(unit) = lower(v_inv_unit) LIMIT 1),
    1);

  -- Guard divide-by-zero (mirrors frontend `inventoryUnitFactorOz > 0`).
  IF v_inv_factor IS NULL OR v_inv_factor <= 0 THEN
    RETURN NULL;
  END IF;

  RETURN ROUND(
    (COALESCE(p_tier_price, 0) * (p_rate_per_acre * v_rate_factor) / v_inv_factor)::numeric,
    2);
END;
$$;


ALTER FUNCTION "public"."product_price_per_acre"("p_tier_price" numeric, "p_rate_per_acre" numeric, "p_rate_unit" "text", "p_inventory_unit" "text", "p_unit_size" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reassign_delivery"("p_delivery_id" "uuid", "p_new_driver" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_delivery record;
  v_old_driver uuid;
  v_result jsonb;
  v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true
      AND role IN ('admin', 'sales_rep')
  ) THEN
    IF NOT EXISTS (
      SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'driver'
    ) OR NOT EXISTS (
      SELECT 1 FROM deliveries WHERE id = p_delivery_id AND assigned_driver IS NULL
    ) THEN
      RAISE EXCEPTION 'Not authorized to reassign deliveries';
    END IF;
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'reassign_delivery');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = p_new_driver AND is_active = true AND role IN ('admin', 'sales_rep', 'driver')
  ) THEN
    RAISE EXCEPTION 'Target driver not found or inactive';
  END IF;

  SELECT * INTO v_delivery FROM deliveries WHERE id = p_delivery_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found'; END IF;
  IF v_delivery.status NOT IN ('scheduled', 'in_progress') THEN
    RAISE EXCEPTION 'Cannot reassign a % delivery', v_delivery.status;
  END IF;

  v_old_driver := v_delivery.assigned_driver;

  UPDATE deliveries SET
    assigned_driver = p_new_driver,
    last_edited_by = v_actor,
    last_edited_at = now(),
    updated_at = now()
  WHERE id = p_delivery_id;

  IF v_old_driver IS NOT NULL AND v_old_driver != p_new_driver THEN
    INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
    VALUES (
      v_old_driver, 'Delivery Reassigned',
      'Delivery ' || v_delivery.delivery_number || ' has been reassigned.',
      'delivery_update', 'delivery', p_delivery_id
    );
  END IF;

  INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
  VALUES (
    p_new_driver, 'New Delivery Assigned',
    'Delivery ' || v_delivery.delivery_number || ' has been assigned to you.',
    'delivery_update', 'delivery', p_delivery_id
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'delivery_reassigned',
    'Delivery ' || v_delivery.delivery_number || ' reassigned',
    v_actor, 'delivery', p_delivery_id, v_delivery.customer_id
  );

  v_result := jsonb_build_object('status', 'reassigned', 'delivery_id', p_delivery_id);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'reassign_delivery', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."reassign_delivery"("p_delivery_id" "uuid", "p_new_driver" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalc_product_price_per_acre"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t1 numeric := COALESCE(NEW.tier1_price, 0);  -- getTierPrice fallback base
BEGIN
  NEW.tier1_price_per_acre := public.product_price_per_acre(
    v_t1,
    NEW.rate_per_acre, NEW.rate_unit, NEW.inventory_unit, NEW.unit_size);
  NEW.tier2_price_per_acre := public.product_price_per_acre(
    COALESCE(NULLIF(NEW.tier2_price, 0), v_t1),
    NEW.rate_per_acre, NEW.rate_unit, NEW.inventory_unit, NEW.unit_size);
  NEW.tier3_price_per_acre := public.product_price_per_acre(
    COALESCE(NULLIF(NEW.tier3_price, 0), v_t1),
    NEW.rate_per_acre, NEW.rate_unit, NEW.inventory_unit, NEW.unit_size);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."recalc_product_price_per_acre"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_po_items"("p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_allow_over_receive" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item jsonb; v_po_item RECORD;
  v_existing jsonb; v_result jsonb;
  v_recv_id uuid; v_receiving_record_ids jsonb := '[]'::jsonb;
  v_qty numeric; v_actor uuid; v_actor_role text;
  v_affected_po_ids uuid[] := '{}'; v_unique_po_id uuid;
  v_condition text; v_lot_number text; v_notes text;
  v_storage_location text;
  v_over_receive boolean; v_over_receive_reason text;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;

  SELECT role INTO v_actor_role
    FROM profiles
   WHERE id = v_actor
     AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'Only admin or sales_rep can receive PO items';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'receive_po_items');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'No items provided for receiving';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_qty := COALESCE((v_item->>'quantity')::numeric, 0);
    IF v_qty::text IN ('NaN', 'Infinity', '-Infinity') THEN
      RAISE EXCEPTION 'Receiving quantity must be finite';
    END IF;
    IF v_qty <= 0 THEN
      RAISE EXCEPTION 'RECEIVING_QUANTITY_MUST_BE_POSITIVE';
    END IF;

    -- PARKED-009 + bug-hunt B2: lock BOTH the po_item AND its parent purchase_order.
    -- Locking poi serializes concurrent receives of the same item; locking po serializes
    -- receive against a concurrent cancel_purchase_order so a cancel can't slip in after
    -- we read po.status but before we increment inventory / roll the status up.
    SELECT poi.*, po.po_number, po.id AS po_parent_id, po.status AS po_status
      INTO v_po_item
      FROM purchase_order_items poi
      JOIN purchase_orders po ON po.id = poi.purchase_order_id
     WHERE poi.id = (v_item->>'po_item_id')::uuid
     FOR UPDATE OF poi, po;

    IF NOT FOUND THEN RAISE EXCEPTION 'PO item not found: %', v_item->>'po_item_id'; END IF;

    -- Fail fast on a PO that cannot legitimately be received. draft (never submitted)
    -- and cancelled are the states where a receive today wastefully touches inventory
    -- before the status-transition trigger rejects the roll-up. submitted /
    -- partially_received / fully_received stay receivable (fully_received only via
    -- p_allow_over_receive, preserving the existing over-receive correction path).
    IF v_po_item.po_status IN ('draft', 'cancelled') THEN
      RAISE EXCEPTION 'Cannot receive against PO % -- status is % (draft/cancelled cannot be received)',
        v_po_item.po_number, v_po_item.po_status;
    END IF;

    v_over_receive :=
      (COALESCE(v_po_item.quantity_received, 0) + v_qty) > v_po_item.quantity_ordered;
    v_over_receive_reason := NULLIF(btrim(v_item->>'over_receive_reason'), '');

    IF v_over_receive AND NOT COALESCE(p_allow_over_receive, false) THEN
      RAISE EXCEPTION 'Cannot receive more than ordered for item %. Ordered: %, Already received: %, Attempting: %',
        v_po_item.id, v_po_item.quantity_ordered, COALESCE(v_po_item.quantity_received, 0), v_qty;
    END IF;
    IF v_over_receive AND v_actor_role <> 'admin' THEN
      RAISE EXCEPTION 'OVER_RECEIVE_ADMIN_REQUIRED';
    END IF;
    IF v_over_receive AND v_over_receive_reason IS NULL THEN
      RAISE EXCEPTION 'OVER_RECEIVE_REASON_REQUIRED';
    END IF;

    v_condition := COALESCE(v_item->>'condition', 'good');
    v_lot_number := v_item->>'lot_number';
    v_notes := v_item->>'notes';
    IF v_over_receive THEN
      v_notes := concat_ws(' | ', NULLIF(btrim(v_notes), ''), 'OVER-RECEIVE: ' || v_over_receive_reason);
    END IF;
    v_storage_location := COALESCE(v_item->>'storage_location', 'Main Warehouse');

    UPDATE inventory SET
      quantity_available = quantity_available + v_qty,
      quantity_on_order = GREATEST(COALESCE(quantity_on_order, 0) - v_qty, 0),
      updated_at = now()
    WHERE product_id = v_po_item.product_id AND location = v_storage_location;

    IF NOT FOUND THEN
      INSERT INTO inventory (product_id, location, quantity_available, quantity_on_order, quantity_prebooked, unit_size)
      VALUES (v_po_item.product_id, v_storage_location, v_qty, 0, 0, v_po_item.unit_size);
    END IF;

    INSERT INTO inventory_transactions (product_id, transaction_type, quantity, to_location,
      purchase_order_id, performed_by, notes)
    VALUES (v_po_item.product_id, 'received', v_qty, v_storage_location,
      v_po_item.po_parent_id, v_actor,
      concat_ws(
        ' | ',
        'Received ' || v_qty || ' units via PO ' || COALESCE(v_po_item.po_number, ''),
        CASE WHEN v_over_receive
          THEN 'OVER-RECEIVE: ' || v_over_receive_reason
        END
      ));

    INSERT INTO receiving_records (purchase_order_id, po_item_id, product_id,
      quantity_received, received_by, notes, condition,
      lot_number, storage_location, unit_size)
    VALUES (v_po_item.po_parent_id, v_po_item.id, v_po_item.product_id,
      v_qty, v_actor, v_notes, v_condition,
      v_lot_number, v_storage_location, v_po_item.unit_size)
    RETURNING id INTO v_recv_id;

    v_receiving_record_ids := v_receiving_record_ids || to_jsonb(v_recv_id::text);

    IF NOT v_po_item.po_parent_id = ANY(v_affected_po_ids) THEN
      v_affected_po_ids := v_affected_po_ids || v_po_item.po_parent_id;
    END IF;

    UPDATE purchase_order_items SET
      quantity_received = COALESCE(quantity_received, 0) + v_qty
    WHERE id = v_po_item.id;
  END LOOP;

  FOREACH v_unique_po_id IN ARRAY (SELECT ARRAY(SELECT DISTINCT unnest(v_affected_po_ids)))
  LOOP
    -- A large over-receipt on one line must never hide an open line on another.
    -- The PO is fully received only when every individual line is complete.
    IF NOT EXISTS (
      SELECT 1 FROM purchase_order_items
       WHERE purchase_order_id = v_unique_po_id
         AND COALESCE(quantity_received, 0) < quantity_ordered
    ) THEN
      UPDATE purchase_orders SET status = 'fully_received', updated_at = now()
      WHERE id = v_unique_po_id AND status != 'fully_received';
    ELSIF EXISTS (
      SELECT 1 FROM purchase_order_items
       WHERE purchase_order_id = v_unique_po_id
         AND COALESCE(quantity_received, 0) > 0
    ) THEN
      UPDATE purchase_orders SET status = 'partially_received', updated_at = now()
      WHERE id = v_unique_po_id AND status != 'partially_received';
    END IF;
  END LOOP;

  v_result := jsonb_build_object('status', 'received', 'receiving_record_ids', v_receiving_record_ids);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'receive_po_items', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."receive_po_items"("p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text", "p_allow_over_receive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_return"("p_return_id" "uuid", "p_received_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_order_id uuid;
  v_customer_id uuid;
  v_order_customer_id uuid;
  v_order_status text;
  v_is_legacy_unlinked boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_received_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'receive_return');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT r.order_id, r.customer_id INTO v_order_id, v_customer_id
  FROM public.returns r
  WHERE r.id = p_return_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Return not found: %', p_return_id; END IF;

  IF v_order_id IS NOT NULL THEN
    SELECT o.status, o.customer_id INTO v_order_status, v_order_customer_id
    FROM public.orders o
    WHERE o.id = v_order_id AND o.deleted_at IS NULL
    FOR UPDATE;
    IF NOT FOUND OR v_order_status IN ('voided', 'cancelled') THEN
      RAISE EXCEPTION 'RETURN_SOURCE_ORDER_INACTIVE';
    END IF;
    IF v_order_customer_id IS DISTINCT FROM v_customer_id THEN
      RAISE EXCEPTION 'RETURN_ORDER_CUSTOMER_MISMATCH';
    END IF;

    -- Older linked rows were writable through table policies, so re-derive and
    -- verify every source fact before the legacy implementation can restock.
    IF NOT EXISTS (
      SELECT 1 FROM public.return_items ri WHERE ri.return_id = p_return_id
    ) OR EXISTS (
      SELECT 1
      FROM public.return_items ri
      LEFT JOIN public.order_items oi
        ON oi.id = ri.order_item_id AND oi.order_id = v_order_id
      WHERE ri.return_id = p_return_id
        AND (
          ri.order_item_id IS NULL
          OR oi.id IS NULL
          OR oi.price_per_unit IS NULL
          OR ri.product_id IS DISTINCT FROM oi.product_id
          OR ri.unit IS DISTINCT FROM coalesce(oi.unit_size, 'ea')
          OR ri.quantity <= 0
          OR ri.quantity > coalesce(oi.quantity_delivered, 0)
          OR ri.unit_price_cents IS DISTINCT FROM round(oi.price_per_unit * 100)::bigint
          OR ri.extended_cents IS DISTINCT FROM round(ri.quantity * oi.price_per_unit * 100)::bigint
        )
    ) OR (
      SELECT count(*) <> count(DISTINCT ri.order_item_id)
      FROM public.return_items ri
      WHERE ri.return_id = p_return_id
    ) OR EXISTS (
      SELECT 1
      FROM public.return_items current_ri
      JOIN public.order_items oi
        ON oi.id = current_ri.order_item_id AND oi.order_id = v_order_id
      WHERE current_ri.return_id = p_return_id
        AND (
          SELECT coalesce(sum(other_ri.quantity), 0)
          FROM public.return_items other_ri
          JOIN public.returns other_r ON other_r.id = other_ri.return_id
          WHERE other_ri.order_item_id = oi.id
            AND other_r.deleted_at IS NULL
            AND other_r.status NOT IN ('rejected', 'cancelled')
        ) > coalesce(oi.quantity_delivered, 0)
    ) THEN
      RAISE EXCEPTION 'RETURN_SOURCE_NOT_VERIFIED';
    END IF;
  ELSE
    -- Exact one-time compatibility for the sole approved production RMA that
    -- predates order-line capture. IDs and immutable source/money fields were
    -- verified read-only immediately before this migration was authored.
    v_is_legacy_unlinked := p_return_id = '0cb556ed-467a-4949-866d-8d9edbb09522'::uuid
      AND EXISTS (
        SELECT 1
        FROM public.returns r
        WHERE r.id = p_return_id
          AND r.return_number = 'RMA-2026-0001'
          AND r.customer_id = 'df6087cb-232f-4962-bb33-c74580a06935'::uuid
          AND r.requested_by = '22c1fc50-4d2a-4baa-8ff8-341c0c7edd4f'::uuid
          AND r.approved_by = '22c1fc50-4d2a-4baa-8ff8-341c0c7edd4f'::uuid
          AND r.reason = 'overstock'
          AND r.created_at = timestamptz '2026-04-30 20:48:18.967975+00'
          AND r.requested_at = timestamptz '2026-04-30 20:48:18.967975+00'
          AND r.approved_at = timestamptz '2026-07-10 16:45:29.044351+00'
          AND r.total_credit_cents = 0
      )
      AND 1 = (
        SELECT count(*) FROM public.return_items ri WHERE ri.return_id = p_return_id
      )
      AND EXISTS (
        SELECT 1
        FROM public.return_items ri
        WHERE ri.return_id = p_return_id
          AND ri.id = 'c4f6cc7d-0bbd-4c25-8bc0-c2c9e84aaadd'::uuid
          AND ri.order_item_id IS NULL
          AND ri.product_id = 'fad3ea45-cd8c-4bb8-b0ce-8a515941586c'::uuid
          AND ri.product_name = 'Gen Capture LFR: (Batallion LFC, Seguro) - 2.5 Gal'
          AND ri.quantity = 15.00
          AND ri.unit = 'ea'
          AND ri.unit_price_cents = 7597
          AND ri.extended_cents = 113955
          AND ri.condition = 'unopened'
          AND ri.restock = true
          AND ri.restocked = false
          AND ri.sort_order = 0
          AND ri.notes IS NULL
          AND ri.created_at = timestamptz '2026-04-30 20:48:19.173027+00'
      );
    IF NOT v_is_legacy_unlinked THEN
      RAISE EXCEPTION 'RETURN_SOURCE_NOT_VERIFIED';
    END IF;
  END IF;

  RETURN public._receive_return_impl_20260714(
    p_return_id, v_actor, p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."receive_return"("p_return_id" "uuid", "p_received_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recompute_job_applied_acres"("p_job_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_job_id IS NULL THEN
    RETURN;
  END IF;

  -- Per-JOB total feeding remaining_acres: sum applied_acres across ALL of the
  -- job's records (manual-only #17 records included; per-location records contribute
  -- the child-sum the child trigger keeps current). NEVER writes remaining_acres.
  UPDATE jobs
  SET applied_acres = COALESCE((
    SELECT SUM(r.applied_acres)
    FROM job_applied_records r
    WHERE r.job_id = p_job_id
  ), 0)
  WHERE jobs.id = p_job_id;
END;
$$;


ALTER FUNCTION "public"."recompute_job_applied_acres"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_negative_inventory"("p_inventory_id" "uuid", "p_new_quantity" numeric, "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_existing jsonb;
  v_inv      record;
  v_delta    numeric;
  v_result   jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Admin access required to reconcile inventory';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required for reconciliation';
  END IF;

  IF p_new_quantity IS NULL OR p_new_quantity < 0 THEN
    RAISE EXCEPTION 'New quantity must be >= 0';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'reconcile_negative_inventory');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_inv FROM inventory WHERE id = p_inventory_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory row not found: %', p_inventory_id;
  END IF;

  v_delta := p_new_quantity - COALESCE(v_inv.quantity_available, 0);

  UPDATE inventory
  SET quantity_available = p_new_quantity,
      updated_at = now()
  WHERE id = p_inventory_id;

  INSERT INTO inventory_transactions (
    product_id, transaction_type, quantity,
    to_location, performed_by, notes
  ) VALUES (
    v_inv.product_id, 'adjusted', v_delta,
    v_inv.location, v_actor,
    'RECONCILIATION (was ' || COALESCE(v_inv.quantity_available, 0)::text ||
    ', now ' || p_new_quantity::text || '): ' || p_reason
  );

  v_result := jsonb_build_object(
    'success',           true,
    'inventory_id',      p_inventory_id,
    'product_id',        v_inv.product_id,
    'old_quantity',      COALESCE(v_inv.quantity_available, 0),
    'new_quantity',      p_new_quantity,
    'delta',             v_delta
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'reconcile_negative_inventory', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."reconcile_negative_inventory"("p_inventory_id" "uuid", "p_new_quantity" numeric, "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_prepay_balances"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cust record;
  v_actual bigint;
  v_fixes jsonb := '[]'::jsonb;
  v_fix_count integer := 0;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin' AND is_active = true
  ) THEN
    RAISE EXCEPTION 'Only admins can run prepay reconciliation';
  END IF;

  FOR v_cust IN
    SELECT c.id, c.farm_name, COALESCE(c.prepay_balance_cents, 0) AS cached_balance
    FROM customers c WHERE c.is_active = true
  LOOP
    SELECT COALESCE(SUM(pc.balance_cents), 0) INTO v_actual
    FROM prepay_credits pc
    WHERE pc.customer_id = v_cust.id AND pc.balance_cents > 0;

    IF v_cust.cached_balance IS DISTINCT FROM v_actual THEN
      UPDATE customers SET prepay_balance_cents = v_actual, updated_at = now()
      WHERE id = v_cust.id;

      v_fixes := v_fixes || jsonb_build_object(
        'customer_id', v_cust.id, 'customer_name', v_cust.farm_name,
        'old_cached', v_cust.cached_balance, 'actual', v_actual,
        'difference', v_actual - v_cust.cached_balance
      );
      v_fix_count := v_fix_count + 1;
    END IF;
  END LOOP;

  IF v_fix_count > 0 THEN
    INSERT INTO financial_audit_log (
      operation_type, entity_type, entity_id,
      actor_user_id, total_impact_cents, description
    ) VALUES (
      'prepay_reconciliation', 'customer', NULL,
      auth.uid(), 0,
      'Reconciled prepay balances: ' || v_fix_count || ' customer(s) corrected'
    );
  END IF;

  RETURN jsonb_build_object(
    'total_checked', (SELECT COUNT(*) FROM customers WHERE is_active = true),
    'discrepancies_found', v_fix_count,
    'corrections', v_fixes
  );
END;
$$;


ALTER FUNCTION "public"."reconcile_prepay_balances"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_invoice_payment"("p_invoice_id" "uuid", "p_amount_cents" bigint, "p_payment_method" "text", "p_reference_number" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION 'LEGACY_PAYMENT_PATH_DISABLED: record_invoice_payment used an obsolete ledger with no compatible reversal. Use allocate_payment so cash can be safely unapplied through void_payment.';
END;
$$;


ALTER FUNCTION "public"."record_invoice_payment"("p_invoice_id" "uuid", "p_amount_cents" bigint, "p_payment_method" "text", "p_reference_number" "text", "p_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_job_post_notifications"("p_job_id" "uuid", "p_subject" "text", "p_message" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor               uuid;
  v_role                text;
  v_existing            jsonb;
  v_primary_customer_id uuid;
  v_job_status          text;
  v_recipient           record;
  v_email               text;
  v_per_email_key       text;
  v_row_id              uuid;
  v_recipients          jsonb := '[]'::jsonb;
  v_sent_count          int := 0;
  v_failed_count        int := 0;
  v_result              jsonb;
BEGIN
  -- actor / strict-actor / role gate (admin or sales_rep send notifications).
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales_rep required';
  END IF;

  IF p_subject IS NULL OR btrim(p_subject) = '' THEN
    RAISE EXCEPTION 'INVALID_SUBJECT: a non-empty subject is required';
  END IF;
  IF p_message IS NULL OR btrim(p_message) = '' THEN
    RAISE EXCEPTION 'INVALID_MESSAGE: a non-empty message is required';
  END IF;

  -- Load the job's primary customer + status (also validates the job exists).
  SELECT j.customer_id, j.status INTO v_primary_customer_id, v_job_status
  FROM jobs j WHERE j.id = p_job_id AND j.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'JOB_NOT_FOUND: job % does not exist', p_job_id;
  END IF;

  -- LIFECYCLE GATE (bug-hunt B1): a POST-application notice only makes sense for a
  -- job whose work HAS happened — completed or invoiced. This gate now runs BEFORE the
  -- idempotency replay, so a retry after the job's status changed cannot re-drive a
  -- stale "application complete" notice on a job that is no longer completed/invoiced.
  IF v_job_status NOT IN ('completed', 'invoiced') THEN
    RAISE EXCEPTION 'JOB_NOT_POST_NOTIFIABLE: job % is % (post-notice requires completed or invoiced)', p_job_id, v_job_status;
  END IF;

  -- idempotency: return the cached result if this key already ran for THIS op —
  -- ONLY reached once the lifecycle gate above has (re-)passed for the CURRENT status.
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'record_job_post_notifications');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  -- Resolve the DISTINCT share customers with the SAME precedence the compliance
  -- resolver uses (get_job_billed_customers). IDENTICAL to record_job_pre_notifications.
  FOR v_recipient IN
    WITH job_field_ids AS (
      SELECT DISTINCT jf.field_id
      FROM job_fields jf
      WHERE jf.job_id = p_job_id AND jf.field_id IS NOT NULL
    ),
    fields_with_share AS (
      SELECT DISTINCT jfs.field_id
      FROM job_field_shares jfs
      JOIN job_field_ids jfi ON jfi.field_id = jfs.field_id
      WHERE jfs.job_id = p_job_id
    ),
    resolved AS (
      SELECT jfs.customer_id
      FROM job_field_shares jfs
      JOIN job_field_ids jfi ON jfi.field_id = jfs.field_id
      WHERE jfs.job_id = p_job_id AND jfs.customer_id IS NOT NULL

      UNION ALL

      SELECT fbd.customer_id
      FROM job_field_ids jfi
      JOIN field_billing_defaults fbd ON fbd.field_id = jfi.field_id
      WHERE jfi.field_id NOT IN (SELECT field_id FROM fields_with_share)
        AND fbd.customer_id IS NOT NULL

      UNION ALL

      SELECT v_primary_customer_id
      FROM job_field_ids jfi
      WHERE jfi.field_id NOT IN (SELECT field_id FROM fields_with_share)
        AND NOT EXISTS (
          SELECT 1 FROM field_billing_defaults fbd WHERE fbd.field_id = jfi.field_id
        )
        AND v_primary_customer_id IS NOT NULL

      UNION ALL

      SELECT v_primary_customer_id
      WHERE NOT EXISTS (SELECT 1 FROM job_field_ids)
        AND v_primary_customer_id IS NOT NULL
    )
    SELECT
      c.id AS customer_id,
      c.farm_name,
      c.email,
      (c.id = v_primary_customer_id) AS is_primary
    FROM (SELECT DISTINCT r.customer_id FROM resolved r) d
    JOIN customers c ON c.id = d.customer_id
    ORDER BY (c.id = v_primary_customer_id) DESC, c.farm_name NULLS LAST
  LOOP
    v_email := nullif(btrim(coalesce(v_recipient.email, '')), '');
    v_per_email_key := CASE
      WHEN v_email IS NULL OR p_idempotency_key IS NULL THEN NULL
      ELSE p_idempotency_key || ':' || v_recipient.customer_id::text
    END;

    INSERT INTO job_notifications
      (job_id, notification_type, customer_id, recipient_email, channel,
       subject, message, status, sent_at, sent_by, idempotency_key)
    VALUES
      (p_job_id, 'post', v_recipient.customer_id, v_email, 'email',
       p_subject, p_message, 'failed', NULL, v_actor, v_per_email_key)
    RETURNING id INTO v_row_id;

    IF v_email IS NULL THEN
      v_failed_count := v_failed_count + 1;
    ELSE
      v_sent_count := v_sent_count + 1;
    END IF;

    v_recipients := v_recipients || jsonb_build_object(
      'notification_id', v_row_id,
      'customer_id', v_recipient.customer_id,
      'farm_name',   v_recipient.farm_name,
      'email',       v_email,
      'has_email',   (v_email IS NOT NULL),
      'email_idempotency_key', v_per_email_key,
      'is_primary',  v_recipient.is_primary
    );
  END LOOP;

  IF jsonb_array_length(v_recipients) = 0 THEN
    RAISE EXCEPTION 'NO_RECIPIENTS: job % has no resolvable customer to notify', p_job_id;
  END IF;

  INSERT INTO activity_feed
    (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES (
    'job_post_notification_sent',
    'Post-application notice recorded for ' || v_sent_count || ' recipient(s) with email'
      || CASE WHEN v_failed_count > 0
              THEN ' (' || v_failed_count || ' with no email on file)'
              ELSE '' END,
    v_actor, 'job', p_job_id, v_primary_customer_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'recipients_with_email', v_sent_count,
    'recipients_without_email', v_failed_count,
    'recipients', v_recipients
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'record_job_post_notifications', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."record_job_post_notifications"("p_job_id" "uuid", "p_subject" "text", "p_message" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_job_post_notifications"("p_job_id" "uuid", "p_subject" "text", "p_message" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Field-app #41: records a per-recipient post-application notification log on a job (notification_type=post), resolving the job''s distinct share customers via the get_job_billed_customers precedence. Every row is recorded status=failed and only flips to sent via confirm_job_notification_sent after the outbound email succeeds. Lifecycle-gated to completed/invoiced. SECURITY DEFINER; admin/sales_rep only.';



CREATE OR REPLACE FUNCTION "public"."record_job_pre_notifications"("p_job_id" "uuid", "p_subject" "text", "p_message" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor               uuid;
  v_role                text;
  v_existing            jsonb;
  v_primary_customer_id uuid;
  v_job_status          text;
  v_recipient           record;
  v_email               text;
  v_per_email_key       text;
  v_row_id              uuid;
  v_recipients          jsonb := '[]'::jsonb;
  v_sent_count          int := 0;   -- recipients WITH an email (a send will be attempted)
  v_failed_count        int := 0;   -- recipients with NO email on file
  v_result              jsonb;
BEGIN
  -- actor / strict-actor / role gate (admin or sales_rep send notifications).
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales_rep required';
  END IF;

  IF p_subject IS NULL OR btrim(p_subject) = '' THEN
    RAISE EXCEPTION 'INVALID_SUBJECT: a non-empty subject is required';
  END IF;
  IF p_message IS NULL OR btrim(p_message) = '' THEN
    RAISE EXCEPTION 'INVALID_MESSAGE: a non-empty message is required';
  END IF;

  -- Load the job's primary customer + status (also validates the job exists).
  SELECT j.customer_id, j.status INTO v_primary_customer_id, v_job_status
  FROM jobs j WHERE j.id = p_job_id AND j.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'JOB_NOT_FOUND: job % does not exist', p_job_id;
  END IF;

  -- LIFECYCLE GATE (Codex #40 P2 + bug-hunt B1): a PRE-application notice only makes
  -- sense for a job that has NOT happened yet — scheduled or in_progress. This gate
  -- now runs BEFORE the idempotency replay (B1), so a retry after the job's status
  -- changed cannot re-drive a stale "upcoming application" notice.
  IF v_job_status NOT IN ('scheduled', 'in_progress') THEN
    RAISE EXCEPTION 'JOB_NOT_PRE_NOTIFIABLE: job % is % (pre-notice requires scheduled or in_progress)', p_job_id, v_job_status;
  END IF;

  -- idempotency: return the cached result if this key already ran for THIS op —
  -- ONLY reached once the lifecycle gate above has (re-)passed for the CURRENT status.
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'record_job_pre_notifications');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  -- Resolve the DISTINCT share customers with the SAME precedence the compliance
  -- resolver uses, so a pre-notice targets exactly the parties a split-billed job
  -- bills: explicit job_field_shares, else field_billing_defaults, else the job's
  -- primary customer. Record one row per resolved customer.
  FOR v_recipient IN
    WITH job_field_ids AS (
      SELECT DISTINCT jf.field_id
      FROM job_fields jf
      WHERE jf.job_id = p_job_id AND jf.field_id IS NOT NULL
    ),
    fields_with_share AS (
      SELECT DISTINCT jfs.field_id
      FROM job_field_shares jfs
      JOIN job_field_ids jfi ON jfi.field_id = jfs.field_id
      WHERE jfs.job_id = p_job_id
    ),
    resolved AS (
      -- 1. Saved per-field shares (explicit split) — only fields on the job.
      SELECT jfs.customer_id
      FROM job_field_shares jfs
      JOIN job_field_ids jfi ON jfi.field_id = jfs.field_id
      WHERE jfs.job_id = p_job_id AND jfs.customer_id IS NOT NULL

      UNION ALL

      -- 2. field_billing_defaults for fields WITHOUT a saved share.
      SELECT fbd.customer_id
      FROM job_field_ids jfi
      JOIN field_billing_defaults fbd ON fbd.field_id = jfi.field_id
      WHERE jfi.field_id NOT IN (SELECT field_id FROM fields_with_share)
        AND fbd.customer_id IS NOT NULL

      UNION ALL

      -- 3. The job's PRIMARY customer for fields with neither.
      SELECT v_primary_customer_id
      FROM job_field_ids jfi
      WHERE jfi.field_id NOT IN (SELECT field_id FROM fields_with_share)
        AND NOT EXISTS (
          SELECT 1 FROM field_billing_defaults fbd WHERE fbd.field_id = jfi.field_id
        )
        AND v_primary_customer_id IS NOT NULL

      UNION ALL

      -- 4. SAFETY FALLBACK: a job with NO fields still has a primary customer.
      SELECT v_primary_customer_id
      WHERE NOT EXISTS (SELECT 1 FROM job_field_ids)
        AND v_primary_customer_id IS NOT NULL
    )
    SELECT
      c.id AS customer_id,
      c.farm_name,
      c.email,
      (c.id = v_primary_customer_id) AS is_primary
    FROM (SELECT DISTINCT r.customer_id FROM resolved r) d
    JOIN customers c ON c.id = d.customer_id
    ORDER BY (c.id = v_primary_customer_id) DESC, c.farm_name NULLS LAST
  LOOP
    v_email := nullif(btrim(coalesce(v_recipient.email, '')), '');
    v_per_email_key := CASE
      WHEN v_email IS NULL OR p_idempotency_key IS NULL THEN NULL
      ELSE p_idempotency_key || ':' || v_recipient.customer_id::text
    END;

    INSERT INTO job_notifications
      (job_id, notification_type, customer_id, recipient_email, channel,
       subject, message, status, sent_at, sent_by, idempotency_key)
    VALUES
      (p_job_id, 'pre', v_recipient.customer_id, v_email, 'email',
       p_subject, p_message, 'failed', NULL, v_actor, v_per_email_key)
    RETURNING id INTO v_row_id;

    IF v_email IS NULL THEN
      v_failed_count := v_failed_count + 1;
    ELSE
      v_sent_count := v_sent_count + 1;
    END IF;

    v_recipients := v_recipients || jsonb_build_object(
      'notification_id', v_row_id,
      'customer_id', v_recipient.customer_id,
      'farm_name',   v_recipient.farm_name,
      'email',       v_email,
      'has_email',   (v_email IS NOT NULL),
      'email_idempotency_key', v_per_email_key,
      'is_primary',  v_recipient.is_primary
    );
  END LOOP;

  IF jsonb_array_length(v_recipients) = 0 THEN
    RAISE EXCEPTION 'NO_RECIPIENTS: job % has no resolvable customer to notify', p_job_id;
  END IF;

  INSERT INTO activity_feed
    (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES (
    'job_pre_notification_sent',
    'Pre-application notice recorded for ' || v_sent_count || ' recipient(s) with email'
      || CASE WHEN v_failed_count > 0
              THEN ' (' || v_failed_count || ' with no email on file)'
              ELSE '' END,
    v_actor, 'job', p_job_id, v_primary_customer_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'recipients_with_email', v_sent_count,
    'recipients_without_email', v_failed_count,
    'recipients', v_recipients
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'record_job_pre_notifications', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."record_job_pre_notifications"("p_job_id" "uuid", "p_subject" "text", "p_message" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_job_pre_notifications"("p_job_id" "uuid", "p_subject" "text", "p_message" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Field-app #40: records a per-recipient pre-application notification log on a job (notification_type=pre), resolving the job''s distinct share customers via the get_job_billed_customers precedence. Every row is recorded status=failed and only flips to sent via confirm_job_notification_sent after the outbound email succeeds. Lifecycle-gated to scheduled/in_progress. SECURITY DEFINER; admin/sales_rep only.';



CREATE OR REPLACE FUNCTION "public"."record_vendor_payment"("p_vendor_bill_id" "uuid", "p_amount_cents" bigint, "p_payment_date" "date" DEFAULT CURRENT_DATE, "p_payment_method" "text" DEFAULT NULL::"text", "p_reference_number" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_payment_id uuid; v_bill record; v_new_paid bigint; v_new_status text;
  v_actor uuid; v_actor_role text; v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role <> 'admin' THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin role required to record vendor payments';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'record_vendor_payment');
    IF v_existing IS NOT NULL THEN RETURN (v_existing->>'payment_id')::uuid; END IF;
  END IF;

  SELECT * INTO v_bill FROM vendor_bills WHERE id = p_vendor_bill_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'BILL_NOT_FOUND: vendor bill % does not exist', p_vendor_bill_id; END IF;
  IF v_bill.status = 'voided' THEN RAISE EXCEPTION 'BILL_VOIDED: cannot record payment on a voided bill'; END IF;
  IF p_amount_cents <= 0 THEN RAISE EXCEPTION 'INVALID_AMOUNT: payment amount must be positive'; END IF;
  IF p_amount_cents > v_bill.balance_cents THEN
    RAISE EXCEPTION 'OVER_PAYMENT: payment of $% exceeds remaining balance $%',
      (p_amount_cents / 100.0)::numeric(12,2), (v_bill.balance_cents / 100.0)::numeric(12,2);
  END IF;

  PERFORM check_period_open(p_payment_date);

  INSERT INTO vendor_payments (vendor_bill_id, payment_date, amount_cents, payment_method,
    reference_number, notes, created_by)
  VALUES (p_vendor_bill_id, p_payment_date, p_amount_cents, p_payment_method,
    p_reference_number, p_notes, v_actor)
  RETURNING id INTO v_payment_id;

  v_new_paid := COALESCE(v_bill.paid_cents, 0) + p_amount_cents;
  v_new_status := CASE
    WHEN v_new_paid >= v_bill.total_cents THEN 'paid'
    WHEN v_new_paid > 0 THEN 'partially_paid'
    ELSE 'unpaid' END;

  UPDATE vendor_bills SET paid_cents = v_new_paid, status = v_new_status, updated_at = now()
    WHERE id = p_vendor_bill_id;

  INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_user_id, actor_role,
    new_values, total_impact_cents, description)
  VALUES ('vendor_payment_recorded', 'vendor_payment', v_payment_id, v_actor, v_actor_role,
    jsonb_build_object('vendor_bill_id', p_vendor_bill_id, 'amount_cents', p_amount_cents,
      'payment_method', p_payment_method, 'reference_number', p_reference_number, 'new_bill_status', v_new_status),
    p_amount_cents,
    'Payment of $' || (p_amount_cents / 100.0)::numeric(12,2) ||
      ' on vendor bill ' || COALESCE(NULLIF(v_bill.bill_number, ''), p_vendor_bill_id::text));

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'record_vendor_payment', jsonb_build_object('payment_id', v_payment_id));
  END IF;

  RETURN v_payment_id;
END;
$_$;


ALTER FUNCTION "public"."record_vendor_payment"("p_vendor_bill_id" "uuid", "p_amount_cents" bigint, "p_payment_date" "date", "p_payment_method" "text", "p_reference_number" "text", "p_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_watchdog_flags"("p_job_id" "uuid" DEFAULT NULL::"uuid", "p_acre_divergence_threshold" numeric DEFAULT 10, "p_rate_fallback_multiple" numeric DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_inserted int := 0;
  v_deleted  int := 0;
BEGIN
  v_actor := auth.uid();

  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'WATCHDOG_ACCESS_DENIED: admin or sales_rep role required';
  END IF;

  IF p_acre_divergence_threshold IS NULL OR p_acre_divergence_threshold <= 0 THEN
    RAISE EXCEPTION 'INVALID_THRESHOLD: acre_divergence_threshold must be > 0';
  END IF;
  IF p_rate_fallback_multiple IS NULL OR p_rate_fallback_multiple <= 0 THEN
    RAISE EXCEPTION 'INVALID_THRESHOLD: rate_fallback_multiple must be > 0';
  END IF;

  -- ── Remove stale flags (non-dismissed) in scope ──────────────────────────
  IF p_job_id IS NOT NULL THEN
    DELETE FROM watchdog_flags wf
    WHERE wf.job_id = p_job_id
      AND NOT EXISTS (
        SELECT 1 FROM watchdog_flag_dismissals d WHERE d.flag_id = wf.id
      );
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
  ELSE
    DELETE FROM watchdog_flags wf
    WHERE NOT EXISTS (
      SELECT 1 FROM watchdog_flag_dismissals d WHERE d.flag_id = wf.id
    );
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
  END IF;

  -- ── FLAG 1: Acre Divergence (unchanged) ───────────────────────────────────
  INSERT INTO watchdog_flags (
    natural_key, flag_type, severity, entity_type, entity_id,
    job_id, customer_id, message, detail
  )
  SELECT
    'acre_divergence:job:' || j.id::text,
    'acre_divergence'::text,
    'warning'::text,
    'job'::text,
    j.id,
    j.id,
    j.customer_id,
    format(
      'Job %s applied acres (%s) diverge %s%% from total field boundary acres (%s)',
      j.job_number,
      j.applied_acres,
      ROUND(
        ABS(j.applied_acres - field_totals.boundary_acres)
          / NULLIF(field_totals.boundary_acres, 0) * 100,
        1
      ),
      ROUND(field_totals.boundary_acres, 2)
    ),
    jsonb_build_object(
      'applied_acres',    j.applied_acres,
      'boundary_acres',   ROUND(field_totals.boundary_acres, 2),
      'divergence_pct',
        ROUND(
          ABS(j.applied_acres - field_totals.boundary_acres)
          / NULLIF(field_totals.boundary_acres, 0) * 100,
          1
        ),
      'threshold_pct',    p_acre_divergence_threshold,
      'field_count',      field_totals.field_count
    )
  FROM jobs j
  JOIN LATERAL (
    SELECT
      SUM(COALESCE(f.override_acres, f.measured_acres, f.total_acres)) AS boundary_acres,
      COUNT(*)                                                          AS field_count,
      COUNT(*) FILTER (
        WHERE COALESCE(f.override_acres, f.measured_acres, f.total_acres) > 0
      )                                                                 AS fields_with_acres
    FROM job_fields jf
    JOIN fields f ON f.id = jf.field_id
    WHERE jf.job_id = j.id
  ) field_totals ON field_totals.boundary_acres IS NOT NULL
                 AND field_totals.boundary_acres > 0
                 AND field_totals.field_count = field_totals.fields_with_acres
  WHERE j.deleted_at IS NULL
    AND j.status IN ('completed','invoiced')
    AND j.applied_acres IS NOT NULL
    AND j.applied_acres > 0
    AND ABS(j.applied_acres - field_totals.boundary_acres)
        / field_totals.boundary_acres * 100
        >= p_acre_divergence_threshold
    AND (p_job_id IS NULL OR j.id = p_job_id)
  ON CONFLICT (natural_key) WHERE natural_key IS NOT NULL DO UPDATE
    SET message    = EXCLUDED.message,
        detail     = EXCLUDED.detail,
        created_at = now()
    WHERE watchdog_flags.natural_key IS NOT NULL;

  -- ── FLAG 2: Rate Over Label Max (unchanged) ───────────────────────────────
  INSERT INTO watchdog_flags (
    natural_key, flag_type, severity, entity_type, entity_id,
    job_id, product_id, customer_id, message, detail
  )
  SELECT
    'rate_over_label:jc:' || jc.id::text,
    'rate_over_label'::text,
    'warning'::text,
    'job_chemical'::text,
    jc.id,
    jc.job_id,
    jc.product_id,
    j.customer_id,
    CASE
      WHEN p.max_label_rate IS NOT NULL
           AND NULLIF(btrim(COALESCE(p.max_label_rate_unit,'')), '') IS NOT NULL
           AND jc.rate_per_acre > p.max_label_rate
           AND normalize_rate_unit(jc.rate_unit)
               = normalize_rate_unit(p.max_label_rate_unit)
      THEN format(
        'Job %s: %s applied at %s %s/acre exceeds label max of %s %s/acre',
        j.job_number, p.product_name,
        jc.rate_per_acre, jc.rate_unit,
        p.max_label_rate, p.max_label_rate_unit
      )
      ELSE format(
        'Job %s: %s applied at %s %s/acre exceeds %s× suggested rate (%s %s/acre)',
        j.job_number, p.product_name,
        jc.rate_per_acre, COALESCE(jc.rate_unit,''),
        p_rate_fallback_multiple,
        p.rate_per_acre, COALESCE(p.rate_unit,'')
      )
    END,
    jsonb_build_object(
      'rate_per_acre',          jc.rate_per_acre,
      'rate_unit',              NULLIF(btrim(COALESCE(jc.rate_unit,'')), ''),
      'max_label_rate',         p.max_label_rate,
      'max_label_rate_unit',    NULLIF(btrim(COALESCE(p.max_label_rate_unit,'')), ''),
      'suggested_rate',         p.rate_per_acre,
      'suggested_rate_unit',    NULLIF(btrim(COALESCE(p.rate_unit,'')), ''),
      'fallback_multiple',      p_rate_fallback_multiple,
      'product_name',           p.product_name,
      'flag_reason',
        CASE
          WHEN p.max_label_rate IS NOT NULL
               AND NULLIF(btrim(COALESCE(p.max_label_rate_unit,'')), '') IS NOT NULL
               AND normalize_rate_unit(jc.rate_unit)
                   = normalize_rate_unit(p.max_label_rate_unit)
          THEN 'label_max'
          ELSE 'fallback_multiple'
        END
    )
  FROM jobs j
  JOIN job_chemicals jc ON jc.job_id = j.id
  JOIN products p ON p.id = jc.product_id
  WHERE j.deleted_at IS NULL
    AND j.status IN ('completed','invoiced')
    AND jc.rate_per_acre IS NOT NULL
    AND jc.rate_per_acre > 0
    AND (p_job_id IS NULL OR j.id = p_job_id)
    AND (
      (
        p.max_label_rate IS NOT NULL
        AND NULLIF(btrim(COALESCE(p.max_label_rate_unit,'')), '') IS NOT NULL
        AND jc.rate_per_acre > p.max_label_rate
        AND normalize_rate_unit(jc.rate_unit)
            = normalize_rate_unit(p.max_label_rate_unit)
      )
      OR
      (
        (
          p.max_label_rate IS NULL
          OR NULLIF(btrim(COALESCE(p.max_label_rate_unit,'')), '') IS NULL
          OR normalize_rate_unit(jc.rate_unit)
             <> normalize_rate_unit(p.max_label_rate_unit)
        )
        AND p.rate_per_acre IS NOT NULL
        AND p.rate_per_acre > 0
        AND jc.rate_per_acre > (p_rate_fallback_multiple * p.rate_per_acre)
        AND NULLIF(btrim(COALESCE(jc.rate_unit,'')), '') IS NOT NULL
        AND NULLIF(btrim(COALESCE(p.rate_unit,'')), '') IS NOT NULL
        AND normalize_rate_unit(jc.rate_unit)
            = normalize_rate_unit(p.rate_unit)
      )
    )
  ON CONFLICT (natural_key) WHERE natural_key IS NOT NULL DO UPDATE
    SET message    = EXCLUDED.message,
        detail     = EXCLUDED.detail,
        created_at = now()
    WHERE watchdog_flags.natural_key IS NOT NULL;

  -- ── FLAG 3: Double-Bill (job-level, unchanged) ────────────────────────────
  INSERT INTO watchdog_flags (
    natural_key, flag_type, severity, entity_type, entity_id,
    job_id, invoice_id, customer_id, message, detail
  )
  SELECT DISTINCT ON (i.id)
    'double_bill:job_invoice:' || i.id::text,
    'double_bill'::text,
    'warning'::text,
    'invoice'::text,
    i.id,
    i.job_id,
    i.id,
    i.customer_id,
    format(
      'Invoice %s may duplicate job %s — %s active invoices exist for this job',
      i.invoice_number,
      j.job_number,
      dup.cnt
    ),
    jsonb_build_object(
      'invoice_id',      i.id,
      'invoice_number',  i.invoice_number,
      'job_id',          i.job_id,
      'job_number',      j.job_number,
      'active_count',    dup.cnt
    )
  FROM invoices i
  JOIN jobs j ON j.id = i.job_id
  JOIN (
    SELECT job_id, COUNT(*) AS cnt
    FROM invoices
    WHERE job_id IS NOT NULL
      AND status NOT IN ('voided','cancelled')
      AND deleted_at IS NULL
    GROUP BY job_id
    HAVING COUNT(*) > 1
  ) dup ON dup.job_id = i.job_id
  WHERE i.status NOT IN ('voided','cancelled')
    AND i.deleted_at IS NULL
    AND j.deleted_at IS NULL
    AND (p_job_id IS NULL OR i.job_id = p_job_id)
  ON CONFLICT (natural_key) WHERE natural_key IS NOT NULL DO UPDATE
    SET message    = EXCLUDED.message,
        detail     = EXCLUDED.detail,
        created_at = now()
    WHERE watchdog_flags.natural_key IS NOT NULL;

  -- ── FLAG 3b: Double-Bill (blend-ticket level, unchanged) ──────────────────
  INSERT INTO watchdog_flags (
    natural_key, flag_type, severity, entity_type, entity_id,
    invoice_id, customer_id, message, detail
  )
  SELECT DISTINCT ON (i.id)
    'double_bill:bt_invoice:' || i.id::text,
    'double_bill'::text,
    'warning'::text,
    'invoice'::text,
    i.id,
    i.id,
    i.customer_id,
    format(
      'Invoice %s may duplicate blend ticket — %s distinct invoice groups exist for this blend ticket',
      i.invoice_number,
      dup.group_count
    ),
    jsonb_build_object(
      'invoice_id',        i.id,
      'invoice_number',    i.invoice_number,
      'blend_ticket_id',   i.blend_ticket_id,
      'group_count',       dup.group_count
    )
  FROM invoices i
  JOIN (
    SELECT
      blend_ticket_id,
      COUNT(DISTINCT COALESCE(invoice_group_id::text, id::text)) AS group_count
    FROM invoices
    WHERE blend_ticket_id IS NOT NULL
      AND status NOT IN ('voided','cancelled')
      AND deleted_at IS NULL
    GROUP BY blend_ticket_id
    HAVING COUNT(DISTINCT COALESCE(invoice_group_id::text, id::text)) > 1
  ) dup ON dup.blend_ticket_id = i.blend_ticket_id
  WHERE i.status NOT IN ('voided','cancelled')
    AND i.deleted_at IS NULL
    AND i.job_id IS NULL
    AND p_job_id IS NULL
  ON CONFLICT (natural_key) WHERE natural_key IS NOT NULL DO UPDATE
    SET message    = EXCLUDED.message,
        detail     = EXCLUDED.detail,
        created_at = now()
    WHERE watchdog_flags.natural_key IS NOT NULL;

  -- ── FLAG 4: REI Not Cleared — based on ACTUAL applied records (GAP 3) ──────
  -- The window is now measured between ACTUAL application timestamps, resolved per
  -- (job, field) with this precedence, degrading gracefully:
  --   1. field-specific applied record:
  --        job_applied_records.application_date (+ start_weather_time)
  --        for a record linked to THIS field via job_applied_record_fields
  --   2. job-level applied record: the latest applied record for that job (any field)
  --   3. fallback: job_date + scheduled_time (when no applied record exists)
  -- "Actual entry" of the CURRENT job is resolved the same way; the prior product's
  -- rei_hours decides whether the window had cleared.
  INSERT INTO watchdog_flags (
    natural_key, flag_type, severity, entity_type, entity_id,
    job_id, product_id, field_id, customer_id, message, detail
  )
  SELECT DISTINCT ON (j.id, jf.field_id)
    'rei_not_cleared:job:' || j.id::text || ':field:' || jf.field_id::text,
    'rei_not_cleared'::text,
    'warning'::text,
    'job'::text,
    j.id,
    j.id,
    prior_j.prior_product_id,
    jf.field_id,
    j.customer_id,
    format(
      'Job %s entered field "%s" but the REI from job %s (%s, %s hours) may not have cleared',
      j.job_number,
      f.field_name,
      prior_j.job_number,
      prior_j.prior_product_name,
      prior_j.prior_rei_hours
    ),
    jsonb_build_object(
      'field_name',        f.field_name,
      'prior_product',     prior_j.prior_product_name,
      'prior_rei_hours',   prior_j.prior_rei_hours,
      'prior_job_number',  prior_j.job_number,
      'prior_applied_ts',  prior_j.prior_ts,
      'prior_ts_source',   prior_j.prior_ts_source,
      'this_applied_ts',   cur.this_ts,
      'this_ts_source',    cur.this_ts_source,
      'hours_since_prior',
        ROUND((EXTRACT(EPOCH FROM (cur.this_ts - prior_j.prior_ts)) / 3600)::numeric, 1)
    )
  FROM jobs j
  JOIN job_fields jf ON jf.job_id = j.id
  JOIN fields f ON f.id = jf.field_id
  -- Actual entry time of the CURRENT job onto THIS field (precedence 1→2→3).
  -- Use the EARLIEST (MIN) pass: re-entry risk is the FIRST time someone re-entered
  -- the field, so a later pass that happened after the REI cleared must NOT mask an
  -- earlier pass that occurred while the prior product's REI was still open.
  JOIN LATERAL (
    SELECT
      COALESCE(jarf_ts.ts, jrec_ts.ts,
               (j.job_date + COALESCE(j.scheduled_time, '00:00:00'::time))::timestamptz) AS this_ts,
      CASE WHEN jarf_ts.ts IS NOT NULL THEN 'applied_record_field'
           WHEN jrec_ts.ts IS NOT NULL THEN 'applied_record_job'
           ELSE 'scheduled' END AS this_ts_source
    FROM (
      -- field-specific record for the current job + this field (earliest real pass);
      -- only count a row that actually treated this field (applied_acres > 0).
      -- Time-of-day precedence: the record's start_weather_time, else the job's
      -- scheduled_time, else midnight — so a date-only record keeps a real time and
      -- doesn't collapse to 00:00 (which would hide same-day re-entry).
      SELECT MIN((r.application_date + COALESCE(r.start_weather_time, j.scheduled_time, '00:00:00'::time))::timestamptz) AS ts
      FROM job_applied_records r
      JOIN job_applied_record_fields rf ON rf.application_record_id = r.id AND rf.field_id = jf.field_id
      WHERE r.job_id = j.id AND rf.applied_acres > 0
    ) jarf_ts
    CROSS JOIN (
      -- job-level record for the current job (any field, earliest real pass).
      -- ONLY a legacy fallback: when the job records per-field child rows, an absent
      -- child for THIS field means the field wasn't covered — so don't borrow another
      -- field's time. Gate the fallback to jobs that have NO per-field child data at all.
      SELECT MIN((r.application_date + COALESCE(r.start_weather_time, j.scheduled_time, '00:00:00'::time))::timestamptz) AS ts
      FROM job_applied_records r
      WHERE r.job_id = j.id AND COALESCE(r.applied_acres, 0) > 0
        AND NOT EXISTS (
          SELECT 1 FROM job_applied_records r2
          JOIN job_applied_record_fields rf2 ON rf2.application_record_id = r2.id
          WHERE r2.job_id = j.id
        )
    ) jrec_ts
  ) cur ON true
  -- Most-recent PRIOR application on this same field (ANY product) whose REI hasn't
  -- cleared, judged by the PRIOR product's rei_hours and the PRIOR actual applied time.
  JOIN LATERAL (
    SELECT pj.id, pj.job_number, pj.job_date,
           prior_ts.ts          AS prior_ts,
           prior_ts.ts_source   AS prior_ts_source,
           pp.id AS prior_product_id, pp.product_name AS prior_product_name, pp.rei_hours AS prior_rei_hours
    FROM jobs pj
    JOIN job_fields pjf ON pjf.job_id = pj.id AND pjf.field_id = jf.field_id
    JOIN job_chemicals pjc ON pjc.job_id = pj.id
    JOIN products pp ON pp.id = pjc.product_id
    -- prior job's ACTUAL applied time onto this field (precedence 1→2→3)
    JOIN LATERAL (
      SELECT
        COALESCE(
          pjarf_ts.ts,
          pjrec_ts.ts,
          -- Scheduled fallback ONLY when the prior job has NO applied records at all.
          -- If it HAS records but none usable here (e.g. all AFTER the current entry —
          -- the prior job was actually sprayed later — or all 0-acre), we must NOT fall
          -- back to its scheduled time, or a job sprayed after this entry would be
          -- mistaken for a prior application. NULL ts → the outer predicate drops it.
          CASE WHEN NOT EXISTS (
                 SELECT 1 FROM job_applied_records r WHERE r.job_id = pj.id
               )
               THEN (pj.job_date + COALESCE(pj.scheduled_time, '00:00:00'::time))::timestamptz
          END
        ) AS ts,
        CASE WHEN pjarf_ts.ts IS NOT NULL THEN 'applied_record_field'
             WHEN pjrec_ts.ts IS NOT NULL THEN 'applied_record_job'
             ELSE 'scheduled' END AS ts_source
      FROM (
        -- field-specific PRIOR record; only count a row that actually treated this
        -- field (applied_acres > 0) — a 0-acre location row is not a real application.
        -- Bound to passes BEFORE the current entry: a prior job with a later pass that
        -- post-dates this entry must not have that after-current pass picked by MAX
        -- (which the outer prior_ts < cur.this_ts predicate would then reject wholesale,
        -- masking an earlier pass that IS within the REI window).
        -- Time-of-day precedence: record start time, else the prior job's scheduled
        -- time, else midnight (same rationale as the current-job block above).
        SELECT MAX((r.application_date + COALESCE(r.start_weather_time, pj.scheduled_time, '00:00:00'::time))::timestamptz) AS ts
        FROM job_applied_records r
        JOIN job_applied_record_fields rf ON rf.application_record_id = r.id AND rf.field_id = jf.field_id
        WHERE r.job_id = pj.id AND rf.applied_acres > 0
          AND (r.application_date + COALESCE(r.start_weather_time, pj.scheduled_time, '00:00:00'::time))::timestamptz < cur.this_ts
      ) pjarf_ts
      CROSS JOIN (
        -- job-level PRIOR record; only count a record with positive applied acres,
        -- and only the latest one BEFORE the current entry (same reason as above).
        -- Legacy fallback only: gate to prior jobs with NO per-field child data at all,
        -- so a prior job that DID record per-field rows but not for this field (i.e. it
        -- didn't treat this field) doesn't manufacture a window from another field's time.
        SELECT MAX((r.application_date + COALESCE(r.start_weather_time, pj.scheduled_time, '00:00:00'::time))::timestamptz) AS ts
        FROM job_applied_records r
        WHERE r.job_id = pj.id AND COALESCE(r.applied_acres, 0) > 0
          AND (r.application_date + COALESCE(r.start_weather_time, pj.scheduled_time, '00:00:00'::time))::timestamptz < cur.this_ts
          AND NOT EXISTS (
            SELECT 1 FROM job_applied_records r2
            JOIN job_applied_record_fields rf2 ON rf2.application_record_id = r2.id
            WHERE r2.job_id = pj.id
          )
      ) pjrec_ts
    ) prior_ts ON true
    WHERE pj.id <> j.id
      AND pj.deleted_at IS NULL
      AND pj.status IN ('completed','invoiced')
      AND pp.rei_hours IS NOT NULL
      AND pp.rei_hours > 0
      -- Exclude a prior job that AFFIRMATIVELY recorded NO real application on this
      -- field. Once a job records per-field child rows (job_applied_record_fields),
      -- those rows ARE the authoritative coverage list — a field absent from them, or
      -- present only at 0 acres, was NOT treated. In that case the scheduled fallback
      -- must NOT manufacture an REI window for this field. (A prior job with NO child
      -- rows at all is a legacy record → scheduled fallback still applies; absence of
      -- ALL child data ≠ a recorded "not this field".)
      AND NOT (
        EXISTS (
          SELECT 1 FROM job_applied_records r
          JOIN job_applied_record_fields rf ON rf.application_record_id = r.id
          WHERE r.job_id = pj.id
        )
        AND NOT EXISTS (
          SELECT 1 FROM job_applied_records r
          JOIN job_applied_record_fields rf
            ON rf.application_record_id = r.id AND rf.field_id = jf.field_id
          WHERE r.job_id = pj.id AND rf.applied_acres > 0
        )
      )
      -- prior application must be strictly before the current entry, by ACTUAL time
      AND prior_ts.ts < cur.this_ts
      -- and the REI window must not yet have cleared at the current entry time
      AND EXTRACT(EPOCH FROM (cur.this_ts - prior_ts.ts)) / 3600 < pp.rei_hours
    ORDER BY prior_ts.ts DESC, pp.rei_hours DESC
    LIMIT 1
  ) prior_j ON true
  WHERE j.deleted_at IS NULL
    AND j.status IN ('completed','invoiced')
    AND (p_job_id IS NULL OR j.id = p_job_id)
    -- Symmetric to the prior-job guard: once the CURRENT job records per-field child
    -- rows, those rows are the authoritative coverage list. If THIS field is absent
    -- from them (or present only at 0 acres), the job never entered this field — so
    -- don't flag REI for it. (cur.this_ts may have borrowed another field's pass via
    -- the job-level path; this stops that borrowed time manufacturing a warning. A job
    -- with NO child rows at all stays on the legacy scheduled path.)
    AND NOT (
      EXISTS (
        SELECT 1 FROM job_applied_records r
        JOIN job_applied_record_fields rf ON rf.application_record_id = r.id
        WHERE r.job_id = j.id
      )
      AND NOT EXISTS (
        SELECT 1 FROM job_applied_records r
        JOIN job_applied_record_fields rf
          ON rf.application_record_id = r.id AND rf.field_id = jf.field_id
        WHERE r.job_id = j.id AND rf.applied_acres > 0
      )
    )
  ON CONFLICT (natural_key) WHERE natural_key IS NOT NULL DO UPDATE
    SET message    = EXCLUDED.message,
        detail     = EXCLUDED.detail,
        created_at = now()
    WHERE watchdog_flags.natural_key IS NOT NULL;

  -- ── Return summary (count only active non-dismissed flags in scope) ────────
  SELECT COUNT(*) INTO v_inserted
  FROM watchdog_flags wf
  WHERE NOT EXISTS (
    SELECT 1 FROM watchdog_flag_dismissals d WHERE d.flag_id = wf.id
  )
  AND (p_job_id IS NULL OR wf.job_id = p_job_id);

  RETURN jsonb_build_object(
    'flags_total',   v_inserted,
    'flags_deleted', v_deleted,
    'scope',         CASE WHEN p_job_id IS NOT NULL THEN 'job:' || p_job_id::text ELSE 'all' END
  );
END;
$$;


ALTER FUNCTION "public"."refresh_watchdog_flags"("p_job_id" "uuid", "p_acre_divergence_threshold" numeric, "p_rate_fallback_multiple" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refresh_watchdog_flags"("p_job_id" "uuid", "p_acre_divergence_threshold" numeric, "p_rate_fallback_multiple" numeric) IS 'Recomputes all 4 watchdog flag types. Flag 4 (REI) measures the re-entry window between ACTUAL applied-record timestamps (job_applied_records ± field link), falling back to job_date+scheduled_time only when no applied record exists. Uses natural_key upsert — dismissed flags survive re-sweeps if the underlying condition persists.';



CREATE OR REPLACE FUNCTION "public"."reject_return"("p_return_id" "uuid", "p_rejected_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor  uuid := auth.uid();
  v_return record;
  v_cached jsonb;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_rejected_by IS NOT NULL AND p_rejected_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached := check_idempotency(p_idempotency_key, 'reject_return');
    IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
  END IF;

  SELECT id, return_number, status, customer_id INTO v_return FROM returns WHERE id = p_return_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Return not found: %', p_return_id; END IF;
  IF v_return.status <> 'requested' THEN
    RAISE EXCEPTION 'Only requested returns can be rejected (current status: %)', v_return.status;
  END IF;

  PERFORM set_config('app.return_rpc', 'true', true);
  UPDATE returns SET status = 'rejected', updated_at = now() WHERE id = p_return_id;

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('return_rejected', 'Return ' || v_return.return_number || ' rejected', v_actor, 'return', p_return_id, v_return.customer_id);

  v_result := jsonb_build_object('success', true, 'return_id', p_return_id, 'return_number', v_return.return_number, 'status', 'rejected');
  IF p_idempotency_key IS NOT NULL THEN PERFORM save_idempotency(p_idempotency_key, 'reject_return', v_result); END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."reject_return"("p_return_id" "uuid", "p_rejected_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_expired_quote_holds"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_released integer;
BEGIN
  UPDATE inventory_holds ih SET
    is_active = false, updated_at = now()
  FROM quotes q
  WHERE ih.source_id = q.id
    AND ih.is_active = true
    AND q.status IN ('declined', 'expired');

  GET DIAGNOSTICS v_released = ROW_COUNT;

  RETURN jsonb_build_object('holds_released', v_released);
END;
$$;


ALTER FUNCTION "public"."release_expired_quote_holds"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_holds_on_quote_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_released_count integer := 0;
BEGIN
  IF NEW.status IN ('accepted', 'declined', 'expired', 'cancelled', 'closed_by_application', 'closed_short')
     AND OLD.status NOT IN ('accepted', 'declined', 'expired', 'cancelled', 'closed_by_application', 'closed_short') THEN
    UPDATE public.inventory_holds
    SET is_active = false, updated_at = now()
    WHERE source_id = NEW.id AND is_active = true;
    GET DIAGNOSTICS v_released_count = ROW_COUNT;

    IF v_released_count > 0 THEN
      INSERT INTO public.activity_feed (event_type, description, performed_by,
        related_entity_type, related_entity_id, customer_id)
      VALUES ('inventory_holds_released',
        'Released ' || v_released_count || ' inventory hold(s) for quote ' || NEW.quote_number || ' (' || NEW.status || ')',
        COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'),
        'quote', NEW.id, NEW.customer_id);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."release_holds_on_quote_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_inventory_hold"("p_hold_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_hold record;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'admin') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'release_inventory_hold');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_hold FROM inventory_holds WHERE id = p_hold_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory hold not found';
  END IF;

  -- LAYER2<<< a job reservation is lifecycle-managed, never manually released here —
  -- releasing it via this generic path would orphan its job_product_draws row and
  -- leave the parent quote's crop_program hold un-resynced (§4A.6 / Codex round-4 P1).
  IF v_hold.hold_type = 'job' THEN
    RAISE EXCEPTION 'JOB_HOLD_NOT_MANUALLY_RELEASABLE: this is a job reservation — it releases automatically when the job is cancelled, completed, or deleted, not by manual release';
  END IF;
  -- >>>LAYER2

  IF NOT v_hold.is_active THEN
    RETURN jsonb_build_object('status', 'already_released');
  END IF;

  UPDATE inventory_holds SET is_active = false WHERE id = p_hold_id;

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id
  ) VALUES (
    'inventory_hold_released',
    'Inventory hold released for product ' || v_hold.product_id::text,
    v_actor, 'inventory_hold', p_hold_id
  );

  v_result := jsonb_build_object('status', 'released', 'hold_id', p_hold_id);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'release_inventory_hold', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."release_inventory_hold"("p_hold_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reopen_accounting_period"("p_period_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_period   record;
  v_existing jsonb;
  v_result   jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'admin') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required to reopen an accounting period';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key
       AND operation = 'reopen_accounting_period';
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  SELECT * INTO v_period
    FROM accounting_periods
   WHERE id = p_period_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Accounting period not found: %', p_period_id;
  END IF;

  IF v_period.status != 'closed' THEN
    RAISE EXCEPTION 'Accounting period is not closed (status: %)', v_period.status;
  END IF;

  UPDATE accounting_periods SET
    status     = 'open',
    closed_at  = NULL,
    closed_by  = NULL,
    updated_at = now()
  WHERE id = p_period_id;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    old_values, new_values, description
  ) VALUES (
    'period_reopened', 'accounting_period', p_period_id,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object('status', 'closed', 'closed_at', v_period.closed_at),
    jsonb_build_object('status', 'open'),
    'Accounting period reopened: ' || p_reason
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id
  ) VALUES (
    'period_reopened',
    'Accounting period ' || v_period.period_start || ' to ' || v_period.period_end ||
      ' reopened: ' || p_reason,
    v_actor, 'accounting_period', p_period_id
  );

  v_result := jsonb_build_object(
    'success',      true,
    'period_id',    p_period_id,
    'period_start', v_period.period_start,
    'period_end',   v_period.period_end
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result, expires_at)
    VALUES (p_idempotency_key, 'reopen_accounting_period', v_result, now() + interval '24 hours')
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."reopen_accounting_period"("p_period_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reopen_accounting_period"("p_period_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Admin-only reopen of a closed accounting period with mandatory reason; logs to financial_audit_log + activity_feed. Wave A.6 explicit rewrite of the dynamic-clone version.';



CREATE OR REPLACE FUNCTION "public"."require_admin"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
BEGIN
  SELECT role INTO v_role FROM profiles WHERE id = auth.uid() AND is_active = true;
  IF v_role IS NULL OR v_role <> 'admin' THEN
    RAISE EXCEPTION 'Permission denied: requires admin role';
  END IF;
END;
$$;


