CREATE OR REPLACE FUNCTION "public"."require_governed_product_pricing"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_pricing_changed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_pricing_changed := NEW.current_cost IS NOT NULL
      OR NEW.tier1_margin IS NOT NULL
      OR NEW.tier2_margin IS NOT NULL
      OR NEW.tier3_margin IS NOT NULL
      OR NEW.tier1_price IS NOT NULL
      OR NEW.tier2_price IS NOT NULL
      OR NEW.tier3_price IS NOT NULL;

    -- Product creation stays a pricing-free shell. Pricing is a separate,
    -- previewed update through the governed RPC after the row exists.
    IF v_pricing_changed THEN
      RAISE EXCEPTION 'PRODUCT_PRICING_GOVERNED_PATH_REQUIRED';
    END IF;
    RETURN NEW;
  END IF;

  v_pricing_changed :=
    OLD.current_cost IS DISTINCT FROM NEW.current_cost
    OR OLD.tier1_margin IS DISTINCT FROM NEW.tier1_margin
    OR OLD.tier2_margin IS DISTINCT FROM NEW.tier2_margin
    OR OLD.tier3_margin IS DISTINCT FROM NEW.tier3_margin
    OR OLD.tier1_price IS DISTINCT FROM NEW.tier1_price
    OR OLD.tier2_price IS DISTINCT FROM NEW.tier2_price
    OR OLD.tier3_price IS DISTINCT FROM NEW.tier3_price;

  -- Gross-margin and per-acre fields are trigger-derived. Authenticated
  -- callers have no column grant for them, but ordinary rate/unit edits must
  -- be allowed to recalculate per-acre values through the live trigger.

  IF v_pricing_changed
     AND current_setting('crx.pricing_authorized', true) IS DISTINCT FROM 'phase1a' THEN
    RAISE EXCEPTION 'PRODUCT_PRICING_GOVERNED_PATH_REQUIRED';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."require_governed_product_pricing"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_split_invoice_creation_claim"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.order_id IS NOT NULL
     AND NEW.invoice_group_id IS NOT NULL
     AND (
       EXISTS (
         SELECT 1
           FROM public.orders o
          WHERE o.id = NEW.order_id
            AND COALESCE(o.needs_split_billing, false)
       )
       OR EXISTS (
         SELECT 1
           FROM public.order_item_field_allocations oifa
           JOIN public.order_items oi ON oi.id = oifa.order_item_id
          WHERE oi.order_id = NEW.order_id
       )
     )
     AND NOT EXISTS (
       SELECT 1
         FROM public.split_invoice_creation_claims claim
        WHERE claim.transaction_id = pg_current_xact_id()
          AND claim.order_id = NEW.order_id
     ) THEN
    RAISE EXCEPTION
      'SPLIT_INVOICE_CREATION_CLAIM_REQUIRED: split-protected grouped invoices must be created by create_split_invoices_from_order'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."require_split_invoice_creation_claim"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_job_inventory"("p_job_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_role text;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  SELECT role INTO v_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  v_result := _sync_job_holds(p_job_id, v_actor);
  RETURN jsonb_build_object('success', true) || v_result;
END;
$$;


