CREATE OR REPLACE FUNCTION "public"."resolve_offline_action"("p_client_action_id" "uuid", "p_resolution" "text", "p_note" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_receipt public.offline_action_receipts%ROWTYPE;
  v_existing jsonb;
  v_result jsonb;
  v_note text := btrim(COALESCE(p_note, ''));
  v_entity_type text;
  v_resolution_label text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = v_actor
      AND p.is_active = true
      AND p.role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: active office role required';
  END IF;
  IF p_client_action_id IS NULL THEN
    RAISE EXCEPTION 'PAYLOAD_INVALID: client action ID is required';
  END IF;
  IF p_resolution IS NULL OR p_resolution NOT IN ('already_completed', 'abandoned') THEN
    RAISE EXCEPTION 'OFFLINE_RESOLUTION_INVALID';
  END IF;
  IF length(v_note) NOT BETWEEN 10 AND 1000 THEN
    RAISE EXCEPTION 'REASON_REQUIRED: resolution note must be 10 to 1000 characters';
  END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) > 200 THEN
    RAISE EXCEPTION 'PAYLOAD_INVALID: a bounded idempotency key is required';
  END IF;

  -- The shared idempotency helper saves at the end of the transaction. Serialize
  -- this operation+key before the cache check so two different receipts cannot
  -- both mutate under the same previously unseen key.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('resolve_offline_action:' || p_idempotency_key, 0)
  );

  v_existing := public.check_idempotency(p_idempotency_key, 'resolve_offline_action');
  IF v_existing IS NOT NULL THEN
    IF v_existing->>'client_action_id' IS DISTINCT FROM p_client_action_id::text
       OR v_existing->>'review_resolution' IS DISTINCT FROM p_resolution
       OR v_existing->>'review_note' IS DISTINCT FROM v_note THEN
      RAISE EXCEPTION 'IDEMPOTENCY_ARGUMENT_MISMATCH';
    END IF;
    RETURN v_existing;
  END IF;

  SELECT *
    INTO v_receipt
    FROM public.offline_action_receipts r
   WHERE r.client_action_id = p_client_action_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TARGET_NOT_FOUND: offline receipt not found';
  END IF;
  IF v_receipt.status <> 'needs_review' THEN
    RAISE EXCEPTION 'OFFLINE_ACTION_NOT_REVIEWABLE';
  END IF;
  IF v_receipt.resolved_at IS NOT NULL THEN
    IF v_receipt.resolved_by IS DISTINCT FROM v_actor
       OR v_receipt.review_resolution IS DISTINCT FROM p_resolution
       OR v_receipt.review_note IS DISTINCT FROM v_note THEN
      RAISE EXCEPTION 'OFFLINE_ACTION_ALREADY_RESOLVED';
    END IF;
  ELSE
    UPDATE public.offline_action_receipts
       SET review_resolution = p_resolution,
           review_note = v_note,
           resolved_at = now(),
           resolved_by = v_actor
     WHERE client_action_id = p_client_action_id
     RETURNING * INTO v_receipt;

    v_entity_type := CASE v_receipt.operation
      WHEN 'complete_delivery' THEN 'delivery'
      WHEN 'complete_job' THEN 'job'
      ELSE 'offline_action_receipt'
    END;
    v_resolution_label := CASE p_resolution
      WHEN 'already_completed' THEN 'already handled outside the offline queue'
      ELSE 'intentionally abandoned and must not run'
    END;

    INSERT INTO public.activity_feed (
      event_type,
      description,
      performed_by,
      related_entity_type,
      related_entity_id
    ) VALUES (
      'offline_action_resolved',
      format(
        'Offline %s receipt %s was resolved as %s.',
        v_receipt.operation,
        left(v_receipt.client_action_id::text, 8),
        v_resolution_label
      ),
      v_actor,
      v_entity_type,
      v_receipt.entity_id
    );
  END IF;

  v_result := jsonb_build_object(
    'client_action_id', v_receipt.client_action_id,
    'operation', v_receipt.operation,
    'entity_id', v_receipt.entity_id,
    'status', v_receipt.status,
    'review_resolution', v_receipt.review_resolution,
    'review_note', v_receipt.review_note,
    'resolved_at', v_receipt.resolved_at,
    'resolved_by', v_receipt.resolved_by,
    'updated_at', v_receipt.updated_at
  );

  PERFORM public.save_idempotency(
    p_idempotency_key,
    'resolve_offline_action',
    v_result
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."resolve_offline_action"("p_client_action_id" "uuid", "p_resolution" "text", "p_note" "text", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_offline_action"("p_client_action_id" "uuid", "p_resolution" "text", "p_note" "text", "p_idempotency_key" "text") IS 'Records an audited non-destructive office resolution without rerunning or deleting the offline business action.';



CREATE OR REPLACE FUNCTION "public"."restore_cancelled_delivery"("p_delivery_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_delivery record;
  v_existing jsonb;
  v_result   jsonb;
BEGIN
  -- Strict-actor admin guard (was COALESCE(p_performed_by, auth.uid()) gating on the
  -- caller-supplied actor's role — forgeable). Authorize the REAL caller only.
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required to restore a cancelled delivery';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key
       AND operation = 'restore_cancelled_delivery';
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  SELECT * INTO v_delivery
    FROM deliveries
   WHERE id = p_delivery_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Delivery not found: %', p_delivery_id;
  END IF;

  IF v_delivery.status != 'cancelled' THEN
    RAISE EXCEPTION 'Only cancelled deliveries can be restored (current status: %)', v_delivery.status;
  END IF;

  -- Bracket the enforcer-forbidden cancelled->scheduled write with the admin override.
  PERFORM set_config('app.admin_override', 'true', true);
  UPDATE deliveries SET
    status     = 'scheduled',
    updated_at = now()
  WHERE id = p_delivery_id;
  PERFORM set_config('app.admin_override', 'false', true);

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    old_values, new_values, description
  ) VALUES (
    'delivery_restored', 'delivery', p_delivery_id,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object('status', 'cancelled'),
    jsonb_build_object('status', 'scheduled'),
    'Delivery ' || v_delivery.delivery_number || ' restored from cancelled to scheduled: ' || p_reason
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'delivery_restored',
    'Delivery ' || v_delivery.delivery_number || ' restored from cancelled to scheduled: ' || p_reason,
    v_actor, 'delivery', p_delivery_id, v_delivery.customer_id
  );

  v_result := jsonb_build_object(
    'success',           true,
    'delivery_id',       p_delivery_id,
    'delivery_number',   v_delivery.delivery_number
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result, expires_at)
    VALUES (p_idempotency_key, 'restore_cancelled_delivery', v_result, now() + interval '24 hours')
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."restore_cancelled_delivery"("p_delivery_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_cancelled_delivery"("p_delivery_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Admin-only restore of a cancelled delivery to "scheduled". Wave A.6 explicit rewrite.';



CREATE OR REPLACE FUNCTION "public"."restore_cancelled_order"("p_order_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
BEGIN
  -- Authorize the REAL caller (strict actor), then refuse — restore is disabled.
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- H4 fix: restoring a cancelled order cannot safely reverse the cancel's
  -- side-effects (released inventory prebook/holds, zeroed commissions, reversed
  -- booking draws), so it is no longer permitted. Create a new order or
  -- re-convert / revert the source quote instead.
  RAISE EXCEPTION 'ORDER_RESTORE_NOT_SUPPORTED: a cancelled order cannot be safely restored — its released inventory reservations, commissions, and booking draws are not re-applied, which would leave a corrupt confirmed order. Create a new order, or re-convert/revert the source quote instead.';
END;
$$;


ALTER FUNCTION "public"."restore_cancelled_order"("p_order_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_cancelled_order"("p_order_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Admin-only restore of a cancelled order to "confirmed". Does not auto-restore linked deliveries. Wave A.6 explicit rewrite.';



CREATE OR REPLACE FUNCTION "public"."restore_quote_version"("p_quote_id" "uuid", "p_version_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_snapshot jsonb;
  v_section jsonb;
  v_item jsonb;
  v_section_id uuid;
  v_version_number integer;
  v_actor uuid;
  v_drawn_guard record; -- drawn-version guard (20260611120100)
BEGIN
  -- Strict-actor auth (function previously had NO auth check). Before idempotency.
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true
      AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- Idempotency check — operation-scoped so a key minted for a different operation
  -- can't short-circuit a legitimate restore (was: matched idempotency_key alone).
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM 1 FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key
        AND operation = 'restore_quote_version';
    IF FOUND THEN
      RETURN jsonb_build_object('status', 'duplicate', 'message', 'Already processed');
    END IF;
  END IF;

  -- Get snapshot data
  SELECT snapshot_data, version_number INTO v_snapshot, v_version_number
  FROM quote_versions
  WHERE id = p_version_id AND quote_id = p_quote_id;

  IF v_snapshot IS NULL THEN
    RAISE EXCEPTION 'Version not found: %', p_version_id;
  END IF;

  -- Delete existing sections (cascades to items via ON DELETE CASCADE)
  DELETE FROM quote_sections WHERE quote_id = p_quote_id;

  -- Restore quote-level fields. Bracket the status write with the admin override so
  -- the enforcer permits restore->revised from any source state (accepted/declined/etc.).
  PERFORM set_config('app.admin_override', 'true', true);
  UPDATE quotes SET
    header_notes = v_snapshot->'quote'->>'header_notes',
    footer_notes = v_snapshot->'quote'->>'footer_notes',
    total_price = (v_snapshot->'quote'->>'total_price')::numeric,
    total_cost = (v_snapshot->'quote'->>'total_cost')::numeric,
    total_profit = (v_snapshot->'quote'->>'total_profit')::numeric,
    total_margin_pct = (v_snapshot->'quote'->>'total_margin_pct')::numeric,
    status = 'revised',
    updated_at = now()
  WHERE id = p_quote_id;
  PERFORM set_config('app.admin_override', 'false', true);

  -- Restore sections and items from snapshot
  FOR v_section IN SELECT * FROM jsonb_array_elements(v_snapshot->'sections')
  LOOP
    INSERT INTO quote_sections (quote_id, section_name, sort_order, section_notes, section_header_notes, needed_by_date)
    VALUES (
      p_quote_id,
      v_section->>'section_name',
      (v_section->>'sort_order')::integer,
      v_section->>'section_notes',
      v_section->>'section_header_notes',
      (v_section->>'needed_by_date')::date
    )
    RETURNING id INTO v_section_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(v_section->'items')
    LOOP
      INSERT INTO quote_items (
        quote_id, section_id, product_id, sort_order, notes,
        price_per_unit, current_cost, suggested_rate, actual_rate, rate_unit,
        oz_per_acre, price_per_acre, acres, total_units_needed, unit_size,
        profit, total_price, net_margin, calc_mode, price_unit
      )
      VALUES (
        p_quote_id, v_section_id,
        (v_item->>'product_id')::uuid,
        (v_item->>'sort_order')::integer,
        v_item->>'notes',
        (v_item->>'price_per_unit')::numeric,
        (v_item->>'current_cost')::numeric,
        v_item->>'suggested_rate',
        (v_item->>'actual_rate')::numeric,
        v_item->>'rate_unit',
        (v_item->>'oz_per_acre')::numeric,
        (v_item->>'price_per_acre')::numeric,
        (v_item->>'acres')::numeric,
        (v_item->>'total_units_needed')::numeric,
        v_item->>'unit_size',
        (v_item->>'profit')::numeric,
        (v_item->>'total_price')::numeric,
        (v_item->>'net_margin')::numeric,
        v_item->>'calc_mode',
        v_item->>'price_unit'
      );
    END LOOP;
  END LOOP;

  -- BEGIN drawn-version guard (20260611120100)
  -- Codex round-2 MED (2026-06-11): a restore must never under-book the drawn
  -- ledger (quote_product_draws deliberately survives the section delete +
  -- re-insert above). Validates the FINAL persisted quote_items — the same
  -- invariant, token, and block shape as save_quote's drawn-product guard
  -- (20260610184230). A violation rolls back the entire restore atomically,
  -- including the section DELETE.
  -- LAYER2<<< drawn guard counts ORDER + JOB draws (§6.5 / Codex round-2 P1).
  SELECT
    COALESCE(p.product_name, d.product_id::text) AS product_name,
    d.quantity_drawn,
    COALESCE(b.booked, 0) AS new_booked
  INTO v_drawn_guard
  FROM (
    SELECT product_id, SUM(qty) AS quantity_drawn
    FROM (
      SELECT product_id, quantity_drawn AS qty FROM quote_product_draws WHERE quote_id = p_quote_id AND quantity_drawn > 0
      UNION ALL
      SELECT product_id, quantity_drawn AS qty FROM job_product_draws WHERE quote_id = p_quote_id AND quantity_drawn > 0
    ) x
    GROUP BY product_id
  ) d
  LEFT JOIN (
    SELECT product_id, SUM(COALESCE(total_units_needed, 0)) AS booked
    FROM quote_items
    WHERE quote_id = p_quote_id
    GROUP BY product_id
  ) b ON b.product_id = d.product_id
  LEFT JOIN products p ON p.id = d.product_id
  WHERE d.quantity_drawn > 0
    AND COALESCE(b.booked, 0) < d.quantity_drawn
  ORDER BY d.quantity_drawn - COALESCE(b.booked, 0) DESC, d.product_id
  LIMIT 1;
  -- >>>LAYER2
  IF FOUND THEN
    IF v_drawn_guard.new_booked <= 0 THEN
      RAISE EXCEPTION 'BOOKING_OVERDRAWN: cannot restore this version — it removes %, which already has % drawn',
        v_drawn_guard.product_name, v_drawn_guard.quantity_drawn;
    END IF;
    RAISE EXCEPTION 'BOOKING_OVERDRAWN: cannot restore this version — % would fall below its already-drawn % (restored total would be %)',
      v_drawn_guard.product_name, v_drawn_guard.quantity_drawn, v_drawn_guard.new_booked;
  END IF;
  -- END drawn-version guard (20260611120100)

  -- BEGIN planned-hold + job-reservation sync (20260611132115 + Layer2 A3.12)
  -- Codex round-2 #3: restores rewrite quote_items wholesale — rebuild the
  -- planned reservation (booked − drawn) to match the restored state.
  -- LAYER2-CHAN (push-gate #C): a restore that changes booked quantity must ALSO
  -- re-sync the quote's ACTIVE jobs (draws + shed holds), exactly as save_quote now
  -- does — else a restored-larger booking leaves stale job draws and reopens balance
  -- the job still needs. _sync_quote_job_reservations rebuilds the jobs THEN calls
  -- _sync_planned_holds itself (strict superset). Was: PERFORM _sync_planned_holds(...).
  PERFORM _sync_quote_job_reservations(p_quote_id, v_actor);
  -- END planned-hold + job-reservation sync

  -- Save idempotency key (result stored as a valid jsonb object — was a bare ::text UUID).
  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'restore_quote_version', jsonb_build_object('quote_id', p_quote_id))
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'status', 'restored',
    'restored_from_version', v_version_number,
    'quote_id', p_quote_id
  );
END;
$$;


ALTER FUNCTION "public"."restore_quote_version"("p_quote_id" "uuid", "p_version_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retire_inventory_item"("p_inventory_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor             uuid;
  v_inv               record;
  v_existing          jsonb;
  v_active_holds      int;
  v_pending_deliv     int;
  v_old_quantity      numeric;
  v_result            jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Admin access required to retire an inventory item';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'retire_inventory_item');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_inv FROM inventory WHERE id = p_inventory_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory row not found: %', p_inventory_id;
  END IF;

  v_old_quantity := COALESCE(v_inv.quantity_available, 0);

  SELECT COUNT(*) INTO v_active_holds
  FROM inventory_holds
  WHERE product_id = v_inv.product_id AND is_active = true;
  IF v_active_holds > 0 THEN
    RAISE EXCEPTION 'Cannot delete: % active inventory hold(s) on this product. Release holds first.', v_active_holds;
  END IF;

  IF COALESCE(v_inv.quantity_prebooked, 0) > 0 THEN
    RAISE EXCEPTION 'Cannot delete: % unit(s) committed (prebooked) on this product. Cancel/complete the linked orders first.',
      v_inv.quantity_prebooked;
  END IF;

  SELECT COUNT(*) INTO v_pending_deliv
  FROM delivery_items di
  JOIN deliveries d ON d.id = di.delivery_id
  WHERE di.product_id = v_inv.product_id
    AND d.status IN ('scheduled', 'in_progress');
  IF v_pending_deliv > 0 THEN
    RAISE EXCEPTION 'Cannot delete: % delivery(ies) still scheduled/in_progress for this product.', v_pending_deliv;
  END IF;

  INSERT INTO inventory_transactions (
    product_id, transaction_type, quantity, to_location,
    performed_by, notes
  ) VALUES (
    v_inv.product_id, 'adjusted', -v_old_quantity,
    COALESCE(v_inv.location, 'Main Warehouse'),
    v_actor,
    'Inventory record retired (had ' || v_old_quantity || ' available)'
  );

  DELETE FROM inventory WHERE id = p_inventory_id;

  v_result := jsonb_build_object(
    'success', true,
    'inventory_id', p_inventory_id,
    'product_id', v_inv.product_id,
    'retired_quantity', v_old_quantity
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'retire_inventory_item', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."retire_inventory_item"("p_inventory_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_failed_notifications"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_retried integer := 0;
  v_resolved integer := 0;
  v_exceeded integer := 0;
  v_row RECORD;
BEGIN
  -- Mark entries that exceeded max attempts
  UPDATE public.failed_notifications
  SET resolved_at = now(), updated_at = now()
  WHERE resolved_at IS NULL
    AND attempts >= max_attempts;
  GET DIAGNOSTICS v_exceeded = ROW_COUNT;

  -- Return summary (actual retry logic lives in the app layer
  -- since notifications use the Supabase client, not raw SQL)
  SELECT COUNT(*) INTO v_retried
  FROM public.failed_notifications
  WHERE resolved_at IS NULL;

  RETURN jsonb_build_object(
    'pending', v_retried,
    'exceeded_max_attempts', v_exceeded
  );
END;
$$;


ALTER FUNCTION "public"."retry_failed_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_application_record"("p_application_record_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor                uuid := auth.uid();
  v_cached               jsonb;
  v_record               record;
  v_original_txn         record;
  v_inventory            record;
  v_expected_deductions  integer := 0;
  v_ledger_deductions    integer := 0;
  v_reversed_count       integer := 0;
  v_result               jsonb;
  v_prior_reversal       boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  -- Fix F: admin-only (matches the replaced admin-only app_records_delete policy).
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin role required to reverse application records';
  END IF;

  -- Canonical helper-based replay check. Bind the cached result to this RPC's
  -- sole business argument so reuse of a key for another record fails loudly.
  IF p_idempotency_key IS NOT NULL THEN
    v_cached := check_idempotency(p_idempotency_key, 'reverse_application_record');
    IF v_cached IS NOT NULL THEN
      IF (v_cached->>'application_record_id')::uuid IS DISTINCT FROM p_application_record_id THEN
        RAISE EXCEPTION 'IDEMPOTENCY_ARGUMENT_MISMATCH: key % was already used to reverse a different application record',
          p_idempotency_key;
      END IF;
      RETURN v_cached;
    END IF;
  END IF;

  -- Serializes concurrent reversals of the same record. After the first caller
  -- commits its DELETE, a waiting caller observes no row and returns a no-op.
  SELECT ar.*
    INTO v_record
    FROM public.application_records ar
   WHERE ar.id = p_application_record_id
   FOR UPDATE;

  IF NOT FOUND THEN
    SELECT EXISTS (
      SELECT 1
        FROM public.inventory_transactions it
       WHERE it.transaction_type = 'adjusted'
         AND strpos(
               COALESCE(it.notes, ''),
               '(reversed application record ' || p_application_record_id::text || ')'
             ) > 0
    ) INTO v_prior_reversal;

    v_result := jsonb_build_object(
      'success', true,
      'status', CASE WHEN v_prior_reversal THEN 'already_reversed' ELSE 'not_found' END,
      'application_record_id', p_application_record_id,
      'inventory_transactions_reversed', 0,
      'already_reversed', v_prior_reversal
    );

    IF p_idempotency_key IS NOT NULL THEN
      PERFORM save_idempotency(
        p_idempotency_key,
        'reverse_application_record',
        v_result
      );
    END IF;
    RETURN v_result;
  END IF;

  -- This reversal is intentionally scoped to the create RPC named in Bug B.
  -- Job-sourced records have a separate job lifecycle and ledger-link shape.
  IF v_record.source_type IS DISTINCT FROM 'blend_ticket' THEN
    RAISE EXCEPTION 'APPLICATION_RECORD_NOT_REVERSIBLE: only blend_ticket application records can be reversed by this RPC';
  END IF;

  -- The create RPC writes one deduction transaction for every positive,
  -- product-linked product_data row. Count both sides before changing stock so
  -- a missing/edited ledger cannot produce a partial credit followed by DELETE.
  SELECT count(*)::integer
    INTO v_expected_deductions
    FROM jsonb_array_elements(COALESCE(v_record.product_data, '[]'::jsonb)) AS item
   WHERE NULLIF(item->>'product_id', '') IS NOT NULL
     AND COALESCE((item->>'quantity')::numeric, 0) > 0;

  SELECT count(*)::integer
    INTO v_ledger_deductions
    FROM public.inventory_transactions it
   WHERE it.transaction_type = 'job_applied'
     AND it.from_location = 'Main Warehouse'
     AND it.quantity > 0
     AND it.notes LIKE 'Blend ticket application:%'
     AND strpos(
           COALESCE(it.notes, ''),
           '(application record ' || p_application_record_id::text || ')'
         ) > 0;

  IF v_ledger_deductions IS DISTINCT FROM v_expected_deductions THEN
    RAISE EXCEPTION 'APPLICATION_RECORD_REVERSAL_LEDGER_MISMATCH: record % expects % deduction row(s), found %; record was not deleted',
      p_application_record_id, v_expected_deductions, v_ledger_deductions;
  END IF;

  -- Lock and credit products in deterministic order. quantity is the exact
  -- converted amount originally deducted; no unit conversion is repeated here.
  FOR v_original_txn IN
    SELECT it.id, it.product_id, it.quantity
      FROM public.inventory_transactions it
     WHERE it.transaction_type = 'job_applied'
       AND it.from_location = 'Main Warehouse'
       AND it.quantity > 0
       AND it.notes LIKE 'Blend ticket application:%'
       AND strpos(
             COALESCE(it.notes, ''),
             '(application record ' || p_application_record_id::text || ')'
           ) > 0
     ORDER BY it.product_id, it.id
     FOR UPDATE
  LOOP
    SELECT inv.*
      INTO v_inventory
      FROM public.inventory inv
     WHERE inv.product_id = v_original_txn.product_id
       AND inv.location = 'Main Warehouse'
     FOR UPDATE;

    IF NOT FOUND THEN
      -- The create RPC creates this row when absent. Recreate only if it was
      -- subsequently removed, preserving the same canonical warehouse shape.
      INSERT INTO public.inventory (
        product_id, location, quantity_available,
        quantity_prebooked, quantity_on_order
      ) VALUES (
        v_original_txn.product_id, 'Main Warehouse', v_original_txn.quantity,
        0, 0
      )
      ON CONFLICT (product_id, location) DO UPDATE
        SET quantity_available = public.inventory.quantity_available + EXCLUDED.quantity_available,
            updated_at = now();
    ELSE
      UPDATE public.inventory
         SET quantity_available = quantity_available + v_original_txn.quantity,
             updated_at = now()
       WHERE id = v_inventory.id;
    END IF;

    -- "adjusted" is an existing allowed inventory transaction type and is the
    -- closest available type for a non-delivery stock correction. Positive
    -- quantity + to_location mirrors the physical credit back to the warehouse.
    INSERT INTO public.inventory_transactions (
      product_id, transaction_type, quantity, to_location,
      performed_by, notes, requires_review
    ) VALUES (
      v_original_txn.product_id,
      'adjusted',
      v_original_txn.quantity,
      'Main Warehouse',
      v_actor,
      'Reversed blend ticket application record ' || v_record.record_number ||
        '; original inventory transaction ' || v_original_txn.id::text ||
        ' (reversed application record ' || p_application_record_id::text || ')',
      false
    );

    v_reversed_count := v_reversed_count + 1;
  END LOOP;

  -- Both child tables use ON DELETE CASCADE, but explicit deletes make the
  -- intended removal order clear and remain harmless if either table is empty.
  DELETE FROM public.application_record_lots
   WHERE application_record_id = p_application_record_id;
  DELETE FROM public.application_record_fields
   WHERE application_record_id = p_application_record_id;
  DELETE FROM public.application_records
   WHERE id = p_application_record_id;

  INSERT INTO public.activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'application_record_reversed',
    'Application record ' || v_record.record_number || ' reversed; ' ||
      v_reversed_count || ' inventory deduction(s) restored',
    v_actor,
    'blend_ticket',
    v_record.source_id,
    v_record.customer_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'status', 'reversed',
    'application_record_id', p_application_record_id,
    'blend_ticket_id', v_record.source_id,
    'record_number', v_record.record_number,
    'inventory_transactions_reversed', v_reversed_count,
    'already_reversed', false
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(
      p_idempotency_key,
      'reverse_application_record',
      v_result
    );
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."reverse_application_record"("p_application_record_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reverse_application_record"("p_application_record_id" "uuid", "p_idempotency_key" "text") IS 'Atomically restores exact blend-ticket application inventory deductions, writes reversal ledger rows, removes the application record, and enforces argument-bound idempotency.';



CREATE OR REPLACE FUNCTION "public"."reverse_blend_ticket_approval"("p_ticket_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_ticket   record;
  v_existing jsonb;
  v_result   jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'admin') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required to reverse a blend ticket approval';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key
       AND operation = 'reverse_blend_ticket_approval';
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  SELECT * INTO v_ticket
    FROM blend_tickets
   WHERE id = p_ticket_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Blend ticket not found: %', p_ticket_id;
  END IF;

  IF v_ticket.review_status != 'approved' THEN
    RAISE EXCEPTION 'Only approved blend tickets can have their approval reversed (current review_status: %)', v_ticket.review_status;
  END IF;

  -- OVERNIGHT FIX (finding #8): a billed ticket must NOT be reopened while it still has a live
  -- invoice — otherwise its already-invoiced contents could be edited and diverge from the issued
  -- invoice. The application_records guard below is vacuous for blend invoices (billing writes none),
  -- so gate on an active linked invoice too: void the invoice(s) first.
  IF EXISTS (
    SELECT 1 FROM invoices
    WHERE blend_ticket_id = p_ticket_id
      AND status NOT IN ('voided', 'cancelled')
      AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'CANNOT_REVERSE_APPROVAL_INVOICE_EXISTS: blend ticket % has an active invoice — void the invoice(s) first, then reverse the approval', v_ticket.ticket_number;
  END IF;

  IF EXISTS (
    SELECT 1 FROM application_records
    WHERE source_type = 'blend_ticket' AND source_id = p_ticket_id
  ) THEN
    RAISE EXCEPTION 'CANNOT_REVERSE_APPROVAL_RECORDS_EXIST: application records exist for blend ticket % — reverse those (and their inventory) first', v_ticket.ticket_number;
  END IF;

  UPDATE blend_tickets SET
    review_status = 'unreviewed',
    reviewed_by   = NULL,
    reviewed_at   = NULL,
    updated_at    = now()
  WHERE id = p_ticket_id;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    old_values, new_values, description
  ) VALUES (
    'blend_ticket_approval_reversed', 'blend_ticket', p_ticket_id,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object('review_status', 'approved', 'reviewed_by', v_ticket.reviewed_by, 'reviewed_at', v_ticket.reviewed_at),
    jsonb_build_object('review_status', 'unreviewed'),
    'Blend ticket ' || v_ticket.ticket_number || ' approval reversed: ' || p_reason
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'blend_ticket_approval_reversed',
    'Blend ticket ' || v_ticket.ticket_number || ' approval reversed: ' || p_reason,
    v_actor, 'blend_ticket', p_ticket_id, v_ticket.customer_id
  );

  v_result := jsonb_build_object(
    'success',        true,
    'ticket_id',      p_ticket_id,
    'ticket_number',  v_ticket.ticket_number
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result, expires_at)
    VALUES (p_idempotency_key, 'reverse_blend_ticket_approval', v_result, now() + interval '24 hours')
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."reverse_blend_ticket_approval"("p_ticket_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reverse_blend_ticket_approval"("p_ticket_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Admin-only revert of a blend ticket review_status from "approved" to "unreviewed". Wave A.6 explicit rewrite.';



CREATE OR REPLACE FUNCTION "public"."reverse_completed_cycle_count"("p_cycle_count_id" "uuid", "p_reversed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_reversed_by IS NOT NULL AND p_reversed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'reverse_completed_cycle_count');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;
  PERFORM 1 FROM public.cycle_counts WHERE id = p_cycle_count_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CYCLE_COUNT_NOT_FOUND'; END IF;
  PERFORM 1
  FROM public.inventory i
  JOIN public.cycle_count_items cci ON cci.inventory_id = i.id
  WHERE cci.cycle_count_id = p_cycle_count_id
  ORDER BY i.id
  FOR UPDATE OF i;
  PERFORM public._reverse_completed_cycle_count_impl(p_cycle_count_id, v_actor, p_idempotency_key);
END;
$$;


ALTER FUNCTION "public"."reverse_completed_cycle_count"("p_cycle_count_id" "uuid", "p_reversed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_credit_memo_application"("p_application_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor      uuid;
  v_actor_role text;
  v_app        record;
  v_existing   jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  -- Codex BLOCKER: NULL (inactive/absent profile) must be rejected — `NULL NOT IN (...)` is not true.
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: only active admins and sales reps can reverse credit applications';
  END IF;
  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'REASON_REQUIRED: a reason is required to reverse a credit application';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'reverse_credit_memo_application');
    IF v_existing IS NOT NULL THEN
      -- Codex HIGH: bind idempotency to the application id (mirror the apply RPC) so a key reused
      -- for a DIFFERENT application can't silently return the first application's success.
      IF (v_existing->>'application_id')::uuid IS DISTINCT FROM p_application_id THEN
        RAISE EXCEPTION 'IDEMPOTENCY_ARGUMENT_MISMATCH: key % was already used to reverse a different application', p_idempotency_key;
      END IF;
      RETURN v_existing;
    END IF;
  END IF;

  SELECT * INTO v_app FROM credit_memo_applications WHERE id = p_application_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CREDIT_APPLICATION_NOT_FOUND: %', p_application_id; END IF;
  IF v_app.reversed_at IS NOT NULL THEN
    RAISE EXCEPTION 'CREDIT_APPLICATION_ALREADY_REVERSED: %', p_application_id;
  END IF;

  -- Codex HIGH: gate on the APPLICATION's own period (applied_at), NOT the memo's ISSUE date. Apply
  -- checks CURRENT_DATE, so an application made in an open period must stay reversible in it even if
  -- the memo was issued in a since-closed period (mirrors void_payment gating on payment_date).
  PERFORM check_period_open(v_app.applied_at::date);

  PERFORM _reverse_credit_memo_application(p_application_id, v_actor, v_actor_role, p_reason);

  v_existing := jsonb_build_object(
    'success', true, 'application_id', p_application_id,
    'credit_memo_id', v_app.credit_memo_id, 'target_invoice_id', v_app.target_invoice_id,
    'amount_cents', v_app.amount_cents
  );
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'reverse_credit_memo_application', v_existing);
  END IF;
  RETURN v_existing;
END;
$$;


ALTER FUNCTION "public"."reverse_credit_memo_application"("p_application_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_receiving_record"("p_record_id" "uuid", "p_reason" "text" DEFAULT 'Manually reversed'::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rec    record;
  v_actor  uuid;
  v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'admin') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'reverse_receiving_record';
    IF v_existing IS NOT NULL THEN
      RETURN jsonb_build_object('success', true, 'record_id', p_record_id, 'idempotent', true);
    END IF;
  END IF;

  SELECT * INTO v_rec
  FROM receiving_records
  WHERE id = p_record_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receiving record not found: %', p_record_id;
  END IF;

  PERFORM set_config('app.reversal_rpc_active', 'true', true);
  PERFORM set_config('app.admin_override', 'true', true);

  UPDATE inventory
  SET quantity_available = quantity_available - v_rec.quantity_received,
      updated_at         = now()
  WHERE product_id = v_rec.product_id
    AND location   = v_rec.storage_location;

  INSERT INTO inventory_transactions (
    product_id, transaction_type, quantity, to_location,
    notes, performed_by
  ) VALUES (
    v_rec.product_id,
    'adjusted',
    -1 * v_rec.quantity_received,
    v_rec.storage_location,
    'Reversed receiving record ' || p_record_id::text || ': ' || p_reason,
    v_actor
  );

  UPDATE purchase_order_items
  SET quantity_received = GREATEST(quantity_received - v_rec.quantity_received, 0)
  WHERE id = v_rec.po_item_id;

  UPDATE purchase_orders
  SET status = CASE
    WHEN (
      SELECT bool_and(quantity_received = 0)
      FROM purchase_order_items
      WHERE purchase_order_id = v_rec.purchase_order_id
    ) THEN 'submitted'
    WHEN (
      SELECT bool_and(quantity_received >= quantity_ordered)
      FROM purchase_order_items
      WHERE purchase_order_id = v_rec.purchase_order_id
    ) THEN 'fully_received'
    ELSE 'partially_received'
  END,
  updated_at = now()
  WHERE id = v_rec.purchase_order_id
    AND status <> 'cancelled';

  DELETE FROM receiving_photos WHERE receiving_record_id = p_record_id;
  DELETE FROM receiving_records WHERE id = p_record_id;

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'reverse_receiving_record', to_jsonb(p_record_id));
  END IF;

  RETURN jsonb_build_object(
    'success',             true,
    'record_id',           p_record_id,
    'product_id',          v_rec.product_id,
    'quantity_reversed',   v_rec.quantity_received,
    'storage_location',    v_rec.storage_location
  );
END;
$$;


ALTER FUNCTION "public"."reverse_receiving_record"("p_record_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_write_off"("p_write_off_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor          uuid;
  v_wo             record;
  v_existing       jsonb;
  v_new_balance    bigint;
  v_old_status     text;
  v_due_date       date;
  v_new_status     text;
  v_status_changed boolean;
  v_result         jsonb;
BEGIN
  -- Strict-actor: derive from JWT, never trust a client-supplied UUID.
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  IF (SELECT role FROM profiles WHERE id = v_actor AND is_active = true) != 'admin' THEN
    RAISE EXCEPTION 'Admin access required to reverse write-offs';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required to reverse a write-off';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key
       AND operation = 'reverse_write_off';
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  SELECT * INTO v_wo
    FROM write_offs
   WHERE id = p_write_off_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Write-off not found: %', p_write_off_id;
  END IF;

  IF v_wo.reversed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Write-off has already been reversed';
  END IF;

  -- OVERNIGHT FIX (finding #2): reversing a write-off retroactively changes AR and writes the
  -- append-only ledger; gate on the write-off's booked date so a closed period blocks it
  -- (Hard Red Line: never bypass check_period_open).
  PERFORM check_period_open(v_wo.created_at::date);

  SELECT status, due_date INTO v_old_status, v_due_date
    FROM invoices
   WHERE id = v_wo.invoice_id
   FOR UPDATE;

  IF v_old_status IS NULL THEN
    RAISE EXCEPTION 'Invoice not found for write-off %: %', p_write_off_id, v_wo.invoice_id;
  END IF;

  UPDATE invoices
     SET write_off_cents = GREATEST(COALESCE(write_off_cents, 0) - v_wo.amount_cents, 0),
         updated_at      = now()
   WHERE id = v_wo.invoice_id;

  SELECT balance_cents INTO v_new_balance
    FROM invoices
   WHERE id = v_wo.invoice_id;

  IF v_old_status = 'paid' AND v_new_balance > 0 THEN
    IF v_due_date IS NOT NULL AND v_due_date < CURRENT_DATE THEN
      v_new_status := 'overdue';
    ELSE
      v_new_status := 'posted';
    END IF;
    UPDATE invoices
       SET status     = v_new_status,
           updated_at = now()
     WHERE id = v_wo.invoice_id;
    v_status_changed := true;
  ELSE
    v_new_status := v_old_status;
    v_status_changed := false;
  END IF;

  UPDATE write_offs
     SET reversed_at     = now(),
         reversed_by     = v_actor,
         reversed_reason = p_reason
   WHERE id = p_write_off_id;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    old_values, new_values, total_impact_cents, description
  ) VALUES (
    'write_off_reversed', 'write_off', p_write_off_id,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object(
      'amount_cents',   v_wo.amount_cents,
      'reversed_at',    null,
      'invoice_status', v_old_status
    ),
    jsonb_build_object(
      'reversed_at',       now(),
      'reverse_reason',    p_reason,
      'invoice_status',    v_new_status,
      'new_balance_cents', v_new_balance
    ),
    v_wo.amount_cents,
    'Write-off of ' || (v_wo.amount_cents::numeric / 100)::text ||
      ' reversed on invoice ' || v_wo.invoice_id::text || ': ' || p_reason
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'write_off_reversed',
    'Write-off of $' || (v_wo.amount_cents::numeric / 100)::text || ' reversed: ' || p_reason,
    v_actor, 'invoice', v_wo.invoice_id, v_wo.customer_id
  );

  v_result := jsonb_build_object(
    'success',           true,
    'write_off_id',      p_write_off_id,
    'amount_cents',      v_wo.amount_cents,
    'invoice_id',        v_wo.invoice_id,
    'new_balance_cents', v_new_balance,
    'status_changed',    v_status_changed,
    'new_status',        v_new_status
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result, expires_at)
    VALUES (p_idempotency_key, 'reverse_write_off', v_result, now() + interval '24 hours')
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."reverse_write_off"("p_write_off_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reverse_write_off"("p_write_off_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Reverses a write-off by decrementing invoices.write_off_cents (balance_cents is GENERATED). Re-derives status: paid -> overdue when due_date < CURRENT_DATE, paid -> posted otherwise. Idempotency-safe. Wave A.1 + follow-up / audit finding P3-1.';



CREATE OR REPLACE FUNCTION "public"."revert_quote_status"("p_quote_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor              uuid;
  v_quote              record;
  v_existing           jsonb;
  v_existing_operation text;
  v_result             jsonb;
  v_reason             text;
  v_request            jsonb;
  v_fingerprint        text;
  v_contract CONSTANT text := 'revert_quote_status_v1';
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'admin') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required to revert quote status';
  END IF;
  v_reason := btrim(p_reason);

  IF p_idempotency_key IS NOT NULL THEN
    IF btrim(p_idempotency_key) = '' THEN
      RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
    END IF;

    v_request := jsonb_build_object(
      'contract_version', v_contract,
      'quote_id', p_quote_id,
      'actor_id', v_actor,
      'reason', v_reason
    );
    v_fingerprint := md5(v_request::text);

    PERFORM pg_advisory_xact_lock(
      hashtextextended('crx:idempotency:revert_quote_status:' || p_idempotency_key, 0)
    );
    PERFORM pg_advisory_xact_lock(
      hashtextextended('crx:idempotency:' || p_idempotency_key, 0)
    );

    DELETE FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key
       AND expires_at < now();

    SELECT operation, result
      INTO v_existing_operation, v_existing
      FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key;

    IF FOUND THEN
      IF v_existing_operation IS DISTINCT FROM 'revert_quote_status' THEN
        RAISE EXCEPTION
          'IDEMPOTENCY_CROSS_OP_KEY_REUSE: idempotency_key % is already in use for operation %; cannot reuse it for operation revert_quote_status',
          p_idempotency_key, v_existing_operation;
      END IF;
      IF v_existing->>'_contract' IS DISTINCT FROM v_contract
         OR NOT (v_existing ? 'request_fingerprint') THEN
        RAISE EXCEPTION
          'IDEMPOTENCY_UNBOUND_REPLAY: key % has no revert_quote_status_v1 request binding; use a new key',
          p_idempotency_key;
      END IF;
      IF v_existing->>'request_fingerprint' IS DISTINCT FROM v_fingerprint THEN
        RAISE EXCEPTION
          'IDEMPOTENCY_REQUEST_MISMATCH: key % was already used with different revert_quote_status arguments',
          p_idempotency_key;
      END IF;
      IF NOT (v_existing ? 'response') OR v_existing->'response' = 'null'::jsonb THEN
        RAISE EXCEPTION
          'IDEMPOTENCY_INCOMPLETE_REPLAY: key % has no completed revert_quote_status response',
          p_idempotency_key;
      END IF;
      RETURN v_existing->'response';
    END IF;

    INSERT INTO idempotency_keys (idempotency_key, operation, result, expires_at)
    VALUES (
      p_idempotency_key,
      'revert_quote_status',
      jsonb_build_object(
        '_contract', v_contract,
        'request_fingerprint', v_fingerprint,
        'request', v_request,
        'response', NULL
      ),
      now() + interval '24 hours'
    );
  END IF;

  SELECT * INTO v_quote
    FROM quotes
   WHERE id = p_quote_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Quote not found: %', p_quote_id;
  END IF;

  IF v_quote.status NOT IN ('declined', 'expired', 'cancelled', 'accepted') THEN
    RAISE EXCEPTION 'Cannot revert quote in status "%" — only declined, expired, cancelled, or accepted quotes can be reverted', v_quote.status;
  END IF;

  IF v_quote.status = 'accepted' THEN
    -- DEADLOCK FIX: keep the quote-first contract shared with conversion, but
    -- never wait on an order that cancel_order may hold while it waits here.
    -- A serialization_failure is safe to retry; the whole idempotency claim and
    -- every earlier action roll back with this transaction.
    BEGIN
      PERFORM 1
        FROM orders
       WHERE quote_id = p_quote_id
       ORDER BY id
       FOR UPDATE NOWAIT;
    EXCEPTION WHEN lock_not_available THEN
      RAISE EXCEPTION
        'QUOTE_REOPEN_CONCURRENT_ORDER_CHANGE_RETRY: an order from quote % is changing; retry after the cancellation finishes',
        v_quote.quote_number
        USING ERRCODE = '40001';
    END;

    IF EXISTS (SELECT 1 FROM orders WHERE quote_id = p_quote_id AND status <> 'cancelled') THEN
      RAISE EXCEPTION 'Cannot revert accepted quote % — an active (non-cancelled) order exists from it', v_quote.quote_number;
    END IF;

    IF EXISTS (
         SELECT 1
           FROM orders o
           JOIN order_items oi ON oi.order_id = o.id
          WHERE o.quote_id = p_quote_id
            AND COALESCE(oi.quantity_delivered, 0) > 0
       )
       OR EXISTS (
         SELECT 1
           FROM orders o
           JOIN deliveries d ON d.order_id = o.id
          WHERE o.quote_id = p_quote_id
            AND d.status = 'completed'
       )
       OR EXISTS (
         SELECT 1
           FROM orders o
           JOIN invoices i ON i.order_id = o.id
          WHERE o.quote_id = p_quote_id
            AND i.deleted_at IS NULL
            AND i.status NOT IN ('voided', 'cancelled')
       )
       OR EXISTS (
         SELECT 1
           FROM orders o
           JOIN commissions c ON c.order_id = o.id
          WHERE o.quote_id = p_quote_id
            AND c.status = 'paid'
       )
       OR EXISTS (
         SELECT 1
           FROM orders o
           JOIN commissions c ON c.order_id = o.id
           JOIN commission_payment_items cpi ON cpi.commission_id = c.id
           JOIN commission_payments cp ON cp.id = cpi.commission_payment_id
          WHERE o.quote_id = p_quote_id
            AND cp.status <> 'voided'
       ) THEN
      RAISE EXCEPTION 'QUOTE_REOPEN_HAS_ORDER_HISTORY: quote % has delivered, invoiced, or paid/batched commission history; create a new quote/order instead of re-converting it', v_quote.quote_number;
    END IF;
  END IF;

  PERFORM set_config('app.admin_override', 'true', true);
  UPDATE quotes SET
    status     = 'sent',
    updated_at = now()
  WHERE id = p_quote_id;
  PERFORM set_config('app.admin_override', 'false', true);

  IF v_quote.status = 'accepted' THEN
    UPDATE quote_product_draws
       SET quantity_drawn = 0, updated_at = now()
     WHERE quote_id = p_quote_id AND quantity_drawn <> 0;
  END IF;

  IF v_quote.is_planned THEN
    PERFORM create_planned_holds(p_quote_id, v_actor, NULL);
  END IF;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    old_values, new_values, description
  ) VALUES (
    'quote_status_reverted', 'quote', p_quote_id,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object('status', v_quote.status),
    jsonb_build_object('status', 'sent'),
    'Quote ' || v_quote.quote_number || ' reverted from ' || v_quote.status || ' to sent: ' || v_reason
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'quote_status_reverted',
    'Quote ' || v_quote.quote_number || ' reverted from ' || v_quote.status || ' to sent: ' || v_reason,
    v_actor, 'quote', p_quote_id, v_quote.customer_id
  );

  v_result := jsonb_build_object(
    'success',       true,
    'quote_id',      p_quote_id,
    'quote_number',  v_quote.quote_number,
    'old_status',    v_quote.status,
    'new_status',    'sent'
  );

  IF p_idempotency_key IS NOT NULL THEN
    UPDATE idempotency_keys
       SET result = jsonb_build_object(
             '_contract', v_contract,
             'request_fingerprint', v_fingerprint,
             'request', v_request,
             'response', v_result
           ),
           expires_at = now() + interval '24 hours'
     WHERE idempotency_key = p_idempotency_key
       AND operation = 'revert_quote_status';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'IDEMPOTENCY_CLAIM_LOST: revert_quote_status key % disappeared', p_idempotency_key;
    END IF;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."revert_quote_status"("p_quote_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."revert_quote_status"("p_quote_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Admin-only revert of a declined/expired/cancelled/accepted quote back to "sent". Accepted quotes blocked if an order has been created. Wave A.6 explicit rewrite.';



CREATE OR REPLACE FUNCTION "public"."review_customer_fact"("p_fact_id" "uuid", "p_verdict" "text", "p_review_note" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_fact public.customer_facts%ROWTYPE;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  IF p_verdict NOT IN ('verified', 'rejected') THEN
    RAISE EXCEPTION 'FACT_VERDICT_INVALID';
  END IF;

  SELECT * INTO v_fact FROM public.customer_facts WHERE id = p_fact_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FACT_NOT_FOUND'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.is_active)
     OR NOT (public.is_admin() OR (public.is_sales_rep() AND EXISTS (
       SELECT 1 FROM public.customers c
       WHERE c.id = v_fact.customer_id AND c.assigned_sales_rep = auth.uid()
     ))) THEN
    RAISE EXCEPTION 'FACT_ACCESS_DENIED';
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'review_customer_fact');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;
  IF v_fact.status <> 'pending_review' THEN
    IF v_fact.status = p_verdict THEN
      v_result := jsonb_build_object('success', true, 'fact_id', v_fact.id, 'noop', true, 'status', v_fact.status);
    ELSE
      RAISE EXCEPTION 'FACT_ALREADY_REVIEWED';
    END IF;
  ELSE
    UPDATE public.customer_facts
    SET status = p_verdict, reviewed_by = auth.uid(), reviewed_at = now(), review_note = p_review_note
    WHERE id = v_fact.id;
    v_result := jsonb_build_object('success', true, 'fact_id', v_fact.id, 'noop', false, 'status', p_verdict);
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(p_idempotency_key, 'review_customer_fact', v_result);
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."review_customer_fact"("p_fact_id" "uuid", "p_verdict" "text", "p_review_note" "text", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_customer_fact"("p_fact_id" "uuid", "p_verdict" "text", "p_review_note" "text", "p_idempotency_key" "text") IS 'Reviews a pending customer fact with active-admin or assigned-rep authorization and idempotent replay.';



CREATE OR REPLACE FUNCTION "public"."review_vendor_alias"("p_alias_id" "uuid", "p_vendor_id" "uuid", "p_decision" "text", "p_review_note" "text", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_request_fp text;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;
  IF p_decision NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'VENDOR_ALIAS_DECISION_INVALID';
  END IF;
  IF p_decision = 'approved' AND NOT EXISTS (
    SELECT 1 FROM public.vendors WHERE id = p_vendor_id AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'VENDOR_NOT_FOUND';
  END IF;

  v_request_fp := md5(jsonb_build_object(
    'actor_id', v_actor,
    'alias_id', p_alias_id,
    'vendor_id', p_vendor_id,
    'decision', p_decision,
    'review_note', p_review_note
  )::text);
  v_existing := public.check_idempotency(p_idempotency_key, 'review_vendor_alias');
  IF v_existing IS NOT NULL THEN
    IF v_existing->>'actor_id' IS DISTINCT FROM v_actor::text
       OR v_existing->>'request_fingerprint' IS DISTINCT FROM v_request_fp THEN
      RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH';
    END IF;
    RETURN v_existing->'response';
  END IF;

  UPDATE public.vendor_aliases AS alias
  SET vendor_id = CASE WHEN p_decision = 'approved' THEN p_vendor_id ELSE NULL END,
      review_status = p_decision,
      review_note = NULLIF(btrim(COALESCE(p_review_note, '')), ''),
      reviewed_by = v_actor,
      reviewed_at = now()
  WHERE id = p_alias_id
    AND review_status = 'pending'
  RETURNING to_jsonb(alias) INTO v_result;
  IF v_result IS NULL THEN RAISE EXCEPTION 'VENDOR_ALIAS_NOT_PENDING'; END IF;

  PERFORM public.save_idempotency(
    p_idempotency_key,
    'review_vendor_alias',
    jsonb_build_object('actor_id', v_actor, 'request_fingerprint', v_request_fp, 'response', v_result)
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."review_vendor_alias"("p_alias_id" "uuid", "p_vendor_id" "uuid", "p_decision" "text", "p_review_note" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rollover_quote_to_season"("p_quote_id" "uuid", "p_new_season" integer, "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_old_quote quotes%ROWTYPE;
  v_new_quote_id uuid;
  v_new_quote_number text;
  v_section RECORD;
  v_new_section_id uuid;
  v_item RECORD;
  v_tier_price numeric;
  v_current_cost numeric;
  v_has_draws boolean := false;
  v_total_remainder numeric;
  v_drawn numeric;
  v_cum_before numeric;
  v_item_tun numeric;
  v_new_tun numeric;
  v_new_acres numeric;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'rollover_quote_to_season' AND created_at > now() - interval '24 hours'
    ) THEN
      RETURN jsonb_build_object('status', 'duplicate', 'message', 'Already processed');
    END IF;
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'rollover_quote_to_season', to_jsonb(p_quote_id));
  END IF;

  SELECT * INTO v_old_quote FROM quotes WHERE id = p_quote_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found: %', p_quote_id; END IF;

  -- A5 draw-awareness, GATED to OPEN bookings. LAYER2: "draws" now means BOTH order
  -- draws (quote_product_draws) AND job draws (job_product_draws) — a booking consumed
  -- by a job rolls over only its truly-undrawn remainder (§6.5). The gate includes
  -- 'draft' because a job can be scheduled from a DRAFT planned quote (A4 gates the
  -- reserve on is_planned + non-terminal, which includes draft), so a draft with a live
  -- job draw must NOT clone the job-consumed units into the next season (Codex round-3
  -- P2). Order draws only ever exist on sent/revised, so adding 'draft' only affects
  -- job-draw detection.
  IF v_old_quote.status IN ('draft', 'sent', 'revised') THEN
    SELECT
      EXISTS (SELECT 1 FROM quote_product_draws WHERE quote_id = p_quote_id AND quantity_drawn > 0)
      -- LAYER2<<< job draws also count as "drawn"
      OR EXISTS (SELECT 1 FROM job_product_draws WHERE quote_id = p_quote_id AND quantity_drawn > 0)
      -- >>>LAYER2
    INTO v_has_draws;
    IF v_has_draws THEN
      -- LAYER2<<< remainder subtracts order + job draws per product
      SELECT COALESCE(SUM(GREATEST(b.booked - COALESCE(d.quantity_drawn, 0) - COALESCE(jd.qty, 0), 0)), 0)
      INTO v_total_remainder
      FROM (
        SELECT product_id, SUM(COALESCE(total_units_needed, 0)) AS booked
        FROM quote_items WHERE quote_id = p_quote_id
        GROUP BY product_id
      ) b
      LEFT JOIN quote_product_draws d
        ON d.quote_id = p_quote_id AND d.product_id = b.product_id
      LEFT JOIN (
        SELECT product_id, SUM(quantity_drawn) AS qty
        FROM job_product_draws WHERE quote_id = p_quote_id
        GROUP BY product_id
      ) jd ON jd.product_id = b.product_id;
      -- >>>LAYER2
      IF v_total_remainder <= 0 THEN
        RAISE EXCEPTION 'BOOKING_FULLY_DRAWN: quote % has no undrawn balance to roll over — every booked quantity is already on orders or jobs', v_old_quote.quote_number;
      END IF;
    END IF;
  END IF;

  SELECT generate_quote_number() INTO v_new_quote_number;

  INSERT INTO quotes (
    quote_number, customer_id, created_by, tier, status, is_planned,
    commission_split, valid_days, header_notes, footer_notes, season, salesman_id
  ) VALUES (
    v_new_quote_number, v_old_quote.customer_id, v_actor, v_old_quote.tier,
    'draft', v_old_quote.is_planned, v_old_quote.commission_split,
    v_old_quote.valid_days, v_old_quote.header_notes, v_old_quote.footer_notes,
    p_new_season, v_old_quote.salesman_id
  ) RETURNING id INTO v_new_quote_id;

  FOR v_section IN
    SELECT * FROM quote_sections WHERE quote_id = p_quote_id ORDER BY sort_order
  LOOP
    INSERT INTO quote_sections (quote_id, section_name, sort_order, section_notes, section_header_notes)
    VALUES (v_new_quote_id, v_section.section_name, v_section.sort_order,
      v_section.section_notes, v_section.section_header_notes)
    RETURNING id INTO v_new_section_id;

    FOR v_item IN
      SELECT * FROM quote_items WHERE section_id = v_section.id ORDER BY sort_order
    LOOP
      v_drawn := 0;
      v_new_tun := NULL;
      v_new_acres := NULL;
      IF v_has_draws THEN
        -- LAYER2<<< consumed quantity = order draws + job draws for this product
        SELECT
          COALESCE((SELECT quantity_drawn FROM quote_product_draws
                    WHERE quote_id = p_quote_id AND product_id = v_item.product_id), 0)
          + COALESCE((SELECT SUM(quantity_drawn) FROM job_product_draws
                      WHERE quote_id = p_quote_id AND product_id = v_item.product_id), 0)
        INTO v_drawn;
        v_drawn := COALESCE(v_drawn, 0);
        -- >>>LAYER2
        IF v_drawn > 0 THEN
          v_item_tun := COALESCE(v_item.total_units_needed, 0);
          SELECT COALESCE(SUM(COALESCE(qi2.total_units_needed, 0)), 0) INTO v_cum_before
          FROM quote_items qi2
          JOIN quote_sections qs2 ON qs2.id = qi2.section_id
          WHERE qi2.quote_id = p_quote_id
            AND qi2.product_id = v_item.product_id
            AND (qs2.sort_order, qs2.id, qi2.sort_order, qi2.id)
              < (v_section.sort_order, v_section.id, v_item.sort_order, v_item.id);
          v_new_tun := LEAST(v_item_tun, GREATEST(v_cum_before + v_item_tun - v_drawn, 0));
          IF v_new_tun <= 0 THEN
            CONTINUE;
          END IF;
          IF v_new_tun = v_item_tun THEN
            v_new_acres := v_item.acres;
          ELSIF v_item.acres IS NOT NULL AND v_item_tun > 0 THEN
            v_new_acres := ROUND(v_item.acres * v_new_tun / v_item_tun, 2);
          ELSE
            v_new_acres := v_item.acres;
          END IF;
        END IF;
      END IF;

      SELECT CASE v_old_quote.tier
        WHEN 1 THEN COALESCE(p.tier1_price, 0)
        WHEN 2 THEN COALESCE(p.tier2_price, p.tier1_price, 0)
        WHEN 3 THEN COALESCE(p.tier3_price, p.tier1_price, 0)
        ELSE COALESCE(p.tier1_price, 0)
      END, p.current_cost
      INTO v_tier_price, v_current_cost
      FROM products p WHERE p.id = v_item.product_id;

      IF v_has_draws AND v_drawn > 0 THEN
        INSERT INTO quote_items (
          quote_id, section_id, product_id, sort_order, notes,
          price_per_unit, current_cost, suggested_rate, actual_rate, rate_unit,
          acres, calc_mode, price_unit, total_units_needed
        ) VALUES (
          v_new_quote_id, v_new_section_id, v_item.product_id, v_item.sort_order,
          v_item.notes, v_tier_price, v_current_cost, v_item.suggested_rate,
          v_item.actual_rate, v_item.rate_unit, v_new_acres,
          v_item.calc_mode, v_item.price_unit, v_new_tun
        );
      ELSE
        INSERT INTO quote_items (
          quote_id, section_id, product_id, sort_order, notes,
          price_per_unit, current_cost, suggested_rate, actual_rate, rate_unit,
          acres, calc_mode, price_unit
        ) VALUES (
          v_new_quote_id, v_new_section_id, v_item.product_id, v_item.sort_order,
          v_item.notes, v_tier_price, v_current_cost, v_item.suggested_rate,
          v_item.actual_rate, v_item.rate_unit, v_item.acres,
          v_item.calc_mode, v_item.price_unit
        );
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'status', 'created',
    'quote_id', v_new_quote_id,
    'quote_number', v_new_quote_number,
    'season', p_new_season,
    'remainder_rollover', v_has_draws
  );
END;
$$;


ALTER FUNCTION "public"."rollover_quote_to_season"("p_quote_id" "uuid", "p_new_season" integer, "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_data_integrity_sweep"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_negative_inventory integer := 0;
  v_negative_invoices  integer := 0;
  v_stale_holds        integer := 0;
  v_overdraws          integer := 0;
BEGIN
  -- admin-only when an authenticated user calls this; pg_cron / service_role
  -- (auth.uid() = NULL) bypass. Same pattern as check_unpriced_orders.
  IF auth.uid() IS NOT NULL AND NOT is_admin() THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- (a) NEW negative inventory: per-product net position across locations,
  --     skipping the pre-existing negatives in the baseline (H1).
  INSERT INTO integrity_alerts (alert_type, entity_table, entity_id, details)
  SELECT 'negative_inventory', 'products', neg.product_id,
         jsonb_build_object('net_quantity_available', neg.net_qty)
  FROM (
    SELECT product_id, SUM(quantity_available) AS net_qty
    FROM inventory
    GROUP BY product_id
    HAVING SUM(quantity_available) < 0
  ) neg
  WHERE NOT EXISTS (
    SELECT 1 FROM integrity_negative_baseline b WHERE b.product_id = neg.product_id
  )
  ON CONFLICT (alert_type, entity_table, entity_id) WHERE resolved_at IS NULL
  DO NOTHING;
  GET DIAGNOSTICS v_negative_inventory = ROW_COUNT;

  -- (b) Invoices with a negative balance. balance_cents is GENERATED ALWAYS
  --     ((total - paid - prepay_applied - write_off)) — SELECT-only here.
  --     Negative means we over-collected — anomalous EXCEPT for credit memos,
  --     which are legitimately negative (the live invoices_balance_non_negative
  --     CHECK exempts invoice_type='credit_memo' for exactly this reason).
  INSERT INTO integrity_alerts (alert_type, entity_table, entity_id, details)
  SELECT 'negative_invoice_balance', 'invoices', inv.id,
         jsonb_build_object(
           'invoice_number', inv.invoice_number,
           'status',         inv.status,
           'balance_cents',  inv.balance_cents)
  FROM invoices inv
  WHERE inv.balance_cents < 0
    AND inv.invoice_type <> 'credit_memo'  -- CHANGED (Codex 2026-07-05 P2): valid open credits are negative by design
    AND inv.deleted_at IS NULL
  ON CONFLICT (alert_type, entity_table, entity_id) WHERE resolved_at IS NULL
  DO NOTHING;
  GET DIAGNOSTICS v_negative_invoices = ROW_COUNT;

  -- (c) Active crop_program holds whose parent quote is terminal — those holds
  --     should have been released by the decline/expire/cancel/close paths;
  --     a survivor silently shrinks Net Free forever.
  --     U5<<< 'closed_short' is a terminal booking whose crop_program remainder
  --     is released on close — a survivor is stale, same as the others. (#1)
  INSERT INTO integrity_alerts (alert_type, entity_table, entity_id, details)
  SELECT 'stale_quote_hold', 'inventory_holds', h.id,
         jsonb_build_object(
           'quote_id',     q.id,
           'quote_status', q.status,
           'product_id',   h.product_id,
           'quantity',     h.quantity)
  FROM inventory_holds h
  JOIN quotes q ON q.id = h.source_id
  WHERE h.is_active = true
    AND h.hold_type = 'crop_program'
    AND q.status IN ('declined', 'expired', 'cancelled', 'closed_by_application', 'closed_short')
  ON CONFLICT (alert_type, entity_table, entity_id) WHERE resolved_at IS NULL
  DO NOTHING;
  GET DIAGNOSTICS v_stale_holds = ROW_COUNT;

  -- (d) Booking overdraw: drawn more than the booking cap. Cap = the same
  --     SUM(COALESCE(quote_items.total_units_needed, 0)) per (quote, product)
  --     that draw_down_quote's fully-drawn check uses (20260610145253).
  --     Also catches drawn > 0 rows whose quote_items lines were edited away
  --     (cap collapses to 0) — that IS drift worth flagging.
  INSERT INTO integrity_alerts (alert_type, entity_table, entity_id, details)
  SELECT 'booking_overdraw', 'quote_product_draws', d.id,
         jsonb_build_object(
           'quote_id',       d.quote_id,
           'product_id',     d.product_id,
           'quantity_drawn', d.quantity_drawn,
           'booking_cap',    cap.booked)
  FROM quote_product_draws d
  JOIN quotes q ON q.id = d.quote_id
  CROSS JOIN LATERAL (
    SELECT COALESCE(SUM(COALESCE(qi.total_units_needed, 0)), 0) AS booked
    FROM quote_items qi
    WHERE qi.quote_id = d.quote_id AND qi.product_id = d.product_id
  ) cap
  WHERE q.deleted_at IS NULL
    AND d.quantity_drawn > cap.booked
  ON CONFLICT (alert_type, entity_table, entity_id) WHERE resolved_at IS NULL
  DO NOTHING;
  GET DIAGNOSTICS v_overdraws = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'new_negative_inventory', v_negative_inventory,
    'new_negative_invoice_balance', v_negative_invoices,
    'new_stale_quote_holds', v_stale_holds,
    'new_booking_overdraws', v_overdraws
  );
END;
$$;


ALTER FUNCTION "public"."run_data_integrity_sweep"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_data_integrity_sweep"() IS 'Daily 06:45 UTC data-integrity sentinel: inserts one integrity_alerts row per NEW break (negative inventory beyond the H1 baseline, negative invoice balance, active hold on a terminal quote, booking overdraw). INSERT-only + partial-unique dedupe; never mutates business data.';



CREATE OR REPLACE FUNCTION "public"."run_morning_notification_checks"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Port of checkLowStockNotifications: one alert per active admin and product,
  -- with the same low_stock type and a rolling 24-hour per-recipient dedup.
  WITH low_stock_products AS (
    SELECT DISTINCT ON (p.id)
      p.id AS product_id,
      p.product_name,
      COALESCE(inv.quantity_available, 0) AS quantity_available,
      COALESCE(inv.reorder_point, 0) AS reorder_point
    FROM public.products p
    JOIN public.inventory inv ON inv.product_id = p.id
    WHERE p.is_active = true
      AND (
        (inv.reorder_point > 0 AND inv.quantity_available <= inv.reorder_point)
        OR inv.quantity_available < 0
      )
    ORDER BY p.id, COALESCE(inv.quantity_available, 0) ASC
  )
  INSERT INTO public.notifications (
    user_id, title, message, notification_type, related_entity_type, related_entity_id
  )
  SELECT
    admin.id,
    'Low Stock Alert',
    lsp.product_name || ' is low — ' || lsp.quantity_available
      || ' units available (reorder point: ' || lsp.reorder_point || ')',
    'low_stock',
    'product',
    lsp.product_id
  FROM low_stock_products lsp
  CROSS JOIN public.profiles admin
  WHERE admin.role = 'admin'
    AND admin.is_active = true
    AND NOT EXISTS (
      SELECT 1
      FROM public.notifications n
      WHERE n.related_entity_type = 'product'
        AND n.related_entity_id = lsp.product_id
        AND n.notification_type = 'low_stock'
        AND n.user_id = admin.id
        AND n.created_at >= now() - interval '24 hours'
    );

  -- Port of checkExpiringQuoteNotifications: sent/revised ad-hoc quotes only,
  -- with a same-day-inclusive date window, the same quote_expiring type, and a
  -- rolling 24-hour per-recipient dedup.
  WITH expiring_quotes AS (
    SELECT
      q.id AS quote_id,
      q.quote_number,
      q.created_by,
      q.expires_at,
      c.farm_name,
      (q.expires_at::date - CURRENT_DATE) AS days_left
    FROM public.quotes q
    JOIN public.customers c ON c.id = q.customer_id
    WHERE q.status IN ('sent', 'revised')
      AND q.is_planned = false
      AND q.deleted_at IS NULL
      AND q.expires_at::date BETWEEN CURRENT_DATE AND CURRENT_DATE + 7
  )
  INSERT INTO public.notifications (
    user_id, title, message, notification_type, related_entity_type, related_entity_id
  )
  SELECT
    eq.created_by,
    'Quote Expiring Soon',
    'Quote ' || eq.quote_number || ' for ' || eq.farm_name
      || ' expires in ' || eq.days_left || ' day'
      || CASE WHEN eq.days_left <> 1 THEN 's' ELSE '' END,
    'quote_expiring',
    'quote',
    eq.quote_id
  FROM expiring_quotes eq
  JOIN public.profiles creator ON creator.id = eq.created_by AND creator.is_active = true
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.notifications n
    WHERE n.related_entity_type = 'quote'
      AND n.related_entity_id = eq.quote_id
      AND n.notification_type = 'quote_expiring'
      AND n.user_id = eq.created_by
      AND n.created_at >= now() - interval '24 hours'
  );

  RETURN;
END;
$$;


ALTER FUNCTION "public"."run_morning_notification_checks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_weekly_db_backup"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_ts        timestamptz := now();
  v_tbl       text;
  v_tables    integer := 0;
  v_rows      bigint  := 0;
  v_failed    text[]  := '{}';
  v_succeeded boolean;
BEGIN
  FOR v_tbl IN
    SELECT tablename
    FROM pg_tables
    WHERE schemaname = 'public'
      AND tablename NOT IN ('backup_snapshots', 'backup_runs')
    ORDER BY tablename
  LOOP
    BEGIN
      EXECUTE format(
        'INSERT INTO public.backup_snapshots (taken_at, table_name, row_count, data) '
        'SELECT $1, $2, count(*)::int, COALESCE(jsonb_agg(to_jsonb(t.*)), ''[]''::jsonb) '
        'FROM public.%I t',
        v_tbl
      ) USING v_ts, v_tbl;
      v_tables := v_tables + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := array_append(v_failed, v_tbl || ': ' || SQLERRM);
    END;
  END LOOP;

  SELECT COALESCE(sum(row_count), 0)
    INTO v_rows
    FROM public.backup_snapshots
   WHERE taken_at = v_ts;

  v_succeeded := (array_length(v_failed, 1) IS NULL) AND v_tables > 0;

  INSERT INTO public.backup_runs (ran_at, tables_backed_up, rows_backed_up, failed, succeeded)
  VALUES (v_ts, v_tables, v_rows, to_jsonb(v_failed), v_succeeded);

  IF v_succeeded THEN
    DELETE FROM public.backup_snapshots
     WHERE taken_at < now() - interval '56 days';
    DELETE FROM public.backup_runs
     WHERE ran_at < now() - interval '56 days';
  END IF;

  RETURN json_build_object(
    'taken_at',  v_ts,
    'succeeded', v_succeeded,
    'tables',    v_tables,
    'rows',      v_rows,
    'failed',    to_jsonb(v_failed)
  );
END;
$_$;


ALTER FUNCTION "public"."run_weekly_db_backup"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."safe_cents_qty"("p_cents" bigint, "p_qty" numeric) RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT ROUND(COALESCE(p_cents, 0)::numeric * COALESCE(p_qty, 0))::bigint;
$$;


ALTER FUNCTION "public"."safe_cents_qty"("p_cents" bigint, "p_qty" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_blend_recipe"("p_recipe_id" "uuid", "p_name" "text", "p_recipe_type" "text", "p_items" "jsonb", "p_description" "text" DEFAULT NULL::"text", "p_crop_type" "text" DEFAULT NULL::"text", "p_timing" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor        uuid := auth.uid();
  v_recipe_id    uuid;
  v_existing     jsonb;
  v_result       jsonb;
  v_item         jsonb;
  v_item_count   int := 0;
  v_idx          int := 0;
  v_was_create   boolean := (p_recipe_id IS NULL);
  v_creator      uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_name IS NULL OR p_name = '' THEN RAISE EXCEPTION 'NAME_REQUIRED'; END IF;
  IF p_recipe_type NOT IN ('generic', 'crop_specific') THEN RAISE EXCEPTION 'RECIPE_TYPE_INVALID'; END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'ITEMS_INVALID';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'save_blend_recipe');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF v_was_create THEN
    INSERT INTO public.blend_recipes (
      name, description, recipe_type, crop_type, timing, created_by
    ) VALUES (
      trim(p_name), NULLIF(p_description, ''), p_recipe_type,
      CASE WHEN p_recipe_type = 'crop_specific' THEN NULLIF(p_crop_type, '') ELSE NULL END,
      CASE WHEN p_recipe_type = 'crop_specific' THEN NULLIF(p_timing, '') ELSE NULL END,
      v_actor
    )
    RETURNING id INTO v_recipe_id;
  ELSE
    SELECT created_by INTO v_creator FROM public.blend_recipes WHERE id = p_recipe_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'RECIPE_NOT_FOUND'; END IF;
    IF NOT (is_admin() OR v_creator = v_actor) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

    UPDATE public.blend_recipes SET
      name = trim(p_name),
      description = NULLIF(p_description, ''),
      recipe_type = p_recipe_type,
      crop_type = CASE WHEN p_recipe_type = 'crop_specific' THEN NULLIF(p_crop_type, '') ELSE NULL END,
      timing = CASE WHEN p_recipe_type = 'crop_specific' THEN NULLIF(p_timing, '') ELSE NULL END,
      updated_at = now()
    WHERE id = p_recipe_id;

    DELETE FROM public.blend_recipe_items WHERE recipe_id = p_recipe_id;
    v_recipe_id := p_recipe_id;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    IF (v_item->>'product_id') IS NULL THEN
      RAISE EXCEPTION 'ITEM_INVALID: product_id required';
    END IF;
    IF (v_item->>'quantity') IS NULL OR (v_item->>'quantity')::numeric <= 0 THEN
      RAISE EXCEPTION 'ITEM_INVALID: quantity must be > 0';
    END IF;
    -- >>> DELTA:recipe_price (Phase 4 bundle): validate the optional per-unit
    -- price (money is non-negative bigint cents; the column CHECK also enforces
    -- this, but we fail loud + early with a clear token).
    IF (v_item->>'price_per_unit_cents') IS NOT NULL
       AND (v_item->>'price_per_unit_cents')::bigint < 0 THEN
      RAISE EXCEPTION 'ITEM_INVALID: price_per_unit_cents must be >= 0';
    END IF;
    -- <<< DELTA:recipe_price

    INSERT INTO public.blend_recipe_items (
      recipe_id, product_id, product_name, quantity, unit,
      -- >>> DELTA:recipe_price: carry price_per_unit_cents so a set price is NOT
      -- wiped on edit/duplicate (live body omitted this column -> reset to 0).
      rate_per_acre, price_per_unit_cents, sort_order, notes
    ) VALUES (
      v_recipe_id,
      (v_item->>'product_id')::uuid,
      COALESCE(v_item->>'product_name', ''),
      (v_item->>'quantity')::numeric,
      COALESCE(NULLIF(v_item->>'unit', ''), 'gal'),
      NULLIF(v_item->>'rate_per_acre', '')::numeric,
      COALESCE((v_item->>'price_per_unit_cents')::bigint, 0),
      -- <<< DELTA:recipe_price
      v_idx,
      NULLIF(v_item->>'notes', '')
    );
    v_idx := v_idx + 1;
    v_item_count := v_item_count + 1;
  END LOOP;

  v_result := jsonb_build_object(
    'success', true, 'recipe_id', v_recipe_id,
    'created', v_was_create, 'item_count', v_item_count
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'save_blend_recipe', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."save_blend_recipe"("p_recipe_id" "uuid", "p_name" "text", "p_recipe_type" "text", "p_items" "jsonb", "p_description" "text", "p_crop_type" "text", "p_timing" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_blend_ticket"("p_ticket_id" "uuid", "p_ticket_payload" "jsonb", "p_products" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ticket public.blend_tickets%ROWTYPE;
  v_existing jsonb;
  v_result jsonb;
  v_actor uuid := auth.uid();
  v_effective_customer uuid;
  v_effective_job_id uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = v_actor
       AND is_active = true
       AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(
      p_idempotency_key,
      'save_blend_ticket'
    );
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_ticket
    FROM public.blend_tickets
   WHERE id = p_ticket_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Blend ticket not found: %', p_ticket_id;
  END IF;
  IF v_ticket.status = 'processing' THEN
    RAISE EXCEPTION 'BLEND_TICKET_OCR_PROCESSING';
  END IF;
  IF NULLIF(p_ticket_payload->>'_expected_updated_at', '') IS NULL THEN
    RAISE EXCEPTION 'BLEND_TICKET_EXPECTED_VERSION_REQUIRED';
  END IF;
  IF (p_ticket_payload->>'_expected_updated_at')::timestamptz
       IS DISTINCT FROM v_ticket.updated_at THEN
    RAISE EXCEPTION 'BLEND_TICKET_STALE_EDIT';
  END IF;

  v_effective_customer := CASE
    WHEN p_ticket_payload ? 'customer_id'
      THEN NULLIF(p_ticket_payload->>'customer_id', '')::uuid
    ELSE v_ticket.customer_id
  END;
  v_effective_job_id := CASE
    WHEN p_ticket_payload ? 'job_id'
      THEN NULLIF(p_ticket_payload->>'job_id', '')::uuid
    ELSE v_ticket.job_id
  END;
  IF v_effective_job_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.jobs j
     WHERE j.id = v_effective_job_id
       AND j.customer_id = v_effective_customer
  ) THEN
    RAISE EXCEPTION 'BLEND_JOB_CUSTOMER_MISMATCH';
  END IF;
  IF jsonb_typeof(p_products) IS DISTINCT FROM 'array'
     OR EXISTS (
       SELECT 1
         FROM jsonb_array_elements(p_products) AS product_row(product)
        WHERE jsonb_typeof(product) IS DISTINCT FROM 'object'
           OR NULLIF(product->>'id', '') IS NULL
  ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_PRODUCT_SNAPSHOT_INVALID';
  END IF;
  IF jsonb_array_length(p_products) > 200 THEN
    RAISE EXCEPTION 'BLEND_TICKET_PRODUCT_COUNT_INVALID';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_products) AS product_row(product)
     GROUP BY (product->>'id')::uuid
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_PRODUCT_SNAPSHOT_DUPLICATE';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_products) AS product_row(product)
      JOIN public.blend_ticket_products existing
        ON existing.id = (product->>'id')::uuid
     WHERE existing.blend_ticket_id <> p_ticket_id
  ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_PRODUCT_OWNERSHIP_MISMATCH';
  END IF;

  UPDATE public.blend_tickets SET
    customer_id = CASE WHEN p_ticket_payload ? 'customer_id'
      THEN NULLIF(p_ticket_payload->>'customer_id', '')::uuid ELSE customer_id END,
    ticket_date = CASE WHEN p_ticket_payload ? 'ticket_date'
      THEN NULLIF(p_ticket_payload->>'ticket_date', '')::date ELSE ticket_date END,
    ticket_time = CASE WHEN p_ticket_payload ? 'ticket_time'
      THEN NULLIF(p_ticket_payload->>'ticket_time', '') ELSE ticket_time END,
    job_number = CASE WHEN p_ticket_payload ? 'job_number'
      THEN NULLIF(p_ticket_payload->>'job_number', '') ELSE job_number END,
    invoice_number = CASE WHEN p_ticket_payload ? 'invoice_number'
      THEN NULLIF(p_ticket_payload->>'invoice_number', '') ELSE invoice_number END,
    driver_name = CASE WHEN p_ticket_payload ? 'driver_name'
      THEN NULLIF(p_ticket_payload->>'driver_name', '') ELSE driver_name END,
    applicator_name = CASE WHEN p_ticket_payload ? 'applicator_name'
      THEN NULLIF(p_ticket_payload->>'applicator_name', '') ELSE applicator_name END,
    mixer_name = CASE WHEN p_ticket_payload ? 'mixer_name'
      THEN NULLIF(p_ticket_payload->>'mixer_name', '') ELSE mixer_name END,
    tank_number = CASE WHEN p_ticket_payload ? 'tank_number'
      THEN NULLIF(p_ticket_payload->>'tank_number', '') ELSE tank_number END,
    vehicle_info = CASE WHEN p_ticket_payload ? 'vehicle_info'
      THEN NULLIF(p_ticket_payload->>'vehicle_info', '') ELSE vehicle_info END,
    field_names = CASE WHEN p_ticket_payload ? 'field_names'
      THEN NULLIF(p_ticket_payload->>'field_names', '') ELSE field_names END,
    total_acres = CASE WHEN p_ticket_payload ? 'total_acres'
      THEN NULLIF(p_ticket_payload->>'total_acres', '')::numeric ELSE total_acres END,
    application_rate = CASE WHEN p_ticket_payload ? 'application_rate'
      THEN NULLIF(p_ticket_payload->>'application_rate', '') ELSE application_rate END,
    total_volume = CASE WHEN p_ticket_payload ? 'total_volume'
      THEN NULLIF(p_ticket_payload->>'total_volume', '')::numeric ELSE total_volume END,
    total_volume_unit = CASE WHEN p_ticket_payload ? 'total_volume_unit'
      THEN NULLIF(p_ticket_payload->>'total_volume_unit', '') ELSE total_volume_unit END,
    notes = CASE WHEN p_ticket_payload ? 'notes'
      THEN NULLIF(p_ticket_payload->>'notes', '') ELSE notes END,
    job_id = CASE WHEN p_ticket_payload ? 'job_id'
      THEN NULLIF(p_ticket_payload->>'job_id', '')::uuid ELSE job_id END,
    application_service_id = CASE WHEN p_ticket_payload ? 'application_service_id'
      THEN NULLIF(p_ticket_payload->>'application_service_id', '')::uuid ELSE application_service_id END,
    manually_corrected_fields = ARRAY(
      SELECT DISTINCT touched.field_name
        FROM unnest(
          COALESCE(manually_corrected_fields, '{}'::text[])
          || ARRAY[
            CASE WHEN p_ticket_payload ? 'customer_id' THEN 'customer_id' END,
            CASE WHEN p_ticket_payload ? 'ticket_date' THEN 'ticket_date' END,
            CASE WHEN p_ticket_payload ? 'driver_name' THEN 'driver_name' END,
            CASE WHEN p_ticket_payload ? 'tank_number' THEN 'tank_number' END,
            CASE WHEN p_ticket_payload ? 'applicator_name' THEN 'applicator_name' END,
            CASE WHEN p_ticket_payload ? 'job_number' THEN 'job_number' END,
            CASE WHEN p_ticket_payload ? 'ticket_time' THEN 'ticket_time' END,
            CASE WHEN p_ticket_payload ? 'vehicle_info' THEN 'vehicle_info' END,
            CASE WHEN p_ticket_payload ? 'mixer_name' THEN 'mixer_name' END,
            CASE WHEN p_ticket_payload ? 'field_names' THEN 'field_names' END,
            CASE WHEN p_ticket_payload ? 'total_acres' THEN 'total_acres' END,
            CASE WHEN p_ticket_payload ? 'application_rate' THEN 'application_rate' END,
            CASE WHEN p_ticket_payload ? 'total_volume' THEN 'total_volume' END,
            CASE WHEN p_ticket_payload ? 'invoice_number' THEN 'invoice_number' END,
            CASE WHEN p_ticket_payload ? 'notes' THEN 'notes' END
          ]::text[]
        ) AS touched(field_name)
       WHERE touched.field_name IS NOT NULL
       ORDER BY touched.field_name
    ),
    updated_at = now()
  WHERE id = p_ticket_id;

  -- p_products is the complete editor snapshot. Add/remove stay local until
  -- this version-checked transaction, so a page never invalidates its own
  -- optimistic token and header + product changes commit as one unit.
  DELETE FROM public.blend_ticket_products btp
   WHERE btp.blend_ticket_id = p_ticket_id
     AND NOT EXISTS (
       SELECT 1
         FROM jsonb_array_elements(p_products) AS product_row(product)
        WHERE (product->>'id')::uuid = btp.id
     );

  UPDATE public.blend_ticket_products btp SET
    product_id = CASE WHEN prod ? 'product_id'
      THEN NULLIF(prod->>'product_id', '')::uuid ELSE btp.product_id END,
    product_name = COALESCE(NULLIF(prod->>'product_name', ''), btp.product_name),
    quantity = COALESCE(NULLIF(prod->>'quantity', '')::numeric, btp.quantity),
    unit = CASE WHEN prod ? 'unit' THEN NULLIF(prod->>'unit', '') ELSE btp.unit END,
    lot_number = CASE WHEN prod ? 'lot_number' THEN NULLIF(prod->>'lot_number', '') ELSE btp.lot_number END,
    rate_per_acre = CASE WHEN prod ? 'rate_per_acre'
      THEN NULLIF(prod->>'rate_per_acre', '')::numeric ELSE btp.rate_per_acre END,
    rate_per_acre_unit = CASE WHEN prod ? 'rate_per_acre_unit'
      THEN NULLIF(prod->>'rate_per_acre_unit', '') ELSE btp.rate_per_acre_unit END,
    sequence_order = product_row.ordinality::integer,
    manually_corrected = true
  FROM jsonb_array_elements(p_products) WITH ORDINALITY AS product_row(prod, ordinality)
  WHERE btp.id = (product_row.prod->>'id')::uuid
    AND btp.blend_ticket_id = p_ticket_id;

  INSERT INTO public.blend_ticket_products (
    id, blend_ticket_id, product_id, product_name, quantity, unit,
    lot_number, rate_per_acre, rate_per_acre_unit, sequence_order,
    confidence_score, manually_corrected
  )
  SELECT
    (product_row.prod->>'id')::uuid,
    p_ticket_id,
    NULLIF(product_row.prod->>'product_id', '')::uuid,
    COALESCE(product_row.prod->>'product_name', ''),
    COALESCE(NULLIF(product_row.prod->>'quantity', '')::numeric, 0),
    NULLIF(product_row.prod->>'unit', ''),
    NULLIF(product_row.prod->>'lot_number', ''),
    NULLIF(product_row.prod->>'rate_per_acre', '')::numeric,
    NULLIF(product_row.prod->>'rate_per_acre_unit', ''),
    product_row.ordinality::integer,
    0,
    true
  FROM jsonb_array_elements(p_products) WITH ORDINALITY AS product_row(prod, ordinality)
  WHERE NOT EXISTS (
    SELECT 1
      FROM public.blend_ticket_products existing
     WHERE existing.id = (product_row.prod->>'id')::uuid
  );

  INSERT INTO public.activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id
  ) VALUES (
    'blend_ticket_updated',
    'Blend ticket ' || COALESCE(v_ticket.ticket_number, '') || ' updated',
    v_actor, 'blend_ticket', p_ticket_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'ticket_id', p_ticket_id,
    'ticket_number', v_ticket.ticket_number
  );
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(
      p_idempotency_key,
      'save_blend_ticket',
      v_result
    );
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."save_blend_ticket"("p_ticket_id" "uuid", "p_ticket_payload" "jsonb", "p_products" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_blend_ticket_fields"("p_blend_ticket_id" "uuid", "p_fields" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_field jsonb;
  v_count integer := 0;
  v_existing text;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'save_blend_ticket_fields';
    IF v_existing IS NOT NULL THEN RETURN v_existing::jsonb; END IF;
  END IF;

  DELETE FROM blend_ticket_fields WHERE blend_ticket_id = p_blend_ticket_id;

  FOR v_field IN SELECT * FROM jsonb_array_elements(p_fields)
  LOOP
    INSERT INTO blend_ticket_fields (blend_ticket_id, field_id, customer_id, planned_acres, sort_order)
    VALUES (
      p_blend_ticket_id,
      (v_field->>'field_id')::uuid,
      (v_field->>'customer_id')::uuid,
      (v_field->>'planned_acres')::numeric,
      v_count
    );
    v_count := v_count + 1;
  END LOOP;

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'save_blend_ticket_fields', jsonb_build_object('fields_saved', v_count));
  END IF;

  RETURN jsonb_build_object('fields_saved', v_count);
END;
$$;


ALTER FUNCTION "public"."save_blend_ticket_fields"("p_blend_ticket_id" "uuid", "p_fields" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_customer"("p_customer_id" "uuid", "p_customer_payload" "jsonb", "p_addresses" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_actor_role text;
  v_customer_id uuid;
  v_is_new boolean := (p_customer_id IS NULL);
  v_incoming_ids uuid[];
  v_result jsonb;
  v_existing jsonb;
  v_cached_customer_id uuid;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_actor_role
  FROM profiles
  WHERE id = v_actor
    AND is_active = true
    AND role IN ('admin', 'sales_rep');
  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- Ownership gates run BEFORE the idempotency early-return (Codex P2, 2026-07-17):
  -- check_idempotency is not actor/customer-scoped, so a cached result must never
  -- be released to an actor the gates below would reject.
  IF v_actor_role <> 'admin' THEN
    IF v_is_new THEN
      -- Mirrors customers_insert WITH CHECK: a sales rep may only create
      -- customers assigned to themselves; NULL/absent is rejected too.
      IF (p_customer_payload->>'assigned_sales_rep')::uuid IS DISTINCT FROM v_actor THEN
        RAISE EXCEPTION 'REP_MUST_SELF_ASSIGN';
      END IF;
    ELSE
      -- Mirrors customers_update USING: non-admin actors may only update
      -- customers assigned to them. FOR UPDATE holds the row lock through the
      -- customer/address DML so a concurrent reassignment can't slip between
      -- this check and the UPDATE.
      IF NOT EXISTS (
        SELECT 1 FROM customers
        WHERE id = p_customer_id
          AND assigned_sales_rep = v_actor
        FOR UPDATE
      ) THEN
        RAISE EXCEPTION 'NOT_CUSTOMER_OWNER';
      END IF;
      -- Mirrors customers_update WITH CHECK: a rep may not hand the customer to
      -- someone else (absent key leaves the column untouched, which is fine).
      IF p_customer_payload ? 'assigned_sales_rep'
         AND (p_customer_payload->>'assigned_sales_rep')::uuid IS DISTINCT FROM v_actor THEN
        RAISE EXCEPTION 'REP_CANNOT_REASSIGN';
      END IF;
    END IF;
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'save_customer');
    IF v_existing IS NOT NULL THEN
      -- Bind the replay to the cached target (Codex r2, 2026-07-17):
      -- check_idempotency is scoped only by key+operation, so the cached result
      -- must name the same customer as this request and still pass ownership
      -- before it is released (same pattern as save_purchase_order's replay).
      v_cached_customer_id := NULLIF(v_existing->>'customer_id', '')::uuid;
      IF v_cached_customer_id IS NULL THEN
        RAISE EXCEPTION 'SAVE_CUSTOMER_RESULT_INVALID';
      END IF;
      IF p_customer_id IS NOT NULL
         AND p_customer_id IS DISTINCT FROM v_cached_customer_id THEN
        RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_CONFLICT';
      END IF;
      IF v_actor_role <> 'admin' AND NOT EXISTS (
        SELECT 1 FROM customers
        WHERE id = v_cached_customer_id
          AND assigned_sales_rep = v_actor
      ) THEN
        RAISE EXCEPTION 'NOT_CUSTOMER_OWNER';
      END IF;
      RETURN v_existing;
    END IF;
  END IF;

  IF p_customer_payload ? 'default_commission_split'
     AND p_customer_payload->'default_commission_split' IS NOT NULL
     AND p_customer_payload->'default_commission_split' <> 'null'::jsonb THEN
    PERFORM public.validate_commission_split_json(p_customer_payload->'default_commission_split');
  END IF;

  IF v_is_new THEN
    INSERT INTO customers (
      farm_name, contact_name, phone, email, billing_address,
      assigned_tier, assigned_sales_rep, total_acres, corn_acres,
      soybean_acres, other_acres, payment_terms,
      default_commission_split, notes, is_active,
      parent_customer_id, credit_limit_cents,
      finance_charge_rate, finance_charge_enabled, finance_charge_grace_days,
      default_application_service_id
    ) VALUES (
      p_customer_payload->>'farm_name',
      NULLIF(p_customer_payload->>'contact_name', ''),
      NULLIF(p_customer_payload->>'phone', ''),
      NULLIF(p_customer_payload->>'email', ''),
      NULLIF(p_customer_payload->>'billing_address', ''),
      COALESCE((p_customer_payload->>'assigned_tier')::integer, 1),
      (p_customer_payload->>'assigned_sales_rep')::uuid,
      (p_customer_payload->>'total_acres')::numeric,
      (p_customer_payload->>'corn_acres')::numeric,
      (p_customer_payload->>'soybean_acres')::numeric,
      (p_customer_payload->>'other_acres')::numeric,
      NULLIF(p_customer_payload->>'payment_terms', ''),
      CASE WHEN p_customer_payload ? 'default_commission_split'
        THEN (p_customer_payload->'default_commission_split') ELSE NULL END,
      NULLIF(p_customer_payload->>'notes', ''),
      COALESCE((p_customer_payload->>'is_active')::boolean, true),
      (p_customer_payload->>'parent_customer_id')::uuid,
      COALESCE((p_customer_payload->>'credit_limit_cents')::bigint, 0),
      COALESCE((p_customer_payload->>'finance_charge_rate')::numeric, 0),
      COALESCE((p_customer_payload->>'finance_charge_enabled')::boolean, true),
      COALESCE((p_customer_payload->>'finance_charge_grace_days')::integer, 0),
      (p_customer_payload->>'default_application_service_id')::uuid
    ) RETURNING id INTO v_customer_id;
  ELSE
    v_customer_id := p_customer_id;

    UPDATE customers SET
      farm_name = COALESCE(p_customer_payload->>'farm_name', farm_name),
      contact_name = CASE WHEN p_customer_payload ? 'contact_name' THEN NULLIF(p_customer_payload->>'contact_name', '') ELSE contact_name END,
      phone = CASE WHEN p_customer_payload ? 'phone' THEN NULLIF(p_customer_payload->>'phone', '') ELSE phone END,
      email = CASE WHEN p_customer_payload ? 'email' THEN NULLIF(p_customer_payload->>'email', '') ELSE email END,
      billing_address = CASE WHEN p_customer_payload ? 'billing_address' THEN NULLIF(p_customer_payload->>'billing_address', '') ELSE billing_address END,
      assigned_tier = CASE WHEN p_customer_payload ? 'assigned_tier' THEN COALESCE((p_customer_payload->>'assigned_tier')::integer, 1) ELSE assigned_tier END,
      assigned_sales_rep = CASE WHEN p_customer_payload ? 'assigned_sales_rep' THEN (p_customer_payload->>'assigned_sales_rep')::uuid ELSE assigned_sales_rep END,
      total_acres = CASE WHEN p_customer_payload ? 'total_acres' THEN (p_customer_payload->>'total_acres')::numeric ELSE total_acres END,
      corn_acres = CASE WHEN p_customer_payload ? 'corn_acres' THEN (p_customer_payload->>'corn_acres')::numeric ELSE corn_acres END,
      soybean_acres = CASE WHEN p_customer_payload ? 'soybean_acres' THEN (p_customer_payload->>'soybean_acres')::numeric ELSE soybean_acres END,
      other_acres = CASE WHEN p_customer_payload ? 'other_acres' THEN (p_customer_payload->>'other_acres')::numeric ELSE other_acres END,
      payment_terms = CASE WHEN p_customer_payload ? 'payment_terms' THEN NULLIF(p_customer_payload->>'payment_terms', '') ELSE payment_terms END,
      default_commission_split = CASE WHEN p_customer_payload ? 'default_commission_split' THEN (p_customer_payload->'default_commission_split') ELSE default_commission_split END,
      notes = CASE WHEN p_customer_payload ? 'notes' THEN NULLIF(p_customer_payload->>'notes', '') ELSE notes END,
      is_active = COALESCE((p_customer_payload->>'is_active')::boolean, is_active),
      parent_customer_id = CASE WHEN p_customer_payload ? 'parent_customer_id' THEN (p_customer_payload->>'parent_customer_id')::uuid ELSE parent_customer_id END,
      credit_limit_cents = CASE WHEN p_customer_payload ? 'credit_limit_cents' THEN COALESCE((p_customer_payload->>'credit_limit_cents')::bigint, 0) ELSE credit_limit_cents END,
      finance_charge_rate = CASE WHEN p_customer_payload ? 'finance_charge_rate' THEN COALESCE((p_customer_payload->>'finance_charge_rate')::numeric, 0) ELSE finance_charge_rate END,
      finance_charge_enabled = CASE WHEN p_customer_payload ? 'finance_charge_enabled' THEN COALESCE((p_customer_payload->>'finance_charge_enabled')::boolean, true) ELSE finance_charge_enabled END,
      finance_charge_grace_days = CASE WHEN p_customer_payload ? 'finance_charge_grace_days' THEN COALESCE((p_customer_payload->>'finance_charge_grace_days')::integer, 0) ELSE finance_charge_grace_days END,
      default_application_service_id = CASE WHEN p_customer_payload ? 'default_application_service_id' THEN (p_customer_payload->>'default_application_service_id')::uuid ELSE default_application_service_id END,
      updated_at = now()
    WHERE id = v_customer_id;

    IF NOT FOUND THEN RAISE EXCEPTION 'CUSTOMER_NOT_FOUND'; END IF;

    SELECT array_agg((addr->>'id')::uuid) INTO v_incoming_ids
    FROM jsonb_array_elements(COALESCE(p_addresses, '[]'::jsonb)) AS addr
    WHERE addr->>'id' IS NOT NULL;

    DELETE FROM customer_addresses ca
    WHERE ca.customer_id = v_customer_id
      AND (v_incoming_ids IS NULL OR ca.id != ALL(v_incoming_ids))
      AND NOT EXISTS (SELECT 1 FROM deliveries d WHERE d.delivery_address_id = ca.id);
  END IF;

  IF p_addresses IS NOT NULL AND jsonb_array_length(p_addresses) > 0 THEN
    UPDATE customer_addresses ca SET
      label = COALESCE(addr->>'label', ''),
      address_line = NULLIF(addr->>'address_line', ''),
      city = NULLIF(addr->>'city', ''),
      state = NULLIF(addr->>'state', ''),
      zip = NULLIF(addr->>'zip', ''),
      delivery_notes = NULLIF(addr->>'delivery_notes', ''),
      is_default = COALESCE((addr->>'is_default')::boolean, false)
    FROM jsonb_array_elements(p_addresses) AS addr
    WHERE ca.id = (addr->>'id')::uuid AND ca.customer_id = v_customer_id;

    INSERT INTO customer_addresses (
      customer_id, label, address_line, city, state, zip, delivery_notes, is_default
    )
    SELECT
      v_customer_id,
      COALESCE(addr->>'label', ''),
      NULLIF(addr->>'address_line', ''),
      NULLIF(addr->>'city', ''),
      NULLIF(addr->>'state', ''),
      NULLIF(addr->>'zip', ''),
      NULLIF(addr->>'delivery_notes', ''),
      COALESCE((addr->>'is_default')::boolean, false)
    FROM jsonb_array_elements(p_addresses) AS addr
    WHERE addr->>'id' IS NULL
      AND (COALESCE(addr->>'label', '') != '' OR COALESCE(addr->>'address_line', '') != '');
  END IF;

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type,
    related_entity_id,
    customer_id
  ) VALUES (
    CASE WHEN v_is_new THEN 'customer_created' ELSE 'customer_updated' END,
    CASE WHEN v_is_new
      THEN 'Customer ' || COALESCE(p_customer_payload->>'farm_name', '') || ' created'
      ELSE 'Customer ' || COALESCE(p_customer_payload->>'farm_name', '') || ' updated'
    END,
    v_actor, 'customer', v_customer_id, v_customer_id
  );

  v_result := jsonb_build_object('status', 'saved', 'customer_id', v_customer_id);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'save_customer', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."save_customer"("p_customer_id" "uuid", "p_customer_payload" "jsonb", "p_addresses" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_field"("p_field_id" "uuid", "p_field_payload" "jsonb", "p_billing_defaults" "jsonb" DEFAULT '[]'::"jsonb", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_field_id uuid;
  v_total_pct numeric;
  v_existing jsonb;
BEGIN
  PERFORM require_admin_or_sales_rep();
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'save_field');
    IF v_existing IS NOT NULL THEN RETURN (v_existing->>'field_id')::uuid; END IF;
  END IF;
  IF jsonb_array_length(p_billing_defaults) > 0 THEN
    SELECT COALESCE(SUM((elem->>'split_pct')::numeric), 0) INTO v_total_pct
    FROM jsonb_array_elements(p_billing_defaults) AS elem;
    IF ABS(v_total_pct - 100) > 0.01 THEN
      RAISE EXCEPTION 'Billing splits must total 100%% (got %.2f%%)', v_total_pct;
    END IF;
  END IF;
  IF p_field_id IS NULL THEN
    INSERT INTO fields (
      customer_id, field_name, legal_description, county, state,
      total_acres, fsa_farm_number, fsa_tract_number, fsa_field_number,
      crop_type, soil_type, irrigation, notes, is_active
    )
    SELECT
      (p_field_payload->>'customer_id')::uuid,
      p_field_payload->>'field_name',
      p_field_payload->>'legal_description',
      p_field_payload->>'county',
      COALESCE(p_field_payload->>'state', 'IL'),
      (p_field_payload->>'total_acres')::numeric,
      p_field_payload->>'fsa_farm_number',
      p_field_payload->>'fsa_tract_number',
      p_field_payload->>'fsa_field_number',
      p_field_payload->>'crop_type',
      p_field_payload->>'soil_type',
      COALESCE((p_field_payload->>'irrigation')::boolean, false),
      p_field_payload->>'notes',
      COALESCE((p_field_payload->>'is_active')::boolean, true)
    RETURNING id INTO v_field_id;
  ELSE
    UPDATE fields SET
      customer_id = (p_field_payload->>'customer_id')::uuid,
      field_name = p_field_payload->>'field_name',
      legal_description = p_field_payload->>'legal_description',
      county = p_field_payload->>'county',
      state = COALESCE(p_field_payload->>'state', 'IL'),
      total_acres = (p_field_payload->>'total_acres')::numeric,
      fsa_farm_number = p_field_payload->>'fsa_farm_number',
      fsa_tract_number = p_field_payload->>'fsa_tract_number',
      fsa_field_number = p_field_payload->>'fsa_field_number',
      crop_type = p_field_payload->>'crop_type',
      soil_type = p_field_payload->>'soil_type',
      irrigation = COALESCE((p_field_payload->>'irrigation')::boolean, false),
      notes = p_field_payload->>'notes',
      is_active = COALESCE((p_field_payload->>'is_active')::boolean, true)
    WHERE id = p_field_id;
    v_field_id := p_field_id;
  END IF;
  DELETE FROM field_billing_defaults WHERE field_id = v_field_id;
  IF jsonb_array_length(p_billing_defaults) > 0 THEN
    INSERT INTO field_billing_defaults (
      field_id, customer_id, split_pct, is_primary, notes,
      price_override_cents, pricing_note
    )
    SELECT
      v_field_id,
      (elem->>'customer_id')::uuid,
      (elem->>'split_pct')::numeric,
      COALESCE((elem->>'is_primary')::boolean, false),
      elem->>'notes',
      (elem->>'price_override_cents')::bigint,
      elem->>'pricing_note'
    FROM jsonb_array_elements(p_billing_defaults) AS elem;
  END IF;
  IF p_performed_by IS NOT NULL THEN
    INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id)
    VALUES ('field_saved', 'Field saved: ' || (p_field_payload->>'field_name'), p_performed_by, 'field', v_field_id);
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'save_field', jsonb_build_object('field_id', v_field_id));
  END IF;
  RETURN v_field_id;
END;
$$;


ALTER FUNCTION "public"."save_field"("p_field_id" "uuid", "p_field_payload" "jsonb", "p_billing_defaults" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_field_app_invoice"("p_invoice_id" "uuid", "p_invoice" "jsonb", "p_locations" "jsonb", "p_chemicals" "jsonb", "p_performed_by" "uuid", "p_application_service_id" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_initial_group_id uuid;
  v_locked_group_id uuid;
  v_locked_status text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE id = v_actor
      AND is_active = true
      AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'Not authorized: active admin or sales role required to save field application invoices';
  END IF;

  -- This acquires the shared transaction-scoped advisory lock before any invoice
  -- row is touched. A retry that already completed returns without being rejected
  -- merely because the invoice was posted after the original save committed.
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(
      p_idempotency_key,
      'save_field_app_invoice'
    );
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  IF p_invoice_id IS NOT NULL THEN
    SELECT invoice_group_id
      INTO v_initial_group_id
    FROM public.invoices
    WHERE id = p_invoice_id
      AND deleted_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Invoice not found: %', p_invoice_id;
    END IF;

    -- Use the same row-lock boundary as post_invoice/post_invoice_group. Once this
    -- returns, a concurrent post has either completed (and is rejected below) or
    -- must wait until the complete save transaction finishes.
    IF v_initial_group_id IS NOT NULL THEN
      -- A row UUID is not a stable group anchor: a concurrent insert can create a
      -- lower UUID. Serialize every group save/post on the immutable group ID first.
      PERFORM pg_advisory_xact_lock(hashtextextended(v_initial_group_id::text, 0));

      -- Lock one stable member first, then acquire the full set in a NEW statement.
      -- Under READ COMMITTED, a one-statement multi-row lock keeps its pre-wait
      -- snapshot and can miss a sibling created by the transaction it waited for.
      -- The anchor wait ends first; the fresh second statement then sees and locks
      -- every current sibling. post_invoice_group uses the identical order below.
      PERFORM 1
      FROM public.invoices
      WHERE invoice_group_id = v_initial_group_id
        AND deleted_at IS NULL
      ORDER BY id
      LIMIT 1
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Invoice group changed while saving; reload and try again';
      END IF;

      PERFORM 1
      FROM public.invoices
      WHERE invoice_group_id = v_initial_group_id
        AND deleted_at IS NULL
      ORDER BY id
      FOR UPDATE;
    ELSE
      PERFORM 1
      FROM public.invoices
      WHERE id = p_invoice_id
        AND deleted_at IS NULL
      FOR UPDATE;
    END IF;

    SELECT status, invoice_group_id
      INTO v_locked_status, v_locked_group_id
    FROM public.invoices
    WHERE id = p_invoice_id
      AND deleted_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Invoice not found: %', p_invoice_id;
    END IF;
    IF v_locked_group_id IS DISTINCT FROM v_initial_group_id THEN
      RAISE EXCEPTION 'Invoice group changed while saving; reload and try again';
    END IF;
    IF v_locked_status NOT IN ('draft', 'unposted') THEN
      RAISE EXCEPTION 'Cannot edit field app invoice with status: %', v_locked_status;
    END IF;
    IF v_locked_group_id IS NOT NULL AND EXISTS (
      SELECT 1
      FROM public.invoices
      WHERE invoice_group_id = v_locked_group_id
        AND deleted_at IS NULL
        AND status NOT IN ('draft', 'unposted')
    ) THEN
      RAISE EXCEPTION 'Cannot edit field app invoice group after any member is posted or voided';
    END IF;
  END IF;

  RETURN public._save_field_app_invoice_impl_20260714(
    p_invoice_id,
    p_invoice,
    p_locations,
    p_chemicals,
    v_actor,
    p_application_service_id,
    p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."save_field_app_invoice"("p_invoice_id" "uuid", "p_invoice" "jsonb", "p_locations" "jsonb", "p_chemicals" "jsonb", "p_performed_by" "uuid", "p_application_service_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_field_app_invoice"("p_invoice_id" "uuid", "p_invoice" "jsonb", "p_locations" "jsonb", "p_chemicals" "jsonb", "p_performed_by" "uuid", "p_application_service_id" "uuid", "p_idempotency_key" "text") IS 'Saves a field-application invoice after locking and rechecking the target invoice or split group so save and post cannot race.';



CREATE OR REPLACE FUNCTION "public"."save_field_crop_history"("p_field_id" "uuid", "p_season" integer, "p_crop_type" "text", "p_variety" "text" DEFAULT NULL::"text", "p_planting_date" "date" DEFAULT NULL::"date", "p_harvest_date" "date" DEFAULT NULL::"date", "p_yield_per_acre" numeric DEFAULT NULL::numeric, "p_yield_unit" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor        uuid;
  v_season       integer;
  v_id           uuid;
  v_idemp        jsonb;
  v_result       jsonb;
BEGIN
  -- strict-actor (canonical) --------------------------------------------------
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- idempotency replay --------------------------------------------------------
  IF p_idempotency_key IS NOT NULL THEN
    v_idemp := check_idempotency(p_idempotency_key, 'save_field_crop_history');
    IF v_idemp IS NOT NULL THEN RETURN v_idemp; END IF;
  END IF;

  -- validate inputs -----------------------------------------------------------
  IF NOT EXISTS (SELECT 1 FROM fields WHERE id = p_field_id) THEN
    RAISE EXCEPTION 'FIELD_NOT_FOUND';
  END IF;
  IF p_crop_type IS NULL OR btrim(p_crop_type) = '' THEN
    RAISE EXCEPTION 'CROP_TYPE_REQUIRED';
  END IF;

  -- season: explicit if provided, else derive from planting date / today ------
  v_season := COALESCE(p_season, compute_season(COALESCE(p_planting_date, CURRENT_DATE)));

  -- upsert on the (field_id, season) unique index -----------------------------
  INSERT INTO field_crop_history (
    field_id, season, crop_type, variety, planting_date, harvest_date,
    yield_per_acre, yield_unit, notes
  ) VALUES (
    p_field_id, v_season, btrim(p_crop_type), p_variety, p_planting_date, p_harvest_date,
    p_yield_per_acre, p_yield_unit, p_notes
  )
  ON CONFLICT (field_id, season) DO UPDATE SET
    crop_type      = EXCLUDED.crop_type,
    variety        = EXCLUDED.variety,
    planting_date  = EXCLUDED.planting_date,
    harvest_date   = EXCLUDED.harvest_date,
    yield_per_acre = EXCLUDED.yield_per_acre,
    yield_unit     = EXCLUDED.yield_unit,
    notes          = EXCLUDED.notes
  RETURNING id INTO v_id;

  v_result := jsonb_build_object('success', true, 'id', v_id, 'season', v_season);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'save_field_crop_history', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."save_field_crop_history"("p_field_id" "uuid", "p_season" integer, "p_crop_type" "text", "p_variety" "text", "p_planting_date" "date", "p_harvest_date" "date", "p_yield_per_acre" numeric, "p_yield_unit" "text", "p_notes" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_field_geometry"("p_field_id" "uuid", "p_centroid_geojson" "text" DEFAULT NULL::"text", "p_boundary_geojson" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_existing jsonb;
BEGIN
  PERFORM require_admin_or_sales_rep();
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'save_field_geometry');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;
  UPDATE fields SET
    centroid = CASE
      WHEN p_centroid_geojson IS NOT NULL THEN ST_GeomFromGeoJSON(p_centroid_geojson)::geography -- FIELD_GEO_42883_DELTA G1
      ELSE centroid
    END,
    boundary = CASE
      WHEN p_boundary_geojson IS NOT NULL THEN ST_GeomFromGeoJSON(p_boundary_geojson)::geography -- FIELD_GEO_42883_DELTA G2
      ELSE boundary
    END,
    updated_at = now()
  WHERE id = p_field_id;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'save_field_geometry', '{}'::jsonb);
  END IF;
END;
$$;


ALTER FUNCTION "public"."save_field_geometry"("p_field_id" "uuid", "p_centroid_geojson" "text", "p_boundary_geojson" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_field_polygons"("p_field_id" "uuid", "p_polygons" "jsonb", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_existing jsonb; v_poly jsonb; v_total_acres numeric := 0; v_first_geojson jsonb;
BEGIN
  PERFORM require_admin_or_sales_rep();
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'save_field_polygons');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;
  DELETE FROM field_polygons WHERE field_id = p_field_id;
  FOR v_poly IN SELECT * FROM jsonb_array_elements(p_polygons) LOOP
    INSERT INTO field_polygons (field_id, polygon_geojson, label, acres, sort_order)
    VALUES (p_field_id, v_poly->'polygon_geojson', v_poly->>'label', (v_poly->>'acres')::numeric, COALESCE((v_poly->>'sort_order')::int, 0));
    v_total_acres := v_total_acres + COALESCE((v_poly->>'acres')::numeric, 0);
  END LOOP;
  UPDATE fields SET total_acres = v_total_acres, updated_at = now() WHERE id = p_field_id;
  SELECT polygon_geojson INTO v_first_geojson FROM field_polygons WHERE field_id = p_field_id ORDER BY sort_order LIMIT 1;
  IF v_first_geojson IS NOT NULL THEN
    -- FIELD_GEO_42883_DELTA P1+P2 BEGIN (both PostGIS calls on the next line)
    UPDATE fields SET boundary = ST_GeomFromGeoJSON(v_first_geojson::text)::geography, centroid = ST_Centroid(ST_GeomFromGeoJSON(v_first_geojson::text))::geography, updated_at = now() WHERE id = p_field_id;
    -- FIELD_GEO_42883_DELTA P1+P2 END
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'save_field_polygons', '{}'::jsonb);
  END IF;
END; $$;


ALTER FUNCTION "public"."save_field_polygons"("p_field_id" "uuid", "p_polygons" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_idempotency"("p_key" "text", "p_operation" "text", "p_result" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing_op text;
BEGIN
  IF p_key IS NULL OR btrim(p_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;
  IF p_operation IS NULL OR btrim(p_operation) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_OPERATION_REQUIRED';
  END IF;

  SELECT operation INTO v_existing_op
  FROM public.idempotency_keys
  WHERE idempotency_key = p_key
    AND operation <> p_operation
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'IDEMPOTENCY_CROSS_OP_KEY_REUSE: idempotency_key % is already in use for operation %; cannot reuse it for operation %',
      p_key, v_existing_op, p_operation;
  END IF;

  INSERT INTO public.idempotency_keys (idempotency_key, operation, result)
  VALUES (p_key, p_operation, p_result)
  ON CONFLICT (idempotency_key) DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."save_idempotency"("p_key" "text", "p_operation" "text", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_invoice"("p_invoice" "jsonb", "p_items" "jsonb" DEFAULT '[]'::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice_id uuid := NULLIF(p_invoice->>'id', '')::uuid;
  v_saved_id   uuid;
  v_governed   boolean := false;
BEGIN
  IF v_invoice_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
        FROM public.split_invoice_provenance p
       WHERE p.invoice_id = v_invoice_id
    ) INTO v_governed;
  END IF;

  IF v_governed THEN
    INSERT INTO public.split_invoice_mutation_claims (
      transaction_id, invoice_id, operation
    ) VALUES (
      pg_current_xact_id(), v_invoice_id, 'save_invoice'
    );
  END IF;

  v_saved_id := public._save_invoice_split_provenance_impl_20260719(
    p_invoice,
    p_items,
    p_idempotency_key
  );

  IF v_governed THEN
    IF v_saved_id IS DISTINCT FROM v_invoice_id THEN
      RAISE EXCEPTION 'SPLIT_INVOICE_SAVE_IDENTITY_MISMATCH';
    END IF;

    UPDATE public.split_invoice_provenance p
       SET total_amount_cents = i.total_amount_cents,
           content_claim = public._split_invoice_content_claim(i.id)
      FROM public.invoices i
     WHERE p.invoice_id = v_saved_id
       AND i.id = p.invoice_id
       AND p.order_id = i.order_id
       AND p.invoice_group_id = i.invoice_group_id
       AND p.customer_id = i.customer_id
       AND p.invoice_type = i.invoice_type
       AND p.season = i.season;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'SPLIT_INVOICE_PROVENANCE_REFRESH_FAILED';
    END IF;

    DELETE FROM public.split_invoice_mutation_claims
     WHERE transaction_id = pg_current_xact_id()
       AND invoice_id = v_invoice_id
       AND operation = 'save_invoice';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'SPLIT_INVOICE_MUTATION_CLAIM_LOST';
    END IF;
  END IF;

  RETURN v_saved_id;
END;
$$;


ALTER FUNCTION "public"."save_invoice"("p_invoice" "jsonb", "p_items" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_job"("p_job_id" "uuid", "p_job_payload" "jsonb", "p_fields" "jsonb", "p_chemicals" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_job_id uuid;
  v_is_new boolean := (p_job_id IS NULL);
  v_field jsonb;
  v_chem jsonb;
  v_share jsonb;
  v_field_id uuid;
  v_season integer;
  v_job_date date;
  v_existing jsonb;
  v_result jsonb;
  v_share_total numeric;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true
      AND role IN ('admin', 'sales_rep')
  ) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  -- Idempotency: replay with the same key returns the original result without
  -- creating a second job (the create-path double-submit hazard).
  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key
       AND operation = 'save_job';
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  v_job_date := (p_job_payload->>'job_date')::date;
  -- U3 (Codex R2 P2): the live body used a JULY season cutoff (>= 7) while the
  -- system canon is Oct 1 (CLAUDE.md; create_job_from_quote_section and
  -- allocate_payment both use >= 10). transfer_job_to_invoice passes jobs.season
  -- to compute_application_service_fee for customer-specific rates, so a
  -- Jul-Sep job stamped into next season would look up the WRONG season's rate.
  -- Use the canonical live helper.
  v_season := compute_season(v_job_date);

  IF v_is_new THEN
    INSERT INTO jobs (
      job_number, customer_id, status, job_date, scheduled_time,
      applicator_id, vehicle_id, recipe_id, application_service_id,
      notes, tags, batch_id, season,
      total_acres, total_cost_cents, total_price_cents,
      call_date, date_proposed, time_proposed, schedule_date, date_expires,
      consultant_id, loader_comment, additional_info, internal_memo,
      created_by, updated_by
    ) VALUES (
      next_job_number(),
      (p_job_payload->>'customer_id')::uuid,
      COALESCE(p_job_payload->>'status', 'scheduled'),
      v_job_date,
      CASE WHEN p_job_payload->>'scheduled_time' IS NOT NULL
        THEN (p_job_payload->>'scheduled_time')::time ELSE NULL END,
      CASE WHEN p_job_payload->>'applicator_id' IS NOT NULL AND p_job_payload->>'applicator_id' != ''
        THEN (p_job_payload->>'applicator_id')::uuid ELSE NULL END,
      CASE WHEN p_job_payload->>'vehicle_id' IS NOT NULL AND p_job_payload->>'vehicle_id' != ''
        THEN (p_job_payload->>'vehicle_id')::uuid ELSE NULL END,
      CASE WHEN p_job_payload->>'recipe_id' IS NOT NULL AND p_job_payload->>'recipe_id' != ''
        THEN (p_job_payload->>'recipe_id')::uuid ELSE NULL END,
      CASE WHEN p_job_payload->>'application_service_id' IS NOT NULL AND p_job_payload->>'application_service_id' != ''
        THEN (p_job_payload->>'application_service_id')::uuid ELSE NULL END,
      p_job_payload->>'notes',
      CASE WHEN p_job_payload->'tags' IS NOT NULL
        THEN ARRAY(SELECT jsonb_array_elements_text(p_job_payload->'tags'))
        ELSE NULL END,
      p_job_payload->>'batch_id',
      v_season,
      COALESCE((p_job_payload->>'total_acres')::numeric, 0),
      COALESCE((p_job_payload->>'total_cost_cents')::bigint, 0),
      COALESCE((p_job_payload->>'total_price_cents')::bigint, 0),
      NULLIF(p_job_payload->>'call_date','')::date,
      NULLIF(p_job_payload->>'date_proposed','')::date,
      NULLIF(p_job_payload->>'time_proposed','')::time,
      NULLIF(p_job_payload->>'schedule_date','')::date,
      NULLIF(p_job_payload->>'date_expires','')::date,
      CASE WHEN p_job_payload->>'consultant_id' IS NOT NULL AND p_job_payload->>'consultant_id' != ''
        THEN (p_job_payload->>'consultant_id')::uuid ELSE NULL END,
      p_job_payload->>'loader_comment',
      p_job_payload->>'additional_info',
      p_job_payload->>'internal_memo',
      p_performed_by,
      v_actor
    )
    RETURNING id INTO v_job_id;
  ELSE
    SELECT id INTO v_job_id FROM jobs WHERE id = p_job_id FOR UPDATE;
    IF v_job_id IS NULL THEN
      RAISE EXCEPTION 'Job not found: %', p_job_id;
    END IF;

    UPDATE jobs SET
      customer_id = (p_job_payload->>'customer_id')::uuid,
      job_date = v_job_date,
      scheduled_time = CASE WHEN p_job_payload->>'scheduled_time' IS NOT NULL
        THEN (p_job_payload->>'scheduled_time')::time ELSE NULL END,
      applicator_id = CASE WHEN p_job_payload->>'applicator_id' IS NOT NULL AND p_job_payload->>'applicator_id' != ''
        THEN (p_job_payload->>'applicator_id')::uuid ELSE NULL END,
      vehicle_id = CASE WHEN p_job_payload->>'vehicle_id' IS NOT NULL AND p_job_payload->>'vehicle_id' != ''
        THEN (p_job_payload->>'vehicle_id')::uuid ELSE NULL END,
      recipe_id = CASE WHEN p_job_payload->>'recipe_id' IS NOT NULL AND p_job_payload->>'recipe_id' != ''
        THEN (p_job_payload->>'recipe_id')::uuid ELSE NULL END,
      -- U3 (Codex R3 P2): three-way — key ABSENT (stale/cached client on the old
      -- payload shape) preserves the saved service; key present-but-empty is an
      -- explicit clear; a uuid sets it. Prevents an old client's ordinary save
      -- from silently wiping a billing-impacting field.
      application_service_id = CASE
        WHEN NOT (p_job_payload ? 'application_service_id') THEN application_service_id
        WHEN p_job_payload->>'application_service_id' IS NOT NULL AND p_job_payload->>'application_service_id' != ''
          THEN (p_job_payload->>'application_service_id')::uuid
        ELSE NULL END,
      notes = p_job_payload->>'notes',
      tags = CASE WHEN p_job_payload->'tags' IS NOT NULL
        THEN ARRAY(SELECT jsonb_array_elements_text(p_job_payload->'tags'))
        ELSE NULL END,
      batch_id = p_job_payload->>'batch_id',
      season = v_season,
      total_acres = COALESCE((p_job_payload->>'total_acres')::numeric, 0),
      total_cost_cents = COALESCE((p_job_payload->>'total_cost_cents')::bigint, 0),
      total_price_cents = COALESCE((p_job_payload->>'total_price_cents')::bigint, 0),
      call_date = NULLIF(p_job_payload->>'call_date','')::date,
      date_proposed = NULLIF(p_job_payload->>'date_proposed','')::date,
      time_proposed = NULLIF(p_job_payload->>'time_proposed','')::time,
      schedule_date = NULLIF(p_job_payload->>'schedule_date','')::date,
      date_expires = NULLIF(p_job_payload->>'date_expires','')::date,
      consultant_id = CASE WHEN p_job_payload->>'consultant_id' IS NOT NULL AND p_job_payload->>'consultant_id' != ''
        THEN (p_job_payload->>'consultant_id')::uuid ELSE NULL END,
      loader_comment = p_job_payload->>'loader_comment',
      additional_info = p_job_payload->>'additional_info',
      internal_memo = p_job_payload->>'internal_memo',
      updated_by = v_actor
    WHERE id = v_job_id;
  END IF;

  -- Replace fields (now incl. agronomy: planted_acres, crop, strip, pests)
  DELETE FROM job_fields WHERE job_id = v_job_id;
  FOR v_field IN SELECT * FROM jsonb_array_elements(p_fields) LOOP
    INSERT INTO job_fields (job_id, field_id, acres_to_treat, planted_acres, crop, strip, pests, sort_order)
    VALUES (
      v_job_id,
      (v_field->>'field_id')::uuid,
      (v_field->>'acres_to_treat')::numeric,
      NULLIF(v_field->>'planted_acres','')::numeric,
      v_field->>'crop',
      v_field->>'strip',
      v_field->>'pests',
      COALESCE((v_field->>'sort_order')::integer, 0)
    );
  END LOOP;

  -- Replace per-field customer shares. Each field's shares must total 100%
  -- (mirrors the field-app split invariant so section #26 can split cleanly).
  -- A share whose field_id is NOT one of the job's fields (a stale defaults
  -- response or a hand-built payload) is REJECTED — otherwise the Jobs list /
  -- the #26 split would surface a customer/field that is not on the job (Codex P2).
  DELETE FROM job_field_shares WHERE job_id = v_job_id;
  IF p_job_payload->'field_shares' IS NOT NULL THEN
    -- Reject any share pointing at a field not in p_fields.
    IF EXISTS (
      SELECT 1
        FROM jsonb_array_elements(p_job_payload->'field_shares') s
       WHERE (s->>'field_id')::uuid NOT IN (
         SELECT (f->>'field_id')::uuid FROM jsonb_array_elements(p_fields) f
       )
    ) THEN
      RAISE EXCEPTION 'SHARE_FIELD_NOT_ON_JOB';
    END IF;

    -- Validate: per field, the sum of split_pct == 100 (within rounding).
    FOR v_field_id IN
      SELECT DISTINCT (s->>'field_id')::uuid
      FROM jsonb_array_elements(p_job_payload->'field_shares') s
    LOOP
      SELECT COALESCE(SUM((s->>'split_pct')::numeric), 0)
        INTO v_share_total
        FROM jsonb_array_elements(p_job_payload->'field_shares') s
       WHERE (s->>'field_id')::uuid = v_field_id;
      IF ROUND(v_share_total, 2) <> 100 THEN
        RAISE EXCEPTION 'SHARE_NOT_100' USING DETAIL = 'Field shares must total 100%; got ' || v_share_total;
      END IF;
    END LOOP;

    FOR v_share IN SELECT * FROM jsonb_array_elements(p_job_payload->'field_shares') LOOP
      INSERT INTO job_field_shares (job_id, field_id, customer_id, split_pct, is_primary)
      VALUES (
        v_job_id,
        (v_share->>'field_id')::uuid,
        (v_share->>'customer_id')::uuid,
        (v_share->>'split_pct')::numeric,
        COALESCE((v_share->>'is_primary')::boolean, false)
      );
    END LOOP;
  END IF;

  -- Replace chemicals (now incl. extras: diluent_rate, rei_hours, phi_days,
  -- warehouse, vendor)
  DELETE FROM job_chemicals WHERE job_id = v_job_id;
  FOR v_chem IN SELECT * FROM jsonb_array_elements(p_chemicals) LOOP
    INSERT INTO job_chemicals (
      job_id, product_id, quantity, unit, rate_per_acre, rate_unit,
      cost_per_unit_cents, price_per_unit_cents,
      diluent_rate, rei_hours, phi_days, warehouse, vendor, customer_supplied,
      sort_order
    )
    VALUES (
      v_job_id,
      (v_chem->>'product_id')::uuid,
      COALESCE((v_chem->>'quantity')::numeric, 0),
      v_chem->>'unit',
      (v_chem->>'rate_per_acre')::numeric,
      v_chem->>'rate_unit',
      COALESCE((v_chem->>'cost_per_unit_cents')::bigint, 0),
      COALESCE((v_chem->>'price_per_unit_cents')::bigint, 0),
      NULLIF(v_chem->>'diluent_rate','')::numeric,
      NULLIF(v_chem->>'rei_hours','')::integer,
      NULLIF(v_chem->>'phi_days','')::integer,
      v_chem->>'warehouse',
      v_chem->>'vendor',
      -- U4<<< customer-supplied product: applied but not drawn/deducted/billed. (#53/#54)
      COALESCE((v_chem->>'customer_supplied')::boolean, false),
      -- >>>U4
      COALESCE((v_chem->>'sort_order')::integer, 0)
    );
  END LOOP;

  v_result := jsonb_build_object('success', true, 'job_id', v_job_id, 'is_new', v_is_new);

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result, expires_at)
    VALUES (p_idempotency_key, 'save_job', v_result, now() + interval '24 hours')
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."save_job"("p_job_id" "uuid", "p_job_payload" "jsonb", "p_fields" "jsonb", "p_chemicals" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_job_applied_record"("p_record" "jsonb", "p_fields" "jsonb", "p_crew" "jsonb" DEFAULT NULL::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_record_id uuid;
  v_job_id uuid;
  v_actor uuid;
  v_request_hash text;
  v_stored_hash text;
  v_result jsonb;
BEGIN
  -- PARKED-004 (codex-driven cycle 3 #2 HIGH): strict-actor — created_by is bound to
  -- auth.uid(); the client cannot supply (or forge) the audit identity.
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_record_id := NULLIF(p_record->>'id', '')::uuid;
  v_job_id    := (p_record->>'job_id')::uuid;

  IF v_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required' USING ERRCODE = 'check_violation';
  END IF;

  -- Fingerprint of the FULL create request. Computed from the canonical jsonb text so a
  -- byte-identical retry hashes the same (jsonb normalizes key order + whitespace) and only
  -- a genuine edit differs. chr(31) (unit separator) keeps the three parts unambiguous.
  v_request_hash := md5(
    coalesce(p_record::text, '') || chr(31) ||
    coalesce(p_fields::text, '') || chr(31) ||
    coalesce(p_crew::text, '')
  );

  -- ── Parent upsert ─────────────────────────────────────────────────────────
  IF v_record_id IS NULL THEN
    -- Insert-once: stamp the dedup key + request fingerprint on the new row. A
    -- network-timeout retry replays the SAME key; the second INSERT trips the partial
    -- UNIQUE index, we catch it and either replay (identical payload) or surface a
    -- conflict (changed payload). Only the idempotency_key index can raise
    -- unique_violation on this table (the PK is a server-defaulted uuid); if the
    -- recovered id is NULL the violation came from something else, so re-raise.
    BEGIN
      INSERT INTO job_applied_records (
        job_id, applicator_id, vehicle_id, application_date, applied_acres, notes,
        start_weather_time, start_temp_f, start_wind_direction, start_wind_mph,
        start_humidity_pct, start_weather_source,
        end_weather_time, end_temp_f, end_wind_direction, end_wind_mph,
        end_humidity_pct, end_weather_source,
        beginning_tach, end_tach, created_by, idempotency_key, idempotency_request_hash
      )
      VALUES (
        v_job_id,
        NULLIF(p_record->>'applicator_id', '')::uuid,
        NULLIF(p_record->>'vehicle_id', '')::uuid,
        (p_record->>'application_date')::date,
        NULLIF(p_record->>'applied_acres', '')::numeric,
        NULLIF(p_record->>'notes', ''),
        NULLIF(p_record->>'start_weather_time', '')::time,
        NULLIF(p_record->>'start_temp_f', '')::numeric,
        NULLIF(p_record->>'start_wind_direction', ''),
        NULLIF(p_record->>'start_wind_mph', '')::numeric,
        NULLIF(p_record->>'start_humidity_pct', '')::numeric,
        NULLIF(p_record->>'start_weather_source', ''),
        NULLIF(p_record->>'end_weather_time', '')::time,
        NULLIF(p_record->>'end_temp_f', '')::numeric,
        NULLIF(p_record->>'end_wind_direction', ''),
        NULLIF(p_record->>'end_wind_mph', '')::numeric,
        NULLIF(p_record->>'end_humidity_pct', '')::numeric,
        NULLIF(p_record->>'end_weather_source', ''),
        NULLIF(p_record->>'beginning_tach', '')::numeric,
        NULLIF(p_record->>'end_tach', '')::numeric,
        v_actor,               -- strict-actor: bound to auth.uid()
        NULLIF(p_idempotency_key, ''),
        -- Fingerprint only when a dedup key is actually in play (keyed create).
        CASE WHEN NULLIF(p_idempotency_key, '') IS NOT NULL THEN v_request_hash ELSE NULL END
      )
      RETURNING id INTO v_record_id;
    EXCEPTION WHEN unique_violation THEN
      -- Recover the first record for THIS job + key. Scoping to v_job_id (not key alone)
      -- means a key accidentally reused across a DIFFERENT job re-raises the
      -- unique_violation (surfaced as an error) instead of silently returning — and
      -- appearing to "succeed" as — another job's record.
      SELECT id, idempotency_request_hash
        INTO v_record_id, v_stored_hash
        FROM job_applied_records
       WHERE idempotency_key = NULLIF(p_idempotency_key, '')
         AND job_id = v_job_id;
      IF v_record_id IS NULL THEN
        RAISE;  -- not a same-job dedup-key collision — surface the real error
      END IF;
      -- Payload-conflict guard: if the first call stored a fingerprint and the retried
      -- payload differs, the retry carries CHANGED data under the same key. Returning the
      -- original would silently drop the correction (a legal application record), so
      -- surface the conflict instead. A legacy NULL-hash row (none exist live) falls back
      -- to a plain replay — never a false conflict.
      IF v_stored_hash IS NOT NULL AND v_stored_hash IS DISTINCT FROM v_request_hash THEN
        RAISE EXCEPTION
          'APPLIED_RECORD_ALREADY_SAVED_DIFFERENT: this entry was already saved with different values under the same submission; reload to review and edit the saved record'
          USING ERRCODE = 'raise_exception';
      END IF;
      -- Replay: identical retry (or legacy no-hash). Return the first record WITHOUT
      -- re-running the child writes (true insert-once semantics).
      RETURN jsonb_build_object('record_id', v_record_id);
    END;
  ELSE
    UPDATE job_applied_records SET
      applicator_id        = NULLIF(p_record->>'applicator_id', '')::uuid,
      vehicle_id           = NULLIF(p_record->>'vehicle_id', '')::uuid,
      application_date     = (p_record->>'application_date')::date,
      applied_acres        = NULLIF(p_record->>'applied_acres', '')::numeric,
      notes                = NULLIF(p_record->>'notes', ''),
      start_weather_time   = NULLIF(p_record->>'start_weather_time', '')::time,
      start_temp_f         = NULLIF(p_record->>'start_temp_f', '')::numeric,
      start_wind_direction = NULLIF(p_record->>'start_wind_direction', ''),
      start_wind_mph       = NULLIF(p_record->>'start_wind_mph', '')::numeric,
      start_humidity_pct   = NULLIF(p_record->>'start_humidity_pct', '')::numeric,
      start_weather_source = NULLIF(p_record->>'start_weather_source', ''),
      end_weather_time     = NULLIF(p_record->>'end_weather_time', '')::time,
      end_temp_f           = NULLIF(p_record->>'end_temp_f', '')::numeric,
      end_wind_direction   = NULLIF(p_record->>'end_wind_direction', ''),
      end_wind_mph         = NULLIF(p_record->>'end_wind_mph', '')::numeric,
      end_humidity_pct     = NULLIF(p_record->>'end_humidity_pct', '')::numeric,
      end_weather_source   = NULLIF(p_record->>'end_weather_source', ''),
      beginning_tach       = NULLIF(p_record->>'beginning_tach', '')::numeric,
      end_tach             = NULLIF(p_record->>'end_tach', '')::numeric
      -- idempotency_key / idempotency_request_hash intentionally NOT rewritten on edit:
      -- an edit is a pure re-upsert (naturally idempotent) and the create-time tokens
      -- must persist.
    WHERE id = v_record_id AND job_id = v_job_id;

    -- 0 rows = the row is invisible/unauthorized to the caller (RLS) or wrong job.
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Applied record % not found or not editable', v_record_id
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  -- ── Child: per-location fields (always a full replacement) ────────────────
  -- The job_applied_record_fields INSERT RLS (Wave 2a) enforces field MEMBERSHIP:
  -- a foreign field_id RAISES here and rolls back the parent too.
  DELETE FROM job_applied_record_fields WHERE application_record_id = v_record_id;

  IF p_fields IS NOT NULL AND jsonb_typeof(p_fields) = 'array' THEN
    INSERT INTO job_applied_record_fields (application_record_id, field_id, applied_acres)
    SELECT v_record_id, (e->>'field_id')::uuid, (e->>'applied_acres')::numeric
    FROM jsonb_array_elements(p_fields) AS e;
  END IF;

  -- ── Child: ground crew (replace, preserving NULL-member legal snapshots) ──
  IF p_crew IS NOT NULL AND jsonb_typeof(p_crew) = 'array' THEN
    DELETE FROM job_applied_record_crew
    WHERE application_record_id = v_record_id AND member_id IS NOT NULL;

    INSERT INTO job_applied_record_crew (
      application_record_id, member_id, member_name_snapshot,
      crew_id_snapshot, crew_name_snapshot
    )
    SELECT
      v_record_id,
      (e->>'member_id')::uuid,
      e->>'member_name_snapshot',
      NULLIF(e->>'crew_id_snapshot', '')::uuid,
      NULLIF(e->>'crew_name_snapshot', '')
    FROM jsonb_array_elements(p_crew) AS e;
  END IF;

  v_result := jsonb_build_object('record_id', v_record_id);
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."save_job_applied_record"("p_record" "jsonb", "p_fields" "jsonb", "p_crew" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_job_applied_record"("p_record" "jsonb", "p_fields" "jsonb", "p_crew" "jsonb", "p_idempotency_key" "text") IS 'Atomically upsert a job_applied_records entry plus its per-location field rows and ground-crew rows in ONE transaction (SECURITY INVOKER -> caller RLS, incl. the field-membership WITH CHECK, gates every write). Strict-actor: created_by := auth.uid(). p_idempotency_key stamps a dedup token + request fingerprint on a NEW record; a retried create with the SAME payload replays the first row (insert-once, no duplicate), while a retry with a CHANGED payload RAISEs APPLIED_RECORD_ALREADY_SAVED_DIFFERENT so a corrected retry surfaces a conflict instead of silently dropping the correction. p_crew NULL skips the crew mutation (catalog-unavailable guard); an array replaces live crew rows while preserving member_id-NULL legal snapshots.';



CREATE OR REPLACE FUNCTION "public"."save_purchase_order"("p_po_id" "uuid", "p_po_payload" "jsonb", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_payload jsonb := COALESCE(p_po_payload, '{}'::jsonb);
  v_bulk_intent_key text := NULLIF(btrim(v_payload->>'bulk_import_intent_key'), '');
  v_vendor text := v_payload->>'vendor';
  v_vendor_reference text := v_payload->>'bulk_import_vendor_reference';
  -- ECMAScript WhiteSpace and LineTerminator code points used by trim(). Keep
  -- this list explicit so collation and regex locale cannot alter identity.
  v_identity_boundary_chars text :=
      chr(9) || chr(10) || chr(11) || chr(12) || chr(13) || chr(32)
      || chr(160) || chr(5760)
      || chr(8192) || chr(8193) || chr(8194) || chr(8195) || chr(8196)
      || chr(8197) || chr(8198) || chr(8199) || chr(8200) || chr(8201)
      || chr(8202) || chr(8232) || chr(8233) || chr(8239) || chr(8287)
      || chr(12288) || chr(65279);
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH: p_performed_by must match auth.uid()'
      USING ERRCODE = 'P0001';
  END IF;
  IF NOT (public.is_admin() OR public.is_sales_rep()) THEN
    RAISE EXCEPTION 'Only admins or sales reps can manage purchase orders';
  END IF;

  IF v_bulk_intent_key IS NOT NULL THEN
    v_vendor := btrim(v_vendor, v_identity_boundary_chars);
    v_vendor_reference := btrim(v_vendor_reference, v_identity_boundary_chars);

    IF NULLIF(v_vendor, '') IS NULL THEN
      RAISE EXCEPTION 'BULK_PO_VENDOR_REQUIRED';
    END IF;
    IF NULLIF(v_vendor_reference, '') IS NULL THEN
      RAISE EXCEPTION 'BULK_PO_VENDOR_REFERENCE_REQUIRED';
    END IF;

    v_payload := jsonb_set(
      jsonb_set(v_payload, '{vendor}', to_jsonb(v_vendor), true),
      '{bulk_import_vendor_reference}',
      to_jsonb(v_vendor_reference),
      true
    );
  END IF;

  RETURN public._save_purchase_order_ascii_identity_impl(
    p_po_id,
    v_payload,
    p_items,
    p_performed_by,
    p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."save_purchase_order"("p_po_id" "uuid", "p_po_payload" "jsonb", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_purchase_order"("p_po_id" "uuid", "p_po_payload" "jsonb", "p_items" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Saves a purchase order; a bulk-import marker opts into PostgreSQL-derived NFKC/lower/NFKC document identity, deterministic claim/replay, and reviewed-content binding.';



CREATE OR REPLACE FUNCTION "public"."save_quote"("p_quote_id" "uuid", "p_quote_payload" "jsonb", "p_sections" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_quote_id uuid;
  v_section_id uuid;
  v_item jsonb;
  v_section jsonb;
  v_status text;
  v_old_status text;
  v_tier int;
  v_server_totals record;
  v_drawn_guard record;
  v_allowed_transitions jsonb := '{
    "draft": ["sent"],
    "sent": ["revised","accepted","declined","expired"],
    "revised": ["sent","accepted","declined","expired"]
  }'::jsonb;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = v_actor AND role IN ('admin','sales_rep') AND is_active = true
  ) THEN
    RAISE EXCEPTION 'Not authorized to save quotes';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'save_quote');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  v_status := COALESCE(p_quote_payload->>'status', 'draft');
  v_tier := COALESCE((p_quote_payload->>'tier')::int, 1);

  IF p_quote_id IS NOT NULL THEN
    -- LAYER2-COORD (#5): lock the quote row up front (FOR UPDATE) so the unplan
    -- guard's job_product_draws check below can't be raced by a concurrent job
    -- schedule (_sync_quote_job_reservations locks the same row FOR UPDATE, so
    -- the two serialize). Was: SELECT status ... WHERE id = p_quote_id;
    SELECT status INTO v_old_status FROM quotes WHERE id = p_quote_id FOR UPDATE;
    IF v_old_status IS NULL THEN
      RAISE EXCEPTION 'Quote not found: %', p_quote_id;
    END IF;

    IF v_status IS DISTINCT FROM v_old_status THEN
      IF NOT (
        v_allowed_transitions->v_old_status IS NOT NULL
        AND v_allowed_transitions->v_old_status ? v_status
      ) THEN
        RAISE EXCEPTION 'Invalid status transition: % -> %', v_old_status, v_status;
      END IF;
    END IF;

    -- LAYER2<<< block unplanning a booking a scheduled job is still drawing from
    -- (Codex final push-gate P1 #1): if is_planned would become false while a live
    -- job_product_draws row exists for this quote, the UPDATE below + trailing
    -- _sync_planned_holds release the quote's crop_program holds, and the next job
    -- re-sync drops the draw (quote no longer planned-open) — reopening the full
    -- booking balance while the job still consumes the stock (double-count). Clear the
    -- job reservation via the job lifecycle (cancel/reschedule) before unplanning.
    IF COALESCE((p_quote_payload->>'is_planned')::boolean,
                (SELECT is_planned FROM quotes WHERE id = p_quote_id)) = false
       AND EXISTS (
         SELECT 1 FROM job_product_draws
         WHERE quote_id = p_quote_id AND quantity_drawn > 0
       ) THEN
      RAISE EXCEPTION 'BOOKING_HAS_JOB_RESERVATION: cannot unplan this booking — a scheduled job is still reserving product from it; cancel or reschedule the job first';
    END IF;
    -- >>>LAYER2

    UPDATE quotes SET
      customer_id = (p_quote_payload->>'customer_id')::uuid,
      tier = v_tier,
      status = v_status,
      commission_split = CASE
        WHEN p_quote_payload->'commission_split' IS NOT NULL
        THEN p_quote_payload->'commission_split'
        ELSE commission_split
      END,
      valid_days = COALESCE((p_quote_payload->>'valid_days')::int, valid_days),
      expires_at = COALESCE((p_quote_payload->>'expires_at')::date, expires_at),
      header_notes = p_quote_payload->>'header_notes',
      footer_notes = p_quote_payload->>'footer_notes',
      is_planned = COALESCE((p_quote_payload->>'is_planned')::boolean, is_planned),
      sent_at = CASE
        WHEN v_status = 'sent' AND sent_at IS NULL THEN now()
        WHEN v_status = 'sent' THEN sent_at
        ELSE sent_at
      END,
      updated_at = now()
    WHERE id = p_quote_id;

    v_quote_id := p_quote_id;

    DELETE FROM quote_sections WHERE quote_id = v_quote_id;
  ELSE
    IF v_status <> 'draft' THEN
      RAISE EXCEPTION 'New quotes must start with status draft';
    END IF;

    INSERT INTO quotes (
      id, quote_number, customer_id, created_by, tier, status,
      commission_split, total_price, total_cost, total_profit, total_margin_pct,
      valid_days, expires_at, header_notes, footer_notes, is_planned, created_at, updated_at
    ) VALUES (
      gen_random_uuid(),
      p_quote_payload->>'quote_number',
      (p_quote_payload->>'customer_id')::uuid,
      v_actor,
      v_tier,
      'draft',
      COALESCE(p_quote_payload->'commission_split', '{"splits":[]}'::jsonb),
      0, 0, 0, 0,
      COALESCE((p_quote_payload->>'valid_days')::int, 15),
      COALESCE((p_quote_payload->>'expires_at')::date, current_date + 15),
      p_quote_payload->>'header_notes',
      p_quote_payload->>'footer_notes',
      COALESCE((p_quote_payload->>'is_planned')::boolean, false),
      now(), now()
    )
    RETURNING id INTO v_quote_id;
  END IF;

  FOR v_section IN SELECT * FROM jsonb_array_elements(p_sections)
  LOOP
    INSERT INTO quote_sections (
      id, quote_id, section_name, sort_order, section_notes,
      section_header_notes, needed_by_date, field_id
    ) VALUES (
      gen_random_uuid(),
      v_quote_id,
      COALESCE(v_section->>'section_name', 'Section'),
      COALESCE((v_section->>'sort_order')::int, 0),
      v_section->>'section_notes',
      v_section->>'section_header_notes',
      NULLIF(v_section->>'needed_by_date', '')::date,
      NULLIF(v_section->>'field_id', '')::uuid
    )
    RETURNING id INTO v_section_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(v_section->'items')
    LOOP
      INSERT INTO quote_items (
        id, quote_id, section_id, product_id, sort_order, notes,
        price_per_unit, price_override, current_cost, suggested_rate, actual_rate,
        rate_unit, oz_per_acre, price_per_acre, acres,
        total_units_needed, unit_size, profit, total_price, net_margin,
        calc_mode, price_unit
      ) VALUES (
        gen_random_uuid(),
        v_quote_id,
        v_section_id,
        (v_item->>'product_id')::uuid,
        COALESCE((v_item->>'sort_order')::int, 0),
        v_item->>'notes',
        COALESCE((v_item->>'price_per_unit')::numeric, 0),
        (v_item->>'price_override')::numeric,
        COALESCE((v_item->>'current_cost')::numeric, 0),
        v_item->>'suggested_rate',
        (v_item->>'actual_rate')::numeric,
        v_item->>'rate_unit',
        (v_item->>'oz_per_acre')::numeric,
        (v_item->>'price_per_acre')::numeric,
        (v_item->>'acres')::numeric,
        (v_item->>'total_units_needed')::numeric,
        v_item->>'unit_size',
        COALESCE((v_item->>'profit')::numeric, 0),
        COALESCE((v_item->>'total_price')::numeric, 0),
        COALESCE((v_item->>'net_margin')::numeric, 0),
        COALESCE(v_item->>'calc_mode', 'rate_acres'),
        v_item->>'price_unit'
      );
    END LOOP;
  END LOOP;

  WITH base AS (
    SELECT
      qi.id AS item_id,
      COALESCE(qi.calc_mode, 'rate_acres') AS calc_mode,
      COALESCE(qi.actual_rate, 0) AS ar,
      COALESCE(qi.acres, 0) AS ac,
      COALESCE(qi.total_units_needed, 0) AS client_units,
      COALESCE(qi.price_override, CASE v_tier
        WHEN 1 THEN COALESCE(p.tier1_price, 0)
        WHEN 2 THEN COALESCE(p.tier2_price, p.tier1_price, 0)
        ELSE COALESCE(p.tier3_price, p.tier1_price, 0)
      END) AS ppu,
      COALESCE(p.current_cost, 0) AS cc,
      COALESCE(rate_conv.factor_oz, 1) AS rate_oz,
      COALESCE(inv_conv.factor_oz, 1) AS inv_oz
    FROM quote_items qi
    JOIN products p ON p.id = qi.product_id
    LEFT JOIN unit_conversions rate_conv
      ON LOWER(rate_conv.unit) = LOWER(qi.rate_unit)
    LEFT JOIN unit_conversions inv_conv
      ON LOWER(inv_conv.unit) = LOWER(COALESCE(p.inventory_unit, p.unit_size, 'Ea'))
    WHERE qi.quote_id = v_quote_id
  ),
  calc AS (
    SELECT
      item_id,
      ppu,
      cc,
      calc_mode,
      CASE
        WHEN calc_mode = 'units_direct' AND ac > 0 AND inv_oz > 0
          THEN ROUND((client_units * inv_oz) / ac, 2)
        WHEN calc_mode = 'rate_acres'
          THEN ROUND(ar * rate_oz, 2)
        ELSE 0
      END AS oz_per_acre,
      CASE
        WHEN calc_mode = 'units_direct' THEN ROUND(client_units, 2)
        WHEN inv_oz > 0 THEN ROUND((ac * ar * rate_oz) / inv_oz, 2)
        ELSE 0
      END AS total_units,
      CASE
        WHEN calc_mode = 'units_direct' AND ac > 0
          THEN ROUND(ppu * client_units / ac, 2)
        WHEN calc_mode = 'rate_acres' AND inv_oz > 0
          THEN ROUND(ppu * (ar * rate_oz / inv_oz), 2)
        ELSE 0
      END AS price_per_acre
    FROM base
  ),
  final AS (
    SELECT
      item_id,
      ppu,
      cc,
      oz_per_acre,
      total_units,
      price_per_acre,
      ROUND(ppu * total_units, 2) AS total_price,
      ROUND((ppu - cc) * total_units, 2) AS profit,
      CASE
        WHEN ppu * total_units > 0
          THEN ROUND(((ppu - cc) * total_units) / (ppu * total_units) * 100, 2)
        ELSE 0
      END AS net_margin
    FROM calc
  )
  UPDATE quote_items qi SET
    price_per_unit = f.ppu,
    current_cost = f.cc,
    oz_per_acre = f.oz_per_acre,
    total_units_needed = f.total_units,
    price_per_acre = f.price_per_acre,
    total_price = f.total_price,
    profit = f.profit,
    net_margin = f.net_margin
  FROM final f
  WHERE qi.id = f.item_id;

  -- LAYER2<<< drawn-product guard counts ORDER + JOB draws (§6.5 / Codex round-2 P1):
  -- a line can't be reduced below what an order OR a scheduled job already drew from it.
  SELECT
    COALESCE(p.product_name, d.product_id::text) AS product_name,
    d.quantity_drawn,
    COALESCE(b.booked, 0) AS new_booked
  INTO v_drawn_guard
  FROM (
    SELECT product_id, SUM(qty) AS quantity_drawn
    FROM (
      SELECT product_id, quantity_drawn AS qty FROM quote_product_draws WHERE quote_id = v_quote_id AND quantity_drawn > 0
      UNION ALL
      SELECT product_id, quantity_drawn AS qty FROM job_product_draws WHERE quote_id = v_quote_id AND quantity_drawn > 0
    ) x
    GROUP BY product_id
  ) d
  LEFT JOIN (
    SELECT product_id, SUM(COALESCE(total_units_needed, 0)) AS booked
    FROM quote_items
    WHERE quote_id = v_quote_id
    GROUP BY product_id
  ) b ON b.product_id = d.product_id
  LEFT JOIN products p ON p.id = d.product_id
  WHERE d.quantity_drawn > 0
    AND COALESCE(b.booked, 0) < d.quantity_drawn
  ORDER BY d.quantity_drawn - COALESCE(b.booked, 0) DESC, d.product_id
  LIMIT 1;
  -- >>>LAYER2
  IF FOUND THEN
    IF v_drawn_guard.new_booked <= 0 THEN
      RAISE EXCEPTION 'BOOKING_OVERDRAWN: cannot remove % — % already drawn',
        v_drawn_guard.product_name, v_drawn_guard.quantity_drawn;
    END IF;
    RAISE EXCEPTION 'BOOKING_OVERDRAWN: cannot reduce % below its already-drawn % (new total would be %)',
      v_drawn_guard.product_name, v_drawn_guard.quantity_drawn, v_drawn_guard.new_booked;
  END IF;

  SELECT
    COALESCE(SUM(total_price), 0) AS total_price,
    COALESCE(SUM(current_cost * total_units_needed), 0) AS total_cost,
    COALESCE(SUM(profit), 0) AS total_profit
  INTO v_server_totals
  FROM quote_items
  WHERE quote_id = v_quote_id;

  UPDATE quotes SET
    total_price = v_server_totals.total_price,
    total_cost = (SELECT COALESCE(SUM(current_cost * total_units_needed), 0) FROM quote_items WHERE quote_id = v_quote_id),
    total_profit = (SELECT COALESCE(SUM(profit), 0) FROM quote_items WHERE quote_id = v_quote_id),
    total_margin_pct = CASE
      WHEN (SELECT COALESCE(SUM(total_price), 0) FROM quote_items WHERE quote_id = v_quote_id) > 0
      THEN ROUND(
        (SELECT COALESCE(SUM(profit), 0) FROM quote_items WHERE quote_id = v_quote_id)
        / (SELECT COALESCE(SUM(total_price), 0) FROM quote_items WHERE quote_id = v_quote_id) * 100, 2
      )
      ELSE 0
    END,
    updated_at = now()
  WHERE id = v_quote_id;

  INSERT INTO activity_feed (id, event_type, description, performed_by, related_entity_type, related_entity_id, created_at)
  VALUES (
    gen_random_uuid(),
    CASE WHEN p_quote_id IS NOT NULL THEN 'quote_updated' ELSE 'quote_created' END,
    'Quote ' || COALESCE(p_quote_payload->>'quote_number', '') || ' saved',
    v_actor,
    'quote',
    v_quote_id,
    now()
  );

  -- LAYER2-COORD (#4): re-sync this quote's ACTIVE jobs to the edited booking,
  -- then resync crop_program holds. _sync_quote_job_reservations rebuilds every
  -- active job's draws+holds (so a grown line re-draws its job, a shrunk line
  -- reallocates siblings) and ends by calling _sync_planned_holds itself, so it
  -- is a strict superset of the prior trailing `_sync_planned_holds(v_quote_id)`
  -- (identical for a quote with no jobs). Was: PERFORM _sync_planned_holds(...).
  PERFORM _sync_quote_job_reservations(v_quote_id, v_actor);

  v_result := jsonb_build_object(
    'status', 'saved',
    'quote_id', v_quote_id,
    'server_totals', jsonb_build_object(
      'total_price', (SELECT total_price FROM quotes WHERE id = v_quote_id),
      'total_cost', (SELECT total_cost FROM quotes WHERE id = v_quote_id),
      'total_profit', (SELECT total_profit FROM quotes WHERE id = v_quote_id),
      'total_margin_pct', (SELECT total_margin_pct FROM quotes WHERE id = v_quote_id)
    )
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'save_quote', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."save_quote"("p_quote_id" "uuid", "p_quote_payload" "jsonb", "p_sections" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_quote_template"("p_quote_id" "uuid", "p_template_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_sections jsonb;
  v_template_id uuid;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role IN ('admin', 'sales_rep')) THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'save_quote_template' AND created_at > now() - interval '24 hours'
    ) THEN
      RETURN jsonb_build_object('status', 'duplicate', 'message', 'Already processed');
    END IF;
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'save_quote_template', to_jsonb(p_quote_id));
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'section_name', qs.section_name,
      'sort_order', qs.sort_order,
      'section_notes', qs.section_notes,
      'section_header_notes', qs.section_header_notes,
      'items', (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'product_id', qi.product_id,
            'product_name', p.product_name,
            'sku', p.sku,
            'sort_order', qi.sort_order,
            'notes', qi.notes,
            'suggested_rate', qi.suggested_rate,
            'actual_rate', qi.actual_rate,
            'rate_unit', qi.rate_unit,
            'calc_mode', qi.calc_mode
          ) ORDER BY qi.sort_order
        ), '[]'::jsonb)
        FROM quote_items qi
        JOIN products p ON p.id = qi.product_id
        WHERE qi.section_id = qs.id
      )
    ) ORDER BY qs.sort_order
  ), '[]'::jsonb) INTO v_sections
  FROM quote_sections qs WHERE qs.quote_id = p_quote_id;

  INSERT INTO quote_templates (template_name, description, sections, created_by)
  VALUES (p_template_name, p_description, v_sections, v_actor)
  RETURNING id INTO v_template_id;

  RETURN jsonb_build_object('status', 'created', 'template_id', v_template_id);
END;
$$;


ALTER FUNCTION "public"."save_quote_template"("p_quote_id" "uuid", "p_template_name" "text", "p_description" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_vendor"("p_vendor_id" "uuid", "p_payload" "jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid; v_actor_role text; v_vendor_id uuid;
  v_is_new boolean := (p_vendor_id IS NULL);
  v_name text; v_result jsonb; v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role <> 'admin' THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: only admins can manage vendors';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'save_vendor');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  v_name := NULLIF(trim(p_payload->>'name'), '');
  IF v_name IS NULL THEN RAISE EXCEPTION 'INVALID_NAME: vendor name is required'; END IF;

  IF v_is_new THEN
    INSERT INTO vendors (name, contact_name, phone, email, address,
      default_payment_terms, default_payment_terms_days, notes)
    VALUES (v_name,
      NULLIF(p_payload->>'contact_name', ''),
      NULLIF(p_payload->>'phone', ''),
      NULLIF(p_payload->>'email', ''),
      NULLIF(p_payload->>'address', ''),
      NULLIF(p_payload->>'default_payment_terms', ''),
      (p_payload->>'default_payment_terms_days')::integer,
      NULLIF(p_payload->>'notes', ''))
    RETURNING id INTO v_vendor_id;
  ELSE
    v_vendor_id := p_vendor_id;
    UPDATE vendors SET name = v_name,
      contact_name = CASE WHEN p_payload ? 'contact_name' THEN NULLIF(p_payload->>'contact_name', '') ELSE contact_name END,
      phone = CASE WHEN p_payload ? 'phone' THEN NULLIF(p_payload->>'phone', '') ELSE phone END,
      email = CASE WHEN p_payload ? 'email' THEN NULLIF(p_payload->>'email', '') ELSE email END,
      address = CASE WHEN p_payload ? 'address' THEN NULLIF(p_payload->>'address', '') ELSE address END,
      default_payment_terms = CASE WHEN p_payload ? 'default_payment_terms' THEN NULLIF(p_payload->>'default_payment_terms', '') ELSE default_payment_terms END,
      default_payment_terms_days = CASE WHEN p_payload ? 'default_payment_terms_days' THEN (p_payload->>'default_payment_terms_days')::integer ELSE default_payment_terms_days END,
      notes = CASE WHEN p_payload ? 'notes' THEN NULLIF(p_payload->>'notes', '') ELSE notes END,
      updated_at = now()
    WHERE id = v_vendor_id AND deleted_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'VENDOR_NOT_FOUND: % (or already deleted)', v_vendor_id;
    END IF;
  END IF;

  INSERT INTO activity_feed (event_type, description, performed_by,
    related_entity_type, related_entity_id)
  VALUES (CASE WHEN v_is_new THEN 'vendor_created' ELSE 'vendor_updated' END,
    CASE WHEN v_is_new THEN 'Vendor ' || v_name || ' created' ELSE 'Vendor ' || v_name || ' updated' END,
    v_actor, 'vendor', v_vendor_id);

  v_result := jsonb_build_object('success', true, 'vendor_id', v_vendor_id, 'is_new', v_is_new);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'save_vendor', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."save_vendor"("p_vendor_id" "uuid", "p_payload" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


