CREATE OR REPLACE FUNCTION "public"."set_application_record_lots"("p_application_record_id" "uuid", "p_lots" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor          uuid := auth.uid();
  v_existing       jsonb;
  v_rec            record;
  v_lot            jsonb;
  v_product_id     uuid;
  v_lot_number     text;
  v_src            uuid;
  v_valid_products uuid[];
  v_seen           text[] := '{}';
  v_key            text;
  v_count          int := 0;
  v_result         jsonb;
BEGIN
  -- strict-actor (bind auth.uid(); reject a spoofed p_performed_by)
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  -- in-body role gate (the real gate — the EXECUTE grant is not enough)
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales role required to set application record lots';
  END IF;

  -- lock the parent record FIRST (race safety for the delete+reinsert) and validate it exists
  SELECT * INTO v_rec FROM application_records
   WHERE id = p_application_record_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'APPLICATION_RECORD_NOT_FOUND: %', p_application_record_id;
  END IF;

  -- idempotency check AFTER the lock, BEFORE any mutation: same-key concurrent retries
  -- serialize on the parent FOR UPDATE, so the loser sees the winner's committed key and
  -- replays the cached result instead of re-running the delete/reinsert (Codex P2 — a
  -- pre-lock check let both racers pass before either saved the key).
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'set_application_record_lots');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF p_lots IS NULL OR jsonb_typeof(p_lots) <> 'array' THEN
    RAISE EXCEPTION 'INVALID_LOTS_PAYLOAD: p_lots must be a JSON array';
  END IF;

  -- valid products = the non-null product_id values in this record's product_data
  SELECT COALESCE(array_agg(DISTINCT (pd->>'product_id')::uuid), '{}')
    INTO v_valid_products
    FROM jsonb_array_elements(v_rec.product_data) pd
   WHERE NULLIF(pd->>'product_id', '') IS NOT NULL;

  -- replace: clear this record's lots, then reinsert from the payload
  DELETE FROM application_record_lots WHERE application_record_id = p_application_record_id;

  FOR v_lot IN SELECT * FROM jsonb_array_elements(p_lots)
  LOOP
    v_product_id := NULLIF(v_lot->>'product_id', '')::uuid;
    v_lot_number := btrim(COALESCE(v_lot->>'lot_number', ''));

    IF v_product_id IS NULL THEN
      RAISE EXCEPTION 'LOT_MISSING_PRODUCT: each lot requires a product_id';
    END IF;
    IF v_lot_number = '' THEN
      RAISE EXCEPTION 'LOT_MISSING_NUMBER: each lot requires a non-blank lot_number';
    END IF;
    IF NOT (v_product_id = ANY (v_valid_products)) THEN
      RAISE EXCEPTION 'PRODUCT_NOT_ON_RECORD: product % is not in this application record', v_product_id;
    END IF;

    -- if a source receiving record is cited, it must actually be for THIS product + lot —
    -- otherwise a stale/edited suggestion would point the compliance trace at the wrong
    -- receipt (Codex P2). Free-typed lots pass source_receiving_record_id = NULL (no check).
    v_src := NULLIF(v_lot->>'source_receiving_record_id', '')::uuid;
    IF v_src IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM receiving_records rr
      WHERE rr.id = v_src
        AND rr.product_id = v_product_id
        AND lower(btrim(rr.lot_number)) = lower(v_lot_number)
    ) THEN
      RAISE EXCEPTION 'SOURCE_RECEIPT_MISMATCH: receiving record % is not for product % lot %', v_src, v_product_id, v_lot_number;
    END IF;

    -- one row per (product, normalized lot) within this record (the SOW invariant + the unique
    -- index backstop) — reject a duplicate payload entry with a friendly token instead of a 23505.
    v_key := v_product_id::text || '|' || lower(v_lot_number);
    IF v_key = ANY (v_seen) THEN
      RAISE EXCEPTION 'DUPLICATE_LOT: product % lot % is listed more than once for this record', v_product_id, v_lot_number;
    END IF;
    v_seen := v_seen || v_key;

    INSERT INTO application_record_lots (
      application_record_id, product_id, lot_number,
      source_receiving_record_id, quantity_from_lot, unit, notes, created_by
    ) VALUES (
      p_application_record_id, v_product_id, v_lot_number,
      v_src,
      NULLIF(v_lot->>'quantity_from_lot', '')::numeric,
      NULLIF(v_lot->>'unit', ''),
      NULLIF(v_lot->>'notes', ''),
      v_actor
    );
    v_count := v_count + 1;
  END LOOP;

  -- Audit trail: lot assignments are recall-critical and this is a replace-all edit (the DELETE
  -- above cleared the prior rows). Record it in the activity feed so a later recall investigation
  -- can see who changed a record's lots and when — created_by on the new rows alone misses edits
  -- (and a clear-to-zero leaves no row at all).
  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES (
    'application_record_lots_updated',
    'Lots updated on application record ' || v_rec.record_number || ' — ' || v_count || ' lot(s)',
    v_actor, 'application_record', p_application_record_id, v_rec.customer_id
  );

  v_result := jsonb_build_object('success', true, 'count', v_count);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'set_application_record_lots', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."set_application_record_lots"("p_application_record_id" "uuid", "p_lots" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_field_boundary"("p_field_id" "uuid", "p_boundary_geojson" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid := auth.uid();
  v_existing jsonb;
  v_customer uuid;
  v_override numeric;
  v_geom     geometry;
  v_mpoly    geometry(MultiPolygon,4326);
  v_largest  geometry;
  v_measured numeric;
  v_billable numeric;
  v_result   jsonb;
BEGIN
  -- 1) strict-actor + role gate (source-verifiable inline binding + the project role helper)
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  PERFORM require_admin_or_sales_rep();

  -- 2) lock the field row (serialize concurrent boundary writes), then claim idempotency in the lock
  SELECT customer_id, override_acres INTO v_customer, v_override
  FROM fields WHERE id = p_field_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FIELD_NOT_FOUND: %', p_field_id; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing FROM idempotency_keys
    WHERE idempotency_key = p_idempotency_key AND operation = 'set_field_boundary';
    IF FOUND THEN RETURN v_existing; END IF;
  END IF;

  -- 3) parse + normalize geometry (contract: a Polygon/MultiPolygon geometry GeoJSON)
  v_geom := ST_GeomFromGeoJSON(p_boundary_geojson);
  v_geom := ST_Force2D(v_geom);
  v_geom := ST_SetSRID(v_geom, 4326);
  IF NOT ST_IsValid(v_geom) THEN v_geom := ST_MakeValid(v_geom); END IF;
  v_geom := ST_UnaryUnion(ST_CollectionExtract(v_geom, 3));   -- polygons only, dissolve overlaps
  v_mpoly := ST_Multi(v_geom);
  IF v_mpoly IS NULL OR ST_IsEmpty(v_mpoly) OR GeometryType(v_mpoly) <> 'MULTIPOLYGON' THEN
    RAISE EXCEPTION 'INVALID_GEOMETRY: boundary did not resolve to a polygon';
  END IF;

  -- 4) geodesic measure (m^2 -> acres), 2dp
  v_measured := round((ST_Area(v_mpoly::geography) / 4046.8564224)::numeric, 2);

  -- 5) sanity band — stop a fat-fingered / self-intersecting polygon minting a bad bill
  IF v_measured < 0.1 OR v_measured > 5000 THEN
    RAISE EXCEPTION 'AREA_OUT_OF_BAND: measured % ac (allowed 0.1-5000). Split the field or set an explicit override.', v_measured;
  END IF;

  -- 6) legacy single boundary = the largest part (a MultiPolygon cannot cast to geography(POLYGON))
  SELECT d.geom INTO v_largest
  FROM (SELECT (ST_Dump(v_mpoly)).geom AS geom) d
  ORDER BY ST_Area(d.geom::geography) DESC
  LIMIT 1;

  -- 7) write. acres_source is GENERATED — never written here. total_acres mirrors billable so
  --    legacy readers (that still read total_acres directly) stay correct until B2 threads precedence.
  v_billable := COALESCE(v_override, v_measured);
  PERFORM set_config('app.acre_authority_write', 'on', true);   -- authorize the authority-column write
  UPDATE fields
  SET boundary_geom  = v_mpoly,
      boundary       = v_largest::geography,
      centroid       = ST_Centroid(v_mpoly)::geography,
      measured_acres = v_measured,
      total_acres    = v_billable,
      updated_at     = now()
  WHERE id = p_field_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'FIELD_NOT_FOUND: %', p_field_id; END IF;
  PERFORM set_config('app.acre_authority_write', 'off', true);

  -- 7b) keep the legacy field_polygons editing store (read by get_field_polygons in FieldSetup)
  --     in sync with the new boundary — regenerate one row per part so the map editor never
  --     reopens stale polygons. (Labels are not carried across a boundary replacement.)
  DELETE FROM field_polygons WHERE field_id = p_field_id;
  INSERT INTO field_polygons (field_id, polygon_geojson, acres, sort_order)
  SELECT p_field_id,
         ST_AsGeoJSON(d.geom)::jsonb,
         round((ST_Area(d.geom::geography) / 4046.8564224)::numeric, 2),
         (d.path)[1] - 1
  FROM ST_Dump(v_mpoly) d;

  -- 8) audit (table is activity_feed, NOT activity_log)
  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('field_acres_changed',
          'Boundary set: measured ' || v_measured || ' ac (billable ' || v_billable || ')',
          v_actor, 'field', p_field_id, v_customer);

  v_result := jsonb_build_object(
    'field_id', p_field_id,
    'measured_acres', v_measured,
    'billable_acres', v_billable,
    'acres_source', CASE WHEN v_override IS NOT NULL THEN 'override' ELSE 'measured' END
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'set_field_boundary', v_result)
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."set_field_boundary"("p_field_id" "uuid", "p_boundary_geojson" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_field_override_acres"("p_field_id" "uuid", "p_override_acres" numeric, "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid := auth.uid();
  v_existing jsonb;
  v_customer uuid;
  v_measured numeric;
  v_total    numeric;
  v_override numeric := round(p_override_acres, 2);   -- validate/store at the column's numeric(10,2) precision
  v_billable numeric;
  v_result   jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  PERFORM require_admin_or_sales_rep();

  -- validate at STORED precision (numeric(10,2)): NULL clears; otherwise must round to >= 0.01
  -- (so 0.004 -> 0.00 is rejected, not silently stored as zero) and <= 5000 (1000x-typo guard).
  IF v_override IS NOT NULL AND (v_override <= 0 OR v_override > 5000) THEN
    RAISE EXCEPTION 'INVALID_OVERRIDE_ACRES: must round to > 0 and <= 5000 ac at 2dp (or NULL to clear)';
  END IF;

  SELECT customer_id, measured_acres, total_acres INTO v_customer, v_measured, v_total
  FROM fields WHERE id = p_field_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FIELD_NOT_FOUND: %', p_field_id; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing FROM idempotency_keys
    WHERE idempotency_key = p_idempotency_key AND operation = 'set_field_override_acres';
    IF FOUND THEN RETURN v_existing; END IF;
  END IF;

  -- override never touches boundary_geom/measured_acres (so it survives a redraw).
  -- billable precedence override -> measured -> legacy total; clearing an override on a
  -- legacy field MUST fall back to its existing total_acres (never erase the legacy bill).
  v_billable := COALESCE(v_override, v_measured, v_total);
  PERFORM set_config('app.acre_authority_write', 'on', true);   -- authorize the authority-column write
  UPDATE fields
  SET override_acres = v_override,
      total_acres    = v_billable,
      updated_at     = now()
  WHERE id = p_field_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'FIELD_NOT_FOUND: %', p_field_id; END IF;
  PERFORM set_config('app.acre_authority_write', 'off', true);

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('field_acres_changed',
          CASE WHEN v_override IS NULL
               THEN 'Override cleared -> billable ' || COALESCE(v_billable::text, 'n/a')
               ELSE 'Override set: billable ' || v_override || ' ac (measured ' || COALESCE(v_measured::text,'n/a') || ')' END,
          v_actor, 'field', p_field_id, v_customer);

  v_result := jsonb_build_object(
    'field_id', p_field_id,
    'override_acres', v_override,
    'billable_acres', v_billable,
    'acres_source', CASE WHEN v_override IS NOT NULL THEN 'override'
                         WHEN v_measured IS NOT NULL THEN 'measured' ELSE 'legacy' END
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'set_field_override_acres', v_result)
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."set_field_override_acres"("p_field_id" "uuid", "p_override_acres" numeric, "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_primary_customer_contact"("p_customer_id" "uuid", "p_contact_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_target_id uuid;
  v_current_primary_id uuid;
BEGIN
  -- Lock the target row first. A missing row (wrong customer, or not visible
  -- under the caller's RLS) is a hard error, not a silent no-op.
  SELECT id INTO v_target_id
  FROM public.customer_contacts
  WHERE customer_id = p_customer_id
    AND id = p_contact_id
  FOR UPDATE;

  IF v_target_id IS NULL THEN
    RAISE EXCEPTION 'CONTACT_NOT_FOUND';
  END IF;

  -- Lock the existing primary (if any, and different from the target) before
  -- mutating so two concurrent promotions serialize here.
  SELECT id INTO v_current_primary_id
  FROM public.customer_contacts
  WHERE customer_id = p_customer_id
    AND is_primary
    AND id <> p_contact_id
  FOR UPDATE;

  -- Unset the old primary BEFORE setting the new one: the partial unique index
  -- on (customer_id) WHERE is_primary forbids two primaries even momentarily.
  IF v_current_primary_id IS NOT NULL THEN
    UPDATE public.customer_contacts
    SET is_primary = false
    WHERE id = v_current_primary_id;
  END IF;

  UPDATE public.customer_contacts
  SET is_primary = true,
      is_active = true
  WHERE id = p_contact_id;

  RETURN jsonb_build_object('success', true, 'contact_id', p_contact_id);
END;
$$;


ALTER FUNCTION "public"."set_primary_customer_contact"("p_customer_id" "uuid", "p_contact_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_primary_customer_contact"("p_customer_id" "uuid", "p_contact_id" "uuid") IS 'Atomically promotes one customer contact to primary (unset old, then set target) under the caller''s RLS; convergent, so replays settle to the same single-primary state.';



