ALTER FUNCTION "public"."set_supplier_evidence_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_applied_record_acres"("p_record_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_record_id IS NULL THEN
    RETURN;
  END IF;
  UPDATE job_applied_records r
  SET applied_acres = COALESCE((
    SELECT SUM(f.applied_acres)
    FROM job_applied_record_fields f
    WHERE f.application_record_id = p_record_id
  ), 0)
  WHERE r.id = p_record_id
    AND r.applied_acres IS DISTINCT FROM COALESCE((
      SELECT SUM(f.applied_acres)
      FROM job_applied_record_fields f
      WHERE f.application_record_id = p_record_id
    ), 0);
END;
$$;


ALTER FUNCTION "public"."settle_applied_record_acres"("p_record_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."snapshot_field_crop_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_season integer;
BEGIN
  IF OLD.crop_type IS NULL OR OLD.crop_type = NEW.crop_type THEN RETURN NEW; END IF;
  v_season := compute_season(CURRENT_DATE);
  INSERT INTO field_crop_history (field_id, season, crop_type) VALUES (OLD.id, v_season, OLD.crop_type)
  ON CONFLICT (field_id, season) DO UPDATE SET crop_type = EXCLUDED.crop_type;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."snapshot_field_crop_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stage_offline_action"("p_client_action_id" "uuid", "p_operation" "text", "p_entity_id" "uuid", "p_schema_version" integer, "p_client_created_at" timestamp with time zone, "p_payload" "jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_entity_snapshot_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_role text;
  v_existing public.offline_action_receipts%ROWTYPE;
  v_canonical jsonb := '{}'::jsonb;
  v_quantities jsonb;
  v_canonical_quantities jsonb := '{}'::jsonb;
  v_field_acres jsonb := '[]'::jsonb;
  v_canonical_field_acres jsonb := '[]'::jsonb;
  v_seen_fields jsonb := '{}'::jsonb;
  v_key text;
  v_text text;
  v_value jsonb;
  v_uuid uuid;
  v_number numeric;
  v_timestamp timestamptz;
  v_assigned_driver uuid;
  v_job_applicator uuid;
  v_target_updated_at timestamptz;
  v_target_exists boolean := false;
  v_authorized boolean := false;
  v_initial_status text := 'received';
  v_failure_code text;
  v_failure_summary text;
  v_payload_requires_review boolean := false;
  v_payload_review_summary text;
  v_now timestamptz := now();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;

  SELECT p.role
    INTO v_actor_role
    FROM public.profiles p
   WHERE p.id = v_actor
     AND p.is_active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: active profile required';
  END IF;

  IF p_client_action_id IS NULL OR p_entity_id IS NULL OR p_client_created_at IS NULL THEN
    RAISE EXCEPTION 'PAYLOAD_INVALID: action, entity, and client timestamp are required';
  END IF;
  IF p_client_created_at > v_now + interval '24 hours' THEN
    RAISE EXCEPTION 'PAYLOAD_INVALID: client timestamp is too far in the future';
  END IF;
  IF p_schema_version IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'UNSUPPORTED_SCHEMA_VERSION';
  END IF;
  IF p_operation IS NULL
     OR p_operation NOT IN ('complete_delivery', 'complete_job') THEN
    RAISE EXCEPTION 'UNSUPPORTED_OPERATION';
  END IF;
  IF p_idempotency_key IS NULL
     OR btrim(p_idempotency_key) = ''
     OR length(p_idempotency_key) > 200 THEN
    RAISE EXCEPTION 'PAYLOAD_INVALID: a bounded idempotency key is required';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'PAYLOAD_INVALID: payload must be a JSON object';
  END IF;
  IF pg_column_size(p_payload) > 65536 THEN
    RAISE EXCEPTION 'PAYLOAD_TOO_LARGE';
  END IF;

  IF p_operation = 'complete_delivery' THEN
    IF (p_payload - ARRAY['signed_by', 'quantities', 'issue_type', 'issue_notes', 'completed_at']) <> '{}'::jsonb THEN
      RAISE EXCEPTION 'PAYLOAD_INVALID: unsupported complete_delivery field';
    END IF;

    v_text := btrim(COALESCE(p_payload->>'signed_by', ''));
    IF v_text = '' OR length(v_text) > 200 THEN
      RAISE EXCEPTION 'PAYLOAD_INVALID: signed_by is required and limited to 200 characters';
    END IF;
    v_canonical := jsonb_build_object('signed_by', v_text);

    IF p_payload ? 'quantities' AND p_payload->'quantities' <> 'null'::jsonb THEN
      IF jsonb_typeof(p_payload->'quantities') <> 'object' THEN
        RAISE EXCEPTION 'PAYLOAD_INVALID: quantities must be an object';
      END IF;
      v_quantities := p_payload->'quantities';
      IF (SELECT count(*) FROM jsonb_object_keys(v_quantities)) > 500 THEN
        RAISE EXCEPTION 'PAYLOAD_TOO_LARGE: quantities exceeds 500 entries';
      END IF;

      FOR v_key, v_value IN SELECT key, value FROM jsonb_each(v_quantities)
      LOOP
        IF v_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: quantity key must be a UUID';
        END IF;
        IF jsonb_typeof(v_value) NOT IN ('number', 'string') THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: quantity must be numeric';
        END IF;
        v_text := v_value #>> '{}';
        IF v_text IS NULL OR v_text !~ '^-?([0-9]+(\.[0-9]+)?|\.[0-9]+)$' THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: quantity must be a finite decimal';
        END IF;
        v_number := v_text::numeric;
        IF v_number < 0 THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: quantity cannot be negative';
        END IF;
        v_uuid := v_key::uuid;
        v_canonical_quantities := v_canonical_quantities || jsonb_build_object(v_uuid::text, to_jsonb(v_number));
      END LOOP;
      v_canonical := v_canonical || jsonb_build_object('quantities', v_canonical_quantities);
    END IF;

    IF p_payload ? 'issue_type' AND p_payload->'issue_type' <> 'null'::jsonb THEN
      v_text := p_payload->>'issue_type';
      IF v_text NOT IN ('none', 'customer_not_home', 'gate_locked', 'road_blocked', 'wrong_address', 'refused', 'weather', 'other') THEN
        RAISE EXCEPTION 'PAYLOAD_INVALID: issue_type is not supported';
      END IF;
      v_canonical := v_canonical || jsonb_build_object('issue_type', v_text);
    END IF;

    IF p_payload ? 'issue_notes' AND p_payload->'issue_notes' <> 'null'::jsonb THEN
      IF jsonb_typeof(p_payload->'issue_notes') <> 'string' OR length(p_payload->>'issue_notes') > 2000 THEN
        RAISE EXCEPTION 'PAYLOAD_INVALID: issue_notes must be text up to 2000 characters';
      END IF;
      v_canonical := v_canonical || jsonb_build_object('issue_notes', p_payload->>'issue_notes');
    END IF;

    IF p_payload ? 'completed_at' AND p_payload->'completed_at' <> 'null'::jsonb THEN
      IF jsonb_typeof(p_payload->'completed_at') <> 'string' THEN
        RAISE EXCEPTION 'PAYLOAD_INVALID: completed_at must be an ISO timestamp';
      END IF;
      BEGIN
        v_timestamp := (p_payload->>'completed_at')::timestamptz;
      EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
        RAISE EXCEPTION 'PAYLOAD_INVALID: completed_at must be an ISO timestamp';
      END;
      IF v_timestamp > v_now + interval '5 minutes' THEN
        v_payload_requires_review := true;
        v_payload_review_summary := 'The saved completion time is ahead of the server clock. Office review is required.';
      ELSIF v_timestamp < v_now - interval '14 days' THEN
        v_payload_requires_review := true;
        v_payload_review_summary := 'The saved completion time is more than 14 days old. Office review is required before posting into a prior period.';
      END IF;
      v_canonical := v_canonical || jsonb_build_object('completed_at', to_jsonb(v_timestamp));
    END IF;

    SELECT d.assigned_driver, d.updated_at
      INTO v_assigned_driver, v_target_updated_at
      FROM public.deliveries d
     WHERE d.id = p_entity_id;
    v_target_exists := FOUND;
    v_authorized := v_target_exists AND (
      v_actor_role IN ('admin', 'sales_rep')
      OR (v_actor_role = 'driver' AND v_assigned_driver = v_actor)
    );

    IF v_target_exists AND v_quantities IS NOT NULL AND EXISTS (
      SELECT 1
      FROM jsonb_object_keys(v_quantities) q(item_id)
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.delivery_items di
        WHERE di.id = q.item_id::uuid
          AND di.delivery_id = p_entity_id
      )
    ) THEN
      v_payload_requires_review := true;
      v_payload_review_summary := 'A saved delivery item no longer belongs to this delivery. Office review is required.';
    END IF;

  ELSE
    IF (p_payload - ARRAY[
      'actual_start_time', 'actual_end_time', 'wind_speed', 'wind_direction',
      'temperature', 'humidity', 'actual_gallons_applied', 'notes', 'field_acres'
    ]) <> '{}'::jsonb THEN
      RAISE EXCEPTION 'PAYLOAD_INVALID: unsupported complete_job field';
    END IF;

    FOREACH v_key IN ARRAY ARRAY['wind_speed', 'temperature', 'humidity', 'actual_gallons_applied']::text[]
    LOOP
      IF p_payload ? v_key AND p_payload->v_key <> 'null'::jsonb THEN
        IF jsonb_typeof(p_payload->v_key) NOT IN ('number', 'string') THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: % must be numeric', v_key;
        END IF;
        v_text := p_payload->>v_key;
        IF v_text IS NULL OR v_text !~ '^-?([0-9]+(\.[0-9]+)?|\.[0-9]+)$' THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: % must be a finite decimal', v_key;
        END IF;
        v_number := v_text::numeric;
        v_canonical := v_canonical || jsonb_build_object(v_key, to_jsonb(v_number));
      END IF;
    END LOOP;

    IF p_payload ? 'wind_direction' AND p_payload->'wind_direction' <> 'null'::jsonb THEN
      IF jsonb_typeof(p_payload->'wind_direction') <> 'string' OR length(p_payload->>'wind_direction') > 64 THEN
        RAISE EXCEPTION 'PAYLOAD_INVALID: wind_direction must be text up to 64 characters';
      END IF;
      v_canonical := v_canonical || jsonb_build_object('wind_direction', p_payload->>'wind_direction');
    END IF;

    IF p_payload ? 'notes' AND p_payload->'notes' <> 'null'::jsonb THEN
      IF jsonb_typeof(p_payload->'notes') <> 'string' OR length(p_payload->>'notes') > 4000 THEN
        RAISE EXCEPTION 'PAYLOAD_INVALID: notes must be text up to 4000 characters';
      END IF;
      v_canonical := v_canonical || jsonb_build_object('notes', p_payload->>'notes');
    END IF;

    FOREACH v_key IN ARRAY ARRAY['actual_start_time', 'actual_end_time']::text[]
    LOOP
      IF p_payload ? v_key AND p_payload->v_key <> 'null'::jsonb THEN
        IF jsonb_typeof(p_payload->v_key) <> 'string' THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: % must be an ISO timestamp', v_key;
        END IF;
        BEGIN
          v_timestamp := (p_payload->>v_key)::timestamptz;
        EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: % must be an ISO timestamp', v_key;
        END;
        v_canonical := v_canonical || jsonb_build_object(v_key, to_jsonb(v_timestamp));
      END IF;
    END LOOP;

    IF p_payload ? 'field_acres' AND p_payload->'field_acres' <> 'null'::jsonb THEN
      IF jsonb_typeof(p_payload->'field_acres') <> 'array' THEN
        RAISE EXCEPTION 'PAYLOAD_INVALID: field_acres must be an array';
      END IF;
      v_field_acres := p_payload->'field_acres';
      IF jsonb_array_length(v_field_acres) > 500 THEN
        RAISE EXCEPTION 'PAYLOAD_TOO_LARGE: field_acres exceeds 500 entries';
      END IF;

      FOR v_value IN SELECT value FROM jsonb_array_elements(v_field_acres)
      LOOP
        IF jsonb_typeof(v_value) <> 'object'
           OR (v_value - ARRAY['field_id', 'acres_applied']) <> '{}'::jsonb
           OR NOT (v_value ? 'field_id')
           OR NOT (v_value ? 'acres_applied') THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: field_acres entry shape is invalid';
        END IF;
        v_text := v_value->>'field_id';
        IF v_text IS NULL OR v_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: field_id must be a UUID';
        END IF;
        v_uuid := v_text::uuid;
        IF v_seen_fields ? v_uuid::text THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: duplicate field_id';
        END IF;
        v_seen_fields := v_seen_fields || jsonb_build_object(v_uuid::text, true);

        IF jsonb_typeof(v_value->'acres_applied') NOT IN ('number', 'string') THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: acres_applied must be numeric';
        END IF;
        v_text := v_value->>'acres_applied';
        IF v_text IS NULL OR v_text !~ '^-?([0-9]+(\.[0-9]+)?|\.[0-9]+)$' THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: acres_applied must be a finite decimal';
        END IF;
        v_number := v_text::numeric;
        IF v_number < 0 THEN
          RAISE EXCEPTION 'PAYLOAD_INVALID: acres_applied cannot be negative';
        END IF;
        v_canonical_field_acres := v_canonical_field_acres || jsonb_build_array(
          jsonb_build_object('field_id', v_uuid, 'acres_applied', v_number)
        );
      END LOOP;

      SELECT COALESCE(jsonb_agg(e.value ORDER BY e.value->>'field_id'), '[]'::jsonb)
        INTO v_canonical_field_acres
        FROM jsonb_array_elements(v_canonical_field_acres) e(value);
      v_canonical := v_canonical || jsonb_build_object('field_acres', v_canonical_field_acres);
    END IF;

    SELECT j.applicator_id, j.updated_at
      INTO v_job_applicator, v_target_updated_at
      FROM public.jobs j
     WHERE j.id = p_entity_id;
    v_target_exists := FOUND;

    v_authorized := v_target_exists AND (
      public.is_admin()
      OR public.is_sales_rep()
      OR (public.is_applicator() AND v_job_applicator IS NOT NULL AND v_job_applicator = v_actor)
      OR (
        public.is_applicator()
        AND public._is_dispatched_to_me(p_entity_id)
        AND NOT EXISTS (
          SELECT 1
          FROM public.job_fields jf2
          WHERE jf2.job_id = p_entity_id
            AND NOT EXISTS (
              SELECT 1
              FROM public.job_location_dispatches d2
              WHERE d2.job_field_id = jf2.id
                AND d2.dispatch_status = 'dispatched'
                AND (
                  d2.applicator_id = v_actor
                  OR (
                    d2.crew_id IS NOT NULL
                    AND EXISTS (
                      SELECT 1
                      FROM public.ground_crew_members gcm
                      JOIN public.ground_crews gc ON gc.id = gcm.crew_id
                      WHERE gcm.crew_id = d2.crew_id
                        AND gcm.profile_id = v_actor
                        AND gcm.is_active
                        AND gc.is_active
                    )
                  )
                )
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.job_location_dispatches d
          WHERE d.job_id = p_entity_id
            AND d.dispatch_status = 'dispatched'
            AND NOT (
              (d.applicator_id IS NOT NULL AND d.applicator_id = v_actor)
              OR (
                d.crew_id IS NOT NULL
                AND EXISTS (
                  SELECT 1
                  FROM public.ground_crew_members gcm
                  JOIN public.ground_crews gc ON gc.id = gcm.crew_id
                  WHERE gcm.crew_id = d.crew_id
                    AND gcm.profile_id = v_actor
                    AND gcm.is_active
                    AND gc.is_active
                )
              )
            )
        )
      )
    );

    IF v_target_exists AND p_payload ? 'field_acres' AND EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_canonical_field_acres) e(value)
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.job_fields jf
        WHERE jf.job_id = p_entity_id
          AND jf.field_id = (e.value->>'field_id')::uuid
      )
    ) THEN
      v_payload_requires_review := true;
      v_payload_review_summary := 'A saved field no longer belongs to this job. Office review is required.';
    END IF;
  END IF;

  IF NOT v_target_exists THEN
    v_initial_status := 'needs_review';
    v_failure_code := 'TARGET_NOT_FOUND';
    v_failure_summary := 'The referenced delivery or job no longer exists.';
  ELSIF NOT v_authorized THEN
    v_initial_status := 'needs_review';
    v_failure_code := 'NOT_AUTHORIZED';
    v_failure_summary := 'The current user is no longer authorized to complete this delivery or job.';
  ELSIF p_entity_snapshot_at IS NULL THEN
    v_initial_status := 'needs_review';
    v_failure_code := 'LEGACY_OUTCOME_UNKNOWN';
    v_failure_summary := 'This saved action does not include a target snapshot. Office review is required before it can run.';
  ELSIF p_entity_snapshot_at IS NOT NULL
        AND v_target_updated_at IS DISTINCT FROM p_entity_snapshot_at THEN
    v_initial_status := 'needs_review';
    v_failure_code := 'TARGET_STATE_CONFLICT';
    v_failure_summary := 'The delivery or job changed after this action was saved offline. Office review is required.';
  ELSIF v_payload_requires_review THEN
    v_initial_status := 'needs_review';
    v_failure_code := 'PAYLOAD_INVALID';
    v_failure_summary := v_payload_review_summary;
  END IF;

  INSERT INTO public.offline_action_receipts (
    client_action_id, actor_id, operation, entity_id, schema_version,
    client_created_at, entity_snapshot_at, request_payload, idempotency_key,
    status, failure_code, failure_summary, needs_review_at
  ) VALUES (
    p_client_action_id, v_actor, p_operation, p_entity_id, p_schema_version,
    p_client_created_at, p_entity_snapshot_at, v_canonical, p_idempotency_key,
    v_initial_status, v_failure_code, v_failure_summary,
    CASE WHEN v_initial_status = 'needs_review' THEN v_now ELSE NULL END
  )
  ON CONFLICT DO NOTHING;

  SELECT *
    INTO v_existing
    FROM public.offline_action_receipts r
   WHERE r.client_action_id = p_client_action_id;

  IF NOT FOUND THEN
    IF EXISTS (
      SELECT 1
      FROM public.offline_action_receipts r
      WHERE r.idempotency_key = p_idempotency_key
    ) THEN
      RAISE EXCEPTION 'IDEMPOTENCY_KEY_REUSE';
    END IF;
    RAISE EXCEPTION 'OFFLINE_STAGE_CONFLICT';
  END IF;

  IF v_existing.actor_id IS DISTINCT FROM v_actor
     OR v_existing.operation IS DISTINCT FROM p_operation
     OR v_existing.entity_id IS DISTINCT FROM p_entity_id
     OR v_existing.schema_version IS DISTINCT FROM p_schema_version
     OR v_existing.client_created_at IS DISTINCT FROM p_client_created_at
     OR v_existing.entity_snapshot_at IS DISTINCT FROM p_entity_snapshot_at
     OR v_existing.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_existing.request_payload IS DISTINCT FROM v_canonical THEN
    RAISE EXCEPTION 'OFFLINE_ACTION_ID_REUSE';
  END IF;

  RETURN jsonb_build_object(
    'client_action_id', v_existing.client_action_id,
    'operation', v_existing.operation,
    'entity_id', v_existing.entity_id,
    'status', v_existing.status,
    'result', v_existing.result,
    'failure_code', v_existing.failure_code,
    'failure_summary', v_existing.failure_summary,
    'attempt_count', v_existing.attempt_count,
    'client_created_at', v_existing.client_created_at,
    'received_at', v_existing.received_at,
    'updated_at', v_existing.updated_at
  );
END;
$_$;


ALTER FUNCTION "public"."stage_offline_action"("p_client_action_id" "uuid", "p_operation" "text", "p_entity_id" "uuid", "p_schema_version" integer, "p_client_created_at" timestamp with time zone, "p_payload" "jsonb", "p_idempotency_key" "text", "p_entity_snapshot_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."stage_offline_action"("p_client_action_id" "uuid", "p_operation" "text", "p_entity_id" "uuid", "p_schema_version" integer, "p_client_created_at" timestamp with time zone, "p_payload" "jsonb", "p_idempotency_key" "text", "p_entity_snapshot_at" timestamp with time zone) IS 'Validates and permanently stages one approved offline completion under an immutable client UUID.';



CREATE OR REPLACE FUNCTION "public"."stage_supplier_price_import"("p_vendor_id" "uuid", "p_document_date" "date", "p_ingestion_method" "text", "p_format_version" "text", "p_source_document_path" "text", "p_source_document_name" "text", "p_source_document_mime" "text", "p_rows" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_request_fp text;
  v_import_id uuid;
  v_row jsonb;
  v_sequence integer;
  v_link public.product_supplier_links%ROWTYPE;
  v_cost_cents bigint;
  v_effective_from date;
  v_effective_to date;
  v_package_quantity numeric(20,8);
  v_price_kind text;
  v_price_unit text;
  v_status text;
  v_errors text[];
  v_link_id uuid;
  v_result jsonb;
  v_row_count integer;
  v_eligible_count integer;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;
  IF p_document_date IS NULL THEN RAISE EXCEPTION 'DOCUMENT_DATE_REQUIRED'; END IF;
  IF p_ingestion_method NOT IN ('quote_sheet', 'quick_quote') THEN
    RAISE EXCEPTION 'SUPPLIER_INGESTION_METHOD_INVALID';
  END IF;
  IF NULLIF(btrim(p_format_version), '') IS NULL THEN
    RAISE EXCEPTION 'SUPPLIER_FORMAT_VERSION_REQUIRED';
  END IF;
  IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'SUPPLIER_IMPORT_ROWS_REQUIRED';
  END IF;
  v_row_count := jsonb_array_length(p_rows);
  IF v_row_count < 1 OR v_row_count > 5000 THEN
    RAISE EXCEPTION 'SUPPLIER_IMPORT_ROW_COUNT_INVALID';
  END IF;
  IF p_source_document_path IS NOT NULL AND (
    NULLIF(btrim(COALESCE(p_source_document_name, '')), '') IS NULL
    OR p_source_document_mime IS DISTINCT FROM 'application/pdf'
  ) THEN
    RAISE EXCEPTION 'SUPPLIER_SOURCE_DOCUMENT_INVALID';
  END IF;
  IF p_source_document_path IS NOT NULL AND (
    split_part(p_source_document_path, '/', 1) IS DISTINCT FROM v_actor::text
    OR NOT EXISTS (
      SELECT 1
      FROM storage.objects object
      WHERE object.bucket_id = 'supplier-price-evidence'
        AND object.name = p_source_document_path
    )
  ) THEN
    RAISE EXCEPTION 'SUPPLIER_SOURCE_DOCUMENT_NOT_OWNED';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.vendors WHERE id = p_vendor_id AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'VENDOR_NOT_FOUND';
  END IF;

  v_request_fp := md5(jsonb_build_object(
    'actor_id', v_actor,
    'vendor_id', p_vendor_id,
    'document_date', p_document_date,
    'ingestion_method', p_ingestion_method,
    'format_version', p_format_version,
    'source_document_path', p_source_document_path,
    'rows', p_rows
  )::text);
  v_existing := public.check_idempotency(p_idempotency_key, 'stage_supplier_price_import');
  IF v_existing IS NOT NULL THEN
    IF v_existing->>'actor_id' IS DISTINCT FROM v_actor::text
       OR v_existing->>'request_fingerprint' IS DISTINCT FROM v_request_fp THEN
      RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH';
    END IF;
    RETURN v_existing->'response';
  END IF;

  INSERT INTO public.supplier_price_imports(
    vendor_id, document_date, ingestion_method, format_version, status,
    source_document_path, source_document_name, source_document_mime,
    request_fingerprint, idempotency_key, row_count, created_by
  ) VALUES (
    p_vendor_id, p_document_date, p_ingestion_method, p_format_version, 'draft',
    NULLIF(btrim(COALESCE(p_source_document_path, '')), ''),
    NULLIF(btrim(COALESCE(p_source_document_name, '')), ''),
    NULLIF(btrim(COALESCE(p_source_document_mime, '')), ''),
    v_request_fp, p_idempotency_key, v_row_count, v_actor
  ) RETURNING id INTO v_import_id;

  FOR v_row, v_sequence IN
    SELECT value, ordinality::integer
    FROM jsonb_array_elements(p_rows) WITH ORDINALITY
  LOOP
    v_errors := ARRAY[]::text[];
    v_status := 'new';
    v_cost_cents := NULL;
    v_effective_from := NULL;
    v_effective_to := NULL;
    v_package_quantity := NULL;
    v_link_id := NULL;
    v_link := NULL;
    v_price_kind := lower(COALESCE(NULLIF(btrim(v_row->>'price_kind'), ''), 'quote'));
    v_price_unit := NULLIF(btrim(COALESCE(v_row->>'price_unit', '')), '');

    IF lower(COALESCE(v_row->>'has_formula', 'false')) = 'true' THEN
      v_errors := array_append(v_errors, 'FORMULA_NOT_ALLOWED');
    END IF;

    BEGIN
      v_link_id := NULLIF(btrim(COALESCE(v_row->>'product_supplier_link_id', '')), '')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      v_errors := array_append(v_errors, 'LINK_ID_INVALID');
    END;

    IF v_link_id IS NOT NULL THEN
      SELECT * INTO v_link
      FROM public.product_supplier_links
      WHERE id = v_link_id AND is_active;
      IF NOT FOUND OR v_link.vendor_id IS DISTINCT FROM p_vendor_id THEN
        v_errors := array_append(v_errors, 'LINK_VENDOR_MISMATCH');
        v_link_id := NULL;
        v_link := NULL;
      ELSIF NOT v_link.is_reusable THEN
        v_errors := array_append(v_errors, 'LINK_NOT_CONFIRMED_FOR_REUSE');
      ELSE
        IF v_price_unit IS NULL THEN v_price_unit := v_link.supplier_uom; END IF;
      END IF;
    ELSE
      v_errors := array_append(v_errors, 'LINK_REQUIRED');
    END IF;

    BEGIN
      v_cost_cents := public._parse_pricing_dollars(btrim(COALESCE(v_row->>'new_cost', '')));
      IF v_cost_cents <= 0 THEN
        v_errors := array_append(v_errors, 'COST_MUST_BE_POSITIVE');
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := array_append(v_errors, 'COST_INVALID');
      v_cost_cents := NULL;
    END;

    IF v_price_kind NOT IN ('list', 'quote', 'contract', 'promo', 'manual') THEN
      v_errors := array_append(v_errors, 'PRICE_KIND_INVALID');
      v_price_kind := NULL;
    END IF;
    IF v_price_unit IS NULL THEN
      v_errors := array_append(v_errors, 'PRICE_UNIT_REQUIRED');
    END IF;

    BEGIN
      v_package_quantity := COALESCE(NULLIF(btrim(v_row->>'package_quantity'), '')::numeric, 1);
      IF v_package_quantity <= 0 THEN
        v_errors := array_append(v_errors, 'PACKAGE_QUANTITY_INVALID');
      END IF;
    EXCEPTION WHEN numeric_value_out_of_range OR invalid_text_representation THEN
      v_errors := array_append(v_errors, 'PACKAGE_QUANTITY_INVALID');
      v_package_quantity := NULL;
    END;

    BEGIN
      v_effective_from := COALESCE(NULLIF(btrim(v_row->>'effective_date'), '')::date, p_document_date);
      v_effective_to := NULLIF(btrim(COALESCE(v_row->>'effective_to', '')), '')::date;
      IF v_effective_to IS NOT NULL AND v_effective_to < v_effective_from THEN
        v_errors := array_append(v_errors, 'EFFECTIVE_RANGE_INVALID');
      END IF;
    EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN
      v_errors := array_append(v_errors, 'EFFECTIVE_DATE_INVALID');
      v_effective_from := NULL;
      v_effective_to := NULL;
    END;

    IF cardinality(v_errors) > 0 THEN
      v_status := 'invalid';
    ELSIF EXISTS (
      SELECT 1 FROM public.supplier_price_import_rows prior
      WHERE prior.import_id = v_import_id
        AND prior.product_supplier_link_id = v_link_id
        AND prior.cost_cents = v_cost_cents
        AND prior.effective_from = v_effective_from
        AND prior.price_kind = v_price_kind
    ) THEN
      v_status := 'duplicate';
    ELSIF EXISTS (
      SELECT 1 FROM public.supplier_price_observations o
      WHERE o.product_supplier_link_id = v_link_id
        AND o.cost_cents = v_cost_cents
        AND o.effective_from = v_effective_from
        AND o.price_kind = v_price_kind
        AND o.price_unit = v_price_unit
        AND o.package_quantity = v_package_quantity
    ) THEN
      v_status := 'unchanged';
    ELSIF v_link.comparison_status <> 'comparable' THEN
      v_status := 'cannot_compare';
    ELSIF EXISTS (
      SELECT 1
      FROM public.supplier_price_observations o
      WHERE o.product_supplier_link_id = v_link_id
    ) THEN
      v_status := 'changed';
    END IF;

    INSERT INTO public.supplier_price_import_rows(
      import_id, row_number, submitted_row,
      product_id, vendor_id, product_supplier_link_id,
      supplier_sku, supplier_product_name,
      cost_cents, price_unit, package_quantity,
      effective_from, effective_to, price_kind,
      row_status, validation_errors
    ) VALUES (
      v_import_id, v_sequence, v_row,
      CASE WHEN v_link_id IS NULL THEN NULL ELSE v_link.product_id END,
      CASE WHEN v_link_id IS NULL THEN NULL ELSE p_vendor_id END,
      v_link_id,
      CASE WHEN v_link_id IS NULL THEN NULL ELSE v_link.supplier_sku END,
      CASE WHEN v_link_id IS NULL THEN NULL ELSE v_link.supplier_product_name END,
      v_cost_cents, v_price_unit, v_package_quantity,
      v_effective_from, v_effective_to, v_price_kind,
      v_status, v_errors
    );
  END LOOP;

  SELECT count(*)::integer INTO v_eligible_count
  FROM public.supplier_price_import_rows
  WHERE import_id = v_import_id
    AND row_status IN ('new', 'changed', 'cannot_compare');

  UPDATE public.supplier_price_imports
  SET status = 'needs_review',
      eligible_row_count = v_eligible_count
  WHERE id = v_import_id;

  v_result := public.get_supplier_price_import(v_import_id);
  PERFORM public.save_idempotency(
    p_idempotency_key,
    'stage_supplier_price_import',
    jsonb_build_object(
      'actor_id', v_actor,
      'request_fingerprint', v_request_fp,
      'response', v_result
    )
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."stage_supplier_price_import"("p_vendor_id" "uuid", "p_document_date" "date", "p_ingestion_method" "text", "p_format_version" "text", "p_source_document_path" "text", "p_source_document_name" "text", "p_source_document_mime" "text", "p_rows" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stage_vendor_alias"("p_alias_raw" "text", "p_alias_display" "text", "p_proposed_vendor_id" "uuid", "p_source" "text", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_request_fp text;
  v_alias_id uuid;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;
  IF NULLIF(btrim(p_alias_raw), '') IS NULL OR NULLIF(btrim(p_alias_display), '') IS NULL THEN
    RAISE EXCEPTION 'VENDOR_ALIAS_TEXT_REQUIRED';
  END IF;
  IF p_source NOT IN ('legacy_product', 'legacy_po', 'import', 'manual') THEN
    RAISE EXCEPTION 'VENDOR_ALIAS_SOURCE_INVALID';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.vendors WHERE id = p_proposed_vendor_id AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'VENDOR_NOT_FOUND';
  END IF;

  v_request_fp := md5(jsonb_build_object(
    'actor_id', v_actor,
    'alias_raw', p_alias_raw,
    'alias_display', p_alias_display,
    'proposed_vendor_id', p_proposed_vendor_id,
    'source', p_source
  )::text);
  v_existing := public.check_idempotency(p_idempotency_key, 'stage_vendor_alias');
  IF v_existing IS NOT NULL THEN
    IF v_existing->>'actor_id' IS DISTINCT FROM v_actor::text
       OR v_existing->>'request_fingerprint' IS DISTINCT FROM v_request_fp THEN
      RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH';
    END IF;
    RETURN v_existing->'response';
  END IF;

  INSERT INTO public.vendor_aliases(
    proposed_vendor_id, alias_raw, alias_display, source,
    review_status, created_by
  ) VALUES (
    p_proposed_vendor_id, btrim(p_alias_raw), btrim(p_alias_display), p_source,
    'pending', v_actor
  ) RETURNING id INTO v_alias_id;

  SELECT to_jsonb(a) INTO v_result
  FROM public.vendor_aliases a WHERE a.id = v_alias_id;
  PERFORM public.save_idempotency(
    p_idempotency_key,
    'stage_vendor_alias',
    jsonb_build_object('actor_id', v_actor, 'request_fingerprint', v_request_fp, 'response', v_result)
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."stage_vendor_alias"("p_alias_raw" "text", "p_alias_display" "text", "p_proposed_vendor_id" "uuid", "p_source" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stamp_job_printed"("p_job_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cached jsonb;
BEGIN
  -- Visibility gate FIRST (Codex P2 hardening: never serve a cached replay to a
  -- caller who can't see the job). Mirror jobs_select (admin / sales / assigned
  -- applicator) plus jobs_select_location_dispatchee (_is_dispatched_to_me).
  -- Anyone who can read the job can print it, so they must be able to record
  -- that they did.
  IF NOT EXISTS (
    SELECT 1 FROM public.jobs j
    WHERE j.id = p_job_id
      AND (
        is_admin()
        OR is_sales_rep()
        OR (is_applicator() AND j.applicator_id = (SELECT auth.uid()))
        OR _is_dispatched_to_me(j.id)
      )
  ) THEN
    RETURN json_build_object('success', false, 'error', 'Job not found or not visible');
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_cached := check_idempotency(p_idempotency_key, 'stamp_job_printed');
    IF v_cached IS NOT NULL THEN
      -- Codex P2 hardening: check_idempotency keys on (key, operation) only, so a
      -- reused key with a DIFFERENT job must not replay the other job's result.
      IF v_cached->>'job_id' IS DISTINCT FROM p_job_id::text THEN
        RETURN json_build_object('success', false, 'error', 'IDEMPOTENCY_ARGUMENT_MISMATCH');
      END IF;
      RETURN v_cached::json;
    END IF;
  END IF;

  UPDATE public.jobs
     SET printed_at = now(),
         last_printed_by = (SELECT auth.uid())
   WHERE id = p_job_id;

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'stamp_job_printed',
      jsonb_build_object('success', true, 'job_id', p_job_id));
  END IF;

  RETURN json_build_object('success', true, 'job_id', p_job_id);
END;
$$;


ALTER FUNCTION "public"."stamp_job_printed"("p_job_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."stamp_job_printed"("p_job_id" "uuid", "p_idempotency_key" "text") IS 'Records the print audit (printed_at + last_printed_by) for any user who can see the job. SECURITY DEFINER because jobs_update RLS is admin/sales-only.';



CREATE OR REPLACE FUNCTION "public"."start_job"("p_job_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor     uuid := auth.uid();
  v_existing  jsonb;
  v_job       record;
  v_now       timestamptz := now();
  v_result    jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key AND operation = 'start_job';
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_job FROM jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found: %', p_job_id;
  END IF;

  -- U12: widened with an OR branch (superset — nothing previously authorized
  -- loses access). A per-location-only dispatchee (job_location_dispatches,
  -- #36/#37) is now ALSO authorized to start the job, mirroring the visibility
  -- grant _is_dispatched_to_me already gives them for reading it.
  IF NOT (
    is_admin() OR is_sales_rep()
    -- NULL-SAFE (U12 live-verify finding): when jobs.applicator_id IS NULL this
    -- comparison yielded NULL, and IF NOT (NULL) skips the RAISE — any active
    -- applicator could start/complete a NULL-applicator job. Wrap it so the
    -- branch is FALSE, not NULL, and authorization falls through to the
    -- dispatch-based branch (which is already null-safe).
    OR (is_applicator() AND v_job.applicator_id IS NOT NULL AND v_job.applicator_id = v_actor)
    OR (is_applicator() AND public._is_dispatched_to_me(p_job_id))
  ) THEN
    RAISE EXCEPTION 'Not authorized to start this job';
  END IF;

  IF v_job.status = 'in_progress' THEN
    v_result := jsonb_build_object(
      'job_id', p_job_id,
      'status', 'in_progress',
      'started_at', (SELECT actual_start_time FROM job_applied_info WHERE job_id = p_job_id),
      'already_started', true
    );
    IF p_idempotency_key IS NOT NULL THEN
      INSERT INTO idempotency_keys (idempotency_key, operation, result)
      VALUES (p_idempotency_key, 'start_job', v_result)
      ON CONFLICT (idempotency_key) DO NOTHING;
    END IF;
    RETURN v_result;
  END IF;

  IF v_job.status != 'scheduled' THEN
    RAISE EXCEPTION 'Cannot start job — current status is %, expected scheduled', v_job.status;
  END IF;

  UPDATE jobs SET status = 'in_progress' WHERE id = p_job_id;

  INSERT INTO job_applied_info (job_id, actual_start_time)
  VALUES (p_job_id, v_now)
  ON CONFLICT (job_id) DO UPDATE SET
    actual_start_time = COALESCE(job_applied_info.actual_start_time, EXCLUDED.actual_start_time);

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'job_started',
    'Job ' || v_job.job_number || ' started',
    p_performed_by, 'job', p_job_id, v_job.customer_id
  );

  v_result := jsonb_build_object(
    'job_id', p_job_id,
    'status', 'in_progress',
    'started_at', v_now,
    'already_started', false
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'start_job', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."start_job"("p_job_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."start_job"("p_job_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Phase 2 (2026-04-30): transitions a job from scheduled to in_progress and stamps job_applied_info.actual_start_time. Idempotent.';



CREATE OR REPLACE FUNCTION "public"."submit_purchase_order"("p_po_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_status text;
  v_po_number text;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'submit_purchase_order');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT status, po_number
    INTO v_status, v_po_number
  FROM purchase_orders
  WHERE id = p_po_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'PURCHASE_ORDER_NOT_FOUND'; END IF;
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'PO_SUBMIT_REQUIRES_DRAFT: %', v_status;
  END IF;

  UPDATE purchase_orders
  SET status = 'submitted',
      submitted_date = (now() AT TIME ZONE 'America/Chicago')::date,
      updated_at = now()
  WHERE id = p_po_id;

  INSERT INTO activity_feed (
    event_type, description, performed_by, related_entity_type, related_entity_id
  ) VALUES (
    'po_submitted',
    'PO ' || COALESCE(v_po_number, '') || ' submitted',
    v_actor, 'purchase_order', p_po_id
  );

  v_result := jsonb_build_object('status', 'submitted', 'po_id', p_po_id);
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'submit_purchase_order', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."submit_purchase_order"("p_po_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supersede_customer_fact"("p_fact_id" "uuid", "p_value_text" "text", "p_value_json" "jsonb", "p_confidence" numeric, "p_expires_at" timestamp with time zone, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_fact public.customer_facts%ROWTYPE;
  v_new_fact_id uuid;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  IF (p_value_text IS NULL) = (p_value_json IS NULL)
     OR (p_value_text IS NOT NULL AND btrim(p_value_text) = '')
     OR (p_value_json IS NOT NULL AND jsonb_typeof(p_value_json) NOT IN ('object', 'array'))
     OR (p_confidence IS NOT NULL AND p_confidence NOT BETWEEN 0 AND 1) THEN
    RAISE EXCEPTION 'FACT_VALUE_INVALID';
  END IF;

  SELECT * INTO v_fact FROM public.customer_facts WHERE id = p_fact_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FACT_NOT_FOUND'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.is_active)
     OR NOT (public.is_admin() OR (public.is_sales_rep() AND EXISTS (
       SELECT 1 FROM public.customers c
       WHERE c.id = v_fact.customer_id AND c.assigned_sales_rep = auth.uid()
     ))) THEN
    RAISE EXCEPTION 'FACT_ACCESS_DENIED';
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'supersede_customer_fact');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;
  -- Time-sensitive validation sits AFTER the idempotency replay (Codex r2): a committed call
  -- whose short expiry has since passed must replay its committed result on retry, not error.
  IF p_expires_at IS NOT NULL AND p_expires_at <= now() THEN
    RAISE EXCEPTION 'FACT_EXPIRY_INVALID';
  END IF;
  IF v_fact.status <> 'verified' OR v_fact.superseded_at IS NOT NULL THEN
    RAISE EXCEPTION 'FACT_NOT_CURRENT_VERIFIED';
  END IF;

  -- Three-step order: the self-FK on superseded_by is NOT deferrable, so the
  -- replacement row must exist before the old row can reference it — and the
  -- old row must leave the current-verified partial unique index before the
  -- replacement can enter it. (1) retire old, (2) insert new, (3) link.
  v_new_fact_id := gen_random_uuid();
  UPDATE public.customer_facts
  SET superseded_at = now()
  WHERE id = v_fact.id;

  INSERT INTO public.customer_facts (
    id,
    customer_id, category, fact_key, value_text, value_json, confidence,
    status, source, entered_by, reviewed_by, reviewed_at, expires_at
  ) VALUES (
    v_new_fact_id, v_fact.customer_id, v_fact.category, v_fact.fact_key, p_value_text, p_value_json, p_confidence,
    'verified', 'rep', auth.uid(), auth.uid(), now(), p_expires_at
  );

  UPDATE public.customer_facts
  SET superseded_by = v_new_fact_id
  WHERE id = v_fact.id;

  v_result := jsonb_build_object('success', true, 'fact_id', v_fact.id, 'replacement_fact_id', v_new_fact_id);
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(p_idempotency_key, 'supersede_customer_fact', v_result);
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."supersede_customer_fact"("p_fact_id" "uuid", "p_value_text" "text", "p_value_json" "jsonb", "p_confidence" numeric, "p_expires_at" timestamp with time zone, "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."supersede_customer_fact"("p_fact_id" "uuid", "p_value_text" "text", "p_value_json" "jsonb", "p_confidence" numeric, "p_expires_at" timestamp with time zone, "p_idempotency_key" "text") IS 'Replaces one current verified fact atomically with a new self-verified rep fact carrying an explicit replacement expiry.';



CREATE OR REPLACE FUNCTION "public"."sync_blend_ticket_payment_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.blend_ticket_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.status IN ('voided', 'cancelled') AND OLD.status NOT IN ('voided', 'cancelled') THEN
    -- Over-reset guard (overnight bug-hunt HIGH, 20260620): only reset the ticket to
    -- 'unbilled' when NO live sibling invoice remains. A multi-customer blend ticket has
    -- multiple invoices sharing this blend_ticket_id; without this guard, voiding one
    -- customer's invoice re-opens the whole ticket and the next create_invoice_from_
    -- blend_ticket double-bills every customer. NEW is already voided/cancelled here, so
    -- it is excluded by the status filter below.
    UPDATE blend_tickets SET payment_status = 'unbilled', updated_at = now()
    WHERE id = NEW.blend_ticket_id AND payment_status = 'billed'
      AND NOT EXISTS (
        SELECT 1 FROM invoices i
        WHERE i.blend_ticket_id = NEW.blend_ticket_id
          AND i.status NOT IN ('voided', 'cancelled')
          AND i.deleted_at IS NULL
      );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_blend_ticket_payment_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_customer_to_primary_contact"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  IF btrim(coalesce(NEW.contact_name, '')) = ''
     AND btrim(coalesce(NEW.phone, '')) = ''
     AND btrim(coalesce(NEW.email, '')) = '' THEN
    -- All legacy contact info cleared: retire the auto-synced primary contact
    -- rather than leave it active with stale data. (identity_present CHECK
    -- forbids blanking the row in place; deactivation preserves history.)
    UPDATE public.customer_contacts
    SET is_primary = false,
        is_active = false
    WHERE customer_id = NEW.id
      AND is_primary;
    RETURN NEW;
  END IF;

  INSERT INTO public.customer_contacts (
    customer_id, name, phone_display, phone_e164, email, is_primary
  )
  VALUES (
    NEW.id,
    nullif(btrim(NEW.contact_name), ''),
    nullif(btrim(NEW.phone), ''),
    public.normalize_phone_e164(NEW.phone),
    nullif(btrim(NEW.email), ''),
    true
  )
  ON CONFLICT (customer_id) WHERE is_primary DO UPDATE
  SET name = EXCLUDED.name,
      phone_display = EXCLUDED.phone_display,
      phone_e164 = EXCLUDED.phone_e164,
      email = EXCLUDED.email
  WHERE customer_contacts.name IS DISTINCT FROM EXCLUDED.name
     OR customer_contacts.phone_display IS DISTINCT FROM EXCLUDED.phone_display
     OR customer_contacts.phone_e164 IS DISTINCT FROM EXCLUDED.phone_e164
     OR customer_contacts.email IS DISTINCT FROM EXCLUDED.email;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_customer_to_primary_contact"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_primary_contact_to_customer"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  UPDATE public.customers c
  SET contact_name = NEW.name,
      phone = NEW.phone_display,
      email = NEW.email
  WHERE c.id = NEW.customer_id
    AND (
      c.contact_name IS DISTINCT FROM NEW.name
      OR c.phone IS DISTINCT FROM NEW.phone_display
      OR c.email IS DISTINCT FROM NEW.email
    );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_primary_contact_to_customer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."touch_blend_ticket_product_parent_version"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ticket_ids uuid[];
BEGIN
  v_ticket_ids := CASE
    WHEN TG_OP = 'INSERT' THEN ARRAY[NEW.blend_ticket_id]
    WHEN TG_OP = 'DELETE' THEN ARRAY[OLD.blend_ticket_id]
    ELSE ARRAY[OLD.blend_ticket_id, NEW.blend_ticket_id]
  END;

  PERFORM id
    FROM public.blend_tickets
   WHERE id = ANY(v_ticket_ids)
   ORDER BY id
   FOR UPDATE;

  UPDATE public.blend_tickets
     SET updated_at = clock_timestamp()
   WHERE id = ANY(v_ticket_ids);

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION "public"."touch_blend_ticket_product_parent_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_invoice_to_job"("p_invoice_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_inv RECORD;
  v_job RECORD;
  v_existing jsonb;
  v_result jsonb;
  v_actor_role text;
  v_commissions_cancelled integer := 0;  -- U8 (#99)
BEGIN
  -- Role gate (active admin/sales_rep) on the authenticated user.
  SELECT role INTO v_actor_role FROM profiles
    WHERE id = auth.uid() AND is_active = true AND role IN ('admin','sales_rep');
  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized: requires admin,sales_rep role';
  END IF;

  -- Strict actor: the recorded performer must be the authenticated user
  -- (mirrors transfer_job_to_invoice / complete_job / save_field_app_invoice).
  IF p_performed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH: p_performed_by must match the authenticated user';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'transfer_invoice_to_job');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_inv FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found: %', p_invoice_id; END IF;

  IF v_inv.invoice_type IS DISTINCT FROM 'field_application' THEN
    RAISE EXCEPTION 'Only a field application invoice can be transferred back to a job';
  END IF;
  IF v_inv.job_id IS NULL THEN
    RAISE EXCEPTION 'This invoice was not created from a job, so it cannot be returned to scheduling';
  END IF;
  IF v_inv.status NOT IN ('draft', 'unposted') THEN
    RAISE EXCEPTION 'Only a draft or unposted invoice can be returned to scheduling (status: %). Void the invoice first.', v_inv.status;
  END IF;

  -- Lock the source job and confirm it still owns this invoice (no race / double reverse).
  SELECT * INTO v_job FROM jobs WHERE id = v_inv.job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Source job not found: %', v_inv.job_id; END IF;
  IF v_job.status <> 'invoiced' THEN
    RAISE EXCEPTION 'Source job % is no longer invoiced (status: %); cannot return this invoice to scheduling', v_job.job_number, v_job.status;
  END IF;
  IF v_job.invoice_id IS DISTINCT FROM p_invoice_id THEN
    RAISE EXCEPTION 'Source job % no longer points at this invoice; refusing to reverse', v_job.job_number;
  END IF;

  -- U7: a multi-owner split cannot be reversed member-by-member here (it would release the
  -- job while sibling owner-invoices stay live). Direct the office to void the owner
  -- invoices instead -- voiding the LAST live member reopens the job (group-aware void).
  IF v_inv.invoice_group_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM invoices o
    WHERE o.job_id = v_inv.job_id AND o.id <> p_invoice_id
      AND o.invoice_type = 'field_application'
      AND o.status NOT IN ('voided', 'cancelled') AND o.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'JOB_BILLED_AS_GROUP: job % was invoiced as a multi-owner split; return it to scheduling by voiding each owner invoice (voiding the last one reopens the job).', v_job.job_number;
  END IF;

  -- Detach the as-applied legal records from this invoice (inverse of the forward
  -- UPDATE application_records SET invoice_id = v_invoice_id ...).
  UPDATE application_records SET invoice_id = NULL
    WHERE source_type = 'job' AND source_id = v_inv.job_id AND invoice_id = p_invoice_id;

  -- Tear down the invoice contents the forward transfer built.
  DELETE FROM invoice_shares WHERE invoice_id = p_invoice_id;
  DELETE FROM invoice_items  WHERE invoice_id = p_invoice_id;

  -- Cancel the invoice (draft|unposted -> cancelled is an allowed transition; no override).
  -- total/paid/prepay are already 0 on a never-posted invoice; zero them defensively.
  -- total_cost_cents (the internal COGS header) is ALSO zeroed here (P3 remediation) so a
  -- cancelled, line-less invoice does not keep a stale forward cost total on its PDF.
  UPDATE invoices SET
    status = 'cancelled',
    void_reason = 'Returned to scheduling (job ' || v_job.job_number || ')',
    total_amount_cents = 0,
    paid_amount_cents = 0,
    prepay_applied_cents = 0,
    total_cost_cents = 0,
    updated_at = now()
  WHERE id = p_invoice_id;

  -- U8<<< (#99): the forward transfer minted this invoice's pending commissions —
  -- reverse them with it (a re-transfer creates a fresh pending set). Codex R1 P1:
  -- scoped by commissions.invoice_id so only THIS invoice's generation is touched.
  -- Codex R6 P1: order-channel payout protections (batched-pending blocks; paid
  -- rows stay + admins notified).
  IF EXISTS (
    SELECT 1 FROM commissions c
    JOIN commission_payment_items cpi ON cpi.commission_id = c.id
    JOIN commission_payments cp ON cp.id = cpi.commission_payment_id
    WHERE c.job_id = v_inv.job_id AND c.invoice_id = p_invoice_id
      AND c.status = 'pending' AND cp.status <> 'voided'
  ) THEN
    RAISE EXCEPTION 'JOB_HAS_BATCHED_COMMISSIONS: this job invoice''s pending commissions are in an active payout batch — void that commission payment first';
  END IF;
  IF EXISTS (
    SELECT 1 FROM commissions
    WHERE job_id = v_inv.job_id AND invoice_id = p_invoice_id AND status = 'paid'
  ) THEN
    INSERT INTO notifications (user_id, title, message, notification_type, related_entity_type, related_entity_id)
    SELECT p.id, 'Job invoice returned to scheduling — commissions already paid',
      'Invoice ' || v_inv.invoice_number || ' was returned to scheduling but its commissions were already paid out. Manual review needed before the job is re-invoiced.',
      'commission_review', 'invoice', p_invoice_id
    FROM profiles p WHERE p.role = 'admin' AND p.is_active = true;
  END IF;
  UPDATE commissions SET status = 'cancelled', commission_amount = 0
    WHERE job_id = v_inv.job_id AND invoice_id = p_invoice_id AND status = 'pending';
  GET DIAGNOSTICS v_commissions_cancelled = ROW_COUNT;
  -- >>>U8

  -- Return the job to 'completed' so it is editable / re-transferable. The reverse
  -- invoiced -> completed transition is only sanctioned via the admin-override GUC
  -- (SET LOCAL = transaction-scoped); RESET immediately after the single UPDATE.
  SET LOCAL app.admin_override = 'true';
  UPDATE jobs SET status = 'completed', invoice_id = NULL WHERE id = v_inv.job_id;
  RESET app.admin_override;

  -- Append-only money ledger: record the cancellation (mirrors void_invoice's
  -- draft/unposted -> cancelled audit row), with the source-job provenance.
  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_user_id, actor_role,
    old_values, new_values, total_impact_cents, description
  ) VALUES (
    'invoice_cancelled', 'invoice', p_invoice_id, auth.uid(), v_actor_role,
    jsonb_build_object('status', v_inv.status, 'total_cents', v_inv.total_amount_cents, 'job_id', v_inv.job_id),
    jsonb_build_object('status', 'cancelled', 'reason', 'transfer_to_scheduling', 'job_id', v_inv.job_id, 'commissions_cancelled', v_commissions_cancelled),
    -1 * COALESCE(v_inv.total_amount_cents, 0),
    'Invoice ' || v_inv.invoice_number || ' returned to scheduling (job ' || v_job.job_number || ')'
  );

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('invoice_transferred_to_scheduling',
    'Invoice ' || v_inv.invoice_number || ' returned to scheduling — job ' || v_job.job_number || ' reopened',
    COALESCE(p_performed_by, auth.uid()), 'job', v_inv.job_id, v_inv.customer_id);

  v_result := jsonb_build_object(
    'success', true,
    'invoice_id', p_invoice_id,
    'job_id', v_inv.job_id,
    'job_number', v_job.job_number,
    'invoice_status', 'cancelled',
    'job_status', 'completed',
    'commissions_cancelled', v_commissions_cancelled
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'transfer_invoice_to_job', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."transfer_invoice_to_job"("p_invoice_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transfer_invoice_to_job"("p_invoice_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Field-app parity #27: reverse of transfer_job_to_invoice. Returns a draft/unposted field_application invoice to its source job (invoice -> cancelled, items/shares deleted, application_records detached, job invoiced -> completed). Cancel path zeroes total_cost_cents too (P3 remediation). Admin/sales_rep, strict-actor, idempotent.';



CREATE OR REPLACE FUNCTION "public"."transfer_job_to_invoice"("p_job_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_job RECORD;
  v_invoice_id uuid;
  v_invoice_number text;
  v_chem RECORD;
  v_item_order integer := 0;
  v_field_names text[];
  v_crop_types text[];
  v_crop_type text;
  v_total_acres numeric := 0;
  v_applicator_name text;
  v_vehicle_name text;
  v_field RECORD;
  v_billing RECORD;
  v_total_cost_cents bigint := 0;
  v_conversion RECORD;
  v_total_applied numeric;
  v_share RECORD;
  v_share_total bigint := 0;
  v_has_price_override boolean := false;
  v_existing jsonb;
  v_result jsonb;
  -- DELTA-8 (G1 per-acre fee) locals
  v_fee jsonb;
  v_fee_total bigint := 0;
  v_fee_cost bigint := 0;
  v_fee_c bigint;
  v_cost_c bigint;
  v_fee_acres numeric := 0;
  -- U8 (#99 commissions on the application channel) locals
  v_commission_split jsonb;
  v_chem_profit_cents bigint := 0;
  -- U7 (#42/#100/#50 multi-owner group) locals
  v_n_owners integer := 0;
  v_group_id uuid;
  v_owner_ids uuid[];
  v_owner_names text[];
  v_owner_acres numeric[];
  v_owner_primary boolean[];
  v_total_billable_acres numeric := 0;
  v_acre_pcts numeric[];
  v_chem_price_split bigint[];
  v_chem_cost_split bigint[];
  v_oidx integer;
  v_member_id uuid;
  v_member_ids uuid[] := '{}';
  v_anchor_id uuid;
  v_member_acres numeric;
  v_member_total bigint;
  v_member_cost bigint;
  v_member_profit_cents bigint := 0;
  v_member_field_names text[];
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin','sales_rep')
  ) THEN
    RAISE EXCEPTION 'Not authorized: requires admin,sales_rep role';
  END IF;

  -- BEGIN DELTA-7 (G3 strict-actor): the role gate above is on auth.uid(), but
  -- p_performed_by was written verbatim to created_by / the activity log, so the
  -- recorded performer was forgeable. Bind the authenticated user and reject a
  -- mismatch (matches complete_job / start_job / save_field_app_invoice).
  IF p_performed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH: p_performed_by must match the authenticated user';
  END IF;
  -- END DELTA-7

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'transfer_job_to_invoice');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT j.* INTO v_job FROM jobs j WHERE j.id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Job not found: %', p_job_id; END IF;
  IF v_job.status = 'invoiced' THEN RAISE EXCEPTION 'Job already invoiced'; END IF;
  IF v_job.status != 'completed' THEN RAISE EXCEPTION 'Job must be completed to invoice (status: %)', v_job.status; END IF;

  -- U6 #91b: refuse to invoice the job if a blend ticket for the SAME job has already
  -- been billed (payment_status='billed' = a live, non-voided invoice exists for it).
  -- The blend-ticket invoice and this job invoice bill the same application, so
  -- allowing both double-bills the customer. Block, do not warn. (The
  -- trg_sync_blend_ticket_payment trigger resets billed->unbilled when that invoice
  -- is voided, so a genuine re-bill after a void is unaffected.)
  -- Codex R3 P2: test for a LIVE blend-ticket invoice directly (mirror of the
  -- opposite guard's invoices.job_id test) — payment_status can be written
  -- manually via update_blend_ticket_billing_status and drift out of sync.
  IF EXISTS (
    SELECT 1 FROM blend_tickets bt
    JOIN invoices i ON i.blend_ticket_id = bt.id
    WHERE bt.job_id = p_job_id
      AND bt.deleted_at IS NULL  -- Codex R2 P2: a soft-deleted ticket must not block forever
      AND i.status NOT IN ('voided', 'cancelled')
      AND i.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_ALREADY_BILLED: a blend ticket for this job has already been billed; invoicing the job too would double-bill the customer. Void that blend-ticket invoice first if you meant to re-bill here.';
  END IF;

  FOR v_field IN
    SELECT jf.field_id, jf.acres_to_treat, f.field_name, f.crop_type AS f_crop_type
    FROM job_fields jf JOIN fields f ON f.id = jf.field_id
    WHERE jf.job_id = p_job_id ORDER BY f.field_name
  LOOP
    v_field_names := array_append(v_field_names, v_field.field_name);
    v_total_acres := v_total_acres + COALESCE(v_field.acres_to_treat, 0);
    IF v_field.f_crop_type IS NOT NULL THEN v_crop_types := array_append(v_crop_types, v_field.f_crop_type); END IF;
  END LOOP;

  IF v_crop_types IS NOT NULL AND array_length(v_crop_types, 1) > 0 THEN
    SELECT mode() WITHIN GROUP (ORDER BY unnest) INTO v_crop_type FROM unnest(v_crop_types);
  END IF;

  IF v_job.applicator_id IS NOT NULL THEN
    SELECT p.full_name INTO v_applicator_name FROM profiles p WHERE p.id = v_job.applicator_id;
  END IF;

  IF v_job.vehicle_id IS NOT NULL THEN
    SELECT v.vehicle_name INTO v_vehicle_name FROM vehicles v WHERE v.id = v_job.vehicle_id;
  END IF;

  -- ==========================================================================
  -- U7 (#42 / #100 / #50): MULTI-OWNER per-owner invoice GROUP.
  -- Trigger ONLY on EXPLICIT multi-owner billing: >1 distinct field_billing_defaults
  -- customer across the job's fields (the landlord/tenant setup the finding is about).
  -- A job with NO billing defaults keeps today's single-invoice behavior, even if its
  -- fields belong to different customers — no surprise change. In the group path, any
  -- field WITHOUT billing defaults falls back to the field's own customer at 100%
  -- (mirror of create_split_invoices_from_order).
  -- ==========================================================================
  SELECT count(DISTINCT fbd.customer_id) INTO v_n_owners
    FROM job_fields jf JOIN field_billing_defaults fbd ON fbd.field_id = jf.field_id
    WHERE jf.job_id = p_job_id;

  IF COALESCE(v_n_owners, 0) > 1 THEN
    -- Scope guard: per-field $/acre overrides are not supported by the percentage/acre
    -- split. Refuse rather than silently drop an override the single-invoice path honors.
    IF EXISTS (
      SELECT 1 FROM job_fields jf JOIN field_billing_defaults fbd ON fbd.field_id = jf.field_id
      WHERE jf.job_id = p_job_id AND fbd.price_override_cents IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'SPLIT_OVERRIDE_UNSUPPORTED: this multi-owner job has per-field $/acre price overrides. Percentage split billing does not support overrides — bill it as a single invoice, or price each owner in the field-application editor.';
    END IF;

    -- Validate every billed field's splits total 100 (mirror FIELD_SPLIT_NOT_100), so the
    -- owner acre shares sum to the job acres and calculate_billing_splits stays penny-exact.
    IF EXISTS (
      SELECT 1 FROM job_fields jf JOIN field_billing_defaults fbd ON fbd.field_id = jf.field_id
      WHERE jf.job_id = p_job_id
      GROUP BY jf.field_id HAVING sum(fbd.split_pct) < 99.99 OR sum(fbd.split_pct) > 100.01
    ) THEN
      RAISE EXCEPTION 'FIELD_SPLIT_NOT_100: one or more of this job''s fields has billing splits that do not total 100%%. Fix the field billing defaults before invoicing.';
    END IF;

    -- Ordered owner arrays (stable ORDER BY owner_id) with each owner's BILLABLE ACRES:
    -- fbd fields contribute acres_to_treat * split_pct/100; non-fbd fields contribute
    -- their full acres to the field's own customer.
    SELECT array_agg(owner_id ORDER BY owner_id),
           array_agg(farm_name ORDER BY owner_id),
           array_agg(billable_acres ORDER BY owner_id),
           array_agg(is_primary ORDER BY owner_id)
      INTO v_owner_ids, v_owner_names, v_owner_acres, v_owner_primary
    FROM (
      SELECT owner_id,
             sum(billable_acres) AS billable_acres,
             bool_or(is_primary) AS is_primary,
             max(farm_name) AS farm_name
      FROM (
        SELECT fbd.customer_id AS owner_id,
               COALESCE(jf.acres_to_treat, 0) * fbd.split_pct / 100.0 AS billable_acres,
               COALESCE(fbd.is_primary, false) AS is_primary, c.farm_name
          FROM job_fields jf
          JOIN field_billing_defaults fbd ON fbd.field_id = jf.field_id
          JOIN customers c ON c.id = fbd.customer_id
          WHERE jf.job_id = p_job_id
        UNION ALL
        SELECT COALESCE(f.customer_id, v_job.customer_id) AS owner_id,
               COALESCE(jf.acres_to_treat, 0) AS billable_acres,
               false AS is_primary, c.farm_name
          FROM job_fields jf
          JOIN fields f ON f.id = jf.field_id
          JOIN customers c ON c.id = COALESCE(f.customer_id, v_job.customer_id)
          WHERE jf.job_id = p_job_id
            AND NOT EXISTS (SELECT 1 FROM field_billing_defaults fbd2 WHERE fbd2.field_id = jf.field_id)
      ) parts
      GROUP BY owner_id
    ) oa;

    v_total_billable_acres := COALESCE((SELECT sum(a) FROM unnest(v_owner_acres) a), 0);
    IF v_total_billable_acres <= 0 THEN
      RAISE EXCEPTION 'SPLIT_NO_ACRES: cannot split a multi-owner job with zero billable acres (job %)', v_job.job_number;
    END IF;

    -- Acre-share percentages across owners (sum to exactly 100 -> penny-exact splits).
    SELECT array_agg(a / v_total_billable_acres * 100 ORDER BY ord)
      INTO v_acre_pcts FROM unnest(v_owner_acres) WITH ORDINALITY AS u(a, ord);

    v_group_id := gen_random_uuid();

    -- Create one draft invoice per owner (empty; filled in the chemical/fee loops below).
    FOR v_oidx IN 1 .. array_length(v_owner_ids, 1) LOOP
      v_member_acres := v_owner_acres[v_oidx];

      -- Fields this owner is billed for (informational header list).
      SELECT array_agg(DISTINCT fname ORDER BY fname) INTO v_member_field_names FROM (
        SELECT f.field_name AS fname
          FROM job_fields jf JOIN field_billing_defaults fbd ON fbd.field_id = jf.field_id
          JOIN fields f ON f.id = jf.field_id
          WHERE jf.job_id = p_job_id AND fbd.customer_id = v_owner_ids[v_oidx]
        UNION
        SELECT f.field_name AS fname
          FROM job_fields jf JOIN fields f ON f.id = jf.field_id
          WHERE jf.job_id = p_job_id AND f.customer_id = v_owner_ids[v_oidx]
            AND NOT EXISTS (SELECT 1 FROM field_billing_defaults fbd2 WHERE fbd2.field_id = jf.field_id)
      ) mf;

      v_invoice_number := next_invoice_number('field_application');
      INSERT INTO invoices (
        invoice_number, customer_id, invoice_type, status, invoice_date, due_date,
        total_amount_cents, total_cost_cents, paid_amount_cents, prepay_applied_cents,
        field_names, crop_type, total_acres, applicator_name, vehicle_name,
        application_date, header_notes, season, created_by, job_id,
        application_service_id, invoice_group_id
      ) VALUES (
        v_invoice_number, v_owner_ids[v_oidx], 'field_application', 'draft',
        CURRENT_DATE, (CURRENT_DATE + interval '30 days')::date,
        0, 0, 0, 0,
        COALESCE(v_member_field_names, v_field_names), v_crop_type, v_member_acres, v_applicator_name, v_vehicle_name,
        v_job.job_date, v_job.notes,
        COALESCE(
          v_job.season,
          CASE WHEN extract(month FROM CURRENT_DATE) >= 10
               THEN extract(year FROM CURRENT_DATE)::integer + 1
               ELSE extract(year FROM CURRENT_DATE)::integer END
        ),
        p_performed_by, p_job_id, v_job.application_service_id, v_group_id
      ) RETURNING id INTO v_member_id;
      v_member_ids := array_append(v_member_ids, v_member_id);
    END LOOP;

    -- Chemical lines: split each chemical's agreed price/cost across owners BY acre share
    -- (penny-exact). qty / applied-acres are prorated by the same share.
    v_item_order := 0;
    FOR v_chem IN
      SELECT jc.product_id, jc.rate_per_acre,
             safe_cents_qty(jc.cost_per_unit_cents, jc.quantity) AS chem_cost,
             safe_cents_qty(jc.price_per_unit_cents, jc.quantity) AS chem_price,
             jc.quantity,
             jc.customer_supplied,
             p.product_name, p.unit_size, p.epa_registration, p.product_form,
             COALESCE(jc.rate_unit, p.unit_size) AS rate_unit
      FROM job_chemicals jc JOIN products p ON p.id = jc.product_id
      WHERE jc.job_id = p_job_id ORDER BY p.product_name
    LOOP
      v_item_order := v_item_order + 1;
      -- customer-supplied products carry $0 price AND $0 cost (we didn't buy them).
      v_chem_price_split := calculate_billing_splits(
        CASE WHEN v_chem.customer_supplied THEN 0 ELSE COALESCE(v_chem.chem_price, 0) END, v_acre_pcts);
      v_chem_cost_split := calculate_billing_splits(
        CASE WHEN v_chem.customer_supplied THEN 0 ELSE COALESCE(v_chem.chem_cost, 0) END, v_acre_pcts);

      FOR v_oidx IN 1 .. array_length(v_owner_ids, 1) LOOP
        v_member_acres := v_owner_acres[v_oidx];
        -- Owner's applied amount = rate x their acres (their slice of the uniform-rate
        -- application). The line quantity stays 1 (a single job-chemical line, matching
        -- the single-owner path where unit_price == extended); the real applied amount
        -- lives in total_applied / total_applied_gl_lb.
        v_total_applied := CASE WHEN v_chem.rate_per_acre IS NOT NULL AND v_member_acres > 0
          THEN v_chem.rate_per_acre * v_member_acres ELSE NULL END;
        SELECT * INTO v_conversion
          FROM convert_to_gl_lb(v_total_applied, v_chem.rate_unit, v_chem.product_form);

        INSERT INTO invoice_items (
          invoice_id, product_id, description, quantity, unit_size, unit_price_cents, extended_cents,
          cost_cents, sort_order, acres, rate_per_acre, rate_unit,
          total_applied, total_applied_unit, total_applied_gl_lb, gl_lb_unit,
          epa_registration, product_form, is_application_fee, price_source
        ) VALUES (
          v_member_ids[v_oidx], v_chem.product_id,
          CASE WHEN v_chem.customer_supplied THEN v_chem.product_name || ' (customer supplied)' ELSE v_chem.product_name END,
          1,
          v_chem.unit_size,
          v_chem_price_split[v_oidx],
          v_chem_price_split[v_oidx],
          v_chem_cost_split[v_oidx],
          v_item_order, v_member_acres,
          v_chem.rate_per_acre, v_chem.rate_unit, v_total_applied,
          COALESCE(v_chem.rate_unit, v_chem.unit_size),
          v_conversion.converted_value, v_conversion.converted_unit,
          v_chem.epa_registration, v_chem.product_form, false,
          CASE WHEN v_chem.customer_supplied THEN 'manual' ELSE NULL END
        );
      END LOOP;
    END LOOP;

    -- Per-owner totals, per-acre application fee, header flip, and per-member commission.
    FOR v_oidx IN 1 .. array_length(v_owner_ids, 1) LOOP
      v_member_id := v_member_ids[v_oidx];
      v_member_acres := v_owner_acres[v_oidx];

      SELECT COALESCE(SUM(extended_cents), 0), COALESCE(SUM(cost_cents), 0)
        INTO v_member_total, v_member_cost
        FROM invoice_items WHERE invoice_id = v_member_id;

      -- DELTA-8 per-acre machine fee at this owner's own rate, on this owner's acres.
      IF v_job.application_service_id IS NOT NULL AND v_member_acres > 0 THEN
        v_fee := compute_application_service_fee(
                   v_job.application_service_id, v_owner_ids[v_oidx], v_member_acres, v_job.season);
        v_fee_c  := COALESCE((v_fee->>'total_fee_cents')::bigint, 0);
        v_cost_c := COALESCE((v_fee->>'total_cost_cents')::bigint, 0);
        IF v_fee_c > 0 THEN
          v_item_order := v_item_order + 1;
          INSERT INTO invoice_items (
            invoice_id, description, quantity, unit_size, unit_price_cents, extended_cents,
            cost_cents, sort_order, acres, rate_per_acre, rate_unit,
            is_application_fee, price_source
          ) VALUES (
            v_member_id, COALESCE(v_fee->>'service_name', 'Application'), v_member_acres, 'acre',
            ROUND(v_fee_c / v_member_acres)::bigint, v_fee_c,
            v_cost_c, v_item_order, v_member_acres,
            ROUND(v_fee_c / v_member_acres)::bigint, 'acre',
            true, 'tier'
          );
          v_member_total := v_member_total + v_fee_c;
          v_member_cost  := v_member_cost + v_cost_c;
        END IF;
      END IF;

      UPDATE invoices SET total_amount_cents = v_member_total, total_cost_cents = v_member_cost
        WHERE id = v_member_id;

      -- one invoice_shares row (100% of this member -> itself) so statements/year-end read it.
      INSERT INTO invoice_shares (invoice_id, customer_id, customer_name, split_percentage, acres, amount_cents, is_primary, sort_order)
      VALUES (v_member_id, v_owner_ids[v_oidx], v_owner_names[v_oidx], 100.0, v_member_acres, v_member_total,
              COALESCE(v_owner_primary[v_oidx], false), v_oidx);

      -- DELTA-4: draft -> unposted now that the member is fully built.
      UPDATE invoices SET status = 'unposted' WHERE id = v_member_id;
    END LOOP;

    -- Commission split resolution (mirror of the single-owner path: snapshot on the job,
    -- else the parent quote's split, else the customer default for pre-U8 jobs).
    v_commission_split := v_job.commission_split;
    IF v_commission_split IS NULL THEN
      IF v_job.quote_id IS NOT NULL THEN
        SELECT q.commission_split INTO v_commission_split FROM quotes q WHERE q.id = v_job.quote_id;
      ELSE
        SELECT c.default_commission_split INTO v_commission_split FROM customers c WHERE c.id = v_job.customer_id;
      END IF;
    END IF;

    -- Anchor = the primary owner's member (else the first). jobs.invoice_id is a scalar,
    -- so it points at the anchor; siblings are found via invoices.invoice_group_id / job_id.
    -- v_member_ids[i] corresponds to v_owner_ids[i] / v_owner_primary[i] (same build order).
    v_anchor_id := v_member_ids[1];
    FOR v_oidx IN 1 .. array_length(v_owner_ids, 1) LOOP
      IF COALESCE(v_owner_primary[v_oidx], false) THEN
        v_anchor_id := v_member_ids[v_oidx];
        EXIT;
      END IF;
    END LOOP;

    UPDATE jobs SET status = 'invoiced', invoice_id = v_anchor_id,
      commission_split = COALESCE(commission_split, v_commission_split, '{"splits":[]}'::jsonb)
    WHERE id = p_job_id;
    UPDATE application_records SET invoice_id = v_anchor_id WHERE source_type = 'job' AND source_id = p_job_id;

    -- Per-member commission: on THAT member's chemical-line profit (product lines only,
    -- excludes the per-acre fee). Sum across members == the whole job's chemical profit.
    FOR v_oidx IN 1 .. array_length(v_member_ids, 1) LOOP
      v_member_id := v_member_ids[v_oidx];
      SELECT COALESCE(SUM(COALESCE(ii.extended_cents, 0) - COALESCE(ii.cost_cents, 0)), 0)
        INTO v_member_profit_cents
      FROM invoice_items ii
      WHERE ii.invoice_id = v_member_id
        AND COALESCE(ii.is_application_fee, false) = false
        AND ii.product_id IS NOT NULL;

      PERFORM _insert_commissions_for_job(
        p_job_id, v_member_id, v_owner_ids[v_oidx],
        v_member_profit_cents::numeric / 100.0,
        v_commission_split,
        CURRENT_DATE
      );

      -- Per-member creation audit row (mirror of the single path's invoice_created row).
      INSERT INTO financial_audit_log (
        operation_type, entity_type, entity_id, actor_user_id, actor_role,
        new_values, total_impact_cents, description
      ) VALUES (
        'invoice_created', 'invoice', v_member_id, auth.uid(),
        (SELECT role FROM profiles WHERE id = auth.uid()),
        jsonb_build_object(
          'invoice_number', (SELECT invoice_number FROM invoices WHERE id = v_member_id),
          'job_id', p_job_id,
          'customer_id', v_owner_ids[v_oidx],
          'invoice_group_id', v_group_id,
          'total_cents', (SELECT total_amount_cents FROM invoices WHERE id = v_member_id)
        ),
        (SELECT total_amount_cents FROM invoices WHERE id = v_member_id),
        'Split invoice ' || (SELECT invoice_number FROM invoices WHERE id = v_member_id) ||
          ' created from job ' || v_job.job_number || ' (per-owner group)'
      );
    END LOOP;

    INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
    VALUES ('job_invoiced',
      'Job ' || v_job.job_number || ' transferred to a ' || array_length(v_member_ids, 1) ||
        '-owner split invoice group',
      COALESCE(p_performed_by, auth.uid()), 'job', p_job_id, v_job.customer_id);

    v_result := jsonb_build_object(
      'success', true, 'job_id', p_job_id,
      'invoice_id', v_anchor_id,
      'invoice_ids', to_jsonb(v_member_ids),
      'invoice_group_id', v_group_id,
      'invoice_count', array_length(v_member_ids, 1),
      'split', true
    );

    IF p_idempotency_key IS NOT NULL THEN
      PERFORM save_idempotency(p_idempotency_key, 'transfer_job_to_invoice', v_result);
    END IF;

    RETURN v_result;
  END IF;
  -- ================= end multi-owner group path =================

  -- Fail-safe for legacy single-owner defaults that predate the deferred table guard.
  -- Match the multi-owner FIELD_SPLIT_NOT_100 validation before creating any invoice rows.
  IF EXISTS (
    SELECT 1 FROM job_fields jf JOIN field_billing_defaults fbd ON fbd.field_id = jf.field_id
    WHERE jf.job_id = p_job_id
    GROUP BY jf.field_id HAVING sum(fbd.split_pct) < 99.99 OR sum(fbd.split_pct) > 100.01
  ) THEN
    RAISE EXCEPTION 'FIELD_SPLIT_NOT_100: one or more of this job''s fields has billing splits that do not total 100%%. Fix the field billing defaults before invoicing.';
  END IF;

  -- OVERNIGHT FIX (Run 2 cycle 6 — invoice-number canonicalization, Codex-confirmed MEDIUM):
  -- use the shared next_invoice_number() — the SAME invoice_number_seq, 'invoice_number:INV:<year>'
  -- advisory lock, and setval self-heal that every other invoice creator AND the
  -- invoices.invoice_number column default use. The previous inline
  -- `pg_advisory_xact_lock(hashtext('invoice_number'))` + MAX(regexp_replace(...))+1 scan took a
  -- DIFFERENT advisory-lock key, so it did not serialize against other INV creators (two callers
  -- could compute the same number -> 23505 on the UNIQUE index invoices_invoice_number_key,
  -- aborting the transfer) and it never advanced invoice_number_seq.
  v_invoice_number := next_invoice_number('field_application');

  INSERT INTO invoices (
    invoice_number, customer_id, invoice_type, status, invoice_date, due_date,
    total_amount_cents, total_cost_cents, paid_amount_cents, prepay_applied_cents,
    field_names, crop_type, total_acres, applicator_name, vehicle_name,
    application_date, header_notes, season, created_by, job_id,
    application_service_id
  ) VALUES (
    -- insert as 'draft' (DELTA-1) — trg_invoice_draft_insert rejects non-draft,
    -- non-credit_memo inserts; DELTA-4 flips to 'unposted' once fully built.
    v_invoice_number, v_job.customer_id, 'field_application', 'draft',
    CURRENT_DATE, (CURRENT_DATE + interval '30 days')::date,
    COALESCE(v_job.total_price_cents, 0), 0, 0, 0,
    v_field_names, v_crop_type, v_total_acres, v_applicator_name, v_vehicle_name,
    v_job.job_date, v_job.notes,
    -- N2-7 #109<<< stamp the JOB's season, not the season-of-now. An invoice cut in a
    -- later season for a prior-season job must file under the job's season (reports/
    -- year-end read invoices.season). invoices.season is NOT NULL and jobs.season is
    -- nullable, so COALESCE back to the ORIGINAL CURRENT_DATE-based expression when the
    -- job has no season — never stamp NULL, and legacy null-season jobs behave exactly
    -- as before this migration.
    COALESCE(
      v_job.season,
      CASE WHEN extract(month FROM CURRENT_DATE) >= 10
           THEN extract(year FROM CURRENT_DATE)::integer + 1
           ELSE extract(year FROM CURRENT_DATE)::integer END
    ),
    -- >>>N2-7 #109
    p_performed_by, p_job_id, v_job.application_service_id
  ) RETURNING id INTO v_invoice_id;

  FOR v_chem IN
    SELECT jc.product_id, jc.rate_per_acre,
           safe_cents_qty(jc.cost_per_unit_cents, jc.quantity) AS chem_cost,
           safe_cents_qty(jc.price_per_unit_cents, jc.quantity) AS chem_price,
           jc.customer_supplied,
           p.product_name, p.unit_size, p.epa_registration, p.product_form,
           COALESCE(jc.rate_unit, p.unit_size) AS rate_unit
    FROM job_chemicals jc JOIN products p ON p.id = jc.product_id
    WHERE jc.job_id = p_job_id ORDER BY p.product_name
  LOOP
    v_item_order := v_item_order + 1;
    -- U4<<< a grower-supplied product costs us nothing (we didn't buy it) — keep
    -- it OUT of the invoice cost so margin isn't understated. (#53/#54)
    v_total_cost_cents := v_total_cost_cents + CASE WHEN v_chem.customer_supplied THEN 0 ELSE COALESCE(v_chem.chem_cost, 0) END;
    -- >>>U4
    v_total_applied := CASE WHEN v_chem.rate_per_acre IS NOT NULL AND v_total_acres > 0
      THEN v_chem.rate_per_acre * v_total_acres ELSE NULL END;
    -- DELTA-6: call convert_to_gl_lb unconditionally so v_conversion always receives a
    -- tuple structure (the helper returns one row even for NULL inputs); an unrated line
    -- yields (NULL, NULL) without leaving v_conversion unassigned.
    SELECT * INTO v_conversion
      FROM convert_to_gl_lb(v_total_applied, v_chem.rate_unit, v_chem.product_form);
    INSERT INTO invoice_items (
      invoice_id, product_id, description, quantity, unit_size, unit_price_cents, extended_cents,
      cost_cents, sort_order, acres, rate_per_acre, rate_unit,
      total_applied, total_applied_unit, total_applied_gl_lb, gl_lb_unit,
      epa_registration, product_form, is_application_fee, price_source
    ) VALUES (
      v_invoice_id, v_chem.product_id,
      -- U4<<< customer-supplied: keep the line (legal/application record) but at $0
      -- with a labeled description; force cost + price to 0. price_source='manual'
      -- pins the $0 (Codex R5 P1: a product-backed $0 line without it would be
      -- re-priced by tier when the unposted invoice is edited + re-saved). (#53/#54)
      CASE WHEN v_chem.customer_supplied THEN v_chem.product_name || ' (customer supplied)' ELSE v_chem.product_name END,
      1,
      v_chem.unit_size,
      CASE WHEN v_chem.customer_supplied THEN 0 ELSE COALESCE(v_chem.chem_price, 0) END,
      CASE WHEN v_chem.customer_supplied THEN 0 ELSE COALESCE(v_chem.chem_price, 0) END,
      CASE WHEN v_chem.customer_supplied THEN 0 ELSE COALESCE(v_chem.chem_cost, 0) END,
      -- >>>U4
      v_item_order, v_total_acres,
      v_chem.rate_per_acre, v_chem.rate_unit, v_total_applied,
      COALESCE(v_chem.rate_unit, v_chem.unit_size),
      v_conversion.converted_value, v_conversion.converted_unit,
      v_chem.epa_registration, v_chem.product_form, false,
      CASE WHEN v_chem.customer_supplied THEN 'manual' ELSE NULL END
    );
  END LOOP;

  UPDATE invoices SET total_cost_cents = v_total_cost_cents WHERE id = v_invoice_id;

  IF EXISTS (SELECT 1 FROM job_fields jf JOIN field_billing_defaults fbd ON fbd.field_id = jf.field_id WHERE jf.job_id = p_job_id) THEN
    SELECT EXISTS (SELECT 1 FROM job_fields jf JOIN field_billing_defaults fbd ON fbd.field_id = jf.field_id WHERE jf.job_id = p_job_id AND fbd.price_override_cents IS NOT NULL) INTO v_has_price_override;
    FOR v_share IN
      SELECT fbd.customer_id, c.farm_name,
        CASE WHEN sum(COALESCE(jf.acres_to_treat, 0)) > 0
          THEN sum(fbd.split_pct * COALESCE(jf.acres_to_treat, 0)) / sum(COALESCE(jf.acres_to_treat, 0))
          ELSE avg(fbd.split_pct) END AS avg_split_pct,
        sum(COALESCE(jf.acres_to_treat, 0)) *
          CASE WHEN sum(COALESCE(jf.acres_to_treat, 0)) > 0
            THEN sum(fbd.split_pct * COALESCE(jf.acres_to_treat, 0)) / sum(COALESCE(jf.acres_to_treat, 0))
            ELSE avg(fbd.split_pct) END / 100.0 AS share_acres,
        bool_or(fbd.is_primary) AS is_primary,
        CASE WHEN count(DISTINCT fbd.price_override_cents) = 1 AND min(fbd.price_override_cents) IS NOT NULL
          THEN min(fbd.price_override_cents) ELSE NULL END AS price_override_cents,
        max(fbd.pricing_note) AS pricing_note,
        row_number() OVER (ORDER BY bool_or(fbd.is_primary) DESC, c.farm_name) AS sort_ord
      FROM job_fields jf JOIN field_billing_defaults fbd ON fbd.field_id = jf.field_id
      JOIN customers c ON c.id = fbd.customer_id WHERE jf.job_id = p_job_id
      GROUP BY fbd.customer_id, c.farm_name
    LOOP
      DECLARE v_amount bigint; v_ppa bigint;
      BEGIN
        IF v_share.price_override_cents IS NOT NULL THEN
          v_amount := safe_cents_qty(v_share.price_override_cents, v_share.share_acres);
          v_ppa := v_share.price_override_cents;
        ELSE
          v_amount := ROUND(COALESCE(v_job.total_price_cents, 0) * v_share.avg_split_pct / 100.0)::bigint;
          v_ppa := NULL;
        END IF;
        INSERT INTO invoice_shares (invoice_id, customer_id, customer_name, split_percentage, acres, amount_cents, is_primary, sort_order, price_per_acre_cents, pricing_note)
        VALUES (v_invoice_id, v_share.customer_id, v_share.farm_name, v_share.avg_split_pct, v_share.share_acres, v_amount, v_share.is_primary, v_share.sort_ord, v_ppa, v_share.pricing_note);
        v_share_total := v_share_total + v_amount;
      END;
    END LOOP;
    -- OVERNIGHT FIX (Run 2 cycle 2, finding #3 — penny-drift): reconcile the header to the share
    -- sum for BOTH the override AND the percentage-split path (was override-only). Independent
    -- per-customer ROUND(total_price_cents * pct/100) can drift ±1c on odd-cent splits, so without
    -- this the percentage-split header stayed at total_price_cents while invoice_shares summed a cent
    -- off — and get_customer_year_end_summary / get_detailed_statement_data read invoice_shares.amount_cents,
    -- so statements wouldn't tie. v_share_total is the exact sum of the shares; DELTA-8 then adds the
    -- per-acre fee to both shares and header, preserving the tie. The single-customer ELSE branch
    -- already inserts header = its one share, so it ties without this.
    UPDATE invoices SET total_amount_cents = v_share_total WHERE id = v_invoice_id;
  ELSE
    INSERT INTO invoice_shares (invoice_id, customer_id, customer_name, split_percentage, acres, amount_cents, is_primary, sort_order)
    SELECT v_invoice_id, v_job.customer_id, c.farm_name, 100.0, v_total_acres, COALESCE(v_job.total_price_cents, 0), true, 1
    FROM customers c WHERE c.id = v_job.customer_id;
  END IF;

  -- DELTA-8 (G1 per-acre application fee, PER-CUSTOMER rate): now that invoice_shares exist,
  -- charge each billed customer the per-acre machine fee at that customer's own rate; add each
  -- customer's fee to their share, emit one is_application_fee line, fold into the header.
  IF v_job.application_service_id IS NOT NULL AND v_total_acres > 0 THEN
    FOR v_share IN
      SELECT id, customer_id, COALESCE(acres, 0) AS acres, price_per_acre_cents
      FROM invoice_shares WHERE invoice_id = v_invoice_id
    LOOP
      -- A grower on a price_override (all-inclusive $/acre) does NOT also pay the per-acre
      -- machine fee, or they'd be double-charged (mirrors save_field_app_invoice).
      IF v_share.price_per_acre_cents IS NOT NULL THEN CONTINUE; END IF;
      v_fee := compute_application_service_fee(
                 v_job.application_service_id, v_share.customer_id, v_share.acres, v_job.season);
      v_fee_c  := COALESCE((v_fee->>'total_fee_cents')::bigint, 0);
      v_cost_c := COALESCE((v_fee->>'total_cost_cents')::bigint, 0);
      v_fee_total := v_fee_total + v_fee_c;
      v_fee_cost  := v_fee_cost  + v_cost_c;
      v_fee_acres := v_fee_acres + v_share.acres;
      IF v_fee_c <> 0 THEN
        UPDATE invoice_shares SET amount_cents = amount_cents + v_fee_c WHERE id = v_share.id;
      END IF;
    END LOOP;

    IF v_fee_total > 0 AND v_fee_acres > 0 THEN
      v_item_order := v_item_order + 1;
      INSERT INTO invoice_items (
        invoice_id, description, quantity, unit_size, unit_price_cents, extended_cents,
        cost_cents, sort_order, acres, rate_per_acre, rate_unit,
        is_application_fee, price_source
      ) VALUES (
        v_invoice_id, COALESCE(v_fee->>'service_name', 'Application'), v_fee_acres, 'acre',
        ROUND(v_fee_total / v_fee_acres)::bigint, v_fee_total,
        v_fee_cost, v_item_order, v_fee_acres,
        ROUND(v_fee_total / v_fee_acres)::bigint, 'acre',
        true, 'tier'
      );
      UPDATE invoices SET
        total_amount_cents = COALESCE(total_amount_cents, 0) + v_fee_total,
        total_cost_cents   = total_cost_cents + v_fee_cost
      WHERE id = v_invoice_id;
    END IF;
  END IF;
  -- END DELTA-8

  -- U8<<< (#99): resolve the commission split. New jobs carry a creation-time
  -- snapshot (quote-born: the quote's split via create_job_from_quote_section;
  -- direct: the customer default via trg_jobs_snapshot_commission_split), so this
  -- fallback only fires for PRE-U8 jobs. Order-channel parity (Codex R3 P1): a
  -- quote-born job uses the parent quote's split and ONLY that — convert_quote_to_order
  -- passes only v_quote.commission_split, so a NULL quote split pays no commission,
  -- never the customer default. A pre-U8 direct job uses the customer default, like
  -- a direct order. Codex R2 P2: the resolved fallback is PERSISTED onto the job in
  -- the same UPDATE that flips it to 'invoiced', so attribution locks at first use.
  v_commission_split := v_job.commission_split;
  IF v_commission_split IS NULL THEN
    IF v_job.quote_id IS NOT NULL THEN
      SELECT q.commission_split INTO v_commission_split FROM quotes q WHERE q.id = v_job.quote_id;
    ELSE
      SELECT c.default_commission_split INTO v_commission_split FROM customers c WHERE c.id = v_job.customer_id;
    END IF;
  END IF;
  -- >>>U8

  UPDATE jobs SET status = 'invoiced', invoice_id = v_invoice_id,
    -- U8 (Codex R2 P2 + R4 P1): persist the resolution — even a nothing-anywhere
    -- result locks as the empty sentinel so re-invoices never re-read live sources.
    commission_split = COALESCE(commission_split, v_commission_split, '{"splits":[]}'::jsonb)
  WHERE id = p_job_id;
  UPDATE application_records SET invoice_id = v_invoice_id WHERE source_type = 'job' AND source_id = p_job_id;

  -- DELTA-4: invoice was inserted as 'draft'; flip to 'unposted' now that items, shares and
  -- totals are final. draft -> unposted is allowed by _enforce_invoice_status_transition.
  UPDATE invoices SET status = 'unposted' WHERE id = v_invoice_id;

  -- U8<<< (#99): mint the application-channel commissions — chemical-line profit only.
  -- Mirror of the order channel (convert_quote_to_order → _insert_commissions_for_order).
  -- Profit basis: the chemical lines just written to THIS invoice. The per-acre machine
  -- fee (is_application_fee=true, product_id NULL) is excluded per the owner rule, and
  -- customer-supplied lines carry $0 price AND $0 cost so they contribute exactly 0.
  -- invoice_items money is bigint CENTS; commissions are numeric DOLLARS → /100.0.
  -- The helper no-ops on a NULL/splits-less split and validates a present one
  -- (COMMISSION_SPLIT_INVALID aborts, matching the order-conversion behavior).
  -- Pending amounts stay in sync with later unposted-invoice edits via the
  -- recompute in the item-rewrite path (Codex R2 P1), mirroring update_order_items.
  SELECT COALESCE(SUM(COALESCE(ii.extended_cents, 0) - COALESCE(ii.cost_cents, 0)), 0)
    INTO v_chem_profit_cents
  FROM invoice_items ii
  WHERE ii.invoice_id = v_invoice_id
    AND COALESCE(ii.is_application_fee, false) = false
    AND ii.product_id IS NOT NULL;

  PERFORM _insert_commissions_for_job(
    p_job_id, v_invoice_id, v_job.customer_id,
    v_chem_profit_cents::numeric / 100.0,
    v_commission_split,
    CURRENT_DATE
  );
  -- >>>U8

  -- DELTA-5: log to activity_feed (performed_by NOT NULL: COALESCE to auth.uid()).
  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('job_invoiced',
    'Job ' || v_job.job_number || ' transferred to invoice ' || v_invoice_number,
    COALESCE(p_performed_by, auth.uid()), 'job', p_job_id, v_job.customer_id);

  -- OVERNIGHT FIX (finding #3): write the canonical 'invoice_created' financial_audit_log row
  -- the other six invoice creators write, so the append-only money ledger records creation
  -- provenance for job-built invoices too. Read the FINAL header total back (DELTA-8 may have
  -- adjusted it). Shape mirrors save_field_app_invoice's invoice_created row.
  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_user_id, actor_role,
    new_values, total_impact_cents, description
  ) VALUES (
    'invoice_created', 'invoice', v_invoice_id, auth.uid(),
    (SELECT role FROM profiles WHERE id = auth.uid()),
    jsonb_build_object(
      'invoice_number', v_invoice_number,
      'job_id', p_job_id,
      'customer_id', v_job.customer_id,
      'total_cents', (SELECT total_amount_cents FROM invoices WHERE id = v_invoice_id)
    ),
    (SELECT total_amount_cents FROM invoices WHERE id = v_invoice_id),
    'Invoice ' || v_invoice_number || ' created from job ' || v_job.job_number
  );

  v_result := jsonb_build_object('success', true, 'job_id', p_job_id, 'invoice_id', v_invoice_id, 'invoice_number', v_invoice_number);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'transfer_job_to_invoice', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."transfer_job_to_invoice"("p_job_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_rebate_claim"("p_claim_id" "uuid", "p_new_status" "text", "p_paid_amount_cents" bigint DEFAULT NULL::bigint, "p_manufacturer_ref" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_claim       public.rebate_claims%ROWTYPE;
  v_existing    jsonb;
  v_result      jsonb;
  v_paid_cents  bigint;
  v_today       date := current_date;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT is_admin() THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  IF p_claim_id IS NULL THEN RAISE EXCEPTION 'CLAIM_ID_REQUIRED'; END IF;
  IF p_new_status IS NULL THEN RAISE EXCEPTION 'STATUS_REQUIRED'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'transition_rebate_claim');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_claim
    FROM public.rebate_claims
   WHERE id = p_claim_id
   FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'CLAIM_NOT_FOUND'; END IF;

  IF v_claim.status = 'pending' AND p_new_status IN ('submitted', 'rejected') THEN
    NULL;
  ELSIF v_claim.status = 'submitted' AND p_new_status IN ('approved', 'rejected') THEN
    NULL;
  ELSIF v_claim.status = 'approved' AND p_new_status = 'paid' THEN
    NULL;
  ELSE
    RAISE EXCEPTION 'INVALID_TRANSITION: % -> %', v_claim.status, p_new_status;
  END IF;

  IF p_new_status = 'submitted' THEN
    UPDATE public.rebate_claims
       SET status = 'submitted', submitted_date = v_today, updated_at = now()
     WHERE id = p_claim_id;
  ELSIF p_new_status = 'approved' THEN
    UPDATE public.rebate_claims
       SET status = 'approved', approved_date = v_today, updated_at = now()
     WHERE id = p_claim_id;
  ELSIF p_new_status = 'paid' THEN
    v_paid_cents := COALESCE(p_paid_amount_cents, v_claim.claim_amount_cents);
    IF v_paid_cents <= 0 THEN RAISE EXCEPTION 'PAID_AMOUNT_INVALID'; END IF;
    UPDATE public.rebate_claims
       SET status = 'paid', paid_date = v_today, paid_amount_cents = v_paid_cents,
           manufacturer_ref = COALESCE(p_manufacturer_ref, manufacturer_ref),
           updated_at = now()
     WHERE id = p_claim_id;
  ELSIF p_new_status = 'rejected' THEN
    UPDATE public.rebate_claims
       SET status = 'rejected', updated_at = now()
     WHERE id = p_claim_id;
  END IF;

  v_result := jsonb_build_object(
    'success', true, 'claim_id', p_claim_id,
    'old_status', v_claim.status, 'new_status', p_new_status
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'transition_rebate_claim', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."transition_rebate_claim"("p_claim_id" "uuid", "p_new_status" "text", "p_paid_amount_cents" bigint, "p_manufacturer_ref" "text", "p_idempotency_key" "text") OWNER TO "postgres";


