CREATE OR REPLACE FUNCTION "public"."trg_inventory_significant_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_product_name text; v_qty_change numeric;
BEGIN
  v_qty_change := NEW.quantity_available - COALESCE(OLD.quantity_available, 0);
  IF ABS(v_qty_change) > 10 OR (
    COALESCE(OLD.quantity_available, 0) > 0 AND
    ABS(v_qty_change) > COALESCE(OLD.quantity_available, 1) * 0.10
  ) THEN
    IF auth.uid() IS NOT NULL THEN
      SELECT product_name INTO v_product_name FROM products WHERE id = NEW.product_id;
      INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id)
      VALUES ('inventory_adjusted',
        COALESCE(v_product_name, 'Product') || ' inventory changed by ' || v_qty_change ||
        ' units (now ' || NEW.quantity_available || ')',
        auth.uid(), 'inventory', NEW.id);
    END IF;
  END IF;
  RETURN NEW;
END; $$;


