CREATE OR REPLACE FUNCTION "public"."trg_recalc_order_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order_id uuid;
  v_total_price numeric;
  v_total_cost numeric;
  v_total_profit numeric;
  v_margin_pct numeric;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_order_id := OLD.order_id;
  ELSE
    v_order_id := NEW.order_id;
  END IF;

  SELECT
    COALESCE(SUM(total_price), 0),
    COALESCE(SUM(COALESCE(cost_per_unit, 0) * total_units_needed), 0)
  INTO v_total_price, v_total_cost
  FROM order_items
  WHERE order_id = v_order_id;

  v_total_profit := v_total_price - v_total_cost;
  v_margin_pct := CASE WHEN v_total_price > 0
    THEN ROUND((v_total_profit / v_total_price) * 100, 2)
    ELSE 0
  END;

  UPDATE orders SET
    total_price = ROUND(v_total_price, 2),
    total_cost = ROUND(v_total_cost, 2),
    total_profit = ROUND(v_total_profit, 2),
    total_margin_pct = v_margin_pct,
    -- REMOVED: balance_due = ... (AR tracked via invoices.balance_cents)
    updated_at = now()
  WHERE id = v_order_id;

  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


ALTER FUNCTION "public"."trg_recalc_order_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unapply_credit_memo"("p_credit_memo_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid;
  v_invoice  record;
  v_return   record;
  v_existing jsonb;
  v_result   jsonb;
  v_capp     record;  -- CREDIT-APPLY: active-application cursor
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'admin') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required to unapply a credit memo';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key
       AND operation = 'unapply_credit_memo';
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  SELECT * INTO v_invoice
    FROM invoices
   WHERE id = p_credit_memo_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice not found: %', p_credit_memo_id;
  END IF;

  IF v_invoice.invoice_type != 'credit_memo' THEN
    RAISE EXCEPTION 'Invoice % is not a credit memo (type: %)', v_invoice.invoice_number, v_invoice.invoice_type;
  END IF;

  IF v_invoice.status != 'posted' THEN
    RAISE EXCEPTION 'Only posted credit memos can be unapplied (current status: %)', v_invoice.status;
  END IF;

  -- Preserved from LIVE (PARKED-001): unapply respects the ORIGINAL credit's booking period.
  -- NOT new in this migration — the on-disk base file (20260609190725) predates this live gate.
  PERFORM check_period_open(v_invoice.invoice_date);

  -- CREDIT-APPLY: reverse every active application this memo handed out, so each target becomes
  -- owed again and the ledger stays consistent, BEFORE the memo is voided below (Codex #4).
  FOR v_capp IN
    SELECT id, applied_at FROM credit_memo_applications
     WHERE credit_memo_id = p_credit_memo_id AND reversed_at IS NULL
     ORDER BY id
  LOOP
    -- drift HIGH: each application's reversal is a money movement — gate it on THAT application's
    -- own period (applied_at), matching void_invoice + reverse_credit_memo_application. The
    -- top-of-function check_period_open(v_invoice.invoice_date) only covers the memo's ISSUE date;
    -- an application that landed in a since-closed period must not be reversible without its gate.
    PERFORM check_period_open(v_capp.applied_at::date);
    PERFORM _reverse_credit_memo_application(v_capp.id, v_actor,
      (SELECT role FROM profiles WHERE id = v_actor),
      'Auto-reversed: credit memo ' || v_invoice.invoice_number || ' unapplied — ' || p_reason);
  END LOOP;

  SELECT * INTO v_return
    FROM returns
   WHERE credit_invoice_id = p_credit_memo_id
   FOR UPDATE;

  UPDATE invoices SET
    status      = 'voided',
    voided_by   = v_actor,
    voided_at   = now(),
    void_reason = p_reason,
    updated_at  = now()
  WHERE id = p_credit_memo_id;

  IF v_return.id IS NOT NULL THEN
    PERFORM set_config('app.admin_override', 'true', true);
    UPDATE returns SET
      status             = 'received',
      credit_invoice_id  = NULL,
      total_credit_cents = 0,
      credited_at        = NULL,
      credited_by        = NULL,
      updated_at         = now()
    WHERE id = v_return.id;
    PERFORM set_config('app.admin_override', 'false', true);
  END IF;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_role,
    old_values, new_values, total_impact_cents, description
  ) VALUES (
    'credit_memo_unapplied', 'invoice', p_credit_memo_id,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object('status', 'posted', 'total_amount_cents', v_invoice.total_amount_cents),
    jsonb_build_object(
      'status', 'voided',
      'return_reverted', CASE WHEN v_return.id IS NOT NULL THEN v_return.return_number ELSE NULL END
    ),
    -v_invoice.total_amount_cents,
    'Credit memo ' || v_invoice.invoice_number || ' unapplied: ' || p_reason
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'credit_memo_unapplied',
    'Credit memo ' || v_invoice.invoice_number || ' unapplied: ' || p_reason,
    v_actor, 'invoice', p_credit_memo_id, v_invoice.customer_id
  );

  v_result := jsonb_build_object(
    'success',         true,
    'credit_memo_id',  p_credit_memo_id,
    'invoice_number',  v_invoice.invoice_number,
    'return_id',       v_return.id,
    'return_reverted', v_return.id IS NOT NULL
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result, expires_at)
    VALUES (p_idempotency_key, 'unapply_credit_memo', v_result, now() + interval '24 hours')
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."unapply_credit_memo"("p_credit_memo_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."unapply_credit_memo"("p_credit_memo_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Admin-only void of a posted credit memo invoice and revert of its linked return from "credited" back to "received". Wave A.6 explicit rewrite (also fixes audit-log status string for the new state).';



CREATE OR REPLACE FUNCTION "public"."undispatch_job_locations"("p_job_field_ids" "uuid"[], "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor      uuid;
  v_role       text;
  v_existing   jsonb;
  v_count      int := 0;
  v_row        record;
  v_assignee   text;
  v_field      text;
  v_result     jsonb;
  v_dispatchable_jobs uuid[];  -- the locked, dispatchable parent jobs (TOCTOU guard)
BEGIN
  -- actor / strict-actor / role gate (mirrors dispatch_job_locations).
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  SELECT role INTO v_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'sales_rep') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE: admin or sales_rep required';
  END IF;

  -- idempotency: return the cached result if this key already ran for THIS op.
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'undispatch_job_locations');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF p_job_field_ids IS NULL OR array_length(p_job_field_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'NO_LOCATIONS: at least one job_field_id required';
  END IF;

  -- LOCK the distinct DISPATCHABLE parent jobs of the target locations BEFORE touching
  -- their dispatch rows. A bare EXISTS on jobs only reads a snapshot, so a concurrent
  -- complete/cancel of the same job could slip its status out of scheduled/in_progress
  -- between the check and the UPDATE — cancelling a dispatch on a now-finished job
  -- (TOCTOU). The status-transition enforcer takes a FOR UPDATE row lock on the job, so
  -- locking the same rows here serializes against it: any in-flight transition either
  -- already committed (and we skip a non-dispatchable job) or waits behind us (and sees
  -- our cancel). Mirrors dispatch_job_locations's FOR UPDATE guard (Codex #37 final-2 P2).
  -- We lock each job individually in a deterministic (id-ordered) loop — FOR UPDATE cannot
  -- be combined with array_agg in one statement — collecting the dispatchable ids; the
  -- id ORDER avoids deadlocks with a concurrent dispatch over an overlapping job set.
  v_dispatchable_jobs := '{}';
  FOR v_row IN
    SELECT j.id
      FROM jobs j
     WHERE j.deleted_at IS NULL
       AND j.status IN ('scheduled', 'in_progress')
       AND j.id IN (
         SELECT DISTINCT d.job_id
           FROM job_location_dispatches d
          WHERE d.job_field_id = ANY(p_job_field_ids)
            AND d.dispatch_status = 'dispatched'
       )
     ORDER BY j.id
     FOR UPDATE
  LOOP
    v_dispatchable_jobs := array_append(v_dispatchable_jobs, v_row.id);
  END LOOP;

  -- Cancel each CURRENT ('dispatched') dispatch for the given locations whose parent job
  -- is in the LOCKED dispatchable set. A location whose job is not dispatchable (or got
  -- finished by a transaction that beat our lock) matches nothing and is silently skipped
  -- (reflected in the undispatched count), consistent with the no-op semantics. This RPC
  -- is SECURITY DEFINER and bypasses RLS, so this lifecycle gate is the real write
  -- boundary (the UI hiding the controls is not enough). RETURNING drives the per-row
  -- activity log + the accurate undispatched count.
  FOR v_row IN
    UPDATE job_location_dispatches d
       SET dispatch_status = 'cancelled',
           updated_at = now()
     WHERE d.job_field_id = ANY(p_job_field_ids)
       AND d.dispatch_status = 'dispatched'
       AND d.job_id = ANY(v_dispatchable_jobs)
     RETURNING d.job_id, d.job_field_id, d.applicator_id, d.crew_id
  LOOP
    -- Resolve the assignee + field label for the audit row.
    IF v_row.applicator_id IS NOT NULL THEN
      SELECT full_name INTO v_assignee FROM profiles WHERE id = v_row.applicator_id;
      v_assignee := 'applicator ' || coalesce(v_assignee, v_row.applicator_id::text);
    ELSE
      SELECT name INTO v_assignee FROM ground_crews WHERE id = v_row.crew_id;
      v_assignee := 'crew ' || coalesce(v_assignee, v_row.crew_id::text);
    END IF;
    SELECT f.field_name INTO v_field
      FROM job_fields jf JOIN fields f ON f.id = jf.field_id WHERE jf.id = v_row.job_field_id;

    INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
    SELECT
      'job_location_undispatched',
      'Location ' || coalesce(v_field, '') || ' undispatched from ' || v_assignee,
      v_actor, 'job', v_row.job_id, j.customer_id
    FROM jobs j WHERE j.id = v_row.job_id;

    v_count := v_count + 1;
  END LOOP;

  v_result := jsonb_build_object('undispatched', v_count);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'undispatch_job_locations', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."undispatch_job_locations"("p_job_field_ids" "uuid"[], "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unlink_blend_ticket_from_order"("p_blend_ticket_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_ticket public.blend_tickets%ROWTYPE;
  v_order_id uuid;
  v_order_num text;
  v_deleted integer;
  v_result json;
  v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  PERFORM public.require_admin_or_sales_rep();

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(
      p_idempotency_key,
      'unlink_blend_ticket_from_order'
    );
    IF v_existing IS NOT NULL THEN RETURN v_existing::json; END IF;
  END IF;

  SELECT * INTO v_ticket
    FROM public.blend_tickets
   WHERE id = p_blend_ticket_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Blend ticket not found');
  END IF;
  IF v_ticket.order_link_status <> 'linked' THEN
    RETURN json_build_object('success', false, 'error', 'Not linked');
  END IF;
  IF v_ticket.payment_status <> 'unbilled' THEN
    RAISE EXCEPTION 'BLEND_TICKET_UNLINK_BILLING_LOCKED';
  END IF;
  IF EXISTS (
       SELECT 1 FROM public.invoices
        WHERE blend_ticket_id = p_blend_ticket_id
          AND deleted_at IS NULL
          AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_UNLINK_INVOICE_EXISTS';
  END IF;
  IF EXISTS (
       SELECT 1 FROM public.application_records
        WHERE source_type = 'blend_ticket'
          AND source_id = p_blend_ticket_id
     ) THEN
    RAISE EXCEPTION 'BLEND_TICKET_UNLINK_APPLICATION_EXISTS';
  END IF;

  SELECT DISTINCT bto.order_id, o.order_number
    INTO v_order_id, v_order_num
    FROM public.blend_ticket_to_order_items bto
    JOIN public.orders o ON o.id = bto.order_id
   WHERE bto.blend_ticket_id = p_blend_ticket_id
   LIMIT 1;

  DELETE FROM public.blend_ticket_to_order_items
   WHERE blend_ticket_id = p_blend_ticket_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  IF v_deleted = 0 THEN
    RAISE EXCEPTION 'BLEND_TICKET_UNLINK_MAPPING_MISSING';
  END IF;

  UPDATE public.blend_tickets
     SET order_link_status = 'unlinked', updated_at = now()
   WHERE id = p_blend_ticket_id;

  INSERT INTO public.activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id
  ) VALUES (
    'blend_ticket_unlinked_from_order',
    'Blend ticket ' || v_ticket.ticket_number || ' unlinked from order ' || COALESCE(v_order_num, 'unknown'),
    v_actor, 'blend_ticket', p_blend_ticket_id
  );

  INSERT INTO public.financial_audit_log (
    operation_type, entity_type, entity_id, actor_user_id,
    actor_role, new_values, description
  ) VALUES (
    'blend_ticket_unlinked', 'blend_ticket', p_blend_ticket_id, v_actor,
    (SELECT role FROM public.profiles WHERE id = v_actor),
    jsonb_build_object('order_id', v_order_id, 'items_removed', v_deleted),
    'Unlinked blend ticket ' || v_ticket.ticket_number || ' from order ' || COALESCE(v_order_num, 'unknown')
  );

  v_result := json_build_object(
    'success', true,
    'items_removed', v_deleted,
    'order_id', v_order_id
  );
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency(
      p_idempotency_key,
      'unlink_blend_ticket_from_order',
      v_result::jsonb
    );
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."unlink_blend_ticket_from_order"("p_blend_ticket_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unlink_field_from_parent"("p_field_id" "uuid", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_existing jsonb;
BEGIN
  PERFORM require_admin_or_sales_rep();
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'unlink_field_from_parent');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;
  UPDATE fields SET parent_field_id = NULL, updated_at = now() WHERE id = p_field_id;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'unlink_field_from_parent', '{}'::jsonb);
  END IF;
END; $$;


ALTER FUNCTION "public"."unlink_field_from_parent"("p_field_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unpost_invoice"("p_invoice_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_inv RECORD;
  v_actor_role text;
  v_existing jsonb;
  v_result jsonb;
  v_alloc_count int := 0;
  v_prepay_count int := 0;
  v_rup_voided int := 0;
  v_credit_app_count int := 0;  -- CREDIT-APPLY
BEGIN
  SELECT role INTO v_actor_role FROM profiles
    WHERE id = auth.uid() AND is_active = true AND role IN ('admin','sales_rep');
  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized: requires admin,sales_rep role';
  END IF;
  IF p_performed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH: p_performed_by must match the authenticated user';
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'unpost_invoice');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_inv FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found: %', p_invoice_id; END IF;
  IF v_inv.status NOT IN ('posted', 'overdue') THEN
    IF v_inv.status IN ('draft', 'unposted') THEN
      RAISE EXCEPTION 'Invoice % is not posted (status: %); there is nothing to unpost', v_inv.invoice_number, v_inv.status;
    ELSE
      RAISE EXCEPTION 'Cannot unpost a % invoice (%). Only a posted, unpaid invoice can be returned to the Unposted list.', v_inv.status, v_inv.invoice_number;
    END IF;
  END IF;

  SELECT count(*) INTO v_alloc_count FROM invoice_line_allocations WHERE invoice_id = p_invoice_id;
  SELECT count(*) INTO v_prepay_count FROM prepay_applications     WHERE invoice_id = p_invoice_id;
  -- CREDIT-APPLY: active applications where this invoice is the memo OR the target.
  SELECT count(*) INTO v_credit_app_count FROM credit_memo_applications
   WHERE reversed_at IS NULL AND (credit_memo_id = p_invoice_id OR target_invoice_id = p_invoice_id);
  IF v_alloc_count > 0
     OR v_prepay_count > 0
     OR v_credit_app_count > 0
     OR COALESCE(v_inv.paid_amount_cents, 0)    <> 0
     OR COALESCE(v_inv.prepay_applied_cents, 0) <> 0
     OR COALESCE(v_inv.write_off_cents, 0)      <> 0
     OR COALESCE(v_inv.credit_applied_cents, 0) <> 0
  THEN
    RAISE EXCEPTION 'Cannot unpost invoice % — it has payments, prepay, write-offs, or applied credit. Reverse those first (or void the invoice instead).', v_inv.invoice_number;
  END IF;

  PERFORM check_period_open(v_inv.invoice_date);

  PERFORM set_config('app.admin_override', 'true', true);
  UPDATE invoices SET
    status      = 'unposted',
    posted_by   = NULL,
    posted_at   = NULL,
    updated_at  = now()
  WHERE id = p_invoice_id;
  PERFORM set_config('app.admin_override', 'false', true);

  UPDATE rup_sales_records SET
    voided_at  = now(),
    voided_by  = auth.uid(),
    void_reason = 'Invoice ' || v_inv.invoice_number || ' unposted'
  WHERE invoice_id = p_invoice_id
    AND voided_at IS NULL;
  GET DIAGNOSTICS v_rup_voided = ROW_COUNT;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_user_id, actor_role,
    old_values, new_values, total_impact_cents, description
  ) VALUES (
    'invoice_unposted', 'invoice', p_invoice_id, auth.uid(), v_actor_role,
    jsonb_build_object('status', v_inv.status, 'posted_at', v_inv.posted_at),
    jsonb_build_object('status', 'unposted', 'unposted_at', now()::text, 'rup_rows_voided', v_rup_voided),
    -1 * COALESCE(v_inv.total_amount_cents, 0),
    'Unposted ' || v_inv.invoice_number || ' (was ' || v_inv.status || ') — $' || (COALESCE(v_inv.total_amount_cents,0) / 100.0)::numeric(12,2)
      || CASE WHEN v_rup_voided > 0 THEN '; ' || v_rup_voided || ' RUP sale row(s) voided' ELSE '' END
  );

  IF v_rup_voided > 0 THEN
    INSERT INTO financial_audit_log (
      operation_type, entity_type, entity_id, actor_user_id, actor_role,
      new_values, total_impact_cents, description
    ) VALUES (
      'rup_sales_voided', 'invoice', p_invoice_id, auth.uid(), v_actor_role,
      jsonb_build_object('rows_voided', v_rup_voided, 'reason', 'invoice_unposted'),
      0,
      v_rup_voided || ' RUP sale row(s) voided for invoice ' || v_inv.invoice_number || ' on unpost'
    );
  END IF;

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id, customer_id)
  VALUES ('invoice_unposted',
    'Unposted invoice ' || v_inv.invoice_number || ' — returned to the Unposted list',
    COALESCE(p_performed_by, auth.uid()), 'invoice', p_invoice_id, v_inv.customer_id);

  v_result := jsonb_build_object(
    'success', true,
    'invoice_id', p_invoice_id,
    'invoice_number', v_inv.invoice_number,
    'previous_status', v_inv.status,
    'status', 'unposted',
    'rup_rows_voided', v_rup_voided
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'unpost_invoice', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."unpost_invoice"("p_invoice_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."unpost_invoice"("p_invoice_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Field-app parity #28: reverse of post_invoice. Returns a posted/overdue invoice with NO payments/prepay/write-off applied to ''unposted'' (clears posted_by/posted_at), respecting check_period_open. Admin/sales_rep, strict-actor, idempotent, append-only audit (invoice_unposted).';



CREATE OR REPLACE FUNCTION "public"."unpost_invoice_group"("p_invoice_group_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor          uuid := auth.uid();
  v_existing       jsonb;
  v_inv            record;
  v_unposted_ids   uuid[] := '{}';
  v_total_cents    bigint := 0;
  v_member_count   int := 0;
  v_result         jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH: p_performed_by must match the authenticated user';
  END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'Not authorized: admin or sales role required to unpost invoice groups';
  END IF;

  IF p_invoice_group_id IS NULL THEN RAISE EXCEPTION 'invoice_group_id is required'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'unpost_invoice_group';
    IF v_existing IS NOT NULL THEN
      -- Replay-safety: only return a cached result that belongs to the SAME group
      -- (the page-level idempotency key persists across navigations; if group A's call
      -- succeeded but the client timed out before reset and the user then unposts group
      -- B under the SAME key, a blind replay would report A's success while B stays
      -- posted). Refuse a mismatched replay with an honest error instead of a silent
      -- wrong-group success (Codex).
      IF (v_existing->>'invoice_group_id') IS DISTINCT FROM p_invoice_group_id::text THEN
        RAISE EXCEPTION 'IDEMPOTENCY_KEY_REUSED: this key was already used for a different invoice group';
      END IF;
      RETURN v_existing;
    END IF;
  END IF;

  -- Lock the group's members for the duration of the transaction.
  PERFORM 1 FROM invoices WHERE invoice_group_id = p_invoice_group_id AND deleted_at IS NULL FOR UPDATE;

  SELECT COUNT(*) INTO v_member_count FROM invoices WHERE invoice_group_id = p_invoice_group_id AND deleted_at IS NULL;
  IF v_member_count = 0 THEN RAISE EXCEPTION 'No invoices found in group %', p_invoice_group_id; END IF;

  -- Unpost EVERY member in this single transaction. unpost_invoice enforces, per member,
  -- the status/money/closed-period guards and writes the append-only audit row; if ANY
  -- member cannot be unposted it RAISES and the whole transaction rolls back (all-or-nothing).
  FOR v_inv IN SELECT * FROM invoices WHERE invoice_group_id = p_invoice_group_id AND deleted_at IS NULL ORDER BY invoice_number
  LOOP
    PERFORM unpost_invoice(v_inv.id, p_performed_by, NULL);
    v_unposted_ids := array_append(v_unposted_ids, v_inv.id);
    v_total_cents := v_total_cents + COALESCE(v_inv.total_amount_cents, 0);
  END LOOP;

  INSERT INTO activity_feed (event_type, description, performed_by, related_entity_type, related_entity_id)
  VALUES ('invoice_group_unposted',
          'Unposted ' || v_member_count || ' invoice(s) in group — total $' ||
            (v_total_cents / 100.0)::numeric(12,2),
          p_performed_by, 'invoice', v_unposted_ids[1]);

  v_result := jsonb_build_object(
    'success',              true,
    'unposted_invoice_ids', to_jsonb(v_unposted_ids),
    'invoice_group_id',     p_invoice_group_id,
    'total_unposted_cents', v_total_cents,
    'member_count',         v_member_count
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'unpost_invoice_group', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."unpost_invoice_group"("p_invoice_group_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."unpost_invoice_group"("p_invoice_group_id" "uuid", "p_performed_by" "uuid", "p_idempotency_key" "text") IS 'Field-app FIX 4 (Wave 2a): ALL-OR-NOTHING group inverse of post_invoice_group. Unposts every member of a split invoice group in ONE transaction via unpost_invoice; if any member can''t unpost (paid/money-applied/closed-period/wrong-status) the whole call RAISES and rolls back. Admin/sales_rep, strict-actor, idempotent, SECDEF.';



CREATE OR REPLACE FUNCTION "public"."update_blend_ticket_billing_status"("p_blend_ticket_id" "uuid", "p_payment_status" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT "auth"."uid"(), "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ticket public.blend_tickets%ROWTYPE;
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  PERFORM require_admin_or_sales_rep();

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(
      p_idempotency_key,
      'update_blend_ticket_billing_status'
    );
    IF v_existing IS NOT NULL THEN
      RETURN v_existing::json;
    END IF;
  END IF;

  SELECT *
    INTO v_ticket
    FROM public.blend_tickets
   WHERE id = p_blend_ticket_id
     AND deleted_at IS NULL
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Blend ticket not found');
  END IF;

  IF p_payment_status = 'billed'
     AND v_ticket.order_link_status = 'unlinked'
     AND NOT EXISTS (
       SELECT 1 FROM public.invoices
        WHERE blend_ticket_id = p_blend_ticket_id
          AND deleted_at IS NULL
          AND COALESCE(status, '') NOT IN ('voided', 'cancelled')
     ) THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Cannot set payment status to billed without a linked order or active invoice'
    );
  END IF;

  IF p_payment_status IS NOT NULL THEN
    UPDATE public.blend_tickets
       SET payment_status = p_payment_status,
           updated_at = now()
     WHERE id = p_blend_ticket_id;

    INSERT INTO public.activity_feed (
      event_type, description, performed_by, related_entity_type, related_entity_id
    ) VALUES (
      'blend_ticket_status_changed',
      'Blend ticket ' || v_ticket.ticket_number ||
        ' payment status changed to ' || p_payment_status,
      v_actor, 'blend_ticket', p_blend_ticket_id
    );
  END IF;

  v_result := jsonb_build_object('success', true);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(
      p_idempotency_key,
      'update_blend_ticket_billing_status',
      v_result
    );
  END IF;

  RETURN v_result::json;
END;
$$;


ALTER FUNCTION "public"."update_blend_ticket_billing_status"("p_blend_ticket_id" "uuid", "p_payment_status" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_blend_ticket_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at := GREATEST(
    clock_timestamp(),
    COALESCE(OLD.updated_at, '-infinity'::timestamptz) + interval '1 microsecond'
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_blend_ticket_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_cycle_count_item"("p_item_id" "uuid", "p_counted_qty" numeric DEFAULT NULL::numeric, "p_notes" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor        uuid;
  v_existing     jsonb;
  v_item         record;
  v_count        record;
  v_variance     numeric;
  v_variance_pct numeric;
  v_result       jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match authenticated user';
  END IF;
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Admin access required to update cycle count items';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'update_cycle_count_item');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT cc.* INTO v_count
    FROM cycle_count_items cci
    JOIN cycle_counts cc ON cc.id = cci.cycle_count_id
   WHERE cci.id = p_item_id
     FOR UPDATE OF cc;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cycle count item not found: %', p_item_id;
  END IF;

  IF v_count.status != 'in_progress' THEN
    RAISE EXCEPTION 'Cannot edit cycle count item: parent count is % (only in_progress counts can be edited)', v_count.status;
  END IF;

  SELECT * INTO v_item FROM cycle_count_items WHERE id = p_item_id;

  IF p_counted_qty IS NOT NULL THEN
    v_variance := p_counted_qty - v_item.expected_qty;
    IF v_item.expected_qty <> 0 THEN
      v_variance_pct := round((v_variance / v_item.expected_qty) * 100, 2);
    ELSE
      v_variance_pct := NULL;
    END IF;
  ELSE
    v_variance := NULL;
    v_variance_pct := NULL;
  END IF;

  UPDATE cycle_count_items
  SET counted_qty  = p_counted_qty,
      variance     = v_variance,
      variance_pct = v_variance_pct,
      is_counted   = (p_counted_qty IS NOT NULL),
      counted_by   = CASE WHEN p_counted_qty IS NOT NULL THEN v_actor ELSE NULL END,
      counted_at   = CASE WHEN p_counted_qty IS NOT NULL THEN now() ELSE NULL END,
      notes        = COALESCE(p_notes, notes)
  WHERE id = p_item_id;

  v_result := jsonb_build_object(
    'item_id',      p_item_id,
    'counted_qty',  p_counted_qty,
    'variance',     v_variance,
    'variance_pct', v_variance_pct,
    'is_counted',   (p_counted_qty IS NOT NULL)
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'update_cycle_count_item', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."update_cycle_count_item"("p_item_id" "uuid", "p_counted_qty" numeric, "p_notes" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_field_app_applied_info"("p_invoice_ids" "uuid"[], "p_wind_direction" "text" DEFAULT NULL::"text", "p_temperature_text" "text" DEFAULT NULL::"text", "p_applicator_name" "text" DEFAULT NULL::"text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_start_temp_f" numeric DEFAULT NULL::numeric, "p_start_wind_mph" numeric DEFAULT NULL::numeric, "p_start_wind_direction" "text" DEFAULT NULL::"text", "p_start_humidity_pct" numeric DEFAULT NULL::numeric, "p_start_weather_time" time without time zone DEFAULT NULL::time without time zone, "p_start_weather_source" "text" DEFAULT NULL::"text", "p_end_temp_f" numeric DEFAULT NULL::numeric, "p_end_wind_mph" numeric DEFAULT NULL::numeric, "p_end_wind_direction" "text" DEFAULT NULL::"text", "p_end_humidity_pct" numeric DEFAULT NULL::numeric, "p_end_weather_time" time without time zone DEFAULT NULL::time without time zone, "p_end_weather_source" "text" DEFAULT NULL::"text", "p_weather_manual_override" boolean DEFAULT NULL::boolean, "p_update_weather" boolean DEFAULT false, "p_diluent_rate_gpa" numeric DEFAULT NULL::numeric, "p_update_diluent" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid := auth.uid();
  v_expected int;
  v_updated  int;
  v_existing jsonb;
  v_result   jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match the authenticated user';
  END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'Not authorized: admin or sales role required to save applied info';
  END IF;

  v_expected := COALESCE(array_length(p_invoice_ids, 1), 0);
  IF v_expected = 0 THEN
    RAISE EXCEPTION 'At least one invoice id is required';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key AND operation = 'update_field_app_applied_info';
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  -- Validate the structured weather at the RPC layer (equivalent to job_applied_records'
  -- DB CHECKs, but kept OFF the invoices money table — invoices must not gain a new CHECK).
  -- Reject only physically-impossible values; NULLs (unentered) always pass. Wind speed and
  -- humidity cannot be negative; humidity is a 0-100 percentage; the source flag, when set,
  -- must be 'auto' or 'manual'. Temperature is left unbounded (legitimately can be sub-zero F).
  IF p_start_wind_mph IS NOT NULL AND p_start_wind_mph < 0
     OR p_end_wind_mph IS NOT NULL AND p_end_wind_mph < 0 THEN
    RAISE EXCEPTION 'Wind speed cannot be negative';
  END IF;
  IF p_start_humidity_pct IS NOT NULL AND (p_start_humidity_pct < 0 OR p_start_humidity_pct > 100)
     OR p_end_humidity_pct IS NOT NULL AND (p_end_humidity_pct < 0 OR p_end_humidity_pct > 100) THEN
    RAISE EXCEPTION 'Humidity must be between 0 and 100 percent';
  END IF;
  IF p_start_weather_source IS NOT NULL AND p_start_weather_source NOT IN ('auto', 'manual')
     OR p_end_weather_source IS NOT NULL AND p_end_weather_source NOT IN ('auto', 'manual') THEN
    RAISE EXCEPTION 'Weather source must be auto or manual';
  END IF;

  -- Validate the diluent rate at the RPC layer (kept OFF the invoices money table — no new
  -- CHECK). A diluent rate is a non-negative quantity; NULL (unentered/cleared) always passes.
  -- Only enforced when this caller actually intends to write diluent (p_update_diluent),
  -- so an old-bundle caller can never trip a validation it does not even pass a value to.
  IF p_update_diluent AND p_diluent_rate_gpa IS NOT NULL AND p_diluent_rate_gpa < 0 THEN
    RAISE EXCEPTION 'Diluent rate cannot be negative';
  END IF;

  -- Only editable field-application invoices — never a posted/voided row or a non-field invoice.
  -- Structured weather columns are written ONLY when p_update_weather = TRUE (the new UI). A
  -- stale 6-arg caller leaves p_update_weather = FALSE, so each weather column keeps its current
  -- value (= column) — captured weather is never silently erased by an old-bundle save. When the
  -- new UI saves (TRUE), the weather columns are written exactly as passed (NULL there = an
  -- intentional clear, mirroring the legacy free-text "blank clears" behavior).
  -- diluent_rate_gpa follows the SAME sentinel rule with p_update_diluent.
  UPDATE invoices SET
    wind_direction          = p_wind_direction,
    temperature_text        = p_temperature_text,
    applicator_name         = p_applicator_name,
    start_temp_f            = CASE WHEN p_update_weather THEN p_start_temp_f         ELSE start_temp_f         END,
    start_wind_mph          = CASE WHEN p_update_weather THEN p_start_wind_mph       ELSE start_wind_mph       END,
    start_wind_direction    = CASE WHEN p_update_weather THEN p_start_wind_direction ELSE start_wind_direction END,
    start_humidity_pct      = CASE WHEN p_update_weather THEN p_start_humidity_pct   ELSE start_humidity_pct   END,
    start_weather_time      = CASE WHEN p_update_weather THEN p_start_weather_time   ELSE start_weather_time   END,
    start_weather_source    = CASE WHEN p_update_weather THEN p_start_weather_source ELSE start_weather_source END,
    end_temp_f              = CASE WHEN p_update_weather THEN p_end_temp_f           ELSE end_temp_f           END,
    end_wind_mph            = CASE WHEN p_update_weather THEN p_end_wind_mph         ELSE end_wind_mph         END,
    end_wind_direction      = CASE WHEN p_update_weather THEN p_end_wind_direction   ELSE end_wind_direction   END,
    end_humidity_pct        = CASE WHEN p_update_weather THEN p_end_humidity_pct     ELSE end_humidity_pct     END,
    end_weather_time        = CASE WHEN p_update_weather THEN p_end_weather_time     ELSE end_weather_time     END,
    end_weather_source      = CASE WHEN p_update_weather THEN p_end_weather_source   ELSE end_weather_source   END,
    weather_manual_override = CASE WHEN p_update_weather THEN COALESCE(p_weather_manual_override, false) ELSE weather_manual_override END,
    diluent_rate_gpa        = CASE WHEN p_update_diluent THEN p_diluent_rate_gpa     ELSE diluent_rate_gpa    END,
    updated_at              = now()
  WHERE id = ANY(p_invoice_ids)
    AND invoice_type = 'field_application'
    AND status IN ('draft', 'unposted');
  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated <> v_expected THEN
    RAISE EXCEPTION 'Applied info update affected % of % invoice(s) — some are not editable field-application invoices', v_updated, v_expected;
  END IF;

  v_result := jsonb_build_object('updated', v_updated);

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'update_field_app_applied_info', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."update_field_app_applied_info"("p_invoice_ids" "uuid"[], "p_wind_direction" "text", "p_temperature_text" "text", "p_applicator_name" "text", "p_performed_by" "uuid", "p_idempotency_key" "text", "p_start_temp_f" numeric, "p_start_wind_mph" numeric, "p_start_wind_direction" "text", "p_start_humidity_pct" numeric, "p_start_weather_time" time without time zone, "p_start_weather_source" "text", "p_end_temp_f" numeric, "p_end_wind_mph" numeric, "p_end_wind_direction" "text", "p_end_humidity_pct" numeric, "p_end_weather_time" time without time zone, "p_end_weather_source" "text", "p_weather_manual_override" boolean, "p_update_weather" boolean, "p_diluent_rate_gpa" numeric, "p_update_diluent" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_field_app_invoice_billing"("p_invoice_ids" "uuid"[], "p_purchase_order_ref" "text" DEFAULT NULL::"text", "p_payment_terms" "text" DEFAULT NULL::"text", "p_header_notes" "text" DEFAULT NULL::"text", "p_due_date" "date" DEFAULT NULL::"date", "p_footer_notes" "text" DEFAULT NULL::"text", "p_internal_notes" "text" DEFAULT NULL::"text", "p_discounts" "jsonb" DEFAULT '{}'::"jsonb", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid := auth.uid();
  v_expected int;
  v_updated  int;
  v_existing jsonb;
  v_result   jsonb;
  v_disc     jsonb := COALESCE(p_discounts, '{}'::jsonb);
  v_id       uuid;
  v_amount   bigint;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'p_performed_by does not match the authenticated user';
  END IF;
  IF NOT (is_admin() OR is_sales_rep()) THEN
    RAISE EXCEPTION 'Not authorized: admin or sales role required to save invoice billing details';
  END IF;

  v_expected := COALESCE(array_length(p_invoice_ids, 1), 0);
  IF v_expected = 0 THEN
    RAISE EXCEPTION 'At least one invoice id is required';
  END IF;

  -- Validate any supplied discount amounts up-front (non-negative; matches the
  -- column CHECK). A blank/absent entry leaves the column at 0 (off).
  FOR v_id, v_amount IN
    SELECT key::uuid, COALESCE((value->>'amount_cents')::bigint, 0)
      FROM jsonb_each(v_disc)
  LOOP
    IF v_amount < 0 THEN
      RAISE EXCEPTION 'Discount Earned cannot be negative for invoice %', v_id;
    END IF;
  END LOOP;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing FROM idempotency_keys
     WHERE idempotency_key = p_idempotency_key AND operation = 'update_field_app_invoice_billing';
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  -- Header fields apply uniformly; the discount is resolved per-invoice from the
  -- map (absent id -> 0 / NULL). Only editable field-application invoices.
  UPDATE invoices i SET
    purchase_order_ref    = p_purchase_order_ref,
    payment_terms         = p_payment_terms,
    header_notes          = p_header_notes,
    due_date              = p_due_date,
    footer_notes          = p_footer_notes,
    internal_notes        = p_internal_notes,
    discount_earned_cents = COALESCE((v_disc -> i.id::text ->> 'amount_cents')::bigint, 0),
    discount_date         = (v_disc -> i.id::text ->> 'date')::date,
    updated_at            = now()
  WHERE i.id = ANY(p_invoice_ids)
    AND i.invoice_type = 'field_application'
    AND i.status IN ('draft', 'unposted');
  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated <> v_expected THEN
    RAISE EXCEPTION 'Invoice billing update affected % of % invoice(s) — some are not editable field-application invoices', v_updated, v_expected;
  END IF;

  v_result := jsonb_build_object('updated', v_updated);

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'update_field_app_invoice_billing', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."update_field_app_invoice_billing"("p_invoice_ids" "uuid"[], "p_purchase_order_ref" "text", "p_payment_terms" "text", "p_header_notes" "text", "p_due_date" "date", "p_footer_notes" "text", "p_internal_notes" "text", "p_discounts" "jsonb", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


