CREATE OR REPLACE FUNCTION "public"."update_vendor_bill"("p_bill_id" "uuid", "p_subtotal_cents" bigint, "p_adjustment_cents" bigint, "p_bill_date" "date", "p_due_date" "date", "p_notes" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid;
  v_actor_role text;
  v_bill record;
  v_active_payment_count integer;
  v_new_total_cents bigint;
  v_old_values jsonb;
  v_new_values jsonb;
  v_result jsonb;
  v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role <> 'admin' THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: only admins can edit vendor bills';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'update_vendor_bill');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  IF p_subtotal_cents IS NULL OR p_subtotal_cents <= 0 THEN
    RAISE EXCEPTION 'INVALID_AMOUNT: subtotal must be positive';
  END IF;
  IF p_due_date < p_bill_date THEN
    RAISE EXCEPTION 'INVALID_DATE_RANGE: due_date cannot precede bill_date';
  END IF;

  PERFORM check_period_open(p_bill_date);

  SELECT * INTO v_bill
  FROM vendor_bills
  WHERE id = p_bill_id AND deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BILL_NOT_FOUND';
  END IF;

  IF v_bill.status <> 'unpaid' THEN
    RAISE EXCEPTION 'BILL_NOT_EDITABLE: status is % (only unpaid bills can be edited)', v_bill.status;
  END IF;

  SELECT count(*) INTO v_active_payment_count
  FROM vendor_payments
  WHERE vendor_bill_id = p_bill_id AND voided_at IS NULL;

  IF v_active_payment_count > 0 THEN
    RAISE EXCEPTION 'BILL_HAS_ACTIVE_PAYMENTS: void each payment first (% active)', v_active_payment_count;
  END IF;

  v_new_total_cents := p_subtotal_cents + COALESCE(p_adjustment_cents, 0);

  IF v_new_total_cents <= 0 THEN
    RAISE EXCEPTION 'INVALID_AMOUNT: bill total must be positive (got %)', v_new_total_cents;
  END IF;

  v_old_values := jsonb_build_object(
    'subtotal_cents', v_bill.subtotal_cents,
    'adjustment_cents', v_bill.adjustment_cents,
    'total_cents', v_bill.total_cents,
    'bill_date', v_bill.bill_date,
    'due_date', v_bill.due_date,
    'notes', v_bill.notes
  );

  UPDATE vendor_bills SET
    subtotal_cents = p_subtotal_cents,
    adjustment_cents = COALESCE(p_adjustment_cents, 0),
    total_cents = v_new_total_cents,
    bill_date = p_bill_date,
    due_date = p_due_date,
    notes = p_notes,
    updated_at = now()
  WHERE id = p_bill_id;

  v_new_values := jsonb_build_object(
    'subtotal_cents', p_subtotal_cents,
    'adjustment_cents', COALESCE(p_adjustment_cents, 0),
    'total_cents', v_new_total_cents,
    'bill_date', p_bill_date,
    'due_date', p_due_date,
    'notes', p_notes
  );

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_user_id, actor_role,
    old_values, new_values, total_impact_cents, description
  ) VALUES (
    'vendor_bill_updated', 'vendor_bill', p_bill_id, v_actor, v_actor_role,
    v_old_values, v_new_values,
    v_new_total_cents - v_bill.total_cents,
    'Updated vendor bill ' || v_bill.bill_number || ' — total $' ||
    (v_bill.total_cents / 100.0)::numeric(12,2) || ' → $' ||
    (v_new_total_cents / 100.0)::numeric(12,2)
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id
  ) VALUES (
    'vendor_bill_updated',
    'Updated vendor bill ' || v_bill.bill_number,
    v_actor, 'vendor_bill', p_bill_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'bill_id', p_bill_id,
    'old_total_cents', v_bill.total_cents,
    'new_total_cents', v_new_total_cents
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'update_vendor_bill', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."update_vendor_bill"("p_bill_id" "uuid", "p_subtotal_cents" bigint, "p_adjustment_cents" bigint, "p_bill_date" "date", "p_due_date" "date", "p_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_product_supplier_link"("p_product_id" "uuid", "p_vendor_id" "uuid", "p_supplier_sku" "text", "p_supplier_product_name" "text", "p_supplier_uom" "text", "p_supplier_pack_description" "text", "p_inventory_units_per_supplier_unit" "text", "p_conversion_unit" "text", "p_comparison_status" "text", "p_comparison_note" "text", "p_is_preferred" boolean, "p_performed_by" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_link_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_request_fp text;
  v_units numeric(20,8);
  v_product public.products%ROWTYPE;
  v_link_id uuid;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'ACTOR_MISMATCH'; END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;
  IF NULLIF(btrim(p_supplier_sku), '') IS NULL
     OR NULLIF(btrim(p_supplier_uom), '') IS NULL
     OR NULLIF(btrim(p_supplier_pack_description), '') IS NULL THEN
    RAISE EXCEPTION 'SUPPLIER_LINK_REUSE_FIELDS_REQUIRED';
  END IF;
  IF NULLIF(btrim(p_supplier_product_name), '') IS NULL THEN
    RAISE EXCEPTION 'SUPPLIER_PRODUCT_NAME_REQUIRED';
  END IF;
  IF p_comparison_status NOT IN ('pending', 'comparable', 'not_comparable') THEN
    RAISE EXCEPTION 'SUPPLIER_COMPARISON_STATUS_INVALID';
  END IF;

  IF NULLIF(btrim(COALESCE(p_inventory_units_per_supplier_unit, '')), '') IS NOT NULL THEN
    IF btrim(p_inventory_units_per_supplier_unit) !~ '^[0-9]+([.][0-9]{1,8})?$' THEN
      RAISE EXCEPTION 'SUPPLIER_CONVERSION_INVALID';
    END IF;
    v_units := btrim(p_inventory_units_per_supplier_unit)::numeric(20,8);
    IF v_units <= 0 THEN RAISE EXCEPTION 'SUPPLIER_CONVERSION_INVALID'; END IF;
  END IF;
  IF p_comparison_status = 'comparable'
     AND (v_units IS NULL OR NULLIF(btrim(COALESCE(p_conversion_unit, '')), '') IS NULL) THEN
    RAISE EXCEPTION 'SUPPLIER_COMPARISON_REQUIRES_CONVERSION';
  END IF;

  SELECT * INTO v_product
  FROM public.products
  WHERE id = p_product_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_NOT_FOUND'; END IF;
  IF p_comparison_status = 'comparable'
     AND (
       NULLIF(btrim(COALESCE(v_product.inventory_unit, '')), '') IS NULL
       OR lower(btrim(p_conversion_unit)) IS DISTINCT FROM lower(btrim(v_product.inventory_unit))
     ) THEN
    RAISE EXCEPTION 'SUPPLIER_CONVERSION_UNIT_MUST_MATCH_INVENTORY_UNIT';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.vendors WHERE id = p_vendor_id AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'VENDOR_NOT_FOUND';
  END IF;

  v_request_fp := md5(jsonb_build_object(
    'actor_id', v_actor,
    'link_id', p_link_id,
    'product_id', p_product_id,
    'vendor_id', p_vendor_id,
    'supplier_sku', btrim(p_supplier_sku),
    'supplier_product_name', btrim(p_supplier_product_name),
    'supplier_uom', btrim(p_supplier_uom),
    'supplier_pack_description', btrim(p_supplier_pack_description),
    'inventory_units_per_supplier_unit', v_units,
    'conversion_unit', NULLIF(btrim(COALESCE(p_conversion_unit, '')), ''),
    'comparison_status', p_comparison_status,
    'comparison_note', NULLIF(btrim(COALESCE(p_comparison_note, '')), ''),
    'is_preferred', p_is_preferred
  )::text);
  v_existing := public.check_idempotency(p_idempotency_key, 'upsert_product_supplier_link');
  IF v_existing IS NOT NULL THEN
    IF v_existing->>'actor_id' IS DISTINCT FROM v_actor::text
       OR v_existing->>'request_fingerprint' IS DISTINCT FROM v_request_fp THEN
      RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH';
    END IF;
    RETURN v_existing->'response';
  END IF;

  -- Approved observations normalize through this link. Once that history exists,
  -- changing the product, package, or conversion in place would silently rewrite
  -- the meaning of old evidence. Require a new link for a changed supplier pack.
  IF p_link_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.product_supplier_links l
    WHERE l.id = p_link_id
      AND EXISTS (
        SELECT 1
        FROM public.supplier_price_observations observation
        WHERE observation.product_supplier_link_id = l.id
      )
      AND (
        l.product_id IS DISTINCT FROM p_product_id
        OR l.vendor_id IS DISTINCT FROM p_vendor_id
        OR l.supplier_sku IS DISTINCT FROM btrim(p_supplier_sku)
        OR l.supplier_product_name IS DISTINCT FROM btrim(p_supplier_product_name)
        OR l.supplier_uom IS DISTINCT FROM btrim(p_supplier_uom)
        OR l.supplier_pack_description IS DISTINCT FROM btrim(p_supplier_pack_description)
        OR l.inventory_units_per_supplier_unit IS DISTINCT FROM v_units
        OR l.conversion_unit IS DISTINCT FROM NULLIF(btrim(COALESCE(p_conversion_unit, '')), '')
        OR l.comparison_status IS DISTINCT FROM p_comparison_status
      )
  ) THEN
    RAISE EXCEPTION 'SUPPLIER_LINK_WITH_HISTORY_IMMUTABLE';
  END IF;

  IF p_is_preferred THEN
    UPDATE public.product_supplier_links
    SET is_preferred = false
    WHERE product_id = p_product_id
      AND is_preferred
      AND (p_link_id IS NULL OR id <> p_link_id);
  END IF;

  IF p_link_id IS NULL THEN
    INSERT INTO public.product_supplier_links(
      product_id, vendor_id, supplier_sku, supplier_product_name,
      supplier_uom, supplier_pack_description,
      inventory_units_per_supplier_unit, conversion_unit,
      comparison_status, comparison_note,
      link_status, is_preferred, match_confidence,
      confirmed_by, confirmed_at, created_by
    ) VALUES (
      p_product_id, p_vendor_id, btrim(p_supplier_sku), btrim(p_supplier_product_name),
      btrim(p_supplier_uom), btrim(p_supplier_pack_description),
      v_units, NULLIF(btrim(COALESCE(p_conversion_unit, '')), ''),
      p_comparison_status, NULLIF(btrim(COALESCE(p_comparison_note, '')), ''),
      'confirmed', p_is_preferred, 1,
      v_actor, now(), v_actor
    ) RETURNING id INTO v_link_id;
  ELSE
    UPDATE public.product_supplier_links
    SET product_id = p_product_id,
        vendor_id = p_vendor_id,
        supplier_sku = btrim(p_supplier_sku),
        supplier_product_name = btrim(p_supplier_product_name),
        supplier_uom = btrim(p_supplier_uom),
        supplier_pack_description = btrim(p_supplier_pack_description),
        inventory_units_per_supplier_unit = v_units,
        conversion_unit = NULLIF(btrim(COALESCE(p_conversion_unit, '')), ''),
        comparison_status = p_comparison_status,
        comparison_note = NULLIF(btrim(COALESCE(p_comparison_note, '')), ''),
        link_status = 'confirmed',
        is_active = true,
        is_preferred = p_is_preferred,
        match_confidence = 1,
        confirmed_by = v_actor,
        confirmed_at = now()
    WHERE id = p_link_id
    RETURNING id INTO v_link_id;
    IF v_link_id IS NULL THEN RAISE EXCEPTION 'SUPPLIER_LINK_NOT_FOUND'; END IF;
  END IF;

  SELECT jsonb_build_object(
    'id', l.id,
    'product_id', l.product_id,
    'vendor_id', l.vendor_id,
    'supplier_sku', l.supplier_sku,
    'supplier_product_name', l.supplier_product_name,
    'supplier_uom', l.supplier_uom,
    'supplier_pack_description', l.supplier_pack_description,
    'inventory_units_per_supplier_unit', l.inventory_units_per_supplier_unit,
    'conversion_unit', l.conversion_unit,
    'comparison_status', l.comparison_status,
    'link_status', l.link_status,
    'is_reusable', l.is_reusable,
    'is_preferred', l.is_preferred
  ) INTO v_result
  FROM public.product_supplier_links l
  WHERE l.id = v_link_id;

  PERFORM public.save_idempotency(
    p_idempotency_key,
    'upsert_product_supplier_link',
    jsonb_build_object(
      'actor_id', v_actor,
      'request_fingerprint', v_request_fp,
      'response', v_result
    )
  );
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."upsert_product_supplier_link"("p_product_id" "uuid", "p_vendor_id" "uuid", "p_supplier_sku" "text", "p_supplier_product_name" "text", "p_supplier_uom" "text", "p_supplier_pack_description" "text", "p_inventory_units_per_supplier_unit" "text", "p_conversion_unit" "text", "p_comparison_status" "text", "p_comparison_note" "text", "p_is_preferred" boolean, "p_performed_by" "uuid", "p_idempotency_key" "text", "p_link_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_commission_split_json"("p_split" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_split jsonb;
  v_recipient text;
  v_seen text[] := ARRAY[]::text[];
  v_percentage numeric;
  v_total numeric := 0;
BEGIN
  IF p_split IS NULL OR p_split = 'null'::jsonb THEN
    RETURN;
  END IF;

  IF jsonb_typeof(p_split) <> 'object'
     OR NOT (p_split ? 'splits')
     OR jsonb_typeof(p_split->'splits') <> 'array' THEN
    RAISE EXCEPTION 'COMMISSION_SPLIT_INVALID: expected object with splits array';
  END IF;

  IF jsonb_array_length(p_split->'splits') = 0 THEN
    RETURN;
  END IF;

  FOR v_split IN SELECT value FROM jsonb_array_elements(p_split->'splits')
  LOOP
    v_recipient := NULLIF(btrim(v_split->>'recipient'), '');
    IF v_recipient IS NULL THEN
      RAISE EXCEPTION 'COMMISSION_SPLIT_INVALID: recipient is required';
    END IF;

    IF lower(v_recipient) = ANY(v_seen) THEN
      RAISE EXCEPTION 'COMMISSION_SPLIT_INVALID: duplicate recipient %', v_recipient;
    END IF;
    v_seen := array_append(v_seen, lower(v_recipient));

    BEGIN
      v_percentage := (v_split->>'percentage')::numeric;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'COMMISSION_SPLIT_INVALID: invalid percentage for %', v_recipient;
    END;

    IF v_percentage <= 0 OR v_percentage > 100 THEN
      RAISE EXCEPTION 'COMMISSION_SPLIT_INVALID: percentage out of range for %', v_recipient;
    END IF;

    v_total := v_total + v_percentage;
  END LOOP;

  IF abs(v_total - 100) > 0.01 THEN
    RAISE EXCEPTION 'COMMISSION_SPLIT_INVALID: percentages total %.2f, expected 100.00', v_total;
  END IF;
END;
$$;


ALTER FUNCTION "public"."validate_commission_split_json"("p_split" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_units"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Validate inventory_unit matches product_form
  IF NEW.product_form IS NOT NULL AND NEW.inventory_unit IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM unit_conversions
      WHERE unit = NEW.inventory_unit
        AND (unit_type = NEW.product_form OR unit_type = 'both')
    ) THEN
      RAISE EXCEPTION 'inventory_unit "%" is not valid for product_form "%"',
        NEW.inventory_unit, NEW.product_form;
    END IF;
  END IF;

  -- Validate container_unit matches product_form
  IF NEW.product_form IS NOT NULL AND NEW.container_unit IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM unit_conversions
      WHERE unit = NEW.container_unit
        AND (unit_type = NEW.product_form OR unit_type = 'both')
    ) THEN
      RAISE EXCEPTION 'container_unit "%" is not valid for product_form "%"',
        NEW.container_unit, NEW.product_form;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_product_units"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_supplier_price_observation_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_link public.product_supplier_links%ROWTYPE;
  v_row public.supplier_price_import_rows%ROWTYPE;
  v_prior public.supplier_price_observations%ROWTYPE;
BEGIN
  SELECT * INTO v_link
  FROM public.product_supplier_links
  WHERE id = NEW.product_supplier_link_id;
  IF NOT FOUND
     OR v_link.product_id IS DISTINCT FROM NEW.product_id
     OR v_link.vendor_id IS DISTINCT FROM NEW.vendor_id THEN
    RAISE EXCEPTION 'SUPPLIER_LINK_MISMATCH';
  END IF;

  SELECT * INTO v_row
  FROM public.supplier_price_import_rows
  WHERE id = NEW.import_row_id;
  IF NOT FOUND
     OR v_row.import_id IS DISTINCT FROM NEW.import_id
     OR v_row.product_id IS DISTINCT FROM NEW.product_id
     OR v_row.vendor_id IS DISTINCT FROM NEW.vendor_id
     OR v_row.product_supplier_link_id IS DISTINCT FROM NEW.product_supplier_link_id THEN
    RAISE EXCEPTION 'SUPPLIER_IMPORT_PROVENANCE_MISMATCH';
  END IF;

  IF NEW.supersedes_observation_id IS NOT NULL THEN
    SELECT * INTO v_prior
    FROM public.supplier_price_observations
    WHERE id = NEW.supersedes_observation_id;
    IF NOT FOUND
       OR v_prior.product_id IS DISTINCT FROM NEW.product_id
       OR v_prior.vendor_id IS DISTINCT FROM NEW.vendor_id
       OR v_prior.product_supplier_link_id IS DISTINCT FROM NEW.product_supplier_link_id THEN
      RAISE EXCEPTION 'SUPPLIER_SUPERSESSION_MISMATCH';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_supplier_price_observation_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vendor_bills_positive_subtotal_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.subtotal_cents IS NULL OR NEW.subtotal_cents <= 0 THEN
    RAISE EXCEPTION 'INVALID_AMOUNT: vendor_bill subtotal must be positive (got %)', NEW.subtotal_cents;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."vendor_bills_positive_subtotal_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_commission_payment"("p_payment_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_payment record;
  v_reset_count integer;
  v_cancelled_count integer;
  v_existing jsonb;
  v_result jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT is_admin() THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'REASON_REQUIRED'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'void_commission_payment');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_payment
  FROM commission_payments
  WHERE id = p_payment_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'COMMISSION_PAYMENT_NOT_FOUND'; END IF;
  IF v_payment.status NOT IN ('posted', 'unposted') THEN
    RAISE EXCEPTION 'INVALID_COMMISSION_PAYMENT_STATUS: %', v_payment.status;
  END IF;

  -- PARKED-003 (codex-driven cycle 2, Claude-independent HIGH): a commission-payment
  -- void retroactively changes the commission ledger and writes the append-only
  -- financial_audit_log. By the void_invoice / void_payment / reverse_write_off
  -- precedent (every other reverse-side money RPC) AND by direct parallel to PARKED-001
  -- (unapply_credit_memo), this must respect the ORIGINAL payment's accounting period.
  -- Gate AFTER the existence + status guards so error-message stability is preserved.
  -- Use COALESCE(v_payment.payment_date, CURRENT_DATE) — mirrors post_commission_payment
  -- exactly (the table column is NOT NULL today but COALESCE matches the precedent).
  PERFORM check_period_open(COALESCE(v_payment.payment_date, CURRENT_DATE));

  UPDATE commission_payments SET
    status = 'voided',
    updated_at = now()
  WHERE id = p_payment_id;

  -- OVERNIGHT FIX (finding #15): only return a batch commission to 'pending' (re-payable) if its
  -- ORDER is still live. A commission whose order was voided/cancelled/deleted after the batch was
  -- posted must NOT be resurrected — set it 'cancelled' / amount 0, matching cancel_order/void_order.
  UPDATE commissions c SET
    status = 'pending',
    paid_date = NULL
  WHERE c.id IN (
    SELECT commission_id FROM commission_payment_items
    WHERE commission_payment_id = p_payment_id
  )
  AND NOT EXISTS (
    SELECT 1 FROM orders o
    WHERE o.id = c.order_id
      AND (o.status IN ('cancelled', 'voided') OR o.deleted_at IS NOT NULL)
  )
  -- U8 (#99): same liveness rule for the application channel — a job-sourced
  -- commission is only re-payable while ITS OWN minting invoice is still live.
  -- Codex R1 P1: test c.invoice_id (generation-precise), NOT job-level liveness —
  -- after a void→re-invoice cycle the job has a live invoice again, but it belongs
  -- to the NEW commission generation, and the old batch rows must stay dead.
  AND NOT (
    c.job_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM invoices i
      WHERE i.id = c.invoice_id
        AND i.status NOT IN ('voided', 'cancelled')
        AND i.deleted_at IS NULL
    )
  )
  -- U8 / Codex R1 P1 hardening (both channels): a row already 'cancelled' (by an
  -- invoice void or order cancel that ran while it sat in this batch) must never be
  -- resurrected to payable by voiding the batch.
  AND c.status <> 'cancelled';
  GET DIAGNOSTICS v_reset_count = ROW_COUNT;

  UPDATE commissions c SET
    status = 'cancelled',
    commission_amount = 0,
    paid_date = NULL
  WHERE c.id IN (
    SELECT commission_id FROM commission_payment_items
    WHERE commission_payment_id = p_payment_id
  )
  AND (
    EXISTS (
      SELECT 1 FROM orders o
      WHERE o.id = c.order_id
        AND (o.status IN ('cancelled', 'voided') OR o.deleted_at IS NOT NULL)
    )
    -- U8 (#99): job-lineage deadness — the commission's own minting invoice is
    -- no longer live (Codex R1 P1: generation-precise via c.invoice_id).
    OR (
      c.job_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM invoices i
        WHERE i.id = c.invoice_id
          AND i.status NOT IN ('voided', 'cancelled')
          AND i.deleted_at IS NULL
      )
    )
  );
  GET DIAGNOSTICS v_cancelled_count = ROW_COUNT;

  INSERT INTO financial_audit_log (
    operation_type,
    entity_type,
    entity_id,
    actor_role,
    old_values, new_values, description
  ) VALUES (
    'commission_payment_voided', 'commission_payment', p_payment_id,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object('status', v_payment.status, 'total_amount', v_payment.total_amount),
    jsonb_build_object('status', 'voided', 'commissions_reset', v_reset_count, 'commissions_cancelled_dead_order', v_cancelled_count),
    'Commission payment ' || v_payment.payment_number || ' voided: ' || p_reason
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type,
    related_entity_id
  ) VALUES (
    'commission_payment_voided',
    'Commission payment ' || v_payment.payment_number || ' voided: ' || p_reason,
    v_actor, 'commission_payment', p_payment_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'payment_id', p_payment_id,
    'payment_number', v_payment.payment_number,
    'commissions_reset', v_reset_count,
    'commissions_cancelled_dead_order', v_cancelled_count
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'void_commission_payment', v_result);
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."void_commission_payment"("p_payment_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_delivery"("p_delivery_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor         uuid;
  v_delivery      record;
  v_item          record;
  v_posted_invoices_exist boolean := false;
  v_order_confirmed boolean;
  v_order_fulfilled boolean;
  v_new_order_status text;
  v_closed_period record;
  v_effective_completion_date date;
  v_admin record;
  -- DELTA-IDEM BEGIN (#11 nightly-debug: canonical idempotency — cache/replay the rich result)
  v_existing jsonb;
  v_result jsonb;
  -- DELTA-IDEM END
BEGIN
  -- Strict actor pattern (codex audit F1)
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;

  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Admin access required to void a completed delivery';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required to void a delivery';
  END IF;

  -- DELTA-IDEM BEGIN (#11: canonical check — replay the cached rich payload, not a bare marker)
  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'void_delivery');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;
  -- DELTA-IDEM END

  SELECT * INTO v_delivery
  FROM deliveries
  WHERE id = p_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Delivery not found: %', p_delivery_id;
  END IF;

  IF v_delivery.status != 'completed' THEN
    RAISE EXCEPTION 'Only completed deliveries can be voided (current status: %)', v_delivery.status;
  END IF;

  -- A void reverses the completed delivery's accounting event, so period
  -- detection must use the actual Chicago completion business date rather
  -- than the schedule date. Keep the schedule date only as a legacy fallback.
  v_effective_completion_date := COALESCE(
    (v_delivery.completed_at AT TIME ZONE 'America/Chicago')::date,
    v_delivery.scheduled_date
  );

  SELECT id, period_start, period_end
    INTO v_closed_period
    FROM accounting_periods
   WHERE status = 'closed'
     AND v_effective_completion_date BETWEEN period_start AND period_end
   LIMIT 1;

  IF FOUND THEN
    INSERT INTO activity_feed (
      event_type, description, performed_by,
      related_entity_type, related_entity_id, customer_id
    ) VALUES (
      'backdated_delivery_in_closed_period',
      'WARNING: Delivery ' || v_delivery.delivery_number ||
        ' voided for completion date ' || v_effective_completion_date::text ||
        ' which falls in CLOSED accounting period ' ||
        v_closed_period.period_start::text || ' to ' ||
        v_closed_period.period_end::text || '. Reason: ' || p_reason ||
        '. Operation proceeded; verify with finance.',
      v_actor, 'delivery', p_delivery_id, v_delivery.customer_id
    );

    FOR v_admin IN SELECT id FROM profiles WHERE role = 'admin' AND is_active = true
    LOOP
      INSERT INTO notifications (
        user_id, title, message, notification_type,
        related_entity_type, related_entity_id
      ) VALUES (
        v_admin.id,
        'Backdated Delivery Void',
        'Delivery ' || v_delivery.delivery_number ||
          ' was voided for completion date ' || v_effective_completion_date::text ||
          ' — that date is inside a CLOSED accounting period (' ||
          v_closed_period.period_start::text || ' to ' ||
          v_closed_period.period_end::text || '). Inventory was restored and ' ||
          'draft invoices were auto-cancelled. Verify the financial impact.',
        'period_warning', 'delivery', p_delivery_id
      );
    END LOOP;
  END IF;

  PERFORM set_config('app.admin_override', 'true', true);

  FOR v_item IN
    SELECT di.*, p.product_name
    FROM delivery_items di
    JOIN products p ON p.id = di.product_id
    WHERE di.delivery_id = p_delivery_id
      AND di.quantity_delivered > 0
  LOOP
    UPDATE inventory SET
      quantity_available = quantity_available + v_item.quantity_delivered,
      quantity_prebooked = quantity_prebooked + v_item.quantity_delivered,
      updated_at = now()
    WHERE product_id = v_item.product_id AND location = 'Main Warehouse';

    INSERT INTO inventory_transactions (
      product_id, transaction_type, quantity, from_location,
      order_id, delivery_id, performed_by, notes
    ) VALUES (
      v_item.product_id, 'void_delivery_reversal', v_item.quantity_delivered, 'Main Warehouse',
      v_delivery.order_id, p_delivery_id, v_actor,
      'Delivery ' || v_delivery.delivery_number || ' voided: ' || p_reason || ' (available + prebooked restored)'
    );

    UPDATE order_items SET
      quantity_delivered = GREATEST(quantity_delivered - v_item.quantity_delivered, 0),
      quantity_remaining = quantity_remaining + v_item.quantity_delivered
    WHERE id = v_item.order_item_id;
  END LOOP;

  DELETE FROM delivery_remainders WHERE original_delivery_id = p_delivery_id;

  SELECT NOT EXISTS (
    SELECT 1 FROM order_items
    WHERE order_id = v_delivery.order_id AND quantity_remaining > 0
  ) INTO v_order_fulfilled;

  SELECT NOT EXISTS (
    SELECT 1 FROM order_items
    WHERE order_id = v_delivery.order_id AND quantity_remaining < total_units_needed
  ) INTO v_order_confirmed;

  v_new_order_status :=
    CASE
      WHEN v_order_fulfilled  THEN 'fulfilled'
      WHEN v_order_confirmed  THEN 'confirmed'
      ELSE 'partially_fulfilled'
    END;

  UPDATE orders SET
    status = v_new_order_status,
    updated_at = now()
  WHERE id = v_delivery.order_id;

  -- U2 (Codex P1): scope the auto-cancel to THIS delivery's own draft invoice or an
  -- order-level one (delivery_id IS NULL) — was per-order, which would cancel a
  -- SIBLING delivery's draft invoice on void of this delivery.
  UPDATE invoices SET
    status      = 'cancelled',
    void_reason = 'Auto-cancelled: delivery ' || v_delivery.delivery_number || ' was voided by admin',
    updated_at  = now()
  WHERE order_id = v_delivery.order_id AND status = 'draft'
    AND (delivery_id = p_delivery_id OR delivery_id IS NULL);

  -- U2 (Codex P1): read-only "posted invoice needs review" flag — scope it the same
  -- way so a SIBLING delivery's posted invoice (untouched by this void) no longer
  -- raises a false manual-review warning. No guard/blocking behaviour hangs off this
  -- flag, so scoping cannot loosen a safety check.
  SELECT EXISTS (
    SELECT 1 FROM invoices
    WHERE order_id = v_delivery.order_id AND status = 'posted'
      AND (delivery_id = p_delivery_id OR delivery_id IS NULL)
  ) INTO v_posted_invoices_exist;

  UPDATE deliveries SET
    status     = 'voided',
    updated_at = now()
  WHERE id = p_delivery_id;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_user_id, actor_role,
    old_values, new_values, description
  ) VALUES (
    'delivery_voided', 'delivery', p_delivery_id, v_actor,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object('status', 'completed'),
    jsonb_build_object('status', 'voided', 'order_status', v_new_order_status),
    'Delivery ' || v_delivery.delivery_number || ' voided: ' || p_reason
  );

  INSERT INTO activity_feed (
    event_type, description, performed_by,
    related_entity_type, related_entity_id, customer_id
  ) VALUES (
    'delivery_voided',
    'Delivery ' || v_delivery.delivery_number || ' voided: ' || p_reason,
    v_actor, 'delivery', p_delivery_id, v_delivery.customer_id
  );

  -- DELTA-IDEM BEGIN (#11: build the rich result first, then cache it via the canonical helper + replay it)
  v_result := jsonb_build_object(
    'success',                true,
    'delivery_id',            p_delivery_id,
    'delivery_number',        v_delivery.delivery_number,
    'new_order_status',       v_new_order_status,
    'posted_invoices_exist',  v_posted_invoices_exist
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'void_delivery', v_result);
  END IF;

  PERFORM set_config('app.admin_override', 'false', true);

  RETURN v_result;
  -- DELTA-IDEM END
END;
$$;


ALTER FUNCTION "public"."void_delivery"("p_delivery_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_invoice"("p_invoice_id" "uuid", "p_void_reason" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_contract CONSTANT text := 'void_invoice_v1';
  v_request jsonb;
  v_fingerprint text;
  v_replay jsonb;
  v_governed boolean := false;
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles p
     WHERE p.id = v_actor
       AND p.is_active = true
       AND p.role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Only admin users can void invoices';
  END IF;

  v_request := jsonb_build_object(
    'contract_version', v_contract,
    'actor_id', v_actor,
    'invoice_id', p_invoice_id,
    'void_reason', p_void_reason
  );
  v_fingerprint := md5(v_request::text);
  IF p_idempotency_key IS NOT NULL THEN
    v_replay := public._claim_bound_lifecycle_idempotency(
      p_idempotency_key,
      'void_invoice',
      v_contract,
      v_fingerprint,
      v_request
    );
    IF v_replay IS NOT NULL THEN
      RETURN;
    END IF;
  END IF;

  PERFORM 1
    FROM public.invoices i
   WHERE i.id = p_invoice_id
   FOR UPDATE;

  SELECT EXISTS (
    SELECT 1
      FROM public.split_invoice_provenance p
     WHERE p.invoice_id = p_invoice_id
  ) INTO v_governed;

  IF v_governed THEN
    INSERT INTO public.split_invoice_mutation_claims (
      transaction_id, invoice_id, operation
    ) VALUES (
      pg_current_xact_id(), p_invoice_id, 'void_invoice'
    );
  END IF;

  PERFORM public._void_invoice_split_provenance_impl_20260719(
    p_invoice_id,
    p_void_reason,
    NULL::text
  );

  IF v_governed THEN
    UPDATE public.split_invoice_provenance p
       SET total_amount_cents = i.total_amount_cents,
           content_claim = public._split_invoice_content_claim(i.id)
      FROM public.invoices i
     WHERE p.invoice_id = p_invoice_id
       AND i.id = p.invoice_id
       AND p.order_id = i.order_id
       AND p.invoice_group_id = i.invoice_group_id
       AND p.customer_id = i.customer_id
       AND p.invoice_type = i.invoice_type
       AND p.season = i.season
       AND i.status IN ('voided', 'cancelled');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'SPLIT_INVOICE_TERMINAL_PROVENANCE_REFRESH_FAILED';
    END IF;

    DELETE FROM public.split_invoice_mutation_claims
     WHERE transaction_id = pg_current_xact_id()
       AND invoice_id = p_invoice_id
       AND operation = 'void_invoice';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'SPLIT_INVOICE_VOID_CLAIM_LOST';
    END IF;
  END IF;

  PERFORM public._bind_completed_lifecycle_idempotency(
    p_idempotency_key,
    'void_invoice',
    v_contract,
    v_fingerprint,
    v_request,
    'true'::jsonb
  );
END;
$$;


ALTER FUNCTION "public"."void_invoice"("p_invoice_id" "uuid", "p_void_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_order"("p_order_id" "uuid", "p_performed_by" "uuid", "p_reason" "text" DEFAULT 'Voided by admin'::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing jsonb;
  v_order_status text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_idempotency(p_idempotency_key, 'void_order');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT o.status INTO v_order_status
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF;

  IF EXISTS (
    SELECT 1
    FROM public.returns r
    WHERE r.order_id = p_order_id
      AND r.deleted_at IS NULL
      AND r.status IN ('received', 'credited')
  ) THEN
    RAISE EXCEPTION 'ORDER_HAS_RECEIVED_RETURN';
  END IF;

  RETURN public._void_order_impl_20260714(
    p_order_id, p_performed_by, p_reason, p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."void_order"("p_order_id" "uuid", "p_performed_by" "uuid", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_payment"("p_allocation_set_id" "uuid", "p_reason" "text", "p_performed_by" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_set              record;
  v_alloc            record;
  v_actor            uuid;
  v_reversed_cents   bigint := 0;
  v_invoice_count    int    := 0;
  v_prepay_reversed  bigint := 0;
  v_old_balance      bigint;
  v_credit           record;
  v_app              record;
  v_apps_reversed_cents bigint := 0;
  v_existing         jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_performed_by IS NOT NULL AND p_performed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'admin') THEN
    RAISE EXCEPTION 'INSUFFICIENT_ROLE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result INTO v_existing
      FROM idempotency_keys
      WHERE idempotency_key = p_idempotency_key AND operation = 'void_payment';
    IF v_existing IS NOT NULL THEN
      RETURN jsonb_build_object('success', true, 'allocation_set_id', p_allocation_set_id, 'idempotent', true);
    END IF;
  END IF;

  SELECT * INTO v_set FROM allocation_sets WHERE id = p_allocation_set_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Allocation set not found: %', p_allocation_set_id; END IF;
  IF NOT v_set.is_active THEN RAISE EXCEPTION 'Payment already voided'; END IF;

  PERFORM check_period_open(COALESCE(v_set.payment_date, CURRENT_DATE));

  FOR v_alloc IN
    SELECT ila.invoice_id, SUM(ila.amount_cents) AS total_amount
    FROM invoice_line_allocations ila
    WHERE ila.allocation_set_id = p_allocation_set_id AND ila.invoice_id IS NOT NULL
    GROUP BY ila.invoice_id
  LOOP
    UPDATE invoices
    SET paid_amount_cents = GREATEST(paid_amount_cents - v_alloc.total_amount, 0),
        status = CASE
          WHEN status IN ('paid', 'posted') THEN
            -- CREDIT-APPLY: include credit_applied_cents in the settled recompute
            CASE WHEN (total_amount_cents - (GREATEST(paid_amount_cents - v_alloc.total_amount, 0) + prepay_applied_cents + write_off_cents + credit_applied_cents)) <= 0
                 THEN 'paid' ELSE 'posted' END
          ELSE status
        END,
        updated_at = now()
    WHERE id = v_alloc.invoice_id;
    v_reversed_cents := v_reversed_cents + v_alloc.total_amount;
    v_invoice_count  := v_invoice_count + 1;
  END LOOP;

  FOR v_credit IN
    SELECT id, balance_cents
    FROM prepay_credits
    WHERE source_type = 'overpayment'
      AND customer_id = v_set.customer_id
      AND allocation_set_id = p_allocation_set_id
    FOR UPDATE
  LOOP
    FOR v_app IN
      SELECT pa.invoice_id, pa.applied_amount_cents
      FROM prepay_applications pa
      WHERE pa.prepay_credit_id = v_credit.id
    LOOP
      PERFORM 1 FROM invoices WHERE id = v_app.invoice_id FOR UPDATE;
      UPDATE invoices
      SET prepay_applied_cents = GREATEST(prepay_applied_cents - v_app.applied_amount_cents, 0),
          status = CASE
            WHEN status IN ('paid', 'posted') THEN
              CASE WHEN (total_amount_cents - (paid_amount_cents + GREATEST(prepay_applied_cents - v_app.applied_amount_cents, 0) + write_off_cents + credit_applied_cents)) <= 0
                   THEN 'paid' ELSE 'posted' END
            ELSE status
          END,
          updated_at = now()
      WHERE id = v_app.invoice_id;
      v_apps_reversed_cents := v_apps_reversed_cents + v_app.applied_amount_cents;
    END LOOP;

    DELETE FROM prepay_applications WHERE prepay_credit_id = v_credit.id;

    UPDATE prepay_credits
    SET balance_cents = 0, original_amount_cents = 0, notes = COALESCE(notes, '') || ' [VOIDED: ' || p_reason || ']', updated_at = now()
    WHERE id = v_credit.id;
    v_prepay_reversed := v_prepay_reversed + v_credit.balance_cents;
  END LOOP;

  IF v_prepay_reversed > 0 THEN
    UPDATE customers SET prepay_balance_cents = GREATEST(prepay_balance_cents - v_prepay_reversed, 0) WHERE id = v_set.customer_id;
  END IF;

  UPDATE allocation_sets SET is_active = false, notes = COALESCE(notes, '') || ' [VOIDED: ' || p_reason || ']', updated_at = now() WHERE id = p_allocation_set_id;

  INSERT INTO financial_audit_log (
    operation_type, entity_type, entity_id, actor_user_id, old_values, new_values, total_impact_cents, description
  ) VALUES (
    'payment_voided', 'allocation_set', p_allocation_set_id, v_actor,
    jsonb_build_object('total_payment_cents', v_set.total_payment_cents, 'total_allocated_cents', v_set.total_allocated_cents, 'payment_method', v_set.payment_method, 'check_number', v_set.check_number, 'customer_id', v_set.customer_id),
    jsonb_build_object('reason', p_reason, 'invoices_reversed', v_invoice_count, 'prepay_reversed_cents', v_prepay_reversed, 'prepay_applications_reversed_cents', v_apps_reversed_cents),
    -1 * v_reversed_cents,
    'Voided payment ' || COALESCE(v_set.check_number, v_set.reference_number, v_set.id::text) || ' — ' || p_reason
  );

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO idempotency_keys (idempotency_key, operation, result)
    VALUES (p_idempotency_key, 'void_payment', to_jsonb(p_allocation_set_id));
  END IF;

  RETURN jsonb_build_object('success', true, 'allocation_set_id', p_allocation_set_id, 'reversed_cents', v_reversed_cents, 'invoices_affected', v_invoice_count, 'prepay_reversed_cents', v_prepay_reversed, 'prepay_applications_reversed_cents', v_apps_reversed_cents);
END;
$$;


ALTER FUNCTION "public"."void_payment"("p_allocation_set_id" "uuid", "p_reason" "text", "p_performed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_vendor_bill"("p_vendor_bill_id" "uuid", "p_reason" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bill record; v_actor uuid; v_actor_role text; v_existing jsonb; v_active_payments int;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT role INTO v_actor_role FROM profiles WHERE id = v_actor AND is_active = true;
  IF v_actor_role IS NULL OR v_actor_role <> 'admin' THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin role required to void vendor bills';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'REASON_REQUIRED: void requires a reason string';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'void_vendor_bill');
    IF v_existing IS NOT NULL THEN RETURN; END IF;
  END IF;

  SELECT * INTO v_bill FROM vendor_bills WHERE id = p_vendor_bill_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'BILL_NOT_FOUND: vendor bill % does not exist', p_vendor_bill_id; END IF;
  IF v_bill.status = 'voided' THEN RAISE EXCEPTION 'BILL_ALREADY_VOIDED'; END IF;

  SELECT count(*) INTO v_active_payments
    FROM vendor_payments
   WHERE vendor_bill_id = p_vendor_bill_id AND voided_at IS NULL;

  -- (codex audit F3): block voiding ANY bill with active payments
  IF v_active_payments > 0 THEN
    RAISE EXCEPTION
      'BILL_HAS_ACTIVE_PAYMENTS: bill has % active payment(s); void each payment first',
      v_active_payments;
  END IF;

  PERFORM check_period_open(v_bill.bill_date);

  UPDATE vendor_bills SET
    status = 'voided', voided_at = now(), voided_by = v_actor,
    void_reason = p_reason, updated_at = now()
  WHERE id = p_vendor_bill_id;

  INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_user_id, actor_role,
    old_values, new_values, total_impact_cents, description)
  VALUES ('vendor_bill_voided', 'vendor_bill', p_vendor_bill_id, v_actor, v_actor_role,
    jsonb_build_object('status', v_bill.status),
    jsonb_build_object('status', 'voided', 'void_reason', p_reason),
    -v_bill.total_cents,
    'Vendor bill ' || COALESCE(NULLIF(v_bill.bill_number, ''), p_vendor_bill_id::text) ||
      ' voided: ' || p_reason);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'void_vendor_bill',
      jsonb_build_object('voided', true, 'bill_id', p_vendor_bill_id));
  END IF;
END;
$$;


ALTER FUNCTION "public"."void_vendor_bill"("p_vendor_bill_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_vendor_payment"("p_payment_id" "uuid", "p_reason" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid; v_payment record; v_bill record; v_new_paid_cents bigint;
  v_new_status text; v_result jsonb; v_existing jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_actor AND is_active = true AND role = 'admin') THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: only admins can void vendor payments';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) = 0 THEN RAISE EXCEPTION 'REASON_REQUIRED'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := check_idempotency(p_idempotency_key, 'void_vendor_payment');
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;

  SELECT * INTO v_payment FROM vendor_payments WHERE id = p_payment_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PAYMENT_NOT_FOUND'; END IF;
  IF v_payment.voided_at IS NOT NULL THEN RAISE EXCEPTION 'PAYMENT_ALREADY_VOIDED'; END IF;

  SELECT * INTO v_bill FROM vendor_bills WHERE id = v_payment.vendor_bill_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'BILL_NOT_FOUND: parent vendor_bill of this payment is missing'; END IF;

  PERFORM check_period_open(v_payment.payment_date);

  v_new_paid_cents := GREATEST(v_bill.paid_cents - v_payment.amount_cents, 0);
  v_new_status := CASE
    WHEN v_new_paid_cents = 0 THEN 'unpaid'
    WHEN v_new_paid_cents < v_bill.total_cents THEN 'partially_paid'
    ELSE 'paid' END;

  UPDATE vendor_bills SET paid_cents = v_new_paid_cents, status = v_new_status, updated_at = now()
    WHERE id = v_bill.id;

  UPDATE vendor_payments SET voided_at = now(), voided_by = v_actor, void_reason = p_reason
    WHERE id = p_payment_id;

  INSERT INTO financial_audit_log (operation_type, entity_type, entity_id, actor_role,
    old_values, new_values, total_impact_cents, description)
  VALUES ('vendor_payment_voided', 'vendor_payment', p_payment_id,
    (SELECT role FROM profiles WHERE id = v_actor),
    jsonb_build_object('amount_cents', v_payment.amount_cents,
      'bill_id', v_bill.id, 'bill_status_before', v_bill.status,
      'bill_paid_cents_before', v_bill.paid_cents),
    jsonb_build_object('voided_at', now()::text, 'void_reason', p_reason,
      'bill_status_after', v_new_status, 'bill_paid_cents_after', v_new_paid_cents),
    -1 * v_payment.amount_cents,
    'Voided vendor payment of $' || (v_payment.amount_cents / 100.0)::numeric(12,2) ||
    ' on bill — ' || p_reason);

  INSERT INTO activity_feed (event_type, description, performed_by,
    related_entity_type, related_entity_id)
  VALUES ('vendor_payment_voided',
    'Voided vendor payment $' || (v_payment.amount_cents / 100.0)::numeric(12,2) || ' — ' || p_reason,
    v_actor, 'vendor_payment', p_payment_id);

  v_result := jsonb_build_object('success', true, 'payment_id', p_payment_id,
    'bill_id', v_bill.id, 'voided_amount_cents', v_payment.amount_cents,
    'new_paid_cents', v_new_paid_cents, 'new_bill_status', v_new_status);

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM save_idempotency(p_idempotency_key, 'void_vendor_payment', v_result);
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."void_vendor_payment"("p_payment_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."write_product_pricing_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := NULLIF(current_setting('crx.pricing_actor', true), '')::uuid;
  v_source text := NULLIF(current_setting('crx.pricing_source', true), '');
  v_reason text := NULLIF(current_setting('crx.pricing_reason', true), '');
  v_change_set_id uuid := NULLIF(current_setting('crx.pricing_change_set_id', true), '')::uuid;
BEGIN
  IF NOT (
    OLD.current_cost IS DISTINCT FROM NEW.current_cost
    OR OLD.tier1_margin IS DISTINCT FROM NEW.tier1_margin
    OR OLD.tier2_margin IS DISTINCT FROM NEW.tier2_margin
    OR OLD.tier3_margin IS DISTINCT FROM NEW.tier3_margin
    OR OLD.tier1_price IS DISTINCT FROM NEW.tier1_price
    OR OLD.tier2_price IS DISTINCT FROM NEW.tier2_price
    OR OLD.tier3_price IS DISTINCT FROM NEW.tier3_price
    OR OLD.tier1_gross_margin IS DISTINCT FROM NEW.tier1_gross_margin
    OR OLD.tier2_gross_margin IS DISTINCT FROM NEW.tier2_gross_margin
    OR OLD.tier3_gross_margin IS DISTINCT FROM NEW.tier3_gross_margin
  ) THEN
    RETURN NEW;
  END IF;

  -- Until cutover, the deployed frontend remains the writer for legacy direct
  -- changes. Skip those here so its explicit history INSERT stays exactly-once.
  IF current_setting('crx.pricing_authorized', true) IS DISTINCT FROM 'phase1a' THEN
    RETURN NEW;
  END IF;

  IF v_actor IS NULL OR v_actor IS DISTINCT FROM auth.uid()
     OR v_source NOT IN ('pricing_worksheet', 'product_page', 'products_inline')
     OR NOT public.is_admin()
     OR v_change_set_id IS NULL THEN
    RAISE EXCEPTION 'PRODUCT_PRICING_HISTORY_CONTEXT_INVALID';
  END IF;

  INSERT INTO public.cost_history(
    product_id, changed_by,
    old_cost, new_cost,
    old_tier1_price, new_tier1_price,
    old_tier2_price, new_tier2_price,
    old_tier3_price, new_tier3_price,
    old_tier1_margin, new_tier1_margin,
    old_tier2_margin, new_tier2_margin,
    old_tier3_margin, new_tier3_margin,
    change_note, change_source, change_reason, change_set_id,
    old_pricing_version, new_pricing_version
  ) VALUES (
    NEW.id, v_actor,
    OLD.current_cost, NEW.current_cost,
    OLD.tier1_price, NEW.tier1_price,
    OLD.tier2_price, NEW.tier2_price,
    OLD.tier3_price, NEW.tier3_price,
    OLD.tier1_margin, NEW.tier1_margin,
    OLD.tier2_margin, NEW.tier2_margin,
    OLD.tier3_margin, NEW.tier3_margin,
    v_reason, v_source, v_reason, v_change_set_id,
    OLD.pricing_version, NEW.pricing_version
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."write_product_pricing_history"() OWNER TO "postgres";


