    "mime_type" "text" NOT NULL,
    "size_bytes" bigint NOT NULL,
    "uploaded_by" "uuid" NOT NULL,
    "source" "text" DEFAULT 'rep'::"text" NOT NULL,
    "effective_date" "date",
    "expiration_date" "date",
    "notes" "text",
