    CONSTRAINT "customer_documents_document_type_check" CHECK (("document_type" = ANY (ARRAY['license'::"text", 'permit'::"text", 'contract'::"text", 'map'::"text", 'invoice_copy'::"text", 'other'::"text"]))),
    CONSTRAINT "customer_documents_effective_expiration_check" CHECK ((("expiration_date" IS NULL) OR ("effective_date" IS NULL) OR ("expiration_date" >= "effective_date"))),
    CONSTRAINT "customer_documents_path_matches_customer_check" CHECK ((("split_part"("storage_path", '/'::"text", 1) = ("customer_id")::"text") AND ("split_part"("storage_path", '/'::"text", 2) <> ''::"text") AND ("storage_path" !~~ '%/%/%'::"text"))),
    CONSTRAINT "customer_documents_size_bytes_check" CHECK (("size_bytes" > 0)),
    CONSTRAINT "customer_documents_soft_delete_stamp_check" CHECK (((("deleted_at" IS NULL) AND ("deleted_by" IS NULL)) OR (("deleted_at" IS NOT NULL) AND ("deleted_by" IS NOT NULL)))),
    CONSTRAINT "customer_documents_source_check" CHECK (("source" = ANY (ARRAY['rep'::"text", 'ai_receptionist'::"text", 'system'::"text", 'web_store'::"text"])))
);


ALTER TABLE "public"."customer_documents" OWNER TO "postgres";


COMMENT ON TABLE "public"."customer_documents" IS 'Private customer document metadata; file bytes live in the customer-documents Storage bucket and removals are soft deletes.';



COMMENT ON COLUMN "public"."customer_documents"."id" IS 'Stable customer-document identifier.';



COMMENT ON COLUMN "public"."customer_documents"."customer_id" IS 'Customer that owns the document.';



COMMENT ON COLUMN "public"."customer_documents"."contact_id" IS 'Optional customer contact the document concerns.';



COMMENT ON COLUMN "public"."customer_documents"."document_type" IS 'Controlled business classification for the document.';



COMMENT ON COLUMN "public"."customer_documents"."storage_path" IS 'Immutable object path in the private customer-documents bucket.';



COMMENT ON COLUMN "public"."customer_documents"."filename" IS 'Original human-readable file name.';



COMMENT ON COLUMN "public"."customer_documents"."mime_type" IS 'Verified MIME type recorded at upload.';



COMMENT ON COLUMN "public"."customer_documents"."size_bytes" IS 'Positive object size in bytes recorded at upload.';



COMMENT ON COLUMN "public"."customer_documents"."uploaded_by" IS 'Authenticated profile that created the metadata record.';



COMMENT ON COLUMN "public"."customer_documents"."source" IS 'Intake channel that supplied the document.';



COMMENT ON COLUMN "public"."customer_documents"."effective_date" IS 'Optional date when the document becomes effective.';



COMMENT ON COLUMN "public"."customer_documents"."expiration_date" IS 'Optional date when the document expires.';



COMMENT ON COLUMN "public"."customer_documents"."notes" IS 'Optional user-maintained context for the document.';



COMMENT ON COLUMN "public"."customer_documents"."deleted_at" IS 'When the document was soft-deleted from the user-facing CRM.';



COMMENT ON COLUMN "public"."customer_documents"."deleted_by" IS 'Profile that performed the metadata soft-delete.';



COMMENT ON COLUMN "public"."customer_documents"."created_at" IS 'When the metadata record was created.';



COMMENT ON COLUMN "public"."customer_documents"."updated_at" IS 'When permitted metadata was last updated.';



COMMENT ON CONSTRAINT "customer_documents_document_type_check" ON "public"."customer_documents" IS 'Restricts document classification to the CRM document taxonomy.';



COMMENT ON CONSTRAINT "customer_documents_effective_expiration_check" ON "public"."customer_documents" IS 'An expiration date cannot precede an effective date.';



COMMENT ON CONSTRAINT "customer_documents_size_bytes_check" ON "public"."customer_documents" IS 'Rejects empty or negative-size document metadata.';



COMMENT ON CONSTRAINT "customer_documents_soft_delete_stamp_check" ON "public"."customer_documents" IS 'Soft-delete timestamp and actor must be present together.';



COMMENT ON CONSTRAINT "customer_documents_source_check" ON "public"."customer_documents" IS 'Restricts provenance to the shared CRM intake-channel taxonomy.';



CREATE TABLE IF NOT EXISTS "public"."customer_facts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_id" "uuid" NOT NULL,
    "category" "text" NOT NULL,
    "fact_key" "text" NOT NULL,
    "value_text" "text",
    "value_json" "jsonb",
    "confidence" numeric(4,3),
    "status" "text" DEFAULT 'pending_review'::"text" NOT NULL,
    "source" "text" DEFAULT 'rep'::"text" NOT NULL,
    "source_interaction_id" "uuid",
    "entered_by" "uuid",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_note" "text",
    "expires_at" timestamp with time zone,
    "superseded_at" timestamp with time zone,
    "superseded_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "customer_facts_ai_source_interaction_check" CHECK ((("source" <> 'ai_receptionist'::"text") OR ("source_interaction_id" IS NOT NULL))),
    CONSTRAINT "customer_facts_category_check" CHECK (("category" = ANY (ARRAY['product_preference'::"text", 'constraint'::"text", 'operating_preference'::"text", 'agronomy'::"text", 'relationship'::"text", 'communication'::"text"]))),
    CONSTRAINT "customer_facts_confidence_check" CHECK ((("confidence" IS NULL) OR (("confidence" >= (0)::numeric) AND ("confidence" <= (1)::numeric)))),
    CONSTRAINT "customer_facts_fact_key_check" CHECK ((("fact_key" = "lower"("btrim"("fact_key"))) AND ("fact_key" <> ''::"text"))),
    CONSTRAINT "customer_facts_review_stamp_check" CHECK (((("status" = 'pending_review'::"text") AND ("reviewed_by" IS NULL) AND ("reviewed_at" IS NULL)) OR (("status" = ANY (ARRAY['verified'::"text", 'rejected'::"text"])) AND ("reviewed_by" IS NOT NULL) AND ("reviewed_at" IS NOT NULL)))),
    CONSTRAINT "customer_facts_source_check" CHECK (("source" = ANY (ARRAY['rep'::"text", 'ai_receptionist'::"text", 'system'::"text", 'web_store'::"text"]))),
    CONSTRAINT "customer_facts_status_check" CHECK (("status" = ANY (ARRAY['pending_review'::"text", 'verified'::"text", 'rejected'::"text"]))),
    CONSTRAINT "customer_facts_value_check" CHECK (((("value_text" IS NULL) <> ("value_json" IS NULL)) AND (("value_text" IS NULL) OR ("btrim"("value_text") <> ''::"text")))),
    CONSTRAINT "customer_facts_value_json_check" CHECK ((("value_json" IS NULL) OR ("jsonb_typeof"("value_json") = ANY (ARRAY['object'::"text", 'array'::"text"]))))
);


ALTER TABLE "public"."customer_facts" OWNER TO "postgres";


COMMENT ON TABLE "public"."customer_facts" IS 'Reviewable customer knowledge with immutable intake provenance and explicit supersession.';



COMMENT ON COLUMN "public"."customer_facts"."id" IS 'Stable customer-fact identifier.';



COMMENT ON COLUMN "public"."customer_facts"."customer_id" IS 'Customer the fact describes.';



COMMENT ON COLUMN "public"."customer_facts"."category" IS 'Controlled fact category.';



COMMENT ON COLUMN "public"."customer_facts"."fact_key" IS 'Lowercase, trimmed key within the category.';



COMMENT ON COLUMN "public"."customer_facts"."value_text" IS 'Nonblank scalar fact value when structured JSON is not needed.';



COMMENT ON COLUMN "public"."customer_facts"."value_json" IS 'Structured object or array fact value when text is not suitable.';



COMMENT ON COLUMN "public"."customer_facts"."confidence" IS 'Optional confidence from zero through one.';



COMMENT ON COLUMN "public"."customer_facts"."status" IS 'Pending review, verified, or rejected lifecycle state.';



COMMENT ON COLUMN "public"."customer_facts"."source" IS 'Intake channel that originally supplied the fact.';



COMMENT ON COLUMN "public"."customer_facts"."source_interaction_id" IS 'Optional same-customer interaction that supplied the fact.';



COMMENT ON COLUMN "public"."customer_facts"."entered_by" IS 'User who entered the fact.';



COMMENT ON COLUMN "public"."customer_facts"."reviewed_by" IS 'User who verified or rejected the fact.';



COMMENT ON COLUMN "public"."customer_facts"."reviewed_at" IS 'When the fact was verified or rejected.';



COMMENT ON COLUMN "public"."customer_facts"."review_note" IS 'Optional reviewer explanation.';



COMMENT ON COLUMN "public"."customer_facts"."expires_at" IS 'Optional time after which the fact should be reconsidered.';



COMMENT ON COLUMN "public"."customer_facts"."superseded_at" IS 'When a newer verified fact replaced this fact.';



COMMENT ON COLUMN "public"."customer_facts"."superseded_by" IS 'Replacement fact created by the supersession RPC.';



COMMENT ON COLUMN "public"."customer_facts"."created_at" IS 'When this fact was first recorded.';



COMMENT ON COLUMN "public"."customer_facts"."updated_at" IS 'When mutable review or supersession fields last changed.';



