CREATE TABLE IF NOT EXISTS "public"."invoices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "invoice_number" "text" DEFAULT "public"."next_invoice_number"('field_application'::"text") NOT NULL,
    "order_id" "uuid",
    "blend_ticket_id" "uuid",
    "customer_id" "uuid" NOT NULL,
    "invoice_type" "text" DEFAULT 'chemical_sale'::"text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "season" integer DEFAULT "public"."current_season"() NOT NULL,
    "salesman_id" "uuid",
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "total_amount_cents" bigint DEFAULT 0 NOT NULL,
    "paid_amount_cents" bigint DEFAULT 0 NOT NULL,
    "prepay_applied_cents" bigint DEFAULT 0 NOT NULL,
    "posted_by" "uuid",
    "posted_at" timestamp with time zone,
    "voided_by" "uuid",
    "voided_at" timestamp with time zone,
    "void_reason" "text",
    "invoice_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "due_date" "date",
    "purchase_order_ref" "text",
    "header_notes" "text",
    "footer_notes" "text",
    "parent_invoice_id" "uuid",
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "crop_type" "text",
    "field_names" "text"[],
    "total_acres" numeric(12,2),
    "applicator_name" "text",
    "vehicle_name" "text",
    "application_date" "date",
    "job_id" "uuid",
    "total_cost_cents" bigint DEFAULT 0,
    "is_quick_delivery" boolean DEFAULT false,
    "write_off_cents" bigint DEFAULT 0 NOT NULL,
    "invoice_group_id" "uuid",
    "application_service_id" "uuid",
    "delivery_id" "uuid",
    "wind_direction" "text",
    "temperature_text" "text",
    "pricing_pending" boolean DEFAULT false NOT NULL,
    "payment_terms" "text",
    "internal_notes" "text",
    "discount_earned_cents" bigint DEFAULT 0 NOT NULL,
    "discount_date" "date",
    "start_temp_f" numeric,
    "start_wind_mph" numeric,
    "start_wind_direction" "text",
    "start_humidity_pct" numeric,
    "start_weather_time" time without time zone,
    "start_weather_source" "text",
    "end_temp_f" numeric,
    "end_wind_mph" numeric,
    "end_wind_direction" "text",
    "end_humidity_pct" numeric,
    "end_weather_time" time without time zone,
    "end_weather_source" "text",
    "weather_manual_override" boolean DEFAULT false,
    "diluent_rate_gpa" numeric,
    "credit_applied_cents" bigint DEFAULT 0 NOT NULL,
    "balance_cents" bigint GENERATED ALWAYS AS ((((("total_amount_cents" - "paid_amount_cents") - "prepay_applied_cents") - "write_off_cents") +
CASE
    WHEN ("invoice_type" = 'credit_memo'::"text") THEN "credit_applied_cents"
    ELSE (- "credit_applied_cents")
END)) STORED,
    CONSTRAINT "invoices_balance_non_negative" CHECK ((("invoice_type" = 'credit_memo'::"text") OR ("balance_cents" >= 0))),
    CONSTRAINT "invoices_credit_applied_non_negative" CHECK (("credit_applied_cents" >= 0)),
    CONSTRAINT "invoices_credit_memo_balance_nonpositive" CHECK ((("invoice_type" <> 'credit_memo'::"text") OR ("balance_cents" <= 0))),
    CONSTRAINT "invoices_credit_memo_total_nonpositive" CHECK ((("invoice_type" <> 'credit_memo'::"text") OR ("total_amount_cents" <= 0))),
    CONSTRAINT "invoices_discount_earned_nonneg" CHECK (("discount_earned_cents" >= 0)),
    CONSTRAINT "invoices_invoice_type_check" CHECK (("invoice_type" = ANY (ARRAY['chemical_sale'::"text", 'field_application'::"text", 'misc_charge'::"text", 'credit_memo'::"text"]))),
    CONSTRAINT "invoices_paid_non_negative" CHECK (("paid_amount_cents" >= 0)),
    CONSTRAINT "invoices_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'unposted'::"text", 'posted'::"text", 'paid'::"text", 'overdue'::"text", 'voided'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "invoices_total_non_negative" CHECK ((("invoice_type" = 'credit_memo'::"text") OR ("total_amount_cents" >= 0)))
);


ALTER TABLE "public"."invoices" OWNER TO "postgres";


COMMENT ON COLUMN "public"."invoices"."applicator_name" IS 'Name of the person who applied the chemicals. Wave B.1 / audit finding P2-1 wired the read+write path for this previously-unused column.';



COMMENT ON COLUMN "public"."invoices"."application_service_id" IS 'Application service (Hagie Y-Drop, airplane, etc.) used for this field application. Drives per-acre fee calculation. NULL when no service fee applies.';



COMMENT ON COLUMN "public"."invoices"."delivery_id" IS 'For invoices auto-created by complete_delivery, points to the source delivery. NULL for invoices originating from orders, blend tickets, jobs, or returns.';



COMMENT ON COLUMN "public"."invoices"."wind_direction" IS 'Field-app invoice-level applied-info wind direction (free-form text — e.g. "NW @ 5mph"). Per-location wind in field_app_locations.wind_direction is preferred when set; this column is the fallback default for the day. Wave B.1 / audit finding P2-1.';



COMMENT ON COLUMN "public"."invoices"."temperature_text" IS 'Field-app invoice-level applied-info temperature, free-form text (e.g. "72F", "high 70s"). Renamed from "temperature" in Wave B audit B-3 to disambiguate from the numeric temperature columns on blend_tickets, field_app_locations, and job_applied_info.';



COMMENT ON COLUMN "public"."invoices"."payment_terms" IS 'ChemMan "Terms" — free-text payment terms printed on the invoice. Distinct from customers.payment_terms (invoice-level override).';



COMMENT ON COLUMN "public"."invoices"."internal_notes" IS 'Internal job/invoice memo. NOT printed on the customer copy (field-app parity #33).';



COMMENT ON COLUMN "public"."invoices"."discount_earned_cents" IS 'Early-pay "Discount Earned" amount in cents (owner-entered; default 0/off). Informational/displayed — does NOT reduce the GENERATED balance_cents; real reduction flows through payments/write-off. Never a formula.';



COMMENT ON COLUMN "public"."invoices"."discount_date" IS 'Early-pay discount date for the Discount Earned amount (optional).';



COMMENT ON COLUMN "public"."invoices"."start_weather_source" IS 'Provenance of the START weather set: ''auto'' (fetched from Open-Meteo) or ''manual'' (hand-entered/edited). NULL when no START weather captured.';



COMMENT ON COLUMN "public"."invoices"."end_weather_source" IS 'Provenance of the END weather set: ''auto'' or ''manual''. NULL when no END weather captured.';



COMMENT ON COLUMN "public"."invoices"."weather_manual_override" IS 'TRUE when the user hand-edited any auto-filled weather value (compliance audit flag). Weather is modeled, not measured.';



COMMENT ON COLUMN "public"."invoices"."diluent_rate_gpa" IS 'Diluent / carrier-water rate in gallons per acre for this field-application invoice (mirrors jobs.carrier_rate_gpa). NULL = not recorded. A QUANTITY, never money/cents. The total diluent (rate x applied acres) is computed for display/PDF, not stored, because invoices.total_acres is not reliably written on save.';



COMMENT ON COLUMN "public"."invoices"."credit_applied_cents" IS 'Non-negative credit-memo application lever. On a credit_memo it is the total applied out (raises the negative balance toward 0); on a real invoice it is the total credit received (lowers the balance). Written ONLY by apply_credit_memo_to_invoice / reverse_credit_memo_application. Reconciles to SUM of unreversed credit_memo_applications.';



