CREATE TABLE IF NOT EXISTS "public"."job_applied_records" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_id" "uuid" NOT NULL,
    "applicator_id" "uuid",
    "vehicle_id" "uuid",
    "application_date" "date" NOT NULL,
    "applied_acres" numeric,
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "start_weather_time" time without time zone,
    "start_temp_f" numeric,
    "start_wind_direction" "text",
    "start_wind_mph" numeric,
    "start_humidity_pct" numeric,
    "start_weather_source" "text",
    "end_weather_time" time without time zone,
    "end_temp_f" numeric,
    "end_wind_direction" "text",
    "end_wind_mph" numeric,
    "end_humidity_pct" numeric,
    "end_weather_source" "text",
    "beginning_tach" numeric,
    "end_tach" numeric,
    "net_tach" numeric GENERATED ALWAYS AS (
CASE
    WHEN (("beginning_tach" IS NULL) OR ("end_tach" IS NULL)) THEN NULL::numeric
    ELSE GREATEST(("end_tach" - "beginning_tach"), (0)::numeric)
END) STORED,
    "idempotency_key" "text",
    "idempotency_request_hash" "text",
    CONSTRAINT "job_applied_records_applied_acres_check" CHECK ((("applied_acres" IS NULL) OR ("applied_acres" >= (0)::numeric))),
    CONSTRAINT "job_applied_records_beginning_tach_check" CHECK ((("beginning_tach" IS NULL) OR ("beginning_tach" >= (0)::numeric))),
    CONSTRAINT "job_applied_records_end_humidity_pct_check" CHECK ((("end_humidity_pct" IS NULL) OR (("end_humidity_pct" >= (0)::numeric) AND ("end_humidity_pct" <= (100)::numeric)))),
    CONSTRAINT "job_applied_records_end_tach_check" CHECK ((("end_tach" IS NULL) OR ("end_tach" >= (0)::numeric))),
    CONSTRAINT "job_applied_records_end_weather_source_check" CHECK ((("end_weather_source" IS NULL) OR ("end_weather_source" = ANY (ARRAY['auto'::"text", 'manual'::"text"])))),
    CONSTRAINT "job_applied_records_end_wind_mph_check" CHECK ((("end_wind_mph" IS NULL) OR ("end_wind_mph" >= (0)::numeric))),
    CONSTRAINT "job_applied_records_start_humidity_pct_check" CHECK ((("start_humidity_pct" IS NULL) OR (("start_humidity_pct" >= (0)::numeric) AND ("start_humidity_pct" <= (100)::numeric)))),
    CONSTRAINT "job_applied_records_start_weather_source_check" CHECK ((("start_weather_source" IS NULL) OR ("start_weather_source" = ANY (ARRAY['auto'::"text", 'manual'::"text"])))),
    CONSTRAINT "job_applied_records_start_wind_mph_check" CHECK ((("start_wind_mph" IS NULL) OR ("start_wind_mph" >= (0)::numeric))),
    CONSTRAINT "job_applied_records_tach_end_ge_begin_check" CHECK ((("beginning_tach" IS NULL) OR ("end_tach" IS NULL) OR ("end_tach" >= "beginning_tach")))
);


ALTER TABLE "public"."job_applied_records" OWNER TO "postgres";


COMMENT ON COLUMN "public"."job_applied_records"."start_weather_time" IS 'Field-app #19: clock time (local) of the START weather reading; date is the entry application_date.';



COMMENT ON COLUMN "public"."job_applied_records"."start_weather_source" IS 'Field-app #19: ''auto'' (Open-Meteo pull) or ''manual'' (hand-entered/edited).';



COMMENT ON COLUMN "public"."job_applied_records"."end_weather_time" IS 'Field-app #19: clock time (local) of the END weather reading. Total Time = end - start.';



COMMENT ON COLUMN "public"."job_applied_records"."end_weather_source" IS 'Field-app #19: ''auto'' (Open-Meteo pull) or ''manual'' (hand-entered/edited).';



COMMENT ON COLUMN "public"."job_applied_records"."beginning_tach" IS 'Field-app #20: engine-hour meter (tach) reading at the START of the pass. Nullable (optional).';



COMMENT ON COLUMN "public"."job_applied_records"."end_tach" IS 'Field-app #20: engine-hour meter (tach) reading at the END of the pass. Nullable; must be >= beginning_tach when both present.';



COMMENT ON COLUMN "public"."job_applied_records"."net_tach" IS 'Field-app #20: GENERATED engine hours used = GREATEST(end_tach - beginning_tach, 0); NULL when either reading is missing. Never written directly.';



COMMENT ON COLUMN "public"."job_applied_records"."idempotency_key" IS 'Insert-once dedup token for the CREATE path of save_job_applied_record. Set only on a new record; a retried create replays the same key and the partial UNIQUE index collapses it to the first row (no duplicate applied-record / no double-counted applied_acres). NULL on legacy/key-less rows and never set on edit.';



COMMENT ON COLUMN "public"."job_applied_records"."idempotency_request_hash" IS 'md5 fingerprint of the create request (p_record||p_fields||p_crew, canonical jsonb text) stamped alongside idempotency_key on a keyed CREATE. On a retried create the replay path compares this to the retry''s fingerprint: identical => replay the first row (dedup); different => RAISE APPLIED_RECORD_ALREADY_SAVED_DIFFERENT so a corrected retry surfaces a conflict instead of silently discarding the correction. NULL on edit / key-less / legacy.';



