    CONSTRAINT "jobs_loader_tank_capacity_pos" CHECK ((("loader_tank_capacity" IS NULL) OR ("loader_tank_capacity" > (0)::numeric))),
    CONSTRAINT "jobs_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
