CREATE TABLE IF NOT EXISTS "public"."offline_action_receipts" (
    "client_action_id" "uuid" NOT NULL,
    "actor_id" "uuid" NOT NULL,
    "operation" "text" NOT NULL,
    "entity_id" "uuid" NOT NULL,
    "schema_version" integer NOT NULL,
    "client_created_at" timestamp with time zone NOT NULL,
    "entity_snapshot_at" timestamp with time zone,
    "request_payload" "jsonb" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "status" "text" DEFAULT 'received'::"text" NOT NULL,
    "result" "jsonb",
    "failure_code" "text",
    "failure_summary" "text",
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "last_attempt_at" timestamp with time zone,
    "succeeded_at" timestamp with time zone,
    "needs_review_at" timestamp with time zone,
    "received_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "review_resolution" "text",
    "review_note" "text",
    "resolved_at" timestamp with time zone,
    "resolved_by" "uuid",
    CONSTRAINT "offline_action_receipts_attempt_count_check" CHECK ((("attempt_count" >= 0) AND ("attempt_count" <= 50))),
    CONSTRAINT "offline_action_receipts_failure_code_check" CHECK ((("failure_code" IS NULL) OR ("failure_code" = ANY (ARRAY['ACTOR_MISMATCH'::"text", 'IDEMPOTENCY_KEY_REUSE'::"text", 'LEGACY_OUTCOME_UNKNOWN'::"text", 'NOT_AUTHORIZED'::"text", 'PAYLOAD_INVALID'::"text", 'PAYLOAD_TOO_LARGE'::"text", 'RESULT_INVALID'::"text", 'RETRY_LIMIT'::"text", 'TARGET_NOT_FOUND'::"text", 'TARGET_STATE_CONFLICT'::"text", 'UNEXPECTED_SERVER_ERROR'::"text", 'UNSUPPORTED_OPERATION'::"text", 'UNSUPPORTED_SCHEMA_VERSION'::"text"])))),
    CONSTRAINT "offline_action_receipts_idempotency_key_check" CHECK ((("btrim"("idempotency_key") <> ''::"text") AND ("length"("idempotency_key") <= 200))),
    CONSTRAINT "offline_action_receipts_operation_check" CHECK (("operation" = ANY (ARRAY['complete_delivery'::"text", 'complete_job'::"text"]))),
    CONSTRAINT "offline_action_receipts_payload_shape_check" CHECK (("jsonb_typeof"("request_payload") = 'object'::"text")),
    CONSTRAINT "offline_action_receipts_payload_size_check" CHECK (("pg_column_size"("request_payload") <= 65536)),
    CONSTRAINT "offline_action_receipts_review_resolution_check" CHECK ((("review_resolution" IS NULL) OR ("review_resolution" = ANY (ARRAY['already_completed'::"text", 'abandoned'::"text"])))),
    CONSTRAINT "offline_action_receipts_review_resolution_shape_check" CHECK (((("review_resolution" IS NULL) AND ("review_note" IS NULL) AND ("resolved_at" IS NULL) AND ("resolved_by" IS NULL)) OR (("status" = 'needs_review'::"text") AND ("review_resolution" IS NOT NULL) AND ("review_note" IS NOT NULL) AND (("length"("btrim"("review_note")) >= 10) AND ("length"("btrim"("review_note")) <= 1000)) AND ("resolved_at" IS NOT NULL) AND ("resolved_by" IS NOT NULL)))),
    CONSTRAINT "offline_action_receipts_schema_version_check" CHECK (("schema_version" = 1)),
    CONSTRAINT "offline_action_receipts_state_shape_check" CHECK (((("status" = 'received'::"text") AND ("result" IS NULL) AND ("failure_code" IS NULL) AND ("failure_summary" IS NULL) AND ("succeeded_at" IS NULL) AND ("needs_review_at" IS NULL)) OR (("status" = 'succeeded'::"text") AND ("result" IS NOT NULL) AND ("failure_code" IS NULL) AND ("failure_summary" IS NULL) AND ("succeeded_at" IS NOT NULL) AND ("needs_review_at" IS NULL)) OR (("status" = 'needs_review'::"text") AND ("result" IS NULL) AND ("failure_code" IS NOT NULL) AND ("failure_summary" IS NOT NULL) AND ("succeeded_at" IS NULL) AND ("needs_review_at" IS NOT NULL)))),
    CONSTRAINT "offline_action_receipts_status_check" CHECK (("status" = ANY (ARRAY['received'::"text", 'succeeded'::"text", 'needs_review'::"text"])))
);


ALTER TABLE "public"."offline_action_receipts" OWNER TO "postgres";


COMMENT ON TABLE "public"."offline_action_receipts" IS 'Permanent acknowledgement for approved offline complete_delivery/complete_job actions. RPC-only writes; unresolved rows are never auto-deleted.';



COMMENT ON COLUMN "public"."offline_action_receipts"."review_resolution" IS 'Audited office outcome: already_completed or abandoned. Never means the receipt processor succeeded.';



COMMENT ON COLUMN "public"."offline_action_receipts"."review_note" IS 'Required office explanation for a manual resolution; retained with the permanent receipt.';



COMMENT ON COLUMN "public"."offline_action_receipts"."resolved_at" IS 'Time an office user resolved a needs_review item without rerunning its business mutation.';



COMMENT ON COLUMN "public"."offline_action_receipts"."resolved_by" IS 'Active admin or sales_rep who recorded the non-destructive office resolution.';



