    CONSTRAINT "product_supplier_links_link_status_check" CHECK (("link_status" = ANY (ARRAY['pending'::"text", 'confirmed'::"text", 'rejected'::"text"]))),
    CONSTRAINT "product_supplier_links_match_confidence_check" CHECK ((("match_confidence" IS NULL) OR (("match_confidence" >= (0)::numeric) AND ("match_confidence" <= (1)::numeric)))),
    CONSTRAINT "product_supplier_links_supplier_product_name_check" CHECK (("btrim"("supplier_product_name") <> ''::"text")),
    CONSTRAINT "product_supplier_links_supplier_sku_nonblank" CHECK ((("supplier_sku" IS NULL) OR ("btrim"("supplier_sku") <> ''::"text")))
);


