    "idempotency_key" "text" NOT NULL,
    "row_count" integer DEFAULT 0 NOT NULL,
    "eligible_row_count" integer DEFAULT 0 NOT NULL,
    "approved_observation_count" integer DEFAULT 0 NOT NULL,
    "created_by" "uuid" NOT NULL,
    "approved_by" "uuid",
