    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "vendor_id" "uuid",
    "proposed_vendor_id" "uuid",
    "alias_raw" "text" NOT NULL,
    "alias_normalized" "text" GENERATED ALWAYS AS ("public"."normalize_vendor_alias"("alias_raw")) STORED,
    "alias_display" "text" NOT NULL,
    "source" "text" NOT NULL,
    "review_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "review_note" "text",
    "created_by" "uuid",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "vendor_aliases_alias_display_check" CHECK (("btrim"("alias_display") <> ''::"text")),
    CONSTRAINT "vendor_aliases_alias_raw_check" CHECK (("btrim"("alias_raw") <> ''::"text")),
    CONSTRAINT "vendor_aliases_review_shape" CHECK (((("review_status" = 'pending'::"text") AND ("vendor_id" IS NULL) AND ("reviewed_at" IS NULL)) OR (("review_status" = 'approved'::"text") AND ("vendor_id" IS NOT NULL) AND ("reviewed_at" IS NOT NULL)) OR (("review_status" = 'rejected'::"text") AND ("vendor_id" IS NULL) AND ("reviewed_at" IS NOT NULL)))),
    CONSTRAINT "vendor_aliases_review_status_check" CHECK (("review_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "vendor_aliases_source_check" CHECK (("source" = ANY (ARRAY['legacy_product'::"text", 'legacy_po'::"text", 'import'::"text", 'manual'::"text"])))
);


ALTER TABLE "public"."vendor_aliases" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."vendor_bills" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "vendor_id" "uuid" NOT NULL,
    "purchase_order_id" "uuid",
    "bill_number" "text" NOT NULL,
    "bill_date" "date" NOT NULL,
    "due_date" "date" NOT NULL,
    "payment_terms" "text",
    "subtotal_cents" bigint NOT NULL,
    "adjustment_cents" bigint DEFAULT 0,
    "total_cents" bigint NOT NULL,
    "paid_cents" bigint DEFAULT 0,
    "status" "text" DEFAULT 'unpaid'::"text" NOT NULL,
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "deleted_at" timestamp with time zone,
    "voided_at" timestamp with time zone,
    "voided_by" "uuid",
    "void_reason" "text",
    "balance_cents" bigint GENERATED ALWAYS AS (("total_cents" - COALESCE("paid_cents", (0)::bigint))) STORED,
    CONSTRAINT "vendor_bills_status_check" CHECK (("status" = ANY (ARRAY['unpaid'::"text", 'partially_paid'::"text", 'paid'::"text", 'voided'::"text"]))),
    CONSTRAINT "vendor_bills_total_check" CHECK (("total_cents" = ("subtotal_cents" + COALESCE("adjustment_cents", (0)::bigint))))
);


ALTER TABLE "public"."vendor_bills" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."vendor_payments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "vendor_bill_id" "uuid" NOT NULL,
    "payment_date" "date" NOT NULL,
    "amount_cents" bigint NOT NULL,
    "payment_method" "text",
    "reference_number" "text",
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "voided_at" timestamp with time zone,
    "voided_by" "uuid",
    "void_reason" "text",
    CONSTRAINT "vendor_payments_payment_method_check" CHECK ((("payment_method" IS NULL) OR ("payment_method" = ANY (ARRAY['check'::"text", 'ach'::"text", 'cash'::"text", 'credit_card'::"text", 'wire'::"text", 'other'::"text"]))))
);


ALTER TABLE "public"."vendor_payments" OWNER TO "postgres";


