);


ALTER TABLE "public"."vendors" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."view_unmigrated_products" WITH ("security_invoker"='true') AS
 SELECT "id",
    "product_name",
    "sku",
    "category",
    "vendor",
    "container_size",
    "unit_size",
    "rate_unit",
    "product_form",
    "inventory_unit",
    "container_unit",
    "container_type"
   FROM "public"."products"
  WHERE (("product_form" IS NULL) OR ("inventory_unit" IS NULL))
  ORDER BY "product_name";


ALTER VIEW "public"."view_unmigrated_products" OWNER TO "postgres";


