CREATE TABLE IF NOT EXISTS "public"."watchdog_flags" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "flag_type" "text" NOT NULL,
    "severity" "text" DEFAULT 'warning'::"text" NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_id" "uuid" NOT NULL,
    "job_id" "uuid",
    "invoice_id" "uuid",
    "product_id" "uuid",
    "field_id" "uuid",
    "customer_id" "uuid",
    "message" "text" NOT NULL,
    "detail" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "natural_key" "text",
    CONSTRAINT "watchdog_flags_entity_type_check" CHECK (("entity_type" = ANY (ARRAY['job'::"text", 'invoice'::"text", 'job_chemical'::"text"]))),
    CONSTRAINT "watchdog_flags_flag_type_check" CHECK (("flag_type" = ANY (ARRAY['acre_divergence'::"text", 'rate_over_label'::"text", 'double_bill'::"text", 'rei_not_cleared'::"text"]))),
    CONSTRAINT "watchdog_flags_severity_check" CHECK (("severity" = ANY (ARRAY['warning'::"text", 'info'::"text"])))
);


ALTER TABLE "public"."watchdog_flags" OWNER TO "postgres";


COMMENT ON TABLE "public"."watchdog_flags" IS 'Advisory watchdog flags for suspicious job/invoice records. Never blocks — advisory only.';



